#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef long double ld;
typedef unsigned long long ull;

const ld EPS = 1e-7;
const ld PI = acos(-1.0);

struct Point{
	ld x, y;
	int i;
	Point(ld ix = 0.0, ld iy = 0.0, int ii = -1){
		x = ix; y = iy; i = ii;
	}
	Point operator-(Point a){
		return Point(x - a.x, y - a.y);
	}
	Point operator+(Point a){
		return Point(x + a.x, y + a.y);
	}
};

inline ld getAngle(Point a){
	ld nx = a.x;
	ld ny = a.y;
	if(abs(ny) < EPS){
		if(nx >= 0)return 0.0;
		return PI;
	}
	ld theta = PI/2 - atan(abs(nx/ny));
	if(nx < 0)return PI - theta;
	return theta;
}

inline ld cross(Point n, Point p, Point c){
	Point pc = p - c;
	Point pn = p - n;
	return pc.x*pn.y - pc.y*pn.x;
}

inline ld dist(Point a){
	return sqrt(a.x*a.x + a.y*a.y);
}

ld findAngle(Point a, Point b){
	return acos((a.x*b.x + a.y*b.y)/dist(a)/dist(b));
}

int main(){
	ios::sync_with_stdio(false);
	cin.tie(NULL);
	cout<<setprecision(32);

	int n; cin>>n;
	vector<Point> v(n);
	for(int i = 0; i < n; i++){
		cin>>v[i].x>>v[i].y;
		v[i].i = i;
		if(v[i].y < v[0].y || (v[i].y == v[0].y && v[i].x < v[0].x)){
			swap(v[i], v[0]);
		}
	}
	if(n == 1){
		cout<<1.0<<'\n';
		exit(0);
	}
	if(n == 2){
		cout<<0.5<<'\n';
		cout<<0.5<<'\n';
		exit(0);
	}
	sort(v.begin() + 1, v.end(), [&](Point &a, Point &b){
		return getAngle(a - v[0]) < getAngle(b - v[0]);
	});
	vector<Point> hull;
	for(int i = 0; i < n; i++){
		while(hull.size() >= 2 && cross(hull[hull.size() - 2], hull.back(), v[i]) <= 0){
			hull.pop_back();
		}
		hull.push_back(v[i]);
	}
	vector<ld> ans(n);
	if(hull.size() == 2){
		ans[hull[0].i] = 0.5;
		ans[hull[1].i] = 0.5;
	}else{
		int sz = hull.size();
		for(int i = 0; i < sz; i++){
			ld theta = findAngle(hull[(i + sz - 1)%sz] - hull[i], hull[(i + 1)%sz] - hull[i]);
			// ld theta = cross(hull[(i + sz - 1)%sz], hull[i], hull[(i + 1)%sz]);
			// cout<<hull[i].i<<" "<<theta<<endl;
			// theta /= dist(hull[(i + sz - 1)%sz] - hull[i]);
			// theta /= dist(hull[i] - hull[(i + 1)%sz]);
			// theta = asin(theta);
			ans[hull[i].i] = (PI - theta)/(2*PI);
		}
	}
	for(auto x : ans){
		cout<<x<<'\n';
	}


	return 0;
}

