#define double long double
const int N = 105;
const double eps = 1e-10, PI = acos(-1);
int n, top;
double ans[N];
struct point {
    int id;
    double x, y;
    point(){}
    point(double _x, double _y): id(0), x(_x), y(_y){}
    point operator - (const point &b) const{
        return point(x - b.x, y - b.y);
    }
    point operator + (const point &b) const{
        return point(x + b.x, y + b.y);
    }
    friend double cross(const point &a, const point &b){
        return a.x * b.y - a.y * b.x;
    }
    friend double dot(const point &a, const point &b){
        return a.x * b.x + a.y * b.y;
    }
    double norm(){
        return sqrt(x * x + y * y);
    }
    point rot(){
        return point(-y, x);
    }
} p[N], stk[N];

bool cmp(const point &a, const point &b){
    double det = cross(a - p[1], b - p[1]);
    if(abs(det) < eps) return (a - p[1]).norm() < (b - p[1]).norm();
    return det > 0;
}
void graham(){
    int root = 1;
    for(int i = 2; i <= n; i++)
        if(p[i].x < p[root].x || (fabs(p[i].x - p[root].x) < eps && p[i].y < p[root].y))
            root = i;
    if(root != 1) swap(p[1], p[root]);
    sort(p + 1, p + n + 1, cmp);
    stk[++top] = p[1];
    for(int i = 2; i <= n; i++){
        while(top >= 2 && cross(p[i] - stk[top], stk[top] - stk[top - 1]) >= 0) top--;
        stk[++top] = p[i];
    }
    stk[top + 1] = stk[1], stk[0] = stk[top];
}
void calc(){
    for(int i = 1; i <= top; i++){
        point a = (stk[i - 1] - stk[i]).rot(), b = (stk[i] - stk[i + 1]).rot();
        ans[stk[i].id] = acos(dot(a, b) / a.norm() / b.norm()) / 2 / PI;
    }
}

int main(){

    read(n);
    for(int i = 1; i <= n; i++)
        p[i].id = i, read(p[i].x), read(p[i].y);
    graham();
    calc();
    for(int i = 1; i <= n; i++)
        printf("%.10Lf\n", ans[i]);

    return 0;
}

