	}

	if (N == 2) {
		cout << 0.5 << endl;
		cout << 0.5 << endl;
		return 0;
	}

	Vec< Point > convex = convex_hull(vp);
	int m = convex.size();

	Vec< int > convex_id(N, -1);
	for_(i,0,N) {
		const Point& pi = vp[i];
		for_(j,0,m) {
			const Point& pc = convex[j];
			if (pc.x == pi.x && pc.y == pi.y) {
				convex_id[i] = j;
				break;
			}
		}
	}

	for_(i,0,N) {
		//cerr << convex_id[i] << endl;
		if (convex_id[i] == -1) puts("0");
		else {
			int id = convex_id[i];
			double si = PI - acos(calcCos(convex[id], convex[(id+1)%m], convex[(id-1+m)%m]));
			cout << setprecision(9) << setiosflags(ios::fixed) << si / (2. * PI) << endl;
		}
	}
}
