	return ((ld)((ld)b.x - a.x) * (ld)(c.y - a.y) - (ld)(c.x - a.x) * (ld)(b.y - a.y));
}
vector<H> solve(int s, int t) {
	vector<H>ans;
	if (t - s < 3) {
		for (int i = s; i < t; i++) ans.push_back(a[i]);
		return ans;
	}
	int mid = (s + t) / 2;
	vector<H>u = solve(s, mid), v = solve(mid, t);
	//時計回りに並べられた頂点たち
	int p = 0, q = 0; H r = H{ -Inf,Inf };
	for (int i = 0; i < u.size(); i++) {
		if (u[i].x > r.x || (u[i].x == r.x && u[i].y > r.y)) p = i, r = u[i];
	}
	r = H{ Inf,Inf };
	for (int i = 0; i < v.size(); i++) {
		if (v[i].x < r.x || (v[i].x == r.x && v[i].y > r.y)) q = i, r = v[i];
	}
	int c = p, d = q;
	int U = u.size(), V = v.size();
	while (1) {
		if (sgarea(u[p], v[q], v[(q + 1) % V]) > 0) {
			(++q) %= V;
			continue;
		}
		if (sgarea(v[q], u[p], u[(p - 1 + U) % U]) < 0) {
			(p += U - 1) %= U;
			continue;
		}
		break;
	}
	c = p, d = q;
	r = H{ -Inf,-Inf };
	for (int i = 0; i < u.size(); i++) {
		if (u[i].x > r.x || (u[i].x == r.x && u[i].y < r.y)) p = i, r = u[i];
	}
	r = H{ Inf,-Inf };
	for (int i = 0; i < v.size(); i++) {
		if (v[i].x < r.x || (v[i].x == r.x && v[i].y < r.y)) q = i, r = v[i];
	}
	while (1) {
		if (sgarea(u[p], v[q], v[(q - 1 + V) % V]) < 0) {
			(q += V - 1) %= V;
			continue;
		}
		if (sgarea(v[q], u[p], u[(p + 1) % U]) > 0) {
			(++p) %= U;
			continue;
		}
		break;
	}
	for (int i = d; i != q; (++i) %= V) {
		ans.push_back(v[i]);
	}
	ans.push_back(v[q]);
	for (int i = p; i != c; (++i) %= U) {
		ans.push_back(u[i]);
	}
	ans.push_back(u[c]);
	return ans;
}
