        return dp[l][r][k];
    }

    int& res = dp[l][r][k];
    res = 0;

    if (l == r) {
        return res = 1;
    } else if (s[l] == s[r]) {
        chmax(res, 2 + f(l + 1, r - 1, k));
    } else if (k) {
