int check(vertex& v1, vertex& v2, vertex& v3) {
    Pll vec1(v2.x-v1.x, v2.y-v1.y);
    Pll vec2(v3.x-v1.x, v3.y-v1.y);

    ll rot = vec1.fi*vec2.sc - vec1.sc*vec2.fi;

    if (rot > 0) {
        return 1;
    } else if (rot < 0) {
        return -1;
    } else {
        return 0;
    }
}

vector<int> conv(vector<vertex> vertexs) {
    vector<int> res;
    vector<int> tmp;
    for (int i = 0; i < 2; ++i) res.push_back(i);
    for (int i = 2; i < len(vertexs); ++i) {
        for (int j = len(res)-1; j > 0; --j) {
            if (check(vertexs[i], vertexs[res[j]], vertexs[res[j-1]]) < 0) {
                for (int k = 0; k <= j; ++k) {
                    tmp.push_back(res[k]);
                }
                tmp.push_back(i);
                res = tmp;
                tmp.clear();
                break;
            }
            if (j == 1) {
                res.clear();
                res.push_back(0);
                res.push_back(i);
            }
        }
    }


    vector<int> res2;
    for (int i = len(vertexs)-1; i > len(vertexs)-3; --i) res2.push_back(i);
    for (int i = len(vertexs)-3; i >= 0; --i) {
        for (int j = len(res2)-1; j > 0; --j) {
            if (check(vertexs[i], vertexs[res2[j]], vertexs[res2[j-1]]) < 0) {
                for (int k = 0; k <= j; ++k) {
                    tmp.push_back(res2[k]);
                }
                tmp.push_back(i);
                res2 = tmp;
                tmp.clear();
                break;
            }
            if (j == 1) {
                res2.clear();
                res2.push_back(len(vertexs)-1);
                res2.push_back(i);
            }
        }
    }

    for (int i = 1; i < len(res2); ++i) {
        res.push_back(res2[i]);
    }

    return res;
}

double calc_arg(vertex& v1, vertex& v2, vertex& v3) {
    complex<double> comp1(v2.x-v1.x, v2.y-v1.y);
    complex<double> comp2(v3.x-v1.x, v3.y-v1.y);
    comp2 /= comp1;
    return arg(comp2) * 180.0 / M_PI;
}

