  vector<double> probs;
  double a =  calc_arg(vertexs[convs[0]], vertexs[convs[1]], vertexs[convs[len(convs)-2]]);
  probs.push_back((180.0-a)/360.0);

  for (int i = 1; i < len(convs)-1; ++i) {
      a = calc_arg(vertexs[convs[i]], vertexs[convs[i+1]], vertexs[convs[i-1]]);
      probs.push_back((180.0-a)/360.0);
  }

  vector<double> ans(N);
  for (int i = 0; i < len(probs); ++i) {
      int n = vertexs[convs[i]].n;
      ans[n] = probs[i];
  }

