	}

	convex_hull(A,hull);

	for(int i=0;i<hull.size();i++)
	{
		int pre=(i-1+hull.size())%(hull.size());
		int nxt=(i+1)%((int)hull.size());
		ans[i]=dot(hull[pre]-hull[i],hull[nxt]-hull[i])/sqrt(dist2(hull[i],hull[nxt]));
		ans[i]/=sqrt(dist2(hull[i],hull[pre]));
		ans[i]=(PI-acos(ans[i]))/2;
		ans[i]/=PI;
	}	

	for(int i=1;i<=n;i++)
	{
		int fnd=0;
		for(int j=0;j<hull.size();j++)
		{
			if(fabs(x[i]-hull[j].x)<=eps&&fabs(y[i]-hull[j].y)<=eps)
