    ans[ids[0]] = ans[ids[1]] = 0.5;
  } else {
    for (int i = 0; i < m; ++i) {
      pt x = hull[(i + m - 1) % m];
      pt y = hull[i];
      pt z = hull[(i + 1) % m];
      pt A = x - y;
