            theta[j - (j > i)] = std::atan2(y[j] - y[i], x[j] - x[i]);
        }
        std::sort(theta.begin(), theta.end());
        difftheta[0] = 2 * PI + theta[0] - theta[n - 2];
        for (auto j = 1; j < n - 1; j++) {
            difftheta[j] = theta[j] - theta[j - 1];
        }
        auto res = *std::max_element(difftheta.begin(), difftheta.end());
        if (res < PI) std::cout << 0.0 << std::endl;
        else std::cout << (res - PI) / (2 * PI) << std::endl;
    }

    return 0;
}

