const double EPS = 1e-8;
const double INF = 1e12;
const double PI = acos(-1);

using Point = complex<double>;
using Polygon = vector<Point>;

inline int sgn(const double &a) { return (a < -EPS ? -1 : (a > EPS ? 1 : 0)); }

inline bool eq(const Point &a, const Point &b) { return abs(a - b) < EPS; }

namespace std {
inline bool operator<(const Point &a, const Point &b) {
    if (sgn(a.real() - b.real()))
        return sgn(a.real() - b.real()) < 0;
    return sgn(a.imag() - b.imag()) < 0;
}
} // namespace std

double dot(const Point &a, const Point &b) { return real(conj(a) * b); }

double det(const Point &a, const Point &b) { return imag(conj(a) * b); }

struct Line {
    Point p1, p2;

    Line(Point p1 = Point(), Point p2 = Point()) : p1(p1), p2(p2) {}

    bool operator<(const Line &rhs) const {
        if (eq(p2, rhs.p2))
            return p1 < rhs.p1;
        return p2 < rhs.p2;
    }
    bool operator==(const Line &rhs) const {
        return (eq(p1, rhs.p1) && eq(p2, rhs.p2)) ||
               (eq(p1, rhs.p2) && eq(p2, rhs.p1));
    }
};

enum CCW {
    ONLINE_FRONT = -2,
    CLOCKWISE,
    ON_SEGMENT,
    COUNTER_CLOCKWISE,
    ONLINE_BACK
};

int ccw(Point p0, Point p1, Point p2) {
    Point a = p1 - p0;
    Point b = p2 - p0;
    if (sgn(det(a, b)) == 1)
        return COUNTER_CLOCKWISE;
    if (sgn(det(a, b)) == -1)
        return CLOCKWISE;
    if (sgn(dot(a, b)) == -1)
        return ONLINE_BACK;
    if (sgn(norm(b) - norm(a)) == 1)
        return ONLINE_FRONT;
    return ON_SEGMENT;
}

Polygon convex_hull(Polygon s) {
    int n = s.size(), k = 0;
    if (n < 3)
        return s;
    sort(s.begin(), s.end());

    Polygon ch(2 * n);

    // 下側凸包
    for (int i = 0; i < n; i++) {
        while (k >= 2 && ccw(ch[k - 2], ch[k - 1], s[i]) == CLOCKWISE)
            k--;
        ch[k++] = s[i];
    }

    // 上側凸包
    for (int i = n - 2, t = k + 1; i >= 0; i--) {
        while (k >= t && ccw(ch[k - 2], ch[k - 1], s[i]) == CLOCKWISE)
            k--;
        ch[k++] = s[i];
    }

    ch.resize(k - 1);
    return ch;
}

int main(){
    int n;
    cin >> n;
    Polygon p;
    for(int i=0;i<n;++i){
        double x, y;
        cin >> x >> y;
        p.push_back(Point(x, y));
    }
    Polygon ch = convex_hull(p);
    ch.push_back(ch[0]);
    ch.push_back(ch[1]);
    map<Point, double> ans;
    for(int i=1;i<ch.size()-1;++i){
        double ag1 = atan2(imag(ch[i+1]-ch[i]), real(ch[i+1]-ch[i]));
        double ag2 = atan2(imag(ch[i]-ch[i-1]), real(ch[i]-ch[i-1]));
        ans[ch[i]] = (ag1 - ag2) / (2*PI);
        if(ans[ch[i]] < 0)ans[ch[i]] += 1;
    }

    for(auto pt : p){
        printf("%.10f\n",ans[pt]);
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;


constexpr double EPS = 1E-10;
// constexpr double EPS = 1E-5;

double add(double a, double b) {
    if (abs(a+b) < EPS * (abs(a) + abs(b))) return 0;
    return a+b;
}

struct P
{
    double x, y;
    P() {}
    P(double x, double y) : x(x), y(y) {}
    P operator + (P p) {
        return P(add(x, p.x), add(y, p.y));
    }
    P operator - (P p) {
        return P(add(x, -p.x), add(y, -p.y));
    }
    P operator * (double d) {
        return P(x*d, y*d);
    }
    double dot(P p) {
        return add(x*p.x, y*p.y);
    }
    double det(P p) {
        return add(x*p.y, -y*p.x);
    }
    double norm()
    {
        return sqrt(x*x+y*y);
    }
};

bool operator < (const P& a, const P& b) {
    return a.x != b.x ? a.x < b.x : a.y < b.y;
}

int ccw(P a, P b, P c)
{
    P v1 = b-a;
    P v2 = c-a;
    if (v1.det(v2) > EPS) return 1;
    if (v1.det(v2) < EPS) return -1;
    if (v1.dot(v2) < EPS) return 2;
    if (v1.norm() < v2.norm()) return -2;
    return 0;
}

double cosine(P a, P b, P c)
{
    P v1 = a - b;
    P v2 = c - b;
    return v1.dot(v2) / v1.norm() / v2.norm();
}

vector<pair<P, int> > convex_hull(vector<pair<P, int> >& ps)
{
    if (ps.size() == 0) return vector<pair<P, int> >(0);
    if (ps.size() == 1) return ps;
    vector<pair<P, int> > points = ps;
    sort(points.begin(), points.end());
    int n = points.size();
    int k=0;
    vector<pair<P, int> > qs(2*n);
    for (int i=0; i<n; i++) {
        while (k>1 && ccw(qs[k-2].first, qs[k-1].first, points[i].first) <= 0) k--;
        qs[k++] = points[i]; 
    }
    for (int i=n-2, t=k; i>=0; i--) {
        while (k>t && ccw(qs[k-2].first, qs[k-1].first, points[i].first) <= 0) k--;
        qs[k++] = points[i];
    }
    qs.resize(k-1);
    return qs;
}


int main()
{
    int N;
    cin >> N;
    if (N == 2)
    {
        cout << "0.5\n0.5" << endl;
        return 0;
    }
    vector<pair<P, int> > points(N);
    for (int i=0; i<N; i++)
    {
        int x, y;
        cin >> x >> y;
        points[i] = make_pair(P(x, y), i);
    }

    vector<pair<P, int> > totsu = convex_hull(points);

    vector<double> ans(N, 0.0);
    int n = (int)totsu.size();
    for (int i=0; i<n; i++)
    {
        // cout << totsu[i].first.x << " " << totsu[i].first.y << " " << totsu[i].second << endl;
        ans[totsu[i].second] = acos(-cosine(totsu[(i-1+n)%n].first, totsu[i].first, totsu[(i+1)%n].first)) / 3.14159265358979 / 2.0;
    }
    for (auto d : ans) cout << d << endl;
    return 0;
}

