  }

  convexHull();

//  p();

  // fill in the line segments
  // at this point expect each point to be paired with two other points
  //cout << "inserting" << endl;
  for (auto& kv : idx) {
    for (auto v : kv.SS) {
      idx[v].insert(kv.FF);
    }
  }

  //cout << "finding soln" << endl;
  map<LL, double> solution;
  // get angles formed by vectors
  for (auto& kv : idx) {
    LL c = kv.FF;

    if (kv.SS.size() == 1) {
      solution[c] = 0.5;
      continue;
    } else if (kv.SS.size() == 0) {
      solution[c] = 0;
      continue;
    }
    //cout << "(1)" << endl;
    auto it = kv.SS.begin();
    //cout << "(2)" << endl;
    LL l = *it;
    //cout << "(3)" << endl;
    LL r = *(++it);
    //cout << "(4)" << endl;
//    printf("c: %lld, l: %lld, r: %lld\n", c, l, r);
    Vector v1;
