    v1.x = x[l] - x[c];
    v1.y = y[l] - y[c];
    v2.x = x[r] - x[c];
    v2.y = y[r] - y[c];

    //cout << "(5)" << endl;
    double a = angle(v1, v2);
    if (a > M_PI) a -= M_PI;
    a = M_PI - a;

    double total = 2 * M_PI;
    solution[c] = a/total;
  }
  //cout << "done" << endl;

  FORN(i, N) {
