double calc(int i)
{
	int j,k;
	for(j=1;j<=n;++j)
	if(j!=i)
	{
		for(k=1;k<=n;++k)
		if(k!=i&&k!=j&&cross(x[j]-x[i],y[j]-y[i],x[k]-x[i],y[k]-y[i])>0)
		break;
		if(k>n)break;
	}
	if(j>n)return 0;
	double a=atan2(y[j]-y[i],x[j]-x[i]);
	for(j=1;j<=n;++j)
	if(j!=i)
	{
		for(k=1;k<=n;++k)
