using namespace std;
typedef complex<double> xy_t;


double R=10101010;
int N,drop,prob[100];
xy_t holes[100];

int main(){
    cin>>N;
    int x,y;
    for(int i=0;i<N;++i){
        cin>>x>>y;
        xy_t a(static_cast<double>(x),static_cast<double>(y));
        holes[i]=a;
    }
    random_device rnd;
    mt19937 mt(rnd());
    uniform_real_distribution<> dist(-R,R);
    xy_t loc(0,0);

    int iteration=1001001;

    for(int j=0;j<iteration;++j){
        while(true){
            double x=dist(mt),y=dist(mt);
            //cout<<x<<endl;
            xy_t b(x,y);
            loc=b;
            if(abs(loc)<=static_cast<double>(R)) break;
        }

        double min=R*R;
        for(int i=0;i<N;++i){
            if(min>abs(holes[i]-loc)){
                min=abs(holes[i]-loc);
                drop=i;
            }
        }
        prob[drop]++;
    }

    for(int i=0;i<N;++i){
        double output=static_cast<double>(prob[i]);
        cout<<setprecision(20)<<output/iteration<<endl;
    }


}

