		vec[i] = Point{a, b};
		mp[vec[i]] = i;
	}

	auto ch = convexFull(vec);
	std::vector<double> ans(n, 0);
	const double Pi = std::acos(-1);
	for(int i = 0; i < ch.size(); i++) {
		Point u = ch[(i + ch.size() - 1) % ch.size()] - ch[i];
		Point v = ch[(i + 1) % ch.size()] - ch[i];
		ans[mp[ch[i]]] = angle(u, v) / 2.0 / Pi;
	}

	for(auto v : ans) cout << std::fixed << std::setprecision(10) << v << endl;
	return 0;
}

