	for(int i = 0; i < N; i++){
		if(i == index) continue; 
		long long int a = P[soeji].first; 
		long long int b = P[soeji].second; 
		long long int c = P[i].first; 
		long long int d = P[i].second; 
		long double e = (double) (d-b) * pow((c-a) * (c-a) + (d-b) * (d-b), -0.5);
		if(e > mx) {
			index = i; mx = e; 
		}
	}
	CH.push_back(index); 
