using ll = long long;

const long double PI = 3.1415926535;

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n;
    cin >> n;
    vector<long double> x(n), y(n);
    for (int i = 0; i < n; i++) {
        cin >> x[i] >> y[i];
    }
    std::random_device rnd;
    std::mt19937 mt(rnd());
    const long double R = 1e15;
    uniform_real_distribution<> rand_real(-R, R);
    vector<int> cnt(n, 0);
    const int MAX_LOOP = 1000000;
    for (int i = 0; i < MAX_LOOP; i++) {
        long double X = R * cos(2 * PI * i / MAX_LOOP);
        long double Y = R * sin(2 * PI * i / MAX_LOOP);
        int idx = 0;
        long double mind = 1e100;
        for (int j = 0; j < n; j++) {
            long double dx = x[j] - X, dy = y[j] - Y;
            long double d = dx * dx + dy * dy;
            if (mind > d) {
                idx = j;
                mind = d;
            }
        }
        cnt[idx]++;
    }

    for (int i = 0; i < n; i++) {
        cout << setprecision(10) << (long double)cnt[i] / MAX_LOOP << endl;
    }
    return 0;
