typedef long long i64;
const int inf = (int)1.05e9;
typedef complex<long double> point;

long double dot(const point& a, const point& b)
{
	return real(a) * real(b) + imag(a) * imag(b);
}

long double det(const point& a, const point& b)
{
	return real(a) * imag(b) - imag(a) * real(b);
}

vector<point> convex_hull(vector<point> ps)
{
	auto sort_fn = [](const point& a, const point& b) {
		return real(a) != real(b) ? real(a) < real(b) : imag(a) < imag(b);
	};
	sort(ps.begin(), ps.end(), sort_fn);

	int n = ps.size();
	vector<point> qs;

	for(int i = 0; i < n; ++i) {
		while(qs.size() > 1) {
			auto& x = qs[qs.size() - 2];
			auto& y = qs[qs.size() - 1];
			auto& z = ps[i];
			if(det(y - x, z - y) > 0)
				break;
			qs.pop_back();
		}
		qs.push_back(ps[i]);
	}

	int t = qs.size();

	for(int i = n - 2; i >= 0; --i) {
		while(qs.size() > t) {
			auto& x = qs[qs.size() - 2];
			auto& y = qs[qs.size() - 1];
			auto& z = ps[i];
			if(det(y - x, z - y) > 0)
				break;
			qs.pop_back();
		}
		qs.push_back(ps[i]);
	}

	qs.pop_back();

	return qs;
}

const long double PI = 3.14159265358979323846264338327950288;

int main()
{
	vector<point> ps;
	int n;

	scanf("%d", &n);

	for(int i = 0; i < n; ++i) {
		int x, y;
		scanf("%d%d", &x, &y);
		ps.push_back(complex<long double>(x, y));
	}

	auto qs = convex_hull(ps);
	int m = qs.size();

	vector<double> ans(n, 0);

	for(int i = 0; i < m; ++i) {

		auto& x = qs[(i + m - 1) % m];
		auto& y = qs[i];
		auto& z = qs[(i + 1) % m];

		auto t1 = y - x;
		auto t2 = z - y;

		long double a = dot(t1, t2) / (abs(t1) * abs(t2));
		a = max(min(a, (long double)1.0), (long double)-1.0);
		long double r = acos(a);

		long double p = r / (2 * PI);

		for(int j = 0; j < n; ++j) {
			if(y == ps[j])
				ans[j] = (double)p;
		}
	}

	for(auto a : ans) {
		printf("%.20lf\n", a);
	}

	return 0;
}

