using namespace std;

const int MAX_N = 101;
const double PI = 3.14159265358979323846264338327950288;

struct P {
    double x, y;
    int idx;
    P() {}
    P(double x, double y) : x(x), y(y) {
    }
    P operator+ (P p) {
        return P(x + p.x, y + p.y);
    }
    P operator- (P p) {
        return P(x - p.x, y - p.y);
    }
    P operator* (double d) {
        return P(x * d, y * d);
    }
    double dot(P p) {
        return x * p.x + y * p.y;
    }
    double det(P p) {
        return x * p.y - y * p.x;
    }
};

bool cmp_x(const P& p, const P& q) {
    if (p.x != q.x) return p.x < q.x;
    return p.y < q.y;
}

vector<P> convex_hull(vector<P> ps, int n) {
    sort(ps.begin(), ps.end(), cmp_x);
    int k = 0;
    vector<P> qs(n * 2);
    // 下側
    for (int i = 0; i < n; i++) {
        while (k > 1 && (qs[k - 1] - qs[k - 2]).det(ps[i] - qs[k - 1]) <= 0) k--;
        qs[k++] = ps[i];
    }
    // 上側
    for (int i = n - 2, t = k; i >= 0; i--) {
        while (k > t && (qs[k - 1] - qs[k - 2]).det(ps[i] - qs[k - 1]) <= 0) k--;
        qs[k++] = ps[i];
    }
    qs.resize(k - 1);
    return qs;
}

int main() {
    int N;
    double x, y;
    cin >> N;
    vector<P> ps(N);
    for (int i = 0; i < N; i++) {
        cin >> x >> y;
        ps[i].x = x, ps[i].y = y, ps[i].idx = i;
    }
    if (N == 2) {
        // N = 2の時は凸包ができないため
        cout << fixed << setprecision(7);
        cout << 0.5 << endl;
        cout << 0.5 << endl;
        return 0;
    }
    vector<P> qs = convex_hull(ps, N);
    qs.push_back(qs[0]);
    qs.push_back(qs[1]);
    vector<double> ans(N, 0.0);
    for (int i = 0; i < qs.size() - 2; i++) {
        P pr = qs[i] - qs[i + 1], pq = qs[i + 2] - qs[i + 1];  // i+1番目の座標を基準とした座標を作成
        double len_pr = sqrt(pr.x * pr.x + pr.y * pr.y), len_pq = sqrt(pq.x * pq.x + pq.y * pq.y);
        ans[qs[i + 1].idx] = (PI - acos(pr.dot(pq) / (len_pr * len_pq))) / (2 * PI);
    }
    cout << fixed << setprecision(7);
    for (int i = 0; i < N; i++) {
        cout << ans[i] << endl;
    }
    return 0;
}

