// 凸包
vector<pair<Point, int> > ConvexHull(vector<pair<Point, int>> &ps) {
    int n = (int)ps.size();
    vector<pair<Point, int> > res(2*n);
    sort(ps.begin(), ps.end());
    int k = 0;
    for (int i = 0; i < n; ++i) {
        if (k >= 2) {
            while (cross(res[k-1].first - res[k-2].first, ps[i].first - res[k-2].first) < EPS) {
                --k;
                if (k < 2) break;
            }
        }
        res[k].first = ps[i].first;
        res[k].second = ps[i].second;
        ++k;
    }
    int t = k+1;
    for (int i = n-2; i >= 0; --i) {
        if (k >= t) {
            while (cross(res[k-1].first - res[k-2].first, ps[i].first - res[k-2].first) < EPS) {
                --k;
                if (k < t) break;
            }
        }
        res[k].first = ps[i].first;
        res[k].second = ps[i].second;
        ++k;
    }
    res.resize(k-1);
    return res;
}

void solve() {
	int n; cin >> n;
    vector<pair<Point, int>> vp(n);
    rep(i, n) cin >> vp[i].fr.x >> vp[i].fr.y, vp[i].sc = i;

    auto ch = ConvexHull(vp);
    int m = ch.size();

    vector<DD> res(n, 0.0);
    rep(i, m) {
        int id = ch[i].sc;
        //Pointはベクトルみたいなもの
        Point prev = rot90(ch[(i-1+m)%m].fr - ch[i].fr);
        Point next = rot90(ch[i].fr - ch[(i+1)%m].fr);
        DD prevang = amp(prev);
        DD nextang = amp(next);
        DD ang = nextang - prevang;
        if(ang < 0) ang += PI * 2;

        DD prob = ang / (PI * 2);
        res[id] = prob;
    }

    rep(i, n) {
        cout << res[i] << endl;
    }
}

