const double EPS = 1e-8;
const double INF = 1e12;
typedef complex<ll> P;
namespace std {
  bool operator < (const P& a, const P& b) {
    return real(a) != real(b) ? real(a) < real(b) : imag(a) < imag(b);
  }
}
ll cross(const P& a, const P& b) {
  return imag(conj(a)*b);
}
ll dot(const P& a, const P& b) {
  return real(conj(a)*b);
}

typedef vector<P> G;

int ccw(P a, P b, P c) {
  b -= a; c -= a;
  if (cross(b, c) > 0)   return +1;       // counter clockwise
  if (cross(b, c) < 0)   return -1;       // clockwise
  if (dot(b, c) < 0)     return +2;       // c--a--b on line
  if (norm(b) < norm(c)) return -2;       // a--b--c on line
  return 0;
}

vector<P> convex_hull(vector<P> ps) {
  int n = ps.size(), k = 0;
  sort(ps.begin(), ps.end());
  vector<P> ch(2*n);
  for (int i = 0; i < n; ch[k++] = ps[i++]) // lower-hull
    while (k >= 2 && ccw(ch[k-2], ch[k-1], ps[i]) <= 0) --k;
  for (int i = n-2, t = k+1; i >= 0; ch[k++] = ps[i--]) // upper-hull
    while (k >= t && ccw(ch[k-2], ch[k-1], ps[i]) <= 0) --k;
  ch.resize(k-1);
  return ch;
}

int main(){
	ll N;
	cin >> N;
	vector<P> input;
	REP(i, N){
		ll x, y;
		cin >> x >> y;
		P tmp(x, y);
		input.push_back(tmp);
	}
	vector<P> ch = convex_hull(input);
	ll M = ch.size();
	map<P, double> res;
	REP(i, M){
		P p1 = ch[i] - ch[(i-1+M)%M];
		P p2 = ch[(i+1)%M] - ch[i];
		double norm1 = sqrt(norm(p1));
		double norm2 = sqrt(norm(p2));
		double coss = (double)dot(p1, p2)/(norm1*norm2);
		double sinn = (double)cross(p1, p2)/(norm1*norm2);
		double theta = atan2(sinn, coss);
		res[ch[i]] = theta;
	}
	REP(i, N){
      	bool flag = (res.find(input[i])!=res.end());
		if(flag){
			printf("%.20f\n", res[input[i]]/(2*M_PI));
		}else{
			printf("%.20f\n", 0.0);
		}
	}
    return 0;
}

