int main() {
    int N;
    double x[MAX_N], y[MAX_N];
    double min_arg[MAX_N], max_arg[MAX_N], arg[MAX_N];

    cin >> N;
    for (int i = 0; i < N; ++i) {
        cin >> x[i] >> y[i];
    }
    fill(min_arg, min_arg + N, 0);
    fill(max_arg, max_arg + N, 2 * M_PI);


    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (i == j) continue;
            double theta;
            if (x[i] != x[j]) {
                double tan = (y[j] - y[i]) / (x[j] - x[i]);
                theta = atan(tan);
                if (x[i] > x[j]) theta += M_PI;

            } else {
                theta = M_PI / 2;
                if (y[i] > y[j]) theta += M_PI;
            }

            if (theta < 0) theta += 2 * M_PI;  // theta: [0, 2pi)

            double min_ = M_PI / 2 + theta, max_ = - M_PI / 2 + theta;
            if (max_ < 0) max_ += 2 * M_PI;
            if (min_ > 2 * M_PI) min_ -= 2 * M_PI;

            if (min_arg[i] == 0 && max_arg[i] == 2 * M_PI) {
                min_arg[i] = min_; max_arg[i] = max_;
                continue;
            }

            double a = min_arg[i] - max_, b = max_arg[i] - min_;
            if (a > M_PI) a -= 2 * M_PI;
            if (a < -M_PI) a += 2 * M_PI;
            if (b > M_PI) b -= 2 * M_PI;
            if (b < -M_PI) b += 2 * M_PI;

            if (a >= 0 && b <= 0) {
                min_arg[i] = max_arg[i] = 0;
                break;
            } else if (a >= 0 && b > 0) {
                min_arg[i] = min_;
            } else if (a < 0 && b <= 0) {
                max_arg[i] = max_;
            }
        }

        arg[i] = max_arg[i] - min_arg[i];
        if (arg[i] < 0) arg[i] += 2 * M_PI;

    }

    for (int i = 0; i < N; ++i) {
        printf("%.6f\n", arg[i] / (2 * M_PI));
    }

    return 0;
}

