double add(double a, double b){
  if(abs(a+b) < EPS * (abs(a) + abs(b))) return 0;
  return a+b;
}
struct V{
  double x, y;
  V() {}
  V(double x, double y) : x(x), y(y){
  }
  V operator + (V v){
    return V(add(x, v.x), add(y, v.y));
  }
  V operator - (V v){
    return V(add(x, -v.x), add(y, -v.y));
  }
  V operator * (double d){
    return V(x * d, y * d);
  }
  bool operator == (V v){
    if(x == v.x && y == v.y) return true;
    else return false;
  }
  double dot(V v){
    return add(x * v.x, y * v.y);
  }
  double det(V v){
    return add(x * v.y, -y * v.x);
  }
};

bool cp(V p, V q){
  if(p.x != q.x) return (p.x < q.x);
  else (p.y < q.y);
}

vector<V> ch(V ps[], int n){
  sort(ps, ps+n, cp);
  int k = 0;
  vector<V> qs(2*n);
  REP(i, n){
    while(k>1 && (qs[k-1] - qs[k-2]).det(ps[i] - qs[k-1]) <= 0) k--;
    qs[k++] = ps[i];
  }
  for(int i = n-2, t = k; i >= 0; i--){
    while(k>t && (qs[k-1] - qs[k-2]).det(ps[i] - qs[k-1]) <= 0) k--;
    qs[k++] = ps[i];
  }
  qs.resize(k-1);
  return qs;
}

double angle(V v1, V v2){
  if(abs(((v1.dot(v2))/pow(v1.dot(v1), 0.5)/pow(v2.dot(v2), 0.5))-1) < EPS) return PI;
  return PI - acos((v1.dot(v2))/pow(v1.dot(v1), 0.5)/pow(v2.dot(v2), 0.5));
}

int main(){
  int n;
  cin >> n;
  V p[n];
  REP(i, n) cin >> p[i].x >> p[i].y;
  V r[n];
  REP(i, n) r[i] = p[i];
  vector<V> q = ch(r, n);
  int k = q.size();
  int ind[k];
  bool check[n] = { };
  int c = 0;
  for(V pt: q){
    REP(i, n){
      if(pt == p[i]){
        ind[c] = i;
        c++;
        check[i] = true;
      }
    }
  }
  double ans[n] = { };
  REP(i, k){
    V prev = p[ind[(i-1+k)%k]];
    V nxt = p[ind[(i+1)%k]];
    V v1 = p[ind[i]] - prev;
    V v2 = p[ind[i]] - nxt;
    ans[ind[i]] = angle(v1, v2);
  }
  REP(i, n) cout << fixed << setprecision(16) << ans[i]/2.0/PI << endl;
}

