double arctan(int index1, int index2)
{
    int x1 = x[index1];
    int y1 = y[index1];
    int x2 = x[index2];
    int y2 = y[index2];

    double result =
        x2 == x1 ? M_PI / (double)2 : atan((double)(y2 - y1) / (double)(x2 - x1));

    if (result < 0)
        result += M_PI;

    if (y1 > y2)
        result += M_PI;

    return result;
}

double calc(int index)
{
    vector<double> angles;

    rep(i, n)
    {
        if (i == index)
            continue;

        double angle = arctan(index, i);
        if (angle < (double)0)
            angle += (M_PI * (double)2);
        angles.push_back(angle);
    }

    sort(angles.begin(), angles.end());
    double mx = (angles[0] - angles[angles.size() - 1]) + (M_PI * (double)2);

    rep(i, angles.size() - 1)
    {
        double m = angles[i + 1] - angles[i];
        mx = max(mx, m);
    }

    if (mx < M_PI)
        return 0;

    return (mx / M_PI - 1) / 2;
}

