struct Seg {
    double X, Y;
    Seg () {}
    Seg(double _1, double _2) {
        X = _1;
        Y = _2;
    }
    bool operator < (const Seg& A) const {
        return X < A.X;
    }
};

vector <Seg> S;

int n, X[111], Y[111];

int main() {
    scanf("%d", &n);
    for(int i = 1; i <= n; i++) scanf("%d%d", &X[i], &Y[i]);
    for(int i = 1; i <= n; i++) {
        S.clear();
        for(int j = 1; j <= n; j++) if(j != i) {
            double tmp = atan2(Y[j] - Y[i], X[j] - X[i]);
            double l = tmp - M_PI / 2, r = tmp + M_PI / 2;
            if(r < 0) l += 2 * M_PI, r += 2 * M_PI;
            if(l > 2 * M_PI) l -= 2 * M_PI, r -= 2 * M_PI;
            if(l < 0) {
                S.push_back(Seg(l + 2 * M_PI, 2 * M_PI));
                S.push_back(Seg(0, r));
            } else S.push_back(Seg(l, r));
        }
        sort(S.begin(), S.end());
        double ans = 2 * M_PI, pr = S[0].X, nx = S[0].Y;
        for(int i = 1; i < S.size(); i++)
            if(S[i].X > nx) {
                ans -= nx - pr;
                pr = S[i].X;
                nx = S[i].Y;
            } else nx = max(nx, S[i].Y);
        ans -= nx - pr;
        printf("%.15lf\n", ans / 2 / M_PI);
    }
    return 0;
}

