//2dvector
struct P {
	ldouble x, y;
	P() {}
	P(ldouble x, ldouble y) :x(x), y(y) {}
	P operator + (P p) {
		return P(add(x, p.x), add(y, p.y));
	}
	P operator - (P p) {
		return P(add(x, -p.x), add(y, -p.y));
	}
	P operator * (ldouble d) {
		return P(x*d, y*d);
	}
	ldouble dot(P p) {
		return add(x*p.x, y*p.y);
	}
	ldouble det(P p) {
		return add(x*p.y, -y*p.x);
	}
};

//compare_dict
bool cmp_x(const P& p, const P& q) {
	if (p.x != q.x)return p.x < q.x;
	return p.y < q.y;
}

//find convex hull
vector<P> convex_hull(P* ps, int n) {
	sort(ps, ps + n, cmp_x);
	int k = 0;	//vertex_num_of_convex_hull
	vector<P>qs(n * 2);	//convex_hull

						//Lower_part
	for (int i = 0; i < n; i++) {
		while (k > 1 && (qs[k - 1] - qs[k - 2]).det(ps[i] - qs[k - 1]) <= 0)k--;
		qs[k++] = ps[i];
	}
	//Upper_part
	for (int i = n - 2, t = k; i >= 0; i--) {
		while (k > t && (qs[k - 1] - qs[k - 2]).det(ps[i] - qs[k - 1]) <= 0)k--;
		qs[k++] = ps[i];
	}
	qs.resize(k - 1);
	return qs;
}

//squared_dist
ldouble dist(P p, P q) {
	return (p - q).dot(p - q);
}

