vector<P> convex_hull(vector<P> ps) {
  sort(all(ps));
  vector<P> ue, sita;
  ue.pb(ps[0]);
  sita.pb(ps[0]);
  for (int i=1; i<ps.size(); i++) {
    while (ue.size() >= 2 && det(ue.back()-ue[ue.size()-2], ps[i]-ue.back()) >= 0) ue.pop_back();
    ue.pb(ps[i]);
    while (sita.size() >= 2 && det(sita.back()-sita[sita.size()-2], ps[i]-sita.back()) <= 0) sita.pop_back();
    sita.pb(ps[i]);
  }

  vector<P> ret;
  assert(ue.back() == sita.back());
  assert(ue.front() == sita.front());
  sita.pop_back();
  reverse(all(sita));
  sita.pop_back();
  for (P x : ue) ret.pb(x);
  for (P x : sita) ret.pb(x);
  return ret;
}

