vector<P> convex_hull(vector<P>& ps) {
	int n = sz(ps);
	sort(all(ps));
	int k = 0;
	vector<P> qs(n * 2);
	rep(i, 0, n) {
		while(k > 1 && (qs[k - 1] - qs[k - 2]).det(ps[i] - qs[k - 1]) <= -eps) k--;
		qs[k++] = ps[i];
	}

	for(int i = n - 2, t = k; i >= 0; i--) {
		while(k > t && (qs[k - 1] - qs[k - 2]).det(ps[i] - qs[k - 1]) <= -eps) k--;
		qs[k++] = ps[i];
	}
	qs.resize(k - 1);
	return qs;
}

