//２つのベクトルABのなす角度θを求める
DD AngleOf2Vector(Point A, Point B )
{
	//　※ベクトルの長さが0だと答えが出ませんので注意してください。

	//ベクトルAとBの長さを計算する
	DD length_A = get_vector_length(A);
	DD length_B = get_vector_length(B);

	//内積とベクトル長さを使ってcosθを求める
	DD cos_sita = dot(A,B) / ( length_A * length_B );

	//cosθからθを求める
	DD sita = acos( cos_sita );	

	//ラジアンでなく0～180の角度でほしい場合はコメント外す
	//sita = sita * 180.0 / PI;

	return sita;
}

vector<Point> convex_hull(vector<Point> ps){
  int n=ps.size(),k=0;
  sort(ps.begin(),ps.end());
  vector<Point> res(2*n);
  for(int i=0;i<n;res[k++]=ps[i++]){
    while(k>=2&&ccw(res[k-2],res[k-1],ps[i])<=0)--k;
  }
  for(int i=n-2,t=k+1;i>=0;res[k++]=ps[i--]){
    while(k>=t&&ccw(res[k-2],res[k-1],ps[i])<=0)--k;
  }
  res.resize(k-1);
  return res;
}

