  rep(i,n){
    DD x,y;cin>>x>>y;
    xy.push_back(Point(x,y));
  }
  map<Point,DD> M;
  auto ch=convex_hull(xy);
  int chsz=ch.size();
  if(chsz==2){
    M[ch[0]]=M[ch[1]]=0.5;
    rep(i,n)cout<<M[xy[i]]<<endl;
    exit(0);
  }
  rep(i,chsz){
    cout<<ch[i]<<endl;
    int prev=(i-1+chsz)%chsz;
    int next=(i+1)%chsz;
    Point P=(ch[prev]-ch[i]);
    Point Q=(ch[next]-ch[i]);
    DD r=AngleOf2Vector(P,Q);
    M[ch[i]]=0.5-r/(2*PI);
  }
  rep(i,n)cout<<setprecision(10)<<M[xy[i]]<<endl;

}

