//円cと線分lの交点の数を返す
int hasCrossPoints(Circle c, Line l){
	double dis = getDistanceLP(l,c.c);
	if(equals(dis,c.r))return 1;
	if(dis < c.r)return 2;
	return 0;
}
//円cと線分lの交点を返す
pair<Point,Point> getCrossPoints(Circle c, Line l){
	assert(getDistanceLP(l,c.c) < c.r+EPS);
	Vector pr=project(l, c.c);
	Vector e=(l.p2-l.p1)/(l.p2-l.p1).abs();
	double base=sqrt(c.r*c.r-(pr-c.c).norm());
	return {pr+e*base, pr-e*base};
}


