struct point {
    long long x, y;
};

bool cmp(point a, point b) {
    return a.x < b.x || a.x == b.x && a.y < b.y;
}
bool cw(point a, point b, point c) {
    return a.x * (b.y - c.y) + b.x * (c.y - a.y) + c.x * (a.y - b.y) < 0;
}

bool ccw(point a, point b, point c) {
    return a.x * (b.y - c.y) + b.x * (c.y - a.y) + c.x * (a.y - b.y) > 0;
}

vector<point> polygon_convex_hull(vector<point> v) {
    if (v.size() == 1)
        return v;
    sort(v.begin(), v.end(), &cmp);
    point p1 = v.front();
    point p2 = v.back();
    vector<point> up, down;
    up.push_back(p1);
    down.push_back(p1);
    for (int i = 1; i < v.size(); i++) {
        if (i == v.size() - 1 || cw(p1, v[i], p2)) {
            while (up.size() >= 2 && !cw(up[up.size() - 2], up[up.size() - 1], v[i]))
                up.pop_back();
            up.push_back(v[i]);
        }
        if (i == v.size() - 1 || ccw(p1, v[i], p2)) {
            while (down.size() >= 2 && !ccw(down[down.size() - 2], down[down.size() - 1], v[i]))
                down.pop_back();
            down.push_back(v[i]);
        }
    }
    vector<point> hull;
    for (int i = 0; i < up.size(); i++)
        hull.push_back(up[i]);
    for (int i = down.size() - 2; i > 0; i--)
        hull.push_back(down[i]);
    return hull;
}

const double PI = acos(-1.0);

double sqr(double a) {
    return a * a;
}

double point_dis(point a, point b) {
    return sqrt((double) sqr(b.x - a.x) + sqr(b.y - a.y));
}

double point_dot(point a, point b, point c) {
    return (b.x - a.x) * (c.x - a.x) + (b.y - a.y) * (c.y - a.y);
}

double point_angle(point a, point b, point c) {
    return acos(point_dot(a, b, c) / (point_dis(a, b) * point_dis(a, c)));
}

void solve() {
	int n;
	cin >> n;
	vector<point> v(n);
	map<pi, int> mp;
	rep(i, 0, n) {
		cin >> v[i].x >> v[i].y;
		mp[{v[i].x, v[i].y}] = i;
	}
	vector<point> hull = polygon_convex_hull(v);
	int m = sz(hull);
	vector<double> ans(n, 0);
	rep(i, 0, m) {
		int l = (i + m - 1) % m, r = (i + 1) % m;
		double ang = fabs(PI - fabs(point_angle(hull[i], hull[l], hull[r]))) / (2.0 * PI);
		int ind = mp[{hull[i].x, hull[i].y}];
		ans[ind] = ang;
	}
	rep(i, 0, n)
		printf("%0.12lf\n", ans[i]);
}

