using namespace std;
using ll = long long;
static const double PI = 3.14159265359;

struct Point {
	ll x, y;
	Point() : x(0), y(0) { }
	Point(ll x, ll y) : x(x), y(y) { }
};

ll dot(const Point& a, const Point& b){ return a.x * b.x + a.y * b.y; }
ll cross(const Point& a, const Point& b){ return a.x * b.y - a.y * b.x; }
ll norm(const Point& a){ return a.x * a.x + a.y * a.y; }

int ccw(const Point& a, const Point& b, const Point& c){
	const Point d(b.x - a.x, b.y - a.y);
	const Point e(c.x - a.x, c.y - a.y);
	if(cross(d, e) > 0){ return  1; }
	if(cross(d, e) < 0){ return -1; }
	if(dot(d, e) < 0){ return 2; }
	if(norm(d) < norm(e)){ return -2; }
	return 0;
}

vector<Point> convex_hull(vector<Point> ps){
	const int n = ps.size();
	sort(ps.begin(), ps.end(), [](const Point& a, const Point& b){ return a.x < b.x; });
	vector<Point> ch(2 * n);
	int k = 0;
	for(int i = 0; i < n; ch[k++] = ps[i++]){
		while(k >= 2 && ccw(ch[k - 2], ch[k - 1], ps[i]) <= 0){ --k; }
	}
	for(int i = n - 2, t = k + 1; i >= 0; ch[k++] = ps[i--]){
		while(k >= t && ccw(ch[k - 2], ch[k - 1], ps[i]) <= 0){ --k; }
	}
	ch.resize(k - 1);
	return ch;
}

int main(){
	ios_base::sync_with_stdio(false);
	cout << setiosflags(ios::fixed) << setprecision(10);
	int n;
	cin >> n;
	vector<Point> pts(n);
	for(int i = 0; i < n; ++i){ cin >> pts[i].x >> pts[i].y; }
	const auto ch = convex_hull(pts);
	const int m = ch.size();
	vector<double> angles(m);
	for(int i = 0; i < m; ++i){
		const auto a = ch[(i - 1 + m) % m];
		const auto b = ch[i];
		const auto c = ch[(i + 1) % m];
		const Point d(a.x - b.x, a.y - b.y);
		const Point e(c.x - b.x, c.y - b.y);
		angles[i] = PI - acos(dot(d, e) / (sqrt(norm(d)) * sqrt(norm(e))));
	}
	vector<double> answer(n);
	for(int i = 0; i < n; ++i){
		for(int j = 0; j < m; ++j){
			if(pts[i].x == ch[j].x && pts[i].y == ch[j].y){
				answer[i] = angles[j] / (2.0 * PI);
				break;
			}
		}
	}
	for(const auto x : answer){
		cout << x << endl;
	}
	return 0;
}

