Point c[N]; // convex hull
double res[N];

long long ccw(Point O, Point A, Point B) {
	A.x -= O.x; A.y -= O.y;
	B.x -= O.x; B.y -= O.y;
	return 1LL * A.x * B.y - 1LL * A.y * B.x;
}

double angle(Point O, Point A, Point B) {
	A.x -= O.x; A.y -= O.y; 
	B.x -= O.x; B.y -= O.y;
	double angleA = atan2(A.y, A.x);
	double angleB = atan2(B.y, B.x);
	double ret = angleA - angleB;
	while(ret < 0) ret += pi;
	while(ret >= pi) ret -= pi;
	return ret;	
}

