const ll mxn = 105;
const ld pi = 3.14159265359;
ld probability[mxn];

struct Poll
{
	ll x, y, id= -1;
	bool operator<(const Poll b) const {
		return x<b.x or (x==b.x and y<b.y);
	}
	bool operator==(const Poll b) const {
		return x==b.x and y==b.y;
	}
	Poll operator-(const Poll b) {
		ll x0 = x-b.x, y0 = y-b.y;
		Poll p; p.x = x0, p.y = y0;
		return p;
	}
};

bool cw(Poll a, Poll b, Poll c) {
	return a.x*(b.y-c.y)+b.x*(c.y-a.y)+c.x*(a.y-b.y)>0;
}

ld length(Poll a, Poll b) {
	return sqrt((b.x-a.x)*(b.x-a.x)+(b.y-a.y)*(b.y-a.y));
}

ld dot(Poll a, Poll b) {
	return a.x*b.x+a.y*b.y;
}

ld cosin(Poll a, Poll b, Poll c) {
	ld ret = dot(a-b, c-b);
	ret = ret/(length(a, b)*length(c, b));
	return ret;
}

vector<Poll> convex(vector<Poll> &v) {
	vector<Poll> ret;
	if(2>=(ll) v.size()) return ret;
	sort(v.begin(), v.end());
	vector<Poll> up, down;
	up.emplace_back(v[0]); down.emplace_back(v[0]);
	Poll A = v[0], B = v.back();
	for(ll i=1; i<(ll) v.size()-1; i++) {
		if(cw(A, v[i], B)) {
			while(up.size()>=2 and !cw(up[up.size()-2], up[up.size()-1], v[i]))
				up.pop_back();
			up.emplace_back(v[i]);
		}
		else {
			while(down.size()>=2 and cw(down[down.size()-2], down[down.size()-1], v[i]))
				down.pop_back();
			down.emplace_back(v[i]);
		}
	}
	up.emplace_back(B), down.emplace_back(B);
	reverse(down.begin(), down.end());
	ret = up;
	for(ll i=1; i<(ll)down.size()-1; i++) ret.emplace_back(down[i]);
	assert(ret.front()==A);
	return ret;
}

int main() {
	ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);
	ll N; cin>>N;
	vector<Poll> polls;
	for(ll i=0 ;i<N; i++) {
		ll x, y; cin>>x>>y;
		Poll p; p.x = x, p.y = y, p.id = i;
		polls.emplace_back(p);
	}
	if(N==2) {
		cout << 0.5 << '\n' << 0.5 << '\n';
		return 0;
	}
	vector<Poll> hull = convex(polls);
	ll sz = hull.size();
	for(ll i=1; i<sz-1; i++) {
		ld angle = acos(cosin(hull[i-1], hull[i], hull[i+1]));
		probability[hull[i].id] = (pi-angle)/(2*pi);
	}
	ld angle  = acos(cosin(hull[hull.size()-1], hull[0], hull[1]));
	probability[hull[0].id] = (pi-angle)/(2*pi);
	angle = acos(cosin(hull[hull.size()-2] ,hull[hull.size()-1], hull[0]));
	probability[hull[hull.size()-1].id] = (pi-angle)/(2*pi);

	cout.precision(20);
	for(ll i=0; i<N; i++) cout << fixed << probability[i] << '\n';
	return 0;	
}

