vector<pt> upper_hull(vector<pt> pts){
  sort(ALL(pts), [](const pt &a, const pt &b){return (a.x < b.x) or (a.x == b.x and a.y < b.y);});
  reverse(ALL(pts));

  vector<pt> ret;

  ret.push_back(pts.back());
  pts.pop_back();

  while(not pts.empty()){
    auto s = pts.back();
    pts.pop_back();

    if(ret.size() == 1){
      ret.push_back(s);
    }else{
      auto p = *(ret.end()-2);
      auto q = ret.back();

      if(cross(q-p, s-p) <= 0){
	ret.push_back(s);
      }else{
	ret.pop_back();
	pts.push_back(s);
      }
    }
  }

  return ret;
}

vector<pt> lower_hull(vector<pt> pts){
  sort(RALL(pts), [](const pt &a, const pt &b){return (a.x < b.x) or (a.x == b.x and a.y < b.y);});
  reverse(ALL(pts));

  vector<pt> ret;

  ret.push_back(pts.back());
  pts.pop_back();

  while(not pts.empty()){
    auto s = pts.back();
    pts.pop_back();

    if(ret.size() == 1){
      ret.push_back(s);
    }else{
      auto p = *(ret.end()-2);
      auto q = ret.back();

      if(cross(q-p, s-p) <= 0){
	ret.push_back(s);
      }else{
	ret.pop_back();
	pts.push_back(s);
      }
    }
  }

  return ret;
}

vector<pt> convex_hull(const vector<pt> &pts){
  vector<pt> ret = upper_hull(pts);
  auto lower = lower_hull(pts);

  ret.pop_back();
  lower.pop_back();

  for(auto &p : lower) ret.push_back(p);

  return ret;
}


