const int MAXN = 100;

struct punct{double x,y;int id;};
punct v[1 + MAXN],stiva[1 + MAXN];
int compare(int a,int b){
    if(v[a].x<v[b].x)
        return a;
    if(v[a].x>v[b].x)
        return b;
    if(v[a].y<=v[b].y)
        return a;
    return b;
}
void schimba(int a,int b){
    punct aux;
    aux=v[a];
    v[a]=v[b];
    v[b]=aux;
}
bool cmp(punct a,punct b){
    if((a.x-v[1].x)*(b.y-v[1].y)-(a.y-v[1].y)*(b.x-v[1].x)<0)
        return true;
    return false;
}

double answer[1 + MAXN];
const double PI = acos(-1);

double Angle(punct c, punct a, punct b) {
    punct e = {a.x - c.x, a.y - c.y}, f = {b.x - c.x, b.y - c.y};
    double pe = atan2(e.y, e.x), pf = atan2(f.y, f.x);
    if (pe < pf)
        swap(pe, pf);
    double alpha = min(2 * PI - (pe - pf), pe - pf);
    return PI - alpha;
}

