struct point
{
    double x, y;
    int index;
    point(double a, double b, int ind)
    {
        x = a, y = b;
        index = ind;
    }
};
class convex_hull
{
public:
    int n;
    int ccw (point &a, point &b, point &c)
    {
        double v = (b.x - a.x) * (c.y - a.y) - (b.y-a.y)*(c.x-a.x);
        if (v > 0) return 1;
        if (!v) return 0;
        return -1;
    }
    static bool compy (point &a, point &b)
    {
        if (a.y == b.y) return a.x < b.x;
        return a.y < b.y;
    }
    static bool compang(point &a, point &b)
    {
        if (a.y*b.x == a.x*b.y) return compy(a, b);
        return a.y*b.x < a.x*b.y;
    }
    vector <point> pt;
    vector <point> convex;
    void graham_scan()
    {
        sort(all(pt),compy);
        point down = pt[0];
        for (int i = 0; i<n; i++)
        {
            pt[i].x -= down.x;
            pt[i].y -= down.y;
        }
        sort(all(pt), compang);
        convex.push_back(pt[0]);
        convex.push_back(pt[1]);
        for (int i = 2; i<n; i++)
        {
            while(convex.size() > 1)
            {
                point tp = convex.back();
                convex.pop_back();
                point tptp = convex.back();
                if (ccw(tptp,tp,pt[i]) > 0)
                {
                    convex.push_back(tp);
                    break;
                }
            }
            convex.push_back(pt[i]);
        }
    }
};

