typedef long long ll;
typedef long double ld; // or double

const ld pi = acos(-1);
const ld eps = ld(1e-9);

bool eq(ld a, ld b) {
    return fabs(a - b) < eps;
}

bool ls(ld a, ld b) {
    return !eq(a, b) && a < b;
}

bool lsoreq(ld a, ld b) {
    return eq(a, b) || ls(a, b);
}

ld sqr(ld x) {
    return x * x;
}

ld mysqrt(ld x) {
    if (x < 0 && !eq(x, 0)) {
        throw "sqrt(-1)";
    }
    if (x < 0) {
        return 0;
    }
    return sqrt(x);
}

ld myasin(ld x) {
	if (eq(x, 1)) {
		return asin(1);
	} else if (eq(x, -1)) {
		return asin(-1);
	} else if (ls(x, -1) || ls(1, x)) {
		throw "asin";
	} else {
		return asin(x);
	}
}

ld myacos(ld x) {
	if (eq(x, 1)) {
		return acos(1);
	} else if (eq(x, -1)) {
		return acos(-1);
	} else if (ls(x, -1) || ls(1, x)) {
		throw "acos";
	} else {
		return acos(x);
	}
}

struct Vector {
    ld x, y;
    Vector() : x(0), y(0) {}
    Vector(ld a, ld b) : x(a), y(b) {}
    void scan() { cin >> x >> y; }
    void print() { cout << x << " " << y; }
    ld operator*(const Vector &v) const {
        return x * v.x + y * v.y;
    }
    ld operator%(const Vector &v) const {
        return x * v.y - y * v.x;
    }
    Vector operator-(const Vector &v) const {
        return Vector(x - v.x, y - v.y);
    }
    Vector operator+(const Vector &v) const {
        return Vector(x + v.x, y + v.y);
    }
    Vector operator*(const ld &k) const {
        return Vector(x * k, y * k);
    }
    Vector operator/(const ld &k) const {
        return Vector(x / k, y / k);
    }
    bool operator==(const Vector &v) const {
        return eq(x, v.x) && eq(y, v.y);
    }
    ld len() {
        return mysqrt((*this) * (*this));
    }
	ld getAngle(Vector &p) const {
        Vector v = *this;
        return atan2(v % p, v * p);
    }
};

pair <Vector, Vector> getLine3(ld a, ld b, ld c) {
    if (a == 0) {
        return {Vector(0, -c / b), Vector(1, -c / b)};
    } else if (b == 0) {
        return {Vector(-c / a, 0), Vector(-c / a, 1)};
    } else {
        return {Vector(0, -c / b), Vector(1, -(a + c) / b)};
    }
}

struct Line {
    Vector A, B;
    Line() : A(), B() {}
    Line(Vector A1, Vector B1) : A(A1), B(B1) {}
    Line(ld a, ld b, ld c) : A(getLine3(a, b, c).first), B(getLine3(a, b, c).second) {}
    void scan() { A.scan(); B.scan(); }
    void scan3() { ld a, b, c; cin >> a >> b >> c; A = getLine3(a, b, c).first; B = getLine3(a, b, c).second; };
};

struct Circle {
    Vector O;
    ld r;
    Circle() : O(), r(0) {}
    Circle(Vector v, ld a) : O(v), r(a) {}
    void scan() { O.scan(); cin >> r; }
    bool operator==(const Circle &w) const {
        return eq(r, w.r) && O == w.O;
    }
};

struct Segment {
    Vector A, B;
    Segment() : A(), B() {}
    Segment(Vector A1, Vector B1) : A(A1), B(B1) {}
    void scan() { A.scan(); B.scan(); }
    bool operator==(const Segment &v) {
        return (A == v.A && B == v.B) || (A == v.B && B == v.A);
    }
};

bool isz(const Vector &v) {
    return eq(v.x, 0) && eq(v.y, 0);
}

Vector norm(Vector v, ld k = 1) {
    if (eq(v.len(), 0)) {
        if (eq(k, 0)) {
            return Vector();
        } else {
            throw "zero-size Vector /*from norm*/";
        }
    }
    return v * (k / v.len());
}

bool isOnLine(const Vector &v, const Line &a) {
    return eq((a.A - v) % (a.B - v), 0);
}

bool isOnSegment(const Vector &C, const Segment &a) {
    Line b(a.A, a.B);
    return isOnLine(C, b) && lsoreq((a.A - C) * (a.B - C), 0);
}

ld dtp(const Vector &v, const Vector &u) {
    ld a = v.x - u.x;
    ld b = v.y - u.y;
    return mysqrt(sqr(a) + sqr(b));
}

ld dtl(const Vector &v, const Line &a) {
    ld d = dtp(a.A, a.B);
    if (eq(d, 0)) {
        throw "A == B";
    }
    ld s = (v - a.A) % (v - a.B);
    return fabs(s) / d;
}

Vector getH(const Vector &C, const Line &a) {
    Vector v = a.B - a.A;
    Vector u = C - a.A;
    ld k = (v * u) / v.len();
    v = norm(v, k);
    return a.A + v;
}

ld dts(const Vector &C, const Segment &a) {
	if (isOnSegment(C, a)) {
		return 0;
	} 
	Line b(a.A, a.B); 
	Vector H = getH(C, b);
	if (isOnSegment(H, a)) {
		return dtp(C, H);
	} else {
		return min(dtp(C, a.A), dtp(C, a.B));
	} 
}

pair <int, Vector> intersection(const Line &a, const Line &b) {
    Vector v = a.B - a.A;
    ld s1 = (b.A - a.A) % (b.B - a.A);
    ld s2 = (b.B - a.B) % (b.A - a.B);
    ld s = s1 + s2;
    if (eq(s, 0)) {
        if (!isOnLine(a.A, b)) {
            return {0, Vector()};
        } else {
            return {2, Vector()};
        }
    }
    v = v / s;
    v = v * s1;
    return {1, a.A + v};
}

pair <int, Vector> intersection(const Line &a, const Segment &b) {
    Line c(b.A, b.B);
    pair <int, Vector> res = intersection(a, c);
    if (res.first == 0) {
        return {0, Vector()};
    } else if (res.first == 2) {
        return {2, Vector()};
    }
    if (isOnSegment(res.second, b)) {
        return {1, res.second};
    } else {
        return {0, Vector()};
    }
}

