pair <int, Vector> intersection(Segment &a, Segment &b) {
    Line ca(a.A, a.B), cb(b.A, b.B);
    pair <int, Vector> res = intersection(ca, b);
    if (res.first == 0) {
        return {0, Vector()};
    } else if (res.first == 2) {
        if (a == b) {
            return {2, Vector()};
        }
        if (a.A == b.B) {
            if (!isOnSegment(a.B, b) && !isOnSegment(b.A, a)) {
                return {1, a.A};
            }
        }
        if (a.A == b.A) {
            if (!isOnSegment(a.B, b) && !isOnSegment(b.B, a)) {
                return {1, a.A};
            }
        }
        if (a.B == b.A) {
            if (!isOnSegment(a.A, b) && !isOnSegment(b.B, a)) {
                return {1, a.B};
            }
        }
        if (a.B == b.B) {
            if (!isOnSegment(a.A, b) && !isOnSegment(b.A, a)) {
                return {1, a.B};
            }
        }
        if (isOnSegment(a.A, b) || isOnSegment(a.B, b) || isOnSegment(b.A, a) || isOnSegment(b.B, a)) {
            return {2, Vector()};
        } else {
            return {0, Vector()};
        }
    }
    if (isOnSegment(res.second, a) && isOnSegment(res.second, b)) {
        return {1, res.second};
    } else {
        return {0, Vector()};
    }
}

pair <int, vector <Vector> > intersection(const Circle &w, const Line &a) {
    ld h = dtl(w.O, a);
    if (w.r < h) {
        return {0, {}};
    }
    Vector H = getH(w.O, a);
    Vector v = a.B - a.A;
    ld k = mysqrt(sqr(w.r) - sqr(h));
    v = norm(v, k);
    if (isz(v)) {
        return {1, {H + v}};
    } else {
        return {2, {H + v, H - v}};
    }
}

Vector rot90p(const Vector &v) {
    return Vector(-v.y, v.x);
}

Vector rots(const Vector &v, ld sina, ld cosa) {
    Vector u = rot90p(v);
    Vector w = v * cosa + u * sina;
    return w;
}

Vector rotp(const Vector &v, ld al) {
    return rots(v, sin(al), cos(al));
}

pair <int, vector <Vector> > intersection(const Circle &w1, const Circle &w2) {
    ld d = dtp(w1.O, w2.O);
    if (w1.r + w2.r < d || d < fabs(w1.r - w2.r)) {
        return {0, {}};
    }
    if (w1 == w2) {
        return {3, {}};
    }
    ld a = (sqr(w1.r) - sqr(w2.r) + sqr(d)) / ld(2) / d;
    ld h = mysqrt(sqr(w1.r) - sqr(a));
    Vector v = w2.O - w1.O;
    Vector u = rot90p(v);
    v = norm(v, a);
    u = norm(u, h);
    Vector H = w1.O + v;
    if (isz(u)) {
        return {1, {H + u}};
    } else {
        return {2, {H + u, H - u}};
    }
}

pair <int, vector <Vector> > tangent(const Vector &A, const Circle &w)  {
    Vector v = w.O - A;
    ld d = v.len();
    if (d < w.r) {
        return {0, {}};
    }
    ld al = myasin(w.r / d);
    ld L = mysqrt(sqr(d) - sqr(w.r));
    v = norm(v, L);
    Vector N = A + rotp(v, al);
    Vector M = A + rotp(v, -al);
    if (eq(w.r, d)) {
        return {1, {N}};
    } else {
        return {2, {N, M}};
    }
}

