const double pi = acos(-1.0);

double norm(double x){
	while(x < -pi)x += 2 * pi;
	while(x > pi)x -= 2 * pi;
	return x;
}
double len(double s,double e){
	e -= s;
	while(e < 0)e += 2 * pi;
	while(e > 2 * pi)e -= 2 * pi;
	return e;
}
bool in(double x,double s,double e){
	if(s < e)return s <= x && x <= e;
	return x >= s || x <= e;
}
bool chk(double x,double y){
	x -= y;
	return sgn(x) == 0 || sgn(x - 2 * pi) == 0 || sgn(x + 2 * pi) == 0;
}
bool inter(double&s1,double&e1,double s2,double e2){
	if((!in(s1, s2, e2) || chk(s1, e2)) && (!in(e1, s2, e2)||chk(e1,s2)))return false;
	double newS, newE;
	if(in(s2, s1, e1))
		newS = s2;
	else
		newS = s1;
	if(in(e2, s1, e1))
		newE = e2;
	else
		newE = e1;
	s1 = newS;
	e1 = newE;
	return true;
}

