		for(int j=1;j<=N;j++)if(i!=j){

			if( x[i] == x[j] ){
				if( y[i] < y[j] ){

					v.push_back({180.0,0.0});
				}
				else{
					v.push_back({0.0,180.0});
				}
				continue;
			}
			if( y[i] == y[j] ){
				if( x[i] < x[j] ){
					v.push_back({90.0,270.0});
				}
				else{
					v.push_back({270.0,90.0});
				}
				continue;
			}

			double pi = acos(-1);
			double ang = atan2(y[i]-y[j],x[i]-x[j]);
			ang = ang / (2*pi) * 360.0;
			double st = ang - 90;
			if( st > 360.0 ) st -= 360.0; if( st < 0 ) st += 360.0;
			double en = ang + 90;
			if( en > 360.0 ) en -= 360.0; if( en < 0 ) en += 360.0;


			v.push_back({st,en});
		}	

		double start = v[0].Fi, finish = v[0].Se;
		bool ok = true;
		for(auto e : v){

			if( start <= finish ){

				if( e.Fi <= e.Se ){
					if( e.Fi > finish ) ok = false;
					if( e.Se < start ) ok = false;
					start = max(start, e.Fi);
					finish = min(finish, e.Se);
				}
				else{
					if( e.Se < start ) ok = false;
					else if( e.Se >= start && e.Se <= finish ){
						finish = e.Se;
					}
					else{}
				}

			}
			else{
				if( e.Fi > e.Se ){
					if( e.Fi < start && e.Se <= finish ) finish = e.Se;
					else if( e.Fi < start && e.Se > finish ) {}
					else if( e.Fi >= start ) start = e.Fi;
				}
				else{
					if( e.Fi <= finish ) start = e.Fi;
					else if( e.Fi > finish && e.Se < start ) ok = false;
					else if( e.Fi > finish && e.Se >= start ) finish = e.Se;
				}

			}
		//	printf("%f %f : %f %f\n",e.Fi,e.Se,start,finish);
		}
		//printf("%f %f\n",start,finish);

		if( !ok ) printf("0.0\n");
		else if( start > finish ){
			printf("%.10f\n", (finish + 360.0 - start)/360.0);
		}
		else{
			printf("%.10f\n",(finish-start)/360.0);
		}

	}

}

