	return a.first*b.second - a.second*b.first;
}
double dot(P a, P b) {
	return a.first*b.first + a.second*b.second;
}
double abs(P a) {
	return sqrt(pow(a.first, 2) + pow(a.second, 2));
}
P operator-(const P a, const P b) {
