using Real = double;
using Point = complex< Real >;
constexpr Real EPS = 1e-10;
constexpr Real pi = 3.141592653589793238462643383279;
istream &operator>>(istream &is, Point &p) {
  Real a, b;
  is >> a >> b;
  p = Point(a, b);
  return is;
}
ostream &operator<<(ostream &os, Point &p) {
  return os << real(p) << " " << imag(p);
}
inline bool eq(Real a, Real b) { return fabs(b - a) < EPS; }

Point operator*(const Point &p, const Real &d) {
  return Point(real(p) * d, imag(p) * d);
}

namespace std {
  bool operator<(const Point &a, const Point &b) {
    return a.real() != b.real() ? a.real() < b.real() : a.imag() < b.imag();
  }
}

Real cross(const Point &a, const Point &b) {
  return real(a) * imag(b) - imag(a) * real(b);
}
Real dot(const Point &a, const Point &b) {
  return real(a) * real(b) + imag(a) * imag(b);
}

int ccw(const Point &a, Point b, Point c) {
  b = b - a, c = c - a;
  if(cross(b, c) > EPS) return +1;  // 反時計回り
  if(cross(b, c) < -EPS) return -1; // 時計回り
  if(dot(b, c) < 0) return +2;      // c-a-bの順で一直線
  if(norm(b) < norm(c)) return -2;  // a-b-cの順で一直線
  return 0;                         // a-c-bの順で一直線
}

// a-b-c の角度のうち小さい方を返す
Real get_angle(const Point &a, const Point &b, const Point &c) {
  const Point v(b - a), w(c - b);
  Real alpha = atan2(v.imag(), v.real()), beta = atan2(w.imag(), w.real());
  if(alpha > beta) swap(alpha, beta);
  Real theta = (beta - alpha);
  return min(theta, 2 * acos(-1) - theta);
}

//　反時計回りである自己交差のない多角形のclass
using Polygon = vector<Point>;

// 凸包
Polygon convex_hull(vector<Point> ps){
 int n = (int) ps.size(), k = 0;
  if(n <= 2) return ps;
  sort(ps.begin(), ps.end());
  vector< Point > ch(2 * n);
  // 反時計周りに凸包を構築していく
  for(int i = 0; i < n; ch[k++] = ps[i++]) {
    // 条件分岐内はwhile(k >= 2 && ccw(ch[k-2],ch[k-1],ps[i]) != 1)と等価
    while(k >= 2 && cross(ch[k - 1] - ch[k - 2], ps[i] - ch[k - 1]) < EPS) --k;
  }
  for(int i = n - 2, t = k + 1; i >= 0; ch[k++] = ps[i--]) {
    while(k >= t && cross(ch[k - 1] - ch[k - 2], ps[i] - ch[k - 1]) < EPS) --k;
  }
  ch.resize(k - 1);
  return ch;
}

// 多角形の面積
Real area(const Polygon &p) {
  Real A = 0;
  for(int i = 0; i < (int)p.size(); ++i) {
    A += cross(p[i], p[(i + 1) % p.size()]);
  }
  return A * 0.5;
}

void solve(){
  ini(N);
  vector<Point> a(N); in(a);
  auto conv = convex_hull(a);
  vector<double> ans( sz(conv) , 0);
  trc(conv);
  // conv[i]の答えを求める
  int M = sz(conv);
  rep(i , M ){
    // conv[i]の角度
    auto angle = get_angle( conv[(i-1+M)%M] , conv[i] , conv[(i+1)%M] );
    trc(angle * 180 / pi);
    ans[i] = angle / 2 / pi;
  }
  trc(ans);

  vector<double> bns(N , 0.0);
  rep(i , N) rep(j , M){
    if(a[i] == conv[j]) bns[i] = ans[j];
  }
  each(x , bns) out(x);
}

