bool cw(const Point &o, const Point &a, const Point &b) {
    Vector oa(o, a), ob(o, b);
    return oa * ob <= 0;
}

void convexHull(vector<Point> &a) {
    sort(a.begin(), a.end(), [&](const Point &p, const Point &q) {
        return p.x < q.x || (p.x == q.x && p.y < q.y);
    });
    vector<Point> res;
    vector<Point> c;
    for (int j = 0; j < 2; ++j) {
        c.clear();
        c.push_back(a[0]);
        for (int i = 1; i < a.size(); ++i) {
            if (i == a.size() - 1 || cw(a[0], a[i], a.back())) {
                while (c.size() > 1 && cw(c[c.size() - 2], a[i], c[c.size() - 1])) {
                    c.pop_back();
                }
                c.push_back(a[i]);
            }
            a[i].y = -a[i].y;
        }
        a[0].y = -a[0].y;
        if (!j) {
            for (auto cc : c) {
                res.push_back(cc);
            }
        }
    }
    for (int i = c.size() - 2; i > 0; --i) {
        c[i].y = -c[i].y;
        res.push_back(c[i]);
    }
    a = res;
}

