	PT(const PT &p) : x(p.x), y(p.y) {}
	PT operator + (const PT &p)	const { return PT(x+p.x, y+p.y); }
	PT operator - (const PT &p)	const { return PT(x-p.x, y-p.y); }
	PT operator * (double c)	const { return PT(x*c, y*c); }
	PT operator / (double c)	const { return PT(x/c, y/c); }
};
double dot(PT p, PT q)		{ return p.x*q.x + p.y*q.y; }
double dist2(PT p, PT q)	{ return dot(p-q, p-q); }
double cross(PT p, PT q)	{ return p.x*q.y - p.y*q.x; }

typedef long long LL; 
typedef long double LD;
int n;

vector<PT> A,hull;
PT lower_left;

bool sorter(const PT &p, const PT &q)
{
	double cpq = cross(p-lower_left, q-lower_left);
	if(abs(cpq) < eps)
		return dist2(p, lower_left) < dist2(q, lower_left);
	return (cpq > 0);
}


void convex_hull(vector<PT>& A,vector<PT> & hull)
{
	for(int i=1;i<n;i++)
	{
		if(A[i].y<A[0].y||(A[i].y==A[0].y&&A[i].x<A[0].x))
		{
			swap(A[i],A[0]);
		}
	}//bottom-most point and among those points the one which is leftest
	lower_left=A[0];
	sort(A.begin(),A.end(),sorter);//arranged in clockwise order

	hull.push_back(A[0]);
	hull.push_back(A[1]);

	int hull_sz=2;

	for(int i=2;i<A.size();i++)
	{
		while(hull_sz>1&&cross(hull[hull_sz-1]-hull[hull_sz-2],A[i]-hull[hull_sz-1])<=0)
		{
			hull.pop_back();
			hull_sz--;
		}
		hull.push_back(A[i]);
		hull_sz++;
	}
}

