ld ans[MAXN], area[MAXN];
int cnt[MAXN];

ll getdist(ll x0, ll y0, ll x1, ll y1) {
	return (x0 - x1) * (x0 - x1) + (y0 - y1) * (y0 - y1);
}

inline ll getrand() {
	if ( (rand() & 1) == 0) {
		return ( (ll) rand() * rand() + rand() ) % MOD;	
	} else {
		return - (( (ll) rand() * rand() + rand() ) % MOD);
	}
}

//
#define X first
#define Y second
typedef pair<ll, ll> pt;
vector<pt> p[MAXN];

bool cmp (pt a, pt b) {
	return ( (a.X < b.X) || (a.X == b.X && a.Y < b.Y) );
}

bool cw (pt a, pt b, pt c) {
	return a.X*(b.Y-c.Y)+b.X*(c.Y-a.Y)+c.X*(a.Y-b.Y) < 0;
}

bool ccw (pt a, pt b, pt c) {
	return a.X*(b.Y-c.Y)+b.X*(c.Y-a.Y)+c.X*(a.Y-b.Y) > 0;
}

ld S[MAXN];

ld getarea(vector<pt> &v) {
	ld res = 0;
	fi(0, sz(v) - 1) {
		pt pr = v[ (i - 1 + sz(v)) % sz(v) ];
		res += (v[i].X - pr.X) * (v[i].Y + pr.Y);
	}
	return abs(res) / 2;
}

void convex_hull (vector<pt> & a) {
	if (a.size() == 1)  return;
	sort (a.begin(), a.end(), &cmp);
	pt p1 = a[0],  p2 = a.back();
	vector<pt> up, down;
	up.push_back (p1);
	down.push_back (p1);
	for (size_t i=1; i<a.size(); ++i) {
		if (i==a.size()-1 || cw (p1, a[i], p2)) {
			while (up.size()>=2 && !cw (up[up.size()-2], up[up.size()-1], a[i]))
				up.pop_back();
			up.push_back (a[i]);
		}
		if (i==a.size()-1 || ccw (p1, a[i], p2)) {
			while (down.size()>=2 && !ccw (down[down.size()-2], down[down.size()-1], a[i]))
				down.pop_back();
			down.push_back (a[i]);
		}
	}
	a.clear();
	for (size_t i=0; i<up.size(); ++i)
		a.push_back (up[i]);
	for (size_t i=down.size()-2; i>0; --i)
		a.push_back (down[i]);
}	
//

void solve(){
	int q = Q;
	while(q--) {
		ll x = getrand();
		ll y = getrand();
		ll d = INF;
		int b = -1;
		fi(1, n) {
			ll d0 = getdist(::x[i], ::y[i], x, y);
			if (d0 < d) {
				d = d0;
				b = i;
			}						
		}
		//++cnt[b];
		p[b].pb(mp(x, y));
	}							
	fi(1, n) {
		convex_hull(p[i]);
	}
	ld sum = 0;
	fi(1, n) {
		S[i] = getarea(p[i]);
		sum += S[i];
	}
	fi(1, n) {
		ans[i] = S[i] / sum;
	}
	/*fi(1, n) {
		ans[i] = (ld) cnt[i] / Q;
	}*/
}

