struct Point {
    int x,y,id;

    Point() {}

    Point(int _x,int _y, int id = -1) : x(_x),y(_y),id(id) {}

    Point operator + (const Point &rhs) const {
        return Point(x + rhs.x,y + rhs.y);
    }

    Point operator - (const Point &rhs) const {
        return Point(x - rhs.x,y - rhs.y);
    }

    bool operator == (const Point &rhs) const {
        return x == rhs.x && y == rhs.y;
    }

    bool operator < (const Point &rhs) const {
        if (x != rhs.x) return x < rhs.x;
        return y < rhs.y;
    }
};

using LL = long long;

LL det(const Point &a,const Point &b) {
    return a.x * 1LL * b.y - a.y * 1LL * b.x;
}

LL det(const Point &a, const Point &b, const Point &c) {
    return det(b - a, c - a);
}

LL dot(const Point &a,const Point &b) {
    return a.x * 1LL * b.x + a.y * 1LL * b.y;
}

const int kN = 100 + 5;
int n;
Point pts[kN];
double result[kN];

int main()
{
    scanf("%d", &n);
    for (int i = 0; i < n; ++ i) {
        scanf("%d%d", &pts[i].x, &pts[i].y);
        pts[i].id = i;
    }
    std::sort(pts, pts + n);
    for (int i = 0; i + 1 < n; ++ i)
        assert(pts[i].x != pts[i + 1].x || pts[i].y != pts[i + 1].y);
    std::vector<Point> stack;
    for (int i = 0; i < n; ++ i) {
        while (stack.size() > 1 && det(stack[stack.size() - 2], stack.back(), pts[i]) >= 0) stack.pop_back();
        stack.push_back(pts[i]);
    }
    int m = stack.size();
    for (int i = n - 2; i >= 0; -- i) {
        while (stack.size() > m && stack.size() > 1 && det(stack[stack.size() - 2], stack.back(), pts[i]) >= 0) stack.pop_back();
        stack.push_back(pts[i]);
    }
    stack.pop_back();

    if (stack.size() == 2) {
        result[stack.back().id] = .5;
        result[stack[0].id] = .5;
    }
    else {
        for (int i = 0; i < stack.size(); ++ i) {
            const Point &cur = stack[i];
            Point left = stack[(i + stack.size() - 1) % stack.size()] - cur;
            Point right = cur - stack[(i + 1) % stack.size()];
            result[cur.id] = .5 * acos(1. * dot(left, right) / sqrt(dot(left, left)) / sqrt(dot(right, right))) / pi;
            // result[cur.id] = (pi - acos(1. * dot(left, right) / sqrt(dot(left, left)) / sqrt(dot(right, right)))) / (2 * pi);
        }
    }
    for (int i = 0; i < n; ++ i)
        printf("%.10f\n", result[i]);
}

