		Real res = 0;
		rep(i, n * 2 - 3) { chmax(res, angles[i + 1] - angles[i]); }
		ans[i] = (res - pi) / pi / 2;
		chmax(ans[i], (Real)0);
	}
	vout(ans, 1);
}

