const long double EPS = 1e-14;
const long double pi = atan(1.0) * 4.0;
long double ABS(long double x)
{
	return x < 0.0 ? -x : x;
}
long double arccos(long double x)
{
	if(x < -1.0 + EPS) return pi;
	if(x > 1.0 - EPS) return 0.0;
	return acos(x);
}
struct cmplxU{
	long double dx, dy;
	cmplxU()
	{
		dx = dy = 0.0;
	}
	cmplxU(long double x, long double y, const void* t)
	{
		dx = x / sqrt(x * x + y * y);
		dy = y / sqrt(x * x + y * y);
	}
	cmplxU(long double d)
	{
		dx = cos(d);
		dy = sin(d);
	}
	cmplxU(long double x,long double y)
	{
		dx = x; dy = y;
	}
	bool MTH() const
	{
		return dy < 0.0;
	}
	cmplxU invimag() const
	{
		return cmplxU(dx, -dy);
	}
	cmplxU operator*(const cmplxU& oth) const
	{
		return cmplxU(dx * oth.dx - dy * oth.dy, dx * oth.dy + dy * oth.dx);
	}
	cmplxU operator/(const cmplxU& oth) const
	{
		return operator*(oth.invimag());
	}
	bool operator <(const cmplxU& oth) const
	{
		if(MTH() != oth.MTH()) return oth.MTH();
		return MTH() ^ (dx > oth.dx);
	}
	bool operator ==(const cmplxU& oth) const
	{
		return dx == oth.dx && dy == oth.dy;
	}
	long double direc() const
	{
		long double res = arccos(dx);
		if(ABS(sin(res) - dy) >= EPS * 10000) res = 2 * pi - res;
		return res;
	}
};
int x[105], y[105];
long double ans[105];
vector<cmplxU> poi;
bool check(int i0, int i1, cmplxU dir)
{
	return (x[i0] - x[i1]) * dir.dx + (y[i0] - y[i1]) * dir.dy > 0.0;
}
int main()
{
	int n;
	cin >> n;
	rep(i, n) cin >> x[i] >> y[i];
	rep(i, n) rep(j, i) if(i != j) {
		poi.push_back(cmplxU(y[i] - y[j], x[j] - x[i], NULL));
		poi.push_back(cmplxU(y[j] - y[i], x[i] - x[j], NULL));
	}
	sort(poi.begin(), poi.end());
	for(int i = 1; i < poi.size(); i ++)
	if(ABS(poi[i].dx - poi[i - 1].dx) < EPS) poi[i] = poi[i - 1];
	poi.resize(unique(poi.begin(), poi.end()) - poi.begin());
	poi.push_back(poi[0]);
	for(int i = 1; i < poi.size(); i ++) {
		long double dif = (poi[i] / poi[i - 1]).direc();
		cmplxU md = poi[i] / cmplxU(dif / 2);
		int cur = 0;
		for(int j = 1; j < n; j ++)
		if(check(j, cur, md)) cur = j;
		ans[cur] += dif;
	}
	cout << fixed << setprecision(10);
	rep(i, n) cout << ans[i] / (2 * pi) << '\n';
	return 0;
}

