ostream & operator<<(ostream &os, Point p) { os << "(" << p.X << ", " << p.Y << ")"; return os; }

// +1 : ccw
// -1 : cw
// +2 : a--b--c
// -2 : b--c--a
//  0 : b--a--c
int ccw(Point a, Point b, Point c) {
  b -= a; c -= a;
  if(cross(b, c) > EPS) return +1;
  if(cross(b, c) < -EPS) return -1;
  if(dot(b, c) < 0) return 0;
  if(norm(b) < norm(c)) return +2;
  return -2;
}

double arg(Point a, Point b) {
  return acos(dot(a, b) / norm(a) / norm(b));
}
/// ---}}} ///

struct GrahamScan {
  vector<Point> points;
  VI idxs;
  VI hull;

  void add(Point p) {
    points.PB(p);
  }

  int operator[](int i) {
    return hull[i];
  }

  void scan() {
    int n = points.size();
    idxs.resize(n);

    iota(ALL(idxs), 0);
    sort(ALL(idxs), [&](int a, int b) {
        return make_pair(points[a].X, points[a].Y) <
        make_pair(points[b].X, points[b].Y);
        });

    sort(begin(idxs) + 1, end(idxs), [&](int a, int b) {
        Point p1 = points[a] - points[idxs[0]];
        Point p2 = points[b] - points[idxs[0]];
        // p1.y / p1.x < p2.y / p2.x
        double ev = p1.Y * p2.X - p2.Y * p1.X;
        return abs(ev) < EPS ? norm(p1) < norm(p2) : ev < 0;
        });

    hull.PB(idxs[0]);
    FORI(i, 1, n) {
      int ii = i%n;
      while(hull.size() > 2 &&
          ccw(
            points[hull[hull.size()-2]],
            points[hull[hull.size()-1]],
            points[idxs[ii]]
            ) != +1) hull.pop_back();
      hull.PB(idxs[ii]);
    }

    hull.pop_back();
  }
};

double ans[100];
int main() {
  int n=ini;
  GrahamScan ecasdqina;
  REP(i, n) {
    int x=ini, y=ini;
    ecasdqina.add(Point(x, y));
  }
  ecasdqina.scan();
  VI &hull = ecasdqina.hull;
  vector<Point> &points = ecasdqina.points;
  int m = hull.size();
  EACH(i, hull) {
    ans[hull[i]] = arg(
        - (points[hull[(i+m-1)%m]] - points[hull[i]]),
        points[hull[(i+1)%m]] - points[hull[i]]
        ) / 2.0 / PI;
  }

  cout << setprecision(6);
  REP(i, n) cout << ans[i] << endl;
}

