const ld EPS = 1e-9;

struct pt
{
    ld x, y;
    int clr;

    ld len()
    {
        return sqrt(x * x + y * y);
    }
};

ld operator*(pt a, pt b)
{
    return a.x * b.y - a.y * b.x;
}

int sgn(ld x)
{
    if(x < -EPS)
    {
        return -1;
    }
    if(x > EPS)
    {
        return 1;
    }
    return 0;
}


pt vec(pt a, pt b)
{
    return{b.x - a.x, b.y - a.y};
}

vector<pt> conv(vector<pt> a)
{
    pt mn = *min_element(all(a), [](const pt &a, const pt &b)
    {
        if(a.x != b.x)
        {
            return a.x < b.x;
        }
        return a.y < b.y;
    });

    sort(all(a), [=](const pt &a, const pt &b)
    {
        if(sgn(vec(mn, a) * vec(mn, b)) == 0)
        {
            return vec(mn, a).len() < vec(mn, b).len();
        }
        return sgn(vec(mn, a) * vec(mn, b)) == 1;
    });

    vector<pt> ans;

    for(pt i : a)
    {
        while(sz(ans) >= 2 && sgn(vec(ans[sz(ans) - 2], ans.back()) * vec(ans.back(), i)) != 1)
        {
            ans.pop_back();
        }
        ans.push_back(i);
    }

    return ans;
}

inline void _main_function()
{
    int n;
    cin >> n;
    int nn = n;

    vector<pt> a(n);
    vector<ld> ans(n);
    for(int i = 0; i < n; ++i)
    {
        cin >> a[i].x >> a[i].y;
        a[i].clr = i;
    }

    a = conv(a);
    n = sz(a);

    assert(n > 1);

    for(int i = 0; i < n; ++i)
    {
        int pr = (i - 1 + n) % n;
        int nx = (i + 1) % n;
        ld a1 = atan2(-a[pr].x + a[i].x, a[pr].y - a[i].y);
        ld a2 = atan2(a[nx].x - a[i].x, -a[nx].y + a[i].y);
        ld diff = min(abs(a2 - a1), 2 * PI - abs(a2 - a1));
        ans[a[i].clr] = diff / (2 * PI);
    }

    for(int i = 0; i < nn; ++i)
    {
        cout << ans[i] << endl;
    }
}

