using namespace std;
using Int = int_fast64_t;

using point = pair<Int, Int>;
using vect = point;
using indexed_point = pair<point, Int>;
using polygon = vector<indexed_point>;

vect operator-(point p, point q){
	return vect(p.first - q.first, p.second - q.second);
}

vect operator-(indexed_point p, indexed_point q){
	return vect(p.first.first - q.first.first, p.first.second - q.first.second);
}

Int cross(vect v, vect w){
	return v.first * w.second - v.second * w.first;
}

Int dot(vect v, vect w){
	return v.first * w.first + v.second * w.second;
}

double norm(vect v){
	return sqrt(v.first * v.first + v.second * v.second);
}

double deg(vect v, vect w){
	double theta = dot(v, w) / norm(v) / norm(w);
	if(theta > 1.0 - 1e-10) return 0.0;
	return acos(theta);
}

polygon convex_hull(vector<indexed_point> v, int n){
	sort(v.begin(), v.end());
	polygon res;
	for(int i=0; i<n; ++i){
		while(res.size() >= 2 && cross(res.back() - res[res.size()-2], v[i] - res[res.size()-2]) < 0) res.pop_back();
		res.push_back(v[i]);
	}
	for(int i=n-2; i>=0; --i){
		while(res.size() >= 2 && cross(res.back() - res[res.size()-2], v[i] - res[res.size()-2]) < 0) res.pop_back();
		res.push_back(v[i]);
	}
	return res;
}

int main(){
	cin.tie(0);
	ios::sync_with_stdio(false);
	Int n; cin >> n;
	vector<Int> x(n), y(n);
	for(Int i=0; i<n; ++i) cin >> x[i] >> y[i];
	vector<indexed_point> v;
	for(Int i=0; i<n; ++i)
		v.push_back(indexed_point(point(x[i], y[i]), i));
	polygon ch = convex_hull(v, n);
	for(size_t i=0; i<ch.size(); ++i)
		cout << i << " " << ch[i].first.first << " " << ch[i].first.second << "\n";
	vector<double> ans(n);
	for(size_t i=0; i+1<ch.size(); ++i){
		int idx = ch[i].second;
		point pr = (i == 0 ? ch[ch.size()-2].first : ch[i-1].first);
		point p = ch[i].first;
		point ne = ch[i+1].first;
		ans[idx] = (acos(-1) - deg(pr-p, ne-p)) / (2 * acos(-1));
	}
	for(int i=0; i<n; ++i)
		cout << fixed << setprecision(10) << ans[i] << "\n";
}

