struct Point{
    long double x,y;
    int idx;
    Point(){}
    Point(long double x,long double y):x(x),y(y){}
    long double add(long double a,long double b){
        if(abs(a+b)<eps*(abs(a)+abs(b)))return 0;
        return a+b;
    }
    Point operator+(const Point& p){return Point(add(x,p.x),add(y,p.y));}
    Point operator-(const Point& p){return Point(add(x,-p.x),add(y,-p.y));}
    Point operator*(const long double& d){return Point(x*d,y*d);}
    bool operator<(const Point& p) const{return abs(x-p.x)>eps?(x<p.x-eps):(y<p.y-eps);}
    bool operator==(const Point& p) const{return abs(x-p.x)<eps&&abs(y-p.y)<eps;}
    long double dot(const Point& p){return add(x*p.x,y*p.y);}
    long double det(const Point& p){return add(x*p.y,-y*p.x);}
};
using P=Point;
struct ConvexHull{
    vector<P> pts,in;
    int n;
    ConvexHull(vector<P> in):in(in){
        pts.resize(2*in.size());
        build();
    } 
    void build(){
        sort(in.begin(),in.end());
        int k=0;
        for(int i=0;i<in.size();i++){
            while(k>1&&(pts[k-1]-pts[k-2]).det(in[i]-pts[k-1])<=0)--k;
            pts[k++]=in[i];
        }
        for(int i=in.size()-2,t=k;i>=0;i--){
            while(k>t&&(pts[k-1]-pts[k-2]).det(in[i]-pts[k-1])<=0)--k;
            pts[k++]=in[i];
        }
        pts.resize(k-1);
        n=k-1;
    }
};
