            pts.pop_back();
            vecs.pop_back();
        }
        if (!pts.empty())
            vecs.push_back(p[q[i]] - p[pts.back()]);
        pts.push_back(q[i]);
    }
    pts.pop_back();
    reverse(pts.begin(), pts.end());
    pts.pop_back();
    hull.insert(hull.end(), pts.begin(), pts.end());
    vector<double> ans(n);
    for (int i = 0; i < (int)hull.size(); ++i) {
        auto r = p[i == (int)hull.size() - 1 ? hull[0] : hull[i + 1]] - p[hull[i]], l = p[hull[i]] - p[i == 0 ? hull.back() : hull[i - 1]];
        ans[hull[i]] = acos(1.0 * dot(l, r) / sqrt(1.0 * dot(l, l) * dot(r, r))) / (2 * PI);
    }
    cout << setprecision(10) << fixed;
    for (auto i : ans)
        cout << i << "\n";
    return 0;
}

