struct P : public pair<double,double> {

    P(double x = 0, double y = 0) :pair(x,y) {  }

    double& x() { return first; }
    double& y() { return second; }
    double x() const { return first; }
    double y() const { return second; }

    inline double hypot() const { return std::hypot(first, second); }
    inline double hypot(P p) const { return std::hypot(first - p.x(), second - p.y()); }

    inline double dot(P p) const { return first*p.x() + second*p.y(); }

    inline P operator-(P p) const { return P(first - p.x(), second - p.y()); }
};

// http://www.prefield.com/algorithm/geometry/convex_hull.html
int ccw(P a, P b, P c) {
    b.x() -= a.x();
    b.y() -= a.y();
    c.x() -= a.x();
    c.y() -= a.y();
    if (b.x()*c.y() - b.y()*c.x() > 0)   return +1;       // counter clockwise
    if (b.x()*c.y() - b.y()*c.x() < 0)   return -1;       // clockwise
    if (b.x()*c.x() + b.y()*c.y() < 0)   return +2;       // c--a--b on line
    if (b.hypot() < c.hypot()) return -2;       // a--b--c on line
    return 0;
}

