        auto v = ch[(i + 1) % ch.size()] - ch[i];
        double co = dot(u, v) / abs(u) / abs(v);
        ans[mp[ch[i]]] = acos(-co) / 2 / acos(-1);
    }
    for(int i = 0; i < n; i++) {
        printf("%.10f\n", ans[i]);
    }

}

