    using point_type = typename adapter_type::point_type;
    using coord_type = typename adapter_type::coord_type;
    using difference_type = std::pair<coord_type, coord_type>;

    static coord_type x(point_type const& p) { return adapter_type::x(p); }
    static coord_type y(point_type const& p) { return adapter_type::y(p); }

    static bool less(point_type const& p, point_type const& q) {
        return x(p)!=x(q) ? x(p)<x(q) : y(p)<y(q);
    }

    static difference_type sub(point_type const& p, point_type const& q) {
        return std::make_pair(x(q)-x(p), y(q)-y(p));
    }

    static coord_type sq_mag(difference_type const&d) {
        return d.first * d.first + d.second * d.second;
    }

    static coord_type dot(difference_type const& a, difference_type const& b) {
        return a.first * b.first + a.second * b.second;
    }

    static coord_type sq_dist(point_type const& p, point_type const& q) {
        return this_type::sq_mag(sub(p, q));
    }

    static coord_type det(difference_type const& a, difference_type const& b) {
        return a.first * b.second - a.second * b.first;
    }

    static coord_type det_of_broken_segment(point_type const& p, point_type const& q, point_type const& r) {
        return this_type::det(this_type::sub(q, p), this_type::sub(r, p));
