    }

    static vec<point_type> convex_hull(vec<point_type> v) {
        if (v.size() <= 1u) return v;
        // assert(std::is_sorted(v.begin(), v.end(), [](auto&&p, auto&&q) { less(p, q); }));

        auto lower = lower_convex_hull(v);
        std::reverse(v.begin(), v.end());
        auto hull = lower_convex_hull(v);

        lower.pop_back();
        hull.pop_back();
        hull.insert(hull.end(), lower.begin(), lower.end());
        return hull;
    }
};

