typedef long long llint;

struct Pt {
  int x, y, i;
};

int ccw(const Pt& a, const Pt& b, const Pt& c) {
  llint w = 0;
  w += llint(a.x) * (b.y - c.y);
  w += llint(b.x) * (c.y - a.y);
  w += llint(c.x) * (a.y - b.y);
  return w < 0 ? -1 : w > 0;
}

llint dist(const Pt& a, const Pt& b) {
  llint dx = a.x - b.x;
  llint dy = a.y - b.y;
  return dx * dx + dy * dy;
}

vector<Pt> hull(vector<Pt>& v) {
  int first = 0;
  REP(i, (int)v.size()) {
    if (make_pair(v[i].x, v[i].y) < make_pair(v[first].x, v[first].y)) first = i;
  }

  swap(v[0], v[first]);
  sort(v.begin() + 1, v.end(), [&] (const Pt& a, const Pt& b) {
      int c = ccw(v[0], a, b);
      if (c == 0) return dist(v[0], a) < dist(v[0], b);
      return c > 0;
    });

  vector<Pt> hull;
  for (auto& p: v) {
    while (hull.size() >= 2 && ccw(hull[(int)hull.size()-2], hull.back(), p) <= 0) hull.pop_back();
    hull.push_back(p);
  }
  return hull;
}

int main(void) {
  int n;
  scanf("%d", &n);
  vector<Pt> v(n);
  REP(i, n) {
    scanf("%d %d", &v[i].x, &v[i].y);
    v[i].i = i;
  }

  v = hull(v);

  vector<double> angles(n, 0);
  REP(i, (int)v.size()) {
    int p = i == 0 ? (int)v.size() - 1 : i - 1;
    int q = (i + 1) % (int)v.size();
    llint x1 = v[i].x - v[p].x;
    llint y1 = v[i].y - v[p].y;
    llint x2 = v[q].x - v[i].x;
    llint y2 = v[q].y - v[i].y;
    double cs = (x1 * x2 + y1 * y2) / sqrt(x1*x1 + y1*y1) /  sqrt(x2*x2 + y2*y2) + 1e-12;
    double angle = acos(cs);
    if (angle < 0) angle += acos(-1);
    angles[v[i].i] = angle;
  }

  double total = accumulate(angles.begin(), angles.end(), 0.0);
  REP(i, n) printf("%.12lf\n", angles[i] / total);
  return 0;
}

