        hull.push_back( pct[ st.top() ] );
        st.pop();
    }
    reverse( hull.begin(), hull.end() );

    st.push( (I64)pct.size() - 1 );
    st.push( (I64)pct.size() - 2 );
    for( I64 i = (I64)pct.size() - 3;  i >= 0;  --i ) {
        I64 ind2 = st.top();
        st.pop();
        I64 ind1 = st.top();
