typedef pair<pair<long double, long double>, int> point;

bool cw(const point &a, const point &b, const point &c) {
    return (b.F.F - a.F.F) * (c.F.S - a.F.S) - (b.F.S - a.F.S) * (c.F.F - a.F.F) < 0.0;
}

vector<point> convexHull(vector<point> p) {
    int n = p.size();
    if (n <= 1)
        return p;
    int k = 0;
    sort(p.begin(), p.end());
    vector<point> q(n * 2);
    for (int i = 0; i < n; q[k++] = p[i++])
        for (; k >= 2 && !cw(q[k - 2], q[k - 1], p[i]); --k)
            ;
    for (int i = n - 2, t = k; i >= 0; q[k++] = p[i--])
        for (; k > t && !cw(q[k - 2], q[k - 1], p[i]); --k)
            ;
    q.resize(k - 1 - (q[0] == q[1]));
    return q;
}

const int N = 105;
long double P[N];

long double dist(point a, point b)
{
    long double D = ((long double)(a.F.F - b.F.F))*((long double)(a.F.F - b.F.F));
    D += ((long double)(a.F.S - b.F.S))*((long double)(a.F.S - b.F.S));
    D = sqrt(D);
    return D;
}

long double calc(point a, point b, point c)
{
    long double D1 = dist(a, b);
    long double D2 = dist(b, c);
    long double D3 = dist(a, c);

    long double angle;
    angle = acos((D1*D1 + D2*D2 - D3*D3)/(2.0*D1*D2));

    return angle;
}

