int main() {
    constexpr double PI = 3.14159265358;

    ll N;
    cin >> N;
    vector<double> x(N), y(N);
    for (ll i = 0; i < N; i++) {
        cin >> x[i] >> y[i];
    }

    //iからjへの角度を求める
    //真上が0度で時計回りに計測
    //iから見てi以外の点が全てある180度の中に収まっていたら凸包の頂点になる
    vector<vector<double>> angle(N, vector<double>(N));

    for (ll i = 0; i < N; i++) {
        for (ll j = 0; j < N; j++) {
            if (j == i) {
                continue;
            }

            if (x[j] == x[i]) {
                if (y[j] > y[i]) {
                    angle[i][j] = 0;
                } else {
                    angle[i][j] = 2 * PI;
                }
            } else if (x[j] > x[i]) {
                double diff_x = x[j] - x[i];
                double diff_y = y[j] - y[i];
                angle[i][j] = acos(diff_y / sqrt(pow(diff_x, 2) + pow(diff_y, 2)));
            } else {
                double diff_x = x[j] - x[i];
                double diff_y = y[j] - y[i];
                double a = acos(diff_y / sqrt(pow(diff_x, 2) + pow(diff_y, 2)));
                angle[i][j] = 2 * PI - a;
            }
        }
    }

    vector<double> min_angles(N);
    for (ll i = 0; i < N; i++) {
        double min_angle = INT_MAX;
        for (ll j = 0; j < N; j++) {
            if (j == i) {
                continue;
            }
            //jを一番端としてここから全部の点を含めるのに何度必要かを計算
            double tmp = 0;
            for (ll k = 0; k < N; k++) {
                if (k == i || k == j) {
                    continue;
                }
                if (angle[i][k] < angle[i][j]) {
                    angle[i][k] += 2 * PI;
                }
                tmp = max(tmp, angle[i][k] - angle[i][j]);
            }
            min_angle = min(min_angle, tmp);
        }

        min_angles[i] = min_angle;
    }

    for (ll i = 0; i < N; i++) {
        printf("%.10f\n", max(PI - min_angles[i], 0.0) / (2 * PI));
    }
}

