    cin >> p.x >> p.y;
  }
  sort(ps.begin(), ps.end());
  vector<point> qs = convex_hull(ps);
  int k = qs.size();
  vector<double> ans(n, 0.0);
  REP(i,0,k) {
    int prev = (i - 1 + k) % k;
    int next = (i + 1) % k;
    PD v1 = qs[i] - qs[prev];
    PD v2 = qs[next] - qs[i];
    double t = arg(v1, v2);
    ans[qs[i].id] = t;
  }
  FOR(a,ans) {
    cout << setprecision(20) << a << endl;
  }
  return 0;
}

