P n_vector(P a){
  //aベクトルに垂直な単位ベクトル
  long double l = abs(a);
  return (long double)1000.0*a*P(0.0,1.0)/l;
}

int main(){
  int N;
  cin >> N;
  vector<P> V(N);
  long double x, y;
  for(int i = 0; i < N; ++i){
    cin >> x >> y;
    V[i] = P(x,y);
  }
  vector< vector<long double> > A(N);
  long double pi = acos(-1.0);
  for(int i = 0; i < N; ++i){
    for(int j = 0; j < N; ++j){
      if(i == j) continue;
      long double theta = arg(n_vector((long double)100.0*(V[j]-V[i])));
      //if(theta < 0) theta += 2*pi;
      A[i].push_back(theta);
    }
  }
  for(int i = 0; i < N; ++i){
    long double m = A[i][0], M = A[i][0] + pi;
    for(int j = 0; j < A[i].size(); ++j){
      long double m_ = A[i][j], M_ = A[i][j] + pi;
      if(M_ > pi && M_ - 2*pi > m){
        M_ -= 2*pi;
        m_ -= 2*pi;
      }if(m_ + 2*pi < M){
        m_ += 2*pi;
        M_ += 2*pi;
      }
      m = max(m,m_);
      M = min(M,M_);
    }
    printf("%.20Lf\n",max((long double)0.0,(M-m)/pi/2.0));
  }

  return 0;
}

