struct Dat {
    int x,y,t;
    inline long long operator % (const Dat &A) const {return 1LL*x*A.y-1LL*y*A.x;}
    inline double dis() {return sqrt(1LL*x*x+1LL*y*y);}
    inline bool operator < (const Dat &A) const {return x==A.x?y<A.y:x<A.x;}
    inline Dat operator - (const Dat &A) const {return (Dat){x-A.x,y-A.y};}
    inline Dat operator + (const Dat &A) const {return (Dat){x+A.x,y+A.y};}
