    for(int i=1;i<=n;i++) {
	while(tp>1&&(g[i]-v[tp])%(v[tp]-v[tp-1])>=0) --tp;
	v[++tp]=g[i];
    }
    for(int i=n,j=tp;i;i--) {
	while(j<tp&&(g[i]-v[tp])%(v[tp]-v[tp-1])>=0) --tp;
