vector<cpx> convexhull(vector<cpx> ps) {
    int k = 0, n = ps.size();
    sort(ps.begin(), ps.end(), [&](cpx a, cpx b) {
        return real(a) != real(b) ? real(a) < real(b) : imag(a) < imag(b);
    });
    vector<cpx> res(2 * n);
    for (int i = 0; i < n; i++) {
        while (k > 1 && imag(conj(res[k - 1] - res[k - 2]) * (ps[i] - res[k - 1])) <= 0)
            k--;
        res[k++] = ps[i];
    }
    for (int i = n - 2, t = k; i >= 0; i--) {
        while (k > t && imag(conj(res[k - 1] - res[k - 2]) * (ps[i] - res[k - 1])) <= 0)
            k--;
        res[k++] = ps[i];
    }
    res.resize(k - 1);
    return res;
}

