    for (int i = 0; i < ch; i++) {
        DD save = amp(check[(i+1)%ch].first - check[i].first) - amp(check[i].first - check[(i-1+ch)%ch].first);
        ans[check[i].second] = (save + (save < 0 ? PI * 2.0 : 0.0) ) / (PI * 2.0);
    }

    for (int i = 0; i < n; i++) cout << fixed << setprecision(10) << ans[i] << endl;
    return 0;
}

