bool cmp(point a, point b) {
  if (a.x < b.x) return 1;
  else if (a.x == b.x) return a.y < b.y;
  return 0;
}

bool cw(point a, point b, point c) {
  return a.x * (b.y - c.y) + b.x * (c.y - a.y) + c.x * (a.y - b.y) < 0;
}

bool ccw(point a, point b, point c) {
  return a.x * (b.y - c.y) + b.x * (c.y - a.y) + c.x * (a.y - b.y) > 0;
}

double ang(point a, point o, point b) {
  a.x -= o.x;
  b.x -= o.x;
  a.y -= o.y;
  b.y -= o.y;
  return abs(atan2(a.x * b.y - b.x * a.y, a.x * b.x + a.y * b.y));
}

void convexhull(vector < point > &a) {
  sort(a.begin(), a.end(), &cmp);
  point p1 = a[0];
  point p2 = a.back();
  vector < point > up, down;
  up.pb(p1);
  down.pb(p1);
  for (int i = 1; i < a.size(); i++) {
    if (i == a.size() - 1 || cw(p1, a[i], p2)) {
      while (up.size() > 1 && !cw(up[up.size() - 2], up.back(), a[i])) {
        up.pop_back();
      }
      up.pb(a[i]);
    }
    if (i == a.size() - 1 || ccw(p1, a[i], p2)) {
      while(down.size() > 1 && !ccw(down[down.size() - 2], down.back(), a[i])) {
        down.pop_back();
      }
      down.pb(a[i]);
    }
  }
  a.clear();
  for (auto to : up) {
    a.pb(to);
  }
  for (int i = down.size() - 2; i > 0; i--) {
    a.pb(down[i]);
  }
}

