struct rg{
	double l,r;
};
bool cmp(rg x,rg y){
	return x.l<y.l;
}
double solve(int x){
	int i;
	vector<rg> v;
	rep(i,n) if(i!=x){
		rg t;
		t.l=atan2(a[i].x-a[x].x,a[x].y-a[i].y);
		t.r=t.l+pi;
		if(t.r>2*pi) t.r-=2*pi;
		v.push_back(t);
	}
	vector<double> all;
	for(i=0;i<v.size();i++){
		all.push_back(v[i].l);
		all.push_back(v[i].r);
	}
	sort(all.begin(),all.end());
	all.resize(unique(all.begin(),all.end())-all.begin());
	memset(cnt,0,sizeof(cnt));
	for(i=0;i<v.size();i++){
		int tl=upper_bound(all.begin(),all.end(),v[i].l)-all.begin();
		int tr=upper_bound(all.begin(),all.end(),v[i].r)-all.begin();
		cnt[tl]++;cnt[tr]--;
		if(tl>tr) cnt[0]++;
	}
	rep(i,all.size()) cnt[i]+=cnt[i-1];
	double ans=0;
	rep(i,all.size()) if(cnt[i]==v.size()){
		if(i!=all.size()) ans+=all[i]-all[i-1];
		else ans+=all[0]+2*pi-all[i-1];
	}
	return ans/(2*pi);
}
