struct PT {
  ll x, y;
  int id;
  PT() {}
  PT(ll x_, ll y_): x(x_), y(y_), id(-1) {}
  ll len2() const {
    return x * x + y * y;
  }
  double len() const {
    return sqrt(len2());
  }
  PT operator - (const PT &b) const {
    return PT(x - b.x, y - b.y);
  }
  ll operator * (const PT &b) const {
    return x * b.x + y * b.y;
  }
  ll operator % (const PT &b) const {
    return x * b.y - y * b.x;
  }
  bool operator < (const PT &b) const {
    return tie(x, y) < tie(b.x, b.y);
  }
};

const int MAXN = 123;
PT in[MAXN];
double ans[MAXN];

int main() {
  int N;
  scanf("%d", &N);
  assert(N > 70 && N < 90);
  for (int i = 0; i < N; i++) {
    int x, y;
    scanf("%d%d", &x, &y);
    in[i].x = x;
    in[i].y = y;
    in[i].id = i;
  }
  sort(in, in + N);
  vector<PT> st, st2;;
  for (int i = 0; i < N; i++) {
    while (SZ(st) >= 2 && (st[SZ(st) - 1] - st[SZ(st) - 2]) % (in[i] - st[SZ(st) - 1]) <= 0)
      st.pop_back();
    st.PB(in[i]);
  }
  for (int i = N - 1; i >= 0; i--) {
    while (SZ(st2) >= 2 && (st2[SZ(st2) - 1] - st2[SZ(st2) - 2]) % (in[i] - st2[SZ(st2) - 1]) <= 0)
      st2.pop_back();
    st2.PB(in[i]);
  }
  st.pop_back();
  for (const auto &p : st2)
    st.PB(p);
  for (int i = 0; i < N; i++)
    ans[i] = 0;
  debug("SZ %d\n", SZ(st));
  st.PB(st[1]);
  debug("!\n");
  for (int i = 1; i < SZ(st) - 1; i++) {
    debug("i = %d\n", i);
    PT A = st[i - 1] - st[i];
    PT B = st[i + 1] - st[i];
    debug("%f %f\n", A.len(), B.len());
    double tmp = A * B / (A.len() * B.len());
    debug("! %d %f\n", i, tmp);
    double ang = PI - acos(tmp);
    ans[st[i].id] = ang / (2 * PI);
    ans[st[i].id] = 0.5;
