/* 要最適化 */
Polygon Convex_hull(const std::vector<Vector2DInt>& points_arg) {
	std::vector<Vector2DInt> points(points_arg);
	sort(points.begin(), points.end());

	std::vector<Vector2DInt> vertices;
	Polygon ret;

	/* 下側部分を生成 */
	for (auto it = points.begin(); it != points.end(); ++it) {
		while (vertices.size() >= 2
			&& CCW(vertices[vertices.size() - 2], vertices[vertices.size() - 1], *it) != CCWEnum::Counterclockwise) {
			vertices.pop_back();
		}
		vertices.push_back(*it);
	}
	for (auto it = vertices.begin(); it != vertices.end() - 1; ++it) {
		ret.Add(*it);
	}
	vertices.clear();

	/* 上側部分を生成 */
	for (auto rit = points.rbegin(); rit != points.rend(); ++rit) {
		while (vertices.size() >= 2
			&& CCW(vertices[vertices.size() - 2], vertices[vertices.size() - 1], *rit) != CCWEnum::Counterclockwise) {
			vertices.pop_back();
		}
		vertices.push_back(*rit);
	}
	for (auto it = vertices.begin(); it != vertices.end() - 1; ++it) {
		ret.Add(*it);
	}

	return ret;
}
