  if(abs(((v1.dot(v2))/pow(v1.dot(v1), 0.5)/pow(v2.dot(v2), 0.5))-1) < EPS*10) return PI;
  return PI - acos((v1.dot(v2))/pow(v1.dot(v1), 0.5)/pow(v2.dot(v2), 0.5));
}

