			double rad1 = atan2(p1.imag(), p1.real());
			while(rad1 < 0) rad1 += 2 * PI;
			double rad2 = atan2(p2.imag(), p2.real());
			while(rad2 < 0) rad2 += 2 * PI;

			double dx = p1.imag() - p2.imag(), dy = p1.real() - p2.real();
			double rad = atan2(-dx, dy);
			while(rad < 0) rad += 2 * PI;
			if(rad > PI) rad -= PI;
			if(rad1 < rad2){
				ls.push_back({ rad, i, j });
				ls.push_back({ rad + PI, j, i });
			}
			else{
				ls.push_back({ rad, j, i });
				ls.push_back({ rad + PI, i, j });
			}
		}
	}
	sort(ls.begin(), ls.end());

	double r = 1e-15;
	int cnt[100] = { 0 };
	for(auto l : ls){
		if(l.rad > PI) continue;
		cnt[l.A]++;
	}

	for(auto l : ls){
		{
			int idx = max_element(cnt, cnt + N) - cnt;
			double diff = abs(r - l.rad);
			sum[idx] += diff;
		}

		cnt[l.A]--;
		cnt[l.B]++;
		r = l.rad;
	}

	memset(cnt, 0, sizeof cnt);
	for(auto l : ls){
		if(l.rad < PI) continue;
		cnt[l.B]++;
	}
	{
		int idx = max_element(cnt, cnt + N) - cnt;
		double diff = 2 * PI - r;
		sum[idx] += diff;
	}

	for(int i = 0; i < N; i++){
		cout << fixed << setprecision(15) << sum[i] / (2 * PI) << endl;
	}
}

