const int N=105;
int n;
struct Point{
	int x,y,id;
	double ans;
	Point(){}
	Point(int _x,int _y){
		x=_x,y=_y;
	}
	friend Point operator + (Point a,Point b){
		return Point(a.x+b.x,a.y+b.y);
	}
	friend Point operator - (Point a,Point b){
		return Point(a.x-b.x,a.y-b.y);
	}
}p[N];
LL cross(Point a,Point b){
	return (LL)a.x*b.y-(LL)a.y*b.x;
}
LL cross(Point a,Point b,Point c){
	return cross(b-a,c-a);
}
LL Dot(Point a,Point b){
	return (LL)a.x*b.x+(LL)a.y*b.y;
}
LL Dis(Point a,Point b){
	return Dot(a-b,a-b);
}
bool cmp(Point a,Point b){
	LL d=cross(p[1],a,b);
	return d?d>0:Dis(p[1],a)<Dis(p[1],b);
}
bool cmpid(Point a,Point b){
	return a.id<b.id;
}
int st[N],top=0;
double ang[N];
int main(){
	n=read();
	For(i,1,n)
		p[i].x=read(),p[i].y=read(),p[i].id=i,p[i].ans=0;
	For(i,1,n)
		if (p[i].y<p[1].y)
			swap(p[i],p[1]);
		else if (p[i].y==p[1].y&&p[i].x<p[1].x)
			swap(p[i],p[1]);
	sort(p+2,p+n+1,cmp);
	st[++top]=1,st[++top]=2;
	For(i,3,n){
		while (top>1&&cross(p[st[top-1]],p[st[top]],p[i])<=0)
			top--;
		st[++top]=i;
	}
//	For(i,1,n)
//		printf("(%d,%d)\n",p[i].x,p[i].y);
//	outarr(st,1,top);
	st[top+1]=st[1];
	double pi=acos(-1.0);
	For(i,1,top){
		ang[i]=atan((double)(p[st[i+1]].y-p[st[i]].y)
					/(p[st[i+1]].x-p[st[i]].x));
		if (p[st[i+1]].x<=p[st[i]].x)
			ang[i]+=pi;
	}
	ang[0]=ang[top];
	For(i,1,top){
		double tmp=ang[i]-ang[i-1];
		if (tmp<0)
			tmp+=pi*2;
		p[st[i]].ans=tmp;
	}
	sort(p+1,p+n+1,cmpid);
	For(i,1,n)
		printf("%.7lf\n",p[i].ans/(pi*2));
	return 0;
}

