		if (o == 0)
			return abs(lhs.fi.fi-a[0].fi.fi) + abs(lhs.fi.se-a[0].fi.se) < abs(rhs.fi.fi-a[0].fi.fi) + abs(rhs.fi.se-a[0].fi.se);
		return o > 0 ? true : false;
	});
	hull[0] = a[0], hull[1] = a[1];
	for (int i = 2; i < n; i++) {
		while (m >= 2 && ccw(hull[m-1].fi-hull[m-2].fi,a[i].fi-hull[m-2].fi) < 0)
			m--;
		hull[m++] = a[i];
	}
	while (m >= 2 && ccw(hull[m-1].fi-hull[m-2].fi,hull[0].fi-hull[m-2].fi) < 0)
		m--;
	for (int i = 0; i < m; i++) {
		int k = (i-1+m)%m;
		int j = (i+1)%m;
		double alp = scal(hull[k].fi-hull[i].fi,hull[j].fi-hull[i].fi) / (hyp(hull[k].fi-hull[i].fi)*hyp(hull[j].fi-hull[i].fi));
		ans[hull[i].se] = (pi - acos(alp)) / (2. * pi);
		if (abs(ans[hull[i].se]) < eps)
			ans[hull[i].se] = 0;
	}
	for (int i = 0; i < n; i++)
		printf("%.10f\n", ans[i]);
	return 0;
}

