long long id[MAXN],hul[MAXN],top;
bool used[MAXN];
bool cmp(long long a,long long b)
{return fcmp(P[a].x,P[b].x)==-1||(fcmp(P[a].x,P[b].x)==0&&fcmp(P[a].y,P[b].y)==-1);}

void ConvexHull()
{
	for(long long i=1;i<=n;i++)
		id[i]=i;
	sort(id+1,id+n+1,cmp);
	hul[1]=id[1],hul[2]=id[2],top=2;
	used[id[1]]=used[id[2]]=true;
	for(long long i=3;i<=n;i++)
	{
		while(top>1&&fcmp(Vector(P[hul[top-1]],P[hul[top]])^Vector(P[hul[top]],P[id[i]]),0)==-1)
			used[hul[top]]=false,top--;
		used[id[i]]=true;
		hul[++top]=id[i];
	}
	for(long long i=n-1;i>0;i--)
	{
		//if(used[id[i]]&&i!=1)continue;
		while(top>1&&fcmp(Vector(P[hul[top-1]],P[hul[top]])^Vector(P[hul[top]],P[id[i]]),0)==-1)
			used[hul[top]]=false,top--;
		used[id[i]]=true;
		hul[++top]=id[i];
	}
	top--;
}

double probability(long long i)
{
	long long l=hul[(i-1-1+top)%top+1];
	long long r=hul[(i-1+1)%top+1];
	i=hul[i];
	double ang=angle(Vector(P[i],P[r]),Vector(P[i],P[l]));
	return (PI-ang)/(2.0*PI);
}

