    for (int i = 0; i < n; i++) {
        cin >> xy[i].first.first >> xy[i].first.second;
        xy[i].second = i;
    }

    V< P< P<ll, ll>, int > > cht = andrew_cht(xy);
    int sz = cht.size();
    V<double> ans(n, 0.0);
    for (int i = 0; i < sz; i++) {
        P< P< ll, ll >, int > prev = cht[(i - 1 + sz) % sz], post = cht[(i + 1) % sz];
        ll prevx = prev.first.first - cht[i].first.first, prevy = prev.first.second - cht[i].first.second,
               postx = post.first.first - cht[i].first.first, posty = post.first.second - cht[i].first.second;
        double cosss = ((double)prevx * postx + prevy * posty) / (sqrt((double)prevx * prevx + prevy * prevy) * sqrt((double)postx * postx + posty * posty));
        double theta = acos(cosss);
        ans[cht[i].second] = (PI - theta) / (2.0 * PI);
    }

    for (int i = 0; i < n; i++) cout << fixed << setprecision(12) << ans[i] << '\n';
    return 0;
}

