double EPS = 1e-8;

double add(double a, double b) {
    if (abs(a + b) < EPS * (abs(a) + abs(b))) return 0;
    return a + b;
}

struct P {
    int id = -1;
    double x, y;
    P() {}
    P(double x, double y): x(x), y(y) {}
    P(double x, double y, int id): x(x), y(y), id(id) {}
    P operator + (P p) {
        return P(add(x, p.x), add(y, p.y));
    }
    P operator - (P p) {
        return P(add(x, -p.x), add(y, -p.y));
    }
    P operator * (double d) {
        return P(x * d, y * d);
    }
    double dot(P p) {
        return add(x * p.x, y*p.y);
    }
    double det(P p) {
        return add(x * p.y, -y * p.x);
    }
    double dist(P p) {
        return abs(sqrt((p.x - x) * (p.x - x) + (p.y - y) * (p.y - y)));
    }
    double norm() {
        return sqrt(x*x + y*y);
    }
};

bool cmp_x(P p, P q) {
    if (p.x != q.x) return p.x < q.x;
    return p.y < q.y;
}

vector<P> convex_hull(vector<P> ps, int n) {
    sort(ps.begin(), ps.end(), cmp_x);
    int k = 0;
    vector<P> qs(n * 2);

    for (int i = 0; i < n; i++) {
        while (k > 1 && (qs[k-1] - qs[k-2]).det(ps[i] - qs[k-1]) <= 0) k--;
        qs[k++] = ps[i];
    }

    for (int i = n - 2, t = k; i >= 0; i--) {
        while (k > t && (qs[k-1] - qs[k-2]).det(ps[i] - qs[k-1]) <= 0) k--;
        qs[k++] = ps[i];
    }
    qs.resize(k-1);
    return qs;
}

bool solve() {
    int n; cin >> n;
    vector<P> holes(n);
    rep (i, n) {
        double x, y; cin >> x >> y;
        holes[i] = P(x, y, i);
    }

    double pi = acos(-1.0);
    vector<double> ans(n, 0);
    vector<P> cand = convex_hull(holes, n);
    rep (i, cand.size()) {
        int prev = (i + cand.size() - 1) % cand.size(), nxt = (i + 1) % cand.size();
        P p1 = cand[i] - cand[prev], p2 = cand[nxt] - cand[i];
        double ang = p1.dot(p2) / (p1.norm() * p2.norm());
        ans[cand[i].id] = acos(ang) / (2 * pi);
    }

    cout << fixed << setprecision(10);
    rep (i, n) {
        cout << ans[i] << endl;
    }
}

signed main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    solve();
}

