long long xor64(long long range) {
    static unsigned long long x = 1145141919810ULL;
    x ^= x << 13;
    x ^= x >> 7;
    return (x ^= x << 17) % range;
}

struct timer {
    unsigned long long begin_cycle;
    double cycle_per_sec = 2.8e9;
    unsigned long long get_cycle() {
        unsigned low, high;
        __asm__ volatile("rdtsc":"=a"(low), "=d"(high));
        return ((unsigned long long) low) | ((unsigned long long) high << 32);
    }
    double get_time() { return (get_cycle() - begin_cycle) / cycle_per_sec; }
    void init() { begin_cycle = get_cycle(); }
} timer;

int N;
int x[110], y[110];
double ans[110];
bool non_zero[110];

void simulated_annealing() {
    double T = 1.95;
    double start_temp = 1e-3;
    double end_temp = 1e-10;
    int it = 0;
    double pre_sum = 0;
    double time;
    while ((time = timer.get_time()) < T) {
        it++;
        double temp = start_temp + (end_temp - start_temp) * time / T;
        int target = xor64(N);
        double new_sum = pre_sum;
        if (non_zero[target]) { new_sum -= ans[target]; }
        else { new_sum += ans[target]; }
        double prob = exp((abs(pre_sum - 1) - abs(new_sum - 1)) / temp);
        if (prob < (double) xor64(10000000) / 10000000) {
        } else {
            non_zero[target] = !non_zero[target];
            pre_sum = new_sum;
        }
    }
}

signed main() {
    timer.init();
    cin >> N;
    rep(i, N) { cin >> x[i] >> y[i]; }
    if (N == 2) {
        cout << 0.5 << endl << 0.5 << endl;
        return 0;
    }
    rep(i, N) {
        double max_theta = 0;
        rep(j, N) {
            if (i == j) { continue; }
            int vx0 = x[j] - x[i], vy0 = y[j] - y[i];
            rep(k, N) {
                if (i == k) { continue; }
                int vx1 = x[k] - x[i], vy1 = y[k] - y[i];
                int prod = vx0 * vx1 + vy0 * vy1;
                double cos = prod / sqrt((vx0 * vx0 + vy0 * vy0) * (vx1 * vx1 + vy1 * vy1));
                chmax(max_theta, acos(cos));
            }
        }
        ans[i] = (pi - max_theta) / (2 * pi);
    }
    simulated_annealing();
    rep(i, N) {
        if (non_zero[i]) { cout << ans[i] << endl; }
        else { cout << 0.0 << endl; }
    }
}

