vi Convex_Hull(){
    int n=x.size();
    if(n >= 3){
        vi ch;
        for(int i=0;i<n;i++){
            while(ch.size()>=2&&cross(ch.back(),ch[ch.size()-2])<cross(i,ch.back()))ch.pop_back();
            ch.eb(i);
        }
        for(int i=n-2,t=ch.size()+1;i>=0;i--){
            while(ch.size()>=t&&cross(ch.back(),ch[ch.size()-2])<cross(i,ch.back()))ch.pop_back();
            ch.eb(i);
        }
        ch.pop_back();
        return ch;
    }
    vi res;
    rep(i,2)res.pb(i);
    return res;
}
