struct V{
	int x, y, nu;
};
int n;
vector<V>a;
vector<V>con;
bool z;
bool compare(const V& v1, const V& v2){
	if (v1.x != v2.x)return v1.x < v2.x;
	else return v1.y < v2.y;
}

void convex_make(void){
	sort(a.begin(), a.end(), compare);
	int k = 0;
	V co[N];
	f(i, n){
		z = true;
		while (k > 1 && z){
			if ((co[k - 1].x - co[k - 2].x)*(a[i].y - co[k - 1].y) >= (co[k - 1].y - co[k - 2].y)*(a[i].x - co[k - 1].x))k--;
			else z = false;
		}
		co[k] = a[i];
		k++;
	}
	int t = k;
	for (int i = n - 2; i >= 0; i--){
		z = true;
		while (k > t&&z){
			if ((co[k - 1].x - co[k - 2].x)*(a[i].y - co[k - 1].y) >= (co[k - 1].y - co[k - 2].y)*(a[i].x - co[k - 1].x))k--;
			else z = false;
		}
		co[k] = a[i];
		k++;
	}
	con.clear();
	f(i, k - 1)con.push_back(co[i]);
	return;
}

int main(void){
	int x, y,cosi;
	double ans[N];
	f(i, N)ans[i] = 0.000000000;
	long double  da, db, dc;
	scanf("%d", &n);
	f(i, n){
		scanf("%d %d", &x, &y);
		a.push_back({ x, y ,i});
	}
	convex_make();
	cosi = con.size();
	da = sqrt((((con[0].x) - (con[cosi - 1].x))*((con[0].x) - (con[cosi - 1].x))) + (((con[0].y) - (con[cosi - 1].y))*((con[0].y) - (con[cosi - 1].y))));
	db = sqrt((((con[0].x) - (con[1].x))*((con[0].x) - (con[1].x))) + (((con[0].y) - (con[1].y))*((con[0].y) - (con[1].y))));
	dc = sqrt((((con[cosi - 1].x) - (con[1].x))*((con[cosi - 1].x) - (con[1].x))) + (((con[cosi - 1].y) - (con[1].y))*((con[cosi - 1].y) - (con[1].y))));
	ans[con[0].nu] = (acos(-((da*da) + (db*db) - (dc*dc)) / (2 * da*db))) / (2*PI);
	for (int i = 1;i < (cosi - 1); i++){
		da = sqrt((((con[i].x) - (con[i - 1].x))*((con[i].x) - (con[i - 1].x))) + (((con[i].y) - (con[i - 1].y))*((con[i].y) - (con[i - 1].y))));
		db = sqrt((((con[i].x) - (con[i + 1].x))*((con[i].x) - (con[i + 1].x))) + (((con[i].y) - (con[i + 1].y))*((con[i].y) - (con[i + 1].y))));
		dc = sqrt((((con[i-1].x) - (con[i + 1].x))*((con[i-1].x) - (con[i + 1].x))) + (((con[i-1].y) - (con[i + 1].y))*((con[i-1].y) - (con[i + 1].y))));
		ans[con[i].nu] = (acos(-((da*da) + (db*db) - (dc*dc)) / (2 * da*db)))/(2*PI);
	}
	cosi = con.size();
	da = sqrt((((con[0].x) - (con[cosi - 1].x))*((con[0].x) - (con[cosi - 1].x))) + (((con[0].y) - (con[cosi - 1].y))*((con[0].y) - (con[cosi - 1].y))));
	db = sqrt((((con[cosi - 2].x) - (con[cosi - 1].x))*((con[cosi - 2].x) - (con[cosi - 1].x))) + (((con[cosi - 2].y) - (con[cosi - 1].y))*((con[cosi - 2].y) - (con[cosi - 1].y))));
	dc = sqrt((((con[cosi - 2].x) - (con[0].x))*((con[cosi - 2].x) - (con[0].x))) + (((con[cosi - 2].y) - (con[0].y))*((con[cosi - 2].y) - (con[0].y))));
	ans[con[cosi-1].nu] = (acos(-((da*da) + (db*db) - (dc*dc)) / (2 * da*db))) / (2*PI);

	f(i,n)printf("%f\n", ans[i]);

	return 0;
}

