  for (int i = 0; i < size; i ++) {
    int j = (i + 1) % size;

    vector_t e(pts[hull[j]] - pts[hull[i]]), perp(e.y, - e.x);

    perps.push_back(perp);
  }

  double c[111] = {0};

  for (int i = 0; i < size; i ++) {
    int j = (i - 1 + size) % size;

    double t = acos(perps[i] * perps[j] / (perps[i].length() * perps[j].length()));

    c[hull[i]] = t / M_PI / 2;
  }

  for (int i = 0; i < N; i ++)
    std::cout << c[i] << std::endl;

  return 0;
}

