    for (int i = (s + 1) % n; i != s; i = (i + 1) % n) {
      double tmp = fmod(arg(holes[s], holes[i]) - theta + 4 * M_PI, 2 * M_PI);
      if (tmp < m) {
        i_m = i;
        m = tmp;
      }
    }
    if (arg(holes[s], holes[i_m]) - arg(holes[s], holes[0]) < eps) break;
    theta = arg(holes[s], holes[i_m]);
    s = i_m;
    v.push_back(holes[s].i);
  }
  double res[n]; fill(res, res + n, 0.0);
  sort(holes, holes + n, [](point a, point b) { return a.i < b.i; });
  for (int i = 0; i < v.size(); i++) {
    res[v[i]] = fmod(arg(holes[v[i]], holes[v[(i + 1) % v.size()]]) - arg(holes[v[(i + v.size() - 1) % v.size()]], holes[v[i]]) + 8 * M_PI, 2 * M_PI) / (2 * M_PI);
  }
  for (int i = 0; i < n; i++) printf("%.20f\n", res[i]);
  return 0;
}

