	return (a-p[1])*(b-p[1])>0;
}

void graham()
{
	for(int i=1;i<=n;i++)
		if(p[i]<p[1])std::swap(p[i],p[1]);
    std::sort(p+2,p+n+1,cmp);
	q[++m]=p[1];q[++m]=p[2];
	for(int i=3;i<=n;i++)
	{
		while((q[m]-q[m-1])*(p[i]-q[m-1])<eps&&m>1)m--;
		q[++m]=p[i];
	}
}

