struct pt {
    double x, y;
    int id;
};

bool cmp(pt a, pt b) {
    return a.x < b.x || a.x == b.x && a.y < b.y;
}

bool cw(pt a, pt b, pt c) {
    return a.x * (b.y - c.y) + b.x * (c.y - a.y) + c.x * (a.y - b.y) < 0;
}

bool ccw(pt a, pt b, pt c) {
    return a.x * (b.y - c.y) + b.x * (c.y - a.y) + c.x * (a.y - b.y) > 0;
}

void convex_hull(vector<pt> &a) {
    if (a.size() == 1) return;
    sort(a.begin(), a.end(), &cmp);
    pt p1 = a[0], p2 = a.back();
    vector<pt> up, down;
    up.push_back(p1);
    down.push_back(p1);
    for (size_t i = 1; i < a.size(); ++i) {
        if (i == a.size() - 1 || cw(p1, a[i], p2)) {
            while (up.size() >= 2 && !cw(up[up.size() - 2], up[up.size() - 1], a[i]))
                up.pop_back();
            up.push_back(a[i]);
        }
        if (i == a.size() - 1 || ccw(p1, a[i], p2)) {
            while (down.size() >= 2 && !ccw(down[down.size() - 2], down[down.size() - 1], a[i]))
                down.pop_back();
            down.push_back(a[i]);
        }
    }
    a.clear();
    for (size_t i = 0; i < up.size(); ++i)
        a.push_back(up[i]);
    for (size_t i = down.size() - 2; i > 0; --i)
        a.push_back(down[i]);
}

const ld EPS = 1e-9;

ld dst(pt a, pt b) {
    return sqrt(sqr(a.x - b.x) + sqr(a.y - b.y));
}

void smain() {
    int n;
    cin >> n;
    vector<pt> a(n);
    fori (i, n) {
        int x, y;
        cin >> x >> y;
        a[i] = {(ld) x, (ld) y, i};
    }
    convex_hull(a);
    int s = a.size();
    vld ans(n, 0);
    fori (i, s) {
        int rf = (i + 1) % s;
        int lf = (i - 1 + s) % s;
        ld ax = dst(a[i], a[lf]);
        ld b = dst(a[i], a[rf]);
        ld c = dst(a[lf], a[rf]);
        ld angle = PI - acos((-sqr(c) + sqr(ax) + sqr(b)) / (2.0 * ax * b));
        ans[a[i].id] = angle / (2.0 * PI);
    }

    fori (i, n) {
        cout << ans[i] << '\n';
    }

}

