int const MAXN = 141;
ld const PI = acos(-1);

int n, x[MAXN], y[MAXN];
ld ans[MAXN];

ld norm(ld a) {
	while(a > PI * 2) {
		a -= PI * 2;
	}
	while(a < 0) {
		a += PI * 2;
	}
	return a;
}

ld getdist(ld a, ld b) {
	if (b >= a) {
		return b - a;
	}
	ld res = PI * 2 - a + b;
	return res;
}

void solve(){
	fi(0, n - 1) {
		vector<pair<ld, int>> a;
		fj(0, n - 1) {
			if (i == j) continue;
			ld ang = atan2( (ld) y[j] - y[i], (ld) x[j] - x[i] );
			ld a0 = norm(ang + PI / 2);
			ld a1 = norm(ang - PI / 2);
			a.pb(mp(a0, 1));
			a.pb(mp(a1, -1));
		}
		sort(a.begin(), a.end());
/*		for(pair<ld, int> z : a) {
			fprintf(stderr, "%.3lf %d\n", z.first, z.second);
		}
		cerr << '\n';*/
		int x, y, p = -1;
		fj(0, sz(a) - 1) {
			if (a[j].second == 1) {
				p = j;
				break;
			}
		}
		assert(p != -1);
		x = p;
		int q = 0;
		while(a[x].second == 1) {
			x = (x - 1 + sz(a)) % sz(a);
			q++;
		}
		y = (p + 1) % sz(a);
		while(a[y].second == 1) {
			q++;
			y = (y + 1) % sz(a);
		}
//		cerr << "x = " << x << " y = " << y << " q = " << q << endl << endl;
		if (q != n - 1) {
			continue;
		}
		ans[i] = getdist(a[(y - 1 + sz(a)) % sz(a)].first, a[y].first);
		ans[i] /= (PI * 2);
	}	
}

