const double pi = std::acos(-1);

int sgn(double a) { return a < -1e-8 ? -1 : a > 1e-8 ? 1 : 0; }

struct Point {
    double x, y;

    Point(double x, double y) : x(x), y(y) {}

    double abs() { return std::hypot(x, y); }
    double arg() { return std::atan2(y, x); }

    double dot(const Point &p) { return x * p.x + y * p.y; }
    double det(const Point &p) { return x * p.y - y * p.x; }
};

Point operator+(const Point &lhs, const Point &rhs) {
    return { lhs.x + rhs.x, lhs.y + rhs.y };
}

Point operator-(const Point &lhs, const Point &rhs) {
    return { lhs.x - rhs.x, lhs.y - rhs.y };
}

Point operator-(const Point &p) {
    return { -p.x, -p.y };
}

Point operator*(const Point &lhs, const Point &rhs) {
    return { lhs.x * rhs.x - lhs.y * rhs.y, lhs.x * rhs.y + lhs.y * rhs.x };
}

Point operator*(const Point &lhs, double k) {
    return { lhs.x * k, lhs.y * k };
}

Point operator/(const Point &lhs, double k) {
    return { lhs.x / k, lhs.y / k };
}

bool operator<(const Point &lhs, const Point &rhs) {
    auto s = sgn(lhs.x - rhs.x);
    return s ? s < 0 : sgn(lhs.y - rhs.y) < 0;
}

int iSP(const Point &a, const Point &b, const Point &c) {
    auto sd = sgn((b - a).det(c - a));
    return sd ? sd
        : sgn((b - a).dot(c - a)) < 0 ? -2
        : sgn((a - b).dot(c - b)) < 0 ? 2
        : 0;
}

int main() {
    int n;
    std::cin >> n;
    std::vector<std::pair<Point, int>> v;
    for (int i = 0; i < n; i++) {
        double x, y;
        std::cin >> x >> y;
        v.emplace_back(Point(x, y), i);
    }

    std::sort(v.begin(), v.end());

    std::deque<std::pair<Point, int>> ub, lb;
    for (const auto &p : v) {
        while (true) {
            int s = ub.size();
            if (s < 2) break;
            if (sgn((ub[s - 1].first - ub[s - 2].first).det(p.first - ub[s - 2].first)) > 0) break;
            ub.pop_back();
        }
        ub.push_back(p);
    }

    for (const auto &p : v) {
        while (true) {
            int s = lb.size();
            if (s < 2 || sgn((lb[s - 1].first - lb[s - 2].first).det(p.first - lb[s - 2].first)) < 0) break;
            lb.pop_back();
        }
        lb.push_back(p);
    }

    std::deque<std::pair<Point, int>> convexHull(ub.begin(), ub.end());
    convexHull.insert(convexHull.end(), lb.rbegin() + 1, lb.rend() - 1);

    std::vector<double> ret(n);
    for (int i = 0, s = convexHull.size(); i < s; i++) {
        int j = (i + 1) % s, k = (i + s - 1) % s;
        const auto p0 = convexHull[k].first, p1 = convexHull[i].first, p2 = convexHull[j].first;
        auto ang = (p0 - p1).arg() - (p2 - p1).arg();
        if (sgn(ang) < 0) ang += pi * 2;
        auto prob = (pi - ang) / (pi * 2);
        ret[convexHull[i].second] += prob;
    }

    std::cout << std::setprecision(10);

    for (auto p : ret) std::cout << p << std::endl;

    return 0;
}

