        return atan2(y, x);
    }
};

void convex(vector<pt> &a) {
    int n = a.size();
    sort(a.begin(), a.end());
    if (n <= 2) return;
    pt p1 = a[0], p2 = a[n - 1];
    vector<pt> up, down;
    for (int i = 0; i < n; i++) {
        if (i == 0 || i == n - 1 || ((a[i] - p1) * (p2 - p1)) > 0) {
            while (down.size() > 1 && ((a[i] - down.back()) * (down.back() - down[(int)down.size() - 2])) >= 0) {
                down.pop_back();
            }
            down.push_back(a[i]);
        }
        if (i == 0 || i == n - 1 || ((a[i] - p1) * (p2 - p1)) < 0) {
            while (up.size() > 1 && ((a[i] - up.back()) * (up.back() - up[(int)up.size() - 2])) <= 0) {
                up.pop_back();
            }
            up.push_back(a[i]);
        }
    }
    a.clear();
    for (int i = 0; i < (int)down.size(); i++) a.push_back(down[i]);
    for (int i = (int)up.size() - 2; i > 0; i--) a.push_back(up[i]);
}

