Point O;

bool cmp(const Point &A, const Point &B) {
    return (A - O) * (B - O) < 0 || ((A - O) * (B - O) == 0 && (A - O).length() < (B - O).length());
}

vector<Point> convexHull(vector<Point> &a) {
    vector<Point> convex;
    convex.push_back(O);
    for (int i = 1; i < a.size(); ++i) {
        while (convex.size() > 1 && (convex.back() - convex[convex.size() - 2]) * (a[i] - convex.back()) >= 0) {
            convex.pop_back();
        }
        convex.push_back(a[i]);
    }
    return convex;
}

