        p.ind = cnt++;
    }
    sort(pts.begin(), pts.end());
    O = pts[0];
    sort(pts.begin() + 1, pts.end(), cmp);
    auto data = convexHull(pts);
    vector<double> ans(n, 0);
    for (int i = 0; i < data.size(); ++i) {
        int next = (i + 1) % data.size();
        int prev = (i - 1 + data.size()) % data.size();
        Point A = data[prev], B = data[i], C = data[next];
        Point v = B - A;
        v = v.rotate();
        Point u = (C - B).rotate();
        ans[data[i].ind] = atan2(u * v, u % v) / 2 / PI;
