void merge(double &from,double &to,double ff,double tt)
{
    if(from>ff)
    {
        swap(from,ff);
        swap(to,tt);
    }


    if(to==-2.0*PI)
    {
        from=ff;to=tt;
        return ;
    }

    double f0,t0;


    f0=max(from,ff);
    t0=min(to,tt);

    if(f0<=t0)
    {
         from=f0;to=t0;
         return ;
    }

    if(tt>PI)
    {
        ff-=2.0*PI;
        tt-=2.0*PI;
        f0=max(from,ff);
        t0=min(to,tt);
    }

    from=f0;to=t0;
    return ;
}


