        //long double theta = RAND(mt);
        long double theta = 2.0 * PI * ((long double)i / (long double)sum);
        long double now_x = 1e9 * cos(theta);
        long double now_y = 1e9 * sin(theta);
        //cout << theta << " " << now_x << " " << now_y << endl;
        //cout << theta << endl;
        //cout << now_x << " " << now_y << endl;
        long double now_dist = 1e38;
        for(int j = 1; j <= N; j++) {
           long double new_dist = (x[j]-now_x)*(x[j]-now_x)+(y[j]-now_y)*(y[j]-now_y);
           if(now_dist > new_dist) {
               now_dist = new_dist;
               now = j;
           } 
        }
        near[now]++;
    }
    for(int i = 1; i <= N; i++) {
        cout << (double)near[i] / (double)(sum) << endl;
    }
    return 0;
}

#include <stdio.h>
#include <math.h>
#include <algorithm>
#define N 105
#define EPS 1e-8
#define reg register
typedef double real;
const real PI=3.1415926535897932384626433832795;
int n;
real x[N],y[N],d[N];
inline real abs(real a){return a<0?-a:a;}
inline real crm(real x1,real y1,real x2,real y2){return x1*y2-x2*y1;}
int main() {
	reg int i,j,m;
	reg char f;
	reg real dif;
	scanf("%d",&n);
	for(i=1;i<=n;++i) scanf("%lf%lf",x+i,y+i);
	if(n<=2) {
		for(i=1;i<=n;++i) printf("%.12lf\n",1.0/n);
		return 0;
	}
	for(i=1;i<=n;++i) {
		m=0;
		for(j=1;j<=n;++j) if(i!=j) d[m++]=atan2(y[j]-y[i],x[j]-x[i]);
		std::sort(d,d+m);
		d[m]=d[0]+2*PI;
		f=0;
		for(j=0;j<m;++j) {
			dif=d[j+1]-d[j];
			if(abs(dif)>PI-EPS) {
				f=1;
				printf("%.12lf\n",dif/(2*PI)-0.5);
