int stk[N],tp,id[N];

void ConvexHull(Vector* p,int n)
{
	for(int i=1;i<=n;++i)
		id[i]=i;
	sort(id+1,id+n+1,[p](int a,int b)->bool{return p[a].x<p[b].x;});
	for(int i=1;i<=n;++i)
	{
		Vector& a=p[id[i]];
		while(tp>=2&&Det(a-p[stk[tp-1]],p[stk[tp]]-p[stk[tp-1]])<=0)
			--tp;
		stk[++tp]=id[i];
	}
	int rec=tp;
	for(int i=n-1;i>=1;--i)
	{
		Vector& a=p[id[i]];
		while(tp>rec&&Det(a-p[stk[tp-1]],p[stk[tp]]-p[stk[tp-1]])<=0)
			--tp;
		stk[++tp]=id[i];
	}
}

