	double t=2*PI;
	ans[stk[1]]=(PI-Angle(p[stk[tp-1]]-p[stk[1]],p[stk[2]]-p[stk[1]]))/t;
	for(int i=2;i<tp;++i)
		ans[stk[i]]=(PI-Angle(p[stk[i]]-p[stk[i-1]],p[stk[i]]-p[stk[i+1]]))/t;
	for(int i=1;i<=n;++i)
		printf("%.10lf\n",ans[i]+1e-8);
	return 0;
}

