            }

            for (int k = 0; k < n; k++) {
                if (k == i || k == j) {
                    continue;
                }

                Point d1 = p[j] - p[i];
                Point d2 = p[k] - p[j];

                if (d1.X * d2.Y == d2.X * d1.Y) {
                    use[j] = 0;
                }
            }
        }
    }

    vector<Point> q;

    for (int i = 0; i < n; i++) {
        if (use[i]) {
            q.push_back(p[i]);
        }
    }

    auto s = convexHull(q);

    vector<double> ans(n, 0.0);

    double pi = acos(-1);

    cout << fixed << setprecision(12);

    for (int i = 0; i < s.size(); i++) {

        Point d1 = s[(i + 1) % s.size()] - s[i];
        Point d2 = s[(i + s.size() - 1) % s.size()] - s[i];

        double r = arg(d2) - arg(d1);

        if (r < 0) {
            r += 2 * pi;
        }

        assert(0 <= r && r <= pi);

        double x = (pi - r) / (2 * pi);

        int ind = find(p.begin(), p.end(), s[i]) - p.begin();

        ans[ind] = x;
    }

    for (int i = 0; i < n; i++) {
        out(ans[i]);
    }
}

