double eps=1e-10;
double pi=3.1415926535897932;
double add(double a,double b){
  if(abs(a+b)<eps*(abs(a)+abs(b)))return 0;
  return a+b;
}
struct P{
  double x,y;
  P() {}
  P(double x,double y):x(x),y(y){
  }
  P operator + (P p){
    return P(add(x,p.x),add(y,p.y));
  }
  P operator - (P p){
    return P(add(x,-p.x),add(y,-p.y));
  }
  P operator * (double d){
    return P(x*d,y*d);
  }
  double dot(P p){
    return add(x*p.x,y*p.y);
  }
  double det(P p){
    return add(x*p.y,-y*p.x);
  }
};
bool on_seg(P p1,P p2,P q){
  return (p1-q).det(p2-q)==0&&(p1-q).dot(p2-q)<=0;
}
P intersection(P p1,P p2,P q1,P q2){
  return p1+(p2-p1)*((q2-q1).det(q1-p1)/(q2-q1).det(p2-p1));
}
bool cmp_x(const pair<P,int>& p,const pair<P,int>& q){
  P pp=p.first,qq=q.first;
  if(pp.x!=qq.x)return pp.x<qq.x;
  return pp.y<qq.y;
}
vector<pair<P,int>> convex_hull(pair<P,int>* ps,int n){
  sort(ps,ps+n,cmp_x);
  int k=0;
  vector<pair<P,int>> qs(n*2);
  for(int i=0;i<n;i++){
    while(k>1&&(qs[k-1].first-qs[k-2].first).det(ps[i].first-qs[k-1].first)<=0)k--;
    qs[k++]=ps[i];
  }
  for(int i=n-2,t=k;i>=0;i--){
    while(k>t&&(qs[k-1].first-qs[k-2].first).det(ps[i].first-qs[k-1].first)<=0)k--;
    qs[k++]=ps[i];
  }
  qs.resize(k-1);
  return qs;
}
double nolum(P p){
  return pow(p.dot(p),0.5);
}
double kaku(P p,P q){
  return acos(p.dot(q)/(nolum(p)*nolum(q)));
}
int main(){
  int n;
  double x[100],y[100];
  cin>>n;
  pair<P,int> ps[n];
  for(int i=0;i<n;i++){
    cin>>x[i]>>y[i];
    P o;
    o.x=x[i];
    o.y=y[i];
    ps[i]=make_pair(o,i);   
  }
  double ans[n];fill(ans,ans+n,0.0);
  vector<pair<P,int>> qs=convex_hull(ps,n);
  for(int i=0;i<qs.size();i++){
    int s=(i-1+qs.size())%qs.size(),t=(i+1)%qs.size();
    int num=qs[i].second;
    //cout<<num<<endl;
    double si=kaku(qs[s].first-qs[i].first,qs[t].first-qs[i].first);
    ans[num]=0.5-si/(2*pi);
  }
  for(int i=0;i<n;i++){
    cout<<fixed<<setprecision(9)<<ans[i]<<endl;
  }
}

