using namespace std;
double eps = 1e-10;

double add(double a, double b) {
	if (abs(a + b) < eps*(abs(a) + abs(b)))return 0;
	return a + b;
}

struct P {
	double x, y;
	int num;
	P() :x(0), y(0), num(INT32_MAX){
	}
	P(double x, double y) :x(x), y(y), num(INT32_MAX){
	}
	P operator-(P p) {
		return P(add(x, -p.x), add(y, -p.y));
	}
	double dot(P p) {//内積
		return add(x*p.x, y*p.y);
	}
	double det(P p) {//外積
		return add(x*p.y, -y*p.x);
	}
	double dist() {
		return sqrt(x*x + y*y);
	}
};

int n;
double ans[100];
P ps[100];

bool cmp_x(const P& p, const P& q) {
	if (p.x != q.x)return p.x < q.x;
	return p.y < q.y;
}

vector<P> convex_hull() {
	sort(ps, ps + n, cmp_x);
	int k = 0;
	vector<P> qs(n * 2);

	//下側の作成
	for (int i = 0; i < n; i++) {
		while (k > 1 && (qs[k - 1] - qs[k - 2]).det(ps[i] - qs[k - 1]) <= 0)k--;
		qs[k++] = ps[i];
	}

	//上側の作成
	for (int i = n - 2, t = k; i >= 0; i--) {
		while (k > t && (qs[k - 1] - qs[k - 2]).det(ps[i] - qs[k - 1]) <= 0)k--;
		qs[k++] = ps[i];
	}
	qs.resize(k - 1);

	return qs;
}

int main() {
	cin >> n;
	for (int i = 0; i < n; i++) {
		P& p = ps[i];
		cin >> p.x >> p.y;
		p.num = i;
	}
	vector<P>qs = convex_hull();

	//for (int i = 0; i < qs.size();i++)cout << "num:" << qs[i].num << endl;

	//ここでそれぞれの割合を求める
	for (int i = 0; i < qs.size(); i++) {
		P x{ -1, 0 }, y{ 0, 1 };

		//ここが間違えてる
		//垂直2等分線のベクトルを作成
		P vec[2];
		for (int j = 0; j < 2; j++) {
			P v = qs[((i + j - 1 < 0)?qs.size()-1:i+j-1)] - qs[(i + j) % qs.size()];
			double ang = acos((v.dot(y)) / (v.dist()));
			if (v.x >= 0)ang *= -1;
			double x2 = x.x*cos(ang) - x.y*sin(ang);
			double y2 = x.x*sin(ang) + x.y*cos(ang);
			vec[j] = P{ x2, y2 };
			//cout << "j:" << j << " x:" << vec[i].x << " y:" << vec[i].y << endl;
		}
		//cout << endl;

		//両ベクトルの内角を求める
		double ang = acos(vec[0].dot(vec[1]));

		//円の割合を求める
		ans[qs[i].num] = ang / (2*M_PI);
	}

	//答えを出力
	cout.precision(20);
	for (int i = 0; i < n; i++) {
		cout << ans[i] << endl;
	}
}

