long long cross(int a1,int b1,int a2,int b2){return (long long)a1*b2-(long long)a2*b1;}

double calc(int i)
{
	int j,k;
	for(j=1;j<=n;++j)
	if(j!=i)
	{
		for(k=1;k<=n;++k)
		if(k!=i&&k!=j&&cross(x[j]-x[i],y[j]-y[i],x[k]-x[i],y[k]-y[i])>0)
		break;
		if(k>n)break;
	}
	if(j>n)return 0;
	double a=atan2(y[j]-y[i],x[j]-x[i]);
	for(j=1;j<=n;++j)
	if(j!=i&&fabs(atan2(y[j]-y[i],x[j]-x[i])-a)>0.000001)
	{
		for(k=1;k<=n;++k)
		if(k!=i&&k!=j&&cross(x[j]-x[i],y[j]-y[i],x[k]-x[i],y[k]-y[i])<0)
		break;
		if(k>n)break;
	}
	if(j>n)return 0.5;
	double b=atan2(y[j]-y[i],x[j]-x[i]);
	double c=fabs(a-b);
	if(c>pi)c=2*pi-c;
	return (pi-c)/2/pi;
}

