struct Point {
  ld x, y;
  int id;
  Point(ld x=0, ld y=0, int id=-1): x(x), y(y), id(id) {}
  Point& operator+=(const Point& v) { x += v.x; y += v.y; return *this;}
  Point operator+(const Point& v) const { return Point(*this) += v;}
  Point& operator-=(const Point& v) { x -= v.x; y -= v.y; return *this;}
  Point operator-(const Point& v) const { return Point(*this) -= v;}
  Point& operator*=(ld s) { x *= s; y *= s; return *this;}
  Point operator*(ld s) const { return Point(*this) *= s;}
  Point& operator/=(ld s) { x /= s; y /= s; return *this;}
  Point operator/(ld s) const { return Point(*this) /= s;}
  ld dot(const Point& v) const { return x*v.x + y*v.y;}
  ld cross(const Point& v) const { return x*v.y - v.x*y;}
  ld norm2() const { return x*x + y*y;}
  ld norm() const { return sqrt(norm2());}
  Point rotate90() const { return Point(y, -x);}
  int ort() const { // orthant
    if (abs(x) < EPS && abs(y) < EPS) return 0;
    if (y > 0) return x>0 ? 1 : 2;
    else return x>0 ? 4 : 3;
  }
  // bool operator<(const Point& v) const { // argument
  //   int o = ort(), vo = v.ort();
  //   if (o != vo) return o < vo;
  //   return cross(v) > 0;
  // }
  bool operator<(const Point& v) const { // lexicographical
		return x < v.x || (x == v.x && y < v.y);
	}
};
