vector<Point> convex_hull(vector<Point> P) {
	int n = P.size(), k = 0;
	if (n <= 3) return P;
	vector<Point> H(2*n);

	// Sort points lexicographically
	sort(P.begin(), P.end());

	// Build lower hull
	for (int i = 0; i < n; ++i) {
		while (k > 1 && (H[k-1] - H[k-2]).cross(P[i] - H[k-2]) <= 0) k--;
		H[k++] = P[i];
	}

	// Build upper hull
	for (int i = n-2, t = k; i >= 0; --i) {
		while (k > t && (H[k-1] - H[k-2]).cross(P[i] - H[k-2]) <= 0) k--;
		H[k++] = P[i];
	}

	H.resize(k-1);
	return H;
}


int main() {
  ll n; cin >> n;
  vector<Point> P(n);
  rep(i, n) {
    cin >> P[i];
    P[i].id = i;
  }

  auto H = convex_hull(P);
  int k = H.size();

  Vld rad(k);
  rep(i, k) {
    int j = (i+1) % k;
    Point q = (H[i] - H[j]).rotate90();
    rad[i] = atan2(q.y, q.x);
  }

  Vld ans(n);
  rep(i, k) {
    int j = (i+1) % k;
    ld a = rad[j] - rad[i];
    if (a < 0) a += 2*M_PI;
    if (a > 2*M_PI) a -= 2*M_PI;
    ans[H[j].id] = a / (2 * M_PI);
  }

  cout << setprecision(12);
  cout << ans;
  return 0;
}

