					if(max_num>min_num){
						max_num=min(max_num,max_angle);
						min_num=max(min_num,min_angle);
						if(max_num<min_num){
							noans=true;
							break;
						}
					}else{
						if(max_num<max_angle){
							min_num=min_angle;
						}else{
							min_num=min_angle;
							max_num=min(max_num,max_angle);

						}
						if(max_num<min_num){
							noans=true;
							break;
						}

					}
				}else{
					if(max_num>min_num){
						if(min_num>min_angle){
							//do nothing;
						}else{
							min_num=max(min_num,min_angle);
							//max_num=min(max_num,max_angle);
							if(max_num<min_num){
								noans=true;
								break;
							}
						}

					}else{
						min_num=max(min_angle,min_num);
						max_num=min(max_num,max_angle);
					}
				}
			}

		}
		if(noans){
			cout<<0<<endl;
		}else{
			double p=0;
