	rep(i, N) {
		while (k > 1 && det(ret[k - 1] - ret[k - 2], ps[i] - ret[k - 1]) <= 0)
			k--;
		ret[k++] = ps[i];
	}
	for (int i = N - 2, t = k; i >= 0; i--) {
		while (k > t && det(ret[k - 1] - ret[k - 2], ps[i] - ret[k - 1]) <= 0)
			k--;
