int solve(int num) {
    std::sort(point,point+num);
    int k=0;
    for(int i=0;i<num;i++) {
        while(k>1&&(ans[k-1]-ans[k-2]).det(point[i]-ans[k-1])<EPS) k--;
        ans[k++]=point[i];
    }
    for(int i=num-2,t=k;~i;i--) {
        while(k>t&&(ans[k-1]-ans[k-2]).det(point[i]-ans[k-1])<EPS) k--;
        ans[k++]=point[i];
    }
    return k;
}
