const ld eps = 1e-8;
const int dx[] = { 1,0,-1,0 };
const int dy[] = { 0,1,0,-1 };

struct P {
	ld x, y;
	P() {}
	P(ld x, ld y) :x(x), y(y) {}
	P operator +(P & p) {
		return P(x + p.x + eps, y + p.y + eps);
	}
	P operator -(P & p) {
		return P(x - p.x + eps, y - p.y + eps);
	}
	P operator *(ld a) {
		return P(a*x, a*y);
	}
	P & operator +=(const P & p) {
		x += p.x;	y += p.y;	return *this;
	}
	P & operator -=(const P & p) {
		x -= p.x;	y -= p.y;	return *this;
	}
	P & operator *=(ld a) {
		x *= a;	y *= a;	return *this;
	}
	bool operator ==(P & p) {
		return (x == p.x)&&(y == p.y);
	}
	bool operator !=(P & p) {
		return (x != p.x) || (y != p.y);
	}
	bool operator <(P & p) {
		return (x == p.x ? y < p.y : x < p.x);
	}
	bool operator <=(P & p) {
		return (x == p.x ? y <= p.y : x <= p.x);
	}
	bool operator >(P & p) {
		return (x == p.x ? y > p.y : x > p.x);
	}
	bool operator >=(P & p) {
		return (x == p.x ? y >= p.y : x >= p.x);
	}
	ld dot(P p) {
		return x*p.x + y*p.y;
	}
	ld det(P p) {
		return x*p.y - y*p.x;
	}
	ld len() {
		return sqrtl(x*x + y*y);
	}
	ld getArg() {
		return arg(complex<ld>(x, y));
	}
};

vector<P> convex_hull(vector<P> ps, int n) {
	sort(all(ps));
	int k = 0;
	vector<P> qs(n * 2);
	for (int i = 0; i < n; i++) {
		while (k > 1 && (qs[k - 1] - qs[k - 2]).det(ps[i] - qs[k - 1]) <= 0)	k--;
		qs[k++] = ps[i];
	}
	for (int i = n - 2, t = k; i >= 0; i--) {
		while (k > t && (qs[k - 1] - qs[k - 2]).det(ps[i] - qs[k - 1]) <= 0)	k--;
		qs[k++] = ps[i];
	}
	qs.resize(k - 1);
	return qs;
}

int main() {
	int n;	cin >> n;
	vector<P> p(n);
	rep(i, n)	cin >> p[i].x >> p[i].y;
	vector<P> dat = convex_hull(p, n);
	int l = dat.size();
	rep(i, l)	dat.push_back(dat[i]);
	vector<ld> ret(n);
	rep(i, n) {
		srep(j, 1, dat.size()) {
			if (p[i] == dat[j]) {
				P a = dat[j + 1] - dat[j];
				P b = dat[j] - dat[j - 1];
				ld arg = a.getArg() - b.getArg();
				if (arg < 0)	arg += 2 * M_PI;
				ret[i] = arg / (2 * M_PI);
				break;
			}
		}
	}
	rep(i, n)	printf("%.15Lf\n", ret[i]+eps);
}

