bool ge(ld a, ld b) { return a - b >= -eps; }
ld sqr(ld x) { return x * x; }
ld Sqrt(ld x) { return sqrtl(max<ld>(0, x)); }

struct pt {
  ld x, y;
  int id;

  pt operator+(const pt& p) const { return pt{x + p.x, y + p.y, id}; }
  pt operator-(const pt& p) const { return pt{x - p.x, y - p.y, id}; }
  ld operator*(const pt& p) const { return x * p.x + y * p.y; }
  ld operator%(const pt& p) const { return x * p.y - y * p.x; }
  pt operator*(const ld& a) const { return pt{x * a, y * a, id}; }
  bool operator==(const pt& p) const { return eq(x, p.x) && eq(y, p.y); }

  bool up() const { return ze(y) ? x > 0 : y > 0; }

  pt norm() const { return *this * (1. / abs()); }
  pt rot() const { return pt{-y, x, id}; }
  pt rot_cw(pt e) const { return pt{e * *this, e % *this, id}; }
  ld abs() const { return hypotl(x, y); }
  ld abs2() const { return x * x + y * y; }
};

istream &operator>>(istream &in, pt &p) { return in >> p.x >> p.y; }
ostream &operator<<(ostream &out, const pt &p) { return out << p.x << ' ' << p.y; }

bool cmp_yx(const pt& a, const pt& b) {
  if (!eq(a.y, b.y))
    return a.y < b.y;
  if (!eq(a.x, b.x))
    return a.x < b.x;
  return false;
}
bool cmp_angle(const pt& a, const pt& b) {
  bool au = a.up(), bu = b.up();
  if (au != bu)
    return au;
  return a % b > eps;
}

struct Hull {
  vector<pt> h;
  int n;

  void build() {
    sort(h.begin(), h.end(), cmp_yx);
    h.erase(unique(h.begin(), h.end()), h.end());
    vector<pt> L, R;
    for (auto p: h) {
      while (R.size() > 1 && (p - R.back()) % (p - *next(R.rbegin())) >= -eps) {
        R.pop_back();
      }
      R.push_back(p);
      while (L.size() > 1 && (p - L.back()) % (p - *next(L.rbegin())) <= eps) {
        L.pop_back();
      }
      L.push_back(p);
    }
    if (!L.empty()) {
      L.pop_back();
    }
    reverse(L.begin(), L.end());
    if (!L.empty()) {
      L.pop_back();
    }
    h = R;
    h.insert(h.end(), L.begin(), L.end());
    n = h.size();
  }
};

signed main() {
#ifdef LOCAL
  assert(freopen("b.in", "r", stdin));
#endif
  Hull h;
  int n;
  cin >> n;
  vector<ld> ans(n);
  for (int i = 0; i < n; ++i) {
    pt p;
    cin >> p;
    p.id = i;
    h.h.push_back(p);
  }
  h.build();
  for (int i = 0; i < h.n; ++i) {
    int id = h.h[i].id;
    pt A = h.h[i] - h.h[(i+h.n-1)%h.n];
    pt B = h.h[(i+1)%h.n] - h.h[i];
    ld ang = atan2l(A % B, A * B);
    ans[id] = ang / (2 * acosl(-1));
  }
  cout << fixed;
  cout.precision(10);
  for (int i = 0; i < n; ++i) {
    cout << ans[i] << '\n';
  }
}

