  L(P _a,P _b):a(_a),b(_b){}
};

db dot(P a,P b){
  return a.x*b.x + a.y*b.y;
}//dot product 内積

db crs(P a,P b){
  return a.x*b.y-a.y*b.x;
}//cross product 外積

int ccw(P a,P b){
  if(crs(a,b)>EPS)return -1;
  if(crs(a,b)<-EPS)return 1;
  if(dot(a,b)<-EPS)return 2;
  if(a.norm()<b.norm())return -2;
  return 0;
}
//counter clockwise
//-2,-1,0,1,2 : online_front,cw,on,counter_cw,online_back
int ccw(P a,P b,P c){
  return ccw(b-a,c-a);
}

bool intersect(P p1,P p2,P p3,P p4){
  return ccw(p1,p2,p3)*ccw(p1,p2,p4)<=0 && ccw(p3,p4,p1)*ccw(p3,p4,p2)<=0;
}
bool intersect(L a,L b){
  return intersect(a.a,a.b,b.a,b.b);
}//線分交差判定

//Convex Hull------------------------------------------------------------
vector<P> ConvexLower(const vector<P>& ps){
  int tp;
  vector<P> ans(0);
  for(P now:ps){
    tp=ans.size();
    --tp;
    while(0<tp){
      //if(ccw(ans[tp-1],ans[tp],now)==1)break;//線上を入れない
      if(ccw(ans[tp-1],ans[tp],now)!=-1)break;//線上を入れる
      ans.pop_back();
      --tp;
    }
    ans.push_back(now);
  }
  return ans;
}

vector<P> ConvexHull(vector<P> ps){
  vector<P> lower,upper;
  sort(ps.begin(),ps.end());
  ps.erase(unique(ps.begin(),ps.end()),ps.end());
  if(ps.size()<2)return ps;

  lower=ConvexLower(ps);
  reverse(ps.begin(),ps.end());
  upper=ConvexLower(ps);

  lower.insert(lower.end(),upper.begin()+1,upper.end()-1);
  return lower;
}

