using namespace std;
struct P{
	double x,y,w;int id;
	P(){}
	P(double a,double b){x=a;y=b;}
	friend P operator +(P a,P b){
		return P(a.x+b.x,a.y+b.y);
	}
	friend P operator -(P a,P b){
		return P(a.x-b.x,a.y-b.y);
	}
	friend double operator *(P a,P b){
		return a.x*b.y-a.y*b.x;
	}
}a[105];
int s[105],top,n;
double ans[105];
bool cmpx(P a,P b){
	return a.x<b.x;
}
bool cmpw(P a,P b){
	if(fabs(a.w-b.w)>eps) return a.w>b.w;
	return fabs(a.x-::a[1].x)>fabs(b.x-::a[1].x);
}
const double pi=acos(-1);
double calc(P a,P b){
	double len=sqrt(a.x*a.x+a.y*a.y)*sqrt(b.x*b.x+b.y*b.y);
	double ans=(a.x*b.x+a.y*b.y)/len;
	ans=acos(ans);
	return (pi-ans)/(2*pi);
}
void solve(){
	sort(a+1,a+n+1,cmpx);
	for(int i=2;i<=n;i++) a[i].w=atan2(a[i].y-a[1].y,a[i].x-a[1].x);
	sort(a+2,a+n+1,cmpw);
	s[++top]=1;
	for(int i=2;i<=n;i++){
		if(i>2&&fabs(a[i].w-a[i-1].w)<eps) continue;
		while(top>1&&(a[i]-a[s[top]])*(a[s[top]]-a[s[top-1]])<0) top--;
		s[++top]=i;
	}
	for(int i=1,pre,nxt;i<=top;i++){
		pre=i-1,nxt=i+1;
		if(pre==0) pre=top;
		if(nxt==top+1) nxt=1;
		pre=s[pre];nxt=s[nxt];
		ans[a[s[i]].id]=calc(a[s[i]]-a[pre],a[s[i]]-a[nxt]);
	}
}
int main(){
	scanf("%d",&n);
	if(n==1) return puts("1.0"),0;
	for(int i=1;i<=n;i++) scanf("%lf%lf",&a[i].x,&a[i].y),a[i].id=i;
	solve();
	for(int i=1;i<=n;i++) printf("%.12lf\n",ans[i]);
	return 0;
}

