double deg(P p1,P p2){
	double d = atan((p1 - p2).Y / (p1 - p2).X) - PI / 2;
	if(p1.X > p2.X) d += PI;
	while(d < 0) d += 2 * PI;
	while(d > 2 * PI) d -= 2 * PI;
	return d;
}

