struct P
{
    long long x, y;
    int id;
    P operator - (const P &a)const{
        return (P){x - a.x, y - a.y};
    }
    long long operator * (const P &a)const{
        return x * a.y - y * a.x;
    }
    long long operator ^ (const P &a) const {
      return x * a.x + y * a.y;
    }
    bool operator >( const P& a ) const{
        return x == a.x ? y < a.y : x > a.x;
    }
    bool operator <( const P& a ) const{
        return x == a.x ? y > a.y : x < a.x;
    }
};
vector<P> all;
vector<P> vex, upp, dwn;
//sort all
void uphull(){
    int m = 0;
    for(int i = 0; i < all.size(); i++){
        /*if(!i){
            upp.push_back(all[0]);
            continue;
        }*/
        P lar = all[i];
        while(m > 1 && (lar - upp[m - 2]) * (upp[m - 1] - upp[m - 2]) <= 0){
            m--;
            upp.pop_back();
        }
        upp.push_back(lar);
        m++;
    }
}
void dwhull(){
    int m = 0;
    for(int i = 0; i < all.size(); i++){
        P lar = all[i];
        while(m > 1 && (lar - dwn[m - 2]) * (dwn[m - 1] - dwn[m - 2]) >= 0){
            m--;
            dwn.pop_back();
        }
        dwn.push_back(lar);
        m++;
    }
}
void concate(){
    for(int i = 0; i < upp.size(); i++) vex.push_back(upp[i]);
    for(int i = dwn.size() - 2; i > 0; i--) vex.push_back(dwn[i]);
}

long double getAlpha(const P &a, const P &b) {
  return atan2((long double) (a * b), (long double) (a ^ b));
}

int n;

int main() {
  cout.precision(15);
  cin >> n;
  all.resize(n);
  range(i, 0, n) {
    cin >> all[i].x >> all[i].y;
    all[i].id = i;
  }
  sort(all.begin(), all.end());
  uphull();
  dwhull();
  concate();
  long double cur = 2 * 3.141592653589793238462643;
  vector<long double> res(n);
  range(i, 0, (int) vex.size()) {
    P u = vex[(i + vex.size() - 1) % vex.size()];
    P v = vex[(i + 1) % vex.size()];
    u = u - vex[i];
    v = v - vex[i];
    long double t = getAlpha(u, v);
    t = cur / 2 - t;
    res[vex[i].id] = t / cur;
  }
  range(i, 0, n) cout << res[i] << endl;
  return 0;
}

