using namespace std;
using ll = long long;
using ii = pair<int, int>;
using pl = pair<ll, ll>;
constexpr double PI = 4*atan(1.0);

bool ccw(pl p, pl q, pl r) { return (q.f - p.f) * (r.s - p.s) - (r.f - p.f) * (q.s - p.s) > 0; }

vector<pl> convex_hull(vector<pl> & P) {
	int n = P.size(), k = 0;
	vector<pl> H(2 * n);
	sort(P.begin(), P.end());
	for (int i = 0; i < n; i++) {
		while (k >= 2 && ccw(H[k - 2], H[k - 1], P[i]) <= 0) k--;
		H[k++] = P[i];
	}
	for (int i = n - 2, t = k + 1; i >= 0; i--) {
		while (k >= t && ccw(H[k - 2], H[k - 1], P[i]) <= 0) k--;
		H[k++] = P[i];
	}
	H.resize(k);
	return H;
}

int main() {
    if (fopen("in", "r")) freopen("in", "r", stdin), freopen("out", "w", stdout);
    ios_base::sync_with_stdio(0), cin.tie(0);

    int N; cin >> N;
    vector<pl> P(N);
    map<pl, int> M;
    for (int i = 0; i < N; ++i) {
        cin >> P[i].f >> P[i].s;
        M[P[i]] = i;
    }

    vector<pl> CH = convex_hull(P);

    vector<double> S;
    for (int i = 0; i < CH.size() - 1; ++i) {
        S.push_back(atan2(CH[i].s-CH[i+1].s, CH[i].f-CH[i+1].f));
    }

    vector<double> ans(N);
    for (int i = 0; i < CH.size() - 1; ++i) {
        ans[M[CH[i]]] = fmod(S[i] - S[(i-2+CH.size())%(CH.size()-1)] + 4*PI, 2*PI) / (2*PI);
    }

    for (int i = 0; i < N; ++i) {
        cout << ans[i] << '\n';
    }
}

