struct P { double x, y; };

double const PI = std::acos(-1);

int main() {
  std::cin.tie(0); std::ios::sync_with_stdio(false);
  std::cout << std::setprecision(10) << std::fixed;
  int N; std::cin >> N;
  std::vector<P> p(N);
  for(int i = 0; i < N; ++i) std::cin >> p[i].x >> p[i].y;
  std::vector<double> th({-PI, PI});
  for(int i = 0; i < N-1; ++i) for(int j = i+1; j < N; ++j) {
    double vx = p[i].y - p[j].y;
    double vy = p[j].x - p[i].x;
    double theta = std::atan2(vy, vx);
    double x = std::cos(theta);
    double y = std::sin(theta);
    double dot = (p[i].x + p[j].x)*x + (p[i].y+p[j].y)*y;
    if(dot > 1e-8) {
      th.push_back(theta);
      continue;
    }
    th.push_back(std::atan2(-vy, -vx));
    if(dot > -1e-8) th.push_back(theta);
  }
  std::sort(th.begin(), th.end());
  std::vector<double> tmp(N);
  std::vector<double> ans(N, 0.0);
  for(int i = 0; i < th.size()-1; ++i) {
    double tb = th[i], te = th[i+1], tm = (tb+te)*0.5;
    double x = std::cos(tm), y = std::sin(tm);
    for(int i = 0; i < N; ++i) tmp[i] = p[i].x*x + p[i].y*y;
    int ma = std::max_element(tmp.begin(), tmp.end()) - tmp.begin();
    ans[ma] += (te-tb)/(2.0*PI);
  }
  fin(ans, '\n');
  return 0;
}

