const int N = 111;
const double pi = acos(-1.0);
vector< pair<double, int> > a;
int n, x[N], y[N];
double ans[N];

int main() {
	scanf("%d", &n);
	for (int i = 0; i < n; ++i) {
		scanf("%d%d", &x[i], &y[i]);
	}
	for (int i = 0; i < n; ++i) {
		for (int j = 0; j < n; ++j) {
			if (i == j) {
				continue;
			}
			int64 a = y[i] - y[j], b = x[j] - x[i], c = x[i] * (int64) y[j] - x[j] * (int64) y[i];
			bool ok = true;
			for (int k = 0; k < n; ++k) {
				if (a * x[k] + b * y[k] + c < 0) {
					ok = false;
					break;
				}
			}
			if (ok) {
				double alpha = atan2(a, b);
				if (alpha < 0) {
					alpha += 2 * pi;
				}
				(::a).pb(mp(alpha, j));
			}
		}
	}
	sort(a.begin(), a.end());
	for (int i = 0; i < sz(a); ++i) {
		double delta = 0;
		delta = (i == 0) ? (a[i].fs - a[sz(a) - 1].fs + 2 * pi) : (a[i].fs - a[i - 1].fs);
		ans[a[i].sc] = delta;
	}
	for (int i = 0; i < n; ++i) {
		printf("%.10f\n", ans[i] / (2 * pi));
	}
	return 0;
}

