        auto prv = i ? pts[i - 1] : pts.back();
        auto nxt = i + 1 < pts.size() ? pts[i + 1] : pts.front();
        auto p = prv - pts[i], q = nxt - pts[i];
        double ang = acos(min(1., dot(p, q) / (p.len() * q.len())));
        ans[inx[pts[i]]] = (M_PI - ang) / (2 * M_PI);
    }

    for (auto& d : ans) {
        printf("%.9f\n", d);
    }

    return 0;
}

