		double norm1 = sqrt(norm(p1));
		double norm2 = sqrt(norm(p2));
		double coss = (double)dot(p1, p2)/(norm1*norm2);
		double sinn = (double)cross(p1, p2)/(norm1*norm2);
		double theta = atan2(sinn, coss);
		res[ch[i]] = theta;
	}
