	if(tmp == 0) {                  //叉积为0,共线;所以离原点近的排在前面
		if(Dis(A, O) < Dis(B, O)) return true;
		else return false;
	}
	else {                          //不为0,不共线
		if(tmp > 0) return true;    //大于0,说明向量OB在向量OA的左边,所以OA排在前面
		else return false;          //反之,OB排在前面
	}
}

void Graham() {                     //求凸包
	sort(PP + 1, PP + n + 1);       //排序找出最下方的点,作为原点
	sort(PP + 2, PP + n + 1, Gcmp); //对其余的点进行极角排序
	hull[1] = PP[1];
	hull[2] = PP[2];
	top = 2;
	for(int i = 3; i <= n; i++) {
		while(top >= 2 && Cross(hull[top] - hull[top - 1], PP[i] - hull[top - 1]) <= 0)
			top--;
		hull[++top] = PP[i];
	}
}

bool Pcmp(Point A, Point B) {
	return A.pos < B.pos;
}

void debug() {
	printf("top = %d\n", top);
	for(int i = 1; i <= top; i++)
		printf("%d %d\n", hull[i].x, hull[i].y);
	printf("\n");
}

double prod(Vector A, Vector B) {
	return 1.0 * (A.x * B.x + A.y * B.y);
}

void solve() {
	hull[0] = hull[top];
	hull[top + 1] = hull[1];
	for(int i = 1; i <= top; i++) {
		Vector sa = hull[i - 1] - hull[i];
		Vector sb = hull[i + 1] - hull[i];
		hull[i].pb = (PI - acos(prod(sa, sb) / (dis(sa, Point(0, 0)) * dis(sb, Point(0, 0))))) / (2.0 * PI);
	}
	for(int i = 1; i <= n; i++) {
		for(int j = 1; j <= top; j++) {
			if(PP[i] == hull[j]) {
				PP[i].pb = hull[j].pb;
				break;
			}
		}
	}
	sort(PP + 1, PP + n + 1, Pcmp);
	for(int i = 1; i <= n; i++)
		printf("%.20lf\n", PP[i].pb);
}

int main()
{
	//printf("acos() = %lf\n", acos(-0.5));
	while(scanf("%d", &n) != EOF)
	{
		top = 0;
		for(int i = 1; i <= n; i++) {
			scanf("%d %d", &PP[i].x, &PP[i].y);
			PP[i].pos = i;
			PP[i].pb = 0.0;
		}
		Graham();
		//debug();
		solve();
	}
	return 0;
}

