	for(int i=0,t=0;i<n;ans[k++]=ps[i++])
		while(k>t&&cross(ans[k-2],ans[k-1],ps[i])<=0) k--;
	for(int i=n-1,t=k;i>=0;ans[k++]=ps[i--])
		while(k>t&&cross(ans[k-2],ans[k-1],ps[i])<=0) k--;
	ans.resize(k-1);return ans;
