struct Point {
	i64 x, y;

	Point operator-(const Point r) const {
		return Point{x - r.x, y - r.y};
	}

	bool operator<(const Point r) const {
		if(x == r.x) return y < r.y;
		return x < r.x;
	}
};

double abs(const Point a) {
	return std::sqrt(a.x * a.x + a.y * a.y);
}

double cross(const Point a, const Point b) {
	return a.x * b.y - a.y * b.x;
}

double dot(const Point a, const Point b) {
	return a.x * b.x + a.y * b.y;
}

double angle(const Point a, const Point b) {
	return acos(-dot(a, b) / abs(a) / abs(b));
}

std::vector<Point> convexHull(std::vector<Point> p) {
	int n = p.size(), k = 0;
	if(n >= 3) {
		sort(begin(p), end(p));
		std::vector<Point> ch(2 * n);
		for(int i = 0; i < n; ch[k++] = p[i++]) {
			while(k >= 2 and cross(ch[k - 1] - ch[k - 2], p[i] - ch[k - 1]) < 0) --k;
		}
		for(int i = n - 2, t = k + 1; i >= 0; ch[k++] = p[i--]) {
			while(k >= t and cross(ch[k - 1] - ch[k - 2], p[i] - ch[k - 1]) < 0) --k;
		}
		ch.resize(k - 1);
		return ch;
	} else {
		return p;
	}
}

int main() {
	int n; cin >> n;
	std::vector<Point> vec(n);
	std::map<Point, int> mp;
	for(int i = 0; i < n; i++) {
		i64 a, b; cin >> a >> b;

		vec[i] = Point{a, b};
		mp[vec[i]] = i;
	}

	auto ch = convexHull(vec);
	std::vector<double> ans(n, 0);
	const double Pi = std::acos(-1);
	for(int i = 0; i < ch.size(); i++) {
		Point u = ch[(i + ch.size() - 1) % ch.size()] - ch[i];
		Point v = ch[(i + 1) % ch.size()] - ch[i];
		ans[mp[ch[i]]] = angle(u, v) / 2.0 / Pi;
	}

	for(auto v : ans) cout << std::fixed << std::setprecision(10) << v << endl;
	return 0;
}

