bool intersect(Line l, Line m, bool endp){
    double t1=cross(vect(l),Point(m.start-l.start));
    double t2=cross(vect(l),Point(m.end-l.start));
    double t3=cross(vect(m),Point(l.start-l.start));
    double t4=cross(vect(m),Point(l.end-m.start));
    return endp?(t1*t2<=0 and t3*t4<=0):(t1*t2<0 and t3*t4<0);
}

vector<int> ConvexHull(vector<Point> points, bool edges){
    int size=points.size(),num=0; 
    vector<int> order(size),res(size*2); iota(all(order),0);
    sort(all(order),[&](int i, int j){return points[i]<points[j];});
    auto check=[&](int i, int j){
        Point p=points[res[j-1]]-points[res[j-2]];
        Point q=points[order[i]]-points[res[j-1]];
        return edges?cross(p,q)<0:cross(p,q)<eps;
    };
    for(int i=0; i<size; i++){
        while(num>1 and check(i,num))num--;
        res[num++]=order[i];
    }
    for(int i=size-2,t=num; i>=0; i--){
        while(num>t and check(i,num))num--;
        res[num++]=order[i];
    }
    res.resize(num-1);
    return res;
}

