const double EPS = 1e-10;

double add(double a,double b){
	if(abs(a+b) < EPS* (abs(a)+abs(b))) return 0;
	return a+b;
}

struct V{
	double x,y;
	V() {}
	V(double x,double y) : x(x), y(y){
	}
	V operator + (V p){
		return V(add(x, p.x), add(y, p.y));
	}
	V operator - (V p){
		return V(add(x,-p.x),add(y,-p.y));
	}
	V operator * (double d){
		return V(x*d,y*d);
	}
	bool operator == (V p){
		return add(x,-p.x)==0&&add(y,-p.y)==0;
	}
	double dot(V p){
		return add(x*p.x, y*p.y);
	}
	double det(V p){
		return add(x*p.y, -y*p.x);
	}
};

bool on_seg(V v1, V v2, V q){//v1-v2上にqがあるか判定
	return (v1 - q).det(v2 - q) == 0 && (v1 - q).dot(v2 - q) <= 0;
}

V intersection(V v1,V v2,V q1,V q2){ //直線v1-v2とq1-q2の交点
	return v1 + (v2-v1) * ( (q2-q1).det(q1-v1) / (q2-q1).det(v2-v1) );
}

bool cmp_x(const V& p,const V& q){
	if(p.x != q.x) return p.x<q.x;
	else return p.y<q.y;
}

double dist(V p,V q){
	return (p-q).dot(p-q);
}

vector<V> cnv(V* vs,int n){
	sort(vs,vs+n,cmp_x);
	int k=0;
	vector<V> qs(n*2);
	rep(i,n){
		while(k>1&&(qs[k-1]-qs[k-2]).det(vs[i]-qs[k-1])<=0) k--;
		qs[k++] = vs[i];
	}
	for(int i=n-2,t=k;i>=0;i--){
		while(	k>t	&&	(qs[k-1]-qs[k-2]).det(vs[i]-qs[k-1])<=0		) k--;
		qs[k++] = vs[i];
	}
	qs.resize(k-1);
	return qs;
}

