LL determinant(LL i, LL j, LL k) {
  // -           -
  // | x[i] - x[j], x[k] - x[j] |
  // | y[i] - y[j], y[k] - y[j] |
  // -           -
  LL det = (x[i] - x[j]) * (y[k] - y[j]) - (x[k]- x[j]) * (y[i] - y[j]);
  if (det > 0LL) return 1LL;
  if (det == 0LL) return 0LL;
  else return -1LL;
}

LL getMiddlePoint(LL i, LL j, LL k) {
  LL minX = min(x[i], min(x[j], x[k]));
  LL minY = min(y[i], min(y[j], y[k]));
  LL maxX = max(x[i], max(x[j], x[k]));
  LL maxY = max(y[i], max(y[j], y[k]));

//	printf("min: (%lld, %lld), max (%lld, %lld)\n", minX, minY, maxX, maxY);

  if (!((x[i] == minX || x[i] == maxX) && (y[i] == minY || y[i] == maxY))) {
//		printf("middle: (%lld, %lld)\n", x[i], y[i]);
    return i;
	} else if (!((x[j] == minX || x[j] == maxX) && (y[j] == minY || y[j] == maxY))) {
//		printf("middle: (%lld, %lld)\n", x[j], y[j]);
    return j;
	}
  else {
//		printf("middle: (%lld, %lld)\n", x[k], y[k]);
    return k;
	}
}

void convexHull() {
  // brute force convex hull
  FORN(i, N) {
    for (LL j = i+1; j < N; j++) {
      LL signs = 0;
      bool same = true;
      FORN(k, N) {
        if (k == i || k == j) continue;
        LL det = determinant(i, j, k);
        same &= (signs * det >= 0);
        signs = det;
      }
      if (same) {
          idx[i].insert(j);
      }
    }
  }

//  p();
  // fill in the line segments
  // at this point expect each point to be paired with two other points
  for (auto& kv : idx) {
    for (auto v : kv.SS) {
      idx[v].insert(kv.FF);
    }
  }

//  p();

  for (auto& kv : idx) {
    auto i = kv.FF;
    for (auto j : kv.SS) {
      for (auto k : kv.SS) {
        if (j == k) continue;
        LL det = determinant(i, j, k);
				auto m = getMiddlePoint(i, j, k);
//				printf("middle of (%lld, %lld), (%lld, %lld), (%lld, %lld) is (%lld, %lld)\n", x[i], y[i], x[j], y[j], x[k], y[k], x[m], y[m]);
        if (det == 0) toErase.insert(m);
      }
    }
  }
//  p();

  for (auto e : toErase) {
//		printf("erasing %lld\n", e);
    if (idx.find(e) != idx.end()) {
      idx.erase(e);
    }
    for (auto& kv : idx) {
      kv.SS.erase(e);
    }
  }
//  p();


}

