    }

    const pt operator -(pt other) {
        return pt(x - other.x, y - other.y);
    }

    const pt operator -(int c) {
        return pt(x - c, y - c);
    }

    pt& operator +=(pt other) {
        x += other.x;
        y += other.y;
        return *this;
    }

    pt& operator +=(int c) {
        x += c; y += c;
        return *this;
    }

    pt& operator -=(pt other) {
        x -= other.x;
        y -= other.y;
        return *this;
    }

    pt& operator -=(int c) {
