        return *this;
    }

    const pt operator /(int c) {
        return pt(x / c, y / c);
    }

    pt& operator /=(int c) {
        x /= c; y /= c;
        return *this;
    }

    pt& operator =(pt other) {
        x = other.x;
        y = other.y;
        return *this;
    }

    /// FUNCTIONS

    ll distSq(pt p) {
        return (x - p.x) * 1ll * (x - p.x) + (y - p.y) * 1ll * (y - p.y);
    }

    double dist(pt p) {
        return sqrt(distSq(p));
    }

    double magnitude() {
        return dist(pt(0, 0));
    }

    int orient(pt a, pt b) {
        ll val = (a.y - y) * 1ll * (b.x - a.x) - (a.x - x) * 1ll * (b.y - a.y);

        if (val == 0) {
            return 0;
        }

        return (val < 0 ? -1 : 1);
    }
};

const bool operator <(pt a, pt b) {return (a.x == b.x ? a.y < b.y : a.x < b.x);}
