pt convexHullP;

bool convexHullCmp(pt a, pt b) {
    int cur = convexHullP.orient(a, b);

    if (cur == 0) {
        return convexHullP.distSq(a) < convexHullP.distSq(b);
    }

    return cur == -1;
}

struct convexHull {
    vector<pt> V;

    convexHull() {
        V.clear();
    }

    convexHull(vector<pt> _V) {
        V = _V;
    }

    void solve() {
        int n = V.size(), k = 0;
        vector<pt> S(2 * n);
        sort(all(V));

        for (int i = 0; i < n; ++i) {
            while (k >= 2 && S[k - 2].orient(S[k - 1], V[i]) < 0) {
                --k;
            }

            S[k++] = V[i];
        }

        for (int i = n - 2, l = k + 1; i >= 0; --i) {
            while (k >= l && S[k - 2].orient(S[k - 1], V[i]) < 0) {
                --k;
            }

            S[k++] = V[i];
        }

        S.resize(k - 1);
        V = S;
    }
};

