        d[i] = new double[N];
        for(int j=0;j<N;j++){
            d[i][j] = 0;
        }
    }
    for(int i=0;i<N;i++){
        for(int j=i+1;j<N;j++){
            if(x[i]==x[j]){
                if(y[i]>y[j]) d[i][j] = 0.25;
                else d[i][j] = 0.75;
            }
            else{
                double theta = atan((double)(y[i]-y[j])/(double)(x[i]-x[j]))/(2.0 * PI); // in [-0.25, 0.25]
                if(x[i]>x[j]){
                    if(y[i]>y[j]) d[i][j] = theta;
                    else d[i][j] = theta + 1.0;
                }
                else d[i][j] = theta + 0.5;
            }
            if(d[i][j]<0.5) d[j][i] = d[i][j] + 0.5;
            else d[j][i] = d[i][j] - 0.5;
        }
    }
    for(int i=0;i<N;i++){
        double probability = 0.0;
        for(int j=0;j<N;j++){
            if(i==j) continue;
            double nearest_clock = 1.0;
            double nearest_counter = 1.0;
            for(int k=0;k<N;k++){
                if(i==k) continue;
                if(j==k) continue;
                double dist_clock = d[i][j] - d[i][k];
                if(dist_clock<0.0) dist_clock += 1.0;
                double dist_counter = 1.0 - dist_clock;
                nearest_clock = min(nearest_clock, dist_clock);
                nearest_counter = min(nearest_counter, dist_counter);
            }
            if(nearest_clock>0.5 || nearest_counter>0.5){
                probability = max(nearest_clock, nearest_counter) - 0.5;
                break;
            }
        }
        cout << probability << endl;
    }
    delete [] x;
    delete [] y;
    for(int i=0;i<N;i++) delete [] d[i];
    return 0;
}

