        return {x - p.x, y - p.y};
    }

    Point operator+(const Point &p) const {
        return {x + p.x, y + p.y};
    }

    Point &operator+=(const Point &p) {
        x += p.x, y += p.y;
        return *this;
    }

    double operator%(const Point &p) const {
        return x * p.x + y * p.y;
    }

    double operator*(const Point &p) const {
        return x * p.y - p.x * y;
    }

    Point operator/(double k) const {
        return {x / k, y / k};
    }

    Point &operator/=(double k) {
        x /= k;
        y /= k;
        return *this;
    }

    Point operator*(double k) const {
        return {x * k, y * k};
    }

    Point &operator*=(double k) {
        x *= k, y *= k;
        return *this;
    }

    bool operator<(const Point &p) const {
        return x < p.x || (x == p.x && y < p.y);
    }

    double length() const {
        return mySqrt(*this % *this);
    }

    double distTo(const Point &p) const {
        return (*this - p).length();
    }

    double distTo(const Point &A, const Point &B) const {
        double d = A.distTo(B);
        double s = (*this - A) * (*this - B);
        return fabs(s) / d;
    }

    Point normalize(double k = 1.0) const {
        double len = length();
        return *this * (k / len);
    }

    Point getH(const Point &A, const Point &B) const {
        Point C = *this;
        Point v = B - A;
        Point u = C - A;
        double k = v % u / v.length();
        v = v.normalize(k);
        Point H = A + v;
        return H;
    }

    Point rotate() const {
        return {-y, x};
    }

    Point rotate(double alpha) const {
        Point v = *this;
        Point w;
        w.x = v.x * cos(alpha) - v.y * sin(alpha);
        w.y = v.x * sin(alpha) + v.y * cos(alpha);
        return w;
    }

    bool isOnLine(const Point &A, const Point &B) const {
        return doubleEqual((*this - A) * (*this - B), 0.0);
    }

    bool isInSegment(const Point &A, const Point &B) const {
        return isOnLine(A, B) && doubleLessOrEqual((A - *this) % (B - *this), 0);
    }

    bool isInSegmentStrictly(const Point &A, const Point &B) const {
        return isOnLine(A, B) && doubleLess((A - *this) % (B - *this), 0);
    }

    double getAngle() {
        return atan2(y, x);
    }

    double getAngle(const Point &p) const {
        return atan2(p * *this, p % *this);
    }
};

int getTangent(const Point & A, const Point & O, double r, Point & M, Point & N) {
    Point v = O - A;
    double d = v.length();
    double alpha = asin(r / d);
    double L = mySqrt(sqr(d) - sqr(r));
    v = v.normalize(L);
    M = A + v.rotate(alpha);
    N = A + v.rotate(-alpha);
    if (doubleEqual(r, d)) return 1;
    return 2;
}


