ll N;
Polygon pol;
Polygon pol_for_ch;

ll PolToCh[MAX_N] = {};  // pol のインデックスを与えると対応する ch のインデックスを返す。ないときは -1

signed main()
{
    cin >> N;
    REP(i, N) {
        double a, b;
        cin >> a >> b;
        pol.push_back(Point(a, b));
        pol_for_ch.push_back(Point(a, b));
    }

    // 2 点しかない→両方 0.5
    if(N == 2) {
        REP(i, N) { printf("0.5\n"); }
        return 0;
    }
    // 全ての点が直線状にある→端点の 2 つが 0.5 を分け合う
    bool isAllXEq = true;
    bool isAllYEq = true;
    double min_x = pol[0].x;
    double max_x = pol[0].x;
    for(ll i = 0; i < N-1; ++i) {
        if(pol[i].x != pol[i+1].x) { isAllXEq = false; }
        if(pol[i].y != pol[i+1].y) { isAllYEq = false; }
    }
    if(isAllXEq) {
        double min_y = pol[0].y, max_y = pol[0].y;
        ll min_y_ind = 0, max_y_ind = 0;
        REP(i, N) {
            if(min_y > pol[i].y) {
                min_y = pol[i].y;
                min_y_ind = i;
            }
            if(max_y < pol[i].y) {
                max_y = pol[i].y;
                max_y_ind = i;
            }
        }
        REP(i, N) {
            if(i == max_y_ind || i == min_y_ind) { printf("0.5\n"); }
            else { printf("0\n"); }
        }
        return 0;
    }
    if(isAllYEq) {
        double min_x = pol[0].x, max_x = pol[0].x;
        ll min_x_ind = 0, max_x_ind = 0;
        REP(i, N) {
            if(min_x > pol[i].x) {
                min_x = pol[i].x;
                min_x_ind = i;
            }
            if(max_x < pol[i].x) {
                max_x = pol[i].x;
                max_x_ind = i;
            }
        }
        REP(i, N) {
            if(i == max_x_ind || i == min_x_ind) { printf("0.5\n"); }
            else { printf("0\n"); }
        }
        return 0;
    }

    // 凸包を求める
    // 凸包でない点 → 0
    Polygon ch = ConvexHull(pol_for_ch);

    // PolToCh の作成
    MINUS(PolToCh);
    REP(i, N) {
        REP(j, ch.size()) {
            if(pol[i] == ch[j]) {
                PolToCh[i] = j;
            }
        }
    }

    // 凸包の前後の点との法線を求め、そこから角度を出す
    vector<double> ch_ans;
    REP(i, ch.size()) {
        DBG("look (%f, %f)\n", ch[i].x, ch[i].y);
        Point forward, back;    // 前後の点 前：反時計回り方向で先にある点 後：時計回り方向で先にある点
        if(i == 0) {
            forward = ch[i+1];
            back = ch[ch.size()-1];
        }
        else if(i == ch.size()-1) {
            forward = ch[0];
            back = ch[i-1];
        }
        else {
            forward = ch[i+1];
            back = ch[i-1];
        }
        DBG("  forward (%f, %f), back (%f, %f)\n", forward.x, forward.y, back.x, back.y);

        Segment norm_f, norm_b, s;
        Line pb;    // 垂直二等分線
        // 法線ベクトルの作成
        auto SearchOut = [&]() -> Segment {
            Point poly_center = GetPolyCenter(ch);
            Point seg_center = s.Center();
            // 線分の中心から多角形の重心に向かうベクトル
            Point to_poly_center = poly_center - seg_center;
            // それとは逆方向の X もしくは Y にいったものが法線方向
            for(int j = 0; j < 2; ++ j) {
                Point cand = s.Center();
                if(j == 0) {
                    cand.x -= to_poly_center.x;
                    cand.y = pb.GetY(cand.x);
                }
                else {
                    cand.y -= to_poly_center.y;
                    cand.x = pb.GetX(cand.y);
                }
                if(Contains(ch, cand) == Out) {
                    return Segment(s.Center(), cand);
                }
                if(j == 2) { abort(); }
            }
            return Segment(Point(0, 0), Point(1, 0));   // ここには来ない
        };
        // 自分 - 前 との法線
        s = Segment(ch[i], forward);
        pb = s.PerpBisector();
        norm_f = SearchOut();
        // 自分 - 後ろとの法線
        s = Segment(ch[i], back);
        pb = s.PerpBisector();
        norm_b = SearchOut();

        DBG("  norm_f (%f, %f)->(%f, %f)\n  norm_b (%f, %f)->(%f, %f)\n",
                norm_f.a.x, norm_f.a.y, norm_f.b.x, norm_f.b.y,
                norm_b.a.x, norm_b.a.y, norm_b.b.x, norm_b.b.y);


        // 法線どうしの角度の差を求める
        double angle_f = norm_f.GetAngle();
        double angle_b = norm_b.GetAngle();
        double angle_ans;
        DBG("  angle_f %.9f   angle_b %.9f\n", RadianToDegree(angle_f), RadianToDegree(angle_b));
        if(angle_f < 0 && angle_b < 0) { angle_ans = angle_f - angle_b; }
        else if(angle_f < 0 && angle_b >= 0) { angle_ans = (PI - angle_b) + (angle_f + PI); }
        else if(angle_f >= 0 && angle_b < 0) { angle_ans = abs(angle_b) + angle_f; }
        else { angle_ans = angle_f - angle_b; }

        DBG("  angle: %f\n", RadianToDegree(angle_ans));

        ch_ans.push_back(angle_ans / (2 * PI));
    }

    REP(i, N) {
        if(PolToCh[i] == -1) { printf("0\n"); }
        else {
            //printf("%.20f\n", ch_ans[PolToCh[i]]);
            cout << ch_ans[PolToCh[i]] << endl;
        }
    }



    return 0;
}

