inline bool check(double x,double a,double b) {
    while (a>b) b+=2*pi;
    while (x<a) x+=2*pi;
    while (x>b) x-=2*pi;
    if (a<=x && x<=b) return true;
    else return false;
}

inline bool same(double a,double b) {
    while (a<b) a+=2*pi;
    if (a-b<1e-8) return true;else return false;
}
int main() {
    scanf("%d",&n);
    for (int i=1;i<=n;++i) scanf("%d%d",x+i,y+i),a[i]=-10,b[i]=-10;
    for (int i=1;i<=n;++i) {
        for (int j=1;j<=n;++j) {
            if (i==j) continue;
            double t=atan2(double(y[j]-y[i]),double(x[j]-x[i]));
            if (t<0) t+=2*pi;
            double t1=t-pi/2,t2=t+pi/2;
