typedef complex<double> point;

double dot(const point& a, const point& b)
{
	return real(a) * real(b) + imag(a) * imag(b);
}

double det(const point& a, const point& b)
{
	return real(a) * imag(b) - imag(a) * real(b);
}

vector<point> convex_hull(vector<point> ps)
{
	auto sort_fn = [](const point& a, const point& b) {
		return real(a) != real(b) ? real(a) < real(b) : imag(a) < imag(b);
	};
	sort(ps.begin(), ps.end(), sort_fn);

	int n = ps.size();
	vector<point> qs;

	for(int i = 0; i < n; ++i) {
		while(qs.size() > 1) {
			auto& x = qs[qs.size() - 2];
			auto& y = qs[qs.size() - 1];
			auto& z = ps[i];
			if(det(y - x, z - y) > 0)
				break;
			qs.pop_back();
		}
		qs.push_back(ps[i]);
	}

	int t = qs.size();

	for(int i = n - 2; i >= 0; --i) {
		while(qs.size() > t) {
			auto& x = qs[qs.size() - 2];
			auto& y = qs[qs.size() - 1];
			auto& z = ps[i];
			if(det(y - x, z - y) > 0)
				break;
			qs.pop_back();
		}
		qs.push_back(ps[i]);
	}

	qs.pop_back();

	return qs;
}

