		int x, y;
		scanf("%d%d", &x, &y);
		ps.push_back(complex<double>(x, y));
	}

	auto qs = convex_hull(ps);
	int m = qs.size();

	/*for(int i = 0; i < m; ++i) {
		printf("%lf %lf\n", real(qs[i]), imag(qs[i]));
	}*/

	vector<double> ans(n, 0);

