struct Pos{
	int x,y,idx;
	double Dist(){
		return sqrt(x*x+y*y);
	}
};
int cross(Pos a,Pos b){
	return a.x*b.y-a.y*b.x;
}
vector<Pos> CalcConvex(vector<Pos> ps,bool avoid3pts){
	{
		auto itr=min_element(ALL(ps),[&](Pos a,Pos b){
			if(a.x!=b.x)return a.x<b.x;
			else return a.y<b.y;
		});
		swap(*ps.begin(),*itr);
	}
	vector<Pos> convex;
	sort(ps.begin()+1,ps.end(),[&](Pos a,Pos b){
		a.x-=ps[0].x,a.y-=ps[0].y;
		b.x-=ps[0].x,b.y-=ps[0].y;
		int c=cross(a,b);
		if(c)return c>0;
		else if(a.x!=b.x) return a.x<b.x;
		else return a.y<b.y;
	});
	REP(i,ps.size()){
		while(int(convex.size())>=2){
			Pos a=convex[int(convex.size())-2];
			Pos b=convex[int(convex.size())-1];
			Pos c=ps[i];
			a.x-=b.x,a.y-=b.y;
			c.x-=b.x,c.y-=b.y;
			int z=cross(c,a);
			if(z>0||(z==0&&!avoid3pts))break;
			convex.pop_back();
		}
		convex.PB(ps[i]);
	}
	return convex;
}

signed main(){
