	}
	vector<Pos> convex=CalcConvex(ps,true);
	int s=convex.size();
	REP(i,s){
		Pos a=convex[(i+s-1)%s],b=convex[i],c=convex[(i+1)%s];
		a.x-=b.x,a.y-=b.y;
		c.x-=b.x,c.y-=b.y;
		double cos=-(a.x*c.x+a.y*c.y)/a.Dist()/c.Dist();
		double theta=acos(cos);
		ans[b.idx]=theta/(M_PI*2);
	}
	cout<<fixed<<setprecision(20);
