const double pi = 3.14159265358979323846;

vector<pair<double, double>> update(vector<pair<double, double>> v, double l, double r)
{
	vector<pair<double, double>> ov;
	if (r < l)
	{
		ov.push_back(make_pair(l, pi));
		ov.push_back(make_pair(-pi, r));
	}
	else
		ov.push_back(make_pair(l, r));

	vector<pair<double, double>> rs;
	for (const auto& src : v)
		for (const auto& dst : ov)
		{
			pair<double, double> p(max(src.first, dst.first), min(src.second, dst.second));
			if (p.first < p.second)
				rs.push_back(p);
		}
	return rs;
}

int main()
{
	int n;
	cin >> n;

	vector<pair<int, int>> vv;
	for (int i = 0; i < n; ++i)
	{
		int x, y;
		cin >> x >> y;
		vv.push_back(make_pair(x, y));
	}

	vector<vector<pair<double, double>>> rr(n, vector<pair<double, double>>(1, make_pair(-pi, pi)));

	for (int i = 0; i < n; ++i)
	{
		for (int j = i + 1; j < n; ++j)
		{
			double l = atan2(vv[i].first - vv[j].first, vv[j].second - vv[i].second);
			double r = atan2(vv[j].first - vv[i].first, vv[i].second - vv[j].second);
			rr[i] = update(rr[i], l, r);
			rr[j] = update(rr[j], r, l);
		}
	}

	for (int i = 0; i < n; ++i)
	{
		double p = 0.;
		for (const auto& v : rr[i])
			p += v.second - v.first;

		cout << setprecision(10) << (p / pi / 2.) << endl;

	}

	return 0;
}

