const double PI = acos(-1);

struct Point{
    double x, y;
    Point(){}
    Point(double x, double y):x(x), y(y){}
    void initialize(double xi, double yi){ x = xi; y = yi;}

    double det(Point other){
        return x*other.y - y*other.x;
    }

    Point operator-(Point other){
        return Point(x-other.x, y-other.y);
    }
    Point operator+(Point other){
        return Point(x+other.x, y+other.y);
    }
};

vector<Point> convex_hull(vector<Point> ps){
    int N = ps.size();
    sort(ps.begin(), ps.end(), [](auto a, auto b){ return make_pair(a.x, a.y) < make_pair(b.x, b.y);});
    int k = 0;
    vector<Point> qs(2*N);
    for(int i=0; i<N; i++){
        while(k>1 && (qs[k-1] - qs[k-2]).det(ps[i] - qs[k-1]) <= 0) k--;
        qs[k++] = ps[i];
    }
    for(int i=N-2, t=k; i>=0; i--){
        while(k>t && (qs[k-1] - qs[k-2]).det(ps[i] - qs[k-1]) <= 0) k--;
        qs[k++] = ps[i];
    }
    qs.resize(k-1);
    return qs;
}

int main(){
    int N;
    cin >> N;
    vector<double> X(N), Y(N);
    for(int i=0; i<N; i++) cin >> X[i] >> Y[i];
    vector<Point> ps;
    map<pair<double, double>, int> mp;
    for(int i=0; i<N; i++){
        ps.emplace_back(X[i], Y[i]);
        mp[{X[i], Y[i]}] = i;
    }

    auto hull = convex_hull(ps);
    int sz = hull.size();
    vector<double> angle(N), ans(N);
    for(int i=0; i<sz; i++){
        auto v = hull[(i+1)%sz] - hull[i];
        angle[i] = atan2(-v.x, v.y);
    }
    for(int i=0; i<sz; i++){
        double res = angle[i] - angle[(i-1+sz)%sz];
        if(res < 0) res += 2*PI;
        if(res > 2*PI) res -= 2*PI;
        ans[mp[{hull[i].x, hull[i].y}]] = res / 2 / PI;
    }
    for(int i=0; i<N; i++) cout << fixed << setprecision(10) << ans[i] << endl;
}

