using namespace std;
const double Pi=acos(-1);
struct node{
	double x,y;
	int id;
	node(){}
	node(double xx,double yy):x(xx),y(yy) {}
	node operator + (const node &a) const {
		return node(x+a.x,y+a.y);
	}
	node operator - (const node &a) const {
		return node(x-a.x,y-a.y);
	}
	node operator * (const double &t) const {
		return node(x*t,y*t);
	}
	double operator *(const node &a) const{
		return x*a.x+y*a.y;
	}
	double operator ^(const node &a) const{
		return x*a.y-y*a.x;
	}
	bool operator <(const node &a) const {
		return fabs(y-a.y)<EPS?x<a.x:y<a.y;
	}
}p[MAXN],l1[MAXN];
stack<node> s1,s;
double ans[MAXN];
int n,cnt1;
void solve(node a1[],int &cnt){
	s.push(p[1]);
	s1.push(p[1]);
	s1.push(p[2]);
	for(int i=3;i<=n;i++){
		while(!s.empty()&&((p[i]-s.top())^(s1.top()-s.top()))<EPS){
			s.pop();
			s1.pop();
		}
		s.push(s1.top());
		s1.push(p[i]);
	}
	while(!s1.empty()){
		a1[++cnt]=s1.top();
		s1.pop();
	}
	while(!s.empty())
		s.pop();
}
bool cmp(node a,node b){
	return b<a;
}
double len(node a){
    return sqrt(a.x*a.x+a.y*a.y);
}
