        b[i].second=(long long)(p[i].y);
    }
    for(int i=2;i<n;i++){
        long long xx1=b[i].first-b[i-1].first;
        long long xx2=b[i+1].first-b[i].first;
        long long yy1=b[i].second-b[i-1].second;
        long long yy2=b[i+1].second-b[i].second;
        if(yy1*xx2!=yy2*xx1)
            return 0;
    }
    return 1;
}
int main(){
	//freopen("data.in","r",stdin);
	//freopen("data.out","w",stdout);
	SF("%d",&n);
	for(int i=1;i<=n;i++){
		SF("%lf%lf",&p[i].x,&p[i].y);
        p[i].id=i;
	}
	sort(p+1,p+1+n);
	if(n==2){
        PF("0.50000\n");
        for(int i=2;i<n;i++)
            PF("0.00000\n");
        PF("0.50000\n");
        return 0;
	}
	solve(l1,cnt1);
	sort(p+1,p+1+n,cmp);
	cnt1--;
	solve(l1,cnt1);
	cnt1--;
	for(int i=1;i<=cnt1;i++){
        int las,nxt;
        if(i==1)
            las=cnt1;
        else
            las=i-1;
        if(i==cnt1)
            nxt=1;
        else
            nxt=i+1;
        double d=((l1[nxt]-l1[i])*(l1[las]-l1[i]))/(len(l1[nxt]-l1[i])*len(l1[las]-l1[i]));
        //PF("[%lf]",fabs((l1[nxt]-l1[i])*(l1[i]-l1[las])));
        d=acos(-d);
        ans[l1[i].id]=d/(2.0*Pi);
