string to_string(__int128_t a) {
    if (a == 0) return "0";
    if (a < 0) return "-"s + to_string(-a);
    string ret = "";
    while (a) {
        ret += '0' + a % 10;
        a /= 10;
    }
    reverse(ret.begin(), ret.end());
    return ret;
}

struct Rational {
    using Long = __int128_t;
    Long a, b;
    Rational() : a(0), b(1) {}
    Rational(Long a) : a(a), b(1) {}
    Rational(Long a, Long b) : a(a), b(b) { normalize(); }
    explicit operator double() const {
        return (double) a / b;
    }
    void normalize() {
        Long g = __gcd(a, b);
        a /= g, b /= g;
        if (b < 0) {
            a = -a, b = -b;
        }
    }
    Rational& operator+=(const Rational& rhs) {
        Long d = b * rhs.b;
        a = a * rhs.b + b * rhs.a;
        b = d;
        normalize();
        return *this;
    }
    Rational& operator-=(const Rational& rhs) {
        Long d = b * rhs.b;
        a = a * rhs.b - b * rhs.a;
        b = d;
        normalize();
        return *this;
    }
    Rational& operator*=(const Rational& rhs) {
        a *= rhs.a;
        b *= rhs.b;
        normalize();
        return *this;
    }
    Rational& operator/=(const Rational& rhs) {
        a *= rhs.b;
        b *= rhs.a;
        normalize();
        return *this;
    }
    Rational operator-() const {
        return Rational(-a, b);
    }
    Rational operator+(const Rational& rhs) const {
        return Rational(*this) += rhs;
    }
    Rational operator-(const Rational& rhs) const {
        return Rational(*this) -= rhs;
    }
    Rational operator*(const Rational& rhs) const {
        return Rational(*this) *= rhs;
    }
    Rational operator/(const Rational& rhs) const {
        return Rational(*this) /= rhs;
    }
    bool operator<(const Rational& rhs) const {
        return a * rhs.b < b * rhs.a;
    }
    bool operator>(const Rational& rhs) const {
        return rhs < *this;
    }
    bool operator<=(const Rational& rhs) const {
        return !(rhs < *this);
    }
    bool operator>=(const Rational& rhs) const {
        return !(*this > rhs);
    }
    bool operator==(const Rational& rhs) const {
        return !(*this < rhs) && !(rhs < *this);
    }
    bool operator!=(const Rational& rhs) const {
        return *this < rhs || rhs < *this;
    }
    friend ostream& operator<<(ostream& s, const Rational& f) {
        if (f.b == 1) {
            s << to_string(f.a);
        } else {
            s << to_string(f.a) << '/' << to_string(f.b);
        }
        return s;
    }
};

