bool isMostL(int w1, int w2) {
	for (int i=0;i<n;i++) if (i != w1 && i != w2 && ccwInt(tab[w1], tab[w2], tab[i]) > 0) return false;
	return true;
}

bool isMostR(int w1, int w2) {
	for (int i=0;i<n;i++) if (i != w1 && i != w2 && ccwInt(tab[w1], tab[w2], tab[i]) < 0) return false;
	return true;
}

bool allTheSameDir(int w) {
	int dx = -2;
	int dy = -2;
	for (int i=0;i<n;i++) if (i != w) {
		if (dx == -2) {
			if (tab[i].x > tab[w].x) dx = 1; else if (tab[i].x < tab[w].x) dx = -1; else dx = 0;
			if (tab[i].y > tab[w].y) dy = 1; else if (tab[i].y < tab[w].y) dy = -1; else dy = 0;
			continue;
		}
		if (tab[i].x > tab[w].x && dx != 1) return false;
		if (tab[i].x < tab[w].x && dx != -1) return false;
		if (tab[i].x == tab[w].x && dx != 0) return false;
		if (tab[i].y > tab[w].y && dy != 1) return false;
		if (tab[i].y < tab[w].y && dy != -1) return false;
		if (tab[i].y == tab[w].y && dy != 0) return false;
	}
	return true;
}

