typedef complex<long double> P;
namespace std{
	bool operator<(const P& a, const P& b){
		return real(a) != real(b) ? real(a) < real(b) : imag(a) < imag(b);
	}
}
inline long double cross(const P& a, const P& b){ return imag(conj(a)*b); }
inline long double dot(const P& a, const P& b){ return real(conj(a)*b); }
struct L : public vector<P>{
	L(const P &a, const P &b) {
		push_back(a); push_back(b);
	}
};
typedef vector<P> G;
inline int ccw(P a, P b, P c) {
	b -= a; c -= a;
	if(cross(b, c) >  EPS)   return +1;      // counter clockwise
	if(cross(b, c) < -EPS)   return -1;      // clockwise
	if(dot(b, c)   < -EPS)   return +2;      // c--a--b on line
	if(norm(b)+EPS <norm(c)) return -2;      // a--b--c on line
	return 0;                                   // c is between a and b (inclusive)
}
P crosspoint(const L &l, const L &m) {
	long double A = cross(l[1] - l[0], m[1] - m[0]);
	long double B = cross(l[1] - l[0], l[1] - m[0]);
	if (abs(A) < EPS && abs(B) < EPS) return m[0]; // same line
	if (abs(A) < EPS) assert(false); // !!!PRECONDITION NOT SATISFIED!!!
	return m[0] + B / A * (m[1] - m[0]);
}
#define curr(P, i) P[i]
#define next(P, i) P[(i+1)%P.size()]
G convex_cut(const G& po, const L& l) {
  G Q;
  for (int i = 0; i < po.size(); ++i) {
    P A = curr(po, i), B = next(po, i);
    if (ccw(l[0], l[1], A) != -1) Q.push_back(A);
    if (ccw(l[0], l[1], A)*ccw(l[0], l[1], B) < 0)
      Q.push_back(crosspoint(L(A, B), l));
  }
  return Q;
}
G voronoi(const G &g, G S, int idx){
	rep(i, g.size()) if(i != idx){
		P d = (g[i] - g[idx]) * P(0, 1);
		P m = (g[i] + g[idx]) * (long double)0.5;
		L l(m, m + d);
		S = convex_cut(S, l);
	}
	return S;
}

int main(){
	cin.tie(0); cin.sync_with_stdio(0);
	int n; cin >> n;
	double inf = 1e10;
	G g;
	G s = {P(-inf, -inf), P(inf, -inf), P(inf, inf), P(-inf, inf)};
	rep(i, n){
		int x, y; cin >> x >> y;
		g.emplace_back(P(x, y));
	}
	rep(i, n){
		G v = voronoi(g, s, i);
		vector<L> ls;
		auto on_edeg = [&](P p){
			return abs(abs(real(p)) - inf) < 1 || abs(abs(imag(p)) - inf) < 1;
		};

		bool outer = 0;

		rep(j, v.size()){
			outer |= on_edeg(v[j]);
			if(on_edeg(v[j]) ^ on_edeg(v[(j+1)%v.size()]))
			ls.emplace_back(v[j], v[(j+1)%v.size()]);
		}
		double ans = ls.size() != 2 ? 0.0 : arg((ls[0][1] - ls[0][0]) / (ls[1][0] - ls[1][1]));
		if(outer && ls.empty()) ans = PI;
		printf("%.20f\n", abs(ans) / PI / 2);
	}

	return 0;
}

