    for (int i = 0; i < N; i++)
    {
        ld x, y;
        cin >> x >> y;
        v[i] = Point(x, y);
        index[v[i]] = i;
    }
    Polygon pl = convex_hull(v);
    int sz = pl.size();
    vector<ld> ret(N, 0);
    for (int i = 0; i < sz; i++)
    {
        Point p = pl[i];
        Point q = pl[(i + sz - 1) % sz], r = pl[(i + 1) % sz];
        Line l = bisector(q, p), m = bisector(p, r);
        int idx = index[p];
        ret[idx] = degree_ll(l, m) / (2 * pi);
    }
    for (int i = 0; i < N; i++)
        cout << fixed << setprecision(10) << ret[i] << endl;
}

