        for (int j = 0; j < N; ++j) {
            if (i == j) continue;
            double theta;
            if (x[i] != x[j]) {
                double tan = (y[j] - y[i]) / (x[j] - x[i]);
                theta = atan(tan);
            } else {
                theta = M_PI / 2;
            }
            if (x[i] > x[j] || (x[i] == x[j] && y[i] > y[j])) {
                theta += M_PI;
            }

            double min_ = M_PI / 2 + theta, max_ = - M_PI / 2 + theta;
            if (max_ < 0) max_ += 2 * M_PI;

            if (min_arg[i] == 0 && max_arg[i] == 2 * M_PI) {
                min_arg[i] = min_; max_arg[i] = max_;
                continue;
            }

            double a = min_arg[i] - max_, b = max_arg[i] - min_;
            if (a > M_PI) a -= 2 * M_PI;
            if (a < -M_PI) a += 2 * M_PI;
            if (b > M_PI) b -= 2 * M_PI;
            if (b < -M_PI) b += 2 * M_PI;

            if (a > 0 && b < 0) {
                min_arg[i] = max_arg[i] = 0;
                break;
            } else if (a > 0 && b > 0) {
                min_arg[i] = min_;
            } else if (a < 0 && b < 0) {
                max_arg[i] = max_;
            }


        }

        arg[i] = max_arg[i] - min_arg[i];
        if (arg[i] < 0) {
            arg[i] += 2 * M_PI;
        }
    }

    for (int i = 0; i < N; ++i) {
        cout << arg[i] / (2 * M_PI) << endl;
    }

