//二次元ベクトル構造体
struct P {
	int id;//識別番号
	long double x, y;
	long double gain = 0;

	P(){}
	P(long double x, long double y) :x(x), y(y),id(-1) {}
	P(int id , long double x, long double y):id(id),x(x),y(y){}

	P operator +(P p) { return P(add(x, p.x), add(y, p.y)); }
	P operator -(P p) { return P(add(x, -p.x), add(y, -p.y)); }
	P operator *(long double d) { return P(x*d, y*d); }

	long double dot(P p) { return add(x*p.x, y*p.y); }//内積
	long double det(P p) { return add(x*p.y, -y * p.x); }

	long double rad() const{ return atan2(y, x); }
	long double rad(P p)const { return P(x - p.x, y - p.y).rad(); }//pから見た、角度

	//誤差を考慮した足し算
	long double abs(long double num) { return (num > 0 ? num : -num); }
	long double add(long double a, long double b) {
		if (abs(a + b) < (EPS * (abs(a) + abs(b))))return 0;
		return a + b;
	}
};


//辞書順で比較
bool cmp_x(const P& p, const P& q) {
	if (p.x != q.x)return p.x < q.x;
	return p.y < q.y;
}
bool cmp_rad(const P& p, const P& q) {
	return (p.rad() < q.rad());
}

//凸法を求める
vector<P> convex_hull(vector<P>& ps) {
	int n = ps.size();  //元々の頂点数
	int k = 0;          //凸包の頂点数
	vector<P> qs(n * 2);//構築中の凸包

	sort(ps.begin(), ps.end(), cmp_x);
	//下側凸包の作成
	REP(i, n) {
		while (k > 1 && (qs[k - 1] - qs[k - 2]).det(ps[i] - qs[k - 1]) <= 0)k--;
		qs[k++] = ps[i];
	}
	//上側凸包の作成
	for (int i = n - 2, t = k; i >= 0; i--) {
		while (k > t && (qs[k - 1] - qs[k - 2]).det(ps[i] - qs[k - 1]) <= 0)k--;
		qs[k++] = ps[i];
	}
	qs.resize(k - 1);
	return qs;
}



