struct point
{
	LL x, y;
	point(){}
	point(double x1, double y1)
	{
		x = x1;
		y = y1;
	}

	LL d2() const
	{
		return x * x + y * y;
	}

	double len() const
	{
		return sqrt((double)d2());
	}

	point getNorm() const
	{
		return point(-y, x);
	}

	point operator -(const point& a) const
	{
		return point(x - a.x, y - a.y);
	}

	LL operator *(const point& a) const
	{
		return x * a.y - a.x * y;
	}
};

const int MAX = 100 + 47;
point A[MAX];
double ANS[MAX];
int n;
point a, b;

double getAng(point a, point b)
{
	double a1 = atan2(a.y, a.x);
	if (a1 < 0) a1 += 2 * PI;
	double a2 = atan2(b.y, b.x);
	if (a2 < 0) a2 += 2 * PI;

	double alpha = abs(a1 - a2);
	if (alpha > PI) alpha = 2 * PI - alpha;
	return PI - alpha;
}

bool isOk(point a, point b)
{
	bool ccw = false;
	bool cw = false;

	FOR(i, 0, n)
	{
		LL val = (b - a) * (A[i] - a);
		if (val > 0) ccw = true;

		if (val < 0) cw = true;
	}

	if (ccw && cw) return false;

	return true;
}


