	const double pi=acos(-1.0);

	struct point
	{
		double x,y;
		int id;

		point (double a=0,double b=0,int c=0)
		{
			x=a,y=b;
			id=c;
		}
	};

	bool operator < (point A,point B){return A.x<B.x;}
	point operator - (point A,point B){return point(A.x-B.x,A.y-B.y);}

	double cross(point A,point B)
	{
		return A.x*B.y-A.y*B.x;
	}

	point s[N];
	double ans[N];

	int n,m;

	point t[N];

	void insert(point A)
	{
		while(m>1)
		{
			point B=t[m],C=t[m-1];

			if(cross(A-C,B-C)>=-eps)m--;
			else break;
		}
		t[++m]=A;
	}

	void calc_hull()
	{
		m=0;
		for(int i=1;i<=n;i++)
			insert(s[i]);
		for(int i=n-1;i;i--)
			insert(s[i]);
	}

