	{
		scanf("%d",&n);
		for(int i=1;i<=n;i++)
			scanf("%lf%lf",&s[i].x,&s[i].y),s[i].id=i;
		std::sort(s+1,s+n+1);
	}

	double fuck(point A)
	{
		return atan2(A.y,A.x);
	}

	void getans()
	{
