		for(int i=2;i<=m;i++)
		{
			double x=fuck(t[i-1]-t[i]),y=fuck(t[i]-t[i+1]);

			y-=x;
			while(y<0)y+=pi*2;

			ans[t[i].id]=y/pi/2;
		}
	}

	void solve()
	{
		initialize();

		if(n==2)
		{
			printf("0.5\n0.5\n");
			return;
		}

