    if(sz(v) == 1) return;
    pll a = v[0], b = v.back();
    up.pb(a);
    down.pb(a);
    fr(i, 1, sz(v) - 1) {
        ll c = cross(sub(v[i], a), sub(b, v[i]));
        if((i == sz(v) - 1) || (c < 0)) {
            while(sz(up) >= 2 && cross(sub(up.back(), up[sz(up) - 2]), sub(v[i], up.back())) >= 0) {
                up.pop_back();
            }
            up.pb(v[i]);
        }
        if((i == sz(v) - 1) || (c > 0)) {
            while(sz(down) >= 2 && cross(sub(down.back(), down[sz(down) - 2]), sub(v[i], down.back())) <= 0) {
                down.pop_back();
            }
            down.pb(v[i]);
        }
    }
    v = down;
    for(int i = sz(up) - 2; i > 0; i--) {
        v.pb(up[i]);
    }
}

bool inside(pll x) {
    auto it = upper_bound(all(up), x);
    int idx = it - up.begin();
    if(idx == 0) return 0;
    if(idx == sz(up)) return 0;
    pll a = up[idx - 1], b = up[idx];
    if(cross(sub(x, a), sub(b, x)) < 0) return 0;
    it = upper_bound(all(down), x);
    idx = it - down.begin();
    if(idx == 0) return 0;
    if(idx == sz(down)) return 0;
    a = down[idx - 1], b = down[idx];
    if(cross(sub(x, a), sub(b, x)) > 0) return 0;
    return 1;
}

map<pii,int> idx;
const int N = 105;
f80 ans[N];

const f80 PI = acos(-1);

void solve() {
    cout << setprecision(10) << fixed;
	int n;
    sc(n);
    vector<pll> v;
    fr(i, 1, n) {
        int x, y;
        sc(x, y);
        idx[{x, y}] = i;
        v.pb({x, y});
    }
    ConvexHull(v);
    if(sz(v) == 2) {
        ans[idx[v[0]]] = 0.5;
        ans[idx[v[1]]] = 0.5;
        fr(i, 1, n) {
            cout << ans[i] << endl;
        }
        return;
    }
    debug(v);
    int nn = sz(v);
    f80 tot = 0;
    fr(i, 0, sz(v) - 1) {
        pll v1 = sub(v[(i + 1) % nn], v[i]);
        pll v2 = sub(v[(i - 1 + nn) % nn], v[i]);
        f80 ang = cross(v1, v2);
        ang /= sqrtl(v1.fi * v1.fi + v1.se * v1.se);
        ang /= sqrtl(v2.fi * v2.fi + v2.se * v2.se);
        debug(ang);
        ang = min(ang, f80(1));
