        debug(v[i], (180.0 / PI) * ang);
        debug(v1, v2);
        ang = PI - ang;
        tot += ang;
        ans[idx[v[i]]] = ang;
    }
    fr(i, 1, n) {
        ans[i] /= tot;
        cout << ans[i] << endl;
    }
}

