main(){
  cin.tie(0);
  ios::sync_with_stdio(false);
  cin >> n;
  int mi_x, ma_y = -iinf, s;
  FOR(i, 0, n){
    int x, y;
    cin >> x >> y;
    pl.pb(pii(x, y));
    if(y > ma_y || y == ma_y && x < mi_x){
      s = i;
      mi_x = x;
      ma_y = y;
    }
  }
  int p = s;
  double pr = -5.0;
  while(true){
    el.pb(p);
    int idx;
    double cpr = 5.0;
    FOR(i, 0, n){
      if(i == p) continue;
      complex<float> c(pl[i].fi - pl[p].fi, pl[i].se - pl[p].se);
      double ar = arg(c);
      if(ar >= pr && ar <= cpr){
        cpr = ar;
        idx = i;
      }
    }
    pr = cpr;
    p = idx;
    if(p == s) break;
  }
  FOR(i, 0, sz(el)){
    complex<float> v1, v2;
