int orient(pt a, pt b, pt c) {
    ll val = (b.y - a.y) * (c.x - b.x) - (c.y - b.y) * (b.x - a.x);

    if (val < 0) {
        val = -1;
    }

    if (val > 0) {
        val = 1;
    }

    return val;
}

ll distSq(pt a, pt b) {
