}

bool cmp(pt a, pt b) {
    int cur = orient(arr[0], a, b);

    if (cur == 0) {
        return distSq(arr[0], a) <= distSq(arr[0], b);
    }

    return cur == -1;
}

void convexHull() {
    {
        int p = 0;

        for (int i = 1; i < arr.size(); ++i) {
            if (arr[i].y < arr[p].y) {
                p = i;
            }
            else if (arr[i].y == arr[p].y && arr[i].x < arr[p].x) {
                p = i;
            }
        }

        swap(arr[0], arr[p]);
    }

    sort(arr.begin() + 1, arr.end(), cmp);
    int m = 1;

    for (int i = 1; i < arr.size(); ++i) {
        while (i < arr.size() - 1 && orient(arr[0], arr[i], arr[i + 1]) == 0) {
            ++i;
        }

        arr[m++] = arr[i];
    }

    arr.resize(m);

    if (m < 3) {
