    Polygon pol = convex_hull(ps);
    map<Point, double> mp;
    rep(i, pol.size()) {
        Point p1 = pol[i];
        Point p2 = pol[(i + 1) % pol.size()];
        Point p3 = pol[(i + 2) % pol.size()];
        double dt = dot(p3 - p2, p2 - p1) / abs(p3 - p2) / abs(p2 - p1);
        double rad = acos(min(1.0, max(dt, -1.0)));
        mp[p2] = rad / (PI * 2);
    }

    for(Point P : p) {
        cout << fixed << setprecision(20) << mp[P] << endl;
    }

    return 0;
}

