        //printf("a=%lf %lf    %lf %lf\n",a,dot(p1-p[i],p2-p[i]),p1.x-p[i].x,p1.y-p[i].y);
        a=normal(a);
         //printf("a2=%lf\n",a);
        ans[ch[i].id]=a/(2*pi);
    }
    for (i=0;i<n;i++) {
        printf("%.20lf\n",ans[i]);
    }
    return 0;
}

