struct Point
{
    double x,y;
    int idd;
    inline Point operator- (const Point &t)
    {
        Point ret;
        ret.x=x-t.x;
        ret.y=y-t.y;
        return ret;
    }
    inline Point operator+ (const Point &t)
    {
        Point ret;
        ret.x=x+t.x;
        ret.y=y+t.y;
        return ret;
    }
    inline double det(const Point &t)
    {
        return x*t.y-t.x*y;
    }
    inline double dist(Point &t)
    {
        return sqrt(sqr(x-t.x)+sqr(y-t.y));
    }
}d[Maxn];

int convex[Maxn],cTotal;
double eps=1e-8;
int dcmp(double x)  
{  
    if(fabs(x) < eps)  
        return 0;  
    else  
        return x < 0 ? -1 : 1;  
} 
double Dis(Point A, Point B){  
    return sqrt((A.x-B.x)*(A.x-B.x) + (A.y-B.y)*(A.y-B.y));  
}  
bool cmp(Point A, Point B)
{  
    double temp = (A-d[0]).det( B-d[0]);  
    if(dcmp(temp) > 0) return true;  
    if(dcmp(temp) == 0 && dcmp(Dis(d[0], A) - Dis(d[0], B)) < 0) return true;  
    return false;  
} 
void Graham(int n)  
{  
    if(n == 1){ cTotal = 0; convex[0] = 0;}  
    else if(n == 2)  
    {  
        cTotal = 1;  
        convex[0] = 0;  
        convex[1] = 1;  
    }  
    else  
    {  
        for(int i = 0; i <= 1; i++)  
            convex[i] = i;  
        cTotal = 1;  
        for(int i = 2; i < n; i++)  
        { 
		while(cTotal > 0 && dcmp((d[convex[cTotal]]-d[convex[cTotal-1]]).det( d[i]-d[convex[cTotal-1]])) <= 0) cTotal--;  
            cTotal++;  
            convex[cTotal] = i;  
        }  
    }  
}
