            yy = d[i].y;  
            id = i;  
        }  
		//cout<<d[i].x<<' '<<d[i].y<<endl;
	}
	Point T;  
    T = d[0]; d[0] = d[id]; d[id] = T;  
	sort(d+1, d+N, cmp);
	Graham(N);
