	for (int i=0;i<cTotal;i++){
	//	cout<<convex[i]<<endl;
		hav[convex[i]]=true;
	}
	double pi=acos(-1);
	for (int i=0;i<cTotal;i++){
		int pre=i-1,now=i,nxt=i+1;
		if (pre<0) pre=cTotal-1;
		if (nxt>=cTotal) nxt=0;
		pre=convex[pre];now=convex[now];nxt=convex[nxt];
		//cout<<pre<<' '<<now<<' '<<nxt;
