int main() {
	long long N;
	vector<pair<pair<long long, long long>, long long> > V;
	cin >> N;
	V.resize(N);
	for (int i = 0; i < N; i++) cin >> V[i].first.first >> V[i].first.second, V[i].second = i;
	sort(V.begin(), V.end());
	vector<long long> L;
	vector<bool> used(N, false);
	long long A = 0;
	do {
		used[A] = true;
		L.push_back(A);
		long long B = 0;
		for (int i = 1; i < N; i++) {
			if (A == i) continue;
			if (B == A) B = i;
			else {
				pair<long long, long long> AB, AC;
				AB.first = V[B].first.first - V[A].first.first;
				AB.second = V[B].first.second - V[A].first.second;
				AC.first = V[i].first.first - V[A].first.first;
				AC.second = V[i].first.second - V[A].first.second;
				long long X = AB.first * AC.second - AB.second * AC.first;
				if (X > 0 || (X == 0 && AC.first > AB.first)) B = i;
			}
		}
		A = B;
	} while (!used[A]);
	vector<double> ANS(N, 0);
	for (int i = 0; i < L.size(); i++) {
		long long Now = i;
		long long Left = (i + L.size() - 1) % L.size();
		long long Right = (i + 1) % L.size();
		pair<double, double> LP, RP;
		LP.first = V[L[Now]].first.second - V[L[Left]].first.second;
		LP.second = V[L[Left]].first.first - V[L[Now]].first.first;
		RP.first = V[L[Right]].first.second - V[L[Now]].first.second;
		RP.second = V[L[Now]].first.first - V[L[Right]].first.first;
		double LA, RA;
		LA = atan2(LP.first, LP.second);
		RA = atan2(RP.first, RP.second);
		double Angle;
		if (LA < RA) Angle = RA - LA;
		else Angle = 2 * PI - (LA - RA);
		ANS[V[L[Now]].second] = Angle / (PI * 2);
	}
	for (int i = 0; i < N; i++) printf("%.12lf\n", ANS[i]);
}

