typedef long long ll;

class GrahamScan{
public:
	typedef pair<int,int> P;
	vector<P> hull;

	int cross(P a, P b){
		return a.first * b.second - a.second * b.first;
	}

	P sub(P a, P b){
		return P(a.first-b.first, a.second-b.second);
	}

	GrahamScan(vector<P> p){
		int n = p.size();

		sort(p.begin(),p.end());
		hull = vector<P>(n*2);
		int k = 0;

		for (int i = 0;i < n;i++){
			while(k > 1 && cross(sub(hull[k-1], hull[k-2]), sub(p[i], hull[k-1])) <= 0) k--;
			hull[k++] = p[i];
		}
		for (int i = n-2, t = k;i >= 0;i--){
			while(k > t && cross(sub(hull[k-1], hull[k-2]), sub(p[i], hull[k-1])) <= 0) k--;
			hull[k++] = p[i];
		}

		hull.resize(k-1);
	}
};

