bool is_anticlockwise (
  pair<double, double> const& a
, pair<double, double> const& b
, pair<double, double> const& c
) {
  return
    (b.first - a.first) * (c.second - a.second) 
  - (b.second - a.second) * (c.first - a.first)
  > 1e-11;
}
inline int prev(int i, int sz) {
  return 0 < i ? i - 1 : sz - 1;
}
inline int next(int i, int sz) {
  return i < sz - 1 ? i + 1 : 0;
}
double angle (
  pair<double, double> const& A
, pair<double, double> const& B 
, pair<double, double> const& C
) {
  double a = sqrt(pow(B.first - C.first, 2) + pow(B.second - C.second, 2));
  double b = sqrt(pow(C.first - A.first, 2) + pow(C.second - A.second, 2));
  double c = sqrt(pow(A.first - B.first, 2) + pow(A.second - B.second, 2));
  return acos(
    (pow(a, 2) + pow(c, 2) - pow(b, 2))
  / (2 * a * c)
  );
}
int main() {
  int n;
  cin >> n;
  int sz = 0;
  vector<pair<pair<double, double>, int>> hull;
  for (int t = 0; t < 2; t++) {
    pair<double, double> p;
    cin >> p.first >> p.second;
    hull.emplace_back(p, t);
    sz++;
  }
  for (int t = 2; t < n; t++) {
    pair<double, double> pt;
    cin >> pt.first >> pt.second;
    vector<bool> flg(sz);

    for (int i = 0; i < sz; i++) {
      flg[i] = is_anticlockwise(
        hull[i].first
      , hull[next(i, sz)].first
      , pt
      );
    }
    int l = -1, r = -1;
    for (int i = 0; i < sz; i++) {
      int nxt = next(i, sz);
      if (!flg[i] && flg[nxt]) l = nxt;
      if (flg[i] && !flg[nxt]) r = next(nxt, sz);
    }
    if (l == -1 || r == -1) continue;
    if (l < r) {
      hull = decltype(hull)(hull.begin() + l, hull.begin() + r);
      hull.insert(hull.begin(), {pt, t});
    } else {
      hull.erase(hull.begin() + r, hull.begin() + l);
      hull.insert(hull.begin() + l, {pt, t});
    }
    sz++;
  }
  vector<double> agl(sz);
  for (int i = 0; i < sz; i++) {
    agl[i] = angle(
      hull[prev(i, sz)].first
    , hull[i].first
    , hull[next(i, sz)].first
    );
  }
  vector<double> ret(n, 0);
  const double pi = acos(0) * 2;
  for (int i = 0; i < sz; i++) {
    ret[hull[i].second] = (pi - agl[i]) / (2 * pi);
  }
  for (int i = 0; i < n; i++) {
    cout << ret[i] << endl;
  }
  return 0;
}

