        double mind = INF; int minp = -1;
        rep(N, i) {
            if (((ps[i].first-nx)*(ps[i].first-nx)+(ps[i].second-ny)*(ps[i].second-ny))<mind) {
                minp = i;
                mind = (ps[i].first-nx)*(ps[i].first-nx)+(ps[i].second-ny)*(ps[i].second-ny);
            }
        }
        cnt[minp]++;
    }
    rep(N, i) {
        printf("%.6lf\n", cnt[i]/(double)loop);
    }
}

