pt operator - (const pt &a, const pt &b)
{
	return {a.x - b.x, a.y - b.y, -1};
}

ll operator ^ (const pt &a, const pt &b)
{
	return a.x * (ll) b.y - a.y * (ll) b.x;
}

ll operator * (const pt &a, const pt &b)
{
	return a.x * (ll) b.x + a.y * (ll) b.y;
}

pt s;

bool operator < (const pt &a, const pt &b)
{
    if (((a - s) ^ (b - s)) != 0)
    {
	    return ((a - s) ^ (b - s)) < 0;
    }
    else
    {
        return (a - s) * (a - s) < (b - s) * (b - s);
    }
}

vector <pt> hull(vector <pt> e)
{
	sort(e.begin(), e.end(), [] (pt a, pt b)
	{
		if (a.x != b.x)
		{
			return a.x < b.x;
		}
		else
		{
			return a.y < b.y;
		}
	});
	s = e[0];
	sort(e.begin() + 1, e.end());
	vector <pt> h;
	for (auto c : e)
	{
		while (h.size() > 1)
		{
			pt a = h[(int) h.size() - 2];
			pt b = h[(int) h.size() - 1];
			if (((b - a) ^ (c - b)) >= 0)
			{
				h.pop_back();
			}
			else
			{
				break;
			}
		}
		h.push_back(c);
	}
	return h;
}

double dist(const pt &a, const pt &b)
{
    ll len = (a.x - b.x) * (ll) (a.x - b.x) + (a.y - b.y) * (ll) (a.y - b.y);
    return sqrt(len);
}

