  ld m, m1, m2, y;
  line(ld a_, ld b_, ld c_) {
    while(abs(a_-round(a_)) > EPS ||
          abs(b_-round(b_)) > EPS) {
            a_*=10;
            b_*=10;
            c_*=10;
    }
    a=round(a_);
    b=round(b_);
    c=c_;
    int x = __gcd(a,b);
    if(x<0) x*=-1;
    a/=x;
    b/=x;
    if(b<0) a*=-1, b*=-1;
    c/=x;
    if(m2!=0) m = -(ld)a/b;
    else      m = 0;
    if(b<0) m1=a, m2=-b;
    else    m1=-a, m2=b;
    y = -c/b;
