constexpr double EPS = 1E-10;
// constexpr double EPS = 1E-5;

double add(double a, double b) {
    if (abs(a+b) < EPS * (abs(a) + abs(b))) return 0;
    return a+b;
}

struct P
{
    double x, y;
    P() {}
    P(double x, double y) : x(x), y(y) {}
    P operator + (P p) {
        return P(add(x, p.x), add(y, p.y));
    }
    P operator - (P p) {
        return P(add(x, -p.x), add(y, -p.y));
    }
    P operator * (double d) {
        return P(x*d, y*d);
    }
    double dot(P p) {
        return add(x*p.x, y*p.y);
    }
    double det(P p) {
        return add(x*p.y, -y*p.x);
    }
    double norm()
    {
        return sqrt(x*x+y*y);
    }
};

bool operator < (const P& a, const P& b) {
    return a.x != b.x ? a.x < b.x : a.y < b.y;
}

int ccw(P a, P b, P c)
{
    P v1 = b-a;
    P v2 = c-a;
    if (v1.det(v2) > EPS) return 1;
    if (v1.det(v2) < EPS) return -1;
    if (v1.dot(v2) < EPS) return 2;
    if (v1.norm() < v2.norm()) return -2;
    return 0;
}

double cosine(P a, P b, P c)
{
    P v1 = a - b;
    P v2 = c - b;
    return v1.dot(v2) / v1.norm() / v2.norm();
}

vector<pair<P, int> > convex_hull(vector<pair<P, int> >& ps)
{
    if (ps.size() == 0) return vector<pair<P, int> >(0);
    if (ps.size() == 1) return ps;
    vector<pair<P, int> > points = ps;
    sort(points.begin(), points.end());
    int n = points.size();
    int k=0;
    vector<pair<P, int> > qs(2*n);
    for (int i=0; i<n; i++) {
        while (k>1 && ccw(qs[k-2].first, qs[k-1].first, points[i].first) <= 0) k--;
        qs[k++] = points[i]; 
    }
    for (int i=n-2, t=k; i>=0; i--) {
        while (k>t && ccw(qs[k-2].first, qs[k-1].first, points[i].first) <= 0) k--;
        qs[k++] = points[i];
    }
    qs.resize(k-1);
    return qs;
}


