    for (int i = 0; i < N; ++i){
        cin >> vp[i].first.x >> vp[i].first.y;
        vp[i].second = i;
    }

    auto ch = ConvexHull(vp);
    int n = ch.size();

    vector<DD> res(N);
    for (int i = 0; i < n; ++i) {
        Point prev = rot90(ch[(i-1+n)%n].first - ch[i].first);
        DD prevang = amp(prev);

        Point next = rot90(ch[i].first - ch[(i+1)%n].first);
        DD nextang = amp(next);

        DD ang = nextang - prevang;
        if (ang < 0){
            ang += PI * 2;
        }

        DD prob = ang / (PI * 2);

        int id = ch[i].second;
        res[id] = prob;
    }

    for (int i = 0; i < N; ++i) {
        cout << fixed << setprecision(10) << res[i] << endl;
    }
}

