struct XY_LESS{
	bool operator ()(const pair<P,int>& a, const pair<P,int>& b) {
		if (abs(a.first.imag()-b.first.imag()) < EPS) return (a.first.real() < b.first.real());
		return (a.first.imag() < b.first.imag());
	}
};
rn my_ccw(P a, P b, P c) {
	return (conj(b-a)*(c-a)).imag();
}

template<class IN>
void walk_rightside(IN begin, IN end, vector<int>& v, vector<P> &p) {
	IN cur = begin;
	p.push_back(cur->first);v.push_back(cur->second);
	cur++;
	vector<int>::size_type s = v.size();
	p.push_back(cur->first);v.push_back(cur->second);
	cur++;
	while(cur != end) {
		if (v.size() == s || my_ccw(p[v.size()-2], p.back(), cur->first) > EPS){
			v.push_back(cur->second);p.push_back(cur->first);
			cur++;
		}else{
			v.pop_back();p.pop_back();
		}
	}
	v.pop_back();p.pop_back();
}
vector<int> convex_hull(const vector<P> &v) {
	vector<int> cv;
	if (v.size() <= 1){
		cv.push_back(0);
		return cv; // EXCEPTIONAL
	}
	vector<pair<P,int> > vp;
	REP(i,v.size())vp.push_back(MP(v[i],i));
	sort(ALL(vp), XY_LESS());
	vector<P> p;
	walk_rightside(vp.begin(), vp.end(), cv, p);
	walk_rightside(vp.rbegin(), vp.rend(), cv, p);
	return cv;
}
//}}}

void solve(Int N, vector<Int> x, vector<Int> y){
	vector<P> v;
	REP(i,N)v.push_back(P(x[i],y[i]));
	vector<int> id = convex_hull(v);
	vector<rn> ans(N,0.0);
	if(id.size()==2){
		for(auto &&i:id)ans[i] = 0.5L;
	}else{
		REP(i,id.size()){
			int prev_i = (i-1+id.size())%id.size(), next_i = (i+1)%id.size();
			rn p = arg((v[id[next_i]]-v[id[i]])/(v[id[i]]-v[id[prev_i]]));
			ans[id[i]] = p/(PI*2.0L);
		}
	}
	REP(i,ans.size()){
		printf("%.10Lf\n",ans[i]);
	}
}

