const int maxn = 105;
int n;
struct p{
  LL x,y;
  int id;
}a[maxn];
p Stack[maxn];
int xx,yy;
double ans[maxn];
LL cross(p o,p a,p b)
{
   return (a.x - o.x) * (b.y - o.y) - (a.y - o.y) * (b.x - o.x);
}
LL dot(p o,p a,p b){
  return (a.x - o.x) * (b.x - o.x) + (a.y - o.y) * (b.y - o.y);
}
LL dis(p a,p b){
   return (a.x - b.x) * (a.x - b.x) + (a.y - b.y) * (a.y - b.y);
}
bool cmp1(p a,p b){
   if (a.y == b.y){
    return a.x < b.x; 
   }
   return a.y < b.y;
}
bool cmp2(p a,p b)
{   
    p O;
    O.x = xx;
    O.y = yy;
    if (cross(O,a,b) == 0){
       return dis(O,a) < dis(O,b);
    }
    return cross(O,a,b) > 0;
}
