   }
   for (int i = 0; i <= top; i++){
       int pr = (i + top) % (top + 1);
       int nt = (i + 1) % (top + 1);
       double dpr = sqrt(dis(Stack[i],Stack[pr]));
       double dnt = sqrt(dis(Stack[i],Stack[nt]));
       double cgn = dot(Stack[i],Stack[pr],Stack[nt]) / dpr / dnt;
       ans[Stack[i].id] = (acos(-1.0) - acos(cgn)) / (2  * acos(-1.0));  
   }
   for (int i = 0; i < n; i++){
       printf("%.20lf\n",ans[i]);
   }

}

