  std::vector<int> ix(N);
  std::iota(ix.begin(), ix.end(), 0);
  std::sort(ix.begin(), ix.end(), [&](int l, int r){ return p[l].x < p[r].x; });
  std::vector<int> q(N+2);
  int k = 0;
  for(int i = 0; i < N; ++i) {
    while(k > 1 && (p[q[k-1]] - p[q[k-2]]).det(p[ix[i]] - p[q[k-1]]) <= 0.0) --k;
    q[k++] = ix[i];
  }
  for(int i = N-2, t = k; i >= 0; --i) {
    while(k > t && (p[q[k-1]] - p[q[k-2]]).det(p[ix[i]] - p[q[k-1]]) <= 0.0) --k;
    q[k++] = ix[i];
  }
  q.resize(--k); // remove duplicate of start point
  std::vector<double> th;
  for(int i = 0; i < k; ++i) {
    P pb = p[q[i]], pe = p[q[(i+1)%k]];
    P v({pb.y-pe.y, pe.x-pb.x});
    if(v.det(pe-pb) <= 0) v = -v;
    th.push_back(std::atan2(v.y, v.x));
  }
  std::vector<double> ans(N, 0.0);
  for(int i = 0; i < k; ++i) {
    double thb = th[i], the = th[(i+1)%k];
    double thd = the-thb;
    if(thd < 0) thd += PI*2.0;
    ans[q[(i+1)%k]] = thd/(PI*2.0);
  }
  fin(ans, '\n');
  return 0;
}

