// ref
// https://www.sanfoundry.com/cpp-program-implement-gift-wrapping-algorithm-two-dimensions/
void convexHull(vector<Point> points)
{
    int n = points.size();
    vector<Point> ret;

    // There must be at least 3 points
    if (n < 3)
        return;

    // Initialize Result
    int next[n];
    for (int i = 0; i < n; i++)
        next[i] = -1;

    // Find the leftmost point
    int l = 0;
    for (int i = 1; i < n; i++)
        if (points[i].x < points[l].x)
            l = i;

    // Start from leftmost point, keep moving counterclockwise
    // until reach the start point again
    int p = l, q;
    do
    {
        // Search for a point 'q' such that orientation(p, i, q) is
        // counterclockwise for all points 'i'
        q = (p + 1) % n;
        for (int i = 0; i < n; i++)
            if (orientation(points[p], points[i], points[q]) == 2)
                q = i;

        next[p] = q; // Add q to result as a next point of p
        p = q; // Set p as q for next iteration
    }
    while (p != l);

    // 各点について
    FOR(i, 0, n){
        //凸包内なら確率が0より大きい可能性がある
        bool is_in_convex = false;
        FOR(j, 0, n){
            if(next[j] == i){
                is_in_convex = true;
            }
        }

        if(is_in_convex){
            // 確率を出して、print
            // 点 i は凸包内
            // 凸包内での隣の点は？
            Point left;
            FOR(j, 0, n){
                if(next[j]==i){
                    left = points[j];
                }
            }
            Point right = points[next[i]];
            Point center = points[i];
            printAngle(left, center, right);
        }
        else{
            p(0);
        }

    }
}

