			printf("%.6lf\n", ((double)2 - (dr - dl)) / 4); 
		} else if (fabs(ul - 2) < 1e-8 && fabs(ur - 0) < 1e-8) {
			printf("0\n"); 
		} else {
			double ar = ul - dl + 4;
			//cout << endl << ul << " " << ur << " " << dl << " " << dr << endl; 
			if (ar > 2) ar = dr - ur;
			if (ar > 2) printf("0\n");
			else {
				printf("%.6lf\n", ((double)2 - ar) / 4);
			}
		}
	}
	return 0;
}

