double cross(const Point &a, const Point &b)
{
  return a.x * b.y - a.y * b.x;
}


typedef vector< Point > Polygon;

Polygon Convex_Hull(Polygon& p){
    int n = p.size(), k = 0;
    if(n >= 3){
      sort(p.begin(), p.end());
      vector< Point > ch(2 * n);
      for(int i = 0; i < n; ch[k++] = p[i++]){
        while(k >= 2 && cross(ch[k - 1] - ch[k - 2], p[i] - ch[k - 1]) < 0) --k;
      }
      for(int i = n - 2, t = k + 1; i >= 0; ch[k++] = p[i--]){
        while(k >= t && cross(ch[k - 1] - ch[k - 2], p[i] - ch[k - 1]) < 0) --k;
      }
      ch.resize(k - 1);
      return ch;
    } else {
      return p;
    }
}

signed main(){
    int n;
    cin >> n;
    vector<int> x(n), y(n);
    Polygon po;
    map<P, int> mp;
    rep(i, 0, n){
        cin >> x[i] >> y[i];
        mp[P(x[i], y[i])] = i;
        po.push_back(Point(x[i], y[i]));
    }
    if(n == 2){
        cout << 0.5 << endl << 0.5 << endl;
        return 0;
    }
    Polygon ch = Convex_Hull(po);
    vector<double> ans(n, 0.0);
    int sz = ch.size();
    rep(i, 0, ch.size()){
        Point now = ch[i];
        Point pre = ch[(i - 1 + sz) % sz];
        Point next = ch[(i + 1) % sz];
        // double d1 = (now.y - pre.y) / (now.x - pre.x);
        // double d2 = (next.y - now.y) / (next.x - now.x);
        int id = mp[P((int)now.x, (int)now.y)];
        // double m1 = -1.0 / d1;
        // double m2 = -1.0 / d2;
        double m1;
        double m2;
        if(fabs(now.y - pre.y) < EPS) m1 = INF;
        else m1 = -(now.x - pre.x) / (now.y - pre.y);
        if(fabs(next.y - now.y) < EPS) m2 = INF;
        else m2 = -(next.x - now.x) / (next.y - now.y);
        // cout << d1 << ' ' << d2 << ' ' << m1 << ' ' << m2 << endl;     
        double tn, tmp;
        if(fabs(m1 * m2 + 1.0) < EPS || (fabs(m1) < EPS && m2 > 1e9) || (fabs(m2) && m1 > 1e8)){
            tmp = 0.25;
        }else{
            tn = (m2 - m1) / (1.0 + m1 * m2);
            tmp = atan(tn) / (2.0 * PI);
            if(tn < -EPS){
                tmp = (atan(tn) + PI) / (2.0 * PI);
            }
        }
