struct Point {
    long long x, y;
    int ind;

    Point(long long int x, long long int y, int ind) : x(x), y(y), ind(ind) {}

    Point() {}

    Point operator+(Point p) {
        return {x + p.x, y + p.y, ind};
    }

    Point operator-(Point p) {
        return {x - p.x, y - p.y, ind};
    }
};

long long cross(Point a, Point b) {
    return a.x * b.y - a.y * b.x;
}

long long dot(Point a, Point b) {
    return a.x * b.x + a.y * b.y;
}

long long len2(Point a) {
    return a.x * a.x + a.y * a.y;
}

bool cmp(Point a, Point b) {
    if (cross(a, b) != 0) {
        return cross(a, b) > 0;
    } else {
        return len2(a) < len2(b);
    }
}

long double angle(Point a, Point b) {
    return atan2(cross(a, b), dot(a, b));
}

int main() {
    int n;
    cin >> n;
    vector<Point> a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i].x >> a[i].y;
