    for (int i = 0; i < n; i++) {
        if (a[i].y < mn.y || (a[i].y == mn.y && a[i].x < mn.x)) {
            mn = a[i];
        }
    }
    for (int i = 0; i < n; i++) {
        a[i] = a[i] - mn;
    }

    sort(a.begin(), a.end(), cmp);

    vector<Point> st;
    for (auto p : a) {
        while (st.size() >= 2 && cross(st.back() - st[st.size() - 2], p - st.back()) <= 0) {
            st.pop_back();
        }
        st.push_back(p);
    }

    vector<long double> ans(n);

    if (st.size() == 2) {
        ans[st[0].ind] = ans[st[1].ind] = 0.5;
    } else {
        for (int i = 0; i < st.size(); i++) {
            Point p1 = st[(i + st.size() - 1) % st.size()];
            Point p = st[i];
            Point p2 = st[(i + 1) % st.size()];

