const int MAXN = 105;

struct point {
	int x, y, id;
	friend point operator + (const point &a, const point &b)
	{ return (point) {a.x+b.x, a.y+b.y}; }
	friend point operator - (const point &a, const point &b)
	{ return (point) {a.x-b.x, a.y-b.y}; }
	friend long long operator * (const point &a, const point &b)
	{ return 1ll*a.x*b.y-1ll*a.y*b.x; }
	friend bool operator < (const point &a, const point &b)
	{ return a.x != b.x ? a.x < b.x : a.y < b.y; }
	friend bool operator == (const point &a, const point &b)
	{ return a.x == b.x && a.y == b.y; }
	inline long long len()
	{ return 1ll*x*x+1ll*y*y; }
	inline long long dot(point &a)
	{ return 1ll*x*a.x + 1ll*y*a.y; }
} left_most, pt[MAXN];
point stk[MAXN];
int stk_top = 0, n;
int vis[MAXN];

void get_hull()
{
	stk[++stk_top] = left_most;
	vis[left_most.id] = 1;
	while (1) {
		point cur = stk[stk_top], nxt;
		int flag = -1;
		for (int i = 1; i <= n; i++) {
			if (pt[i] == cur) continue;
			if (flag == -1) nxt = pt[i], flag = 0;
			else {
				long long x = (pt[i]-cur)*(nxt-cur);
				if (x > 0) nxt = pt[i];
				if (x == 0 && (pt[i]-cur).len() <= (nxt-cur).len()) nxt = pt[i];
			}
		}
		if (vis[nxt.id]) break;
		stk[++stk_top] = nxt;
		vis[nxt.id] = 1;
	}
	stk[0] = stk[stk_top], stk[stk_top+1] = stk[1];
}

double ans[MAXN];

const double PI = acos(-1);

int main()
{
	cin >> n;
	left_most = (point) {100000000, 100000000, 0};
	for (int i = 1; i <= n; i++) {
		cin >> pt[i].x >> pt[i].y;
		pt[i].id = i;
		left_most = min(left_most, pt[i]);
	}
	get_hull();
	for (int i = 1; i <= stk_top; i++) {
		point x = stk[i-1]-stk[i], y = stk[i+1]-stk[i];
		double ang_cos = x.dot(y)/sqrt(x.len())/sqrt(y.len());
		double ang = acos(ang_cos);
		ans[stk[i].id] = (PI-ang)/PI/2;
	}
	for (int i = 1; i <= n; i++)
		printf("%.10lf\n", ans[i]);
	return 0;
}

