const int maxn=1e2+10;
struct node{
	int x,y,id;
}a[maxn];
inline bool cmp(const node &lhs,const node &rhs){
	return lhs.x==rhs.x?lhs.y>rhs.y:lhs.x<rhs.x;
}
inline bool Cmp(const node &lhs,const node &rhs){
	return lhs.id<rhs.id;
}
int stk[maxn],ans[maxn];
double Ans[maxn],slp[maxn];
inline int read(){
	int x=0,flag=1;
	char ch=getchar();
	while(!isdigit(ch) && ch!='-')ch=getchar();
	if(ch=='-')flag=-1,ch=getchar();
	while(isdigit(ch))x=(x<<3)+(x<<1)+ch-'0',ch=getchar();
	return x*flag;
}
inline double Slope(int idx,int idy){
	if(a[idx].x==a[idy].x){
		if(a[idx].y>a[idy].y)return INF;
		else return -INF;
	}
	return (a[idx].y-a[idy].y)*1.0/(a[idx].x-a[idy].x);
}
inline double arcle(int idx,int idy){
	if(a[idx].x==a[idy].x){
		if(a[idx].y>a[idy].y)return 0;
		else return Pi;
	}
	if(a[idx].y==a[idy].y){
		if(a[idx].x<a[idy].x)return Pi/2;
		else return 3*Pi/2;
	}
	double slope=-1.0/Slope(idx,idy),arc=atan(slope);
	if(arc<0)arc+=Pi;
	if(a[idx].x<a[idy].x)return arc;
	else return arc+Pi;
}
int main(){
	int i,j,k,m,n,pos;
	n=read();
	for(i=1;i<=n;i++){
		a[i].x=read();a[i].y=read();a[i].id=i;
	}
	sort(a+1,a+n+1,cmp);
	stk[1]=a[1].id;stk[2]=a[2].id;int top=2;
	for(i=3;i<=n;i++){
		while(top>1 && Slope(stk[top],stk[top-1])>Slope(i,stk[top]))top--;
		stk[++top]=a[i].id;
	}
	for(i=1;i<top;i++)ans[i]=stk[i];pos=top;
	reverse(a+1,a+n+1);
	stk[1]=a[1].id;stk[2]=a[2].id;
	for(i=3;i<=n;i++){
		while(top>1 && Slope(stk[top],stk[top-1])>Slope(i,stk[top]))top--;
		stk[++top]=a[i].id;
	}
	for(i=pos;i<pos+top-1;i++)ans[i]=stk[i-pos+1];pos=pos+top-2;
	sort(a+1,a+n+1,Cmp);
	ans[0]=ans[pos];ans[pos+1]=ans[1];
	for(i=0;i<=pos;i++)slp[i]=arcle(ans[i+1],ans[i]);
	for(i=1;i<=pos;i++)Ans[ans[i]]=slp[i]-slp[i-1];
	for(i=1;i<=n;i++){
		if(Ans[i]<0)Ans[i]+=2*Pi;
		printf("%.15lf\n",Ans[i]/(2*Pi));
	}
	return 0;
}

