	swap(A,B);
	long double a = dist(B,C);
	long double b = dist(A,C);
	long double c = dist(A,B);
	long double x = (b * b + c * c - a * a) / (2.0 * b * c);
	if (2.0 * b * c < 0.00000000001) return PI;
	dbg(x);
	return acos(x);
}

