	    }
    	return 0;
    }

    hull.push_back(hull[0]);
    for (int i=1;i+1<hull.size();i++){
    	long double a = getAngle(hull[i-1], hull[i], hull[i+1]);
    	ans[hull[i].ID] = (PI - a) / (2 * PI);
    }
    long double a = getAngle(hull[hull.size() - 2], hull[0], hull[1]);
    ans[hull[0].ID] = (PI - a) / (2 * PI);

    for (int i=1;i<=n;i++){
    	cout << fixed << setprecision(9) << ans[i] << '\n';
    }

    return 0;
}

