std::vector<Point> convex_hull(std::vector<Point>& p) {
    int n = (int)p.size();
    std::sort(p.begin(), p.end());
    int k = 0;
    std::vector<Point> h(n * 2);
    for (int i = 0; i < n; ++i) {
        while (k > 1 && (h[k - 1] - h[k - 2]).cross(p[i] - h[k - 1]) <= 0) --k;
        h[k++] = p[i];
    }
    for (int i = n - 2, t = k; i >= 0; --i) {
        while (k > t && (h[k - 1] - h[k - 2]).cross(p[i] - h[k - 1]) <= 0) --k;
        h[k++] = p[i];
    }
    h.resize(k - 1);
    return h;
}

int n;
void solve() {
    cin >> n;
    vector<Point> p(n);
    rep(i, n) {
        cin >> p[i].x >> p[i].y;
        p[i].id = i;
    }
    auto h = convex_hull(p);
    auto m = sz(h);
    vector<double> rad(m);
    rep(i, m) {
        int j = (i + 1) % m;
        auto q = (h[i] - h[j]).rotate90();
        rad[i] = atan2(q.y, q.x);
    }
    vector<double> ans(n);
    rep(i, m) {
        int j = (i + 1) % m;
        auto a = rad[j] - rad[i];
        if (a < 0) a += 2 * M_PI;
        if (a > 2 * M_PI) a -= 2 * M_PI;
        ans[h[j].id] = a / (2 * M_PI);
    }
    rep(i, n) cout << ans[i] << endl;
}

