    }
    debug(pi);
    vector<ld> ans(n);
    rep(i,0,n){
        vector<ld> t;
        rep(j,0,n){
            if(v[i] == v[j])continue;
            t.emplace_back(atan2(v[i].second - v[j].second, v[i].first - v[j].first));
