using namespace std;
int N;
struct P{
	int x,y;
	P(){
	};
	P(int x,int y):x(x),y(y){}
	P operator +(P p){
		return P(x+p.x,y+p.y);
	}
	P operator -(P p){
		return P(x-p.x,y-p.y);
	}
	int dot(P p){
		return x*p.x+y*p.y;
	}
	int det(P p){
		return x*p.y-y*p.x;
	}
	bool operator ==(P p){
		return x==p.x&&y==p.y;
	}
	double len(){
		return sqrt(x*x+y*y);
	}
};
P ps[105];
P po[105];
double pro[105];

bool cmp_x(const P &p,const P &q){
	if(p.x!=q.x) return p.x<q.x;
	return p.y<q.y;
}
vector<P> convex_hull(P *ps,int n){
	sort(ps,ps+n,cmp_x);
	int k=0;
	vector<P> qs(n*2);
	for(int i=0;i<n;i++){
		while(k>1&&(qs[k-1]-qs[k-2]).det(ps[i]-qs[k-1])<=0) k--;
		qs[k++]=ps[i];
	}
	for(int i=n-2,t=k;i>=0;i--){
		while(k>t && (qs[k-1]-qs[k-2]).det(ps[i]-qs[k-1])<=0) k--;
		qs[k++]=ps[i];
	}
	qs.resize(k-1);
	return qs;
}
void calcPro(int i,P a,P b){
	pro[i]=acos(a.dot(b)/a.len()/b.len())/(2*3.14159265358979);
}
int main(){
	scanf("%d",&N);
	int x,y;
	for(int i=0;i<N;i++){
		scanf("%d%d",&x,&y);
		po[i].x=ps[i].x=x;
		po[i].y=ps[i].y=y;
	}
	if(N==1){
		printf("1\n");
		return 0;
	}
	if(N==2){
		printf("0.5\n0.5\n");
		return 0;
	}
	vector<P> qs=convex_hull(ps,N);
	int n=qs.size();
	calcPro(0,qs[0]-qs[n-1],qs[1]-qs[0]);
	for(int i=1;i<n-1;i++){
		calcPro(i,qs[i]-qs[i-1],qs[i+1]-qs[i]);
	}
	calcPro(n-1,qs[n-1]-qs[n-2],qs[0]-qs[n-1]);
	//print
	bool isok=false;
	for(int i=0;i<N;i++){
		isok=false;
		for(int j=0;j<n;j++){
			if(po[i]==qs[j]){
				printf("%.6f\n",pro[j]);
				isok=true;
			}
		}
		if(!isok) printf("0.000000\n");
	}
	return 0;
}

