//3点p0,p1,p2の状態を求める
//https://onlinejudge.u-aizu.ac.jp/status/users/nii/submissions/1/CGL_1_C/judge/3148083/C++14
void AOJ_CGL1C(){
	point p0,p1;
	cin>>p0>>p1;
	int q;
	cin>>q;
	while(q--){
		point p2;
		cin>>p2;
		int t=ccw(p0,p1,p2);
		if(t==CCW_COUNTER_CLOCKWISE){
			//p0,p1,p2が反時計回り
			cout<<"COUNTER_CLOCKWISE"<<endl;
		}else if(t==CCW_CLOCKWISE){
			//p0,p1,p2が時計回り
			cout<<"CLOCKWISE"<<endl;
		}else if(t==CCW_ONLINE_BACK){
			//p2,p0,p1がこの順で同一直線上
			cout<<"ONLINE_BACK"<<endl;
		}else if(t==CCW_ONLINE_FRONT){
			//p0,p1,p2がこの順で同一直線上
			cout<<"ONLINE_FRONT"<<endl;
		}else{
			//線分p0-p1上にp2
			cout<<"ON_SEGMENT"<<endl;
		}
	}
}
