const double EPS=1e-6;
const double PI=3.14159265358979;
typedef complex<double> C;
#define cx real()
#define cy imag()

double Dist(C a,C b){ return hypot(a.cx-b.cx,a.cy-b.cy); }
double dot(C a, C b) { return a.cx * b.cx + a.cy * b.cy; } // |a||b|cosθ
double det(C a, C b) { return a.cx * b.cy - a.cy * b.cx; } // |a||b|sinθ
bool isZero(double a) { return abs(a) < EPS; } // a == 0
bool isPointOnLine(C a, C b, C c) { return isZero(det(b - a, c - a)); } // a-b <- c
double Radian(C a,C b,C c){//∠abc
    return acos(dot(a-b,c-b)/Dist(C(0,0),a-b)/Dist(C(0,0),c-b));
}
bool comp_C(const pair<C,ll>& c1, const pair<C,ll>& c2) {
  if (c1.first.cx != c2.first.cx) return c1.first.cx < c2.first.cx;
  return c1.first.cy < c2.first.cy;
} 
vector<pair<C,ll>> convex_hull(pair<C,ll>* ps, ll n) {
  sort(ps, ps+n, comp_C);
  ll k = 0;
  vector<pair<C,ll>> qs(n*2);
  for (ll i = 0; i < n; i++) {
    while (k > 1 && det((qs[k-1].first - qs[k-2].first), (ps[i].first - qs[k-1].first)) <= EPS) k--;
    qs[k++] = ps[i];
  }
  for (ll i = n-2, t = k; i >= 0; i--) {
    while (k > t && det((qs[k-1].first - qs[k-2].first), (ps[i].first - qs[k-1].first)) <= EPS) k--;
    qs[k++] = ps[i];
  }
  qs.resize(k-1);
  return qs;
}

double RadPercent(ll i,ll i1,ll i2,vector<pair<C,ll>>& v){//∠i i1 i2
    return (PI-Radian(v[i].first,v[i1].first,v[i2].first))/(2*PI);
}

ll N;
pair<C,ll> p[101];
double ans[101]={};
int main(){
    cin>>N;
    for(ll i=0;i<N;i++){
        ll x,y;
        cin>>x>>y;
        p[i]=make_pair(C(x,y),i);
    }
    auto v=convex_hull(p,N);
    ans[v[0].second]=RadPercent(v.size()-1,0,1,v);
    for(ll i=1;i<v.size()-1;i++){
        ans[v[i].second]=RadPercent(i-1,i,i+1,v);
    }
    ans[v[v.size()-1].second]=RadPercent(v.size()-2,v.size()-1,0,v);
    for(ll i=0;i<N;i++){
        cout<<setprecision(10)<<ans[i]<<endl;
    }
    return 0;
}

