using namespace std;

class Point{
public:
    double x, y;
    int original_index;

    Point(double x = 0, double y = 0): x(x), y(y){}

    bool operator < (const Point &p) const{
        return x != p.x ? x < p.x : y < p.y;
    }
    Point operator - (Point p) {
        return Point(x - p.x, y - p.y);
    }

    double cross(Point p){
        return x*p.y - y*p.x;
    }
    bool ccw(Point p){
        if(this->cross(p) <= 0){
            return true;
        }else{
            return false;
        }
    }
    double dot(Point p){
        return x*p.x + y*p.y;
    }
    double norm(){
        return sqrt(x*x + y*y);
    }
    double angle(Point p){
        return acos(this->dot(p) / (this -> norm() * p.norm()));
    }

};

typedef Point Vector;

Point p[100];
int N;
vector<Point> u, l;
vector<Point> convex;
double ans[100];


int main(){
    cin >> N;
    for(int i = 0; i < N; i++){
        double x, y;
        cin >> x >> y;
        p[i].x = x;
        p[i].y = y;
        p[i].original_index = i;
    }

    if(N == 2){
        cout << 0.5 << endl << 0.5 << endl;
        return 0;
    }

    sort(p, p+N);

    u.push_back(p[0]);
    u.push_back(p[1]);
    l.push_back(p[N-1]);
    l.push_back(p[N-2]);

    for(int i = 2; i < N; i++){
        for(int n = u.size(); n >= 2 && !(u[n-1] - u[n-2]).ccw(p[i] - u[n-2]); n--){
            u.pop_back();
        }
        u.push_back(p[i]);
    }
    for(int i = N - 3; i >= 0; i--){
        for(int n = l.size(); n >= 2 && !(l[n-1] - l[n-2]).ccw(p[i] - l[n-2]); n--){
            l.pop_back();
        }
        l.push_back(p[i]);
    }


    for(int i = 0; i < u.size(); i++){
        convex.push_back(u[i]);
    }

    for(int i = 1; i < l.size()-1; i++){
        convex.push_back(l[i]);
    }

    for(int i = 0; i < convex.size(); i++){
        Point now = convex[i];
        Point before = convex[(i-1+convex.size()) % convex.size()];
        Point after = convex[(i+1) % convex.size()];
        Vector bn = now - before;
        Vector orth1 = Vector(bn.y, -bn.x);
        Vector na = after - now;
        Vector orth2 = Vector(na.y, -na.x);
        ans[now.original_index] = orth1.angle(orth2) / (2*M_PI);
    }
    for(int i = 0; i < N; i++){
        printf("%.9lf\n", ans[i]);
    }


}

