typedef complex<double> P;
namespace std {
	bool operator < (const P& a, const P& b) {
		return real(a) != real(b) ? real(a) < real(b) : imag(a) < imag(b);
	}
}
double cross(const P& a, const P& b) {
	return imag(conj(a)*b);
}
double dot(const P& a, const P& b) {
	return real(conj(a)*b);
}

int ccw(P a, P b, P c) {
	b -= a; c -= a;
	if (cross(b, c) > 0)   return +1;       // counter clockwise
	if (cross(b, c) < 0)   return -1;       // clockwise
	if (dot(b, c) < 0)     return +2;       // c--a--b on line
	if (norm(b) < norm(c)) return -2;       // a--b--c on line
	return 0;
}

vector<P> convex_hull(vector<P> ps) {
	int n = ps.size(), k = 0;
	sort(ps.begin(), ps.end());
	vector<P> ch(2 * n);
	for (int i = 0; i < n; ch[k++] = ps[i++]) // lower-hull
		while (k >= 2 && ccw(ch[k - 2], ch[k - 1], ps[i]) <= 0) --k;
	for (int i = n - 2, t = k + 1; i >= 0; ch[k++] = ps[i--]) // upper-hull
		while (k >= t && ccw(ch[k - 2], ch[k - 1], ps[i]) <= 0) --k;
	ch.resize(k - 1);
	return ch;
}

void solve() {
	int N; cin >> N;
	vector<P> ps;
	REP(i, N) {
		double x, y; cin >> x >> y;
		ps.push_back(P(x,y));
	}
	vector<P> res = convex_hull(ps);
	P sum;
	REP(i, res.size()) {
		sum += res[i];
	}
	P center = P(sum.real() / res.size(), sum.imag() / res.size());
	double dsum = 0.0;
	REP(i,res.size()){
		res[i] -= center;
	}
	vector<double> test(res.size());
	double summm = 0;
	REP(i, res.size()) {
		int prv = i;
		int tar = (i + 1) % res.size();
		int nxt = (i + 2) % res.size();
		P p1 = res[tar] - res[prv];
		P p2 = res[nxt] - res[tar];
		double a = abs(arg(p1) - arg(p2));
		if (a > pi) a = 2 * pi - a;
		test[tar]  = (a / (2 * pi));
	}
	vector<pair<P, double> > pd;
	REP(i, res.size()) {
		pd.push_back(make_pair(P(res[i] + center), test[i]));
	}
	vector<double> output(ps.size());
	REP(i, pd.size()) {
		auto result = std::find(ALL(ps), pd[i].first);
		size_t index = std::distance(ps.begin(), result);
		output[index] = pd[i].second;
	}
	REP(i, N) {
		cout << output[i] << endl;
	}
}

