long double ABS(long double x)
{
	return x < 0.0 ? -x : x;
}
long double arccos(long double x)
{
	if(x < -1.0 + EPS) return pi;
	if(x > 1.0 - EPS) return 0.0;
	return acos(x);
}
struct cmplxU{
	long double dx, dy;
	cmplxU()
	{
		dx = dy = 0.0;
	}
	cmplxU(long double x, long double y, const void* t)
	{
		dx = x / sqrt(x * x + y * y);
		dy = y / sqrt(x * x + y * y);
	}
	cmplxU(long double d)
	{
		dx = cos(d);
		dy = sin(d);
	}
	cmplxU(long double x,long double y)
	{
		dx = x; dy = y;
	}
	bool MTH() const
	{
		return dy < 0.0;
	}
	cmplxU invimag() const
	{
		return cmplxU(dx, -dy);
	}
	cmplxU operator*(const cmplxU& oth) const
	{
		return cmplxU(dx * oth.dx - dy * oth.dy, dx * oth.dy + dy * oth.dx);
	}
	cmplxU operator/(const cmplxU& oth) const
	{
		return operator*(oth.invimag());
	}
	bool operator <(const cmplxU& oth) const
	{
		if(MTH() != oth.MTH()) return oth.MTH();
		return MTH() ^ (dx > oth.dx);
	}
	bool operator ==(const cmplxU& oth) const
	{
		return dx == oth.dx && dy == oth.dy;
	}
	long double direc() const
	{
		long double res = arccos(dx);
		if(ABS(sin(res) - dy) >= EPS) res = 2 * pi - res;
		return res;
	}
};
