struct vect {
    ll x, y;
    vect(ll x_, ll y_) : x(x_), y(y_) {}
    vect(point a, point b) {
        x = b.x - a.x;
        y = b.y - a.y;
    }
    ll sqlen() {
        return x * x + y * y;
    }
};

vect perpendicular(point a, point b) {
    return vect(b.x - a.x, a.y - b.y);
}

ll cp(vect u, vect v) {
    return u.x * v.y - v.x * u.y;
}

ll dp(vect u, vect v) {
    return u.x * v.x + u.y * v.y;
}

ld angle(vect u, vect v) {
    return atan2(cp(u, v), dp(u, v));
}

vector<int> convex_hull(vector<point> p) {
    int n = p.size();
    int first = 0;
    forn(i, n) {
        if (mp(p[i].x, p[i].y) < mp(p[first].x, p[first].y))
            first = i;
    }
    vector<int> ind(n);
    iota(all(ind), 0);
    sort(all(ind), [&](int i, int j) -> bool {
        if (cp(vect(p[first], p[i]), vect(p[first], p[j])) == 0)
            return vect(p[first], p[i]).sqlen() < vect(p[first], p[j]).sqlen();
        else
            return cp(vect(p[first], p[i]), vect(p[first], p[j])) > 0;
    });
    vector<int> ans = {ind[0], ind[1]};
    forrn(i, 2, n) {
        point c = p[ind[i]];
        while (ans.size() > 1 && cp(vect(p[ans[ans.size() - 2]], p[ans.back()]), vect(p[ans.back()], c)) <= 0)
            ans.pop_back();
        ans.push_back(ind[i]);
    }
    return ans;
}

