// http://judge.u-aizu.ac.jp/onlinejudge/description.jsp?id=CGL_4_A
// 凸包
Polygon convex_hull(Polygon &p) {
    int n = (int)p.size(), k = 0;
    if(n <= 2) return p;
    sort(p.begin(), p.end());
    vector<Point> ch(2 * n);
    for(int i = 0; i < n; ch[k++] = p[i++]) {
        while(k >= 2 && cross(ch[k - 1] - ch[k - 2], p[i] - ch[k - 1]) < EPS)
            --k;
    }
    for(int i = n - 2, t = k + 1; i >= 0; ch[k++] = p[i--]) {
        while(k >= t && cross(ch[k - 1] - ch[k - 2], p[i] - ch[k - 1]) < EPS)
            --k;
    }
    ch.resize(k - 1);
    return ch;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(0);

    int n;
    cin >> n;
    Points p(n);
    rep(i, n) cin >> p[i];
    Points ps = p;
    Polygon pol = convex_hull(ps);
    map<Point, double> mp;
    rep(i, pol.size()) {
        Point p1 = pol[i];
        Point p2 = pol[(i + 1) % pol.size()];
        Point p3 = pol[(i + 2) % pol.size()];
        double rad = acos(dot(p3 - p2, p2 - p1) / abs(p3 - p2) / abs(p2 - p1));
        mp[p2] = rad / (PI * 2);
    }

    for(Point P : p) {
        cout << fixed << setprecision(15) << mp[P] << endl;
    }

    return 0;
}

