				if (min > dist) {
					min = dist;
					mii = j;
				}
			}
			ans[mii] = t;
		}
	}

	double sum = 0;
	REP(i, n) {
		sum += ans[i];
	}
	REP(i, n) {
		ans[i] /= sum;
	}
	REP(i, n) {
		FOUT(12, ans[i])BR;
	}
	return 0;
}

