struct pct{
    double x, y;
    int id;

    inline bool operator < ( const pct &a ) const {
        if ( x != a.x ) {
            return ( x < a.x );
        }
        return ( y < a.y );
    }
} v[ MAXN + 1 ];

pct st[ MAXN + 1 ];
vector< pct > sol;

inline bool cw( pct a, pct b, pct c ) {
    return ( (b.x - a.x) * (c.y - b.y) - (b.y - a.y) * (c.x - b.x) <= 0 );
}

double answer[1 + MAXN];
const double PI = acos(-1);

double Angle(pct c, pct a, pct b) {
    pct e = {a.x - c.x, a.y - c.y}, f = {b.x - c.x, b.y - c.y};
    double pe = atan2(e.y, e.x), pf = atan2(f.y, f.x);
    if (pe < pf)
        swap(pe, pf);
    double alpha = min(2 * PI - (pe - pf), pe - pf);
    return PI - alpha;
}

