bool cmp_x(const P& p,const P& q){
    if(p.x!=q.x){
        return p.x<q.x;
    }
    return p.y<q.y;
}
vector<P> convex_hull(P* ps,int n){
    sort(ps,ps+n,cmp_x);
    int k=0;
    vector<P> qs(n*2);
    //下側凸包
    for(int i=0;i<n;i++){
        while(k>1&&(qs[k-1]-qs[k-2]).det(ps[i]-qs[k-1])<=0){
            k--;
        }
        qs[k++]=ps[i];
    }
    //上側凸包
    for(int i=n-2,t=k;i>=0;i--){
        while(k>t&&(qs[k-1]-qs[k-2]).det(ps[i]-qs[k-1])<=0){
            k--;
        }
        qs[k++]=ps[i];
    }
    qs.resize(k-1);
    return qs;
}
double dist(P p,P q){
    return (p-q).dot(p-q);
}

