			dx[1] *= -1;
			normal[i].push_back(dx);
		}
	}
	vector<vector<double>> dead(N, vector<double>(2, 0.0));
	for (int i = 0; i < N; i++) {
		for (int j = 0; j < normal[i].size(); j++) {
			double theta;
