enum { CCW = 1, CW = -1, ON = 0 };
int ccw(const P &a, P b, P c) {
	b -= a; c -= a;
	int rdir = cross(b, c);
	if (rdir > 0) return CCW;
	if (rdir < 0) return CW;
	return ON;
}

vector<pair<P, int>> convex_hull(vector<pair<P, int>>& ps) {
	int n = ps.size(), k = 0;
	sort(ps.begin(), ps.end());
	vector<pair<P, int>> ch(2 * n);
	for (int i = 0; i < n; ch[k++] = ps[i++]) // lower-hull
		while (k >= 2 && ccw(ch[k - 2].first, ch[k - 1].first, ps[i].first) <= 0) --k;

	for (int i = n - 2, t = k + 1; i >= 0; ch[k++] = ps[i--]) // upper-hull
		while (k >= t && ccw(ch[k - 2].first, ch[k - 1].first, ps[i].first) <= 0) --k;

	ch.resize(k - 1);

	return ch;
}

