#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef long double ld;
typedef pair <int, int> pii;

const int MAXN = 1e2 + 5;
const ld PI = acos(-1.0);

int N;
pii p[MAXN];
map <pii, int> idx;
vector <pii> g, d, hull;
ld sol[MAXN];

void load() {
	scanf("%d", &N);
	for (int i = 0; i < N; i++) {
		scanf("%d%d", &p[i].first, &p[i].second);
		idx[p[i]] = i;
	}
}

bool ccw(pii a, pii b, pii c) {
	return (ll)a.first * (b.second - c.second) + (ll)b.first * (c.second - a.second) + (ll)c.first * (a.second - b.second) >= 0;
}

ld dot(pii a, pii b) {
	return (ld)a.first * b.first + (ld)a.second * b.second;
}

void solve() {
	sort(p, p + N);

	for (int i = 0; i < N; i++) {
		while (g.size() > 1 && ccw(g[(int)g.size() - 2], g.back(), p[i]))
			g.pop_back();
		g.push_back(p[i]);
	}

	for (int i = N - 1; i >= 0; i--) {
		while (d.size() > 1 && ccw(d[(int)d.size() - 2], d.back(), p[i]))
			d.pop_back();
		d.push_back(p[i]);
	}	

	for (int i = 1; i < g.size(); i++)
		hull.push_back(g[i]);

	for (int i = 1; i < d.size(); i++)
		hull.push_back(d[i]);

	int sz = hull.size();
	for (int i = 0; i < sz; i++) {
		int curr = idx[hull[i]];
		if (sz == 2) {
			sol[curr] = 0.5;
			continue;
		}
		pii prev = hull[(i - 1 + sz) % sz];
		pii nxt = hull[(i + 1) % sz];
		pii x = {prev.first - hull[i].first, prev.second - hull[i].second};
		pii y = {nxt.first - hull[i].first, nxt.second - hull[i].second};
		sol[curr] = 0.5 - acos(dot(x, y) / sqrt(dot(x, x) * dot(y, y))) / (2 * PI);
	}

	for (int i = 0; i < N; i++)
		printf("%.20Lf\n", sol[i]);
}

int main() {
	load();
	solve();
	return 0;
}

