  while (t < '0' || '9' < t) {
    t = getchar_unlocked();
  }
  x = t - '0';
  t = getchar_unlocked();
  while ('0' <= t && t <= '9') {
    x *= 10; x += t - '0';
    t = getchar_unlocked();
  }
#endif
}

