int main() {
    cin >> N;
    for (int j = 0; j < N; ++j) cin >> x[j] >> y[j];

    vector<vector<vector<pair<double, double>>>> rg(N);

    for (int j = 0; j < N; ++j) {
        for (int k = j+1; k < N; ++k) {
            double hx = -(y[j] - y[k]), hy = x[j] - x[k];
            complex<double> c(hx, hy);
            double a1 = arg(c);

            vector<pair<double, double>> vec1, vec2;
            if (a1 < 0) {
                vec1.emplace_back(a1+M_PI, a1+2*M_PI);

                vec2.emplace_back(0, a1+M_PI);
                vec2.emplace_back(a1+2*M_PI, 2*M_PI);
            } else {
                vec1.emplace_back(0, a1);
                vec1.emplace_back(a1+M_PI, 2*M_PI);

                vec2.emplace_back(a1, a1+M_PI);
            }

            rg[j].push_back(vec1);
            rg[k].push_back(vec2);
        }
    }

    cout << fixed << setprecision(10) << endl;
    for (int j = 0; j < N; ++j) { sort(begin(rg[j]), end(rg[j])); }
    for (int j = 0; j < N; ++j) {
        vector<pair<double, double> > res;
        res.emplace_back(0, 2 * M_PI);
        for (vector<pair<double, double> > vec : rg[j]) {
            vector<pair<double, double> > nxt;
            for (auto r1 : res) {
                for (auto r2 : vec) {
                    if (max(r1.first, r2.first) >= min(r1.second, r2.second)) continue;
                    nxt.emplace_back(max(r1.first, r2.first), min(r1.second, r2.second));
                }
            }
            res = nxt;
        }

        double prob = 0;
        for (auto pr : res) {
            prob += (pr.second - pr.first) / (2 * M_PI);
        }
        cout << prob << endl;
    }
    return 0;
}

