    vector<double> Ngrad(N);

    for (int i = 0; i < N; i++) {
        //iが一番となるような範囲(角度)を求める

        vector<pair<double, int>> st;
        const int ok = 0, ng = 1;
        for (int j = 0; j < N; j++) {
            if (j == i) {
                continue;
            }

            if (y[i] == x[j]) {
                //y座標が同じ
                if (x[i] > x[j]) {
                    //点iの方が右にある場合90から270度がokかもしれない
                    st.push_back({ 90, ng });
                } else {
                    st.push_back({ 90, ok });
                }
            } else {
                //垂直二等分線の公式
                //y = (x2 - x1) / (y2 - y1) x + 1/2 (x2^2 - x1^2 + y2^2 - y1^2)

                //垂直二等分線の傾きを出す
                double grad = (double)-(x[j] - x[i]) / (y[j] - y[i]);

                //点iは垂直二等分線のどちら側にあるのか
                double a = grad * x[i] + (pow(x[j], 2) - pow(x[i], 2) + pow(y[j], 2) - pow(y[i], 2)) / 2;
                if (y[i] > a) {
                    //上側
                    if (grad >= 0) {
                        st.push_back({ atan(grad) * 180 / PI, ok });
                    } else {
                        st.push_back({ atan(grad) * 180 / PI + 180, ng });
                    }
                } else {
                    //下側
                    if (grad >= 0) {
                        st.push_back({ atan(grad) * 180 / PI, ng });
                    } else {
                        st.push_back({ atan(grad) * 180 / PI + 180, ok });
                    }
                }
            }
        }

        sort(st.begin(), st.end());

        double ans = 0;
        double start = 0, end = 360;

        for (int i = 0; i < st.size(); i++) {
            //printf("st[%d] = (%f, %d)\n", i, st[i].first, st[i].second);
            if (st[i].second == ok) {
                start = max(start, st[i].first);
                end = min(end, st[i].first + 180);
            } else {
                ans += max(st[i].first - start, 0.0);
                start = st[i].first + 180;
            }
        }

        ans += max(end - start, 0.0);

        Ngrad[i] = ans;
    }

    for (int i = 0; i < N; i++) {
        printf("%.6f\n", Ngrad[i] / 360);
    }
}

