const double EPS=1e-10;
double M_PI=atan(1.0)*4.0;
double add(double a,double b){
    if(abs(a+b)<EPS*(abs(a)+abs(b)))return 0;
    return a+b;
}
struct P{
    double x,y;
    P(){}
    P(double x,double y):x(x),y(y){
    }
    P operator + (P p){
        return P(add(x,p.x),add(y,p.y));
    }
    P operator - (P p){
        return P(add(x,-p.x),add(y,-p.y));
    }
    P operator * (double d){
        return P(x*d,y*d);
    }
    double dot(P p){
        return add(x*p.x,y*p.y);
    }
    double det(P p){
        return add(x*p.y,-y*p.x);
    }
};
bool cmp_x(const P&p,const P& q){
    if(p.x!=q.x)return p.x<q.x;
    return p.y<q.y;
}
vector<P> convex_hull(P* ps,int n){
    sort(ps,ps+n,cmp_x);
    int k=0;
    vector<P>qs(n*2);
    REP(i,n){
        while(k>1&&(qs[k-1]-qs[k-2]).det(ps[i]-qs[k-1])<=0)k--;
        qs[k++]=ps[i];
    }
    for(int i=n-2,t=k;i>=0;i--){
        while(k>t&&(qs[k-1]-qs[k-2]).det(ps[i]-qs[k-1])<=0)k--;
        qs[k++]=ps[i];
    }
    qs.resize(k-1);
    return qs;
}
P ps[101];
int main(){
    int N;
    cin>>N;
    map<PII,int>mp;
    REP(i,N){
        int x,y;
        cin>>x>>y;
        ps[i]=P(x,y);
        mp[MP(x,y)]=i;
    }
    if(N==2){
        cout<<0.5<<endl;
        cout<<0.5<<endl;
        return 0;
    }
    vector<P>qs=convex_hull(ps,N);
    P divp;
    vector<double>res(N,0);
    long double sum=0.0;
    int Q=SZ(qs);
    REP(i,SZ(qs)){
        divp=qs[(i+1)%Q]-qs[i%Q];
        double d1=sqrt(divp.x*divp.x+divp.y*divp.y);
        P p1=divp;
        divp=qs[(i-1+Q)%Q]-qs[i%Q];
        double d2=sqrt(divp.x*divp.x+divp.y*divp.y);
        P p2=divp;
        double as=acos(p1.dot(p2)/(d1*d2));
        //cout<<mp[MP(qs[i].x,qs[i].y)]<<" "<<as<<endl;
        //cout<<mp[MP(qs[i].x,qs[i].y)]<<" "<<M_PI-abs(as)<<endl;
        sum+=abs(M_PI-as);
        res[mp[MP((int)qs[i].x,(int)qs[i].y)]]=abs(M_PI-as);
    }
    REP(i,N){
        cout<<fixed<<setprecision(10)<<res[i]/sum<<endl;
    }
    return 0;
}

