vector<V> convexhull_line(vector<V> &ps) {    int n = (int) ps.size();    if (n <= 2) { return ps; }    vector<V> res(2 * n);    std::sort(ps.begin(), ps.end(), [&](V &l, V &r) { if (l.x != r.x)return l.x < r.x; else return l.y < r.y; });    int k = 0;    for (int i = 0; i < n; ++i) {        if (k >= 2) {            while (cross(res[k - 1] - res[k - 2], ps[i] - res[k - 2]) < -eps) {                --k;                if (k < 2) break;            }        }        res[k] = ps[i];        ++k;    }    int t = k + 1;    for (int i = n - 2; i >= 0; --i) {        if (k >= t) {            while (cross(res[k - 1] - res[k - 2], ps[i] - res[k - 2]) < -eps) {                --k;                if (k < t) break;            }        }        res[k] = ps[i];        ++k;    }    res.resize(k - 1);    return res;}

vi convexhull_line_i(vector<V> &ps) {    int n = (int) ps.size();    if (n <= 2) {        if (n == 1)return vi{0};        else return vi{0, 1};    }    vi res(2 * n);    vi ind = iota(0, n);    std::sort(ind.begin(), ind.end(), [&](int l, int r) {        if (ps[l].x != ps[r].x)return ps[l].x < ps[r].x;        else return ps[l].y < ps[r].y;    });    int k = 0;    for (int i = 0; i < n; ++i) {        if (k >= 2) {            while (cross(ps[res[k - 1]] - ps[res[k - 2]], ps[ind[i]] - ps[res[k - 2]]) < -eps) {                --k;                if (k < 2) break;            }        }        res[k] = ind[i];        ++k;    }    int t = k + 1;    for (int i = n - 2; i >= 0; --i) {        if (k >= t) {            while (cross(ps[res[k - 1]] - ps[res[k - 2]], ps[ind[i]] - ps[res[k - 2]]) < -eps) {                --k;                if (k < t) break;            }        }        res[k] = ind[i];        ++k;    }    res.resize(k - 1);    return res;}/*@formatter:on*/


