//ベクトルの定義
struct Vector2D{
    double x;
    double y;
};

//ベクトルの長さを計算する
double get_vector_length( Vector2D v ) {
    return pow( ( v.x * v.x ) + ( v.y * v.y ), 0.5 );
}

//ベクトル内積
double dot_product(Vector2D vl, Vector2D vr) {
    return vl.x * vr.x + vl.y * vr.y;
}

//２つのベクトルABのなす角度θを求める
double AngleOf2Vector(Vector2D A, Vector2D B )
{
    //　※ベクトルの長さが0だと答えが出ませんので注意してください。

    //ベクトルAとBの長さを計算する
    double length_A = get_vector_length(A);
    double length_B = get_vector_length(B);

    //内積とベクトル長さを使ってcosθを求める
    double cos_sita = dot_product(A,B) / ( length_A * length_B );

    //cosθからθを求める
    double sita = acos( cos_sita );

    //ラジアンでなく0～180の角度でほしい場合はコメント外す
    sita = sita * 180.0/M_PI;
    return sita;
}

struct Point {
    coord_t x, y, z;

    bool operator <(const Point &p) const {
        return x < p.x || (x == p.x && y < p.y);
    }
};

// 2D cross product of OA and OB vectors, i.e. z-component of their 3D cross product.
// Returns a positive value, if OAB makes a counter-clockwise turn,
// negative for clockwise turn, and zero if the points are collinear.
coord2_t cross(const Point &O, const Point &A, const Point &B)
{
    return (A.x - O.x) * (B.y - O.y) - (A.y - O.y) * (B.x - O.x);
}

// Returns a list of points on the convex hull in counter-clockwise order.
// Note: the last point in the returned list is the same as the first one.
vector<Point> convex_hull(vector<Point> P)
{
    int n = P.size(), k = 0;
    if (n == 1) return P;
    vector<Point> H(2*n);

    // Sort points lexicographically
    sort(P.begin(), P.end());

    // Build lower hull
    for (int i = 0; i < n; ++i) {
        while (k >= 2 && cross(H[k-2], H[k-1], P[i]) <= 0) k--;
        H[k++] = P[i];
    }

    // Build upper hull
    for (int i = n-2, t = k+1; i >= 0; i--) {
        while (k >= t && cross(H[k-2], H[k-1], P[i]) <= 0) k--;
        H[k++] = P[i];
    }

    H.resize(k-1);
    return H;
}

