struct Vec2 {
  const double eps = 1e-9;
  double x, y;
  Vec2() : x(0), y(0) {}
  Vec2(double x, double y) : x(x), y(y) {}
  Vec2& operator+=(Vec2 that) { x += that.x, y += that.y; return *this; }
  Vec2& operator-=(Vec2 that) { x -= that.x, y -= that.y; return *this; }
  Vec2& operator*=(double s) { x *= s, y *= s; return *this; }
  Vec2& operator/=(double s) { x /= s, y /= s; return *this; }
  Vec2 operator+(Vec2 that) const { return Vec2(*this) += that; }
  Vec2 operator-(Vec2 that) const { return Vec2(*this) -= that; }
  Vec2 operator*(double that) const { return Vec2(*this) *= that; }
  Vec2 operator/(double that) const { return Vec2(*this) /= that; }
  double dot(Vec2 that) const { return x * that.x + y * that.y; }
  double cross(Vec2 that) const { return x * that.y - y * that.x; }
  double length() const { return hypot(x, y); }
  Vec2 normal() const { return Vec2(*this) / (*this).length(); }
  Vec2 rotate90() const { return Vec2(y, -x); }
  Vec2 rotate(double a) const {
    return Vec2(x * cos(a) - y * sin(a), x * sin(a) + y * cos(a));
  }
  double angle(Vec2 v) const { return acos(this->dot(v) / (this->length() * v.length())); }
  int ort() const {
    if (abs(x) < eps && abs(y) < eps) return 0;
    if (y > 0) return x > 0 ? 1 : 2;
    else return x > 0 ? 4 : 3;
  }
  bool operator<(const Vec2& v) const {
    int o = ort(), vo = v.ort();
    if (o != vo) return o < vo;
    return cross(v) > 0;
  }
  bool operator>(const Vec2& v) const {
    return !(v < *this);
  }
  friend istream& operator>>(istream &is, Vec2 &v) { return is >> v.x >> v.y; }
  friend ostream& operator<<(ostream &os, Vec2 &v) { return os << "(" << v.x << ", " << v.y << ")"; }
};

void solve() {
  int n;
  cin >> n;
  vi32 x(n), y(n);
  rep(i, n) {
    cin >> x[i] >> y[i];
  }
  vector<Vec2> vs;
  vector<Vec2> cs;
  rep(i, n) rep(j, i) {
    Vec2 v(x[i] - x[j], y[i] - y[j]);
    Vec2 c((x[i] + x[j]) / 2.0, (y[i] + y[j]) / 2.0);
    vs.emplace_back(v.rotate90().normal());
    vs.emplace_back(v.rotate90().rotate90().rotate90().normal());
    cs.emplace_back(c);
    cs.emplace_back(c);
  }
  vi32 o(sz(vs));
  iota(all(o), 0);
  sort(all(o), [&](int i, int j) { return vs[i] < vs[j]; });
  vector<double> ans(n);
  rep(_i, sz(vs)) {
    int _j = (_i + 1) % sz(vs);
    int i = o[_i], j = o[_j];
    Vec2 v1 = vs[i], c1 = cs[i];
    Vec2 v2 = vs[j], c2 = cs[j];
    auto c = (v1 * 1e9 + c1).rotate(0.001 * M_PI / 180);
    double min_dist = numeric_limits<double>::infinity();
    int min_i = -1;
