ll det(P p1,P p2){
  return p1.first*p2.second-p2.first*p1.second;
}
P operator +(const P2 &p1,const P2 &p2){
  return P(p1.first.first+p2.first.first,p1.first.second+p2.first.second);
}
P operator -(const P2 &p1,const P2 &p2){
  return P(p1.first.first-p2.first.first,p1.first.second-p2.first.second);
}
P operator -(const P &p1,const P &p2){
  return P(p1.first-p2.first,p1.second-p2.second);
}
P operator -(const P2 &p1,const P &p2){
  return P(p1.first.first-p2.first,p1.first.second-p2.second);
}
vector<int> convex(vector<P2> v,int n){
  sort(v.begin(),v.end());
  int k=0;
  vector<P> ans(n*2);
  vector<int> ret(n*2);
  for(int i=0;i<n;i++){
    while(k>1&&det(ans[k-1]-ans[k-2],v[i]-ans[k-1])<=0) k--;
    ans[k]=v[i].first;
    ret[k]=v[i].second;
    k++;
  }
  for(int i=n-2,t=k;i>=0;i--){
    while(k>t&&det(ans[k-1]-ans[k-2],v[i]-ans[k-1])<=0) k--;
    ans[k]=v[i].first;
    ret[k]=v[i].second;
    k++;
  }
  ans.resize(k-1);
  ret.resize(k-1);
  return ret;
}
