    py*=-1;
    double pa=M_PI/2;
    if(py!=0) pa=atan((double)px/py);

    int zx=vec[v[i]].first.first-vec[v[(i-1)+(i==0?vs:0)]].first.first;
    int zy=vec[v[i]].first.second-vec[v[(i-1)+(i==0?vs:0)]].first.second;
    zy*=-1;
    double za=-M_PI/2;
    if(zy!=0) za=atan((double)zx/zy);

    double ka=abs(pa-za);
