int dcmp(long double a) {
	if (a > EPS) return 1;
	if (fabs(a) < EPS) return 0;
	return -1;	
}

long double Max(long double a, long double b) {
	if (dcmp(a - b) <= 0) return b;
	return a;
}

long double Min(long double a, long double b) {
	if (dcmp(a - b) <= 0) return a;
	return b;
