double posarg(double ang) {
	while(ang >= 2*M_PI)
		ang -= 2*M_PI;
	while(ang < 0)
		ang += 2*M_PI;
	return ang;
}

void ConvexHull() {
	P st(1e9,1e9,-1), nx(1e9,1e9,-1);
	rep(i,pts.size()) {
		if(pts[i].p.x < st.p.x)
			st = pts[i];
	}
	assert(st.id >= 0);
	cv.push_back(st);
	double mn = 3*M_PI;
	rep(i,pts.size()) {
		if(pts[i].id == st.id) continue;
		if(posarg( M_PI - arg(pts[i].p - st.p)) < mn) {
			nx = pts[i];
			mn = posarg(M_PI - arg(nx.p - st.p));
		}
	}
	assert(nx.id >= 0);
	cv.push_back(nx);

	while(cv.back().id != cv[0].id) {
		int n = cv.size();
		complex<double> v1, v2;
		v1 = cv[n-1].p - cv[n-2].p;
		mn = 3*M_PI;
		nx = P(1e9,1e9,-1);
		rep(i,pts.size()) {
			if(pts[i].id == cv[n-1].id) continue;
			v2 = pts[i].p - cv[n-1].p;
			if(posarg(arg(v1) - arg(v2)) < mn) {
				mn = posarg(arg(v1) - arg(v2));
				nx = pts[i];
			}
		}
		assert(nx.id >= 0);
		cv.push_back(nx);
	}
	cv.pop_back();
}

