        swap(dx,dy);
        dy=-dy;
        swap(nx,ny);
        ny=-ny;
        DBG(dx,dy,nx,ny)
        double p = dx*dx+dy*dy;
        double q = nx*nx+ny*ny;
        double r = (nx-dx)*(nx-dx)+(ny-dy)*(ny-dy);
        DBG(p,q,r)
        assert(abs((p+q-r)/(sqrt(p)*sqrt(q)*2.0))<=1.0+eps);
        return acos((p+q-r)/(sqrt(p)*sqrt(q)*2.0));

