point<long long> fst;
template<typename T = long long>
struct convexHull{
	vector<point<T>> P;
	vector<point<T>> ans;
	bool bad = false;

	void add(point<T> crt){
		bad = true;
		P.push_back(crt);
	}

	void instantiate(vector<point<T>> &crt){
		bad = true;
		P = crt;
	}

	static T det(point<T> A, point<T> B, point<T> C){
		return A.x * B.y + A.y * C.x + B.x * C.y - A.x * C.y - A.y * B.x - B.y * C.x;
	}

	static bool comp(point<T> a, point<T> b){
		return det(fst,a,b) < 0;
	}

	vector<point<T>> getConvexHull(){
		if (bad){
			ans.clear();
			if (P.empty()) return ans;
			fst = P[0];
			for (auto it : P) fst = min(fst, it);

			for (auto it = P.begin(); it!=P.end(); it++){
				if (*it == fst){
					P.erase(it);
					break;
				}
			}

			sort(P.begin(), P.end(), comp);
			ans.push_back(fst);
			for (auto it : P){
				while (ans.size() >= 2 && det(ans[ans.size() - 2], ans[ans.size() - 1], it) > 0){
					ans.pop_back();
				}
				ans.push_back(it);
			}
		}
		return ans;
	}
};
