vector<pair<double, double>> get_convex_hull(
    const vector<pair<double, double>> &p0s) {
  const int N = p0s.size();
  vector<pair<double, double>> ps(p0s);
  sort(ps.begin(), ps.end());
  vector<pair<double, double>> res;
  for (int i = 0; i < N; i++) {
    while (res.size() > 1) {
      pair<double, double> v_cur =
                               sub(res[res.size() - 1], res[res.size() - 2]),
                           v_new = sub(ps[i], res[res.size() - 2]);
      if (det(v_cur, v_new) > 0) {
        break;
      }
      res.pop_back();
    }
    res.push_back(ps[i]);
  }

  const int t = res.size();
  for (int i = N - 2; i >= 0; i--) {
    while (res.size() > t) {
      pair<double, double> v_cur =
                               sub(res[res.size() - 1], res[res.size() - 2]),
                           v_new = sub(ps[i], res[res.size() - 2]);
      if (det(v_cur, v_new) > 0) {
        break;
      }
      res.pop_back();
    }
    res.push_back(ps[i]);
  }
  res.pop_back();
  return res;
}

