ld angle (pt a, pt o, pt b) {
  pt u = a - o;
  pt v = b - o;
  ld cosa = dot(u, v) / (norm(u) * norm(v));
  return acos(cosa);
}

bool cw (pt a, pt b, pt c) {
  return cross(b - a, c - a) < 0;
}

template<typename T>
T preback (const vector<T> &v) {
  return *next(v.rbegin());
}

const int MAX_N = 105;

ld ans [MAX_N];

int main () {
  ios::sync_with_stdio(false);

  int n;
  cin >> n;

  vector<pair<pt, int>> pts (n);
  for (int i = 0; i < n; i++) {
    cin >> pts[i].x.x >> pts[i].x.y;
    pts[i].y = i;
  }

  sort(pts.begin(), pts.end());

  vector<pair<pt, int>> upper;
  for (int i = 0; i < n; i++) {
    while ((int) upper.size() >= 2 && !cw(preback(upper).x, upper.back().x, pts[i].x)) {
      upper.pop_back();
    }
    upper.push_back(pts[i]);
  }

  reverse(pts.begin(), pts.end());

  vector<pair<pt, int>> lower;
  for (int i = 0; i < n; i++) {
    while ((int) lower.size() >= 2 && !cw(preback(lower).x, lower.back().x, pts[i].x)) {
      lower.pop_back();
    }
    lower.push_back(pts[i]);
  }

  if (upper.back().y == lower[0].y) upper.pop_back();
  for (auto pr : lower) {
    upper.push_back(pr);
  }
  if (upper.back().y == upper[0].y) upper.pop_back();

  // upper is now the convex hull
  int k = upper.size();
  if (k == 2) {
    ans[upper[0].y] = 0.5;
    ans[upper[1].y] = 0.5;
  } else {
    for (int i = 0; i < k; i++) {
      ans[upper[i].y] = angle(upper[(i + k - 1) % k].x, upper[i].x, upper[(i + 1) % k].x);
      ans[upper[i].y] = (M_PI - ans[upper[i].y]) / (2 * M_PI);
    }
  }

  for (int i = 0; i < n; i++) {
    cout << fixed << setprecision(12) << ans[i] << '\n';
  }
}

#include <bits/stdc++.h>
using namespace std;

typedef long double ld;
typedef long long ll;
const ld pi=acos(-1.0),pi2=pi*2;

struct vec{
	ll x,y;int id;
	vec(){}
	vec(ll x0,ll y0){x=x0;y=y0;}
	vec operator+(vec v){return vec(x+v.x,y+v.y);}
	vec operator-(vec v){return vec(x-v.x,y-v.y);}
	vec operator-(){return vec(-x,-y);}
	ll operator*(vec v){return x*v.y-v.x*y;}
	ld arg(){return atan2(y,x);}
	friend bool operator<(vec a,vec b){
		return a.arg()<b.arg();
	}
}p[105],o(1e9,1e9);

int n;

inline void init(){
	scanf("%d",&n);
	for(int i=1;i<=n;++i){
		scanf("%lld%lld",&p[i].x,&p[i].y);
		p[i].id=i;
		if(p[i].y<o.y)o=p[i];
	}
	for(int i=1,j=1;i<=n;++i){
		if(p[i].x!=o.x||p[i].y!=o.y){
			p[j].x=p[i].x-o.x;
			p[j].y=p[i].y-o.y;
			p[j].id=p[i].id;
			++j;
		}
	}
	sort(p+1,p+n);
}

vec st[105];int top;
ld ans[105];
inline void solve(){
	st[top=1]=vec(0,0);st[1].id=o.id;
	for(int i=1;i<n;++i){
		for(;top>1&&(p[i]-st[top-1])*(p[i]-st[top])<0;--top);
		st[++top]=p[i];
	}
	st[0]=st[top];st[top+1]=st[1];
	for(int i=1;i<=top;++i){
		ld arg=(st[i-1]-st[i]).arg()-(st[i+1]-st[i]).arg();
		if(arg<0)arg+=pi2;
		arg=pi-arg;if(arg<0)arg=0;
		ans[st[i].id]=arg/pi2;
	}
	for(int i=1;i<=n;++i)
		printf("%.8lf\n",(double)ans[i]);
}

int main(){
	init();
	solve();
	return 0;
}

