  double r = 1e10;
  double ans[n];
  CLR(ans);
  FOR(i,0,num+1) {
    double theta = i * 2.0 * PI / num;
    double X = r * cos(theta);
    double Y = r * sin(theta);
    double mn = 1e20;
    int best = 0;
    FOR(j,0,n) {
      double dist = pow(x[j]-X,2)+pow(y[j]-Y,2);
      if(dist < mn) {
        mn = dist;
        best = j;
      }
    }
    ans[best] += 1.0 / num;
  }
  FOR(i,0,n) cout << fixed << setprecision(17) << ans[i] << endl;
  return 0;
}

