		double b2 = imag(p[(i + 2) % sz]) - imag(p[(i + 1) % sz]);

		double theta = -(a1 * b1 + a2 * b2) / (std::sqrt(a1 * a1 + a2 * a2) * std::sqrt(b1 * b1 + b2 * b2));
