            ps[n++] = Point(i, x, y);
            st.insert(pii(x, y));
        }
    }
    if (n == 1) {
        ans[ps[0].id] = 1;
    }
    else if (n == 2) {
        ans[ps[0].id] = ans[ps[1].id] = 1;
    } else {
        int m = ConvexHull(ps, n, ch);
        for (int i = 0; i < m; i++) {
            int j = (i - 1 + m) % m;
            int k = (i + 1) % m;
            Vector v1 = ch[j] - ch[i];
            Vector v2 = ch[k] - ch[i];
            ans[ch[i].id] = pi - Angle(v1, v2);
        }
    }
    double sum = 0.0;
    for (int i = 0; i < N; i++) sum += ans[i];
    for (int i = 0; i < N; i++) ans[i] /= sum;
    for (int i = 0; i < N; i++) {
        printf("%.30f\n", ans[i]);
    }
    return 0;
}

