    stv[2] = 2;
    for(i = 3; i <= n; i++)
    {
        while(m > 1 && det(v[ stv[m - 1] ], v[ stv[m] ], v[i]) < eps)
            m--;
        stv[++m] = i;
    }

    q = m;
    for(i = 1; i <= q; i++)
        r[i] = v[ stv[i] ];

    m = 2;
    stv[1] = n;
    stv[2] = n - 1;
    for(i = n - 2; i >= 1; i--)
    {
        while(m > 1 && det(v[ stv[m - 1] ], v[ stv[m] ], v[i]) < eps)
            m--;
        stv[++m] = i;
    }

    for(i = 1; i <= m; i++)
        r[ ++q ] = v[ stv[i] ];

    vector<point> ans;
    for(i = 1; i < q; i++)
    {
        if(r[i] == r[i - 1] && i > 1)
            continue;
        ans.push_back(r[i]);
    }
    return ans;
}

LD dist(point A, point B)
{
    LD d = (A.x - B.x) * (A.x - B.x) + (A.y - B.y) * (A.y - B.y);
    d = sqrt(d);
    return d;
}

