template<class UnaryFunction>
class function_output_iterator {
public:
    using iterator_category = std::output_iterator_tag;
    using value_type        = void;
    using difference_type   = void;
    using pointer           = void;
    using reference         = void;

    explicit function_output_iterator(const UnaryFunction& f) : f_(f) {};

    class output_proxy {
    public:
        explicit output_proxy(UnaryFunction& f) : f_(f) {}

        template<typename T>
        output_proxy& operator=(const T& x) {
            f_(x);
            return *this;
        }

    private:
        UnaryFunction& f_;
    };

    output_proxy operator*() { return output_proxy(f_); }

    function_output_iterator& operator++()    { return *this; }
    function_output_iterator& operator++(int) { return *this; }

private:
    UnaryFunction f_;
};

template<typename UnaryFunction>
auto make_function_output_iterator(const UnaryFunction& f) {
    return function_output_iterator<UnaryFunction>(f);
}

