double kakudo(int a,int b,int c){
	double retval = acos(((X[b]-X[a])*(X[c]-X[a]) + (Y[b]-Y[a])*(Y[c]-Y[a]))
		/ pow(pow(X[b]-X[a],2) + pow(Y[b]-Y[a],2),0.5) / pow(pow(X[c]-X[a],2) + pow(Y[c]-Y[a],2), 0.5));
	//cout<<((X[b]-X[a])*(X[c]-X[a]) + (Y[b]-Y[a])*(Y[c]-Y[a]))
	//	/ pow(pow(X[b]-X[a],2) + pow(Y[b]-Y[a],2),0.5) / pow(pow(X[c]-X[a],2) + pow(Y[c]-Y[a],2), 0.5)<<" aaa"<<endl;
	return M_PI - retval;
}


bool kakomare(int a,int b,int c,int d){
	double wa = kakudo(a,b,c) + kakudo(a,c,d) + kakudo(a,d,b);
	if(wa >= 0.999 * M_PI && wa <= 1.001 * M_PI){
		return true;
	}
	return false;
}


int main(void){
	ll n,m;
	double x,y;
	cin>>n;
	vector<double> ans;
	rep(i,n){
		cin>>x>>y;
		X.push_back(x);
		Y.push_back(y);
	}
	if(n==2){
		cout<<0.5<<endl;
		cout<<0.5<<endl;
		return 0;
	}
	rep(i,n){
		bool isZero = false;
		rep(j,n){
			if(isZero || j==i) continue;
			rep(k,n){
				if(isZero || k==i || k==j) continue;
				rep(l,n){
					if(isZero || l==i || l==j || l==k) continue;
					if(kakomare(i,j,k,l)){
						isZero = true;
						break;
					}
				}
				if(isZero) break;
			}
			if(isZero) break;
		}
		if(isZero){
			ans.push_back(0);
			continue;
		}
		double memo = 1000;
		rep(j,n-1){
			if(j==i) continue;
			for(int k=j+1; k<n;k++){
				if(k==j || k==i) continue;
				//cout<<kakudo(i,j,k)<<endl;
				memo = min(memo, kakudo(i,j,k));
			}
		}
		ans.push_back(memo/2/M_PI);
	}
	rep(i,n){
		cout<<ans[i]<<endl;
	}
	return 0;
}

