	vector<Hole> h(N);

	for (int i = 0; i < N; i++) {
		cin >> h[i].p;
		h[i].i = i;
	}

	// 凸包を求める
	sort(h.begin(), h.end(), [](auto l, auto r) { return l.p.x < r.p.x || (l.p.x == r.p.x && l.p.y < r.p.y); });

	vector<Hole> convex(N * 2);
	int k = 0;
	for (int i = 0; i < N; i++) {
		while (k > 1 && cross_product(convex[k - 1].p - convex[k - 2].p, h[i].p - convex[k - 1].p) <= 0) k--;
		convex[k++] = h[i];
	}
	for (int i = N - 2, t = k; i >= 0; i--) {
		while (k > t && cross_product(convex[k - 1].p - convex[k - 2].p, h[i].p - convex[k - 1].p) <= 0) k--;
		convex[k++] = h[i];
	}
	int M = k - 1;
	convex.resize(M);

	vector<double> ans(N);

	for (int i = 0; i < M; i++) {
		Point cur = convex[i].p;
		Point prev = convex[(i + M - 1) % M].p;
		Point next = convex[(i + M + 1) % M].p;

		double diff = (next - cur).theta() - (cur - prev).theta();

		if (diff < 0) diff += 2 * M_PI;
		if (diff > 2 * M_PI) diff -= 2 * M_PI;

		ans[convex[i].i] = diff / (2 * M_PI);
	}

	for (int i = 0; i < N; i++)
		cout << ans[i] << endl;
}

