    mp[ps[i]] = i;
  }
  auto ch = move(convex_hull(ps));
  int M = ch.size();
  vector<ld> theta(N,0.0);
  rep(i,M){
    auto& p1 = ch[(i-1+M)%M];
    auto& p2 = ch[i];
    auto& p3 = ch[(i+1)%M];
    ld b = arg(p3-p2); ld a = arg(p2-p1);
    if(a>0.0 && b<0.0) b += 2*PI;
    // cout << b/(2*PI) << " " << a/(2*PI)  << endl;
    theta[mp[p2]] = b-a;
  }
  ld ssum = 0.0;
  for(auto i:theta) ssum += i;
  for(auto i:theta) printf("%.10Lf\n",i/ssum);
  return 0;
}

