Point wall[N];
Point st[N];
int r = 0;

Point minP;

bool cmpPoints(const Point &a, const Point &b)
{
    Point v = a - minP;
    Point u = b - minP;
    if (v * u != 0)
        return v * u > 0;
    return v.length() < u.length();
}

void graham(int n)
{
    minP = *min_element(wall, wall + n);
    sort(wall, wall + n, cmpPoints);
    r = 0;
    for (int i = 0; i < n; i++)
    {
        while (r > 1 && (st[r - 1] - st[r - 2]) * (wall[i] - st[r - 2]) <= 0)
            r--;
        st[r++] = wall[i];
    }
}

double ans[N];

double getAns(Point v, Point u)
{
    double ang = atan2(v * u, v % u);
    return ang / 2 / pi;
}

