    scanf("%d", &n);
    for (int i = 0; i < n; i++)
    {
        wall[i].scan();
        wall[i].id = i;
    }
    graham(n);

    if (r == 2)
    {
        for (int i = 0; i < r; i++)
            ans[st[i].id] = 0.5;
    }
    else
    {
        for (int i = 0; i < r; i++)
        {
            int pid = (i + r - 1) % r;
            int ni = (i + 1) % r;
            Point A = (st[i] - st[pid]).rotate();
            Point B = (st[ni] - st[i]).rotate();
            ans[st[i].id] = getAns(A, B);
        }
    }

    for (int i = 0; i < n; i++)
        printf("%.10lf\n", ans[i] );

    return 0;
}

