void simulated_annealing() {
    double T = 1.95;
    double start_temp = 1;
    double end_temp = 1e-10;
    int it = 0;
    double pre_sum = 0;
    double time;
    while ((time = timer.get_time()) < T) {
        it++;
        double temp = start_temp + (end_temp - start_temp) * time / T;
        int target = xor64(N);
        double new_sum = pre_sum;
        if (non_zero[target]) { new_sum -= ans[target]; }
        else { new_sum += ans[target]; }
        double prob = exp((abs(pre_sum - 1) - abs(new_sum - 1)) / temp);
        if (prob < (double) xor64(10000000) / 10000000) {
        } else {
            non_zero[target] = !non_zero[target];
            pre_sum = new_sum;
        }
    }
}

