	{
		Point q=p[i]-p[0];
		if(i==0)
			q=p[i]-p[1];
		q=Point(q.imag(), -q.real());
		ld left=atan2(q.imag(), q.real());
		ld right=normal(left+pi);

		REP(j,n)
		{
			if(i==0&&j==1) continue;
