			Point q=p[i]-p[j];
			q=Point(q.imag(), -q.real());
			ld l=atan2(q.imag(), q.real());
			bool f1=0,f2=0;
			if((left-pi < l && l < left) || (left+pi < l && l < left+2*pi))
			{
				f1=1;
				left=l;
			}
			ld r=normal(l+pi);
			if((right < r && r < right+pi) || (right-2*pi < r && r < right-pi))
			{
				f2=1;
				right=r;
			}
			if(f1&&f2)
			{
				ans[i]=0;
				left=right;
				break;
			}
		}
