		d2.push_back(Point(x, y));
	}

	sort(d.begin(), d.end());

	Polygon stu, stl;

	stu.push_back(d[0]);
	stu.push_back(d[1]);

	for (int i = 2; i < q; i++) {
		for (int j = stu.size(); j >= 2 && ccw(stu[j - 2], stu[j - 1], d[i]) == ANTI_CLOCK; j--) {
			stu.pop_back();
		}
		stu.push_back(d[i]);
	}
	reverse(d.begin(), d.end());

	stl.push_back(d[0]);
	stl.push_back(d[1]);

	for (int i = 2; i < q; i++) {
		for (int j = stl.size(); j >= 2 && ccw(stl[j - 2], stl[j - 1], d[i]) == ANTI_CLOCK; j--) {
			stl.pop_back();
		}
		stl.push_back(d[i]);
	}


	stl.erase(stl.begin());
	stl.pop_back();

	stu.insert(stu.end(), stl.begin(), stl.end());

	double sum = 0.0;
	map<Point, double>anslist;
	rep(i, stu.size()) {
		Point l, r;
		if (i == 0) {
			l = stu[stu.size() - 1] - stu[i];
			r = stu[i + 1] - stu[i];

		}

		else if (i == stu.size() - 1) {
			l = stu[0] - stu[i];
			r = stu[i - 1] - stu[i];
		}

		else {
			l = stu[i-1] - stu[i];
			r = stu[i+1] - stu[i];
		}

		double co = dot(l, r);
		double l1 = l.abs(), l2 = r.abs();
		co = co /  (l1 * l2);
		anslist[stu[i]] = (acos(-1.0) - acos(co));
		sum += acos(-1.0) - acos(co);
	}




	rep(i, anslist.size()) {

		printf("%.20f\n", anslist[d2[i]] / sum);
	}

	return 0;
}

