#define MAX_N 2e6
double pi = acos(-1);
double _cos = cos(2 * pi / MAX_N);
double _sin = sin(2 * pi / MAX_N);
double c = 1;
double s = 0;

void next() {
    double x = c * _cos - s * _sin;
    double y = c * _sin + s * _cos;
    swap(c, x); swap(s, y);
}

int main() {
    int n; cin >> n;
    vector<double> v(n, 0);
    vector<double> a(n), b(n);
    for (int i = 0; i < n; i++) cin >> a[i] >> b[i];
    for (int ni = 0; ni < MAX_N; ni++) {
        int best = 0; double dist = -c*a[0] - s*b[0];
        for (int i = 1; i < n; i++) {
            double d = -c*a[i]-s*b[i];
            if (dist > d) {
                best = i; dist = d;
            }
        }
        v[best]++;
        next();
    }
    for (int i = 0; i < n; i++) {
        printf("%.12f\n", v[i]/MAX_N);
    }
    return 0;
}

