const ll MOD = 1000000007;
const ll INF = (ll)1e15;

struct Grid
{
    ll x;
    ll y;
    int i;
};

Grid G[105];
double A[105];

int det(Grid p0, Grid p1, Grid p2)
{

    return (p1.x - p0.x) * (p2.y - p0.y) - (p1.y - p0.y) * (p2.x - p0.x);
}

double theta(Grid g0, Grid g1, Grid g2)
{
    pll v0(g1.y - g0.y, -(g1.x - g0.x));
    pll v1(g2.y - g1.y, -(g2.x - g1.x));

    double l0 = sqrt(v0.first * v0.first + v0.second * v0.second);
    double l1 = sqrt(v1.first * v1.first + v1.second * v1.second);
    ll t = (v0.first / l0) * (v1.first / l1) + (v0.second / l0) * (v1.second / l1);
    return acos(t);
}

int main()
{
    int N;
    cin >> N;
    REP(i, N)
    {
        A[i] = 0;
        cin >> G[i].x >> G[i].y;
        G[i].i = i;
    }
    sort(G, G + N, [](Grid a, Grid b) { return a.x == b.x ? a.y < b.y : a.x < b.x; });
    int k = 0;
    vector<Grid> V(N * 2);
    REP(i, N)
    {
        while (k > 1 && det(V[k - 2], V[k - 1], G[i]) <= 0)
            k--;
        V[k++] = G[i];
    }
    for (int i = N - 2, t = k; i >= 0; --i)
    {
        while (k > t && det(V[k - 2], V[k - 1], G[i]) <= 0)
            k--;
        V[k++] = G[i];
    }
    V.resize(k - 1);

    int s = V.size();
    double sum = 0;
    REP(i, s)
    {
        Grid g0 = V[(s + i - 1) % s];
        Grid g1 = V[i];
        Grid g2 = V[(i + 1) % s];

        A[g1.i] = theta(g0, g1, g2);
        sum += A[g1.i];
    }

    REP(i, N)
    {
        cout << OF64 << (A[i] / sum) << endl;
    }
    return 0;
}

