    ra = elevation(arr[roo[count-1]], arr[roo[count-2]]);
    rb = elevation(arr[roo[count-1]], arr[roo[0]]);
    if(ra >= rb)arr[roo[count-1]].rate = (rb - ra + atan2(0.0, -1.0)*2)/atan2(0.0, -1.0)/2.0;
    else arr[roo[count-1]].rate = (rb - ra)/atan2(0.0, -1.0)/2.0;
    for(int i = 1;i < count-1;i++){
        ra = elevation(arr[roo[i]], arr[roo[i-1]]);
        rb = elevation(arr[roo[i]], arr[roo[i+1]]);
        if(ra >= rb)arr[roo[i]].rate = (rb - ra + atan2(0.0, -1.0)*2)/atan2(0.0, -1.0)/2.0;
        else arr[roo[i]].rate = (rb - ra)/atan2(0.0, -1.0)/2.0;
    }
    for(int i = 0;i < n;i++)if(arr[i].rate > 0.5)arr[i].rate -= 0.5;
    for(int i = 0;i < n;i++)printf("%1.9lf\n", arr[i].rate);
    return 0;
}

