    // N > 3, 垂直二等分線が2本はある想定
    else{
        // 一直線チェック
        if(is_straight_line(P)){
            auto p = leftAndRight(P);
            int left_index = p.first;
            int right_index = p.second;

            // 端の2点だけ確率が0.5になる
            FOR(i, 0, N){
                if(i==left_index || i==right_index){
                    p(0.5);
                }else{
                    p(0);
                }
            }
        }
        else{
            // それ以外。convex hullを求める
            convexHull(P);
        }
    }

    return 0;
}

