int cnt;
double ans[maxn];
struct node{ll x,y,id;}p[maxn],s[maxn];

const double pi=acos(-1.0);

inline double operator * (node a,node b){return a.x*b.y-a.y*b.x;}
inline node operator - (node a,node b){return {a.x-b.x,a.y-b.y,0};}

inline double X(node a){return sqrt(a.x*a.x+a.y*a.y);}

inline bool cmp(node a,node b)
{
	ll t=(a-p[1])*(b-p[1]);
	if(t<0) return true; return false;
}

int main()
{
	int n=read();
	rep(i,1,n) p[i].x=read(),p[i].y=read(),p[i].id=i;
	rep(i,2,n)
	{
		if(p[i].x<p[1].x||(p[i].x==p[1].x&&p[i].y<p[1].y))
			swap(p[1].x,p[i].x),swap(p[1].y,p[i].y),swap(p[1].id,p[i].id);
	}
	sort(p+2,p+n+1,cmp); s[++cnt]=p[1]; s[++cnt]=p[2];
	rep(i,3,n)
	{
		while(cnt>=2&&((p[i]-s[cnt])*(p[i]-s[cnt-1])<0)) cnt--;
		s[++cnt]=p[i];
	}
	s[++cnt]=s[1]; s[++cnt]=s[2];
	//rep(i,1,cnt) cout<<s[i].x<<" "<<s[i].y<<endl; cout<<endl<<endl;
	rep(i,2,cnt-1)
	{
		node a=s[i]-s[i-1],b=s[i+1]-s[i];
		ll p1=a.x*b.x+a.y*b.y;
		double p2=X(a)*X(b); double q=acos((double)p1/p2);
		ans[s[i].id]=q/(2*pi);
	}
	rep(i,1,n) printf("%.10lf\n",ans[i]);
	return 0;
}

