    T operator % (const point &q) const { return x*q.y - y*q.x; }
    T len2() const { return x*x + y*y; }
};

int compare(T x, T y) {
    if(y - x > 0) return -1;
    if(x - y > 0) return 1;   
    return 0;
}

T cross(point p, point q, point r) { return (r-q)%(p-q); }

int turn(point p, point q, point r) { return compare(cross(p,q,r), 0); }

int cw(point p, point q, point r) { return turn(p,q,r) < 0; }

double angle(point a, point o, point b) // angle AOB (in radians)
{
    point u = a - o; // u: vector oa
    point v = b - o; // v: vector ob
    return acos(u * v / sqrt(1.0 * u.len2() * v.len2())); 
}

bool cmp(const point &p, const point &q)
{
    return p.x < q.x || (p.x == q.x && p.y < q.y);
}

vector<point> convex_hull(vector<point> &p)
{
    int n = (int)p.size(), k = 0;
    vector<point> h(2 * n);
    sort(p.begin(), p.end(), cmp);
    for(int i = 0; i < n; i++) 
    {
        while(k >= 2 && cw(h[k-2], h[k-1], p[i])) k--;
        h[k++] = p[i];
    }
    for(int i = n - 2, t = k + 1; i >= 0; i--) 
    {
        while(k >= t && cw(h[k-2], h[k-1], p[i])) k--;
        h[k++] = p[i];
    }
    h.resize(k); h.pop_back(); 
    return h;
}

