struct point_t {
    LL x, y;
};
bool operator < (point_t a, point_t b) {
    if(a.x == b.x) {
        return a.y < b.y;
    }
    return a.x < b.x;
}
point_t operator - (point_t a, point_t b) {
    return point_t{a.x - b.x, a.y - b.y};
}
LL operator ^ (point_t a, point_t b) {
    return a.x * b.y - a.y * b.x;
}
int GetSign(LL x) {
    if(x < 0) {
        return -1;
    }
    return x > 0;
}
int RelativePosition(point_t O, point_t A, point_t B) {
    return GetSign((A - O) ^ (B - O));
}
double angle(point_t a) {
    return atan2(a.y, a.x);
}

vector<int> convex_hull(vector<point_t> points) {
    int N = points.size();
    vector<int> ord(N);
    iota(ord.begin(), ord.end(), 0);
    sort(ord.begin(), ord.end(), [&](int i, int j) {return points[i] < points[j];});
    vector<int> aw, cw;
    aw.push_back(ord[0]);
    cw.push_back(ord[0]);
    for(int i = 1; i < N; ++i) {
        int index = ord[i];
        point_t V = points[index];
        while(aw.size() > 1 and RelativePosition(points[aw.rbegin()[1]], V, points[aw.back()]) != -1) {
            aw.pop_back();
        }
        aw.push_back(index);
        while(cw.size() > 1 and RelativePosition(points[cw.rbegin()[1]], V, points[cw.back()]) != 1) {
            cw.pop_back();
        }
        cw.push_back(index);
    }
    aw.pop_back();
    reverse(cw.begin(), cw.end());
    cw.pop_back();
    aw.insert(aw.end(), cw.begin(), cw.end());
    return aw;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int N;
    cin >> N;
    vector<point_t> P(N);
    for(int n = 0; n < N; ++n) {
        cin >> P[n].x >> P[n].y;
    }
    auto H = convex_hull(P);
    vector<double> ans(N);
    H.insert(H.begin(), H.back());
    H.push_back(H[1]);
    for(int i = 1; i + 1 < int(H.size()); ++i) {
        double alpha = angle(P[H[i + 1]] - P[H[i]]) - angle(P[H[i]] - P[H[i - 1]]);
        if(alpha < 0) {
            alpha += 2 * M_PI;
        }
        ans[H[i]] = alpha / (2 * M_PI);
    }
    cout << fixed << setprecision(14);
    for(int n = 0; n < N; ++n) {
        cout << ans[n] << '\n';
    }
}

