// 凸包(を構成する点集合)を求める
// (x, y)が小さい点から反時計回りに入る
// O(NlogN)
// 頂点数はO(\sqrt(N))個になる
vector<int> convex_hull(vector<pair<int, int>> &xy){
    int n = xy.size();

    vector<tuple<int, int, int>> xyid(n);
    for(int i=0; i<n; i++)
        xyid[i] = make_tuple(xy[i].first, xy[i].second, i);

    sort(xyid.begin(), xyid.end());
    vector<int> ch;
    ch.reserve(n);

    // 下側凸包の作成
    // x が小さい点から追加していく
    // 更新のたびに古い点を消すかどうか判断する
    for(int i=0; i<n; i++){
        int x, y, id;
        tie(x, y, id) = xyid[i];
        for(int j = ch.size() - 1; j > 0; j--){
            int id0 = ch[j-1], id1 = ch[j];
            int x0 = xy[id0].first, y0 = xy[id0].second;
            int x1 = xy[id1].first, y1 = xy[id1].second;
            int dx0 = x1 - x0, dy0 = y1 - y0;
            int dx1 = x - x1, dy1 = y - y1;
            int cross = dx0 * dy1 - dy0 * dx1;
            if(cross <= 0) ch.pop_back();
            else break;
        }
        ch.push_back(id);
    }
    // 上側凸包の作成
    // 下側の時に n-1 番目の点は必ず追加されているので n-2 から
    // 0 まで見てから最後に pop_back する
    int k = ch.size() - 1;
    for(int i=n-2; i>=0; i--){
        int x, y, id;
        tie(x, y, id) = xyid[i];
        for(int j = ch.size() - 1; j >= k; j--){ // k は下側まで戻るのを防ぐために必要
            int id0 = ch[j-1], id1 = ch[j];
            int x0 = xy[id0].first, y0 = xy[id0].second;
            int x1 = xy[id1].first, y1 = xy[id1].second;
            int dx0 = x1 - x0, dy0 = y1 - y0;
            int dx1 = x - x1, dy1 = y - y1;
            int cross = dx0 * dy1 - dy0 * dx1;
            if(cross <= 0) ch.pop_back();
            else break;
        }
        ch.push_back(id);
    }
    ch.pop_back();
    ch.shrink_to_fit();

    return ch;
}

int main(){
    int N;
    cin >> N;
    vector<pair<int, int>> xy(N);
    for(int i=0; i<N; i++) cin >> xy[i].first >> xy[i].second;
    if(N == 2){
        cout << 0.5 << endl;
        cout << 0.5 << endl;
        return 0;
    }

    vector<int> ch = convex_hull(xy);
    vector<double> ans(N, 0.0);
    int M = ch.size();

    for(int i=0; i<M; i++){
        int id = ch[i]; 
        int j = ch[(i + 1) % M];
        int k = ch[(i - 1 + M) % M];
        double x0 = xy[k].first,  y0 = xy[k].second;
        double x1 = xy[id].first, y1 = xy[id].second;
        double x2 = xy[j].first,  y2 = xy[j].second;

        double dx0 = x1 - x0, dy0 = y1 - y0;
        double dx1 = x2 - x1, dy1 = y2 - y1;

        double nrm0 = sqrt(dx0*dx0+dy0*dy0);
        double nrm1 = sqrt(dx1*dx1+dy1*dy1);
        double dot = dx0*dx1+dy0*dy1;
        double tmp = dot / (nrm0*nrm1);

        double theta = acos(tmp);
        ans[id] = theta / (2*M_PI);
    }
    for(int i=0; i<N; i++)
        cout << fixed << setprecision(32) << ans[i] << endl;

    return 0;
}

