		return p > q;
	return ccw(O, a.first, b.first);
}

int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(nullptr);

	int n, m, i, j;
	double sum = 0;

	cin>>n;

	for (i = 0; i < n; ++i)
	{
		cin>>arr[i].first.x>>arr[i].first.y;
		arr[i].second = i;
	}
	sort(arr, arr + n, cmp);
	for (i = 0; i < n; ++i)
	{
		_pos[i] = arr[i].second;
		points[i] = arr[i].first;
	}

	j = 0;
	for (i = 0; i < n; ++i)
	{
		while (j >= 2 && !ccw(points[j - 2], points[j - 1], points[i]))
			--j;
		pos[j] = i;
		points[j] = points[i];
		++j;
	}
	m = j;

	for (i = 0; i < m; ++i)
	{
		point& a = points[(i + m - 1) % m];
		point& b = points[(i + 1) % m];
		double p = atan2(-(points[i].x - a.x), points[i].y - a.y);
		double q = atan2(-(b.x - points[i].x), b.y - points[i].y);
		double r = q - p;
		while (r < 0)
			r += 2 * pi;
		while (r >= 2 * pi)
			r -= 2 * pi;
		sol[_pos[pos[i]]] = r;
		sum += r;
	}

	for (i = 0; i < n; ++i)
		cout<<fixed<<setprecision(8)<<sol[i] / sum<<'\n';
}

