vector<Point> convex_hull(vector<Point> P) {
	int n = P.size(), k = 0;
	if (n <= 3) return P;
	vector<Point> H(2*n);

	// Sort points lexicographically
	sort(P.begin(), P.end());

	// Build lower hull
	for (int i = 0; i < n; ++i) {
		while (k > 1 && (H[k-1] - H[k-2]).cross(P[i] - H[k-1]) <= 0) k--;
		H[k++] = P[i];
	}

	// Build upper hull
	for (int i = n-2, t = k+1; i >= 0; --i) {
		while (k > t && (H[k-1] - H[k-2]).cross(P[i] - H[k-1]) <= 0) k--;
		H[k++] = P[i];
	}

	H.resize(k-1);
	return H;
}


