                    j2=j;
                }
                if(h==1&&sled==0&&j!=i){
                    j1=j;
                    sled=1;
                }
            }
            double a=sqrt((x[j1]-x[j2])*(x[j1]-x[j2])+(y[j1]-y[j2])*(y[j1]-y[j2]));
