#include <numeric>

uint64_t GCD(uint64_t a, uint64_t b) {
	if (b == 0) return a;
	if (a % b == 0)return b;
	return GCD(b, a % b);
}

uint64_t LCM(uint64_t a, uint64_t b) {
	return a / GCD(a, b) * b;
}

uint64_t GCD(const std::vector<uint64_t>& values) {
	using FuncType = uint64_t (*)(uint64_t, uint64_t);
	return std::accumulate(values.begin(), values.end(), 0Ui64, (FuncType)GCD);
}

uint64_t LCM(const std::vector<uint64_t>& values) {
	using FuncType = uint64_t(*)(uint64_t, uint64_t);
	return std::accumulate(values.begin(), values.end(), 1Ui64, (FuncType)LCM);
}



