	points.push_back(point);
}

void Polygon::Reverse() {
	std::reverse(points.begin(), points.end());
}

int Polygon::Side_num() const {
	return points.size();
}

long long Polygon::Area_twice(bool oriented) const {
	if (Side_num() <= 2) return 0;
	long long sum = 0;
	Vector2DInt reference = points[0];
	for (int i = 1; i < Side_num() - 1; ++i) {
		sum += Cross(points[i] - reference, points[i + 1] - reference);
	}
	return oriented ? sum : abs(sum);
}

bool Polygon::Is_convex(bool oriented) const {
	const int N = Side_num();
	if (N <= 2) return true;

	CCWEnum first_ccw = CCW(points[0], points[1], points[2]);
	if (oriented && first_ccw != CCWEnum::Counterclockwise) return false;
	for (int i = 1; i < N; ++i) {
		const Vector2DInt& a = points[i];
		const Vector2DInt& b = points[(i + 1) % N];
		const Vector2DInt& c = points[(i + 2) % N];
		CCWEnum ccw = CCW(a, b, c);
		if (first_ccw != ccw) return false;
	}
	return true;
}

