            f64 x2 = xy[hull[(i + 1) % m]].first, y2 = xy[hull[(i + 1) % m]].second;
            f64 x3 = xy[hull[(i - 1 + m) % m]].first, y3 = xy[hull[(i - 1 + m) % m]].second;
            f64 a = dist(x1, y1, x2, y2);
            f64 b = dist(x1, y1, x3, y3);
            f64 c = dist(x2, y2, x3, y3);
            f64 tmp = (a * a + b * b - c * c) / (2. * a * b);
            f64 angle = (abs(tmp) > 1 ? 0. : acos(tmp));
            assert(!isnan(angle));
            angle = angle * 180. / PI;
            angle = 180. - angle;
            res[hull[i]] = angle;
            sum += angle;
        }
        for (int i = 0; i < n; ++i) {
            res[i] /= sum;
            out.precision(20);
            out << fixed << res[i] << "\n";
        }
    }
};

