void kill() {
  //int k = min_element(p, p + n) - p;
  pt mn = *min_element(p, p + n);
  for (int i = 0; i < n; ++i)
    p[i] = p[i] - mn;

  vector<int> id(n);
  iota(all(id), 0);

  //swap(id[0], id[k]);
  //swap(p[0], p[k]);

  for (int i = 0; i < n; ++i)
    for (int j = 0; j + 1 < n; ++j)
      if (!cmpAngle(p[j], p[j + 1])) {
        swap(p[j], p[j + 1]);
        swap(id[j], id[j + 1]);
      }

  //for (int i = 0; i < n; ++i)
    //cout << p[i] << endl;

  vector<pt> hull;
  vector<int> ids;
  vector<ld> ans(n);

  for (int i = 0; i < n; ++i) {
    pt x = p[i];
    while (hull.size() >= 2 
        && (hull[hull.size() - 2] - hull.back()) % (x - hull.back()) >= 0) {
      hull.pop_back();
      ids.pop_back();
    }
    hull.push_back(x);
    ids.push_back(id[i]);
  }


  //for (pt x : hull)
    //cerr << x << endl;

  ld pi = acosl(-1.0);

  int m = hull.size();
  assert(m >= 2);
  if (m == 2) {
    ans[ids[0]] = ans[ids[1]] = 0.5;
  } else {
    for (int i = 0; i < m; ++i) {
      pt x = hull[(i + m - 1) % m];
      pt y = hull[i];
      pt z = hull[(i + 1) % m];
      pt A = x - y;
      pt B = z - y;

      long double res = (pi - acosl((A * B) / A.abs() / B.abs()));
      ans[ids[i]] = res / (2 * pi);
    }
  }

  for (int i = 0; i < n; ++i)
    cout << ans[i] << endl;
}


