  }

  if (N == 2) {
    printf("0.5\n");
    printf("0.5\n");
    return 0;
  }

  convexHull();

  map<LL, double> solution;
  // get angles formed by vectors
  for (auto& kv : idx) {
    LL c = kv.FF;

    if (kv.SS.size() == 1) {
      solution[c] = 0.5;
      continue;
    }
    auto it = kv.SS.begin();
    LL l = *it;
    LL r = *(++it);
//    printf("c: %d, l: %d, r: %d\n", c, l, r);
    Vector v1;
