    double a = angle(v1, v2);
    if (a > M_PI) a -= M_PI;
    a = M_PI - a;

    double total = 2 * M_PI;
    solution[c] = a/total;
  }

  FORN(i, N) {
    printf("%.20f\n", solution[i]);
  }


  return 0;
}

