    rep(i,n){
        cin>>x[i]>>y[i];//点の座標を受け取る
        pt[i]=P(x[i],y[i]);
    }
    vector<P> ch=convex_hull(pt);
    //ch.real()でx座標,ch.imag()でy座標
    rep(i,Size(ch)){
      ll vec1x,vec1y;
      ll vec2x,vec2y;
      ll x1,x2,y1,y2;
      if(i==0){
        x1=ch[Size(ch)-1].real();
        y1=ch[Size(ch)-1].imag();
      }
      else{
        x1=ch[i-1].real();
        y1=ch[i-1].imag();
      }
      if(i==Size(ch)-1){
        x2=ch[0].real();
        y2=ch[0].imag();
      }
      else{
        x2=ch[i+1].real();
        y2=ch[i+1].imag();
      }

      ///////////////2つのベクトルがなす角
