vector<V> convexhull(vector<V> &ps) {int n = (int) ps.size();    if (n <= 2) {        return ps;    }    vector<V> res(2 * n);    std::sort(ps.begin(), ps.end(), [&](V &l, V &r) {        if (l.x != r.x)return l.x < r.x;        else return l.y < r.y;    });    int k = 0;    for (int i = 0; i < n; ++i) {        if (k >= 2) {            while (cross(res[k - 1] - res[k - 2], ps[i] - res[k - 2]) < eps) {                --k;                if (k < 2) break;            }        }        res[k] = ps[i];        ++k;    }    int t = k + 1;    for (int i = n - 2; i >= 0; --i) {        if (k >= t) {            while (cross(res[k - 1] - res[k - 2], ps[i] - res[k - 2]) < eps) {                --k;                if (k < t) break;            }        }        res[k] = ps[i];        ++k;    }    res.resize(k - 1);    return res;}

