    }
    cout << fixed << setprecision(15);
    if(ps_orige.size() == 2) {
        cout << 0.5 << endl;
        cout << 0.5 << endl;
        return 0;
    }
    auto ps = convex_hull(ps_orige);
    vector<D> ans(n);
    rep(i, ps.size()) {
        auto cur = curr(ps, i);
        auto pre = prev(ps, i);
        auto nxt = next(ps, i);
        D a = atan2((pre - cur).Y, (pre - cur).X);
        D b = atan2((nxt - cur).Y, (nxt - cur).X);
        D dif = max(a, b) - min(a, b);
        rep(j, n) {
            if(cur == ps_orige[j]) {
                ans[j] = abs((PI - dif) / (2*PI));
            }
        }
    }
    rep(i, n) {
        cout << ans[i] << endl;
    }
    return 0;
}

