#define PI   (3.14159265359)

struct Range {
    double start;
    double end;
    bool flag;
    void assert_range() {
        assert(this->start <= this->end);
    }
    Range() {
        this->flag = false;
    }
    Range(double start, double end) {
        this->flag = true;
        this->start = start;
        this->end = end;
        this->assert_range();
    }
    void merge(const Range &r) {
        if (!(this->flag)) {
            this->start = r.start;
            this->end = r.end;
            this->flag = true;
            return;
        }

        while (abs(this->start - r.start) > PI) {
            if (this->start < r.start) {
                this->start += 2. * PI;
                this->end += 2. * PI;
            }
            else {
                this->start -= 2. * PI;
                this->end -= 2. * PI;
            }
        }

        this->start = max(this->start, r.start);
        this->end = min(this->end, r.end);

        if (this->start > this->end) this->start = this->end = 0.0;
        this->assert_range();
    }

    double prob() {
        return (end - start) / (2.0 * PI);
    }

};

