using namespace std;

typedef pair<int, int> pii;
#define x first
#define y second

bool cmp(pair<pii,int> a, pair<pii,int> b) {
     return a.x.x < b.x.x || (a.x.x == b.x.x && a.x.y < b.x.y);
}

bool cw(pii a, pii b, pii c) {
     return a.x * (b.y - c.y) + b.x * (c.y - a.y) + c.x * (a.y - b.y) < 0;
}

bool ccw(pii a, pii b, pii c) {
     return a.x * (b.y - c.y) + b.x * (c.y - a.y) + c.x * (a.y - b.y) > 0;
}


vector<pair<pii, int>> convex_hull(vector<pair<pii, int>> d) {
     sort(d.begin(), d.end(), cmp);

     auto p1 = d[0];
     auto p2 = d.back();
     vector<pair<pii, int>> up;
     vector<pair<pii, int>> down;
     up.push_back(p1);
     down.push_back(p2);

     for (int i = 1; i < (int)d.size(); ++i) {
          if (i == (int)d.size() - 1 || cw(p1.first, d[i].first, p2.first)) {
               while (up.size() > 1 && !cw(up[up.size() - 2].first, up.back().first, d[i].first)) {
                    up.pop_back();
               }
               up.push_back(d[i]);
          }
          if (i == d.size() - 1 || ccw(p1.first, d[i].first, p2.first)) {
               while (down.size() > 1 && !ccw(down[down.size() - 2].first, down.back().first, d[i].first)) {
                    down.pop_back();
               }
               down.push_back(d[i]);
          }
     }
     vector<pair<pii, int>> res;
     for (auto el : up) {
          res.push_back(el);
     }

     for (int i = down.size() - 2; i > 0; --i) {
          res.push_back(down[i]);
     }
     return res;
}

double cp(pii a, pii b) {
     return a.x * b.y - a.y * b.x;
}

double dp(pii a, pii b) {
     return a.x * b.x + a.y * b.y;
}

double getangle(pii a, pii b, pii c) {
     pii fir = {b.first - a.first, b.second - a.second};
     pii sec = {c.first - b.first, c.second - b.second};
     double an = atan2(cp(fir, sec), dp(fir, sec));
     if (an < 0) {
          an += M_PI;
     }
     return an;
}


signed main() {
     int n;
     cin >> n;
     if (n == 2) {
          cout << 0.5 << endl << 0.5 << endl;
          return 0;
     }
     vector<pair<pii, int>> d(n);
     vector<double> ans(n, 0);
     int cnt = 0;
     for (auto &el : d) {
          cin >> el.first.first >> el.first.second;
          el.second = cnt;
          cnt++;
     }
     d = convex_hull(d);
     //d.push_back(d.back());
     for (int i = 0; i < d.size(); ++i) {
          int prev = (i - 1 < 0 ? d.size() - 1 : i - 1);
          int nxt = (i + 1) % d.size();
          ans[d[i].second] = (M_PI - getangle(d[prev].first, d[i].first, d[nxt].first)) / (2 * M_PI);
     }
     cout.precision(20);
     for (auto el : ans) {
          cout << el << endl;
     }
     return 0;
}

