      REP(i,k){
	auto &p0 = ch[i];
	auto &p1 = ch[(i-1+k)%k];
	auto &p2 = ch[(i+1)%k];

	double a = fabs(angle(p0,p2) - angle(p0,p1));
	if(a>M_PI) a = 2*M_PI-a;

	a = (M_PI-a)/(2*M_PI);
	ans[m[p0]] = a;
      }
    }

