using namespace std;
typedef complex<double> point;

point anchor;
constexpr int MX_N=101;
int N;
point vertices[MX_N];
int perm[MX_N];
double out[MX_N];

double dist(const point& a, const point& b){
    return abs(a-b);
}

int cross(const point& a, const point& b){
    return real(a)*imag(b) - imag(a)*real(b);
}

bool angleCmp(const point& a, const point& b){
    point relA = a-anchor;
    point relB = b-anchor;
    if(cross(relA,relB)==0)
        return dist(a,anchor) < dist(b,anchor);
    return arg(relA) < arg(relB);
}

bool ccw(const point& a,const point& b, const point& c){
    if(a==b || b==c || a==c)
        return false;
    point u = b-c;
    point v = b-a;
    int cr = cross(u,v);
    return cr > 0;
}

int main(){
    scanf("%d",&N);
    double x,y;
    for(int i = 0; i < N; i++){
        scanf("%lf %lf",&x,&y);
        vertices[i]=point(x,y);
        perm[i]=i;
    }
    sort(perm,perm+N,
            [](int a, int b){
                const point &pa = vertices[a];
                const point &pb = vertices[b];
                if(real(pa)!=real(pb))
                    return real(pa) < real(pb);
                return imag(pa) < imag(pb);
            });
    vector<int> L;
    vector<int> U;
    for(int i = 0; i < N;){
        int t = L.size();
        if(t >= 2 && !ccw(vertices[L[t-2]],vertices[L[t-1]],vertices[perm[i]]))
            L.pop_back();
        else
            L.push_back(perm[i++]);
    }
    for(int i = N-1; i >=0;){
        int t = U.size();
        if(t >= 2 && !ccw(vertices[U[t-2]],vertices[U[t-1]],vertices[perm[i]]))
            U.pop_back();
        else
            U.push_back(perm[i--]);
    }
    vector<int> hull;
    for(int i = 0; i < L.size()-1; ++i)
        hull.push_back(L[i]);
    for(int i = 0; i < U.size()-1; ++i)
        hull.push_back(U[i]);
    int h = hull.size();
    if(h == 2){
        out[hull[0]] = out[hull[1]] = 0.5;
    } else {
        for(int i = 0;i < h; ++i){
            //a -> b -> c
            point a = vertices[hull[(h+(i-1))%h]];
            point b = vertices[hull[i]];
            point c = vertices[hull[(i+1)%h]];
            //printf("(%lf,%lf)->(%lf,%lf)->(%lf,%lf)\n",real(a),imag(a),real(b),imag(b),real(c),imag(c));
            point ab = (b-a)*point(0,1);
            point cb = (b-c)*point(0,-1);
            //printf("ab:(%lf,%lf) cb:(%lf,%lf)\n",real(ab),imag(ab),real(cb),imag(cb));
            double ang = abs(arg(ab)-arg(cb))/(2*M_PI);
            //printf("(%lf,%lf):%lf\n",real(b),imag(b),min(1-ang,ang));
            out[hull[i]] = min(1-ang,ang);
        }
    }
    for(int i = 0; i < N; ++i){
        printf("%.16lf\n",out[i]);
    }
    return 0;
}

