using point_t = pair<int, int>;

point_t sub(point_t p1, point_t p2) {
  return point_t{p1.first - p2.first, p1.second - p2.second};
}

int quad_norm(point_t p) { return p.first * p.first + p.second * p.second; }

const int R           = 1e9;
const int separations = 5e6;

int nearest_index(point_t point, vector<point_t> points) {
  int dist_min  = INF;
  int index_min = 0;

  rep(i, points.size()) {
    auto distance = quad_norm(points[i] - point);
    if (distance < dist_min) {
      dist_min  = distance;
      index_min = i;
    }
  }
  return index_min;
}

signed main() {
  int N = readint();
  vector<point_t> points;
  rep(i, N) points.push_back(point_t{readint(), readint()});
  vector<int> count(N, 0);

  for (double i = 0; i < 2 * M_PI; i += (2 * M_PI) / separations) {
    count[nearest_index(point_t{R * cos(i), R * sin(i)}, points)]++;
  }
  rep(i, N) printf("%0.50lf\n", count[i] / (double)separations);
  return 0;
}

