inline DD arg(Vector a,Vector b){
    DD d=dot(a,b)/( a.dis()*b.dis() );
    if(abs(d)>1.0) d=(int)d;
    DD ret=acosl( d );
    if(cross(a,b)>0) return ret;
    else 2*PI+ret;
}
