inline pair<Point,Point> crossPoint(Circle c,Line l){
    assert(dis(l,c.c)<c.r+EPS);
    Point pr=project(l,c.c);
    Vector e=(l.p2-l.p1)/(dis(l.p2,l.p1));
    DD base=sqrt(c.r*c.r-(pr-c.c).norm());
    return make_pair(pr+e*base,pr-e*base);
}

