//外心
//isParallel()を使って判定を忘れずに
inline Point circumcenter(Point A,Point B,Point C){
    assert(!isParallel(A-B,A-C));
    DD a=(B-C).norm();
    DD b=(A-C).norm();
    DD c=(A-B).norm();
    return ( ( A*a*(b+c-a)+ B*b*(c+a-b)+ C*c*(a+b-c) )/  (a*(b+c-a)+ b*(c+a-b)+ c*(a+b-c) ) );
}


