struct Coordinate {
	long double x;
	long double y;
	bool operator <(const Coordinate& c)const {
		if (y < c.y)return true;
		if (y > c.y)return false;
		if (x < c.x)return true;
		return false;
	}
	bool operator >(const Coordinate& c)const {
		if (y > c.y)return true;
		if (y < c.y)return false;
		if (x > c.x)return true;
		return false;
	}
	Coordinate operator +(const Coordinate& c)const {
		Coordinate box;
		box.x = x + c.x;
		box.y = y + c.y;
		if (abs(box.x) < EPS) {
			box.x = 0;
		}
		if (abs(box.y) < EPS) {
			box.y = 0;
		}
		return box;
	}
	Coordinate operator -(const Coordinate& c)const {
		Coordinate box;
		box.x = x - c.x;
		box.y = y - c.y;
		if (abs(box.x) < EPS) {
			box.x = 0;
		}
		if (abs(box.y) < EPS) {
			box.y = 0;
		}
		return box;
	}
	long double dot(Coordinate a) {
		return x*a.x + y*a.y;
	}
	long double det(Coordinate a) {
		return x*a.y - y*a.x;
	}
	long double dis() {
		return sqrt(x*x + y*y);
	}
};

struct Convex_hull {
