vector<PL> qs(201);
vec convex_hull(int n, vector<PL> &plot, vec &ord){
    int k = 0;
    vec res(201);
    rep(i,n){
        while(k > 1 && (qs[k-1] - qs[k-2]).det(plot[ord[i]] - qs[k - 1]) <= 0) --k;
        qs[k] = plot[ord[i]];
        res[k++] = ord[i];
    }
    for(int i = n - 2, t = k; i >= 0; --i){
        while(k > t && (qs[k - 1] - qs[k - 2]).det(plot[ord[i]] - qs[k - 1]) <= 0) --k;
        qs[k] = plot[ord[i]];
        res[k++] = ord[i];
    }
    qs.resize(k - 1);
    res.resize(k - 1);
    return res;
}

long double pct(PL b, PL n, PL f){
    PL u = n - b, v = f - n;
    long double cs = u.dot(v);
    cs /= sqrt(u.dot(u));
    cs /= sqrt(v.dot(v));
    //cout<<acos(cs)<<endl;
    return acos(cs);
}

