double sqr(double a) {
    return a * a;
}

bool dEqual(double a, double b) {
    return fabs(a - b) < EPS;
}

bool dLess(double a, double b) {
    return a < b && !dEqual(a, b);
}

bool dLessOrEqual(double a, double b) {
    return a < b || dEqual(a, b);
}

bool dGereater(double a, double b) {
    return a > b && !dEqual(a, b);
}

bool dGreaterOrEqual(double a, double b) {
    return a > b || dEqual(a, b);
}

struct Point;
struct Vector;

struct Point {
    double x, y;
    int ind;

    Point(double x = 0, double y = 0) : x(x), y(y) {}

    Point operator+(const Vector &a) const;

    Point &operator+=(const Vector &a);

    Point operator-(const Vector &a) const;

    Point &operator-=(const Vector &a);

    double distTo(const Point &a) const; // dist to point a
    double distTo(const Point &a, const Point &b) const; // dist to line(a, b)
    Point getH(const Point &a, const Point &b) const; // h from this to line(a, b)
    bool isOnLine(const Point &a, const Point &b) const; // this is on line(a, b)?
    bool isInSegment(const Point &a, const Point &b) const; // this is in segment(a, b)?
    bool isInSegmentStrictly(const Point &a, const Point &b) const;
};

struct Vector {
    double x, y;

    Vector(double x = 0, double y = 0) : x(x), y(y) {}

    Vector(const Point &a, const Point &b) :
            x(b.x - a.x), y(b.y - a.y) {}

    Vector operator+(const Vector &a);

    Vector &operator+=(const Vector &a);

    Vector operator-(const Vector &a) const;

    Vector &operator-=(const Vector &a);

    Vector operator*(double k) const;

    Vector &operator*=(double k);

    Vector operator/(double k) const;

    Vector &operator/=(double k);

    double operator*(const Vector &a) const;

    double operator%(const Vector &a) const;

    bool isZero() const;

    double len() const;

    void norm(double k = 1);

    void rotate(); // rotate 90(ccw, 3*rotate() => cw)
    void rotate(double cosa, double sina); // rotate cos, sin
    void rotate(double alph); // rotate alph(ccw, alph < 0 => cw)
    double getAngle() const; // get polar angle
    double getAngle(const Vector &u) const;
};

Point Point::operator+(const Vector &a) const {
    return Point(x + a.x, y + a.y);
}

Point &Point::operator+=(const Vector &a) {
    x += a.x, y += a.y;
    return *this;
}

Point Point::operator-(const Vector &a) const {
    return Point(x - a.x, y - a.y);
}

Point &Point::operator-=(const Vector &a) {
    x -= a.x, y -= a.y;
    return *this;
}

Vector Vector::operator+(const Vector &a) {
    return Vector(x + a.x, y + a.y);
}

Vector &Vector::operator+=(const Vector &a) {
    x += a.x, y += a.y;
    return *this;
}

Vector Vector::operator-(const Vector &a) const {
    return Vector(x - a.x, y - a.y);
}

Vector &Vector::operator-=(const Vector &a) {
    x -= a.x, y -= a.y;
    return *this;
}

Vector Vector::operator*(double k) const {
    return Vector(x * k, y * k);
}

Vector &Vector::operator*=(double k) {
    x *= k, y *= k;
    return *this;
}

Vector Vector::operator/(double k) const {
    return Vector(x / k, y / k);
}

Vector &Vector::operator/=(double k) {
    x /= k, y /= k;
    return *this;
}

double Vector::operator%(const Vector &a) const {
    return x * a.x + y * a.y;
}

double Vector::operator*(const Vector &a) const {
    return x * a.y - y * a.x;
}

double Vector::len() const {
    return sqrt(*this % *this);
}

void Vector::norm(double k) {
    *this *= k / len();
}

void Vector::rotate() {
    swap(x, y);
    x = -x;
}

void Vector::rotate(double alph) {
    rotate(cos(alph), sin(alph));
}

void Vector::rotate(double cosa, double sina) {
    Vector v = *this;
    auto u = v;
    u.rotate();
    *this = v * cosa + u * sina;
}

double Vector::getAngle() const {
    return atan2(y, x);
}

double Vector::getAngle(const Vector &u) const {
    Vector v = *this;
    return atan2(v * u, v % u); // sin, cos
}

bool Vector::isZero() const {
    return dEqual(x, 0) && dEqual(y, 0);
}

double Point::distTo(const Point &a) const {
    return Vector(*this, a).len();
}

double Point::distTo(const Point &a, const Point &b) const {
    double d = a.distTo(b);
    double s = Vector(a, *this) * Vector(b, *this);
    return fabs(s) / d;
}

Point Point::getH(const Point &a, const Point &b) const {
    Point c = *this;
    Vector v(a, b), u(a, c);
    double k = v % u / v.len();
    v.norm(k);
    return a + v;
}

bool Point::isOnLine(const Point &a, const Point &b) const {
    return dEqual(Vector(*this, a) * Vector(*this, b), 0);
}

bool Point::isInSegment(const Point &a, const Point &b) const {
    return isOnLine(a, b) && dLessOrEqual(Vector(*this, a) % Vector(*this, b), 0);
}

bool Point::isInSegmentStrictly(const Point &a, const Point &b) const {
    return isOnLine(a, b) && dLess(Vector(*this, a) % Vector(*this, b), 0);
}

int getIntersection(const Point &a, const Point &b, // line(a, b, line(c, d), res in o
                    const Point &c, const Point &d, // returns num of inters points (2 == inf)
                    Point &o) {
    Vector v(a, b);
    double s1 = Vector(a, c) * Vector(a, d);
    double s2 = Vector(b, d) * Vector(b, c);
    double s = s1 + s2;
    if (dEqual(s, 0)) {
        if (!a.isOnLine(c, d)) {
            return 0;
        }
        return 2;
    }
    v = v / s;
    v = v * s1;
    o = a + v;
    return 1;
}

int getIntersection(const Point &a, double rA, const Point &b, double rB,
                    Point &m, Point &n) { // circle(a, rA), circle(b, rB)
    double d = a.distTo(b);
    if (dLess(rA + rB, d) || dLess(d, fabs(rA - rB))) {
        return 0;
    }
    double la = (sqr(rA) - sqr(rB) + sqr(d)) / 2 /
                d; // длину проекции отрезка (от A до пересечения окружностей) на прямую AB
    double lh = sqr(sqr(rA) - sqr(la)); //расстояние о точки пересечения окружностей до прямой AB
    Vector v(a, b), u(a, b); //направляющий вектор прямой AB
    u.rotate(); // нормальный вектор к прямой AB
    v.norm(la);
    u.norm(lh); //нормируем до нужных длин оба вектора
    Point h = a + v;
    m = h + u, n = h - u;
    if (u.isZero()) return 1; //если u = 0, то окружности касаются
    return 2;
}

int getIntersection(const Point &a, const Point &b, // line(a, b), circle(o, r)
                    const Point &o, double r,
                    Point &m, Point &n) {
    double h = o.distTo(a, b);
    if (dLess(r, h)) {//если окружность далеко от прямой
        return 0;
    }
    Point H = o.getH(a, b); //уронили высоту на AB
    Vector v(a, b); //взяли направляющий вектор прямой
    double k = sqrt(sqr(r) - sqr(h)); // величина, на которую надо подвинуть H до точки пересечения окружности и прямой
    v.norm(k);
    m = H + v;
    n = H - v;
    if (v.isZero()) return 1;
    return 2;
}

