void solve() {
	hull[0] = hull[top];
	hull[top + 1] = hull[1];
	for(int i = 1; i <= top; i++) {
		Vector sa = hull[i - 1] - hull[i];
		Vector sb = hull[i + 1] - hull[i];
		hull[i].pb = (PI - acos(prod(sa, sb) / (dis(sa, Point(0LL, 0LL)) 
		                 * dis(sb, Point(0LL, 0LL))))) / (2.0 * PI);
	}
	for(int i = 1; i <= n; i++) {
