struct P {
  long long x, y;
  int id;
  P operator - (const P & b) const {
    return P{x - b.x, y - b.y};
  }

  void operator += (const P & b) {
    x += b.x, y += b.y;
  }

  long long operator * (const P & b) const {
    return x * b.y - y * b.x;
  }

  long long operator ^ (const P & b) const {
    return x * b.x + y * b.y;
  }

  long long cross(const P & b, const P & c) const {
    return (b - *this) * (c - *this);
  }

   bool isRight() const {
    return x > 0 || (x == 0 && y > 0);
  }

  bool operator < (const P & b) const {
    if(isRight() != b.isRight())
      return isRight();
    return *this * b < 0;
  }

  bool operator == (const P & b) const {
    return make_pair(x, y) == make_pair(b.x, b.y);
  }
};

long double getAlpha(const P &a, const P &b) {
  return atan2((long double) (a * b), (long double) (a ^ b));
}

