double unghi(P A, P B, P C)
{
    A.x -= B.x; A.y -= B.y; C.x -= B.x; C.y -= B.y;
    double angle = atan2(A.y, A.x) - atan2(C.y, C.x);
    if(angle < 0) angle += 2*PI;
    return angle;
}

bool good(int i, int j, int k)
{
    ll res;
    res = (ll) a[i].x * a[j].y + (ll) a[j].x * a[k].y + (ll) a[k].x * a[i].y;
    res -= (ll) a[i].x * a[k].y + (ll) a[j].x * a[i].y + (ll) a[k].x * a[j].y;
    return (res >= 0);
}

void solve()
{
    sort(a+1, a+n+1);

    int nr, add, i;
    st[nr = 1] = 1;
    for(i=2, add = 1; !used[1]; i += add)
    {
        if(i == n) add = -1;
        if(used[i]) continue;

        while(nr>=2 && !good(st[nr-1], st[nr], i)) used[st[nr--]] = 0;
        st[++nr] = i, used[i] = 1;
    }

    double sum = 0;
    for(i=2; i<nr; ++i)
        ans[st[i]] = PI - unghi(a[st[i-1]], a[st[i]], a[st[i+1]]);
    ans[st[1]] = PI - unghi(a[st[nr-1]], a[st[1]], a[st[2]]);

    for(i=1; i<nr; ++i) sum += ans[st[i]];
    for(i=1; i<nr; ++i) ans[st[i]] /= sum;
}

