vi convexhull_i(vector<V> &ps) {    int n = (int) ps.size();    if (n <= 2) {        if (n == 1)return vi{0};else return vi{0, 1};}vi res(2 * n);vi ind = iota(0, n);    std::sort(ind.begin(), ind.end(), [&](int l, int r) {        if (ps[l].x != ps[r].x)return ps[l].x < ps[r].x;        else return ps[l].y < ps[r].y;    });    int k = 0;    for (int i = 0; i < n; ++i) {        if (k >= 2) {            while (cross(ps[res[k - 1]] - ps[res[k - 2]], ps[ind[i]] - ps[res[k - 2]]) < eps) {                --k;                if (k < 2) break;            }        }        res[k] = ind[i];        ++k;    }    int t = k + 1;    for (int i = n - 2; i >= 0; --i) {        if (k >= t) {            while (cross(ps[res[k - 1]] - ps[res[k - 2]], ps[ind[i]] - ps[res[k - 2]]) < eps) {                --k;                if (k < t) break;            }        }        res[k] = ind[i];        ++k;    }    res.resize(k - 1);    return res;}

