        mp[P(x[i], y[i])] = i;
        po.push_back(Point(x[i], y[i]));
    }
    if(n == 2){
        cout << 0.5 << endl << 0.5 << endl;
        return 0;
    }
    Polygon ch = Convex_Hull(po);
    vector<double> ans(n, 0.0);
    int sz = ch.size();
    rep(i, 0, ch.size()){
        Point now = ch[i];
        Point pre = ch[(i - 1 + sz) % sz];
        Point next = ch[(i + 1) % sz];
        // double d1 = (now.y - pre.y) / (now.x - pre.x);
        // double d2 = (next.y - now.y) / (next.x - now.x);
        int id = mp[P((int)now.x, (int)now.y)];
        // double m1 = -1.0 / d1;
        // double m2 = -1.0 / d2;
        double m1;
        double m2;
        if(fabs(now.y - pre.y) < EPS) m1 = INF;
        else m1 = -(now.x - pre.x) / (now.y - pre.y);
        if(fabs(next.y - now.y) < EPS) m2 = INF;
        else m2 = -(next.x - now.x) / (next.y - now.y);
        // cout << d1 << ' ' << d2 << ' ' << m1 << ' ' << m2 << endl;     
        double tn, tmp;
        if(fabs(m1 * m2 + 1.0) < EPS){
            tmp = 0.250000000;
        }else if(fabs(m2) > 1e9 || fabs(m1) > 1e9){
            if(fabs(m1) > 1e9){
                double th1 = -PI / 2.0;
                if(m1 > 1e9) th1 = PI / 2.0;
                double th2 = atan(m2);
            }else{
                double th2 = -PI / 2.0;
                if(m2 > 1e9) th2 = PI / 2.0;
                double th1 = atan(m1);
            }
            tmp = (th2 - th1) / (2.0 * PI);
        }else{
            tn = (m2 - m1) / (1.0 + m1 * m2);
            tmp = atan(tn) / (2.0 * PI);
            if(tn < -EPS){
                tmp = (atan(tn) + PI) / (2.0 * PI);
            }
        }
        ans[id] = tmp;
    }
    rep(i, 0, n){
        printf("%.15f\n", ans[i]);
    }
}

