using namespace std;

typedef long long ll;

const double PI = acos(-1.0);

struct pt {
    int x, y, id;

    pt() {
        x = y = id = 0;
    }
};

double ans[105];

vector<pt> arr;

int n;

int orient(pt a, pt b, pt c) {
    ll val = (b.y - a.y) * (c.x - b.x) - (c.y - b.y) * (b.x - a.x);

    if (val < 0) {
        val = -1;
    }

    if (val > 0) {
        val = 1;
    }

    return val;
}

ll distSq(pt a, pt b) {
    return (a.x - b.x) * (a.x - b.x) + (a.y - b.y) * (a.y - b.y);
}

bool cmp(pt a, pt b) {
    int cur = orient(arr[0], a, b);

    if (cur == 0) {
        return distSq(arr[0], a) <= distSq(arr[0], b);
    }

    return cur == -1;
}

void convexHull() {
    {
        int p = 0;

        for (int i = 1; i < arr.size(); ++i) {
            if (arr[i].y < arr[p].y) {
                p = i;
            }
            else if (arr[i].y == arr[p].y && arr[i].x < arr[p].x) {
                p = i;
            }
        }

        swap(arr[0], arr[p]);
    }

    sort(arr.begin() + 1, arr.end(), cmp);
    int m = 1;

    for (int i = 1; i < arr.size(); ++i) {
        while (i < arr.size() - 1 && orient(arr[0], arr[i], arr[i + 1]) == 0) {
            ++i;
        }

        arr[m++] = arr[i];
    }

    arr.resize(m);

    if (m < 3) {
        return;
    }

    vector<pt> S;
    S.pb(arr[0]);
    S.pb(arr[1]);

    for (int i = 2; i < m; ++i) {
        while (S.size() > 2 && orient(S[S.size() - 2], S.back(), arr[i]) != -1) {
            S.pop_back();
        }

        S.pb(arr[i]);
    }

    arr = S;
}

void solve() {
    scanf("%d", &n);

    for (int i = 1; i <= n; ++i) {
        pt cur;
        scanf("%d %d", &cur.x, &cur.y);
        cur.id = i;
        arr.pb(cur);
    }

    convexHull();
    int sz = arr.size();

    for (int i = 0; i < sz; ++i) {
        pt p1 = arr[(i - 1 + sz) % sz];
        pt p2 = arr[i];
        pt p3 = arr[(i + 1) % sz];

        ll a = distSq(p1, p2);
        ll b = distSq(p2, p3);
        ll c = distSq(p1, p3);

        double alpha = acos((a + b - c) / (2.0 * sqrt(a) * sqrt(b)));
        ans[arr[i].id] = (PI - alpha) / (2.0 * PI);
    }

    for (int i = 1; i <= n; ++i) {
        printf("%.12f\n", ans[i]);
    }
}

int main() {
    int tt = 1;

    while (tt--) {
        solve();
    }

    return 0;
}

