typedef long long ll;

struct point { 
    ll x, y; int i; 
    point() {}
    point(ll x, ll y) : x(x), y(y) {}
};

int compare(ll d1, ll d2)
{
    if(d2 - d1 > 0) return -1;
    if(d1 - d2 > 0) return 1;   
    return 0;
}

int turn(point p, point q, point r)
{
    ll result = (r.x - q.x) * (p.y - q.y) - (r.y - q.y) * (p.x - q.x);
    return compare(result, 0); 
}

bool cw(point p, point q, point r)
{
    return turn(p, q, r) < 0;
}

bool cmp(point p1,point p2)
{
    return p1.x < p2.x || (p1.x == p2.x && p1.y < p2.y);
}

vector<point> convexHull(vector<point> P)
{
    int n = (int)P.size(), k = 0;
    vector<point> H(2 * n);
    sort(P.begin(), P.end(),cmp);
    for(int i = 0; i < n; i++)   
    {
        while(k >= 2 && cw(H[k - 2], H[k - 1], P[i])) k--;
        H[k++] = P[i];
    }
    for(int i = n - 2, t = k + 1; i >= 0; i--) 
    {
        while(k >= t && cw(H[k - 2], H[k - 1], P[i])) k--;
        H[k++] = P[i];
    }
    H.resize(k); H.pop_back(); 
    return H;
}

// dot product 
double dot(point p, point q) { return p.x * q.x + p.y * q.y; }
// modulo^2 de un punto (distance to origin)
double norm2(point p) { return p.x * p.x + p.y * p.y; }


double angle(point a, point o, point b) // angle AOB (radians)
{
   point u(a.x - o.x, a.y - o.y); // u: vector oa
   point v(b.x - o.x, b.y - o.y); // v: vector ob
   return acos(dot(u,v) / sqrt(norm2(u) * norm2(v))); // dot product
}


