	/* 偏角で並べる, 偏角が等しいものは同じとみなす(そのため set などには使えない) */
	int Vector::compareByArg(const Vector& left, const Vector& right) {
		/* ゼロベクトルは最も小さいとする */
		if (left.isZero()) return right.isZero() ? 0 : -1;
		if (right.isZero()) return 1;

		/* どちらか1つの偏角が PI 以上の場合、そちらが大きい */
		bool left_less = left.argIsLessThenPi();
		bool right_less = right.argIsLessThenPi();
		if (left_less && !right_less) return -1;
		if (!left_less && right_less) return 1;

		/* 両方とも PI より小さいか、PI 以上の場合は外積で比較 */
		return -sign(cross(left, right));
	}

