	CCWEnum ccw(const Vector& a, const Vector& b, const Vector& p) {
		Vector ab = b - a;
		Vector ap = p - a;
		Int crs = cross(ab, ap);
		if (crs > 0) return CCWEnum::Counterclockwise;
		if (crs < 0) return CCWEnum::Clockwise;
		if (dot(ab, ap) < 0) return CCWEnum::BackwardOnLine;
		if (ab.norm2() < ap.norm2()) return CCWEnum::ForwardOnLine;
		return CCWEnum::Internal;
	}

