	Line::Line(const Vector& normal, Int constant)
		: normal(normal), constant(constant) {
		reduce();
	}

	/* (x_1, y_1), (x_2, y_2) を通る直線 → 直線 -(y_2 - y_1)x + (x_2 - x_1)y + (x_1 y_2 - x_2 y_1) = 0 */
	Line::Line(const Vector& p, const Vector& q)
		: Line(p.y - q.y, q.x - p.x, cross(p, q)) {
	}

	Line::Line(const Segment& s)
		: Line(s.a, s.b) {
	}

	/* 表現を一意にする */
	void Line::reduce() {
		assert(!normal.isZero());

		/* normal と c の値は既約とする */
		std::vector<Int> list{ normal.x, normal.y, constant };
		Int gcd = 0;

		for (Int element : list) {
			gcd = GCD(gcd, std::abs(element));
		}

		/* 0 <= normal.arg < PI とする */
		if (!normal.argIsLessThenPi()) {
			gcd = -gcd;
		}

		normal.x /= gcd;
		normal.y /= gcd;
		constant /= gcd;
	}

	bool Line::contains(const Vector& p) const {
		return dot(normal, p) == constant;
	}

	int Line::compare(const Line& left, const Line& right) {
		if (left.normal < right.normal) return -1;
		if (left.normal > right.normal) return 1;
		if (left.constant < right.constant) return -1;
		if (left.constant > right.constant) return 1;
		return 0;
