	double distance(const Segment& s, const Vector& p) {
		/* 点 a が最も近い */
		Vector ab = s.b - s.a;
		Vector ap = p - s.a;
		if (dot(ab, ap) <= 0) return ap.norm();

		/* 点 b が最も近い */
		Vector ba = -ab;
		Vector bp = p - s.b;
		if (dot(ba, bp) <= 0) return bp.norm();

		/* それ以外 → 点と直線の距離 */
		return distance(Line(s), p);
	}

	bool hasIntersection(const Segment& s, const Segment& t) {
		return (int)ccw(s.a, s.b, t.a) * (int)ccw(s.a, s.b, t.b) <= 0
			&& (int)ccw(t.a, t.b, s.a) * (int)ccw(t.a, t.b, s.b) <= 0;
	}

