	/* 0 <= x && x < mod の範囲に入るような剰余計算 */
	int Polygon::modPositive(int val, int mod) {
		assert(mod > 0);
		if (val < 0) return (mod - 1) - (~val) % mod;
		return val % mod;
	}

	void Polygon::add(const Vector& point) {
		points.push_back(point);
	}

	void Polygon::reverse() {
		std::reverse(points.begin(), points.end());
	}

