		return points.size();
	}

	Int Polygon::areaTwice(bool oriented) const {
		const int N = size();
		if (N <= 2) return 0;

		Int sum = 0;
		for (int i = 0; i < N; ++i) {
			Vector a = points[i];
			Vector b = points[i == N - 1 ? 0 : i + 1];
			sum += cross(a, b);
		}
		return oriented ? sum : std::abs(sum);
	}

	/* 同一直線上にある場合を考慮していない && 自己交差も考えていない */
	bool Polygon::isConvex(bool oriented) const {
		const int N = size();
		if (N <= 2) return true;

		CCWEnum first_ccw = ccw(points[0], points[1], points[2]);
		if (oriented) {
			if (first_ccw != CCWEnum::Counterclockwise) return false;
		}

		for (int i = 1; i < N; ++i) {
			const Vector& a = points[i];
			const Vector& b = points[(i + 1) % N];
			const Vector& c = points[(i + 2) % N];
			if (first_ccw != ccw(a, b, c)) return false;
		}
		return true;
	}

