	/*---------------------------------*/
	/*---------   グローバル   --------*/
	/*---------------------------------*/

	/* 点群の凸包を構成 O(n log n) */
	/* 一直線上に並ぶ点を保持するなら is_strict == false とする (同一点は保持しないので注意) */
	// verified CGL_4_A (is_strict == false)
	Polygon convexHull(const std::vector<Vector>& points_arg, bool is_strict) {
		/* 凸包上の位置関係として望ましいかどうか */
		auto isInPlace = [is_strict](const Vector& a, const Vector& b, const Vector& c) -> bool {
			CCWEnum res = ccw(a, b, c);
			if (is_strict) {
				return res == CCWEnum::Counterclockwise;
			} else {
				return res == CCWEnum::Counterclockwise || res == CCWEnum::ForwardOnLine;
			}
		};

		/* 凸包の半分を構成 */
		auto constructHalf = [isInPlace](const std::vector<Vector>& points) -> std::vector<Vector> {
			std::vector<Vector> ret;
			for (const Vector& point : points) {
				/* 望ましい位置関係になるまで点を削除 */
				while (true) {
					int n = ret.size();
					if (n < 2) break;
					if (isInPlace(ret[n - 2], ret[n - 1], point)) break;
					ret.pop_back();
				}
				ret.push_back(point);
			}
			ret.pop_back();		// 上下を合わせた際に重複しないよう終点を削除しておく
			return ret;
		};

		std::vector<Vector> points(points_arg);
		sort(points.begin(), points.end());		// x座標でソート

		Polygon ret;

		/* 下半分を構成 */
		for (const Vector& vertex : constructHalf(points)) {
			ret.add(vertex);
		}

		/* 点の並びを反転させてもう一度実行 */
		reverse(points.begin(), points.end());

		/* 下半分を構成 */
		for (const Vector& vertex : constructHalf(points)) {
			ret.add(vertex);
		}

		return ret;
	}

	/* 凸多角形に対して、ベクトル dir 方向に最も遠い点 (dir との内積が最大の点) の添字を返す O(log n) */
	/* polygon は狭義凸である必要がある(一直線上に並ぶ三点があってはならない) */
	int farthestPointConvex(const Polygon& polygon, const Vector& dir) {
		/* 目的関数値 */
		auto f = [&polygon, &dir](int i) -> Int {
			return dot(polygon[i], dir);
		};

		assert(polygon.size() > 0);
		if (polygon.size() == 1) return 0;

		//if (f(0) == f(1)) {
		//	/* f(0) == f(1) のとき、f(0) は最大値か最小値である */
		//	/* 最大値であるケースを先に判定しておく */
		//	if (f(0) > f(-1)) return 0;
		//}

		if (f(1) >= f(0)) {
			/* i == 0 における傾きが正のとき */
			/* [値 >= f(0) かつ 傾き >= 0] の領域 (lo) とそれ以外 (hi) で二分探索 */
			int lo = 0;
			int hi = polygon.size();

			while (hi - lo > 1) {
				int mid = (lo + hi) / 2;
				if (f(mid) >= f(0) && f(mid + 1) >= f(mid)) {
					lo = mid;
				} else {
					hi = mid;
				}
			}
			return hi;
		} else {
			/* i == 0 における傾きが負のとき */
			/* [値 >= f(0) かつ 傾き < 0] の領域 (hi) とそれ以外 (lo) で二分探索 */
			int lo = 0;
			int hi = polygon.size();

			while (hi - lo > 1) {
				int mid = (lo + hi) / 2;
				if (f(mid) >= f(0) && f(mid + 1) < f(mid)) {
					hi = mid;
				} else {
					lo = mid;
				}
			}
			return hi;
		}
	}
