typedef complex<LD> vec2;

const LD EA = 1e-9;

vec2 uv(vec2 a){							//単位ベクトル
	return a / abs(a);
}

LD dot(vec2 a , vec2 b){				//内積 a・b = |a||b|cosθ
	return a.real() * b.real() + a.imag() * b.imag();
}

LD cross(vec2 a , vec2 b){				//外積 a×b = |a||b|sinθ
	return a.real() * b.imag() - a.imag() * b.real();
}

LD pab(vec2 a , vec2 b){				//２点a,b間の距離
	return abs(vec2(a - b));
}

LD dis(vec2 a , vec2 b , vec2 c){		//点aと直線bcの距離
	return abs(cross(a - c , b - c)) / pab(b , c);
}

LD dis_s(vec2 a , vec2 b , vec2 c){		//点aと線分bcの距離
	return dot(a - b , c - b) < 0 ? pab(a , b) : (dot(a - c , b - c) < 0 ? pab(a , c) : dis(a , b , c));
}

vec2 ls(vec2 a , vec2 b , vec2 c){			//点aの直線bcに対称な点
	vec2 x = uv(b - c);
	vec2 y = (a - c) / x;
	return vec2(y.real() , -y.imag()) * x + c;
}

LD x_int(vec2 a , vec2 b){				//直線abのx切片,存在しない場合NaN<isnanで判定>
	return cross(a , b) / (b.imag() - a.imag());
}

bool is_sects(vec2 a , vec2 b , vec2 c , vec2 d){		//線分abと線分cdの交点の存在
	LD x = dis(c , a , b);
	LD y = dis(d , a , b);
	if(-EA < x && x < EA && -EA < y && y < EA){
		return dot(a - c , b - c) <= 0 || dot(a - d , b - d) <= 0 || dot(c - a , d - a) <= 0 || dot(c - b , d - b) <= 0;
	} else {
		return cross(a - b , c - b) * cross(a - b , d - b) <= 0 && cross(c - d , a - d) * cross(c - d , b - d) <= 0;
	}
}

vec2 lin_sp(vec2 a , vec2 b , vec2 c , vec2 d){			//直線abと直線cdの交点
	vec2 s = uv(b - a);
	return vec2(x_int((c - a) / s , (d - a) / s) , 0.0) * s + a;
}

bool cir_sp(vec2 a , LD r , vec2 b , LD s , vec2 &p , vec2 &q){		//円の交点
	LD d = pab(a , b);
	if(!(s - r <= d && r - s <= d && d <= r + s)) return 0;
	LD x = (d * d + r * r - s * s) / 2 / d;
	p = vec2(x , -sqrt(r * r - x * x)) * uv(vec2(b.real() - a.real() , b.imag() - a.imag())) + a;
	q = ls(p , a , b);
	return 1;
}

bool cl_sp(vec2 a , LD r , vec2 b , vec2 c , vec2 &p , vec2 &q){		//円aと直線bcの交点
	vec2 x = uv(b - c);
	vec2 y = (a - c) / x;
	LD d = r * r - y.imag() * y.imag();
	if(d < 0) return 0;
	p = vec2(y.real() + sqrt(d) , 0) * x + c;
	q = vec2(y.real() - sqrt(d) , 0) * x + c;
	return 1;
}

//凸包,反時計回り,直線上に乗る点も含む

bool comp_CH(const vec2 &a , const vec2 &b){
	LD c = cross(a , b);
	if(abs(c) < EA){
		return abs(a) > abs(b);
	}
	return c > 0;
}

int CH(vec2 p[] , int n , vec2 q[]){
	int r = 0;
	for(int i = 1 ; i < n ; ++i){
		if(p[r].imag() > p[i].imag() || (p[r].imag() == p[i].imag() && p[r].real() > p[i].real())) r = i;
	}
	vec2 s = p[0];
	p[0] = p[r];
	p[r] = s;
	for(int i = 1 ; i < n ; ++i) p[i] -= p[0];
	sort(p + 1 , p + n , comp_CH);
	r = 1;
	int t = 2;
	q[0] = vec2(0 , 0);
	if(abs(cross(p[1] , p[2])) < EA){
		while(abs(cross(p[1] , p[t + 1])) < EA) ++t;
		for(int i = t ; i > 0 ; --i){
			q[r] = p[i];
			++r;
		}
	} else {
		q[1] = p[1];
		q[2] = p[2];
		r = 3;
	}
	for(int i = t + 1 ; i < n ; ++i){
		if(abs(cross(p[i - 1] , p[i])) < EA) continue;
		while(cross(p[i] - q[r - 1] , q[r - 2] - q[r - 1]) < 0) --r;
		q[r] = p[i];
		++r;
		t = i;
	}
	++t;
	while(t < n){
		q[r] = p[t];
		++r;
		++t;
	}
	for(int i = 0 ; i < r ; ++i) q[i] += p[0];
	return r;
}

