// https://prefield.com/algorithm/geometry
/*
 * P: 点
 * L: 直線・半直線・線分を2点で定義 半直線はL[0]からL[1]方向に伸びる
 * VP: 点の配列、あるいは多角形
 * C: 円
 */

// point
using P = complex<ld>;

// two points: line
using L = array<P, 2>;

// points
using VP = vector<P>;

// circle
struct C {
  P c;
  ld r;
  C(const P &c_, ld r_) : c(c_), r(r_) {}
  C(ld x_, ld y_, ld r_) : c({x_, y_}), r(r_) {}
};

using VC = vector<C>;

// input
void Pin(P &a) {
  ld tmp;
  cin >> tmp;
  a.real(tmp);
  cin >> tmp;
  a.imag(tmp);
}

// output
void Pout(const P &a) {
  cout << a.real() << " " << a.imag();
}

namespace std {
