struct cT
{
	cT () : x ( 0 ), y ( 0 ) {}
	cT ( int _x, int _y ) : x ( _x ), y ( _y ) {}

	cT operator + ( const cT &a ) const
	{
		return cT ( x + a.x, y + a.y );
	}

	cT operator - ( const cT &a ) const
	{
		return cT ( x - a.x, y - a.y );
	}

	LL operator * ( const cT &a ) const
	{
		return SC ( LL, x ) * a.x + SC ( LL, y ) * a.y;
	}

	LL operator ^ ( const cT &a ) const
	{
		return SC ( LL, x ) * a.y - SC ( LL, y ) * a.x;
	}

	bool operator < ( const cT &a ) const
	{
		return ( x ^ a.x ) ? ( x < a.x ) : ( y < a.y );
	}

	LL abs ()
	{
		return SC ( LL, x ) *  x + SC ( LL, y ) * y;
	}

	LD len ()
	{
		return sqrt ( abs () );
	}

	int x, y;
}cr[MAXN];

