            ans[h[i].i] = (M_PI - angle(h[!i? m-1 : i-1], h[i], h[i==m-1? 0 : i+1])) / 2 / M_PI;
        for(int i = 0; i < n; i++)
            cout << ans[i] << '\n';
    }
    return 0;
}

