const ld EPS = 1e-8;

bool equals (const ld &a, const ld &b) {
    return abs(a - b) < EPS;
}

struct Vec2 {
    ld x, y;
    Vec2(ld x = 0, ld y = 0) : x(x), y(y) {}

    Vec2 &operator+=(const Vec2 &p) {
        x += p.x;
        y += p.y;
        return *this;
    }

    Vec2 &operator-=(const Vec2 &p) {
        x -= p.x;
        y -= p.y;
        return *this;
    }

    Vec2 &operator*=(const ld &a) {
        x *= a;
        y *= a;
        return *this;
    }

    Vec2 &operator/=(const ld &a) {
        x /= a;
        y /= a;
        return *this;
    }

    Vec2 operator+(const Vec2 &p) const {
        return Vec2(*this) += p;
    }

    Vec2 operator-(const Vec2 &p) const {
        return Vec2(*this) -= p;
    }

    Vec2 operator*(const ld &a) const {
        return Vec2(*this) *= a;
    }

    Vec2 operator/(const ld &a) const {
        return Vec2(*this) /= a;
    }

    bool operator<(const Vec2 &p) const {
        if (x < p.x) return true;
        if (x > p.x) return false;
        return y < p.y;
    }

    ld sqrtNorm() const {
        return x*x + y*y;
    }

    ld norm() const {
        return sqrt(sqrtNorm());
    }

    Vec2 unit() const {
        return Vec2(*this) / norm();
    }

    Vec2 rotate90() const {
        return Vec2(y, -x);
    }

    ld innerProduct(const Vec2 &p) {
        return x*p.x + y*p.y;
    }

    ld outerProduct(const Vec2 &p) {
        return x*p.y - y*p.x;
    }

    ld angle(const Vec2 &p) {
        ld theta = acos(innerProduct(p) / norm() / p.norm());
        if (outerProduct(p) < 0) return 2*M_PI - theta;
        return theta;
    }

    friend ostream &operator<<(ostream &os, const Vec2 &p) {
        return os << "{" << p.x << "," << p.y << "}";
    }
};

vi convexHull(const vector<Vec2> &points) {
    int n = points.size();
    vector<pair<Vec2, int>> ps(n);
    REP (i, n) ps[i] = make_pair(points[i], i);
    sort(ALL(ps));
    vi ret;
    int idx = 0;
    do {
        int next = (idx+1)%n;
        REP (i, n) if (i != idx) {
            // 直線上にあるなら遠い方を採用
            if (equals((ps[idx].first - ps[next].first).angle(ps[idx].first - ps[i].first), M_PI)) {
                if ((ps[idx].first - ps[next].first).norm() < (ps[idx].first - ps[i].first).norm()) next = i;
            } else if ((ps[idx].first - ps[next].first).angle(ps[idx].first - ps[i].first) > M_PI) {
                next = i;
            }
        }
        ret.push_back(next);
        idx = next;
    } while (ret[ret.size()-1] != 0);
    REP (i, ret.size()) ret[i] = ps[ret[i]].second;
    return ret;
}

const int MAX = 111;

int N;
int X[MAX], Y[MAX];

vector<ld> solve() {
    vector<Vec2> points(N);
    REP (i, N) points[i] = Vec2(X[i], Y[i]);
    vector<ld> ans(N, 0);
    vi res = convexHull(points);
    if (res.size() == 2) {
        REP (i, 2) ans[res[i]] = 0.5;
    } else {
        REP (j, res.size()) {
            int a = res[(j+1)%res.size()], b = res[(res.size()+j-1)%res.size()], i = res[j];
            ans[i] = 0.5 - (points[a] - points[i]).angle(points[b] - points[i]) / (2 * M_PI);
        }
    }
    return ans;
}

