typedef complex<double> P;
double cross(P a, P b) {
    return imag(conj(a)*b);
}
double dot(P a, P b) {
    return real(conj(a)*b);
}
/*
a->b->cと進むときの点の進行方向
+1: 反時計回り
-1: 時計回り
+2: c--a--b
-2: a--b--c
http://www.prefield.com/algorithm/geometry/ccw.html
*/
int ccw(P a, P b, P c) {
    b = b - a; c = c - a;
    if (cross(b, c) > 0) return +1;
    if (cross(b, c) < 0) return -1;
    if (dot(b, c) < 0) return +2;
    if (norm(b) < norm(c)) return -2;
    return 0;
}

/*
凸包を求める
O(nlgn)
Andrew's Monotone Chain
www.prefield.com/algorithm/geometry/convex_hull.html
*/
vector<P> convexHull(vector<P> ps) {
    int n = (int)ps.size();
    sort(begin(ps), end(ps), [&](P a, P b) {
        if (a.real() != b.real())return a.real() < b.real();
        else return a.imag() < b.imag();
    });
    int k = 0;
    vector<P> qs(n * 2);
    for (int i = 0; i<n; ++i) {
        while (k > 1 && ccw(qs[k - 2], qs[k - 1], ps[i]) <= 0) k--;
        qs[k++] = ps[i];
    }
    for (int i = n - 2, t = k; i >= 0; --i) {
        while (k>t && ccw(qs[k - 2], qs[k - 1], ps[i]) <= 0) k--;
        qs[k++] = ps[i];
    }
    qs.resize(k - 1);
    return qs;
}

/*
凸法を重心を中心にして偏角ソートする
(反時計回りにする)
*/
vector<P> sortConvexHull(vector<P> vertices) {
    // 重心
    P center(0, 0);
    for (P vertex : vertices) {
        center += vertex;
    }
    int number = (int)vertices.size();
    center /= number;
    vector<pair<double, int> > ordered(number);
    for (int i = 0; i < number; ++i) {
        P vertex = vertices[i] - center;
        ordered[i] = make_pair(atan2(vertex.imag(), vertex.real()), i);
    }
    sort(ordered.begin(), ordered.end());
    vector<P> res(number);
    for (int i = 0; i < number; ++i) {
        res[i] = vertices[ordered[i].second];
    }
    return res;
}

