    int chsize = ch.size();
    std::vector<double> out(n, 0);
    for (int i = 0; i < chsize; i++) {
        int tempx = -1 * (ch[(i + 1) % chsize].y - ch[i % chsize].y);
        int tempy = (ch[(i + 1) % chsize].x - ch[i % chsize].x);
        int lastx = -1 * (ch[i % chsize].y - ch[(i - 1 + chsize) % chsize].y);
        int lasty = (ch[i % chsize].x - ch[(i - 1 + chsize) % chsize].x);
        out[ch[i].num] = rad(tempx, tempy, lastx, lasty);
    }
