using namespace std;
typedef std::complex<double> P;
namespace std {
	bool operator < (const P& a, const P& b) {
		return real(a) != real(b) ? real(a) < real(b) : imag(a) < imag(b);
	}
}
double cross(const P& a, const P& b) {
	return imag(conj(a)*b);
}
double dot(const P& a, const P& b) {
	return real(conj(a)*b);
}
int ccw(P a, P b, P c) {
	b -= a; c -= a;
	if (cross(b, c) > 0)   return +1;       // counter clockwise
	if (cross(b, c) < 0)   return -1;       // clockwise
	if (dot(b, c) < 0)     return +2;       // c--a--b on line
	if (norm(b) < norm(c)) return -2;       // a--b--c on line
	return 0;
}
std::vector<P> convex_hull(std::vector<P> ps) {
	int n = ps.size(), k = 0;
	std::sort(ps.begin(), ps.end());
	std::vector<P> ch(2 * n);
	for (int i = 0; i < n; ch[k++] = ps[i++]) // lower-hull
		while (k >= 2 && ccw(ch[k - 2], ch[k - 1], ps[i]) <= 0) --k;
	for (int i = n - 2, t = k + 1; i >= 0; ch[k++] = ps[i--]) // upper-hull
		while (k >= t && ccw(ch[k - 2], ch[k - 1], ps[i]) <= 0) --k;
	ch.resize(k - 1);
	return ch;
}

signed main() {
	INIT;

	VAR(int, n);
	VEC_ROW(int, n, x, y);

	if (n == 2) {
		OUT(0.5)BR;
		OUT(0.5)BR;
		return 0;
	}

	std::vector<P> ps(n);
	REP(i, n) ps[i] = P(x[i], y[i]);
	auto p = convex_hull(ps);
	int sz = p.size();

	std::vector<double> ans(n, 0.0);
	REP(i, sz) {
		double a1 = real(p[(i + 0) % sz]) - real(p[(i + 1) % sz]);
		double a2 = imag(p[(i + 0) % sz]) - imag(p[(i + 1) % sz]);
		double b1 = real(p[(i + 2) % sz]) - real(p[(i + 1) % sz]);
		double b2 = imag(p[(i + 2) % sz]) - imag(p[(i + 1) % sz]);

		double theta = -(a1 * b1 + a2 * b2) / (std::sqrt(a1 * a1 + a2 * a2) * std::sqrt(b1 * b1 + b2 * b2));
		double t = std::acos(theta);
		if (t < 0) t = -t;

		{
			double min = 1e308;
			int mii = -1;
			REP(j, n) {
				double dist = std::hypot(x[j] - real(p[(i + 1) % sz]), y[j] - imag(p[(i + 1) % sz]));
				if (min > dist) {
					min = dist;
					mii = j;
				}
			}
			ans[mii] = t;
		}
	}

	double sum = 0;
	REP(i, n) {
		sum += ans[i];
	}
	REP(i, n) {
		ans[i] /= sum;
	}
	REP(i, n) {
		FOUT(12, ans[i])BR;
	}
	return 0;
}

