#define SIZE(a) ((int)(a).size())

const int N = 105;

struct pt {
	K x, y;
} a[N];

template <class T>
T sqr(T x) {
	return x*x;
}

K dist(const pt& a, const pt& b) {
	return sqrt(sqr(a.x-b.x) + sqr(a.y-b.y));
}

int n;
int cnt[N];

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);	

	cin >> n;
	REP(i, n) cin >> a[i].x >> a[i].y;

	const int I = 1000000;

	K now = 2*acos(-1.0)/I;

	REP(iter, I) {
		K ang = iter*now;
		pt now = {cos(ang)*1e9, sin(ang)*1e9};
		int id = 0;
		REP(i, n) {
			if (dist(now, a[i]) < dist(now, a[id])) {
				id = i;
			}
		}
		++cnt[id];
	}

	REP(i, n) {
		cout << setprecision(15) << fixed << (K)cnt[i]/(K)I << '\n';
	}

	return 0;
}

