double Ans[maxn];
struct node{
	int x,y,id;
	void print(){
		printf("x=%d y=%d\n",x,y);
	}
}a[maxn];
long long cross(const node &A,const node &B){
	return A.x*(long long)B.y-A.y*(long long)B.x;
}
long long operator * (const node &A,const node &B){
	return A.x*(long long)B.x+A.y*(long long)B.y;
}
node operator - (const node &A,const node &B){
	return (node){A.x-B.x,A.y-B.y,A.id};
}
bool cmp1(const node &A,const node &B){
	return A.x==B.x?A.y<B.y:A.x<B.x;
}
long long pf(const node &A){
	return A.x*(long long)A.x+A.y*(long long)A.y;
}
bool cmp2(const node &A,const node &B){
	if(cross(A,B)==0) return pf(A)<pf(B);
	return cross(A,B)>0;
}
double getdis(const node &A){
	return sqrt(A.x*(long long)A.x+A.y*(long long)A.y);
}
int main(){
//		freopen("B.in","r",stdin);
	int n;
	scanf("%d",&n);
	for(int i=1;i<=n;i++){
		scanf("%d%d",&a[i].x,&a[i].y);
		a[i].id=i;
	}
	sort(a+1,a+n+1,cmp1);
	for(int i=n;i>=1;i--)
		a[i]=a[i]-a[1];
	sort(a+2,a+n+1,cmp2);
	static node stk[maxn];
	int top=1;
	stk[1]=a[1];
	for(int i=2;i<=n;i++){
		while(top>1&&cross(a[i]-stk[top-1],stk[top]-stk[top-1])>=0)
			top--;
		stk[++top]=a[i];
	}
	if(top==1){
		for(int i=1;i<=top;i++)
			Ans[stk[i].id]=1.0;
	}
	else if(top==2){
		for(int i=1;i<=top;i++)
			Ans[stk[i].id]=0.5;
	}
	else{
		double x;
		for(int i=1;i<=top;i++){
			x=(stk[i%top+1]-stk[i])*(stk[(i+top-2)%top+1]-stk[i]);
			x=x/(getdis(stk[i%top+1]-stk[i])*getdis(stk[(i+top-2)%top+1]-stk[i]));
			Ans[stk[i].id]=(pi-acos(x))/(pi*2);
		}
	}
	for(int i=1;i<=n;i++)
		printf("%.10f\n",Ans[i]);
	return 0;
}

