typedef double real;
int n,m,ver[N];
char c[N],vis[N];
real x[N],y[N],ans[N];
int ne=0,h[N];struct edge{int to,x;}e[N*N];
inline void ins(int s,int t) {
	e[++ne].to=t;e[ne].x=h[s];h[s]=ne;
}
inline real abs(real a){return a<0?-a:a;}
inline real crm(real x1,real y1,real x2,real y2){return x1*y2-x2*y1;}
int main() {
	reg int i,j,k;
	reg char f,w;
	reg real b,t;
	scanf("%d",&n);
	for(i=1;i<=n;++i) scanf("%lf%lf",x+i,y+i);
	if(n<=3) {
		for(i=1;i<=n;++i) printf("%.12lf\n",1.0/n);
		return 0;
	}
	for(i=1;i<n;++i) {
		for(j=i+1;j<=n;++j) {
			f=0;w=1;
			for(k=1;k<=n;++k) {
				if(k!=i&&k!=j) {
					t=crm(x[i]-x[j],y[i]-y[j],x[i]-x[k],y[i]-y[k]);
					if(!f) f=1,b=t;
					else if(b*t<-EPS) {w=0;break;}
				}
			}
			if(w) {
				c[i]=c[j]=1;
				ins(i,j);ins(j,i);
			}
		}
	}
	m=0;
	for(i=1;i<=n;++i) {
		if(c[i]) {
			do {
				k=0;ver[m++]=i;vis[i]=1;
				for(j=h[i];j;j=e[j].x) if(!vis[e[j].to]) {
					i=e[j].to;k=1;break;
				}
			} while(k);
			break;
		}
	}
	ver[m]=ver[0];ver[m+1]=ver[1];
	for(i=1;i<=m;++i) {
		j=ver[i];
		ans[j]=0.5-abs(atan2(x[j]-x[ver[i-1]],y[j]-y[ver[i-1]])-atan2(x[j]-x[ver[i+1]],y[j]-y[ver[i+1]]))/(2*3.1415926535897932384);
	}
	for(i=1;i<=n;++i) printf("%.12lf\n",c[i]?ans[i]:0.0);
	return 0;
}

