double calc(int poz) {
    double r = 0;

    double px1 = (1.0 * x[poz] + x[poz - 1]) / 2, py1 = (1.0 * y[poz] + y[poz - 1]) / 2,
           px2 = (1.0 * x[poz] + x[poz + 1]) / 2, py2 = (1.0 * y[poz] + y[poz + 1]) / 2;

    px1 -= x[poz];
    px2 -= x[poz];
    py1 -= y[poz];
    py2 -= y[poz];


    double angle = atan2(py1, px1) - atan2(py2, px2);
    angle = angle * 360 / (2*pii);
    if (angle < 0){
        angle = angle + 360;
    }

    if(angle > 180)
        angle -= 180;


    angle = 180 - angle;

    return r = angle / 360.0;
}

