template <typename T>
// 点集合vvに対して凸包を作る
// ansに凸包の各点(vvでのインデックス)が入る
// 戻り値はansのサイズ
int convex_hull(vector<vec2d<T>> &vv, vector<int> &ans) {
    int n = (int)vv.size();
    size_t k = 0;
    vector<size_t> lid((size_t)n), _ans((size_t)n * 2);

    // vvを辞書順ソートしたときのインデックスの順列を作る
    iota(lid.begin(), lid.end(), 0);
    sort(lid.begin(), lid.end(), [&vv](size_t l, size_t r) {
        return vv[l] < vv[r];
    });

    // 下側
    for (int i=0; i<n; i++) {
        while (k > 1 && cross(vv[_ans[k-1]] - vv[_ans[k-2]], vv[lid[(size_t)i]] - vv[_ans[k-1]]) <= 0)
            k--;
        _ans[k] = lid[(size_t)i];
        k++;
    }

    // 上側
    for (int i=n-2, s=(int)k; i>=0; i--) {
        while ((int)k > s && cross(vv[_ans[k-1]] - vv[_ans[k-2]], vv[lid[(size_t)i]] - vv[_ans[k-1]]) <= 0)
            k--;
        _ans[k] = lid[(size_t)i];
        k++;
    }

    for (size_t i=0; i<k-1; i++) ans.push_back((int)_ans[i]);

    return (int)k-1;
}

using V = vec2d<ld>;

int main() {
    int n;
    cin >> n;
    vector<V> vv(n);
    for (auto &vvi:vv) cin >> vvi;
    vector<int> ch;
    int m = convex_hull(vv, ch);
    ld ans[n];
    fill(ans, ans+n, 0);
    V prev = vv[ch[m-1]];
    for (int i=0; i<m; i++) {
        V cur = vv[ch[i]],
          next = vv[ch[(i+1)%m]];
        ans[ch[i]] = acos(cos_between(cur - prev, next - cur)) / (2 * M_PI);
        prev = cur;
    }
    for (auto &ai:ans) cout << setprecision(15) << ai << '\n';
    return 0;
}

