        d.push_back(g);
    }
    vector<Point> key=convex_hull(d);
    double ans[105]={};
    rep(i,0,key.size()){
        if(!i){
            int l=key[i].z;
            Vector2D A={(key[1].x-key[0].x)/2,(key[1].y-key[0].y)/2};
            Vector2D B={(key[0].x-key[key.size()-1].x)/2,(key[0].y-key[key.size()-1].y)/2};
            ans[l]=AngleOf2Vector(A,B)/360.0;
        }
        else if(i==key.size()-1){
            int l=key[i].z;
            Vector2D A={(key[0].x-key[i].x)/2,(key[0].y-key[i].y)/2};
             Vector2D B={(key[i].x-key[i-1].x)/2,(key[i].y-key[i-1].y)/2};
            ans[l]=AngleOf2Vector(A,B)/360.0;
        }
