/*
点群をソートした後,x軸の左側から時計回りになるように点を拾っていく
これによって(簡単のため凸包を円とすると)凸包の上半分が求まる.
次に点群を右から時計回りとなるように拾っていく.
先ほどとは異なり,右から左への遷移であるため先の上半分は反時計回りの点列である..
そのため今回拾うのは左から右への遷移では反時計回りである点列である.
これら2つの点列をつなげることによって凸包を構成することができる.
*/
vector<Point> convex_hull(vector<Point> P)
{
    int n = P.size(), k = 0;
    vector<Point> H(2 * n);
    sort(P.begin(), P.end());
    for (int i = 0; i < n; i++) {
        while (k >= 2 && c_clockwise_delta(H[k - 2], H[k - 1], P[i]) <= 0)
            k--;
        H[k++] = P[i];
    }
    for (int i = n - 2, t = k + 1; i >= 0; i--) {  //n-1を省いているのは,最右端が凸包に含まれるならすでに上半分に含まれているため
        while (k >= t && c_clockwise_delta(H[k - 2], H[k - 1], P[i]) <= 0)
            k--;
        H[k++] = P[i];
    }
    H.resize(k - 1);
    return H;
}
double cosier(double a)
{
    if (a > 1.0) {
        return 1.0;
    } else if (a < -1.0) {
        return -1.0;
    } else {
        return a;
    }
}

double rad(int ax, int ay, int bx, int by)
{
    int tri = ax * bx + ay * by;
    double absa = sqrt(ax * ax + ay * ay);
    double absb = sqrt(bx * bx + by * by);
    return acos(cosier((tri / absa) / absb)) / (2 * acos(-1));
}

