    CV.n = n;
    for (int i = 0; i<n; i++)
    {
        D x, y;
        cin >> x >> y;
        CV.pt.push_back({x, y, i});
    }
    CV.graham_scan();
    CV.convex.push_back(CV.convex[0]);
    CV.convex.push_back(CV.convex[1]);
    int m = CV.convex.size();
    for (int i = 1; i<m-1; i++)
    {
        point a = CV.convex[i];
        point b = CV.convex[i-1];
        point c = CV.convex[i+1];
        //printf("%.2lf %.2lf, %.2lf %.2lf, %.2lf %.2lf\n",a.x,a.y,b.x,b.y,c.x,c.y);
        vt A = {b.x-a.x, b.y-a.y};
        vt B = {c.x-a.x, c.y-a.y};
        //printf("Vector %.2lf %.2lf and %.2lf %.2lf\n",A.dx,A.dy,B.dx,B.dy);
        D cth = A.inner(B)/(A.norm()*B.norm());
        D tha = acos(cth);
        if (tha < 0) tha = 0;
        if (tha > PI) tha = PI;
        //printf("%.4lf angle\n",tha*180/PI);
        prob[a.index] = (PI-tha)/(2*PI);
    }
    for (int i = 0; i<n; i++)
    {
        cout << fixed << setprecision(20)<< prob[i] << '\n';
    }
}

