const int MAX_N = 100 + 10;
const double pi = acos(-1.0);
const double eps = 1e-8;

int dcmp(double x) {
    if (fabs(x) < eps) return 0;
    else return x < 0 ? -1 : 1;
}

struct Point {
    int id;
    double x, y;
    Point(double x=0, double y=0):x(x), y(y) {}
    Point(int id, double x=0, double y=0):id(id), x(x), y(y) {}
    bool operator < (const Point& rhs) const {
        if (dcmp(x - rhs.x) == 0) return y < rhs.y;
        return x < rhs.x;
    }
} ps[MAX_N], ch[MAX_N];

typedef Point Vector;
typedef pair<int, int> pii;

Vector operator - (Point A, Point B) {
    return Vector(A.x - B.x, A.y - B.y);
}

double Cross(Vector A, Vector B) {
    return A.x * B.y - A.y * B.x;
}

double Dot(Vector A, Vector B) {
    return A.x * B.x + A.y * B.y;
}

double Length(Vector A) {
    return sqrt(Dot(A, A));
}

double Angle(Vector A, Vector B) {
    return acos(Dot(A, B) / Length(A) / Length(B));
}

int ConvexHull(Point* p, int n, Point* ch) {
    sort(p, p + n);
    int m = 0;
    for (int i = 0; i < n; i++) {
        while (m > 1 && dcmp(Cross(ch[m - 1] - ch[m - 2], p[i] - ch[m - 2])) <= 0) m--;
        ch[m++] = p[i];
    }
    int k = m;
    for (int i = n - 2; i >= 0; i--) {
        while (m > k && dcmp(Cross(ch[m - 1] - ch[m - 2], p[i] - ch[m - 2])) <= 0) m--;
        ch[m++] = p[i];
    }
    if (n > 1) m--;
    return m;
}

set<pii> st;
double ans[MAX_N];

int main() {
    int N, n = 0, x, y;
    scanf("%d", &N);
    for (int i = 0; i < N; i++) {
        scanf("%d%d", &x, &y);
        ans[i] = 0.0;
        if (st.find(pii(x, y)) == st.end()) {
            ps[n++] = Point(i, x, y);
            st.insert(pii(x, y));
        }
    }
    if (n == 1) {
        ans[ps[0].id] = 1;
    }
    else if (n == 2) {
        printf("fuck\n");
        ans[ps[0].id] = ans[ps[1].id] = 1;
    } else {
        int m = ConvexHull(ps, n, ch);
        for (int i = 0; i < m; i++) {
            int j = (i - 1 + m) % m;
            int k = (i + 1) % m;
            Vector v1 = ch[j] - ch[i];
            Vector v2 = ch[k] - ch[i];
            ans[ch[i].id] = pi - Angle(v1, v2);
        }
    }
    double sum = 0.0;
    for (int i = 0; i < N; i++) sum += ans[i];
    for (int i = 0; i < N; i++) ans[i] /= sum;
    for (int i = 0; i < N; i++) {
        printf("%.30f\n", ans[i]);
    }
    return 0;
}

