int last = -1;
int count2 = 0;

void solve() {
	for (double i = 0; i < 360; i += 1.0 / R) {
		double x = cos(i * 2 * 3.14159 / 360) * 10000000;
		double y = sin(i * 2 * 3.14159 / 360) * 10000000;
		double minDist = 999999999;
		int minIndex = -1;
		for (int j = 0; j < N; ++j) {
