			if (dist < minDist) {
				minDist = dist;
				minIndex = j;
			}
		}
		if (last >= 0 && minIndex != last && count2 <= 0) {
			R = R2;
			i-=1.0/R;
			count2 = 1;
			continue;
		} else {
			if (count2 >= 1) {
				++count2;
				if (count2 == 11) {
					count2 = 0;
					R = R1;
				}
				++result[minIndex];
			} else {
				result[minIndex] += 10;
			}
		}
		last = minIndex;
	}
}

