double getAng(point a, point b)
{
	double a1 = atan2(a.y, a.x);
	if (a1 < 0) a1 += 2 * PI;
	double a2 = atan2(b.y, b.x);
	if (a2 < 0) a2 += 2 * PI;

	double alpha = abs(a1 - a2);
	if (alpha > PI) alpha = 2 * PI - alpha;
	return PI - alpha;
}

