const int nmax = 100;
const double pi = acos(-1);

struct pct {
    int x, y, ind;

    bool operator < (const pct &shp) const {
        if (x != shp.x)
            return x < shp.x;
        return y < shp.y;
    }
} v[nmax + 1], st[nmax + 1];

vector< pct > inf;

double sol[nmax + 1];

inline int ccw (pct x, pct y, pct z) {
    long long ans = (1LL * x.x * y.y - 1LL * x.y * y.x +
                     1LL * y.x * z.y - 1LL * y.y * z.x +
                     1LL * z.x * x.y - 1LL * z.y * x.x);

    if (ans > 0) return 1;
    if (ans == 0) return 0;
    return -1;
}

int main() {
    int n;

    cin >> n;
    for( int i = 1; i <= n; ++ i ) {
        cin >> v[ i ].x >> v[ i ].y;
        v[ i ].ind = i;
    }
    sort(v + 1, v + n + 1);

    int t = 0;
    st[ ++ t ] = v[ 1 ];
    st[ ++ t ] = v[ 2 ];
    for( int i = 2; i <= n; ++ i ) {
        while ( t >= 2 && ccw(st[t - 1], st[ t ], v[ i ]) != 1) {
            -- t;
        }
        st[ ++ t ] = v[ i ];
    }
    for( int i = 1; i <= t; ++ i ) {
        inf.push_back( st[ i ] );
    }

    t = 0;
    st[ ++ t ] = v[ n ];
    st[ ++ t ] = v[ n - 1 ];
    for( int i = n - 2; i > 0; -- i ) {
        while ( t >= 2 && ccw(st[t - 1], st[ t ], v[ i ]) != 1) {
            -- t;
        }
        st[ ++ t ] = v[ i ];
    }

    for( int i = 2; i < t; ++ i ) {
        inf.push_back( st[ i ] );
    }

    for (int i = 0; i < (int)inf.size(); ++ i) {
        pct nxt = inf[ 0 ];
        pct ant = inf.back();

        if (i - 1 >= 0)
            ant = inf[i - 1];
        if (i + 1 < (int)inf.size())
            nxt = inf[i + 1];

        double u1 = atan2(ant.y - inf[ i ].y, ant.x - inf[ i ].x);
        double u2 = atan2(nxt.y - inf[ i ].y, nxt.x - inf[ i ].x);

        if (u1 > u2)
            swap(u1, u2);

        double dif = min(2 * pi - (u2 - u1), u2 - u1);

        sol[ inf[ i ].ind ] = (pi - dif) / (2 * pi);
    }

    cout << setprecision( 7 ) << fixed;
    for (int i = 1; i <= n; ++ i)
        cout << sol[ i ] << "\n";

    return 0;
}

