const ld EPS = 1e-9;

struct pt
{
    ld x, y;
    int clr;
};

ld operator*(pt a, pt b)
{
    return a.x * b.y - a.y * b.x;
}

int sgn(ld x)
{
    if(x < -EPS)
    {
        return -1;
    }
    if(x > EPS)
    {
        return 1;
    }
    return 0;
}


pt vec(pt a, pt b)
{
    return{b.x - a.x, b.y - a.y};
}

vector<pt> conv(vector<pt> a)
{
    pt mn = *min_element(all(a), [](const pt &a, const pt &b)
    {
        if(a.x != b.x)
        {
            return a.x < b.x;
        }
        return a.y < b.y;
    });

    sort(all(a), [=](const pt &a, const pt &b)
    {
        return sgn((mn, a) * vec(mn, b)) == 1;
    });

    vector<pt> ans;

    for(pt i : a)
    {
        while(sz(ans) > 2 && sgn(vec(ans[sz(ans) - 2], ans.back()) * vec(ans.back(), i)) <= 0)
        {
            ans.pop_back();
        }
        ans.push_back(i);
    }

    return ans;
}

