    for(int i = 0; i < n; ++i)
    {
        cin >> a[i].x >> a[i].y;
        a[i].clr = i;
    }

    a = conv(a);
    n = sz(a);

    for(int i = 0; i < n; ++i)
    {
        int pr = (i - 1 + n) % n;
        int nx = (i + 1) % n;
        ld a1 = atan2(-a[pr].x + a[i].x, a[pr].y - a[i].y);
        ld a2 = atan2(a[nx].x - a[i].x, -a[nx].y + a[i].y);
        ld diff = min(abs(a2 - a1), 2 * PI - abs(a2 - a1));
        ans[a[i].clr] = diff / (2 * PI);
    }

    for(int i = 0; i < nn; ++i)
    {
        cout << ans[i] << endl;
    }
}

