    FOR(i, 0, N){
        ll x, y;
        cin >> x >> y;
        P.push_back(Point(x, y));
    }

    if(N==2){
        p(0.5);
        p(0.5);
    }
    // N > 3, 垂直二等分線が2本はある想定
    else{
        // 一直線チェック
        if(is_straight_line(P)){
            // 端の2点だけ確率が0.5になる
            p(0.5);
            FOR(i, 0, P.size()-2){
                p(0);
            }
            p(0.5);
        }
        else{
            // それ以外。convex hullを求める
            convexHull(P);
        }
    }

    return 0;
}

