// a == b
bool eq( const double a, const double b )
{
	return abs( a - b ) <= EPS;
}

// 外積（クロス積）
double cross( const Point &a, const Point &b )
{
	return a.real() * b.imag() - a.imag() * b.real();
}

// x 座標優先
// include : eq
struct CompX : public binary_function<Point,Point,bool>
{
	bool operator ()( const Point &a, const Point &b ) const
	{
		return eq( a.real(), b.real() ) ? a.imag() < b.imag() : a.real() < b.real();
	}
};

// 点集合 ps の凸包（ Graham Scan ）
// include : cross, CompX
vector<Point> convex_hull( vector<Point> ps )
{
	const int N = ps.size();

	sort( ps.begin(), ps.end(), CompX() );

	int k = 0;
	vector<Point> convex( N * 2 );

	for ( int i = 0; i < N; i++ )
	{
		while ( 2 <= k && cross( convex[ k - 1 ] - convex[ k - 2 ], ps[i] - convex[ k - 1 ] ) <= EPS )
		{
			k--;
		}
		convex[ k++ ] = ps[i];
	}

	for ( int i = N - 2, t = k; 0 <= i; i-- )
	{
		while ( t < k && cross( convex[ k - 1 ] - convex[ k - 2 ], ps[i] - convex[ k - 1 ] ) <= EPS )
		{
			k--;
		}
		convex[ k++ ] = ps[i];
	}

	convex.resize( k - 1 );
	return convex;
}

// 法線ベクトル
Point normalVector1( const Point &a )
{
	return a * Point( 0, 1 );
}
Point normalVector2( const Point &a )
{
	return a * Point( 0, -1 );
}
int point_index( const VT< Point > &ps, const Point &q )
{
	REP( i, SZ( ps ) )
	{
		if ( abs( ps[i] - q ) <= EPS )
		{
			return i;
		}
	}

	assert( false );

	return -1;
}

int main()
{
	cin.tie( 0 );
	ios::sync_with_stdio( false );
	cout << setprecision( 12 ) << fixed;

	IN( int, N );

	if ( N == 2 )
	{
		cout << 0.5 << endl;
		cout << 0.5 << endl;
		return 0;
	}

	VT< Point > ps( N );
	cin >> ps;

	const auto convex = convex_hull( ps );
	const int M = SZ( convex );

	VT< double > res( N );
	REP( i, M )
	{
		const auto norm1 = normalVector1( convex[             i ] - convex[ ( i + 1 ) % M ] );
		const auto norm2 = normalVector2( convex[ ( i + 2 ) % M ] - convex[ ( i + 1 ) % M ] );
		const double theta =  arg( norm2 / norm1 );

		res[ point_index( ps, convex[ ( i + 1 ) % M ] ) ] = ( theta ) / ( 2 * PI );
	}

	copy( ALL( res ), ostream_iterator< double >( cout, "\n" ) );
	cout << flush;

	return 0;
}

