const double R1 = 1000.0;
const double R2 = 10000.0;
double R = R1;
int last = -1;
int count2 = 0;

void solve() {
	for (double i = 0; i < 360; i += 1.0 / R) {
		double x = cos(i * 2 * 3.14159 / 360) * 10000000;
		double y = sin(i * 2 * 3.14159 / 360) * 10000000;
		double minDist = 999999999;
		int minIndex = -1;
		for (int j = 0; j < N; ++j) {
			double dist = getDistance(Point(x, y), pList[j]);
			if (dist < minDist) {
				minDist = dist;
				minIndex = j;
			}
		}
		if (last >= 0 && minIndex != last && count2 <= 0) {
			R = R2;
			i-=1.0/R;
			count2 = 1;
			continue;
		} else {
			if (count2 >= 1) {
				++count2;
				if (count2 == 11) {
					count2 = 0;
					R = R1;
				}
				++result[minIndex];
			} else {
				result[minIndex] += 10;
			}
		}
		last = minIndex;
	}
}

