#define FILE_NAME "a"

struct point
{
    int x, y;

    point () : x(0), y(0) {}

    point (int x_, int y_) : x(x_), y(y_) {}

    point operator + (const point &o) const
    {
        return point (x + o.x, y + o.y);
    }

    point operator - (const point &o) const
    {
        return point (x - o.x, y - o.y);
    }

    ll operator * (const point &o) const
    {
        return (ll)x * o.x + (ll)y * o.y;
    }

    ll operator % (const point &o) const
    {
        return (ll)x * o.y - (ll)y * o.x;
    }

    bool operator < (const point &o) const
    {
        if (*this % o)
            return *this % o > 0;
        return *this * *this < o * o;
    }

    bool operator == (const point &o) const
    {
        return x == o.x && y == o.y;
    }

    void read () 
    {
        cin >> x >> y;
    }
};

bool is_less (const point &l, const point &r)
{
    if (l.x != r.x)
        return l.x < r.x;
    return l.y < r.y;
}

vector<point> v;
int n;

bool read() {
    if (!(cin >> n)) {
        return 0;
    }

    v.resize(n);
    forn (i, n)
        v[i].read();

    return 1;
}

using T = double;
const T pi = acos(-1.0);

T angle (const point &p, const point &q)
{
    return fabs(atan2(p % q, p * q));
}

void solve() {
    int where = 0;
    forn (i, n) if (is_less(v[i], v[where]))
        where = i;

    swap(v[where], v[0]);
    ford (i, n)
        v[i] = v[i] - v[0];

    auto orig_v = v;

    sort(v.begin() + 1, v.end());

    vector<point> res;
    res.pb(v[0]);

    forn (i, n) if (i)
    {
        point cur = v[i];
        while (sz(res) >= 2)
        {
            point last = res.back(), prev = res[sz(res) - 2];
            if ((last - prev) % (cur - last) <= 0)
                res.pop_back();
            else
                break;
        }

        res.pb(cur);
    }

    vector<T> ans(sz(res));

    assert(sz(res) >= 2);
    forn (i, sz(res))
    {
        point two = (res[(i + 1) % sz(res)] - res[i]);
        point one = (res[i] - res[(i + sz(res) - 1) % sz(res)]);
        ans[i] = angle(one, two) / (2 * pi);
    }

    forn (i, n)
    {
        int pos = find(all(res), orig_v[i]) - res.begin();
        if (pos != sz(res))
           printf("%.10f\n", (double)ans[pos]);
        else
           printf("0\n");
    }
}

int main() {
#ifdef LOCAL
    freopen(FILE_NAME ".in", "r", stdin);
//    freopen(FILE_NAME ".out", "w", stdout);
#endif

    while (read()) {
        solve();
    }

    return 0;
}

