ll dot(ii a, ii b){return 1ll*a.st*b.nd - 1ll*a.nd*b.st;}
ll yon(ii a, ii b, ii c){return dot(mp(b.st-a.st,b.nd-a.nd),mp(c.st-a.st,c.nd-a.nd));}
double ver(ii a, ii b){return a.st*b.st + a.nd*b.nd;}
double aci(ii a, ii b){return ver(a, b)/(sqrt(a.st*a.st + a.nd*a.nd)*sqrt(b.st*b.st + b.nd*b.nd));};
double bul(ii a, ii b, ii c){return acos(aci(mp(b.st-a.st,b.nd-a.nd),mp(c.st-a.st,c.nd-a.nd)))*180.0/PI;}

int main() {
	// freopen("in.txt", "r", stdin);
