	}
	sort(a + 1, a + n + 1);
	b[++bb] = a[1];
	for(int i = 2; i <= n; i++){
		while(bb >= 2 and yon(b[bb - 1].st, b[bb].st, a[i].st) > 0)
			bb--;
		b[++bb] = a[i];
	}
	c[++cc] = a[n];
	for(int i = n - 1; i >= 1; i--){
		while(cc >= 2 and yon(c[cc - 1].st, c[cc].st, a[i].st) > 0)
			cc--;
