vec convex_hull(vector<Pii> &x){
    int n = x.size();
    vector<PPi> x_(n);
    REP(i, n) x_[i] = PPi(x[i], i);
    Sort(x_);
    int k = 0;
    vec qs(2 * n);
    //下側
    REP(i, n){
        while(k > 1){
            int x1 = x[qs[k - 1]].first - x[qs[k - 2]].first;
            int y1 = x[qs[k - 1]].second - x[qs[k - 2]].second;
            int x2 = x_[i].first.first - x[qs[k - 1]].first;
            int y2 = x_[i].first.second - x[qs[k - 1]].second;
            if(x1 * y2 - x2 * y1 <= 0) k--;
            else break;
        }
        qs[k++] = x_[i].second;
    }
    int t = k;
    //上側
    IREP(i, n - 1){
        while(k > t){
            int x1 = x[qs[k - 1]].first - x[qs[k - 2]].first;
            int y1 = x[qs[k - 1]].second - x[qs[k - 2]].second;
            int x2 = x_[i].first.first - x[qs[k - 1]].first;
            int y2 = x_[i].first.second - x[qs[k - 1]].second;
            if(x1 * y2 - x2 * y1 <= 0) k--;
            else break;
        }
        qs[k++] = x_[i].second;
    }
    qs.resize(k - 1);
    return qs;
}

signed main(){

    int N; cin >> N;
    pairs x(N);
    REP(i, N){
        cin >> x[i].first >> x[i].second;
    }
    vec ch = convex_hull(x);
    int n = SZ(ch);
    //vdebug(ch);
    vector<double> ans(N, 0.0);
    REP(i, n){
        double v1x = x[ch[(i + 1) % n]].first - x[ch[i]].first;
        double v1y = x[ch[(i + 1) % n]].second - x[ch[i]].second;
        double v2x = x[ch[(i - 1 + n) % n]].first - x[ch[i]].first;
        double v2y = x[ch[(i - 1 + n) % n]].second - x[ch[i]].second;
        double ip = (v1x * v2x + v1y * v2y) / (sqrt(v1x * v1x + v1y * v1y) * sqrt(v2x * v2x + v2y * v2y));
        if(abs(ip) < 1.0) ans[ch[i]] = (M_PI - acos(ip)) / (2.0 * M_PI);
        else if(ip > 1.0) ans[ch[i]] = 0.5;
        else ans[ch[i]] = 0.0;
    }
    REP(i, N) cout << ans[i] << endl;

    return 0;
}

