}
//ccw 1, line 0, cw -1
template<class D>
int ccw(Vec2<D> a,Vec2<D> b,Vec2<D> c){
	return sgn(cross(b-a,c-a));
}
template<class D>
complex<double> toC(Vec2<D> v){
	return complex<double>(v.x,v.y);
}
//a->b->c と動くときに、どれだけ曲がるか
//直進する時は 0
template<class D>
double turnArg(Vec2<D> a,Vec2<D> b,Vec2<D> c){
	auto p=toC(b-a);
	auto q=toC(c-b);
	return arg(q/p);
}

//assume a,b,c lie on the same line
//returns if the order is a-b-c
//not verified
template<class D>
bool between(Vec2<D> a,Vec2<D> b,Vec2<D> c,bool inc=true){
	return sgn(dot(a-b,c-b))<=(inc?0:-1);
}

template<class D>
bool parallelVV(Vec2<D> a,Vec2<D> b){
	return !sgn(cross(a,b));
}

using P=Vec2<int>;

//no point is in a edge
vector<P> CalcConvex(vector<P> ps){
	{
		auto itr=min_element(ALL(ps));
		swap(*ps.begin(),*itr);
	}
	vector<P> convex;
	sort(ps.begin()+1,ps.end(),[&](P a,P b){
		int s=sgn(ccw(ps[0],a,b));
		if(s) return s>0;
		else return between(ps[0],a,b,false);
	});
	REP(i,ps.size()){
		while(int(convex.size())>=2){
			P a=convex[int(convex.size())-2];
			P b=convex[int(convex.size())-1];
			P c=ps[i];
			if(sgn(ccw(a,b,c))>0)
				break;
			convex.pop_back();
		}
		convex.PB(ps[i]);
	}
	return convex;
}

signed main(){
	int n=read();
	vector<P> ps(n);
	map<P,int> idx;
	REP(i,n){
		ps[i].x=read();
		ps[i].y=read();
		idx[ps[i]]=i;
	}
	vector<P> c=CalcConvex(ps);
	vector<double> ans(n,0);
	int s=c.size();
	REP(i,s){
		P p=c[(i+s-1)%s];
		P q=c[i];
		P r=c[(i+1)%s];
		double theta=turnArg(p,q,r);
		if(theta<0)
			theta+=2*PI;
		ans[idx[q]]=theta/(2*PI);
	}
	cout<<fixed<<setprecision(20);
	for(auto v:ans)
		cout<<v<<endl;
}

