const int MAX = 50;

double arg(Pair center, Pair pos) {
    return atan2(pos.second - center.second, pos.first - center.first);
}

int main() {
    int n;
    cin >> n;

    if (n == 2) {
        cout << 0.5 << endl << 0.5 << endl;
        return 0;
    }

    vector<Pair> hole(n);
    for (auto i = 0; i < n; i++) {
        cin >> hole[i].first >> hole[i].second;
    }

    vector<double> ans;
    for (auto c : hole) {
        vector<double> args;
        for (auto h : hole) {
            if (c == h)
                continue;
            args.push_back(arg(c, h));
        }
        sort(args.begin(), args.end());

        if (args.back() - args.front() <= M_PI) {
            auto theta = args.back() - args.front();
            ans.push_back(0.5 - theta / (2 * M_PI));
        } else {
            bool isConv = false;
            for (auto i = 0; i < args.size() - 1; i++) {
                if (args[i + 1] - args[i] >= M_PI) {
                    isConv = true;
                    auto theta = args[i + 1] - args[i];
                    ans.push_back(theta / (2 * M_PI) - 0.5);
                    break;
                }
            }
            if (!isConv)
                ans.push_back(0);
        }
    }

    for (auto a : ans)
        cout << a << endl;


}

