		return 0;
	}
	vector<Point> q = convex_hull(p);

	int m = q.size();
	for (int j = 0; j < m; j++) {
		ld costh = (q[mod(j - 1, m)] - q[j]).dot(q[mod(j + 1, m)] - q[j]);
		costh /= dif(q[mod(j - 1, m)], q[j]) * dif(q[mod(j + 1, m)], q[j]);
		// dump(acos(costh));
		ans[q[j].num] = (M_PI - acos(costh)) / (2 * M_PI);
	}
	for (int i = 0; i < n; i++) { dumpf(ans[i], 8); }
	return 0;
}

