  vector<P> qs(n*2);
  // こっちは凸包の辺上の点は凸包の要素に含まない
  for(int i=0;i<n;i++){
    while(k>1&&(cross(qs[k-1]-qs[k-2],ps[i]-qs[k-1])<0||EQ(cross(qs[k-1]-qs[k-2],ps[i]-qs[k-1]),0)))k--;
    qs[k++]=ps[i];
  }
  for(int i=n-2,t=k;i>=0;i--){
    while(k>t&&(cross(qs[k-1]-qs[k-2],ps[i]-qs[k-1])<0||EQ(cross(qs[k-1]-qs[k-2],ps[i]-qs[k-1]),0)))k--;
    qs[k++]=ps[i];
  }
  qs.resize(k-1);
  return qs;
}

int N;
int X[210];
int Y[210];
P ps[210];
double ress[210];

int get_idx(double x, double y){
    for(int i = 0; i < N; i++){
        if(EQ(x, X[i]) && EQ(y, Y[i]))
            return i;
    }
    return -1;
}

P roundPoint(const P &p,double a){
  return P(cos(a)*p.real()-sin(a)*p.imag(),sin(a)*p.real()+cos(a)*p.imag());
}


// 2ベクトル間の角度
// aからbへ左周りで何度か(0->2*PI)
double diffAngle(const P &a,const P &b){
  double angle=atan2(cross(a,b),dot(a,b));
  if(angle<0)
    return 2*PI+angle;
  return angle;
}

int main(){

