    for(int i = 0; i < N; i++) ps[i] = P(X[i], Y[i]);
    vector<P> ch = convex_hull(ps, N);


    if(ch.size() == 2){
        for(int i = 0; i < (int)ch.size(); i++){
            const int idx = get_idx(ch[i].real(), ch[i].imag());
            ress[idx] = 0.5;
        }
    }
    else{
        // for(int i = 0; i < (int)ch.size(); i++){
        //     cout << ch[i] << endl;
