        for(int i = 0; i < (int)ch.size(); i++){
            // ch[i-1]とch[i]のなす直線
            // ch[i]とch[i+1]のなす直線をもとめ、その間の角度を計算する
            P cp1 = (ch[(i-1+(int)ch.size()) % (int)ch.size()] - ch[i]); cp1 = roundPoint(cp1, PI/2);
            P cp2 = (ch[(i+1) % (int)ch.size()] - ch[i]); cp2 = roundPoint(cp2, 3*PI/2);
            double a = diffAngle(cp1, cp2);
            if(a >= PI) a = 2*PI - a;
            ress[get_idx(ch[i].real(), ch[i].imag())] = a / (PI * 2);
        }
    }

