int f(int l, int r, int k) {
    if (l > r) {
        return 0;
    }
    if (dp[l][r][k] != -1) {
        return dp[l][r][k];
    }

    int& res = dp[l][r][k];
    res = 0;

    if (l == r) {
        return res = 1;
    } else if (s[l] == s[r]) {
        chmax(res, 2 + f(l + 1, r - 1, k));
    } else if (k) {
        chmax(res, 2 + f(l + 1, r - 1, k - 1));
    }
    chmax(res, f(l + 1, r, k));
    chmax(res, f(l, r - 1, k));
    return res;
}

