	for(int i=0;i<n;i++){
		int x,y;
		cin>>x>>y;
		points.push_back(make_pair(x,y));
	}
	double total=0;
	for(int i=0;i<n;i++){
		double min_num;
		double max_num;
		bool isFirst=true;
		bool noans=false;
		for(int j=0;j<n;j++){
			if(i==j){
				continue;
			}
			double xdiff=points[j].first-points[i].first;
			double ydiff=points[j].second-points[i].second;
			double max_angle=atan2(xdiff,-1*ydiff);
			double min_angle=atan2(-1*xdiff,ydiff);
			if(max_angle<min_angle){
				max_angle+=2*M_PI;
			}
			//cout<<"i1="<<i<<"i2="<<j<<"min_angle="<<min_angle<<"max_angle="<<max_angle<<endl;
			if(isFirst){
				min_num=min_angle;
				max_num=max_angle;
				isFirst=false;
			}else{
				double temp_min=max(min_angle,min_num);
				double temp_max=min(max_angle,max_num);
				if(temp_min>temp_max){
					temp_min=max(min_angle+2*M_PI,min_num);
					temp_max=min(max_angle+2*M_PI,max_num);
					if(temp_min>temp_max){
						noans=true;
						break;
					}
				}
				min_num=temp_min;
				max_num=temp_max;


			}

		}
		if(noans){
			cout<<0<<endl;
		}else{
			double p=0;
			if(max_num>min_num){
				p=(max_num-min_num)/(2*M_PI);
			}else{
				p=(2*M_PI+max_num-min_num)/(2*M_PI);
			}
			total+=p;
			cout<<fixed<<setprecision(10)<<p<<endl;
		}
	}
	if(abs(total-1)>0.001){
		abort();
	}else{
