  }
  if (N==3) {
    printf("%.16f\n", double(1.0)/3);
    printf("%.16f\n", double(1.0)/3);
    printf("%.16f\n", double(1.0)/3);
    return 0;
  }

  convexHull();

  for (auto& kv : idx) {
    for (auto v : kv.SS) {
      idx[v].insert(kv.FF);
    }
  }
//  printf("=========================\n");
//  p();

  if (idx.size() == 2) {
    printf("0.5\n");
    printf("0.5\n");
    return 0;
  }

  map<int, double> solution;
  for (auto& kv : idx) {
    int c = kv.FF;
    auto it = kv.SS.begin();
    int l = *it;
    int r = *(++it);
//    printf("c: %d, l: %d, r: %d\n", c, l, r);
    Vector v1;
    Vector v2;
    v1.x = x[c] - x[l];
    v1.y = y[c] - y[l];
    v2.x = x[c] - x[r];
    v2.y = y[c] - y[r];

    double a = angle(v1, v2);
    if (a > M_PI) a -= M_PI;
    a = M_PI - a;

    double total = 2 * M_PI;
    solution[c] = a/total;
  }

  FORN(i, N) {
    printf("%.20f\n", solution[i]);
  }


  return 0;
}

