	cin >> N;
	vector<VEC::P> input(N);
	REP(i, N) {
		cin >> input[i].x >> input[i].y;
		input[i].index = i;
		input[i].prob = 0.0;
	}

	vector<VEC::P> qs=VEC::convex_hull(input,N);
	int K = SZ(qs);
	if (K ==2) {
		REP(i, SZ(qs)) {
			qs[i].prob = 0.5;
			input[qs[i].index].prob = 0.5;
		}
