typedef long double db;
struct cp
{
	complex<db> mycp;
	int ind;
	cp operator -(cp b)
	{
		return {mycp - b.mycp, -1};
	}
	db real()
	{
		return mycp.real();
	}
	db imag()
	{
		return mycp.imag();
	}
	bool operator ==(cp b)
	{
		return mycp == b.mycp;
	}
};
//typedef complex<db> cp;

db cross(cp a, cp b)
{
	return a.real() * b.imag() - a.imag() * b.real();
}

int main()
{
	int n;
	cin >> n;
	cout.precision(30);
	vector<cp> pts(n);	
	for (int i = 0; i < n; ++i)
	{
		db x, y;
		cin >> x >> y;
		pts[i].mycp.real(x);
		pts[i].mycp.imag(y);
		pts[i].ind = i;
	}
	cp mn = pts[0];
	for (cp x : pts)
		if (x.imag() < mn.imag() || x.imag() == mn.imag() && x.real() <= mn.real())
			mn = x;
	pts.erase(find(pts.begin(), pts.end(), mn));
	sort(pts.begin(), pts.end(), [&](cp a, cp b)
			{
				db kek = cross(a - mn, b - mn);
				if (kek)
					return kek > 0;
				return abs((a - mn).mycp) < abs((b - mn).mycp);
			});
	vector<cp> st(1, mn);
	for (auto x : pts)
	{
		while (st.size() >= 2 && cross(st.back() - st[st.size() - 2], x - st.back()) <= 0)
			st.pop_back();
		st.push_back(x);
	}
	vector<double> ans(n);
	//double M_PI = 3.14159265;
	for (int i = 0; i < st.size(); ++i)
	{
		int pr = i == 0 ? st.size() - 1 : i - 1;
		int nx = i + 1 == st.size() ? 0 : i + 1;
		ans[st[i].ind] = arg((st[nx] - st[i]).mycp / (st[i] - st[pr]).mycp) / M_PI / 2;
	}
	for (auto& x : ans)
		cout << x << '\n';
}

