vector<pair<int,int>> convex_hull(vector<pair<int,int>> P){
    int N=P.size();
    if(N<=1){
        return P;
    }
    vector<pair<int,int>> LH[2],V[2];
    sort(P.begin(),P.end());
    LH[0].push_back(P[0]);
    for(int i=0;i<N;i++){
        if((P[N-1].first-P[0].first)*(P[i].second-P[0].second)>=(P[N-1].second-P[0].second)*(P[i].first-P[0].first)){
            LH[1].push_back(P[i]);
        }else{
            LH[0].push_back(P[i]);
        }
    }
    LH[0].push_back(P[N-1]);
    reverse(LH[1].begin(),LH[1].end());

    for(int k=0;k<2;k++){
        for(int i=0;i<LH[k].size();i++){
            if(V[k].size()<2){
                V[k].push_back(LH[k][i]);
            }else{
                int j=V[k].size();
                if((V[k][j-1].first-V[k][j-2].first)*(LH[k][i].second-V[k][j-2].second)>=(V[k][j-1].second-V[k][j-2].second)*(LH[k][i].first-V[k][j-2].first)){
                    V[k].push_back(LH[k][i]);
                }else{
                    while(V[k].size()>=2){
                        j=V[k].size();
                        if((V[k][j-1].first-V[k][j-2].first)*(LH[k][i].second-V[k][j-2].second)<(V[k][j-1].second-V[k][j-2].second)*(LH[k][i].first-V[k][j-2].first)){
                            V[k].pop_back();
                        }else{
                            break;
                        }
                    }
                    V[k].push_back(LH[k][i]);
                }
            }
        }
    }

    P.clear();
    for(int i=0;i<V[1].size();i++){
        P.push_back(V[1][i]);
    }
    for(int i=1;i<V[0].size()-1;i++){
        P.push_back(V[0][i]);
    }
    return P;
}


