using namespace std;

const ll INF = 1e9;

struct TVector {
    ll x, y, id;
};

const double PI = acos(-1);
const long double EPS = 1e-8;

struct TLine {
    ll a, b, c;
    TLine(TVector A, TVector B) {
        a = A.y - B.y;
        b = B.x - A.x;
        c = A.y * B.x - B.y * A.x;
    }
    TLine(ll a1, ll b1, ll c1) {
        a = a1;
        b = b1;
        c = c1;
    }
    ll rast(TVector A) {
        ll top = abs(a * A.x + b * A.y - c);
        ll bot = sqrtl(a * a + b * b);
        if (abs(bot) < EPS) return 0;
        return top / bot;
    }
};

inline TVector operator+(TVector a, TVector b) {
    return TVector({a.x + b.x, a.y + b.y});
}

TVector operator-(TVector a, TVector b) {
    return TVector({a.x - b.x, a.y - b.y});
}

inline TVector operator*(TVector a, ll k) {
    return TVector({a.x * k, a.y * k});
}

inline ll operator%(TVector a, TVector b) {
    return a.x * b.x + a.y * b.y;
}

inline ll operator*(TVector a, TVector b) {
    return a.x * b.y - a.y * b.x;
}

inline bool operator==(TVector a, TVector b) {
    return abs(a.x - b.x) < EPS && abs(a.y - b.y) < EPS;
}

bool operator!=(TVector a, TVector b) {
    return !(a == b);
}
inline ll len(TVector a) {
    return sqrt(a % a);
}

inline TVector norm(TVector a) {
    return TVector({a.x / len(a), a.y / len(a)});
}

inline ll rast(TVector A, TVector B, TVector X) {
    TVector v1 = X - A;
    TVector v2 = B - A;
    TVector v3 = X - B;
    if (((v2 % v1 > 0) || (abs(v2 % v1) < EPS)) && ((v2 % v2 >= v2 % v1) || (abs(v2 % v2 - v2 % v1) < EPS))) {
        TLine l = TLine(A, B);
        return l.rast(X);
    }
    return min(len(v3), len(v1));
}

inline ll rast1(TVector A, TVector B, TVector X) {
    TVector v1 = X - A;
    TVector v2 = B - A;
    TVector v3 = X - B;
    if (((v2 % v1 > 0) || (abs(v2 % v1) < EPS))) {
        TLine l = TLine(A, B);
        return l.rast(X);
    }
    return min(len(v3), len(v1));
}

inline ll rast(TVector A, TVector B, TVector C, TVector D) {
    TLine l1 = TLine(A, B), l2 = TLine(C, D);
    TVector v1 = A - D, v2 = A - C, v3 = B - C, v4 = B - D;
    ll fmin = min(len(v1), min(len(v2), min(len(v3), len(v4))));
    ll smin = min(l1.rast(C), min(l1.rast(D), min(l2.rast(C), l2.rast(D))));
    return min(fmin, smin);
}

bool cmp(TVector a, TVector b) {
    if (abs(a.x - b.x) < EPS) {
        return a.y < b.y;
    }
    return a.x < b.x;
}

