map<P, int> toId;
P mid(P a, P b) {
    auto t = a + b;
    t.x /= 2;
    t.y /= 2;
    return t;
    double y = a.dot(a) + b.dot(b);
    auto x = a * b.dot(b) + b * a.dot(a);
    x.x /= y;
    x.y /= y;
    return x;
}
