int n;

typedef pair<pii, int> ppi;
ppi p[110];
pii operator-(pii a, pii b) { return pii(a.Fi - b.Fi, a.Se - b.Se); }
ll operator/(pii a, pii b) { return (ll)a.Fi * b.Se - (ll)a.Se * b.Fi; }
ll operator*(pii a, pii b) { return (ll)a.Fi * b.Fi + (ll)a.Se * b.Se; }
double ans[110];

void solve() {
	scanf("%d", &n);
	rep(i, n) {
		int x, y; scanf("%d%d", &x, &y);
		p[i] = make_pair(pii(x, y), i);
	}
	sort(p, p+n);
	for(int i=n-1;i>=0;i--) {
		p[i].Fi = p[i].Fi - p[0].Fi;
	}
	sort(p, p+n, [&](ppi a, ppi b) {
		ll t = a.Fi / b.Fi;
		if(t != 0) return t > 0;
		else return a.Fi * a.Fi < b.Fi * b.Fi;
	});
	vector <ppi> V;
	rep(i, n) {
		while(szz(V) > 1 && (p[i].Fi - V.back().Fi) / (V.back().Fi - V[szz(V)-2].Fi) >= 0) V.pop_back();
		V.push_back(p[i]);
	}
	if(szz(V) == 2) {
		ans[V[0].second] = ans[V[1].second] = 0.5;
	}
	else {
		rep(i, szz(V)) {
			pii px = V[i].Fi, py = V[(i+1)%szz(V)].Fi, pz = V[(i+szz(V)-1)%szz(V)].Fi;
			double t = atan2((py - px) / (pz - px), (py - px) * (pz - px));
			double P = acos(-1);
			t = P - t;
			t /= 2 * P;
			ans[V[i].second] = t;
		}
	}
	rep(i, n) printf("%.12f\n", ans[i]);
}

int main(){
	int Tc = 1; //scanf("%d\n", &Tc);
	for(int tc=1;tc<=Tc;tc++){
		solve();
	}
	return 0;
}

