	cin >> N;
	vector<long double>ans(N);
	map<Coordinate, int>m;
	Convex_hull ch(false);
	for (int i = 0; i < N; i++) {
		Coordinate c;
		cin >> c.x >> c.y;
		m[c] = i;
		ch.Add_node(c);
	}
	auto node = ch.solve();
	int num = node.size();
	for (int i = 1; i <= num; i++) {
		long double theta = (node[(i - 1) % num] - node[i%num]).dot(node[(i + 1) % num] - node[i%num]) / (node[(i - 1) % num] - node[i%num]).dis() / (node[(i + 1) % num] - node[i%num]).dis();
		theta = PI - acos(theta);
		ans[m[node[i%N]]] = theta / PI / 2;
	}
	for (auto i : ans) {
		cout << setprecision(15) << i << endl;
	}
	return 0;
}

