const double eps = 1e-12;

int fcmp(double x, double y) {
  if(x - y < eps && y - x < eps) return 0;
  return (x - y < eps ? -1 : 1);
}

struct Point {
  double x, y;
  int id;
  Point(double x = 0, double y = 0) : x(x), y(y) {}

  void Read(int il) {
    int xx, yy; id = il;
    scanf("%d%d", &xx, &yy);
    x = xx; y = yy;
  }

  bool operator < (const Point &b)const {
    return fabs(x - b.x) < eps ? y < b.y : x < b.x;
  }

  bool operator == (const Point &b)const {
    return fabs(x - b.x) < eps && fabs(y - b.y) < eps;
  }

  Point operator + (const Point &b)const {
    return Point(x + b.x, y + b.y);
  }

  Point operator - (const Point &b)const {
    return Point(x - b.x, y - b.y);
  }

  Point operator / (const double &b)const {
    return Point(x / b, y / b);
  }

  Point operator * (const double &b)const {
    return Point(x * b, y * b);
  }

  Point Rot(void) {
    return Point(-y, x);
  }

  Point Rev(void)const  {
    return Point(-x, -y);
  }

  double Len(void) const{
    return sqrt(x * x + y * y);
  }

  double Det(const Point &b)const {
    return x * b.y - y * b.x;
  }

  Point Unit(void)const {
    return Point(x, y) / Len();
  }

};

struct Line{
  Point u, v;

  Line(Point u = Point(0, 0), Point v = Point(0, 0)) : u(u), v(v) {}

  vector<Point> operator & (const Line &b)const {
    if(!fcmp(v.Det(b.v), 0)) return {};
    double c = (b.u - u).Det(b.v.Rev()) / v.Det(b.v.Rev());
    return {u + v * c};
  }

  double Shadow(const Point &b)const {
    double e1 = (b - u).Len(), e2 = v.Len(), e3 = (u + v - b).Len();
    if(!e1) return 0;
    double cosb = (e1 * e1 + e2 * e2 - e3 * e3) / (2 * e1 * e2);
    return cosb;
  }

};



Point po[110], st[110], sm;
double ans[110];
int n, top, mm;
vector<Line> l[110];

bool cmp(Point x, Point y) {
  x = x - sm; y = y - sm;
  if(fcmp(x.Det(y), 0.0) == 0) return x.Len() < y.Len();
  return fcmp(x.Det(y), 0.0) == 1;
}

double Angle(Line a, Line b) {
  double bb = a.Shadow(b.v + b.u);
  // cerr << bb << endl;
  return acos(bb);
}

