    else if(po[i] < sm) sm = po[i], mm = i;
  }
  swap(po[mm], po[1]);
  //cerr << mm << endl;
  sort(po + 2, po + n + 1, cmp);
  //cerr << po[3].x << " " << po[3].y << endl;
  st[++top] = po[1];
  st[++top] = po[2];
  for(int i = 3; i <= n; i++) {
    while(fcmp((po[i] - st[top - 1]).Det(po[i] - st[top]), 0.0) < 1 && top >= 2) top--;
    st[++top] = po[i];
  }
  for(int i = 1; i <= top; i++) {
    int nex = i == top ? 1 : i + 1;
    // cerr << st[i].x << " " << st[i].y << " " << st[i].id << endl;
    l[i].push_back(Line(st[i], st[nex] - st[i]));
    l[nex].push_back(Line(st[nex], st[i] - st[nex]));
  }
  for(int i = 1; i <= top; i++) {
    //cerr << st[i].id << endl;
    ans[st[i].id] = acos(-1) - Angle(l[i][0], l[i][1]);
  }
  for(int i = 1; i <= n; i++)
    printf("%.10lf\n", ans[i] / (2 * acos(-1)));
  return 0;
}

