    bool operator<=(point a){ return cmp(a)<=0; }
};
int ccw(point a, point b, point c){ return cmp((b-a)%(c-a)); }
bool between(point a, point b, point c){ return ccw(a,b,c)==0 && cmp((a-b)*(c-b)) <= 0; }
ld angle(point u, point v){ return atan2(u%v,u*v); }

typedef vector<point> polygon;

point pivot;
bool radialcomp(point p, point q){
	point P = p-pivot, Q = q-pivot;
	ll R = P%Q;
	if(cmp(R)) return R > 0;
	return cmp(P*P,Q*Q) < 0;
}
polygon convex_hull(polygon &T){
	int j=0, n = T.size(); polygon U(n);
	pivot = *min_element(all(T));
	sort(all(T), radialcomp);
	for(int i = 0; i < n; i++){
		while(j > 1 && ccw(U[j-1],U[j-2],T[i]) >= 0) j--;
		U[j++] = T[i];
	}
	U.erase(j+all(U));
	return U;
}

