}

inline Real distance(const Line &l, const Point &p)
{
  return abs(p - projection(l, p));
}

inline Real distance(const Line &l, const Line &m)
{
  return intersect(l, m) ? 0 : distance(l, m.a);
}

inline Real distance(const Segment &s, const Point &p)
{
  Point r = projection(s, p);
  if (intersect(s, r))
    return abs(r - p);
  return min(abs(s.a - p), abs(s.b - p));
}

// http://judge.u-aizu.ac.jp/onlinejudge/description.jsp?id=CGL_2_D
Real distance(const Segment &a, const Segment &b)
{
  if (intersect(a, b))
    return 0;
  return min({distance(a, b.a), distance(a, b.b), distance(b, a.a), distance(b, a.b)});
}

Real distance(const Line &l, const Segment &s)
{
  if (intersect(l, s))
    return 0;
  return min(distance(l, s.a), distance(l, s.b));
}

Point crosspoint(const Line &l, const Line &m)
{
  Real A = cross(l.b - l.a, m.b - m.a);
  Real B = cross(l.b - l.a, l.b - m.a);
  if (eq(abs(A), 0.0) && eq(abs(B), 0.0))
    return m.a;
  return m.a + (m.b - m.a) * B / A;
}

// http://judge.u-aizu.ac.jp/onlinejudge/description.jsp?id=CGL_2_C
Point crosspoint(const Segment &l, const Segment &m)
{
  return crosspoint(Line(l), Line(m));
}

// http://judge.u-aizu.ac.jp/onlinejudge/description.jsp?id=CGL_7_D
pair<Point, Point> crosspoint(const Circle &c, const Line l)
{
  Point pr = projection(l, c.p);
  Point e = (l.b - l.a) / abs(l.b - l.a);
  if (eq(distance(l, c.p), c.r))
    return {pr, pr};
  double base = sqrt(c.r * c.r - norm(pr - c.p));
  return {pr - e * base, pr + e * base};
}

pair<Point, Point> crosspoint(const Circle &c, const Segment &l)
{
  Line aa = Line(l.a, l.b);
  if (intersect(c, l) == 2)
    return crosspoint(c, aa);
  auto ret = crosspoint(c, aa);
  if (dot(l.a - ret.first, l.b - ret.first) < 0)
    ret.second = ret.first;
  else
    ret.first = ret.second;
  return ret;
}

// http://judge.u-aizu.ac.jp/onlinejudge/description.jsp?id=CGL_7_E
pair<Point, Point> crosspoint(const Circle &c1, const Circle &c2)
{
  Real d = abs(c1.p - c2.p);
  Real a = acos((c1.r * c1.r + d * d - c2.r * c2.r) / (2 * c1.r * d));
  Real t = atan2(c2.p.imag() - c1.p.imag(), c2.p.real() - c1.p.real());
  Point p1 = c1.p + Point(cos(t + a) * c1.r, sin(t + a) * c1.r);
  Point p2 = c1.p + Point(cos(t - a) * c1.r, sin(t - a) * c1.r);
  return {p1, p2};
}

// http://judge.u-aizu.ac.jp/onlinejudge/description.jsp?id=CGL_7_F
// 点 p を通る円 c の接線
pair<Point, Point> tangent(const Circle &c1, const Point &p2)
{
  return crosspoint(c1, Circle(p2, sqrt(norm(c1.p - p2) - c1.r * c1.r)));
}

// http://judge.u-aizu.ac.jp/onlinejudge/description.jsp?id=CGL_7_G
// 円 c1, c2 の共通接線
Lines tangent(Circle c1, Circle c2)
{
  Lines ret;
  if (c1.r < c2.r)
    swap(c1, c2);
  Real g = norm(c1.p - c2.p);
  if (eq(g, 0))
    return ret;
  Point u = (c2.p - c1.p) / sqrt(g);
  Point v = rotate(PI * 0.5, u);
  for (int s : {-1, 1})
  {
    Real h = (c1.r + s * c2.r) / sqrt(g);
    if (eq(1 - h * h, 0))
    {
      ret.emplace_back(c1.p + u * c1.r, c1.p + (u + v) * c1.r);
    }
    else if (1 - h * h > 0)
    {
      Point uu = u * h, vv = v * sqrt(1 - h * h);
      ret.emplace_back(c1.p + (uu + vv) * c1.r, c2.p - (uu + vv) * c2.r * s);
      ret.emplace_back(c1.p + (uu - vv) * c1.r, c2.p - (uu - vv) * c2.r * s);
    }
  }
  return ret;
}

// http://judge.u-aizu.ac.jp/onlinejudge/description.jsp?id=CGL_3_B
// 凸性判定
bool is_convex(const Polygon &p)
{
  int n = (int)p.size();
  for (int i = 0; i < n; i++)
  {
    if (ccw(p[(i + n - 1) % n], p[i], p[(i + 1) % n]) == -1)
      return false;
  }
  return true;
}

// http://judge.u-aizu.ac.jp/onlinejudge/description.jsp?id=CGL_4_A
// 凸包
Polygon convex_hull(Polygon &p)
{
  int n = (int)p.size(), k = 0;
  if (n <= 2)
    return p;
  sort(p.begin(), p.end());
  vector<Point> ch(2 * n);
  for (int i = 0; i < n; ch[k++] = p[i++])
  {
    while (k >= 2 && cross(ch[k - 1] - ch[k - 2], p[i] - ch[k - 1]) < EPS)
      --k;
  }
  for (int i = n - 2, t = k + 1; i >= 0; ch[k++] = p[i--])
  {
    while (k >= t && cross(ch[k - 1] - ch[k - 2], p[i] - ch[k - 1]) < EPS)
      --k;
  }
  ch.resize(k - 1);
  return ch;
}

using Polyi = vector<pair<Point, int>>;
Polyi convex_hull(Polyi &p)
{
  int n = (int)p.size(), k = 0;
  if (n <= 2)
    return p;
  sort(p.begin(), p.end());
  vector<pair<Point, int>> ch(2 * n);
  for (int i = 0; i < n; ch[k++] = p[i++])
  {
    while (k >= 2 && cross(ch[k - 1].first - ch[k - 2].first, p[i].first - ch[k - 1].first) < EPS)
      --k;
  }
  for (int i = n - 2, t = k + 1; i >= 0; ch[k++] = p[i--])
  {
    while (k >= t && cross(ch[k - 1].first - ch[k - 2].first, p[i].first - ch[k - 1].first) < EPS)
      --k;
  }
  ch.resize(k - 1);
  return ch;
}

void solve()
{
  int n;
  cin >> n;
  Polyi v(n);
  rep(i, n)
  {
    cin >> v[i].first;
    v[i].second = i;
  }
  Polyi ch = convex_hull(v);
  vector<double> ans(n, 0.0);
  int sz = ch.size();
  if (sz == 2)
  {
    ans[ch[0].second] = ans[ch[1].second] = 0.5;
  }
  else
  {
    Real sum = 0;
    rep(i, sz)
    {
      Point p0 = ch[(i - 1 + sz) % sz].first;
      Point p1 = ch[i].first;
      Point p2 = ch[(i + 1) % sz].first;
      int index = ch[i].second;
      Real theta = get_angle(p0, p1, p2);
      ans[index] = theta / (2.0 * PI);
    }
  }
  rep(i, n) cout << ans[i] << "\n";
}

