		return x==b.x and y==b.y;
	}
	Point operator-(const Point b) {
		ll x0 = x-b.x, y0 = y-b.y;
		Point p; p.x = x0, p.y = y0;
		return p;
	}
};

bool cw(Point a, Point b, Point c) {
	return a.x*(b.y-c.y)+b.x*(c.y-a.y)+c.x*(a.y-b.y)>0;
}

ld length(Point a, Point b) {
	return sqrt((b.x-a.x)*(b.x-a.x)+(b.y-a.y)*(b.y-a.y));
}

ld dot(Point a, Point b) {
	return a.x*b.x+a.y*b.y;
}

ld cosin(Point a, Point b, Point c) {
	ld ret = dot(a-b, c-b);
	ret = ret/(length(a, b)*length(c, b));
	return ret;
}

vector<Point> convex(vector<Point> &v) {
	vector<Point> ret;
	if(2>=(ll) v.size()) return ret;
	sort(v.begin(), v.end());
	vector<Point> up, down;
	up.emplace_back(v[0]); down.emplace_back(v[0]);
	Point A = v[0], B = v.back();
	for(ll i=1; i<(ll) v.size()-1; i++) {
		if(cw(A, v[i], B)) {
			while(up.size()>=2 and !cw(up[up.size()-2], up[up.size()-1], v[i]))
				up.pop_back();
			up.emplace_back(v[i]);
		}
		else {
			while(down.size()>=2 and cw(down[down.size()-2], down[down.size()-1], v[i]))
				down.pop_back();
			down.emplace_back(v[i]);
		}
	}
	up.emplace_back(B), down.emplace_back(B);
	reverse(down.begin(), down.end());
	ret = up;
	for(ll i=1; i<(ll)down.size()-1; i++) ret.emplace_back(down[i]);
	assert(ret.front()==A);
	return ret;
}

