template<typename T>
class P2 {
public:
	T x, y;
	P2(T x = 0, T y = 0) : x(x), y(y){}
	bool operator < (const P2<T>& p) const { return make_pair(x, y) < make_pair(p.x, p.y); }
	T length() const { return sqrt(x*x+y*y); }
	void sub(const P2<T>& p){ x -= p.x; y -= p.y; }
	void scale(T s){ x *= s; y *= s; }
};

template<typename T>
auto dot(const P2<T>& a, const P2<T>& b, const P2<T>& c){
	auto dx1 = b.x - a.x;
	auto dy1 = b.x - a.x;
	auto dx2 = c.x - b.x;
	auto dy2 = c.y - b.y;
	return dx1*dx2 + dy1*dy2;
}

template<typename T>
auto cross(const P2<T>& a, const P2<T>& b, const P2<T>& c){
	auto dx1 = b.x - a.x;
	auto dy1 = b.y - a.y;
	auto dx2 = c.x - b.x;
	auto dy2 = c.y - b.y;
	return dx1*dy2 - dy1*dx2;
}

template<typename T>
vector<P2<T>> convexHull(const vector<P2<T>>& ps){
	if(ps.size() <= 2) return ps;
	vector<P2<T>> pt = ps;
	sort(pt.begin(), pt.end());
	vector<P2<T>> res;
	for(int i=0;i<pt.size();i++){
		while(res.size() >= 2){
			int k = res.size();
			long long cr = cross(res[k-2], res[k-1], pt[i]);
			long long dt = dot(res[k-2], res[k-1], pt[i]);
			if(cr < 0 || (cr == 0 && dt >= 0)){
				res.pop_back();
			} else {
				break;
			}
		}
		res.push_back(pt[i]);
	}
	for(int i=pt.size()-2, t=res.size()+1;i>=0;i--){
		while(res.size() >= t){
			int k = res.size();
			long long cr = cross(res[k-2], res[k-1], pt[i]);
			long long dt = dot(res[k-2], res[k-1], pt[i]);
			if(cr < 0 || (cr == 0 && dt >= 0)){
				res.pop_back();
			} else {
				break;
			}
		}
		res.push_back(pt[i]);
	}
	res.pop_back();
	return res;
}

int main(){
	int N;
	while(cin >> N){
		using P2L = P2<long long>;
		vector<P2L> p(N);
		for(auto& t : p) cin >> t.x >> t.y;
		vector<P2L> hull = convexHull(p);
		vector<double> res(N, 0.0);
		int m = hull.size();
		for(int i=0;i<m;i++){
			P2<double> a(hull[i].x - hull[(i+m-1)%m].x, hull[i].y - hull[(i+m-1)%m].y);
			P2<double> b(hull[(i+1)%m].x - hull[i].x, hull[(i+1)%m].y - hull[i].y);
			a.scale(1/a.length());
			b.scale(1/b.length());
			int idx = 0;
			for(int j=0;j<N;j++){
				if(p[j].x == hull[i].x && p[j].y == hull[i].y) idx = j;
