        return 0;
    }
    if(n==1){
        cout<<1.0<<endl;
        return 0;
    }
    vector<P> ch = convex_hull(ps);
    int k = ch.size();
    map<P,double> res;
    for(int i=0;i<k;++i){
        res[ch[i]] = acos(-dot(ch[(i+1)%k]-ch[i],ch[(i-1+k)%k]-ch[i])/sqrt(norm(ch[(i+1)%k]-ch[i])*norm(ch[(i-1+k)%k]-ch[i])))/(2*M_PI);
    }
    for(int i=0;i<n;++i){
        cout<<fixed<<setprecision(20)<<res[ps[i]]<<endl;
    }
    return 0;
}

