class Point {
    public:
    double x;
    double y;

    Point(double x = 0, double y = 0) : x(x), y(y) {}
    bool operator<(const Point& p) const {
        return abs(x - p.x) > eps ? x < p.x : y < p.y;
    }
    bool operator==(const Point& p) const {
        return abs(x - p.x) < eps && abs(y - p.y) < eps;
    }
    Point operator+(const Point& p) const {
        return Point(x + p.x, y + p.y);
    }
    Point operator-(const Point& p) const {
        return Point(x - p.x, y - p.y);
    }
    Point operator*(double r) const {
        return Point(x * r, y * r);
    }
    Point operator/(double r) const {
        return Point(x / r, y / r);
    }
};

inline double angle(const Point& p1, const Point& p2) {
    return (p1.x * p2.x + p1.y * p2.y) / sqrt(p1.x * p1.x + p1.y * p1.y) / sqrt(p2.x * p2.x + p2.y * p2.y);
}

enum CCW {
    LEFT = 1,
    RIGHT = -1,
    FRONT = 2,
    BACK = -2,
    ON = 0
};

inline CCW ccw(const Point& p1, const Point& p2, const Point& p3) {
    Point v = p2 - p1;
    Point w = p3 - p1;
    double r = v.x * w.y - v.y * w.x;
    if (r > eps) return LEFT;
    if (r < -eps) return RIGHT;
    double t = (v.x * w.x + v.y * w.y) / (v.x * v.x + v.y * v.y);
    if (t > 1) return FRONT;
    if (t < 0) return BACK;
    return ON;
}

vector <Point> convex_hull(vector <Point>& v) {
    int m = 0, r;
    vector <Point> w(v.size() * 2);
    sort(v.begin(), v.end());
    for (int i = 0; i < v.size(); w[m++] = v[i++]) {
        while (m > 1 && ccw(w[m - 1], w[m - 2], v[i]) <= 0) m--;
    }
    for (int i = v.size() - 2, r = m; i >= 0; w[m++] = v[i--]) {
        while (m > r && ccw(w[m - 1], w[m - 2], v[i]) <= 0) m--;
    }
    w.resize(m - 1);
    return w;
}

