double solve(vector< Data > d){
  sort(d.begin(),d.end());
  int n=d.size();
  double res=0;
  for(int i=0;i<n;i++){
    if(i+1<n && d[i].second >= d[i+1].first ){
      d[i+1].first=min(d[i+1].first,d[i].first);
      d[i+1].second=max(d[i+1].second,d[i].second);
    }else{
