struct Vec {
    double x = 0;
    double y = 0;

    Vec() {}
    Vec(double x, double y) : x(x), y(y) {}
    Vec operator+(const Vec& rhs) const { return {x + rhs.x, y + rhs.y}; }
    Vec operator-(const Vec& rhs) const { return {x - rhs.x, y - rhs.y}; }
    Vec operator-() { return {-x, -y}; }
    double operator*(const Vec& rhs) const { return x * rhs.x + y * rhs.y; }
    double cross(const Vec& rhs) const {
        return x * rhs.y - y * rhs.x;
    }
    Vec operator*(double k) const { return {x * k, y * k}; }
    Vec operator/(double k) const { return {x / k, y / k}; }
    double len_sq() const { return (*this) * (*this); }
    double len() const { return sqrt(len_sq()); }
    void rotate() { swap(x, y); x *= -1; } // ToDo: 追加する
    double angle(const Vec& rhs) {
        double len_prod = len() * rhs.len();
        double c = (*this * rhs) / len_prod;
        double s = (cross(rhs)) / len_prod;
        return atan2(s, c);
    }
    double angle_abs(const Vec& rhs) {
        return abs(angle(rhs));
    }
};

