};

vector<Vec> upper_closure(vector<Vec> pts) {
    sort(pts.begin(), pts.end(), [](const Vec& lhs, const Vec& rhs) {
        return lhs.x < rhs.x || (lhs.x == rhs.x && lhs.y < rhs.y);
    });
    vector<Vec> upper;
    upper.push_back(pts[0]);
    for (ll i = 1; i < pts.size(); i++) {
        while (true) {
            if (upper.size() < 2) {
                break;
            }
            Vec now = pts[i];
            Vec top = upper.back();
            Vec prv = *(upper.end() - 2);
            if (now.x == top.x) {
                if (prv.x == top.x) {
                    break;
                }
            } else {
                if (prv.x == top.x) {
                    break;
                }
                if ((top.y - prv.y) * (now.x - top.x)
                    > (now.y - top.y) * (top.x - prv.x)) {
                    break;
                }
            }
            upper.pop_back();
        }
        upper.push_back(pts[i]);
    }
    return upper;
}

vector<Vec> closure(vector<Vec> pts) {
    if (pts.size() == 1) {
        return pts;
    }
    vector<Vec> upper = upper_closure(pts);
    for (ll i = 0; i < pts.size(); i++) {
        pts[i].x *= -1;
        pts[i].y *= -1;
    }
    vector<Vec> lower = upper_closure(move(pts));
    for (ll i = 0; i < lower.size(); i++) {
        lower[i].x *= -1;
        lower[i].y *= -1;
    }
    upper.pop_back();
    lower.pop_back();
    if (lower.size() > upper.size()) {
        swap(lower, upper);
    }
    copy(lower.begin(), lower.end(), back_inserter(upper));
    return upper;
}

int main() {
    ll N;
    cin >> N;
    vector<Vec> pts(N);
    rep(i,0,N) {
        cin >> pts[i].x >> pts[i].y;
    }
    unordered_map<double, unordered_map<double, double>> ans;
    vector<Vec> hull = closure(pts);
    rep(i,0,hull.size()) {
        Vec now(hull[i].x, hull[i].y);
        ll next_idx = (i+1)%hull.size();
        Vec next(hull[next_idx].x, hull[next_idx].y);
        ll prev_idx = ((i-1)%hull.size() + (ll)hull.size()) % (ll)hull.size();
        Vec prev(hull[prev_idx].x, hull[prev_idx].y);
        Vec v1 = next - now;
        Vec v2 = now - prev;
        ans[now.x][now.y] = v1.angle_abs(v2) / (2.0 * M_PI);
    }
    rep(i,0,N) {
        if (ans[pts[i].x].find(pts[i].y) != ans[pts[i].x].end()) {
            cout << fixed << setprecision(10) << ans[pts[i].x][pts[i].y] << endl;
        } else {
            cout << 0.0 << endl;
        }
    }
}

