        x /= a, y /= a;
        return *this;
    }
    bool operator<(const Point &p) const {
        return x != p.x ? x < p.x : y < p.y;
    }
    bool operator==(const Point &p) const {
        return fabsl(x - p.x) < EPS and fabsl(y - p.y) < EPS;
    }
    Double abs() { return sqrtl(norm()); }
    Double norm() { return x * x + y * y; }
};
using Vector = Point;
