template<class T>
struct Pos2T
{
	Pos2T() {}
	Pos2T(T x, T y)
		: x(x)
		, y(y)
	{}

	bool operator== (const Pos2T &b) const
	{
		return x == b.x && y == b.y;
	}

	bool operator!= (const Pos2T &b) const
	{
		return x != b.x || y != b.y;
	}

	Pos2T operator*(T q) const
	{
		return Pos2T(x*q,y*q);
	}

	Pos2T operator+(const Pos2T &b) const
	{
		return Pos2T(x+b.x,y+b.y);
	}

	Pos2T &operator+=(const Pos2T &b)
	{
		x += b.x;
		y += b.y;
		return *this;
	}

	Pos2T operator-(const Pos2T &b) const
	{
		return Pos2T(x-b.x,y-b.y);
	}

	Pos2T &operator-=(const Pos2T &b)
	{
		x -= b.x;
		y -= b.y;
		return *this;
	}

	Pos2T operator-() const
	{
		return Pos2T(-x,-y);
	}

	Pos2T &operator*=(T q)
	{
		x *= q;
		y *= q;
		return *this;
	}

	T operator*(const Pos2T &b) const
	{
		return x*b.x + y*b.y;
	}

	T operator%(const Pos2T &b) const
	{
		return x*b.y - y*b.x;
	}

	const Pos2T &pos() const
	{
		return *this;
	}

	double len() const 
	{
		return sqrt(x*x+y*y);
	}

	T len2() const 
	{
		return x*x+y*y;
	}

	Pos2T norm() const
	{
		return (*this)*(1.0/len());
	}

	double dist(const Pos2T &p) const
	{
		return sqrt((x-p.x)*(x-p.x) + (y-p.y)*(y-p.y));
	}

	T dist2(const Pos2T &p) const
	{
		return (x-p.x)*(x-p.x) + (y-p.y)*(y-p.y);
	}	

	T x, y;
};

