    line(ld a_, ld b_, ld c_) {
        while(abs(a_-round(a_)) > EPS ||
              abs(b_-round(b_)) > EPS) {
            a_*=10;
            b_*=10;
            c_*=10;
        }
        a=round(a_);
        b=round(b_);
        c=c_;
