// 1：a->b向きでcが左(反時計)、-1：cはが右(時計)、0：一直線上
int pointside(const Point &a, const Point &b, const Point &c) {
    if (cross(b-a, c-a) > EPS) return 1;
    if (cross(b-a, c-a) < -EPS) return -1;
    /*
    if(dot(b-a, c-a) < 0) return 2; // c-a-b
    if(norm(b-a) < norm(c-a)) return -2; // a-b-c else a-c-b
    */
    return 0;
}

// Lineの交点。線分や曲線なら書き換え
vector<Point> crosspoint(const Line &l, const Line &m) {
    vector<Point> res;
    ld d = cross(m[1] - m[0], l[1] - l[0]);
    if (abs(d) < EPS) return vector<Point>();
    res.push_back(l[0] + (l[1] - l[0]) * cross(m[1] - m[0], m[1] - l[0]) / d);
    return res;
}

// 3点から等距離の点  if(pointside(a,b,c)==0) skip;
Point centerpoint(Point a, Point b, Point c) {
    Line ab((a+b)/2, (a+b)/2 + rot90(a-b));
    Line bc((b+c)/2, (b+c)/2 + rot90(b-c));
    return crosspoint(ab, bc)[0];
}

// 凸包
vector<pair<Point, int> > ConvexHull(vector<pair<Point, int>> &ps) {
    int n = ps.size();
    vector<pair<Point, int> > res(2*n);
    SORT(ps);
    int k = 0;
    for (int i = 0; i < n; ++i) { // 下凸包を左下から右に調べる
        if (k >= 2) {
            while (cross(res[k-1].first - res[k-2].first, ps[i].first - res[k-2].first) < EPS) { //中間が上なら中間を取り除く
                --k;
                if (k < 2) break;
            }
        }
        res[k].first = ps[i].first; res[k].second = ps[i].second;
        ++k;
    }
    int t = k+1; // 下凸包は決定、次の1個は入れる
    for (int i = n-2; i >= 0; --i) { // 上凸包を右上から左に調べる
        if (k >= t) {
            while (cross(res[k-1].first - res[k-2].first, ps[i].first - res[k-2].first) < EPS) {
                --k;
                if (k < t) break;
            }
        }
        res[k].first = ps[i].first; res[k].second = ps[i].second;
        ++k;
    }
    res.resize(k-1); //最後は最初と同じなので除く
    return res;
}

