      ll x1,x2,y1,y2;
      if(i==0){
        x1=ch[Size(ch)-1].real();
        y1=ch[Size(ch)-1].imag();
      }
      else{
        x1=ch[i-1].real();
        y1=ch[i-1].imag();
      }
      if(i==Size(ch)-1){
        x2=ch[0].real();
        y2=ch[0].imag();
      }
      else{
        x2=ch[i+1].real();
        y2=ch[i+1].imag();
      }

      ///////////////2つのベクトルがなす角
      vec1x=ch[i].real()-x1;
      vec1y=ch[i].imag()-y1;
      vec2x=x2-ch[i].real();
      vec2y=y2-ch[i].imag();

      double length_A=sqrt((vec1x*vec1x)+(vec1y*vec1y));
      double length_B=sqrt((vec2x*vec2x)+(vec2y*vec2y));

      double cos_sita=(vec1x*vec2x+vec1y*vec2y)/(length_A*length_B);

      double sita=acos(cos_sita);

      //////////////////

      ans[{ch[i].real(),ch[i].imag()}]=sita/(2.0*pi);
    }
    rep(i,n){
      if(ans[{x[i],y[i]}]==0.0)printf("0\n");
      else printf("%.20f\n",ans[{x[i],y[i]}]);
    }
    return 0;
}

