		for (size_t i = n - 1, t = k + 1; i > 0; --i) {
			while (k >= t && cross(H[k - 2], H[k - 1], P[i - 1]) <= 0) k--;
			H[k++] = P[i - 1];
		}

		H.resize(k - 1);
		return H;
	}
};

struct vector2d {
	double x, y;
	vector2d() :x(0), y(0) {}
	vector2d(double x, double y) : x(x), y(y) {}

	static double distanceSquare(const vector2d& v1, const vector2d& v2) {
		double dx = v1.x - v2.x;
		double dy = v1.y - v2.y;
		return dx * dx + dy * dy;
	}

	static double distance(const vector2d& v1, const vector2d& v2) {
		return sqrt(distanceSquare(v1, v2));
	}

	vector2d sub(vector2d p2) const {
		return vector2d(x - p2.x, y - p2.y);
	}

	vector2d add(vector2d p2) const {
		return vector2d(x + p2.x, y + p2.y);
	}

	double distance(vector2d p2) const {
		return sqrt((x - p2.x) * (x - p2.x) + (y - p2.y) * (y - p2.y));
	}

	vector2d normal() const {
		double length = norm();
		return vector2d(x / length, y / length);
	}

	vector2d scale(float s) const {
		return vector2d(x * s, y * s);
	}
	double norm() const {
		return sqrt(x * x + y * y);
	}

	vector2d operator+(const vector2d& p) const { return vector2d(x + p.x, y + p.y); }
	vector2d operator-(const vector2d& p) const { return vector2d(x - p.x, y - p.y); }
	vector2d operator*(double a) const { return vector2d(x * a, y * a); }
	vector2d Rot90() const { return { -y, x }; }
};

