	ll n;
	cin >> n;
	vector<Point> ps(n);
	rep(i, n) {
		cin >> ps[i].x >> ps[i].y;
		ps[i].id = i;
	}
	if (n == 2) {
		cout << 0.5 << endl;
		cout << 0.5 << endl;
		return 0;
	}

	ConvexHullRunner r;
	auto h = r.convex_hull(ps);
	auto hullSize = h.size();
	h.insert(h.end(), h.begin(), h.end());
	int start = 1;
	int end = hullSize;
	vector<double> as(n, 0);
	for (int i = start; i <= end; i++) {
		int prev = i - 1;
		int next = i + 1;
		auto v1 = vector2d(h[prev].x, h[prev].y);
		auto v2 = vector2d(h[i].x, h[i].y);
		auto v3 = vector2d(h[next].x, h[next].y);
		auto d1 = (v2 - v1).normal().Rot90();
		auto d2 = (v3 - v2).normal().Rot90();
		auto r1 = atan2(d1.y, d1.x);
		auto r2 = atan2(d2.y, d2.x);
		auto ans = (r2 - r1) + 2 * M_PI;
		while (ans > 2 * M_PI) {
			ans -= 2 * M_PI;
		}
		if (ans > M_PI) {
			ans = 2 * M_PI - ans;
		}
		as[h[i].id] = ans/(2*M_PI);
	}
	cout << fixed << setprecision(10);
	for (auto p : as) {
		cout << p << endl;
	}
	return 0;
}

