double dist (const Point &a, const Point &b)
{
    return sqrt((a.x - b.x) * (a.x - b.x) + (a.y - b.y) * (a.y - b.y));
}

ll area (const Point &a, const Point &b, const Point &c)
{
    return a.x * (b.y - c.y) + b.x * (c.y - a.y) + c.x * (a.y - b.y);
}

double ang (const Point &a, const Point &b, const Point &c)
{
    double ab = dist(a, b);
    double bc = dist(b, c);
    double ac = dist(a, c);
    double angCos = (ab * ab + ac * ac - bc * bc) / (2 * ab * ac);
    double ans = acos(angCos);
    if(area(b, a, c) > 0)
        ans = 2 * PI - ans;
    ans -= PI;
    ans /= 2 * PI;
    return ans;
}

int f (const Point &a)
{
    if(a.x > 0 && a.y >= 0)
        return 1;
    if(a.x <= 0 && a.y > 0)
        return 2;
    if(a.x < 0 && a.y <= 0)
        return 3;
    if(a.x >= 0 && a.y < 0)
        return 4;
}

Point O = {0, 0};

bool operator < (const Point &a, const Point &b)
{
    int fa = f(a), fb = f(b);
    if(fa != fb)
        return fa < fb;
    if(fa == 1 || fa == 3)
        return abs(a.y) * abs(b.x) < abs(b.y) * abs(a.x);
    return abs(a.y) * abs(b.x) > abs(b.y) * abs(a.x);
}

