vect operator-(point p, point q){
	return vect(p.first - q.first, p.second - q.second);
}

vect operator-(indexed_point p, indexed_point q){
	return vect(p.first.first - q.first.first, p.first.second - q.first.second);
}

Int cross(vect v, vect w){
	return v.first * w.second - v.second * w.first;
}

Int dot(vect v, vect w){
	return v.first * w.first + v.second * w.second;
}

double norm(vect v){
	return sqrt(v.first * v.first + v.second * v.second);
}

double deg(vect v, vect w){
	return acos(dot(v, w) / norm(v) / norm(w));
}

polygon convex_hull(vector<indexed_point> v, int n){
	sort(v.begin(), v.end());
	polygon res;
	for(int i=0; i<n; ++i){
		while(res.size() >= 2 && cross(res.back() - res[res.size()-2], v[i] - res[res.size()-2]) < 0) res.pop_back();
		res.push_back(v[i]);
	}
	for(int i=n-2; i>=0; --i){
		while(res.size() >= 2 && cross(res.back() - res[res.size()-2], v[i] - res[res.size()-2]) < 0) res.pop_back();
		res.push_back(v[i]);
	}
	return res;
}

