		return PI / 2 + atan(-dx / dy);
	}else if(dx < 0 && dy <= 0){
		return PI + atan(dy / dx);
	}else{
		return 3 * PI / 2 + atan(-dx / dy);
	}
}

int main(){
	scanf("%d", &n);
	for(int i = 1; i <= n; i++){
		scanf("%d %d", &x[i], &y[i]);
	}
	for(int i = 1; i <= n; i++){
		p = 0;
		for(int j = 1; j <= n; j++){
			if(i != j){
				angs[++p] = find_angle(x[j] - x[i], y[j] - y[i]);
			}
		}
		sort(angs + 1, angs + p + 1);
		double gap = 0;
		if(angs[p] - angs[1] < PI){
			gap = PI - (angs[p] - angs[1]);
		}else{
			for(int i = 2; i <= p; i++){
				if(angs[i] - angs[i - 1] > PI){
					gap = angs[i] - angs[i - 1] - PI;
					break;
				}
			}
		}
		printf("%.10lf\n", gap / (2 * PI));
	}
	return 0;
}

