double GetLen(double x, double y) {
    return sqrt(x*x+y*y);
}

int main() {
    int N;
    cin>>N;
    for(int i=1;i<=N;i++) {
        cin>>X[i]>>Y[i];
    }

    double Pi = 3.1415926535897932384626433832795028842;

    for(int i=1;i<=N;i++) {


        vector<std::tuple<ll,ll,ll>> ABC;

        for(int j=1;j<=N;j++) {
            if (i == j)
                continue;

            ll x1 = X[i];
            ll y1 = Y[i];


            ll x2 = X[j];
            ll y2 = Y[j];


            ll A = 2*(x2-x1);
            ll B = 2*(y2-y1);

            ll C = y1*y1-y2*y2+x1*x1-x2*x2;


            if (A*x1+B*y1+C > 0) {
                A=-A;
                B=-B;
                C=-C;
            }

            ABC.push_back(std::make_tuple(A,B,C));
        }

        double Inf = 1e8;



        vector<pair<double,double>> pts;
        for(int j=0;j<ABC.size();j++) {

            double A = std::get<0>(ABC[j]);
            double B = std::get<1>(ABC[j]);
            double C = std::get<2>(ABC[j]);


            double x1,y1;
            double x2,y2;
            if (A == 0) {
                x1 = Inf;
                y1 = -C/B;

                x2 = -Inf;
                y2 = -C/B;

            } else if (B == 0) {
                y1 = Inf;
                x1 = -C/A;

                y2=-Inf;
                x2=-C/A;

            } else {
                x1 = Inf;
                y1 = -(A*x1+C)/B;

                x2 = -Inf;
                y2 = -(A*x2+C)/B;
            }



            bool ok1 = true;
            bool ok2 = true;
            for(int k=0;k<ABC.size();k++) {
                if (j == k)
                    continue;
                double Ao = std::get<0>(ABC[k]);
                double Bo = std::get<1>(ABC[k]);
                double Co = std::get<2>(ABC[k]);

                if (Ao*x1+Bo*y1+C > 0)
                    ok1=false;
                if (Ao*x2+Bo*y2+C > 0)
                    ok2=false;

            }



            if (ok1) {
                pts.push_back({x1,y1});
            } else if (ok2) {
                pts.push_back({x2,y2});
            }

        }




        if (pts.empty()) {
            printf("%1.12f\n",0.0);
        } else if (pts.size() == 1) {
            printf("%1.12f\n",0.5);
        } else {
            if (pts.size() != 2)
                exit(-1);


            double A1 = pts[0].first;
            double B1 = pts[0].second;

            double A2 = pts[1].first;
            double B2 = pts[1].second;


            double theta = acos((A1*A2+B1*B2)/(GetLen(A1,B1)*GetLen(A2,B2)));

            printf("%1.12f\n",theta/(2*Pi));

        }







    }

}

#include<bits/stdc++.h>
using namespace std;
const double eps=1e-12;
const double INF=1e100;
const int MAX=1e2+3;
double x[MAX];
double y[MAX];
double ans[MAX];
const double PI=3.1415926535897932;

struct PT
{
	double x,y;
	PT()	{}
	PT(double x, double y) : x(x), y(y){}
	PT(const PT &p) : x(p.x), y(p.y) {}
	PT operator + (const PT &p)	const { return PT(x+p.x, y+p.y); }
	PT operator - (const PT &p)	const { return PT(x-p.x, y-p.y); }
	PT operator * (double c)	const { return PT(x*c, y*c); }
	PT operator / (double c)	const { return PT(x/c, y/c); }
};
double dot(PT p, PT q)		{ return p.x*q.x + p.y*q.y; }
double dist2(PT p, PT q)	{ return dot(p-q, p-q); }
double cross(PT p, PT q)	{ return p.x*q.y - p.y*q.x; }

typedef long long LL; 
typedef long double LD;
int n;

vector<PT> A,hull;
PT lower_left;

bool sorter(const PT &p, const PT &q)
{
	double cpq = cross(p-lower_left, q-lower_left);
	if(abs(cpq) < eps)
		return dist2(p, lower_left) < dist2(q, lower_left);
	return (cpq > 0);
}


void convex_hull(vector<PT>& A,vector<PT> & hull)
{
	for(int i=1;i<n;i++)
	{
		if(A[i].y<A[0].y||(A[i].y==A[0].y&&A[i].x<A[0].x))
		{
			swap(A[i],A[0]);
		}
	}//bottom-most point and among those points the one which is leftest
	lower_left=A[0];
	sort(A.begin(),A.end(),sorter);//arranged in clockwise order

	hull.push_back(A[0]);
	hull.push_back(A[1]);

	int hull_sz=2;

	for(int i=2;i<A.size();i++)
	{
		while(hull_sz>1&&cross(hull[hull_sz-1]-hull[hull_sz-2],A[i]-hull[hull_sz-1])<=0)
		{
			hull.pop_back();
			hull_sz--;
		}
		hull.push_back(A[i]);
		hull_sz++;
	}
}

int main()
{
	int n;
	scanf("%d",&n);

	for(int i=1;i<=n;i++)
	{
		scanf("%lf %lf",&x[i],&y[i]);
		A.push_back(PT(x[i],y[i]));
	}

	convex_hull(A,hull);

	for(int i=0;i<hull.size();i++)
	{
		int pre=(i-1+hull.size())%(hull.size());
		int nxt=(i+1)%((int)hull.size());
		ans[i]=dot(hull[pre]-hull[i],hull[nxt]-hull[i])/sqrt(dist2(hull[i],hull[nxt]));
		ans[i]/=sqrt(dist2(hull[i],hull[pre]));
		ans[i]=(PI-acos(ans[i]))/2;
		ans[i]/=PI;
	}	

	for(int i=1;i<=n;i++)
	{
		int fnd=0;
		for(int j=0;j<hull.size();j++)
		{
			if(fabs(x[i]-hull[j].x)<=eps&&fabs(y[i]-hull[j].y)<=eps)
			{
				printf("%lf\n",ans[j]);
				fnd=1;
				break;
			}
		}
		if(!fnd)
		{
			printf("0.00000\n");
		}
	}

}

