    map<point,int> ma;
    rep(i,n) ma[v[i]] = i;
    auto ch = convex_hull(v);
    int sz = ch.size();
    vd ans(n);
    rep(i,sz) {
        int fw = (i+1)%sz;
        int bw = (i-1+sz)%sz;
        point f = ch[i]-ch[fw],b = ch[bw]-ch[i];
        f = f.rot90();
        b = b.rot90();
        double d = f.arg()-b.arg();
        if(sgn(d) < 0) d += 2*PI;
        if(sgn(d-2*PI) >= 0) d -= 2*PI;
        ans[ma[ch[i]]] = d/(2*PI);
    }
