struct P
{
    double x,y;
    int id;
    P(){}
    P(double x,double y):x(x),y(y){}
    P operator +(P p)
    {
        return P(add(x,p.x),add(y,p.y));
    }
    P operator -(P p)
    {
        return P(add(x,-p.x),add(y,-p.y));
    }
    P operator *(double d)
    {
        return P(x*d,y*d);
    }
    double dot(P p)
    {
        return add(x*p.x,y*p.y);
    }
    double det(P p)
    {
        return add(x*p.y,-y*p.x);
    }
};
bool cmp_x(const P& p,const P& q)
{
    if (p.x!=q.x) return p.x<q.x;
    return p.y<q.y;
}
vector<P> convex_hull(P* ps,int n)
{
    sort(ps,ps+n,cmp_x);
    int k=0;
    vector<P> qs(n*2);
    for(int i=0;i<n;i++)
    {
        while(k>1&&(qs[k-1]-qs[k-2]).det(ps[i]-qs[k-1])<=0) k--;
        qs[k++]=ps[i];
    }
    for(int i=n-2,t=k;i>=0;i--)
    {
        while(k>t&&(qs[k-1]-qs[k-2]).det(ps[i]-qs[k-1])<=0) k--;
        qs[k++]=ps[i];
    }
    qs.resize(k-1);
    return qs;
}
double dist(P p,P q)
{
    return sqrt((p-q).dot(p-q));
}
int N;
P ps[MAXN];
double ans[MAXN];
int main()
{
    scanf("%d",&N);
    for(int i=0;i<N;i++)
    {
        scanf("%lf %lf",&ps[i].x,&ps[i].y);
        ps[i].id=i;
    }
    vector<P> qs=convex_hull(ps,N);
    for(int i=0;i<(int)qs.size();i++)
    {
        int last=i-1;if(last<0) last+=(int)qs.size();
        int nxt=i+1;if(nxt>=(int)qs.size()) nxt-=(int)qs.size();
        double res=(qs[i]-qs[last]).dot(qs[i]-qs[nxt]);
        double norm=dist(qs[i],qs[last])*dist(qs[i],qs[nxt]);
        double ang=acos(res/norm);
        ans[qs[i].id]=(PI-ang)/(2*PI);
    }
    for(int i=0;i<N;i++) printf("%.10f\n",ans[i]);
    return 0;
}

