class Point{
    public:
    double x, y;
    Point(double _x = 0, double _y = 0){
        x = _x;
        y = _y;
    }
    Point operator + (const Point p){
        return Point(add(x, p.x), add(y, p.y));
    }
    void operator += (const Point p){
        x = add(x, p.x);
        y = add(y, p.y);
    }
    Point operator - (const Point p){
        return Point(add(x, -p.x), add(y, -p.y));
    }
    void operator -= (const Point p){
        x = add(x, -p.x);
        y = add(y, -p.y);
    }
    Point operator * (const double d){
        return Point(x * d, y * d);
    }
    void operator *= (const double d){
        x *= d;
        y *= d;
    }
    Point operator / (const double d){
        return Point(x / d, y / d);
    }
    void operator /= (const double d){
        x /= d;
        y /= d;
    }
    // naiseki
    double dot(const Point p){
        return add(x * p.x, y * p.y);
    }
    // gaiseki
    double det(const Point p){
        return add(x * p.y, -y * p.x);
    }
    bool operator < (const Point &p)const{
        if(x != p.x)return x < p.x;
        return y < p.y;
    }
    double norm(){
        return hypot(x, y);
    }
    void rot(double rad){
        double X = add(x * cos(rad), -y * sin(rad));
        double Y = add(x * sin(rad), +y * cos(rad));
        x = X;
        y = Y;
    }
    Point roted(double rad){
        return Point(add(x * cos(rad), -y * sin(rad)), add(x * sin(rad), +y * cos(rad)));
    }
    void normalize(){
        double d = norm();
        x /= d;
        y /= d;
    }
    Point normalized(){
        double d = norm();
        return Point(x / d, y / d);
    }
    string str(){
        stringstream ss;
        ss << "(" << x << ", " << y << ")";
        return ss.str();
    }
};

void ConvexHull(const vector<Point>&in, vector<Point>&out){
    vector<Point>ps = in;
    int n = ps.size();
    sort(ps.begin(), ps.end());
    int k = 0;
    out = vector<Point>(n * 2);
    for(int i = 0; i < n; i++){
        while(k > 1 && (out[k-1] - out[k-2]).det(ps[i]-out[k-1]) <= 0)k--;
        out[k++] = ps[i];
    }
    for(int i = n - 2, t = k; i >= 0; i--){
        while(k > t && (out[k-1] - out[k-2]).det(ps[i]-out[k-1]) <= 0)k--;
        out[k++] = ps[i];
    }
    out.resize(k-1);
}

