			q.push(imoscell(angle, isleftreally));
			q.push(imoscell(angle + M_PI, !isleftreally));

			if (!isleftreally) imossum++;
		}

		if (imossum <= 0) {
			anglerange = q.top().first;
		}
		while (!q.empty()) {
			imoscell p = q.top();
			q.pop();

			double nextd = (q.empty() ? M_PI * 2 : q.top().first);

			if (p.second) {
				imossum++;
			} else {
				imossum--;
			}

			if (imossum <= 0) {
				anglerange += (nextd - p.first);
			}
		}

		printf("%.12lf\n", anglerange / (M_PI * 2));
	}

