double calc(int poz) {
    double r = 0;

    double px1 = x[poz - 1], py1 = y[poz - 1],
           px2 = x[poz + 1], py2 = y[poz + 1];

    px1 -= x[poz];
    px2 -= x[poz];
    py1 -= y[poz];
    py2 -= y[poz];


    double angle = atan2(py1, px1) - atan2(py2, px2);
    angle = angle * 360 / (2*pii);
    if (angle < 0){
        angle = angle + 360;
    }

    if(angle > 180)
        angle -= 180;


    angle = 180 - angle;

    return r = angle / 360.0;
}

void sol() {
int i, j, k;

    x[r + 1] = x[1];
    y[r + 1] = y[1];
    x[0] = x[r];
    y[0] = y[r];

    for(i = 1; i <= r; ++i) {
        s[pozz[i]] = calc(i);
    }

    for(i = 1; i <= n; ++i) {
        cout << fixed << setprecision(8) << s[i] << "\n";
    }
}

const int nmax = 1205, f_mare = 1e9;

struct punct {
    double x, y;
    int poz;
} a[nmax], minim;
int stiva[nmax], vf;

double det(punct a, punct b, punct c) {
    return a.x*b.y + b.x*c.y + c.x*a.y -
           c.x*b.y - b.x*a.y - c.y*a.x;
}

bool cmp(const punct &a, const punct &b) {
    return (a.y-minim.y)*(b.x-minim.x) < (b.y-minim.y)*(a.x-minim.x);
}

int main() {
