        cout << "0.5\n0.5\n";
        return 0;

    }
    minim = {f_mare, f_mare};
    for (i = 1; i <= n; i++) {
        cin >> a[i].x >> a[i].y;
        a[i].poz = i;

        if (a[i].x < minim.x || (a[i].x == minim.x && a[i].y < minim.y))
            poz = i, minim = a[i];
    }
    swap(a[1], a[poz]);
    sort(a+2,a+n+1,cmp);
    stiva[1] = 1, stiva[2] = 2;
    vf = 2;
    for (i = 3; i <= n; i++) {
        while (vf > 2 && det(a[stiva[vf-1]], a[stiva[vf]], a[i]) <= 0) vf--;
        stiva[++vf] = i;
    }
    r = vf;
    for (i = 1; i <= vf; i++) {
        x[i] = a[stiva[i]].x; y[i] = a[stiva[i]].y;
        pozz[i] = a[stiva[i]].poz;
        }

        sol();
    return 0;
}

