long double dist(point<long double> A, point<long double> B){
	return sqrt((A.x - B.x) * (A.x - B.x) + (A.y - B.y) * (A.y - B.y));
}

const long double PI = acos(-1);
long double getAngle(point<long double> A, point<long double> B, point<long double> C){
	swap(A,B);
	long double a = dist(B,C);
	long double b = dist(A,C);
	long double c = dist(A,B);
	long double x = (b * b + c * c - a * a) / (2.0 * b * c);
	return acos(x);
}

