double EPS = 1e-10;

// 誤差を考慮した足し算
double add(double a, double b)
{
    if (abs(a + b) < EPS * (abs(a) + abs(b))) return 0;
    return a + b;
}

// 二次元ベクトル構造体
struct P
{
    double x, y;

    P() {}

    P(double x, double y) : x(x), y(y) {}

    P operator + (P p)
    {
        return P(add(x, p.x), add(y, p.y));
    }

    P operator - (P p)
    {
        return P(add(x, -p.x), add(y, -p.y));
    }

    P operator * (double d)
    {
        return P(x * d, y * d);
    }

    // 内積
    double dot(P p)
    {
        return add(x * p.x, y * p.y);
    }

    // 外積
    double det(P p)
    {
        return add(x * p.y, -y * p.x);
    }
};

// 辞書順 比較
bool cmp_x(const P &p, const P &q)
{
    if (p.x != q.x) return p.x < q.x;
    return p.y < q.y;
}

// 凸包
vector<P> convex_hull(P *ps, int n)
{
    sort(ps, ps + n, cmp_x);

    // 凸包 頂点数
    int k = 0;

    // 凸包 構築中
    vector<P> qs(n * 2);

    // 凸包 下側
    for (int i = 0; i < n; i++)
    {
        while (k > 1
            && (qs[k - 1] - ps[k - 2]).det
            (ps[i] - qs[k - 1]) <= 0) k--;

        qs[k++] = ps[i];
    }

    // 凸包 上側
    for (int i = n - 2, t = k; i >= 0; i--)
    {
        while (k > t
            && (qs[k - 1] - qs[k - 2]).det
            (ps[i] - qs[k - 1]) <= 0) k--;

        qs[k++] = ps[i];
    }
    qs.resize(k - 1);
    return qs;
}

// ベクトルの長さを計算する
double get_vector_length(P v) {
    return pow((v.x * v.x) + (v.y * v.y), 0.5);
}

// ２つのベクトルABのなす角度θを求める
double AngleOf2Vector(P A, P B)
{
    // ベクトルAとBの長さを計算する
    double length_A = get_vector_length(A);
    double length_B = get_vector_length(B);

    // 内積とベクトル長さを使ってcosθを求める
    double cos_sita = A.dot(B) / ( length_A * length_B );

    // cosθからθを求める
    double sita = acos( cos_sita );

    // ラジアンでなく0～180の角度
    //sita = sita * 180.0 / PI;

    return sita;
}

