			res = min(res, t[l++]);
		if (!(r & 1))
			res = min(res, t[r--]);
		l >>= 1, r >>= 1;		
	}
	return res;
}

void upd(int v, int val)
{
	v += n - 1;
	t[v] = val;
	while(v != 1)
	{
		v >>= 1;
		t[v] = min(t[v << 1], t[v << 1 | 1]);	
	}
}

