		q[p[i]] = i;
	//~calc_t1_t2
	fill(t + 1, t + (n << 1), n + 1);
	for (int i = n; i >= 1; i--)
	{
		upd(q[i], i);
		t2[q[i]] = get(q[i] + 1, min(n, q[i] + k - 1));
		t1[q[i]] = get(max(1, q[i] - k + 1), q[i] - 1);		
		g[t1[q[i]]].pb({q[i], t2[q[i]]});
		g[t2[q[i]]].pb({q[i], t1[q[i]]});
	}
	//~solve
	set < int > st;
	used[n + 1] = true;
	for (auto it : g[n + 1])
	{
		if (used[it.second])
			st.insert(it.first);
	}
	vector < int > ans;
	while(!st.empty())
	{
		int v = *st.rbegin();
		st.erase(v);
		ans.pb(v);
		used[p[v]] = true;
		for (auto it : g[p[v]])
		{
			if (used[it.second])
			{
				st.insert(it.first);
			}
		}
	}
	reverse(all(ans));
	for (int i = 0; i < (int)ans.size(); i++)
		res[ans[i]] = i + 1;
	forn(i, n)
