        double nrm0 = sqrt(dx0*dx0+dy0*dy0);
        double nrm1 = sqrt(dx1*dx1+dy1*dy1);
        double dot = dx0*dx1+dy0*dy1;
        double tmp = dot / (nrm0*nrm1);

