			for(int k=0;k<n;k++){
				if(i==k || j==k)continue;
				if(ccw(i,j,k)==0){
					flag[k]=true;
				}
			}
		}
	}
	for(int i=0;i<n;i++){
		if(!flag[i]){
			g.push_back(P(x[i],y[i],i));
		}
	}
	Polygon res=andrewScan(g);
	if(res.size()<=2){
		for(int i=0;i<n;i++){
			if(!flag[i]){
				printf("%.10f\n",0.5);
			}else{
				printf("%.0f\n",0.0);
			}
		}
	}else{
		double sum=0.0;
		int m=res.size();
		for(int i=0;i<res.size();i++){
			P p1=getCP(res[(i+1)%m],res[i]);
			P p2=getCP(res[i],res[(i+m-1)%m]);
			double co=dot(p1,p2)/(abs(p1)*abs(p2));
			ans[res[i].id]=acos(co)/(M_PI*2.0);
		}
		for(int i=0;i<n;i++){
			printf("%.10f\n",ans[i]);
		}
	}
	return 0;
}

