const double EPS = 1e-6, PI = acos(-1.0);

inline bool eq(double a, double b) { return fabs(b - a) < EPS; }

struct Point
{
  double x, y;

  Point() {}

  Point(double x, double y) : x(x), y(y) {}

  Point operator+(const Point &b) const { return Point(x + b.x, y + b.y); }

  Point operator-(const Point &b) const { return Point(x - b.x, y - b.y); }

  Point operator*(const double b) const { return Point(x * b, y * b); }

  Point operator*(const Point &b) const { return Point(x * b.x - y * b.y, x * b.y + y * b.x); }

  Point operator/(const double b) const { return Point(x / b, y / b); }

  bool operator<(const Point &b) const { return x != b.x ? x < b.x : y < b.y; }

  bool operator==(const Point &b) const { return eq(x, b.x) && eq(y, b.y); }

  double norm() { return x * x + y * y; }

  double arg() { return atan2(x, y); }

  double abs() { return sqrt(norm()); }

  Point rotate(double theta) { return Point(cos(theta) * x - sin(theta) * y, sin(theta) * x + cos(theta) * y); }

  Point rotate90() { return Point(-y, x); }

  friend ostream &operator<<(ostream &os, Point &p) { return os << "(" << p.x << "," << p.y << ")"; }

  friend istream &operator>>(istream &is, Point &a) { return is >> a.x >> a.y; }
};

double cross(const Point &a, const Point &b)
{
  return a.x * b.y - a.y * b.x;
}


typedef vector< Point > Polygon;

Polygon Convex_Hull(Polygon& p){
    int n = p.size(), k = 0;
    if(n >= 3){
      sort(p.begin(), p.end());
      vector< Point > ch(2 * n);
      for(int i = 0; i < n; ch[k++] = p[i++]){
        while(k >= 2 && cross(ch[k - 1] - ch[k - 2], p[i] - ch[k - 1]) < 0) --k;
      }
      for(int i = n - 2, t = k + 1; i >= 0; ch[k++] = p[i--]){
        while(k >= t && cross(ch[k - 1] - ch[k - 2], p[i] - ch[k - 1]) < 0) --k;
      }
      ch.resize(k - 1);
      return ch;
    } else {
      return p;
    }
}

signed main(){
    int n;
    cin >> n;
    vector<int> x(n), y(n);
    Polygon po;
    map<P, int> mp;
    rep(i, 0, n){
        cin >> x[i] >> y[i];
        mp[P(x[i], y[i])] = i;
        po.push_back(Point(x[i], y[i]));
    }
    if(n == 2){
        cout << 0.5 << endl << 0.5 << endl;
        return 0;
    }
    Polygon ch = Convex_Hull(po);
    vector<double> ans(n, 0.0);
    int sz = ch.size();
    rep(i, 0, ch.size()){
        Point now = ch[i];
        Point pre = ch[(i - 1 + sz) % sz];
        Point next = ch[(i + 1) % sz];
        int id = mp[P((int)now.x, (int)now.y)];
        double m1 = atan2(-(now.x - pre.x), (now.y - pre.y));
        double m2 = atan2(-(next.x - now.x),  (next.y - now.y));
        double tn = m2 - m1;
        double tmp;
        while(tn < EPS) tn += PI;
        tmp = tn / (2.0 * PI);
        ans[id] = tmp;
    }
    rep(i, 0, n){
        printf("%.15f\n", ans[i]);
    }
}

