        point[i].real(x);
        point[i].imag(y);
        m[point[i]]=i;
    }
    auto convex=convex_hull(point);
    ll c=convex.size();
    rep(c){
        ans[m[convex[i]]]=1-abs(PI-arg((convex[(i+1)%c]-convex[i])/(convex[(i+c-1)%c]-convex[i])))/2/PI;
    }
    each(i,ans)out(i);
}

