// [-pi, pi] -> [-p/2, pi/2]
double standardize(double arg){
	if(arg > PI / 2) return arg - PI;
	if(arg < -PI / 2) return arg + PI;
	return arg;
}

int main(){
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	int n;
	cin >> n;
	vector<pvi> p(n);
	REP(i, n){
		cin >> p[i].first.x >> p[i].first.y;
		p[i].second = i;
	}
	if(n == 2){
		cout << "0.5\n0.5\n";
		return 0;
	}
	sort(ALL(p));
	vector<vec2D<int>> qs(n * 2);
	int k = 0;
	REP(i, n){
		while(k > 1 && (qs[k - 1] - qs[k - 2]).outer(p[i].X - qs[k - 1]) <= 0) k--;
		qs[k++] = p[i].X;
	}
	for(int i = n - 2, t = k; i >= 0; --i){
		while(k > t && (qs[k - 1] - qs[k - 2]).outer(p[i].X - qs[k - 1]) <= 0) k--;
		qs[k++] = p[i].X;
	}
	qs.resize(k - 1);

	vector<double> pr(n);
	REP(i, n){
		int index = find(ALL(qs), p[i].first) - qs.begin();
		if(index == qs.size()){
			pr[p[i].second] = 0.0;
			continue;
		}
		auto &me = qs[index];
		auto &v1 = qs[(index == 0 ? qs.size() - 1 : index - 1)];
		auto &v2 = qs[(index == qs.size() - 1 ? 0 : index + 1)];
		double arg1 = atan2(double(v1.y - me.y), double(v1.x - me.x));
		double arg2 = atan2(double(v2.y - me.y), double(v2.x - me.x));
		double arg = min(abs(arg1 - arg2), PI * 2 - abs(arg1 - arg2));
		pr[p[i].second] = abs(PI - abs(arg)) / PI / 2;
	}
	REP(i, n) cout << setprecision(10) << pr[i] << "\n";
	//cout << accumulate(ALL(pr), 0.0) << "\n";
	return 0;
}

