	hull.push_back(mn);
	for (int i = 0; i < seq.size(); i++) {
		int ind = seq[i];
		while (hull.size() >= 2 && !Ok(hull[int(hull.size()) - 2], hull.back(), ind)) hull.pop_back();
		hull.push_back(ind);
	}
	while (hull.size() >= 3 && !Ok(hull[int(hull.size()) - 2], hull.back(), mn)) hull.pop_back();
	if (hull.size() == 2) {
		for (int i = 0; i < hull.size(); i++)
			my[hull[i]] = 0.5;
		sum = 1;
	} else 
		for (int i = 0; i < hull.size(); i++) {
			int pi = (i - 1 + hull.size()) % hull.size();
			int ni = (i + 1) % hull.size();
			my[hull[i]] = PI - Angle(hull[i], hull[pi], hull[ni]);
			sum += my[hull[i]];
		}
	for (int i = 0; i < n; i++)
		cout << fixed << setprecision(15) << my[i] / sum << endl;
	return 0;
}

