    vector<P> qs = convex_hull(ps, N);
    qs.push_back(qs[0]);
    qs.push_back(qs[1]);
    vector<double> ans(N, 0.0);
    for (int i = 0; i < qs.size() - 2; i++) {
        P pr = qs[i] - qs[i + 1], pq = qs[i + 2] - qs[i + 1];  // i+1番目の座標を基準とした座標を作成
        double len_pr = pr.x * pr.x + pr.y * pr.y, len_pq = pq.x * pq.x + pq.y * pq.y;
        ans[qs[i + 1].idx] = (PI - acos(pr.dot(pq) / sqrt(len_pr * len_pq))) / (2 * PI);
    }
    cout << fixed << setprecision(7);
    for (int i = 0; i < N; i++) {
        cout << ans[i] << endl;
    }
    return 0;
}

