bool isOn(Point s, Point e, Point p) {
	if (cross(e - s, p - s) != 0) return false;
	return dot(p - s, p - e) <= 0;
}

int n;
Point p[100];

bool isInTriangle(int id) {
	int i, j, k;
	for (i = 0; i < n; i++) {
		if (i == id) continue;
		for (j = i + 1; j < n; j++) {
			if (j == id) continue;
			for (k = j + 1; k < n; k++) {
				if (k == id) continue;
				if (cross(p[j] - p[i], p[k] - p[i]) == 0) continue;
				if (isOn(p[i], p[j], p[id])) { return true; }
				if (isOn(p[j], p[k], p[id])) { return true; }
				if (isOn(p[k], p[i], p[id])) { return true; }
				double a = cross(p[j] - p[i], p[id] - p[i]);
				double b = cross(p[k] - p[j], p[id] - p[j]);
				double c = cross(p[i] - p[k], p[id] - p[k]);
				if (a < 0 && b < 0 && c < 0) { return true; }
				if (a > 0 && b > 0 && c > 0) { return true; }
			}
		}
	}
	return false;
}

