struct xy {
    int x,y,id;
};
xy operator-(xy a, xy b) {
    return {a.x-b.x, a.y-b.y, -1};
}
struct cmpX {bool operator()(xy a, xy b) const {
    return mt(a.x,a.y) < mt(b.x,b.y);}};
double dot(xy a, xy b) {return a.x*b.x + a.y*b.y;} // scalar product
double cross(xy a, xy b) {return a.x*b.y - a.y*b.x;} // vector product
xy read(int i) {int a,b; cin>>a>>b; return {a,b,i};}
double orient(xy a, xy b, xy c) {return cross(b-a,c-a);}
// Remove obsolete hull vertices and add p
void up(V<xy> &st, xy p) {
    while (S(st) >= 2 && orient(st.end()[-2], st.back(), p) <= 0)
        st.pop_back();
    st.pb(p);
}
V<xy> convexHull(V<xy> ps) {
    sort(ALL(ps), cmpX()); // by x then y, see 3.2
    V<xy> lo, hi; // lower and upper hulls
    F(i,S(ps)) up(lo, ps[i]);
    D(i,S(ps)) up(hi, ps[i]);
    lo.pop_back(); hi.pop_back();
    for (xy a : hi) lo.pb(a);
    return lo;
}

