int main()
{
	cout << fixed << setprecision(8);
	int N;
	cin >> N;
	vector<point> ps;
	vector<pair<int, int>> pps;
	for (int i = 0; i < N; i++) {
		int x, y;
		cin >> x >> y;
		ps.emplace_back(x, y);
		pps.emplace_back(x, y);
	}
	auto pol = convex_hull(ps);
	if ((int)pol.size() <= 2) {
		set<int> xs, ys;
		for (int i = 0; i < N; i++) {
			xs.insert(pps[i].first);
			ys.insert(pps[i].second);
		}
		map<pair<int, int>, ld> res;
		if (xs.size() == 1) {
			sort(ps.begin(), ps.end(), [](const point& l, const point& r) {
				return imag(l) < imag(r);
			});
		}
		else {
			sort(ps.begin(), ps.end(), [](const point& l, const point& r) {
				return real(l) < real(r);
			});
		}
		res[make_pair((int)(round(real(ps.front()))), (int)(round(imag(ps.front()))))] = 0.5;
		res[make_pair((int)(round(real(ps.back()))), (int)(round(imag(ps.back()))))] = 0.5;
		for (int i = 0; i < N; i++) {
			cout << res[pps[i]] << endl;
		}
		return 0;
	}
	int n = pol.size();
	map<pair<int, int>, ld> res;
	for (int i = 0; i < n; i++) {
		point a = pol[(i + n - 1) % n] - pol[i], b = pol[(i + 1) % n] - pol[i];
		ld ac = dot(a, b) / abs(a) / abs(b);
		res[make_pair((int)(round(real(pol[i]))), (int)(round(imag(pol[i]))))] = (pi - acosl(ac)) / (pi * 2.0);
	}
	for (int i = 0; i < N; i++) {
		cout << ((ld)res[pps[i]]) << endl;
	}
	return 0;
}

