vector<long> x;
vector<long> y;
int s = 0;

int main() {
    std::ios::sync_with_stdio(false);

    int n;
    cin >> n;
    x.resize(n);
    y.resize(n);
    for (int i = 0; i < n; i++) {
        cin >> x[i] >> y[i];
    }
    for (int i = 0; i < n; i++) {
        if (x[i] < x[s] || x[i] == x[s] && y[i] < y[s]) {
            s = i;
        }
    }
    vector<int> p;
    for (int i = 0; i < n; i++) {
        if (i != s) {
            p.push_back(i);
        }
    }
    std::sort(p.begin(), p.end(), [](const int & a, const int & b) -> bool {
        long vp = (x[a] - x[s]) * (y[b] - y[s]) - (x[b] - x[s]) * (y[a] - y[s]);
        if (vp != 0) return vp > 0;
        long da = (x[a] - x[s]) * (x[a] - x[s]) + (y[a] - y[s]) * (y[a] - y[s]);
        long db = (x[b] - x[s]) * (x[b] - x[s]) + (y[b] - y[s]) * (y[b] - y[s]);
        return da < db;
    });

    vector<int> st;
    st.push_back(s);
    for (int v : p) {
//        cout << x[v] << " " << y[v]<< "\n";
        while (st.size() >= 2) {
            int a = st[st.size() - 1];
            int b = st[st.size() - 2];
            long x1 = x[a] - x[b];
            long y1 = y[a] - y[b];
            long x2 = x[v] - x[a];
            long y2 = y[v] - y[a];
            long vp = x1 * y2 - x2 * y1;
            if (vp <= 0) {
                st.pop_back();
            } else {
                break;
            }
        }
        st.push_back(v);
    }
    vector<double> res(n);
    for (int i = 0; i < st.size(); i++) {
        int a = st[i];
        int v = st[(i + 1) % st.size()];
        int b = st[(i + 2) % st.size()];
        long x1 = x[a] - x[v];
        long y1 = y[a] - y[v];
        long x2 = x[b] - x[v];
        long y2 = y[b] - y[v];
        long vp = x1 * y2 - x2 * y1;
        long sp = x1 * x2 + y1 * y2;
        double an = atan2(vp, sp);
        res[v] = (PI + an) / (2 * PI);
    }
    cout << std::setprecision(20);
    for (int i = 0; i < n; i++) {
        cout << res[i] << "\n";
    }

    return 0;
}

