vector<pair<int,int>> convex_hull(vector<pair<int,int>> P){
    int N=P.size();
    if(N<=1){
        return P;
    }
    vector<pair<int,int>> L,H;
    vector<pair<int,int>> VL,VH;
    sort(P.begin(),P.end());
    for(int i=0;i<N;i++){
        if((P[N-1].first-P[0].first)*(P[i].second-P[0].second)>=(P[N-1].second-P[0].second)*(P[i].first-P[0].first)){
            H.push_back(P[i]);
        }else{
            L.push_back(P[i]);
        }
    }
    int h=H.size();//反時計回り
    int l=L.size();//時計回り
    for(int i=0;i<h;i++){//反時計回り
        if(VH.size()<2){
            VH.push_back(H[i]);
        }else{
            int j=VH.size();
            if((VH[j-1].first-VH[j-2].first)*(H[i].second-VH[j-2].second)<=(VH[j-1].second-VH[j-2].second)*(H[i].first-VH[j-2].first)){
                VH.push_back(H[i]);
            }else{
                while(VH.size()>=2){
                    j=VH.size();
                    if((VH[j-1].first-VH[j-2].first)*(H[i].second-VH[j-2].second)>(VH[j-1].second-VH[j-2].second)*(H[i].first-VH[j-2].first)){
                        VH.pop_back();
                    }else{
                        break;
                    }
                }
                VH.push_back(H[i]);
            }
        }
    }

    for(int i=0;i<l;i++){//時計回り
        if(VL.size()<2){
            VL.push_back(L[i]);
        }else{
            int j=VL.size();
            if((VL[j-1].first-VL[j-2].first)*(L[i].second-VL[j-2].second)>=(VL[j-1].second-VL[j-2].second)*(L[i].first-VL[j-2].first)){
                VL.push_back(L[i]);
            }else{
                while(VL.size()>=2){
                    j=VL.size();
                    if((VL[j-1].first-VL[j-2].first)*(L[i].second-VL[j-2].second)<(VL[j-1].second-VL[j-2].second)*(L[i].first-VL[j-2].first)){
                        VL.pop_back();
                    }else{
                        break;
                    }
                }
                VL.push_back(L[i]);
            }
        }
    }
    P.clear();
    for(int i=0;i<VH.size();i++){
        P.push_back(VH[(VH.size())-1-i]);
    }
    for(int i=0;i<VL.size();i++){
        P.push_back(VL[i]);
    }
    return P;
}


signed main(void){
    int N;
    vector<pair<int,int>> P;
    map<pair<int,int>,int> M;
    double Ans[114]={};
    int x,y;
