    REP(i,P.size()-1){
        double t=atan2(-(P[i+1].first-P[i].first),(P[i+1].second-P[i].second));
        if(t<0)t+=2*PI;
        Ans[M[P[i]]]+=t-now;
        now=t;
    }
    Ans[M[P[0]]]+=2*PI-now;
    double sum=0;
    REP(i,N){
