//直線の直行平行判定
point orth(point p){
	return point(-p.y,p.x);
}
bool isOrthogonal(Vector a,Vector b){
	return equal(dot(a,b),0.0);
}
bool isOrthogonal(point a1,point a2,point b1,point b2){
	return isOrthogonal(a1-a2,b1-b2);
}
bool isOrthogonal(line l1,line l2){
	return equal(dot(l1.p2-l1.p1,l2.p2-l2.p1),0.0);
}
bool isParallel(Vector a,Vector b){
	return equal(det(a,b),0.0);
}
bool isParallel(point a1,point a2,point b1,point b2){
	return isParallel(a1-a2,b1-b2);
}
bool isParallel(line l1,line l2){
	return equal(det(l1.p2-l1.p1,l2.p2-l2.p1),0.0);
}
//同一直線判定
bool isSame(line l1,line l2){
	return equal(det(l1.p2-l1.p1,l2.p2-l1.p1),0.0);
}
bool isSame(point a1,point a2,point b1,point b2){
	return isSame(line(a1,a2),line(b1,b2));
}
//射影対照わからんわからん
point project(line l,point p){
	Vector base=l.p2-l.p1;
	double r=dot(p-l.p1,base)/norm(base);
	return l.p1+base*r;
}
point reflect(line l,point p){
	return p+(project(l,p)-p)*2.0;
}
double arg(Vector p){
	return atan2(p.y,p.x);
}
Vector polar(double a,double r){
	return point(cos(r)*a,sin(r)*a);
}
