		db a=sqrt((x-x1)*(x-x1)+(y-y1)*(y-y1));
		db b=sqrt((x-x2)*(x-x2)+(y-y2)*(y-y2));
		db c=sqrt((x2-x1)*(x2-x1)+(y2-y1)*(y2-y1));
		db theta=acos((a*a+b*b-c*c)/(2*a*b));
		ans[p[hull[i]].i]=(PI-theta)/(2*PI);
	}
	fup(i,0,n-1,1)printf("%.10f\n",ans[i]);
}

