	}
	if(n == 2){
		cout<<0.5<<'\n';
		cout<<0.5<<'\n';
		exit(0);
	}
	sort(v.begin() + 1, v.end(), [&](Point &a, Point &b){
		return getAngle(a - v[0]) < getAngle(b - v[0]);
	});
	vector<Point> hull;
	for(int i = 0; i < n; i++){
		while(hull.size() >= 2 && cross(hull[hull.size() - 2], hull.back(), v[i]) <= 0){
			hull.pop_back();
		}
		hull.push_back(v[i]);
	}
	vector<ld> ans(n);
	if(hull.size() == 2){
		ans[hull[0].i] = 0.5;
		ans[hull[1].i] = 0.5;
	}else{
		int sz = hull.size();
		for(int i = 0; i < sz; i++){
			ld theta = findAngle(hull[(i + sz - 1)%sz] - hull[i], hull[(i + 1)%sz] - hull[i]);
