template<class T> inline bool chmin(T& a, const T& b) { if (b < a) { a = b; return 1; } return 0; }

struct Point {
	double x, y;
	int id;
	bool operator <(const Point& p) const {
		return x < p.x || (x == p.x && y < p.y);
	}
};

struct ConvexHullRunner {
	typedef double coord_t;
	typedef double coord2_t;

	coord2_t cross(const Point& O, const Point& A, const Point& B)
	{
		return (A.x - O.x) * (B.y - O.y) - (A.y - O.y) * (B.x - O.x);
	}

	vector<Point> convex_hull(vector<Point> P)
	{
		size_t n = P.size(), k = 0;
		if (n <= 3) return P;
		vector<Point> H(2 * n);

		sort(P.begin(), P.end());

		for (size_t i = 0; i < n; ++i) {
			while (k >= 2 && cross(H[k - 2], H[k - 1], P[i]) <= 0) k--;
			H[k++] = P[i];
		}

		for (size_t i = n - 1, t = k + 1; i > 0; --i) {
			while (k >= t && cross(H[k - 2], H[k - 1], P[i - 1]) <= 0) k--;
			H[k++] = P[i - 1];
		}

		H.resize(k - 1);
		return H;
	}
};

int main() {
	ll n;
	cin >> n;
	vector<Point> as(n);
	rep(i, n) {
		cin >> as[i].x >> as[i].y;
		as[i].id = i;
	}
	ConvexHullRunner r;
	auto hull = r.convex_hull(as);
	ll s = hull.size();
	hull.insert(hull.end(), hull.begin(), hull.end());
	vector<double> ans(n, 0);
	for (int i = 1; i < s + 1; i++) {
		auto prev = hull[i - 1];
		auto current = hull[i];
		auto next = hull[i + 1];
		auto dx1 = current.x - prev.x;
		auto dy1 = current.y - prev.y;
		auto dx2 = next.x - current.x;
		auto dy2 = next.y - current.y;
		auto t2 = atan2(dy2, dx2);
		if (t2 < 0) t2 += 2 * M_PI;
		auto t1 = atan2(dy1, dx1);
		if (t1 < 0) t1 += 2 * M_PI;
		auto t = t2 - t1;
		if (t < 0) {
			t += 2 * M_PI;
		}
		while(t > 2 * M_PI) {
			t -= M_PI;
		}
		if (t > M_PI) {
			t = 2 * M_PI - t;
		}
		ans[hull[i].id] = t / (2 * M_PI);
	}
	cout << setprecision(10) << fixed;
	for (auto p : ans) {
		cout << p << endl;
	}
	return 0;
}

