struct pt {
    /// Point structure for Int in C++
    int x, y;

    /// CONSTRUCTORS

    pt() : x(0), y(0) {}
    pt(int x, int y) : x(x), y(y) {}

    /// INPUT/OUTPUT

    void print() {
        printf("(%d, %d)", x, y);
    }

    void println() {
        print();
        printf("\n");
    }

    bool read() {
        return scanf("%d %d", &x, &y) == 2;
    }

    /// OPERATORS

    const pt operator +(pt other) {
        return pt(x + other.x, y + other.y);
    }

    const pt operator +(int c) {
        return pt(x + c, y + c);
    }

    const pt operator -(pt other) {
        return pt(x - other.x, y - other.y);
    }

    const pt operator -(int c) {
        return pt(x - c, y - c);
    }

    pt& operator +=(pt other) {
        x += other.x;
        y += other.y;
        return *this;
    }

    pt& operator +=(int c) {
        x += c; y += c;
        return *this;
    }

    pt& operator -=(pt other) {
        x -= other.x;
        y -= other.y;
        return *this;
    }

    pt& operator -=(int c) {
        x -= c; y -= c;
        return *this;
    }

    const pt operator *(int c) {
        return pt(x * c, y * c);
    }

    pt& operator *=(int c) {
        x *= c; y *= c;
        return *this;
    }

    const pt operator /(int c) {
        return pt(x / c, y / c);
    }

    pt& operator /=(int c) {
        x /= c; y /= c;
        return *this;
    }

    pt& operator =(pt other) {
        x = other.x;
        y = other.y;
        return *this;
    }

    /// FUNCTIONS

    ll distSq(pt p) {
        return (x - p.x) * (x - p.x) + (y - p.y) * (y - p.y);
    }

    double dist(pt p) {
        return sqrt(distSq(p));
    }

    double magnitude() {
        return dist(pt(0, 0));
    }

    int orient(pt a, pt b) {
        ll val = (a.y - y) * (b.x - a.x) - (a.x - x) * (b.y - a.y);

        if (val == 0) {
            return 0;
        }

        return (val < 0 ? -1 : 1);
    }
};

const bool operator <(pt a, pt b) {
    if (a.x == b.x) {
        return a.y < b.y;
    }

    return a.x < b.x;
}

pt convexHullP;

bool convexHullCmp(pt a, pt b) {
    int cur = convexHullP.orient(a, b);

    if (cur == 0) {
        return convexHullP.distSq(a) < convexHullP.distSq(b);
    }

    return cur == -1;
}

struct convexHull {
    vector<pt> V;

    convexHull() {
        V.clear();
    }

    convexHull(vector<pt> _V) {
        V = _V;
    }

    void solve() {
        if (V.size() < 3) {
            return;
        }

        int n = V.size(), m = 1;

        for (int i = 1; i < n; ++i) {
            if (V[i] < V[0]) {
                swap(V[0], V[i]);
            }
        }

        convexHullP = V[0];
        sort(V.begin() + 1, V.end(), convexHullCmp);

        for (int i = 1; i < n; ++i) {
            while (i + 1 < n && V[0].orient(V[i], V[i + 1]) == 0) {
                ++i;
            }

            V[m++] = V[i];
        }

        V.resize(m);

        if (m < 3) {
            return;
        }

        vector<pt> S;
        S.pb(V[0]);
        S.pb(V[1]);

        for (int i = 2; i < m; ++i) {
            while (S.size() > 1 && S[S.size() - 2].orient(S.back(), V[i]) != -1) {
                S.pop_back();
            }

            S.pb(V[i]);
        }

        V = S;
    }
};

