            double angle=acos((c*c+b*b-a*a)/(2*b*c));
            double pi= acos(-1);
           // cout<<i<<" "<<j1<<" "<<j2<<" "<<(c*c+b*b-a*a)/(2*b*c)<<endl;
            ans[i] = (pi-angle)/(2*pi);
        }
