LL determinant(LL i, LL j, LL k) {
  // -           -
  // | x[i] - x[j], x[k] - x[j] |
  // | y[i] - y[j], y[k] - y[j] |
  // -           -
  LL det = (x[i] - x[j]) * (y[k] - y[j]) - (x[k]- x[j]) * (y[i] - y[j]);
  if (det > 0LL) return 1LL;
  if (det == 0LL) return 0LL;
  else return -1LL;
}

void removeColinear(LL i) {
  LL minX = x[i];
  LL maxX = x[i];
  LL minY = y[i];
  LL maxY = y[i];

  for (auto j : idx[i]) {
    minX = min(minX, x[j]);
    maxX = max(maxX, x[j]);
    minY = min(minY, y[j]);
    maxY = max(maxY, y[j]);
  }

  idx[i].insert(i);
  for (auto j : idx[i]) {
    if ((x[j] != minX && x[j] != maxX) || (y[j] != minY && y[j] != maxY)) {
      toErase.PB(j);
    }
  }
  idx[i].erase(i);
}

void convexHull() {
  // brute force convex hull
  FORN(i, N) {
    for (LL j = i+1; j < N; j++) {
      LL signs = 0;
      bool same = true;
      FORN(k, N) {
        if (k == i || k == j) continue;
        LL det = determinant(i, j, k);
        same &= (signs * det >= 0);
        signs = det;
      }
      if (same) {
          idx[i].insert(j);
      }
    }
  }

//  p();
  for (auto& kv : idx) {
    if (kv.SS.size() >= 2) {
      removeColinear(kv.FF);
    }
  }
//  p();

  for (auto e : toErase) {
    if (idx.find(e) != idx.end()) {
      idx.erase(e);
    }
    for (auto& kv : idx) {
      kv.SS.erase(e);
    }
  }
}

double angle(Vector v1, Vector v2) {
  double dot = v1.x * v2.x + v1.y * v2.y;
  double len1 = sqrt(v1.x * v1.x + v1.y * v1.y);
  double len2 = sqrt(v2.x * v2.x + v2.y * v2.y);
  double param = dot / (len1 * len2);
//  printf("<%lld, %lld>, <%lld, %lld>\n", v1.x, v1.y, v2.x, v2.y); cout << "dot: " << dot << endl; cout << "len1: " << len1 << endl; cout << "len2: " << len2 << endl; cout << "param: " << param << endl; cout << acos(param) << endl;
  return acos(param);
}

int main() {
  srand(time(NULL));
  GLL(N);

  FORN(i, N) {
    LL t;
    GLL(t);
    x.PB(t);
    GLL(t);
    y.PB(t);
  }

  if (N == 2) {
    printf("0.5\n");
    printf("0.5\n");
    return 0;
  }

  convexHull();

  // fill in the line segments
  // at this point expect each point to be paired with two other points
  for (auto& kv : idx) {
    for (auto v : kv.SS) {
      idx[v].insert(kv.FF);
    }
  }

  map<LL, double> solution;
  // get angles formed by vectors
  for (auto& kv : idx) {
    LL c = kv.FF;

    if (kv.SS.size() == 1) {
      solution[c] = 0.5;
      continue;
    }
    auto it = kv.SS.begin();
    LL l = *it;
    LL r = *(++it);
//    printf("c: %d, l: %d, r: %d\n", c, l, r);
    Vector v1;
    Vector v2;
    v1.x = x[l] - x[c];
    v1.y = y[l] - y[c];
    v2.x = x[r] - x[c];
    v2.y = y[r] - y[c];

    double a = angle(v1, v2);
    if (a > M_PI) a -= M_PI;
    a = M_PI - a;

    double total = 2 * M_PI;
    solution[c] = a/total;
  }

  FORN(i, N) {
    printf("%.20f\n", solution[i]);
  }


  return 0;
}

