constexpr Point conj (const Point& p) {return Point(p.x, -p.y); }
// The angle is in radian
template <typename T> constexpr Point rot (const Point& p, const T& angle) { return Point(cos(angle) * p.x - sin(angle) * p.y, sin(angle) * p.x + cos(angle) * p.y); }
constexpr Point rot90 (const Point& p) { return Point(-p.y, p.x); }
constexpr double cross (const Point& p, const Point& q) { return p.x * q.y - p.y * q.x; }
constexpr double dot (const Point& p, const Point& q) { return p.x * q.x + p.y * q.y; }
constexpr double norm (const Point& p) { return dot(p, p); }
constexpr double abs (const Point& p ) { return sqrt(dot(p, p)); }
constexpr double amp (const Point& p ) { double res = atan2(p.y, p.x); if (res < 0) res += M_PI * 2; return res; }


vector<pair<Point, int>> ConvexHull (vector<pair<Point, int>>& points, bool sortByAngle = false, bool includeMiddlePoint = false) {
  int n = (int) points.size();
  sort(points.begin(), points.end());
  // if (sortByAngle) {
  //   auto compByAngle = [&] (const Point& p, const Point& q) {
  //     Point a = p - points[0];
  //     Point b = q - points[0];
  //     double e = a.y * b.x - a.x * b.y;
  //     return abs(e) < EPS ? norm(a) < norm(b) : e < 0;
  //   };
  //   sort(points.begin() + 1, points.end(), compByAngle);
  // }
  int itr = 0;
  vector<pair<Point, int>> res(n * 2);
  for (int i = 0; i < n; ++i) {
    if (itr >= 2) {
      while (cross(res[itr- 1].first - res[itr - 2].first, points[i].first - res[itr - 2].first) < (includeMiddlePoint ? -EPS : EPS)) {
        --itr;
        if (itr < 2) break;
      }
    }
    res[itr++] = points[i];
  }
  int bound = itr + 1;
  for (int i = n - 2; i >= 0; i--) {
    if (itr >= bound) {
      while (cross(res[itr- 1].first - res[itr - 2].first, points[i].first - res[itr - 2].first) < (includeMiddlePoint ? -EPS : EPS)) {
        --itr;
        if (itr < bound) break;
      }
    }
    res[itr++] = points[i];
  }
  res.resize(itr - 1);
  return res;
}
signed main() { 
  ios::sync_with_stdio(false); cin.tie(0);
  int n;
  cin >> n;
  vector<pair<Point, int>> points(n);
  for (int i = 0; i < n; i++) {
    cin >> points[i].first.x >> points[i].first.y;
    points[i].second = i;
  }
  auto res = ConvexHull(points);
  vector<double> ans(n);
  int m = (int) res.size();
  for (int i = 0; i < m; i++) {
    Point pre = rot90(res[i].first - res[(i - 1 + m) % m].first);
    Point nxt = rot90(res[(i + 1 + m) % m].first - res[i].first);
    int idx = res[i].second;
    double angle = amp(nxt) - amp(pre);
    if (angle < 0) angle += 2 * M_PI;
    ans[idx] = angle / (M_PI * 2);
  }
  for (int i = 0; i < n; i++) cout << setprecision(20) << fixed << ans[i] << '\n';
  return 0;
}

