};

struct Circle {
  Point p; ld r;
  Circle (Point a, ld b) : p(a), r(b) {;}
};

// counter clockwise
int ccw (Point a, Point b, Point c) {
  b -= a; c -= a;
  if (cross(b, c) > eps) return 1;   // counter clockwise
  if (cross(b, c) < -eps) return -1; // clockwise
  if (dot(b, c) < 0) return 2;       // c--a--b on line
  if (norm(b) < norm(c)) return -2;  // a--b--c on line
  return 0;                          // a--c--b on line
}

vector<Point> unique(vector<Point> ps) {
  sort(begin(ps), end(ps), comp);
  vector<Point> res;
  for (Point p: ps)
    if (res.empty() || abs(res.back() - p) > eps)
      res.push_back(p);
  return res;
}

Polygon convex_hull(vector<Point> ps) {
  int n = ps.size(), k = 0;
  sort(begin(ps), end(ps), comp);
  Polygon res(2 * n);
  for (int i = 0; i < n; res[k++] = ps[i++])
    while (k >= 2 && ccw(res[k - 2], res[k - 1], ps[i]) <= 0) --k;
  for (int i = n - 2, t = k + 1; i >= 0; res[k++] = ps[i--])
    while (k >= t && ccw(res[k - 2], res[k - 1], ps[i]) <= 0) --k;
  res.resize(k - 1);
  return res;
}

void solve(ll N, vector<ll> x, vector<ll> y) {
  vector<Point> points;
  REP(i,N) points.emplace_back(x[i], y[i]);
  Polygon poly = convex_hull(points);
  vector<ld> res(N, 0.0L);
  const int n = poly.size();
  REP(i,n) {
    Point a = at(poly, i);
    // cout << a << endl;
    Point b = at(poly, i + 1);
    Point c = at(poly, i + 2);
    ld angle = abs(arg((b - a) / (c - b)));
    ld p = angle / (2 * acos(-1.0));
    REP(j,N) {
      if (abs(points[j] - b) < eps) res[j] += p;
    }
  }
  for (auto i: res) cout << i << endl;
}

