    //General
    template<class T> class cycleq_t{
        private:
        size_t cnt, cap;
        size_t lef, rig;
        T *que;
        public:
        cycleq_t(const size_t size){
            this->cap=size;
            this->que=(T*)malloc(sizeof(T)*size);
            this->clear();
        }
        ~cycleq_t(){
            free(this->que);
        }
        inline void clear(){
            this->lef=this->rig=0;
            this->cnt=0;
        }
        inline void put(const T &obj){
            assert(this->cnt<this->cap);
            this->que[this->rig++]=obj;
            if(this->rig==this->cap)
                this->rig=0;
            this->cnt++;
        }
        inline void put_back(const T &obj){
            this->put(obj);
        }
        inline void put_front(const T &obj){
            assert(this->cnt<this->cap);
            this->lef--;
            if(!~this->lef)
                this->lef=this->cap-1;
            this->que[this->lef]=obj;
            this->cnt++;
        }
        inline T pop(){
            assert(this->cnt>0);
            T res=this->que[this->lef++];
            if(this->lef==this->cap)
                this->lef=0;
            this->cnt--;
            return res;
        }
        inline T pop_front(){
            return this->pop();
        }
        inline T pop_back(){
            assert(this->cnt>0);
            this->rig--;
            if(!~this->rig)
                this->rig=this->cap-1;
            this->cnt--;
            return this->que[this->rig];
        }
        inline T get(int64_t offset=0){
            if(offset>=0){
                assert(offset<this->cnt);
                offset+=this->lef;
                if(offset>this->cap)
                    offset-=this->cap;
                return this->que[offset];
            }else{
                assert(offset>=-this->cnt);
                offset+=this->rig;
                if(offset<0)
                    offset+=this->cap;
                return this->que[offset];
            }
        }
    };

