Real cross(P a, P b){return imag(a*conj(b));}
Real dot(P a, P b){return real(a*conj(b));}

int ccw(int aa, int bb, int cc){
  P a = ps[aa].first, b = ps[bb].first, c = ps[cc].first;
  b -= a; c -= a;
  if (cross(b, c) > 0)   return +1;       // counter clockwise
  if (cross(b, c) < 0)   return -1;       // clockwise
  if (dot(b, c) < 0)     return +2;       // c--a--b on line
  if (norm(b) < norm(c)) return -2;       // a--b--c on line
  return 0;
}

