  }
  // http://www.prefield.com/algorithm/geometry/convex_hull.html
  REP(i,n)ps[i]=make_pair(p[i], i);
  sort(ps,ps+n,[&](pair<P,int> a,pair<P,int> b){
    P ap = a.first, bp = b.first;
    if(ap.real() != bp.real())return ap.real() < bp.real();
    return ap.imag() < bp.imag();
  });
  vi ch;
  for (int i = 0; i < n; ch.push_back(i++)) // lower-hull
    while (ch.size() >= 2 && ccw(ch[ch.size()-2], ch[ch.size()-1], i) <= 0)ch.pop_back();
  for (int i = n-2, t = ch.size()+1; i >= 0; ch.push_back(i--)) // upper-hull
    while (ch.size() >= t && ccw(ch[ch.size()-2], ch[ch.size()-1], i) <= 0)ch.pop_back();
  ch.pop_back();
  REP(i,ch.size()){
    int a = ch[i];
    int b = ch[(i+1)%ch.size()];
    int c = ch[(i+ch.size()-1)%ch.size()];
    int id = ps[a].second;
    P ap = ps[a].first;
    P bp = ps[b].first;
    P cp = ps[c].first;
    // printf("%d %d %d\n",ps[a].second,ps[b].second,ps[c].second);
    if(ch.size()==1){
      ans[id] = 1.0;
