long double arcs(long double I, int ty) {
	long double X = 1.0L, Y = I, Z = sqrtl(X*X + Y*Y);
	I = 1.0L*Y / Z;
	I = asin(I); I *= 0.5L / 3.14159265358979L;
	if (ty == 1) {
		if (I >= 0.0L) return I;
		return 1.0L + I;
	}
	return 0.5L + I;
}

