const double PI = 2 * acos(0);

void solve() {
  cin >> n;
  for(int i = 0; i < n; i++) {
    cin >> x[i] >> y[i];
  }
  for(int i = 0; i < n; i++) {
    map<double, int> dp;
    for(int j = 0; j < n; j++) {
      if(i == j) continue;
      double ang = atan2(y[i] - y[j], x[i] - x[j]);
      double lhs = ang - PI/2;
      double rhs = ang + PI/2;
      if(lhs >= 0) {
        dp[lhs]++;
        dp[rhs]--;
        continue;
      }
      assert(lhs < 0);
      if(rhs < 0) {
        lhs += 2*PI;
        rhs += 2*PI;
        dp[lhs]++;
        dp[rhs]--;
        continue;
      }
      assert(lhs < 0 && rhs >= 0);
      dp[0]++;
      dp[rhs]--;
      dp[lhs+2*PI]++;
    }
    double ret = 0;
    double last = 0;
    int amt = 0;
    for(auto out: dp) {
      if(amt == n-1) ret += out.first - last;
      amt += out.second;
      last = out.first;
    }
    if(amt == n-1) ret += 2*PI-last;
    cout << fixed << setprecision(12) << ret/(2*PI) << "\n";
  }
}

