	for(int i = 0; i < n; i++) {
		i64 a, b; cin >> a >> b;

		vec[i] = Point{a, b};
		mp[vec[i]] = i;
	}

	vec = convexFull(vec);
	std::vector<double> ans(n, 0);
	const double Pi = std::acos(-1);
	for(int i = 0; i < vec.size(); i++) {
		Point u = vec[(i + vec.size() - 1) % vec.size()] - vec[i];
		Point v = vec[(i + 1) % vec.size()] - vec[i];
		ans[mp[vec[i]]] = angle(u, v) / 2.0 / Pi;
	}

	for(auto v : ans) cout << std::fixed << std::setprecision(16) << v << endl;
	return 0;
}

