namespace Nanshou
{
	const int N=105;
	const double eps=1e-9;
	const double pi=acos(-1.0);

	struct point
	{
		double x,y;
		int id;

		point (double a=0,double b=0,int c=0)
		{
			x=a,y=b;
			id=c;
		}
	};

	bool operator < (point A,point B){return A.x<B.x;}
	point operator - (point A,point B){return point(A.x-B.x,A.y-B.y);}

	double cross(point A,point B)
	{
		return A.x*B.y-A.y*B.x;
	}

	point s[N];
	double ans[N];

	int n,m;

	point t[N];

	void insert(point A)
	{
		while(m>1)
		{
			point B=t[m],C=t[m-1];

			if(cross(A-C,B-C)>=-eps)m--;
			else break;
		}
		t[++m]=A;
	}

	void calc_hull()
	{
		m=0;
		for(int i=1;i<=n;i++)
			insert(s[i]);
		for(int i=n-1;i;i--)
			insert(s[i]);
	}

	void initialize()
	{
		scanf("%d",&n);
		for(int i=1;i<=n;i++)
			scanf("%lf%lf",&s[i].x,&s[i].y),s[i].id=i;
		std::sort(s+1,s+n+1);
	}

	double fuck(point A)
	{
		return atan2(A.y,A.x);
	}

	void getans()
	{
		t[m+1]=t[2];

		for(int i=2;i<=m;i++)
		{
			double x=fuck(t[i-1]-t[i]),y=fuck(t[i]-t[i+1]);

			y-=x;
			while(y<0)y+=pi;
			while(y>pi)y-=pi;

			ans[t[i].id]=y/pi/2;
		}
	}

	void solve()
	{
		initialize();

		if(n==2)
		{
			printf("0.5\n0.5\n");
			return;
		}

		calc_hull();

		getans();

		for(int i=1;i<=n;i++)
			printf("%.15lf\n",ans[i]);
	}

}

int main()
{
	Nanshou::solve();
	return 0;
}

