//! グラハムスキャンによる凸包検索クラス
class ConvexFull
{
  public:
    ConvexFull() {}

    //! グラハムスキャンによる凸包検索関数。
    //! pll配列を受け取り、凸包になるような要素のindex配列を返却する。
    //! 返り値の配列は凸包となるような要素のindexが反時計回りで格納されている。
    //! 計算オーダーO(NlogN)
    vector<int> getConvexFullIndex(Vec2 *vecTbl, int N)
    {
        vector<GridInfo> G(N);
        for (int i = 0; i < N; ++i)
        {
            //! とりあえず扱いやすいよう変換
            G[i] = GridInfo(vecTbl[i], i);
        }
        std::sort(G.begin(), G.end(), [](GridInfo a, GridInfo b) { return a.x() == b.x() ? a.y() < b.y() : a.x() < b.x(); });
        vector<int> q(N * 2);
        int k = 0;
        for (int i = 0; i < N; ++i)
        {
            while (k > 1)
            {
                Vec2 v0 = G[i].v - G[q[k - 1]].v;
                Vec2 v1 = G[q[k - 1]].v - G[q[k - 2]].v;
                if (v1.det(v0) > 0)
                    break;
                k--;
            }
            q[k++] = i;
        }
        for (int i = N - 2, t = k; i >= 0; --i)
        {
            while (k > t)
            {
                Vec2 v0 = G[i].v - G[q[k - 1]].v;
                Vec2 v1 = G[q[k - 1]].v - G[q[k - 2]].v;
                if (v1.det(v0) > 0)
                    break;
                k--;
            }
            q[k++] = i;
        }
        q.resize(k - 1);
        REP(i, k - 1)
        {
            q[i] = G[q[i]].i;
        }
        return q;
    }

  private:
    struct GridInfo
    {
        GridInfo() {}
        GridInfo(Vec2 v, int i)
            : v(v), i(i) {}

        Vec2 v;
        int i;

        double x() const
        {
            return v.x;
        }
        double y() const
        {
            return v.y;
        }
    };
};

Vec2 V[105];
double A[105];

int main()
{
    int N;
    cin >> N;
    REP(i, N)
    {
        A[i] = 0;
        cin >> V[i].x >> V[i].y;
    }

    ConvexFull convexFull;
    auto v = convexFull.getConvexFullIndex(V, N);

    int s = v.size();
    REP(i, s)
    {
        if(s==2)
        {
            A[v[i]] = 0.5;
            continue;
        }
        Vec2 v0 = V[v[i]] - V[v[(s + i - 1) % s]];
        Vec2 v1 = V[v[(i + 1) % s]] - V[v[i]];
        v0 = v0.rotate(-M_PI_2).normalize();
        v1 = v1.rotate(-M_PI_2).normalize();
        cout << v0.dot(v1) << endl;
        double theta = acos(v0.dot(v1));
        A[v[i]] = theta / (2 * M_PI);
    }

