class Vec2d {
public:
    Vec2d() : x(0.0), y(0.0) {}
    Vec2d(double xx, double yy) : x(xx), y(yy) {}

    Vec2d& operator+=(const Vec2d& rhs) {
        x += rhs.x;
        y += rhs.y;
        return *this;
    }
    Vec2d& operator-=(const Vec2d& rhs) {
        x -= rhs.x;
        y -= rhs.y;
        return *this;
    }
    Vec2d& operator*=(double c) {
        x *= c;
        y *= c;
        return *this;
    }
    Vec2d& operator/=(double c) {
        x /= c;
        y /= c;
        return *this;
    }

    double norm() const { return x*x + y*y; }
    double abs() const { return hypot(x,y); }

    double x;
    double y;
};

bool equals(const Vec2d& lhs, const Vec2d& rhs, double eps=EPS) {
    return equals(lhs.x, rhs.x, eps) && equals(lhs.y, rhs.y, eps);
}

const Vec2d operator+(const Vec2d& lhs, const Vec2d& rhs) { return Vec2d(lhs) += rhs; }
const Vec2d operator-(const Vec2d& lhs, const Vec2d& rhs) { return Vec2d(lhs) -= rhs; }
const Vec2d operator*(const Vec2d& lhs, double rhs) { return Vec2d(lhs) *= rhs; }
const Vec2d operator*(double lhs, const Vec2d& rhs) { return Vec2d(rhs) *= lhs; }
const Vec2d operator/(const Vec2d& lhs, double rhs) { return Vec2d(lhs) /= rhs; }

ostream& operator<<(ostream& out, const Vec2d& v) {
    return out << '(' << v.x << ',' << v.y << ')';
}

double dot(const Vec2d& lhs, const Vec2d& rhs) {
    return lhs.x * rhs.x + lhs.y * rhs.y;
}

double cross(const Vec2d& lhs, const Vec2d& rhs) {
    return lhs.x * rhs.y - lhs.y * rhs.x;
}

i64 N;
vector<Vec2d> P;

double angle(const Vec2d& lhs, const Vec2d& rhs) {
    return atan2(cross(lhs,rhs), dot(lhs,rhs));
}

// 円周上に等間隔に点をとり、各点について最も近い穴をカウント
// 円周上の点: (R*cos(t), R*sin(t))
// (R*cos(t)-x)^2 + (R*sin(t)-y)^2 = R^2 - 2*R*(x*cos(t)+y*sin(t)) + x^2+y^2
// x^2+y^2 の項は誤差レベルなので無視すると、
// x*cos(t) + y*sin(t) が最大になる穴が最も近い穴
void solve() {
    static constexpr i64 ITER = 250'000;

    const auto f = [](const Vec2d& p, double t) {
        return p.x*cos(t) + p.y*sin(t);
    };

    vector<i64> cnt(N, 0);
    REP(i, ITER) {
        double t = 2.0*PI * i/ITER;

        auto it = ALL(max_element, P, [f,t](const auto& lhs, const auto& rhs) {
            return f(lhs,t) < f(rhs,t);
        });
        i64 j = distance(begin(P), it);

        ++cnt[j];
    }

    for(auto c : cnt) {
        double ans = (0.0+c) / ITER;
        PRINTLN(ans);
    }
}

signed main(signed /*argc*/, char** /*argv*/) {
    RD(N);

    P.reserve(N);
    REP(_, N) {
        double x,y; RD(x); RD(y);
        P.emplace_back(x, y);
    }

    DBG(P);

    solve();

    EXIT();
}

