const int CLOCK = 1;
const int ANTI_CLOCK = -1;
const int  PARALLEL = 0;

class Point {


public:


	double x, y;

	Point(double x = 0, double y = 0) : x(x), y(y) {}

	Point operator + (Point p) { return Point(x + p.x, y + p.y); }
	Point operator - (Point p) { return Point(x - p.x, y - p.y); }
	Point operator * (double a) { return Point(x * a, y * a); }
	Point operator / (double a) { return Point(x / a, y / a); }

	double abs() { return sqrt(norm()); }
	double norm() { return x * x + y * y; }

	bool operator < (const Point &p) const {
		return x != p.x ? x < p.x : y < p.y;
	}

	bool operator == (const Point &p) const {
		return fabs(x - p.x) < EPS && fabs(y - p.y) < EPS;
	}

};
double dot(Point a, Point b) {
	return a.x * b.x + a.y * b.y;
}

double cross(Point a, Point b) {
	return a.x * b.y - a.y * b.x;

}

typedef vector<Point> Polygon;


int ccw(Point p0, Point p1, Point p2) {

	if (fabs(cross(p1 - p0, p2 - p0)) < EPS)
		return PARALLEL;

	else if (cross(p1 - p0, p2 - p0) > 0) {
		return ANTI_CLOCK;
	}
	else {

		return CLOCK;
	}

}

int main() {
	ll q;
	Polygon d, d2;
	cin >> q;

	if (q == 2) {
		cout << 0.5 << endl;
		cout << 0.5 << endl;
		return 0;
	}


	rep(i, q) {
		double x, y;
		cin >> x >> y;
		d.push_back(Point(x, y));
		d2.push_back(Point(x, y));
	}

	sort(d.begin(), d.end());

	Polygon stu, stl;

	stu.push_back(d[0]);
	stu.push_back(d[1]);

	for (int i = 2; i < q; i++) {
		for (int j = stu.size(); j >= 2 && ccw(stu[j - 2], stu[j - 1], d[i]) != CLOCK; j--) {
			stu.pop_back();
		}
		stu.push_back(d[i]);
	}
	reverse(d.begin(), d.end());

	stl.push_back(d[0]);
	stl.push_back(d[1]);

	for (int i = 2; i < q; i++) {
		for (int j = stl.size(); j >= 2 && ccw(stl[j - 2], stl[j - 1], d[i]) != CLOCK; j--) {
			stl.pop_back();
		}
		stl.push_back(d[i]);
	}


	stl.erase(stl.begin());
	stl.pop_back();

	stu.insert(stu.end(), stl.begin(), stl.end());

	double sum = 0.0;
	map<Point, double>anslist;
	rep(i, stu.size()) {
		Point l, r;
		if (i == 0) {
			l = stu[stu.size() - 1] - stu[i];
			r = stu[i + 1] - stu[i];

		}

		else if (i == stu.size() - 1) {
			l = stu[0] - stu[i];
			r = stu[i - 1] - stu[i];
		}

		else {
			l = stu[i-1] - stu[i];
			r = stu[i+1] - stu[i];
		}

		double co = dot(l, r);
		double l1 = l.abs(), l2 = r.abs();
		co = co /  (l1 * l2);
		anslist[stu[i]] = (acos(-1.0) - acos(co));

	}


	sum = 2.0 * acos(-1.0);

	rep(i, anslist.size()) {

		printf("%.20f\n", anslist[d2[i]] / sum);
	}

	return 0;
}

