typedef complex<double> xy;
double eps = 1e-9;
double dot_product(xy a,xy b) {return (conj(a)*b).real();}
double cross_product(xy a,xy b) {return (conj(a)*b).imag();}
bool comp(xy a,xy b){
    return (a.real()!=b.real()? a.real()<b.real() : a.imag()<b.imag());
}
struct point{
    xy place;
    int id;
    bool operator<(const point& right)const{
        return comp(place,right.place);
    }
};

vector<point> convex_hull(vector<point> v){
    int n = v.size();
    vector<point> res;
    sort(v.begin(),v.end());
    for(int i=0;i<n;i++){
        if(i<2){
            res.push_back(v[i]);
            continue;
        }
        while(true){
            int s = res.size();
            if(s<2){
                res.push_back(v[i]);
                break;
            }
            double c = cross_product(res[s-1].place-res[s-2].place,v[i].place-res[s-2].place);
            if(c<-eps){
                res.pop_back();
            }else{
                res.push_back(v[i]);
                break;
            }
        }
    }
    reverse(v.begin(),v.end());
    for(int i=0;i<n;i++){
        while(true){
            int s = res.size();
            if(v[i].place==res.back().place) break;
            if(s<2){
                res.push_back(v[i]);
                break;
            }
            double c = cross_product(res[s-1].place-res[s-2].place,v[i].place-res[s-2].place);
            if(c<-eps){
                res.pop_back();
            }else{
                res.push_back(v[i]);
                break;
            }
        }
    }
    res.pop_back();
    return res;
}


