#include <bits/stdc++.h>
using namespace std;
using P = complex<double>;
const double PI = acos(-1.0);
namespace std{bool operator<(const P& a, const P& b){
  return real(a)!=real(b)?real(a)<real(b):imag(a)<imag(b);
}}
double inP(const P& p, const P& q){ return real(conj(p)*q); } //dot
double outP(const P& p, const P& q){ return imag(conj(p)*q); } //cross
int ccw(P a, P b, P c)
{
    b -= a;
    c -= a;
    if(outP(b,c) > 0) return +1; //counter clockwise
    if(outP(b,c) < 0) return -1; //clockwise
    if(inP(b,c) < 0) return +2; //c-a-b on line
    if(norm(b) < norm(c)) return -2; //a-b-c on line
    return 0;
}
vector<P> convex_hull(vector<P> &ps)
{
    int n = ps.size();
    int k = 0;
    sort(ps.begin(), ps.end());
    vector<P> qs(n*2);
    for(int i = 0; i < n; i++)
    {
        while(k > 1 && ccw(qs[k-2], qs[k-1], ps[i]) <= 0) k--;
        qs[k++] = ps[i];
    }
    for(int i = n-2, t = k; i >= 0; i--)
    {
        while(k > t && ccw(qs[k-2], qs[k-1], ps[i]) <= 0) k--;
        qs[k++] = ps[i];
    }
    qs.resize(k-1);
    return qs;
}

int main()
{
    int n;
    cin >> n;
    vector<P> ps;
    map<vector<int>, int> rem;
    for(int i = 0; i < n; i++)
    {
        int x, y;
        cin >> x >> y;
        ps.push_back(P(x, y));
        rem[{x, y}] = i;
    }
    vector<P> qs = convex_hull(ps);
    vector<double> ans(n);
    int m = qs.size();
    for(int i = 0; i < m; i++)
    {
        int x = qs[i].real();
        int y = qs[i].imag();
        double xprev = qs[(i-1+m)%m].real();
        double yprev = qs[(i-1+m)%m].imag();
        double xnext = real(qs[(i+1+m)%m]);
        double ynext = imag(qs[(i+1+m)%m]);
        double r1 = atan2(yprev-y, xprev-x);
        double r2 = atan2(ynext-y, xnext-x);
        double arg = r1 - r2;
        if(arg < 0) arg += 2*PI;
        double targ = PI - arg;
        int num = rem[{x, y}];
        ans[num] = targ / (2*PI);
    }
    for(int i = 0; i < n; i++)
    {
        printf("%.10f\n", ans[i]);
    }
}

