int determinant(int i, int j, int k) {
  // -           -
  // | x[i] - x[j], x[k] - x[j] |
  // | y[i] - y[j], y[k] - y[j] |
  // -           -
  int det = (x[i] - x[j]) * (y[k] - y[j]) - (x[k]- x[j]) * (y[i] - y[j]);
  if (det > 0) return 1;
  if (det == 0) return 0;
  else return -1;
}

void removeColinear(int i) {
  int minX = x[i];
  int maxX = x[i];
  int minY = y[i];
  int maxY = y[i];

  for (auto j : idx[i]) {
    minX = min(minX, x[j]);
    maxX = max(maxX, x[j]);
    minY = min(minY, y[j]);
    maxY = max(maxY, y[j]);
  }

  idx[i].insert(i);
  for (auto j : idx[i]) {
    if ((x[j] != minX && x[j] != maxX) || (y[j] != minY && y[j] != maxY)) {
      toErase.PB(j);
    }
  }
  idx[i].erase(i);
}

void convexHull() {
  // brute force convex hull
  FORN(i, N) {
    for (int j = i+1; j < N; j++) {
      int signs = 0;
      bool same = true;
      FORN(k, N) {
        if (k == i || k == j) continue;
        int det = determinant(i, j, k);
        same &= (signs * det >= 0);
        signs = det;
      }
      if (same) {
          idx[i].insert(j);
      }
    }
  }

  for (auto& kv : idx) {
    if (kv.SS.size() > 2) {
      removeColinear(kv.FF);
    }
  }

  for (auto e : toErase) {
    if (idx.find(e) != idx.end()) {
      idx.erase(e);
    }
    for (auto& kv : idx) {
      kv.SS.erase(e);
    }
  }
}

