int is_clockwise(pair<ll, ll> x, pair<ll, ll> y, pair<ll, ll> z) {
    pair<int, int> a = {y.first - x.first, y.second - x.second},
                   b = {z.first - x.first, z.second - x.second};
    if (a.first * b.second - a.second * b.first < -(1e-10)) return 1;
    else return 0;
}

template < typename T >
vector< P< pair<T, T>, int > > andrew_cht(vector< P< pair<T, T>, int > > s) {
    vector< P< pair<T, T>, int > > u, l;
    V<int> uid, lid;
    if (s.size() < 3) return s;
    sort(s.begin(), s.end());

    // 凸包の上側を作成
    u.push_back(s[0]);
    u.push_back(s[1]);
    for (int i = 2; i < s.size(); i++) {
        for (int n = u.size(); n >= 2 && is_clockwise(u[n - 2].first, u[n - 1].first, s[i].first) == 1; n--) {
            u.pop_back();
        }
        u.push_back(s[i]);
    }

    // 凸包の下側を作成
    l.push_back(s[s.size() - 1]);
    l.push_back(s[s.size() - 2]);
    for (int i = s.size() - 3; i >= 0; i--) {
        for (int n = l.size(); n >= 2 && is_clockwise(l[n - 2].first, l[n - 1].first, s[i].first) == 1; n--) {
            l.pop_back();
        }
        l.push_back(s[i]);
    }

    // 時計回りになるよう点列を作成
    for (int i = 1; i < l.size() - 1; i++) u.push_back(l[i]);

    return u;
}

