  ll s = qs.size();

  vector<double> ans(N, 0);
  REP(i, 0, qs.size()) {
    Vector2 p = qs[(i + s - 1) % s];
    Vector2 c = qs[i];
    Vector2 n = qs[(i + 1) % s];

    double a1 = n.y - c.y, b1 = -(n.x - c.x);
    double theta1 = atan2(b1, a1) + M_PI;

    double a2 = c.y - p.y, b2 = -(c.x - p.x);
    double theta2 = atan2(b2, a2) + M_PI;

    if(theta1 > theta2) ans[c.t] = (theta1 - theta2) / (M_PI * 2);
    if(theta1 < theta2) ans[c.t] = (theta1 - theta2 + M_PI * 2) / (M_PI * 2);
  }

