	{
		return mycp.real();
	}
	db imag()
	{
		return mycp.imag();
	}
	bool operator ==(cp b)
	{
		return mycp == b.mycp;
	}
};
//typedef complex<db> cp;

db cross(cp a, cp b)
{
	return a.real() * b.imag() - a.imag() * b.real();
}

int main()
{
	int n;
	cin >> n;
	cout.precision(30);
	vector<cp> pts(n);	
	for (int i = 0; i < n; ++i)
	{
		db x, y;
