static uint32_t xor128(void) {
    static uint32_t x = 123456789, y = 362436069, z = 521288629, w = 88675123;
    uint32_t t = x ^ (x << 11); x = y; y = z; z = w;
    return w = (w ^ (w >> 19)) ^ (t ^ (t >> 8));
}
class Solution {
public:
    static bool comp(const mt &lhs, const mt &rhs) {
        if (get<0>(lhs) != get<0>(rhs)) return get<0>(lhs) < get<0>(rhs);
        return get<1>(lhs) < get<1>(rhs);
    }
    void solve(std::istream& in, std::ostream& out) {
        ll n;
        in >> n;
        vmt xy(n);
        ll xmax = 0;
        ll ymax = 0;
        for (int i = 0; i < n; i++) {
            ll x, y;
            in >> x >> y;
            get<0>(xy[i]) = 0.0;
            get<1>(xy[i]) = i;
            get<2>(xy[i]) = x;
            get<3>(xy[i]) = y;
            xmax = max(x, xmax);
            ymax = max(y, ymax);
        }
        vector<long double> probs(n);
        ll cnt = 0;
        vll cum(n);
        for (int i = 0; i < 1000000; i++) {
            int x = (int)(xor128() - INT_MAX);
            int y = (int)(xor128() - INT_MAX);
            for (int i = 0; i < n; i++) {
                get<0>(xy[i]) = hypot(x - get<2>(xy[i]), y - get<3>(xy[i]));
            }
            sort(all(xy), comp);
            cum[get<1>(xy[0])]++;
            cnt++;
        }
        for (int i = 0; i < n; i++) {
            get<0>(xy[i]) = i;
        }
        sort(all(xy), comp);
        for (int i = 0; i < n; i++) {
            out << cum[i] / (double)cnt << endl;
        }
    }
};
void solve(std::istream& in, std::ostream& out) {
    out << std::setprecision(12);
    Solution solution;
    solution.solve(in, out);
}

