  int k=0;
  vector<P> ans(n*2);
  vector<int> ret(n*2);
  for(int i=0;i<n;i++){
    while(k>1&&det(ans[k-1]-ans[k-2],v[i]-ans[k-1])<=0) k--;
    ans[k]=v[i].first;
    ret[k]=v[i].second;
    k++;
  }
  for(int i=n-2,t=k;i>=0;i--){
    while(k>t&&det(ans[k-1]-ans[k-2],v[i]-ans[k-1])<=0) k--;
    ans[k]=v[i].first;
    ret[k]=v[i].second;
    k++;
  }
  ans.resize(k-1);
  ret.resize(k-1);
  return ret;
}
