			else {
				if ( !det ) flag = false;
				break;
			}
		}
		if ( flag ) stk[++top] = i;
	}

	stk[top + 1] = stk[1];
	lpi ( i, 1, top ) {
		ang[i] = getang ( cr[stk[i + 1]].y - cr[stk[i]].y, cr[stk[i]].x - cr[stk[i + 1]].x );
	}

	ang[0] = ang[top];
	lpi ( i, 1, top ) cr[stk[i]].ans = dec ( ang[i], ang[i - 1] ) / ( 2 * PI );

	sort ( cr, cr + n, [] ( cT &x, cT &y ) { return x.id < y.id; } );

	lp ( i, 0, n ) cout << setprecision ( 13 ) << fixed << cr[i].ans << endl;
}

