    for(int i = 0; i < N; i++){
        scanf("%lf %lf",&x,&y);
        vertices[i]=point(x,y);
    }
    int pos = 0;
    for(int i = 0; i < N; i++)
        if(imag(vertices[i]) < imag(vertices[pos]) ||
                (imag(vertices[i])==imag(vertices[pos]) &&
                 (real(vertices[i]) > real(vertices[pos]))))
            pos = i;
