	}
	--m;
	if(m == 2) {
		ans[stk[0]] = ans[stk[1]] = 0.5;
	} else {
		for(int i = 0; i < m; ++i) {
			int lft = stk[(m + i - 1) % m], mid = stk[i], rht = stk[(i + 1) % m];
			Point pre = p[mid] - p[lft], suf = p[rht] - p[mid];
			ans[mid] = acos(pre.dot(suf) / pre.len() / suf.len()) / pi / 2;
		}
	}
	for(int i = 0; i < n; ++i)
		printf("%.20f\n", ans[i]);
	return 0;
}

