struct Point {
	double x, y;
	Point operator - (const Point& a) const { return Point{x - a.x, y - a.y}; }
	bool operator < (const Point& a) const { return x == a.x ? y < a.y : x < a.x; }
};

double norm(const Point& a) { return a.x * a.x + a.y * a.y; }
double abs(const Point& a) { return sqrt((double)norm(a)); }
double dot(const Point& a, const Point& b) { return a.x * b.x + a.y * b.y; }
double cross(const Point& a, const Point& b) { return a.x * b.y - a.y * b.x; }

int ccw(const Point& a, const Point& b, const Point&  c) {
	Point ba = b - a, ca = c - a;
	if (cross(ba, ca) > 0) return +1; // ccw
	if (cross(ba, ca) < 0) return -1; // cw
	if (dot(ba, ca) < 0) return +2; // c-a-b
	if (norm(ba) < norm(ca)) return -2; // a-b-c
	return 0; // a-c-b
}

Vec< Point > convex_hull(Vec< Point > vp) {
	int n = vp.size(), k = 0;
	sort(allof(vp));
	Vec< Point > ch(2 * n);

	for (int i = 0; i < n; ch[k++] = vp[i++]) {
		while (k >= 2 && ccw(ch[k - 2], ch[k - 1], vp[i]) <= 0) --k;
	}

	for (int i = n - 2, t = k + 1; i >= 0; ch[k++] = vp[i--]) {
		while (k >= t && ccw(ch[k - 2], ch[k - 1], vp[i]) <= 0) --k;
	}

	ch.resize(k-1);
	return ch;
}

double calcCos(const Point& a, const Point& b, const Point& c) {
	Point x = b - a, y = c - a;
	return (double)dot(x, y) / (abs(x) * abs(y));
}


