double add(double a, double b)
{
	if (abs(a + b) < EPS*(abs(a) + abs(b))) return 0;
	return a + b;
}

//二次元ベクトル構造体
struct P
{
	double x, y;

	P() {}
	P(double x, double y) : x(x), y(y) {
	}
	P operator + (P p) {
		return P(add(x, p.x), add(y, p.y));
	}
	P operator - (P p) {
		return P(add(x, -p.x), add(y, -p.y));
	}
	P operator * (double d) {
		return P(x*d, y*d);
	}
	double dot(P p) {
		return add(x*p.x, y*p.y);
	}
	double det(P p) {
		return add(x*p.y, -y * p.x);
	}
};

//辞書順で比較
bool cmp_x(const P& p, const P& q)
{
	if (p.x != q.x) return p.x < q.x;
	return p.y < q.y;
}

//凸包を求める
vector<P> convex_hull(P* ps, int n)
{
	sort(ps, ps + n, cmp_x);
	int k = 0; //凸包の頂点数
	vector<P> qs(n * 2); //構築中の凸包

	//下側凸包の作成
	for (int i = 0; i < n; i++)
	{
		while (k > 1 && (qs[k - 1] - qs[k - 2]).det(ps[i] - qs[k - 1]) <= 0)
		{
			k--;
		}
		qs[k++] = ps[i];
	}

	//上側凸包の作成
	for (int i = n - 2, t = k; i >= 0; i--)
	{
		while (k > t && (qs[k - 1] - qs[k - 2]).det(ps[i] - qs[k - 1]) <= 0)
		{
			k--;
		}
		qs[k++] = ps[i];
	}
	qs.resize(k - 1);
	return qs;
}

//距離の2乗
double dist(P p, P q)
{
	return (p - q).dot(p - q);
}

P ps[101], rs[101];

void solve()
{
	vector<P> qs = convex_hull(ps, n);
	double res = 0, ea[101];

	for (int i = 1; i < qs.size() - 1; i++)
	{
		ea[i] = M_PI - acos((qs[i - 1] - qs[i]).dot(qs[i + 1] - qs[i]) / (sqrt(dist(qs[i], qs[i - 1]))*sqrt(dist(qs[i + 1], qs[i]))));
	}
	ea[0] = M_PI - acos((qs[qs.size() - 1] - qs[0]).dot(qs[1] - qs[0]) / (sqrt(dist(qs[0], qs[qs.size() - 1]))*sqrt(dist(qs[1], qs[0]))));
	ea[qs.size() - 1] = M_PI - acos((qs[qs.size() - 2] - qs[qs.size() - 1]).dot(qs[0] - qs[qs.size() - 1]) / (sqrt(dist(qs[qs.size() - 1], qs[qs.size() - 2]))*sqrt(dist(qs[0], qs[qs.size() - 1]))));

	for (int i = 0; i < n; i++)
	{
