	{
		return a.x*b.x+a.y*b.y;
	}


}p[10001];
const double PI=acos(-1);
double cross(pv a,pv b,pv c)
{
	return (b-a)*(c-a);
}
double ans[10001];
int n,st,xt,zt,ids[10001],idx[10001],idz[10001];
pv sm[10001],xm[10001],zm[10001];
double agl(pv a,pv b)
{
	if(sb(a*b)==0){if(sb(a.x*b.x)>=0||sb(a.y*b.y)>=0)return 0;return PI;}
	return acos((a/b)/sqrt((a.x*a.x+a.y*a.y)*(b.x*b.x+b.y*b.y)));
}
