const int MX = 100;
const long double pi = acos(-1), R = 1e15;

int x[MX], y[MX];

int main() {
	int n;
	ignore = scanf("%d", &n);
	for (int i = 0; i < n; i++) ignore = scanf("%d %d", x + i, y + i);

	for (int i = 0; i < n; i++) {
		vector<pair<long double, int>> events;
		for (int j = 0; j < n; j++) {
			if (i == j) continue;

			long double xc = (x[i] + x[j]) / 2.0;
			long double yc = (y[i] + y[j]) / 2.0;

			long double vx = y[j] - y[i];
			long double vy = x[i] - x[j];

			long double a = vx * vx + vy * vy;
			long double b = 2 * (xc * vx + yc * vy);
			long double c = xc * xc + yc * yc - R * R;

			long double D = b * b - 4 * a * c;
			long double t1 = (-b - sqrt(D)) / (2 * a);
			long double t2 = (-b + sqrt(D)) / (2 * a);

			long double x1 = xc + t1 * vx, y1 = yc + t1 * vy;
			long double x2 = xc + t2 * vx, y2 = yc + t2 * vy;

			long double alpha = atan2(y1 / R, x1 / R);
			long double beta =  atan2(y2 / R, x2 / R);

			if (alpha < 0) alpha += 2 * pi;
			if (beta < 0) beta += 2 * pi;

			// swap(alpha, beta); ????

			events.emplace_back(alpha, +1);
			events.emplace_back(beta, -1);
			if (alpha > beta) {
				events.emplace_back(0, +1);
				events.emplace_back(2 * pi, -1);
			}
		}

		sort(events.begin(), events.end());

		int s = 0;
		long double last = 0, sum = 0;
		for (auto& e : events) {
			if (s == n - 1) sum += e.first - last;
			s += e.second;
			last = e.first;
		}

		printf("%.15Lf\n", sum / (2 * pi));
	}

	return 0;
}

