double per(double ang){
	if (ang < 0) ang += 2*PI;
	return ang;
}
pair<double, double> get(pair<double, double> a, pair<double, double> b){
	pair<double, double> vect = make_pair(b.first - a.first, b.second - a.second);
	pair<double, double> L = make_pair(vect.second, -vect.first);
	pair<double, double> R = make_pair(-vect.second, vect.first);
	double ang1 = atan2(L.second, L.first);
	double ang2 = atan2(R.second, R.first);
	ang1  = per(ang1);
	ang2  = per(ang2);
	return make_pair(ang1, ang2);
}
bool vn(double l, double r, double nv){
    double diff1 = r - l;
    double diff2 = nv - l;
    while (diff1 < 0) diff1+=2*PI;
	while (diff1 >= 2*PI) diff1 -= 2*PI;
	while (diff2 < 0) diff2+=2*PI;
	while (diff2 >= 2*PI) diff2 -= 2*PI;
	if (diff1 >= diff2) return true;
	return false;
}
