double angle(point a, point root){
    if(a.y < root.y) return 180.0 - angle(root, a);
    double xx = (180.0 / PI) * asin((double)(a.y - root.y) / dist(a, root));
    if(a.x < root.x) xx = 180 - xx;
    return xx;
}

