      int y1 = v[k].se - v[k-1].se;
      int x2 = p[i].fi - v[k-1].fi;
      int y2 = p[i].se - v[k-1].se;
      //逆の場合
      if (x1 * y2 - x2 * y1 <= 0) {
        k--;
      } else break;
    }
    k++;
    if (k == sz(v)) v.pb(p[i]);
    else v[k] = p[i];
  }

////debug-----------
