      int y1 = v1[k1].se - v1[k1-1].se;
      int x2 = p[i].fi - v1[k1-1].fi;
      int y2 = p[i].se - v1[k1-1].se;
      //逆の場合
      if (x1 * y2 - x2 * y1 >= 0) {
        k1--;
      } else break;
    }
    k1++;
    if (k1 == sz(v1)) v1.pb(p[i]);
