    vector<PPi> x_(n);
    REP(i, n) x_[i] = PPi(x[i], i);
    Sort(x_);
    int k = 0;
    vec qs(2 * n);
    //下側
    REP(i, n){
        while(k > 1){
            int x1 = x[qs[k - 1]].first - x[qs[k - 2]].first;
            int y1 = x[qs[k - 1]].second - x[qs[k - 2]].second;
            int x2 = x_[i].first.first - x[qs[k - 1]].first;
            int y2 = x_[i].first.second - x[qs[k - 1]].second;
            if(x1 * y2 - x2 * y1 <= 0) k--;
            else break;
        }
        qs[k++] = x_[i].second;
    }
    int t = k;
    //上側
    IREP(i, n - 1){
        while(k > t){
            int x1 = x[qs[k - 1]].first - x[qs[k - 2]].first;
            int y1 = x[qs[k - 1]].second - x[qs[k - 2]].second;
            int x2 = x_[i].first.first - x[qs[k - 1]].first;
            int y2 = x_[i].first.second - x[qs[k - 1]].second;
            if(x1 * y2 - x2 * y1 <= 0) k--;
            else break;
        }
        qs[k++] = x_[i].second;
    }
    qs.resize(k - 1);
    return qs;
}

