        ps.emplace_back(x, y);
        idx[ps[i]] = i;
    }

    vector<Point> table = convex_hull(ps);
    int m = table.size();
    vector<ld> ans(n, 0);
    for(int i = 0; i < m; ++i){
        ld t1 = arg(table[(i + 1) % m] - table[i]);
        if(t1 < 0)  t1 += pi * 2;
        ld t2 = arg(table[(i - 1 + m) % m] - table[i]);
        if(t2 < 0)  t2 += pi * 2;
        ld theta = abs(t2 - t1);
        ans[idx[table[i]]] = abs(pi - theta) / (pi * 2);
    }
    cout << fixed << setprecision(10);
    for(int i = 0; i < n; ++i)  cout << ans[i] << '\n';
}

