		return 0;
	}
	convex_hull(a);
	if(a.size() == 2)
	{
		ans[a[0].id] = 0.5;
		ans[a[1].id] = 0.5;
		for(int i = 0; i < n; ++i)
			cout << fixed << ans[i] << '\n';
		return 0;
	}
	for(int i = 0; i < a.size(); ++i)
	{
		int pre = (i - 1 + a.size()) % a.size();
		int nxt = (i + 1) % a.size();
		pt fi = pt(a[pre].x - a[i].x, a[pre].y - a[i].y);
		pt se = pt(a[nxt].x - a[i].x, a[nxt].y - a[i].y);
		double res = fi.scalar(se);
		double alpha = acos(res / (fi.len() * se.len()));
