double cross(const point &a, const point &b){
    return real(a)*imag(b) - real(b)*imag(a);
}

bool ccw(const point &a, const point &b, const point &c){
    if(a==b || b==c || a==c)
        return false;
    point ba = a-b;
    point bc = c-b;
    return cross(ba,bc) >= 0;
}

double angBtwn(const point &a, const point &b){
    point ab = b-a;
    return arg(ab*point(0,1));
}

void cwSort(int pind){
    point tmp = holes[pind];
    holes[pind] = holes[0];
    holes[0]=tmp;
    point piv = holes[0];
    sort(holes.begin()+1,holes.end(),
            [&](const point& a, const point &b){
                return arg((a-piv)*point(0,1)) > arg((b-piv)*point(0,1));
            });
}


