int quadrant(ll tarx,ll tary,ll basex,ll basey){
  if(basex>=tarx&&basey>=tary)return 3;
  else if(basex>=tarx&&basey<=tary)return 2;
  else if(basex<=tarx&&basey<=tary)return 1;
  else return 4;
}

