inline Point project(Segment s,Point p){
    Vector base=s.p2-s.p1;
    DD r=dot(p-s.p1,base)/base.norm();
    return s.p1+base*r;
}

//線分sを対象軸としたときの、点pの線対称の点
inline Point reflect(Segment s,Point p){
    return p+(project(s,p)-p)*2.0;
}



