//線分と点の距離
inline DD disSP(Segment s,Point p){
    if( dot(s.p2-s.p1,p-s.p1)<0.0 ) return dis(p,s.p1);
    if( dot(s.p1-s.p2,p-s.p2)<0.0 ) return dis(p,s.p2);
