//線分p1-p2と線分p3-p4の交差判定
inline bool intersect(Point p1,Point p2,Point p3,Point p4){
    return(ccwH(p1,p2,p3)*ccwH(p1,p2,p4)<=0 && ccwH(p3,p4,p1)*ccwH(p3,p4,p2)<=0);
}
//線分s1,s2は交差するか？
inline bool intersect(Segment s1,Segment s2){
