template <typename T>
std::vector<std::pair<std::complex<T>, int>> convex_hull(std::vector<std::pair<std::complex<T>, int>> points) {
  std::sort(points.begin(), points.end(), [](const std::pair<std::complex<T>, int>& a, const std::pair<std::complex<T>, int>& b) {
    return (std::real(a.first) < std::real(b.first)) || ((std::real(a.first) == std::real(b.first)) && std::imag(a.first) < std::imag(b.first));
  });
  points.erase(std::unique(points.begin(), points.end()), points.end());

  int n = points.size(), k = 0;
  if (n < 3) return points;
  else {
    auto cross = [](const std::complex<T>& a, const std::complex<T>& b) {
      return std::real(a) * std::imag(b) - std::imag(a) * std::real(b);
    };

    std::vector<std::pair<std::complex<T>, int>> ret(n << 1);
    for (int i = 0; i < n; ret[k++] = points[i++]) {
      while (k >= 2 && cross(ret[k - 1].first - ret[k - 2].first, points[i].first - ret[k - 1].first) <= 0) --k;
    }
    for (int i = n - 2, t = k + 1; i >= 0; ret[k++] = points[i--]) {
      while (k >= t && cross(ret[k - 1].first - ret[k - 2].first, points[i].first - ret[k - 1].first) <= 0) --k;
    }
    ret.resize(k - 1);
    return ret;
  }
}

