inline int ccw(const Point &p, const Point &q, const Point &r){
  Point A,B;
  A=q-p;B=r-p;
  if(cross(A,B)>0) return +1; //ccw
  if(cross(A,B)<0) return -1; //cw
  if(dot(A,B)<0) return +2; //c-a-b
  if(norm(A)<norm(B)) return -2; //a-b-c
  return 0;
}

