	 for(int i=1;i<=n;i++){
	 	while(now>2&&sig(cross(res[now-2],p[i],res[now-1]))>0)now--;
	 	res[now++]=p[i];
	 }
	 int k=now;
	 for(int i=n-1;i>=1;i--){
	 	while(now>k&&sig(cross(res[now-2],p[i],res[now-1]))>0)now--;
	 	res[now++]=p[i];
	 }
	 if(n>1)now--;
	 return now-1;
}

