        return d.first * d.first + d.second * d.second;
    }

    static coord_type dot(difference_type const& a, difference_type const& b) {
        return a.first * b.first + a.second * b.second;
    }

    static coord_type sq_dist(point_type const& p, point_type const& q) {
        return this_type::sq_mag(sub(p, q));
    }

    static coord_type det(difference_type const& a, difference_type const& b) {
        return a.first * b.second - a.second * b.first;
    }

    static coord_type det_of_broken_segment(point_type const& p, point_type const& q, point_type const& r) {
        return this_type::det(this_type::sub(q, p), this_type::sub(r, p));
    }

    static coord_type cosine_of_broken_segment(point_type const& p, point_type const& q, point_type const& r) {
        DEBUG( this_type::dot(this_type::sub(q, p), this_type::sub(r, q)) , this_type::sq_dist(p, q) , this_type::sq_dist(q, r) );
        return this_type::dot(this_type::sub(q, p), this_type::sub(r, q)) / std::sqrt( this_type::sq_dist(p, q) * this_type::sq_dist(q, r) );
    }

    static vec<point_type> lower_convex_hull(vec<point_type> const& v) {
        DEBUG(v);
        if (v.size() <= 1u) return v;
        vec<point_type> hull;
        for (auto&& p: v) {
            while (1u < hull.size()
                && this_type::det_of_broken_segment(hull.at(hull.size()-2), hull.at(hull.size()-1), p) <= coord_type{0})
            {
                hull.pop_back();
            }
            hull.push_back(p);
        }
        DEBUG(hull);
        return hull;
    }

    static vec<point_type> convex_hull(vec<point_type> v) {
        if (v.size() <= 1u) return v;
        // assert(std::is_sorted(v.begin(), v.end(), [](auto&&p, auto&&q) { less(p, q); }));

        auto lower = lower_convex_hull(v);
        std::reverse(v.begin(), v.end());
        auto hull = lower_convex_hull(v);

        lower.pop_back();
        hull.pop_back();
        hull.insert(hull.end(), lower.begin(), lower.end());
        return hull;
    }
};

struct planar_adapter {
    using coord_type = double;
    using point_type = std::tuple<coord_type, coord_type, usize>;

    static coord_type x(point_type const& p) { return std::get<0>(p); }
    static coord_type y(point_type const& p) { return std::get<1>(p); }
};


