            		double c=sqrt((x[j2]-x[i])*(x[j2]-x[i])+(y[j2]-y[i])*(y[j2]-y[i]));
            		double angle=acos((c*c+b*b-a*a)/(2*b*c));
            		double pi= acos(-1);
            		ans[i] = (pi-angle)/(2*pi);
		}
	}
	for(int i=0;i<n;i++){
		cout<<ans[i]<<endl;
	}
	return 0;
}

