template <typename T>
struct vec2d {
    T x, y;
    vec2d() = default;
    vec2d(T _x, T _y)
        : x(_x)
        , y(_y) {}

    vec2d &operator+=(vec2d &v) { 
        x += v.x; 
        y += v.y;
        return *this; 
    }
    vec2d &operator-=(vec2d &v) { 
        x -= v.x; 
        y -= v.y;
        return *this; 
    }
    vec2d &operator+(vec2d &v) { return vec2d(*this) += v; }
    vec2d &operator-(vec2d &v) { return vec2d(*this) -= v; }
    vec2d &operator-() { return vec2d(0, 0) - *this; }

    bool operator<(vec2d &v)  { return (x != v.x ? x < v.x : y < v.y); }
    bool operator>(vec2d &v)  { return (x != v.x ? x > v.x : y > v.y); }
    bool operator==(vec2d &v) { return x == v.x && y == v.y; }
    bool operator<=(vec2d &v) { return !(*this > v); }
    bool operator>=(vec2d &v) { return !(*this < v); }
    bool operator!=(vec2d &v) { return !(*this == v); }

    // 内積, 外積
    T dot(vec2d &v)   { return x * v.x + y * v.y; }
    T cross(vec2d &v) { return x * v.y - y * v.x; }

    double abs() { return hypot(x, y); }
    double cos_between(vec2d &v) { return (double)dot(v) / (abs() * v.abs()); }
};

