double dist(P a, P b){
    return sqrt((a.first - b.first) * (a.first - b.first) + (a.second - b.second) * (a.second - b.second));
}

double argument(P p1, P p2, P p3){
    double a = dist(p1, p3);
    double b = dist(p1, p2);
    double c = dist(p2, p3);
    return pi - acos((b * b + c * c - a * a) / (2 * b * c));
}

