		double mx=-INF;
		int max_i=-1;
		for(int j=1;j<=n;j++){
			double tmp = p[j].x*cos(theta)+p[j].y*sin(theta) ;
			if(mx < tmp){
				mx = tmp;
				max_i = j;
			}
		}
		v[max_i]++;
	}

	for(int i=1;i<=n;i++){
		cout << (double)v[i]/(double)BIN << "\n";
	}

	return 0;
}

