            if(i==j)continue;
            ll x = xy[j][0]-xy[i][0];
            ll y = xy[j][1]-xy[i][1];
            ll res = atan2(y,x);

            if(abs(res)<PI/2){
                p1 = max(p1,res+PI/2);
                m1 = max(m1,-(res-PI/2));
            }else{
                if(res>0){
                    p2 = max(p2,PI-(res-PI/2));
                    m2 = max(m2,-PI+(res+PI/2));                    
                }else{
                    p2 = max(p2,-(PI+(res-PI/2)));
                    m2 = max(m2,PI+(res+PI/2));                    
                }
            }
            p1 = min(p1,PI);
            p2 = min(p2,PI);
            m1 = min(m1,PI);
            m2 = min(m2,PI);
        }
        // std::cout << p1<<" "<<p2<<" "<<m1<<" "<<m2 << std::endl;

        std::cout<<setprecision(20) << (PI-min(p1+p2,PI)+PI-min(m1+m2,PI))/(2*PI) << std::endl;
    }
}

