	friend v2d operator -(const v2d&a,const v2d&b){return v2d{a.x-b.x,a.y-b.y,0};}
	friend double operator |(const v2d&a,const v2d&b){return a.x*b.x+a.y*b.y;}
	friend double operator ^(const v2d&a,const v2d&b){return a.x*b.y-a.y*b.x;}
	friend bool operator <(const v2d&a,const v2d&b){return fabs(a.y-b.y)<eps?a.x<b.x:a.y<b.y;}
};
int sgn(double x){return x<-eps?-1:x>eps;}
std::vector<v2d> p,l;
double ans[101];
int n;
void graham(std::vector<v2d> p,std::vector<v2d>&a)
{
	std::stack<v2d> s1,s2;
	s1.push(p[0]);s2.push(p[0]);s2.push(p[1]);
	for(size_t i=2;i<p.size();++i)
	{
		while(!s1.empty()&&sgn((p[i]-s1.top())^(s2.top()-s1.top()))==-1)
		s1.pop(),s2.pop();
		s1.push(s2.top());s2.push(p[i]);
	}
	for(;!s2.empty();s2.pop())
	a.push_back(s2.top());
}
int main()
{
	scanf("%d",&n);
	for(int i=0;i<n;++i)
	{
		double x,y;scanf("%lf%lf",&x,&y);
		p.push_back(v2d{x,y,i});
	}
	if(n==2)return puts("0.5\n0.5"),0;
	std::sort(p.begin(),p.end());
	graham(p,l);l.pop_back();
	std::reverse(p.begin(),p.end());
	graham(p,l);l.pop_back();
	for(size_t i=0;i<l.size();++i)
	{
		int p=(i+l.size()-1)%l.size(),s=(i+1)%l.size();
		double d=((l[s]-l[i])|(l[p]-l[i]))/((l[s]-l[i]).l()*(l[p]-l[i]).l());
		ans[l[i].p]=acos(-d)/(2.*PI);
	}
	for(int i=0;i<n;++i)printf("%.10f\n",ans[i]);
	return 0;
}

