using point_t = pair<int, int>;

point_t sub(point_t p1, point_t p2) {
  return point_t{p2.first - p1.first, p2.second - p1.second};
}

bool is_zero(point_t p) { return p.first == 0 && p.second == 0; }

vector<double> calc_angles(point_t point, vector<point_t> &points) {
  vector<double> angles;
  for (auto opponent : points) {
    auto diff = sub(opponent, point);
    if (is_zero(diff)) continue;
    auto angle = atan2(diff.second, diff.first) / M_PI * 180;
    angles.push_back(180 + angle);
    angles.push_back(180 - angle);
    angles.push_back(360 - angle);
    angles.push_back(360 + angle);
  }
  SORT(angles);
  return angles;
}

double largest_gap(vector<double> angles) {
  double gap = 0;
  rep(i, angles.size() - 1) gap = max(gap, angles[i + 1] - angles[i]);
  return gap;
}

