	for(int i = 1; i < N; i++){
		long long int a = P[0].first.first; 
		long long int b = P[0].first.second; 
		long long int c = P[i].first.first; 
		long long int d = P[i].first.second; 
		long double e = (double) (c-a) * pow((c-a) * (c-a) + (d-b) * (d-b), -0.5);
		if(e < mn) {
			index = i; mn = e; 
		}
	}
