				long long int f = P[k].first.second; 
				long long int g = (c-a)*(e-c) + (d-b)*(f-d); 
				long long int h = (c-a)*(c-a) + (d-b)*(d-b); 
				long long int l = (e-c)*(e-c) + (f-d)*(f-d); 
				cs[i][j][k] = (long double) g * pow(h * l, -0.5); 
			}
		}
	}
	while(CH.at(CH.size() - 1) != 0){
		int j = CH.at(CH.size() - 1);
		int i = CH.at(CH.size() - 2); 
		long double mx = -2.0; 
		int index = 0; 
		for(int k = 0; k < N; k++){
			if(i == k || j == k) continue;
			if(mx < cs[i][j][k]){
				index = k; mx = cs[i][j][k];
			} 
		}
		CH.push_back(index); 
