	for(int i = 1; i < CH.size() - 1; i++){
		ans[taiou[CH[i]]] = cs[CH[i-1]][CH[i]][CH[i+1]]; 
	}
	ans[taiou[CH[0]]] = cs[CH[CH.size()-2]][CH[0]][CH[1]]; 
