llint ccw(const point& a, const point& b, const point& c)
{
	return (b.x - a.x) * (c.y - a.y) - (c.x - a.x) * (b.y - a.y);
}

int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(nullptr);

	int n, m, i;
	double sum = 0;

	cin>>n;

	for (i = 0; i < n; ++i)
	{
		cin>>arr[i].first.x>>arr[i].first.y;
		arr[i].second = i;
	}
	sort(arr, arr + n);
	for (i = 0; i < n; ++i)
	{
		_pos[i] = arr[i].second;
		points[i] = arr[i].first;
	}

	vector<point> hull;
	for (i = 0; i < n; ++i)
	{
		while (hull.size() >= 2 && ccw(hull[hull.size() - 2], hull[hull.size() - 1], points[i]) < 0)
			hull.pop_back();
		pos[hull.size()] = i;
		hull.push_back(points[i]);
//		cout<<i<<' '<<hull.size()<<'\n';
	}
	m = hull.size();
	for (i = n - 2; i > 0; --i)
	{
		while (hull.size() >= 2 && hull.size() > m && ccw(hull[hull.size() - 2], hull[hull.size() - 1], points[i]) < 0)
			hull.pop_back();
		pos[hull.size()] = i;
		hull.push_back(points[i]);
//		cout<<i<<' '<<hull.size()<<'\n';
	}
	while (hull.size() >= 3 && hull.size() > m && ccw(hull[hull.size() - 2], hull[hull.size() - 1], points[0]) < 0)
		hull.pop_back();
	m = hull.size();

//	cout<<m<<'\n';

	for (i = 0; i < m; ++i)
	{
		point& a = hull[(i + m - 1) % m];
		point& b = hull[(i + 1) % m];
		double p = atan2(-(hull[i].x - a.x), hull[i].y - a.y);
		double q = atan2(-(b.x - hull[i].x), b.y - hull[i].y);
		double r = q - p;
		while (r < 0)
			r += 2 * pi;
		while (r >= 2 * pi)
			r -= 2 * pi;
//		cout<<points[i].x<<' '<<points[i].y<<' '<<p<<' '<<q<<' '<<r<<'\n';
		sol[_pos[pos[i]]] = r;
		sum += r;
	}

//	print:
	for (i = 0; i < n; ++i)
		cout<<fixed<<setprecision(8)<<sol[i] / sum<<'\n';
}

