struct GrahamScan {
  vector<Point> points;
  VI ids;
  VI hull;

  void add(Point p) {
    points.PB(p);
  }

  int operator[](int i) {
    return hull[i];
  }

  void scan() {
    int n = points.size();
    ids.resize(n);

    iota(ALL(ids), 0);
    sort(ALL(ids), [&](int a, int b) {
        return make_pair(points[a].X, points[a].Y) <
        make_pair(points[b].X, points[b].Y);
        });

    sort(begin(ids) + 1, end(ids), [&](int a, int b) {
        Point p1 = points[a] - points[ids[0]];
        Point p2 = points[b] - points[ids[0]];
        // p1.y / p1.x < p2.y / p2.x
        double ev = p1.Y * p2.X - p2.Y * p1.X;
        return abs(ev) < EPS ? norm(p1) < norm(p2) : ev < 0;
        });

    hull.PB(ids[0]);
    dump(ids);
    FORI(i, 1, n) {
      int ii = i%n;
      int st;
      while(hull.size() >= 2 &&
          (st = ccw(
                    points[hull[hull.size()-2]],
                    points[hull[hull.size()-1]],
                    points[ids[ii]]
                   ), st == -1)) hull.pop_back();
      dump(i, hull);
      hull.PB(ids[ii]);
      dump( hull);
    }

    hull.pop_back();
  }
};

