const int MAXN = (1 << 20);
const double dinf = (double)1e17;
const double eps = 0.00000000000001;
const double PI = acos(-1);

struct point
{
	double x, y;
	point() {x = 0; y = 0;}
	point(double _x, double _y)
	{
		x = _x;
		y = _y;
	}
};

bool cmp(point a, point b)
{
	if(a.x == b.x) return a.y < b.y;
	return a.x < b.x;
}

double slope(point a, point b)
{
	double deltax = b.x - a.x;
	double deltay = b.y - a.y;
	if(max(-deltax, deltax) < eps) return (((deltax < 0) ? (-1) : 1) * deltay < 0) ? (-dinf) : (dinf);

	return deltay / deltax; 
}

struct convex_hull
{
	vector<point> st;
	convex_hull() {st.clear();}

	void compute_hull(vector<point> vec)
	{
		sort(vec.begin(), vec.end(), cmp);

		for(int i = 0; i < (int)vec.size(); i++)
		{
			while(st.size() >= 2 && slope(st[st.size() - 2], vec[i]) >= slope(st[st.size() - 2], st[st.size() - 1])) 
				st.pop_back();
			st.push_back(vec[i]);
		}

		st.pop_back();
		int k = st.size();

		for(int i = vec.size() - 1; i >= 0; i--)
		{
			while(st.size() - k >= 2 && slope(vec[i], st[st.size() - 2]) >= slope(st[st.size() - 1], st[st.size() - 2]))
				st.pop_back();
			st.push_back(vec[i]);
		}

		st.pop_back();
	}
};

int n;
int64_t x[MAXN], y[MAXN];

vector<point> li;
map<pair<double, double>, int> idx;

void read()
{
	cin >> n;
	for(int i = 0; i < n; i++)
	{
		cin >> x[i] >> y[i];
		li.push_back(point(x[i], y[i]));
		idx[{x[i], y[i]}] = i;
	}
}

convex_hull ch;
double ans[MAXN];

point mns(point a, point b) { return point(a.x - b.x, a.y - b.y); }

double ang(point l, point mid, point r)
{
	l = mns(l, mid);
	r = mns(r, mid);

	double f = atan2(l.y, l.x), s = atan2(r.y, r.x);
	if(s < 0) s += 2 * PI;
	if(f < 0) f += 2 * PI;

	double ret = s - f;
	if(f > s) ret = 2 * PI - f + s;

	chkmin(ret, 2 * PI - ret);
	return ret;
}

void solve()
{
	ch.compute_hull(li);

	double sum = 2 * PI;
	for(int i = 0; i < (int)ch.st.size(); i++)
	{
		int prv = (i - 1 + ch.st.size()) % ch.st.size();
		int nxt = (i + 1 + ch.st.size()) % ch.st.size();

		double angle = PI - ang(ch.st[prv], ch.st[i], ch.st[nxt]);
		ans[idx[make_pair(ch.st[i].x, ch.st[i].y)]] += angle;
	}

	for(int i = 0; i < n; i++)
		cout << setprecision(9) << fixed << (ans[i] / sum) << endl;
}

int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);

	read();
	solve();
	return 0;
}

