struct Point {
	double x, y;
	Point() {}
	Point( double x, double y ):
		x(x), y(y) {}
	Point operator+( const Point &rhs ) const {
		return Point( x+rhs.x, y+rhs.y );
	}
	Point operator-( const Point &rhs ) const {
		return Point( x-rhs.x, y-rhs.y );
	}
	Point operator*( double rhs ) const {
		return Point( x*rhs, y*rhs );
	}
	Point operator/( double rhs ) const {
		return Point( x/rhs, y/rhs );
	}
	bool operator==( const Point &rhs ) const {
		return dcmp(x-rhs.x) == 0 && dcmp(y-rhs.y) == 0;
	}
	bool operator<( const Point &rhs ) const {
		if( dcmp(x-rhs.x) == 0 )
			return y < rhs.y;
		return x < rhs.x;
	}
};
typedef Point Vector;

double Cross( Vector v, Vector w ) {
	return v.x * w.y - v.y * w.x;
}
double Dot( Vector v, Vector w ) {
	return v.x * w.x + v.y * w.y;
}
double Length( Vector v ) {
	return sqrt(v.x * v.x + v.y * v.y);
}
double Angel( Vector v, Vector w ) {
	return acos(Dot(v, w) / Length(v) / Length(w));
}

int n, m;
Point P[N], Q[N], t[N];

void ConvexHull() {
	for( int i = 0; i < n; ++i )
		t[i] = P[i];
	sort(t, t+n), m = 0;
	for( int i = 0; i < n; ++i ) {
		while( m > 1 && Cross( Q[m-1]-Q[m-2], t[i]-Q[m-2] ) <= 0 ) --m;
		Q[m++] = t[i];
	}
	int k = m;
	for( int i = n-2; i >= 0; --i ) {
		while( m > k && Cross( Q[m-1]-Q[m-2], t[i]-Q[m-2] ) <= 0 ) --m;
		Q[m++] = t[i];
	}
	--m;
}

