double query( Point P ) {
	for( int i = 0; i < m; ++i )
		if( P == Q[i] ) {
			Point A = Q[(i+1)%m];
			Point B = Q[(i-1+m)%m];
			double ang = PI - Angel(A-P, B-P);
			return ang/PI/2;
		}
	return 0;
}
