        - (points[hull[(i+m-1)%m]] - points[hull[i]]),
        points[hull[(i+1)%m]] - points[hull[i]]
        ) / 2.0 / PI;
  }

  cout << setprecision(6);
  REP(i, n) cout << ans[i] << endl;
}

