		ok1 = ok2 = ok3 = ok4 = 0;
		FOR(j, 0, n)
		{
			if (i == j)
				continue;
			if (a[j].X >= a[i].X && a[j].Y >= a[i].Y)
				++ok1;
			if (a[j].X >= a[i].X && a[j].Y <= a[i].Y)
				++ok2;
			if (a[j].X <= a[i].X && a[j].Y >= a[i].Y)
				++ok3;
			if (a[j].X <= a[i].X && a[j].Y <= a[i].Y)
				++ok4;
		}

		if (ok1 && ok2 && ok3 && ok4)
			continue;

		LD res = 0;
		FOR(j, 0, n)
		{
			FOR(k, 0, n)
			{
				if (i == j || i == k || j == k)
					continue;

				LD ij = dist(a[i], a[j]);
				LD ik = dist(a[i], a[k]);
				LD jk = dist(a[j], a[k]);
				LD kut = (ij*ij + ik * ik - jk * jk) / (2.0*ij*ik);
				kut = acos(kut);
				res = max(res, kut);
			}
		}

		ans[i] = (PI - res) / (2.0*PI);
	}



	FOR(i, 0, n)
		cout << fixed << setprecision(10) << ans[i] << endl;
	cin >> n;
	return 0;
}

