			double rad = atan2(-dx, dy);
			while(rad < 0) rad += 2 * PI;
			if(rad >= PI) rad -= PI;
			assert(0 <= rad && rad < PI);
			if(rad1 < rad2){
				ls.push_back({ rad, i, j });
				ls.push_back({ rad + PI, j, i });
			}
			else{
				ls.push_back({ rad, j, i });
				ls.push_back({ rad + PI, i, j });
			}
		}
	}
	sort(ls.begin(), ls.end());

	double r = 0;
	int cnt[100] = { 0 };
	for(auto l : ls){
		if(l.rad >= PI) continue;
		cnt[l.A]++;
	}

	for(auto l : ls){
		{
			int idx = max_element(cnt, cnt + N) - cnt;
			double diff = abs(r - l.rad);
			sum[idx] += diff;
		}

		cnt[l.A]--;
		cnt[l.B]++;
		r = l.rad;
	}
	{
		int idx = max_element(cnt, cnt + N) - cnt;
		double diff = 2 * PI - r;
		sum[idx] += diff;
	}

	for(int i = 0; i < N; i++){
		cout << fixed << setprecision(15) << sum[i] / (2 * PI) << endl;
	}
}

