double norm(double r){
	while(r>PI)r-=PI*2;
	while(r<-PI)r+=PI*2;
	return r;
}
bool in(double l,double r,double k){
	if(l<=r)return k>=l&&k<=r;
	return k<=r||k>=l;
}

struct node{
	double l,r;
	bool use;
	node(){
		use=false;
		l=r=0;
	}
	bool And(double s,double t){
		s=norm(s);t=norm(t);
		if(fabs(s-r)<eps&&fabs(t-l)<eps)return false;
		if(!use)return (l=s,r=t,use=true);
		if(in(l,r,s)&&in(l,r,t))return (l=s,r=t,true);
		if(in(s,t,l)&&in(s,t,r))return true;
		if(in(l,r,s)&&in(s,t,r))return (l=s,true);
		if(in(s,t,l)&&in(l,r,t))return (r=t,true);
		return false;
	}
	double part(){
		if(!use)return 1;
		double t=r-l,v=2*PI;
		return (t<0?t+v:t)/v;
	}
};

