ld ans[N];

bool cmp(int i, int j)
{
	return pii(x[i], y[i]) < pii(x[j], y[j]);
}

pii pos(int id)
{
	return pii(x[id], y[id]);
}

ll cross(pii A, pii B, pii C)
{
	return 1LL * (B.F - A.F) * (C.S - B.S) - 1LL * (B.S - A.S) * (C.F - B.F);
}

ll dot(pii A, pii B, pii C)
{
	return 1LL * (B.F - A.F) * (C.F - B.F) + 1LL * (B.S - A.S) * (C.S - B.S);
}

ld dis(pii A, pii B)
{
	return sqrt(1LL * (A.F - B.F) * (A.F - B.F) + 1LL * (A.S - B.S) * (A.S - B.S));
}

