		int id = perm[i];
		if(sz >= 2 && cross(pos(p[sz - 2]), pos(p[sz - 1]), pos(id)) <= 0)sz --;
		p[sz ++] = id;
	}

	int len = sz;

	for(int i=1; i<n; i++)
	{
		int id = perm[i];
		while(sz > len && cross(pos(p[sz - 2]), pos(p[sz - 1]), pos(id)) <= 0) sz --;
		p[sz ++] = id;
	}

	sz --;

	for(int i=0; i<sz; i++)
	{
		int j = (i + 1) % sz, k = (i + 2) % sz;
		ll value = dot(pos(p[i]), pos(p[j]), pos(p[k]));
		ld dis1 = dis(pos(p[i]), pos(p[j])), dis2 = dis(pos(p[j]), pos(p[k]));
