double cos_(int x1, int y1, int x2, int y2, int x3, int y3)
{
        double ax = x1 - x2;
        double ay = y1 - y2;
        double bx = x3 - x2;
        double by = y3 - y2;
        return (ax * bx + ay * by) /
                (sqrt(ax * ax + ay * ay) * sqrt(bx * bx + by * by));
}

std::vector<double> agc021b(int N, const std::vector<int> & X,
        const std::vector<int> & Y)
{
        std::vector<double> r;
        if (N == 2) {
                r.push_back(0.5);
                r.push_back(0.5);
                return r;
        }

        std::vector<int> ois;
        std::set<int> ot;

        int left_i = 0;
        for (int i = 1; i < N; i++) {
                if (X[i] < X[left_i])
                        left_i = i;
        }

        int first_i = left_i;
        ois.push_back(first_i);
        ot.insert(first_i);
        int curr_i = first_i;
        int prev_x = X[curr_i];
        int prev_y = Y[curr_i] - 1;
        //std::cerr << "first_i: "<< first_i << " " << X[first_i] << " " << Y[first_i] << std::endl;
        for (;;) {
                int next_i = -1;
                for (int i = 0; i < N; i++) {
                        if (i == curr_i)
                                continue;
                        //if (ot.find(i) != ot.end())
                        //      continue;
                        if (next_i < 0) {
                                next_i = i;
                                continue;
                        }
                        if (cos_(prev_x, prev_y, X[curr_i], Y[curr_i], X[i], Y[i]) <
                                cos_(prev_x, prev_y, X[curr_i], Y[curr_i], X[next_i], Y[next_i]))
                        {
                                next_i = i;
                        }
                }
                //if (next_i == first_i)
                //      break;
                if (ot.find(next_i) != ot.end()) {
                        //std::cerr << "drop: " << next_i << std::endl;
                        break;
                }
                //std::cerr << "next_i: "<< next_i << " " << X[next_i] << " " << Y[next_i] << std::endl;
                prev_x = X[curr_i];
                prev_y = Y[curr_i];
                curr_i = next_i;
                ois.push_back(next_i);
                ot.insert(next_i);
        }
        ois.push_back(ois[0]);
        ois.push_back(ois[1]);

        r.resize(N);
        for (int i = 0; i < N; i++)
                r[i] = 0.0;

        for (int i = 1; i < (int)ois.size()-1; i++) {
                double c = cos_(X[ois[i-1]], Y[ois[i-1]], X[ois[i]], Y[ois[i]],
                        X[ois[i+1]], Y[ois[i+1]]);
                //std::cerr << i << " ";
                //std::cerr << ois[i] << " " << c << " " << acos(c) << std::endl;
                double a = (PI - acos(c)) / PI2;
                r[ois[i]] = a;
        }

        double s = 0.0;
        for (int i = 0; i < N; i++)
                s += r[i];

        //std::cerr << "sum: " << s << " (must be 1.0)" << std::endl;

        return r;
}

