void solve(){
	int q = Q;
	while(q--) {
		ll x = getrand();
		ll y = getrand();
		ll d = INF;
		int b = -1;
		fi(1, n) {
			ll d0 = getdist(::x[i], ::y[i], x, y);
			if (d0 < d) {
				d = d0;
				b = i;
			}						
		}
		//++cnt[b];
		p[b].pb(mp(x, y));
	}							
	fi(1, n) {
		convex_hull(p[i]);
	}
	ld sum = 0;
	fi(1, n) {
		S[i] = getarea(p[i]);
		sum += S[i];
	}
	fi(1, n) {
		ans[i] = S[i] / sum;
	}
	/*fi(1, n) {
		ans[i] = (ld) cnt[i] / Q;
	}*/
}

