const ld pi=acos(-1);
const ld eps=5e-10;
inline int read(){
	reg int x=0,f=1;reg char ch=getchar();
	for(;!isdigit(ch);f=ch=='-'?-1:1,ch=getchar());
	for(;isdigit(ch);x=(x<<3)+(x<<1)+(ch^48),ch=getchar());
	return x*f;
}
struct vec{
	ll x,y;int id;
	friend vec operator+(vec a,vec b){return (vec){a.x+b.x,a.y+b.y};}
	friend vec operator-(vec a,vec b){return (vec){a.x-b.x,a.y-b.y};}
	friend ld operator*(vec a,vec b){return a.x*b.x+a.y*b.y;}
	friend ld operator/(vec a,vec b){return a.x*b.y-a.y*b.x;}
	ld abs(){return sqrt(x*x+y*y);}
}P[105];
inline bool cmp(vec a,vec b){
	return a.x==b.x?a.y<b.y:a.x<b.x;
}
int n,t,q[105];
ld ans[105];
int main(){
	n=read();
	for(reg int i=1;i<=n;i++)P[i].x=read(),P[i].y=read(),P[i].id=i;
	std::sort(P+1,P+1+n,cmp);
	for(reg int i=1;i<=n;i++){
		while(t>1&&cal(P[q[t-1]],P[q[t]],P[i])<eps)t--;
		q[++t]=i;
	}
	reg int lt=t;
	for(reg int i=n-1;i;i--){
		while(t>lt&&cal(P[q[t-1]],P[q[t]],P[i])<eps)t--;
		q[++t]=i;
	}
	t--;
	for(reg int i=1;i<=t;i++){
		reg vec a=P[q[pre(i)]]-P[q[i]],b=P[q[suf(i)]]-P[q[i]];
		reg ld thita=(a*b)/(a.abs()*b.abs());
		ans[P[q[i]].id]=acos(-thita)/(2.0*pi);
	}
	for(reg int i=1;i<=n;i++)printf("%.20lf\n",(double)(ans[i]+eps));
	return 0;
