#include<bits/stdc++.h>
using namespace std;
typedef complex<double> point;

point anchor;
constexpr int MX_N=101;
int N;
point vertices[MX_N];
point usvertices[MX_N];

double dist(const point& a, const point& b){
    return abs(a-b);
}

int cross(const point& a, const point& b){
    return real(a)*imag(b) - imag(a)*real(b);
}

bool angleCmp(const point& a, const point& b){
    point relA = a-anchor;
    point relB = b-anchor;
    if(cross(relA,relB)==0)
        return dist(a,anchor) < dist(b,anchor);
    return arg(relA) < arg(relB);
}

bool ccw(const point& a,const point& b, const point& c){
    if(a==b || b==c || a==c)
        return false;
    point u = b-c;
    point v = b-a;
    int cr = cross(u,v);
    return cr > 0;
}

int main(){
    scanf("%d",&N);
    double x,y;
    for(int i = 0; i < N; i++){
        scanf("%lf %lf",&x,&y);
        usvertices[i] = vertices[i]=point(x,y);
    }
    int pos = 0;
    for(int i = 0; i < N; i++)
        if(imag(vertices[i]) < imag(vertices[pos]) ||
                (imag(vertices[i])==imag(vertices[pos]) &&
                (real(vertices[i]) > real(vertices[pos]))))
            pos = i;
    point _tp = vertices[0];
    vertices[0] = vertices[pos];
    vertices[pos] = _tp;
    anchor = vertices[0];
    sort(vertices+1,vertices+N, angleCmp);
    vector<point> hull;
    hull.push_back(vertices[N-1]);
    hull.push_back(vertices[0]);
    hull.push_back(vertices[1]);
    for(int i = 2; i < N;){
        int t = hull.size();
        if(ccw(hull[t-2],hull[t-1],vertices[i]))
            hull.push_back(vertices[i++]);
        else
            hull.pop_back();
    }
    hull.pop_back();
    int h = hull.size();
    double out[h];
    for(int i = 0;i < h; ++i){
        //a -> b -> c
        point a = hull[(h+(i-1))%h];
        point b = hull[i];
        point c = hull[(i+1)%h];
        //printf("(%lf,%lf)->(%lf,%lf)->(%lf,%lf)\n",real(a),imag(a),real(b),imag(b),real(c),imag(c));
        point ab = (b-a)*point(0,1);
        point cb = (b-c)*point(0,-1);
        //printf("ab:(%lf,%lf) cb:(%lf,%lf)\n",real(ab),imag(ab),real(cb),imag(cb));
        double ang = abs(arg(ab)-arg(cb))/(2*M_PI);
        //printf("(%lf,%lf):%lf\n",real(b),imag(b),min(1-ang,ang));
        out[i] = min(1-ang,ang);
    }
    for(int i = 0; i < N; ++i){
        bool in = false;
        for(int j = 0; j < h;++j){
            if(hull[j]==usvertices[i]){
                in = true;
                printf("%.8lf\n",out[j]);
                break;
            }
        }
        if(!in)
            puts("0");
    }
    return 0;
}

