double normalize(double theta) {
    while (theta > 2 * PI) { theta -= 2 * PI; }
    while (theta < 0) { theta += 2 * PI; }
    return theta;
}
using P = pair<double, double>;
vector<P> merge(vector<P> a, vector<P> b) {
    vector<pair<double, int>> ps;
    for (P p:a) { ps.emplace_back(make_pair(p.first, 0)), ps.emplace_back(p.second, 0); }
    for (P p:b) { ps.emplace_back(make_pair(p.first, 1)), ps.emplace_back(p.second, 1); }
    sort(all(ps));
    double start;
    bool fa = false, fb = false;
    vector<P> ret;
    for (auto p:ps) {
        if (p.second == 0) {
            fa = !fa;
            if (fa && fb) { start = p.first; }
            if (!fa && fb) { ret.emplace_back(P(start, p.first)); }
        } else {
            fb = !fb;
            if (fa && fb) { start = p.first; }
            if (fa && !fb) { ret.emplace_back(P(start, p.first)); }
        }
    }
    return ret;
}
