    for (int i = 0; i < 2; i++) cout << 0.5 << endl;
    return 0;
  }
  vector<P> ch { convex_hull(ps) };
  int M { (int)ch.size() };
  for (int i = 0; i < N; i++) {
    bool is_zero { true };
    int pv;
    for (int j = 0; j < M; j++) {
      pv = j;
      if (ps[i] == ch[j]) {
        is_zero = false;
        break;
      }
    }
    if (is_zero) {
      cout << 0.0 << endl;
    } else {
      P p { ch[pv] };
      P q { ch[(pv - 1 + M) % M] };
      P r { ch[(pv + 1) % M] };
      ld pi { acos(-1) };
      ld th { arg(r - p) - arg(q - p) };
      cout << fixed << setprecision(7) << (pi + th) / (2.0 * pi) << endl;
    }
  }
  return 0;
}

