    long double px1 = (1.0 * x[poz] + x[poz - 1]) / 2, py1 = (1.0 * y[poz] + y[poz - 1]) / 2,
           px2 = (1.0 * x[poz] + x[poz + 1]) / 2, py2 = (1.0 * y[poz] + y[poz + 1]) / 2;

    px1 -= x[poz];
    px2 -= x[poz];
