    uniform_real_distribution<double> rnd_y1(-1e12, -1e11);
    uniform_real_distribution<double> rnd_y2(1e11, 1e12);


    for (int i = 0; i < s; i++) {

        switch (i % 4) {
        case 0:
            x = rnd_x1(mt);
            y = rnd_y1(mt);
            break;
        case 1:
            x = rnd_x1(mt);
            y = rnd_y2(mt);
            break;
        case 2:
            x = rnd_x2(mt);
            y = rnd_y1(mt);
            break;
        case 3:
            x = rnd_x2(mt);
            y = rnd_y2(mt);
            break;
        }
        indx = 0;

        r = 1e32;
        for (int j = 0; j < n; j++) {
            double R = hypot(x - px[j], y - py[j]);

            if (R < r) {
                indx = j;
                r = R;
            }
        }

        cnt[indx]++;
    }

    for (int i = 0; i < n; i++) {
        printf("%.*lf\n", DBL_DIG, (double)cnt[i] / (double)s);
    }

    return 0;
}

