ld fix(ld x){
	if(x<0)x+=PI*2;
	if(x>PI*2)x-=PI*2;
	return x;
}

int vi[maxn];

ld hs[maxn];int cnt;

void Work(){
	REP(i,1,n){
		cnt=0;
		REP(j,1,n)if(i!=j){
			ld _x=fix(atan2(y[j]-y[i],x[j]-x[i]));
			_x=fix(_x+PI/2);
			ld y=fix(_x+PI);
			hs[++cnt]=_x;hs[++cnt]=y;
		}
		sort(hs+1,hs+cnt+1);cnt=unique(hs+1,hs+cnt+1)-hs-1;
		REP(j,1,cnt)vi[j]=0;
//		REP(j,1,cnt)cout<<hs[j]<<' ';cout<<endl;
		REP(j,1,n)if(i!=j){
			ld _x=fix(atan2(y[j]-y[i],x[j]-x[i]));
			_x=fix(_x+PI/2);
			ld y=fix(_x+PI);
			int xx=LB(hs+1,hs+cnt+1,_x)-hs;
			int yy=LB(hs+1,hs+cnt+1,y)-hs;
			while(xx!=yy){
				vi[xx]=1;
				xx++;if(xx>cnt)xx=1;
			}
		}
		double ans=0;
		REP(j,1,cnt)if(!vi[j])if(j==cnt)ans+=fix(hs[1]-hs[j]);else ans+=fix(hs[j+1]-hs[j]);
		printf("%.15lf\n",ans/PI/2);
	}
}

