using i64 = int64_t;
template<class T> // [pair<Num, Num>]
vector<int> convex_hull(const T& ps) {
    vector<int> res;
    int i = min_element(begin(ps), end(ps)) - begin(ps);
    do {
        cerr << i << endl;
        res.push_back(i);
        int j = (i + 1) % ps.size();
        for (int k = 0; k < ps.size(); ++k) {
            if (k == i) continue;
            auto xi = ps[i].first, yi = ps[i].second,
                xj = ps[j].first - xi, yj = ps[j].second - yi,
                xk = ps[k].first - xi, yk = ps[k].second - yi;
            auto prod = xk * yj - xj * yk;

            // without points on lines
            if (prod > 0 || 
                (prod == 0 && xj * xj + yj * yj < xk * xk + yk * yk)) {
                j = k;
            }
        }
        i = j;
    } while (i != res.front());
    return res;
}
i64 n;
vector<pair<i64, i64>> ps;
int main() {
    cin >> n;
    ps.resize(n);
    for (int i = 0; i < n; ++i) {
        cin >> ps[i].first >> ps[i].second;
    }
    auto ch = convex_hull(ps);
    int m = ch.size();
    vector<double> res(n);
    double PI = acos(-1);
    for (int i = 0; i < m; ++i) {
        int pi = ch[i], ci = ch[(i - 1 + m) % m], ai = ch[(i + 1) % m];
        auto p = ps[pi], q = ps[ci], r = ps[ai];
        double f = atan2(double(q.second - p.second), double(q.first - p.first)),
               g = atan2(double(r.second - p.second), double(r.first - p.first));

        if (f > g) g += 2 * PI;
        // cerr << (f / PI * 180) << '\t' << (g / PI * 180) << endl;
        double a = g - f - PI;
        res[pi] = abs(a / (2.0 * PI));
    }
    for (int i = 0; i < n; ++i) {
        printf("%.10f\n", res[i]);
    }
    return 0;
}

