	Point operator+(Point p){return Point(x+p.x,y+p.y);}
	Point& operator+=(Point p){x+=p.x; y+=p.y; return *this;}
	Point operator-(Point p){return Point(x-p.x,y-p.y);}
	Point& operator-=(Point p){x-=p.x; y-=p.y; return *this;}
	Point operator*(double k){return Point(k*x,k*y);}
	Point& operator*=(double k){x*=k; y*=k; return *this;}
	Point operator/(double k){return Point(x/k,y/k);}
	Point& operator/=(double k){x/=k; y/=k; return *this;}
	double norm2(){return x*x+y*y;}
	double norm(){return sqrt(norm2());}
};
bool comp_x(const Point &a,const Point &b){
	if(a.x!=b.x)return a.x<b.x;
	return a.y<b.y;
}
bool comp_y(const Point &a,const Point &b){
	if(a.y!=b.y)return a.y<b.y;
	return a.x<b.x;
}
double cross(Point a,Point b){
	return a.x*b.y-a.y*b.x;
}
double dot(Point a,Point b){
	return a.x*b.x+a.y*b.y;
}
int ccw(Point a,Point b,Point c){
	b-=a,c-=a;
	if(cross(b,c)>EPS)return +1;    //COUNTER_CLOCKWISE
	if(cross(b,c)<-EPS)return -1;   //CLOCKWISE
	if(dot(b,c)<-EPS)return +2;     //ONLINE_BACK
	if(b.norm()<c.norm())return -2; //ONLINE_FRONT
	return 0;                       //ON_SEGMENT
}

//a-b-c no kaku de tiisaihou
double get_angle(Point a,Point b,Point c){
	Point p=a-b,q=c-b;
	double v=atan2(p.y,p.x),w=atan2(q.y,q.x);
	double t=fabs(v-w);
	return min(t,2.0*PI-t);
}
vector<Point>convex_hull(vector<Point>p){
	sort(p.begin(),p.end(),comp_x);
	int n=p.size(),k=0;
	vector<Point>res(n*2);
	for(int i=0;i<n;i++){
		while(k>1&&ccw(res[k-2],res[k-1],p[i])<0)k--;
		res[k++]=p[i];
	}
	for(int i=n-2,t=k;i>=0;i--){
		while(k>t&&ccw(res[k-2],res[k-1],p[i])<0)k--;
		res[k++]=p[i];
	}
	res.resize(k-1);
	return res;
}
