			auto &b = P[S[(i + sz - 1) % sz]];
			auto &c = P[S[(i + 1) % sz]];
			double ax = b.x - a.x, ay = b.y - a.y;
			double bx = c.x - a.x, by = c.y - a.y;
			sm += acos((ax*bx + ay*by) / hypot(ax, ay) / hypot(bx, by));
			ans[a.i] = (pi - acos((ax*bx+ay*by)/hypot(ax,ay)/hypot(bx,by))) / pi / 2;
		}
	}

	for (int i = 0; i<N; i++) printf("%.12lf\n", ans[i]);

	return 0;
}

