struct Matrix2x2 {

	vvll mat;
	vvll mat_initial;
	ll A, B;
	ll mod;
	vvll identity;

	Matrix2x2(ll A, ll B, ll mod) :A(A), B(B), mod(mod) {
		mat.resize(2, vll(2));
		mat[0][0] = A; mat[0][1] = B;
		mat[1][0] = 0; mat[1][1] = 1;
		mat_initial = mat;
		identity.resize(2, vll(2));
		identity[0][0] = 1; identity[0][1] = 0;
		identity[1][0] = 0; identity[1][1] = 1;
	}

	vvll mul(vvll& c, vvll& d) {
		vvll e(2, vll(2));
		rep(i, 2) {
			rep(k, 2) {
				rep(j, 2) {
					e[i][j] = (e[i][j] + c[i][k] * d[k][j]) % mod;
				}
			}
		}
		return e;
	}

	vvll pow(ll n) {
		if (n == 0)return identity;
		if (n == 1)return mat;
		if (n % 2 == 0) {
			vvll tmp = pow(n / 2);
			mat = mul(tmp, tmp);
		}
		else {
			vvll tmp = pow(n - 1);
			mat = mul(tmp, mat_initial);
		}
		return mat;

	}

