#define REP(i,n) for(int i=0;i<(n);++i)

std::vector<std::pair<int,int>> convex_hull(std::vector<std::pair<int,int>> P){
    int N=P.size();
    if(N<=1){
        return P;
    }
    std::vector<std::pair<int,int>> H,L,R;
    sort(P.begin(),P.end());

    //L
    for(int i=0;i<P.size();i++){
        int j=L.size();
        while(j>=2 && (L[j-1].first-L[j-2].first)*(P[i].second-L[j-2].second)<=(L[j-1].second-L[j-2].second)*(P[i].first-L[j-2].first)){
            L.pop_back();
            j--;
        }
        L.push_back(P[i]);
    }

    //H
    for(int i=P.size()-1;i>=0;i--){
        int j=H.size();
        while(j>=2 && (H[j-1].first-H[j-2].first)*(P[i].second-H[j-2].second)<=(H[j-1].second-H[j-2].second)*(P[i].first-H[j-2].first)){
            H.pop_back();
            j--;
        }
        H.push_back(P[i]);
    }


    R=L;
    for(int i=1;i<H.size()-1;i++){
        R.push_back(H[i]);
    }

    //REP(i,L.size()){cout << L[i].first <<" "<< L[i].second << endl;}cout << endl;
    //REP(i,H.size()){cout << H[i].first <<" "<< H[i].second << endl;}cout << endl;

    //REP(i,R.size()){cout << R[i].first <<" "<< R[i].second << endl;}

    return R;
}


