        P.push_back({x,y});
        M[{x,y}]=i;
    }
    P=convex_hull(P);
    //REP(i,P.size()){cout << P[i].first <<" "<< P[i].second << endl;}

    P.push_back(P[0]);
    double angle[114]={};
    REP(i,P.size()-1){
        double t=atan2(-(P[i+1].first-P[i].first),(P[i+1].second-P[i].second));
        angle[i]=t;
