P getCP(P p1,P p2){
	P mip=(p1+p2)/2.0;
	P tmp=p1-p2;
	P dir=P(-tmp.y,tmp.x,-1);
	double l=0.0,r=1e100;
	for(int i=0;i<10000;i++){
		double mid=(l+r)/2;
		if(pow(mip.x+dir.x*mid,2)+pow(mip.y+dir.x*mid,2)<=1e100)l=mid;
		else r=mid;
	}
	return P(mip.x+dir.x*l,mip.y+dir.y*l,-1);
}

