}

bool cw(pii a, pii b, pii c) {
     return a.x * (b.y - c.y) + b.x * (c.y - a.y) + c.x * (a.y - b.y) < 0;
}

bool ccw(pii a, pii b, pii c) {
     return a.x * (b.y - c.y) + b.x * (c.y - a.y) + c.x * (a.y - b.y) > 0;
}


vector<pair<pii, int>> convex_hull(vector<pair<pii, int>> d) {
     sort(d.begin(), d.end(), cmp);

     auto p1 = d[0];
     auto p2 = d.back();
     vector<pair<pii, int>> up;
     vector<pair<pii, int>> down;
     up.push_back(p1);
     down.push_back(p2);

     for (int i = 1; i < (int)d.size(); ++i) {
          if (i == (int)d.size() - 1 || cw(p1.first, d[i].first, p2.first)) {
               while (up.size() > 1 && !cw(up[up.size() - 2].first, up.back().first, d[i].first)) {
                    up.pop_back();
               }
               up.push_back(d[i]);
          }
          if (i == d.size() - 1 || ccw(p1.first, d[i].first, p2.first)) {
               while (down.size() > 1 && !ccw(down[down.size() - 2].first, down.back().first, d[i].first)) {
                    down.pop_back();
               }
               down.push_back(d[i]);
          }
     }
     vector<pair<pii, int>> res;
     for (auto el : up) {
          res.push_back(el);
     }

     for (int i = down.size() - 2; i >= 0; --i) {
          res.push_back(down[i]);
     }
     return res;
}

double cp(pii a, pii b) {
     return a.x * b.y - a.y * b.x;
}

double dp(pii a, pii b) {
