            tmp=(ans[i]-ans[(i-1+num)%num]).dot(ans[i]-ans[(i+1)%num]);
            tmp=acos(tmp/(ans[i]-ans[(i-1+num)%num]).dis()/(ans[i]-ans[(i+1)%num]).dis());
            res[ans[i].id]=(PI-tmp)/PI/2;
        }
    }
    for(int i=0;i<n;i++) printf("%.12f\n",res[i]);
    return 0;
}

