double EPS=1e-10;
double add(double a,double b){
  if(abs(a+b)<EPS*(abs(a)+abs(b))) return 0;
  return a+b;
}
struct P{
  double x,y;
  P() {}
  P(double x,double y):x(x),y(y){
  }
  P operator +(P p){
    return P(add(x,p.x),add(y,p.y));
  }
  P operator -(P p){
    return P(add(x,-p.x),add(y,-p.y));
  }
  P operator *(double d){
    return P(x*d,y*d);
  }
  double dot(P p){
    return add(x*p.x,y*p.y);
  }
  double det(P p){
    return add(x*p.y,-y*p.x);
  }
};
bool cmp_x(const P& p,const P& q){
  if(p.x!=q.x) return p.x<q.x;
  return p.y<q.y;
}
bool on_seg(P p1,P p2,P q){
  return (p1-q).det(p2-q)==0 and (p1-q).dot(p2-q)<=0;
}
vector<P> ps(100100);
vector<P> convex_hull(int n){
  sort(all(ps),cmp_x);
  int k=0;
  vector<P> qs(n*2);
  rep(i,n){
    while(k>1 and ((qs[k-1]-qs[k-2]).det(ps[i]-qs[k-1]))<=0) k--;
    qs[k++]=ps[i];
  }
  int t=k;
  rep(i,n-1){
    while(k>t and ((qs[k-1]-qs[k-2]).det(ps[n-2-i]-qs[k-1]))<=0) k--;
    qs[k++]=ps[n-2-i];
  }
  qs.resize(k-1);
  return qs;
}

int main(){
  int N;
  cin>>N;
  VI X(N),Y(N);
  rep(i,N) cin>>X[i]>>Y[i];
  rep(i,N) ps[i]=P(X[i],Y[i]);
  ps.resize(N);
  sort(all(ps),cmp_x);
  vector<P> qs=convex_hull(N);
  map<PII,int> M;
  rep(i,N) M[mp(X[i],Y[i])]=i;
  vector<double> ans(N);
  int Q=qs.size();
  rep(i,Q){
    int prv=(i-1+Q)%Q;
    int nxt=(i+1)%Q;
    P C=qs[i]-qs[prv];
    P D=qs[nxt]-qs[i];
    C=P(C.y,-C.x);
    D=P(D.y,-D.x);
    double tmp=C.dot(D)/sqrt(C.dot(C)*D.dot(D));
    ans[M[mp(qs[i].x,qs[i].y)]]=acos(tmp)/(double)2/acos(-1);
  }
  cout<<setprecision(10);
  rep(i,N) cout<<ans[i]<<endl;
}

