struct Point { 
	int x, y; 

	bool operator <(const Point &p) const {
		return x < p.x || (x == p.x && y < p.y);
	}
}; 

int orientation(Point p, Point q, Point r) { 
	int val = (q.y - p.y) * (r.x - q.x) - 
			(q.x - p.x) * (r.y - q.y); 

	if (val == 0) return 0; // colinear 
	return (val > 0)? 1: 2; // clock or counterclock wise 
}

ld dis(Point p, Point q){
	return (p.x - q.x) * (p.x - q.x) + (p.y - q.y) * (p.y - q.y);
}


ld dist(Point p, Point q){
	return sqrt((p.x - q.x) * (p.x - q.x) + (p.y - q.y) * (p.y - q.y));
}

ld deg(Point p, Point q, Point r){
	return acos((dis(p, q) + dis(q, r) - dis(r, p)) / (2.0 * dist(q, p) * dist(q,r)));
}

vector<Point> convexHull(Point points[], int n){
	vector<Point> hull; 
	if (n < 3){
		for(int i = 0;i<n;i++) hull.pb(points[i]);
		return hull;
	}


	int l = 0; 
	for (int i = 1; i < n; i++) 
		if (points[i].x < points[l].x) 
			l = i; 
	int p = l, q; 
	do{ 
		hull.push_back(points[p]); 
		q = (p+1)%n; 
		for (int i = 0; i < n; i++) { 
			if (orientation(points[p], points[i], points[q]) == 2) 
				q = i; 
		}
		p = q; 
	} while (p != l);
	return hull;
} 

Point hol[MAXN];
vector<Point> ans;
map<pll, ll> mp;
ld pr[MAXN];

int main(){
    ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);
	cout.precision(16);
	ll n;
	cin >> n;
	if(n == 2) return cout << "0.5\n0.5\n", 0;
	for(int i = 0; i < n; i++){
		cin >> hol[i].x >> hol[i].y;
		mp[{hol[i].x, hol[i].y}] = i;
	}
	sort(hol, hol + n);
	ans = convexHull(hol, n);
	ll ind, l, nx;
	ll m = ans.size();
	for(int i = 0; i < ans.size(); i++){
		l = (i - 1 + m) % m;
		nx = (i + 1) % m;
		ind = mp[{ans[i].x, ans[i].y}];
		pr[ind] = (acos(-1) - deg(ans[l], ans[i], ans[nx])) / (2 * acos(-1));
	}
	for(int i = 0; i< n;i++) cout << fixed << abs(pr[i]) << '\n';
	return 0;
}


