int X[Maxn], Y[Maxn];
vector <int> seq;
vector <int> hull;
ld my[Maxn], sum;

ll Cross(ll ax, ll ay, ll bx, ll by) { return ax * by - ay * bx; }

ll Dot(ll ax, ll ay, ll bx, ll by) { return ax * bx + ay * by; }

ld Len(ld ax, ld ay) { return sqrt(ax * ax + ay * ay); }

ld Angle(int a, int b, int c)
{
	ll ax = X[b] - X[a], ay = Y[b] - Y[a];
	ll bx = X[c] - X[a], by = Y[c] - Y[a];
	return acos(Dot(ax, ay, bx, by) / Len(ax, ay) / Len(bx, by));
}

bool Ok(int a, int b, int c)
{
	ll ax = X[b] - X[a], ay = Y[b] - Y[a];
	ll bx = X[c] - X[a], by = Y[c] - Y[a];
	return Cross(ax, ay, bx, by) > 0;
}

bool Less(const int &a, const int &b)
{
	ld v1 = atan2(ld(Y[a] - Y[mn]), ld(X[a] - X[mn]));
	ld v2 = atan2(ld(Y[b] - Y[mn]), ld(X[b] - X[mn]));
	if (fabs(v1 - v2) > 1e-9l) return v1 < v2;
	return Len(X[mn] - X[a], Y[mn] - Y[a]) < Len(X[mn] - X[b], Y[mn] - Y[b]);
}

int main()
{
	scanf("%d", &n);
	mn = 0;
	for (int i = 0; i < n; i++) {
		scanf("%d %d", &X[i], &Y[i]);
		if (ii(X[i], Y[i]) < ii(X[mn], Y[mn])) mn = i;
	}
	for (int i = 0; i < n; i++) if (i != mn)
		seq.push_back(i);
	sort(seq.begin(), seq.end(), Less);
	hull.push_back(mn);
	for (int i = 0; i < seq.size(); i++) {
		int ind = seq[i];
		while (hull.size() >= 2 && !Ok(hull[int(hull.size()) - 2], hull.back(), ind)) hull.pop_back();
		hull.push_back(ind);
	}
	while (hull.size() >= 3 && !Ok(hull[int(hull.size()) - 2], hull.back(), mn)) hull.pop_back();
	if (hull.size() == 2) {
		for (int i = 0; i < hull.size(); i++)
			my[hull[i]] = 0.5;
		sum = 1;
	} else 
		for (int i = 0; i < hull.size(); i++) {
			int pi = (i - 1 + hull.size()) % hull.size();
			int ni = (i + 1) % hull.size();
			my[hull[i]] = PI - Angle(hull[i], hull[pi], hull[ni]);
			sum += my[hull[i]];
			cout << sum << " " << my[hull[i]] << endl;
		}
	for (int i = 0; i < n; i++)
		cout << fixed << setprecision(15) << my[i] / sum << endl;
	return 0;
}

