}

double theta(Grid g0, Grid g1, Grid g2)
{
    pll v0(g1.y - g0.y, -(g1.x - g0.x));
    pll v1(g2.y - g1.y, -(g2.x - g1.x));

    double l0 = std::sqrt(v0.first * v0.first + v0.second * v0.second);
    double l1 = std::sqrt(v1.first * v1.first + v1.second * v1.second);
    double t = (v0.first / l0) * (v1.first / l1) + (v0.second / l0) * (v1.second / l1);
    return acos(t);
}

