    for(int i = 1 ; i <= N ; ++i) {read(x);read(y);P[i] = Point(x,y);P[i].id = i;}
    for(int i = 2 ; i <= N ; ++i) {
	if(P[i].x < P[1].x || (P[i].x == P[1].x && P[i].y < P[1].y)) swap(P[1],P[i]);
    }
    sort(P + 2,P + N + 1,cmp);
    sta[++top] = P[1];
    for(int i = 2 ; i <= N ; ++i) {
	while(top >= 2 && (P[i] - sta[top - 1]) * (sta[top] - sta[top - 1]) >= 0.0) --top;
	sta[++top] = P[i];
    }
    if(top == 2) {
	ans[sta[1].id] = 0.5;
	ans[sta[2].id] = 0.5;
    }
    else {
	Point a,b;
	sta[0] = sta[top];
	for(int i = 1 ; i <= top ; ++i) {
	    a = sta[i + 1] - sta[i];
	    b = sta[i - 1] - sta[i];
	    ans[sta[i].id] = (PI - acos( dot(a,b) / (a.norm() * b.norm()) ) ) / (2 * PI); 
 	}
    }
    for(int i = 1 ; i <= N ; ++i) {
	printf("%.10lf\n",ans[i]);
    }
    return 0;
}

