	for(int i=1;i<=howmany;i++)
    {
        int j=i+1,k=i-1;
        if(j>howmany)j=1;
        if(k==0)k=howmany;
        ans[res[i].id] = min(angle( res[i],res[j],res[k] ),pi - angle( res[i],res[j],res[k] ));
    }

    double all = pi*(howmany-2);

    for(int i=1;i<=n;i++)
    {
        printf("%.8f\n",ans[i]/all);
    }

	return 0;
}

