	return 1.0 * (A.x * B.x + A.y * B.y);
}

void solve() {
	hull[0] = hull[top];
	hull[top + 1] = hull[1];
	for(int i = 1; i <= top; i++) {
		Vector sa = hull[i] - hull[i - 1];
		Vector sb = hull[i + 1] - hull[i];
		hull[i].pb = acos(prod(sa, sb) / (dis(sa, Point(0, 0)) * dis(sb, Point(0, 0)))) / (2.0 * PI);
	}
	for(int i = 1; i <= n; i++) {
		for(int j = 1; j <= top; j++) {
			if(PP[i] == hull[j]) {
				PP[i].pb = hull[j].pb;
				break;
			}
		}
	}
	sort(PP + 1, PP + n + 1, Pcmp);
	for(int i = 1; i <= n; i++)
		printf("%.20lf\n", PP[i].pb);

}

