/* Representative * Relation = Representative みたいなノリ */
/* ゆくゆくは Relation * Relation = Relation に */
/* 範囲外アクセスなど注意; validation check必要 */
template <class T>
class RecurrenceRelation;
template <class T>
class RecurrenceRelationRepresentative {
	std::vector<T> coeffs_m;

	int Order() const;
public:
	//RecurrenceRelationRepresentative();
	RecurrenceRelationRepresentative(int order);
	RecurrenceRelationRepresentative(const std::vector<T> coeffs);
	const T& operator[](int index) const;
	T& operator[](int index);

	RecurrenceRelationRepresentative Successor(const RecurrenceRelation<T>& relation) const;
	T Real_value(const std::vector<T>& initial_vals);
};

template<class T>
inline int RecurrenceRelationRepresentative<T>::Order() const {
	return coeffs_m.size();
}

//template<class T>
//inline RecurrenceRelationRepresentative<T>::RecurrenceRelationRepresentative() {}

/* デフォルトコンストラクタは第0項目を表現 */
template<class T>
inline RecurrenceRelationRepresentative<T>::RecurrenceRelationRepresentative(int order) {
	coeffs_m.resize(order);
	coeffs_m[0] = 1;
}

template<class T>
inline RecurrenceRelationRepresentative<T>::RecurrenceRelationRepresentative(const std::vector<T> coeffs)
	: coeffs_m(coeffs){
}

template<class T>
inline const T& RecurrenceRelationRepresentative<T>::operator[](int index) const {
	return coeffs_m.at(index);
}

template<class T>
inline T& RecurrenceRelationRepresentative<T>::operator[](int index) {
	return coeffs_m.at(index);
}

template<class T>
inline RecurrenceRelationRepresentative<T> RecurrenceRelationRepresentative<T>::Successor(const RecurrenceRelation<T>& relation) const {
	std::vector<T> vec;
	vec.reserve(Order());
	vec.push_back(coeffs_m[Order() - 1]);
	for (int i = 1; i < Order(); ++i) {
		vec.push_back(coeffs_m[i - 1] + coeffs_m[Order() - 1] * relation[i]);
	}
	return RecurrenceRelationRepresentative(vec);
}

template<class T>
inline T RecurrenceRelationRepresentative<T>::Real_value(const std::vector<T>& initial_vals) {
	return inner_product(coeffs_m.begin(), coeffs_m.end(), initial_vals.begin(), T());
}


template <class T>
class RecurrenceRelation {
	typedef RecurrenceRelationRepresentative<T> Representative;

	/* 配列 v[k] で a[n + k] = v[0]a[n] + v[1]a[n + 1] + ... + v[k - 1]a[n + k - 1] の形の漸化式を表す */
	std::vector<T> relation_m;

	int Order() const;
	Representative Linear_expression(int index) const;
public:
	RecurrenceRelation(int size);
	RecurrenceRelation(const std::vector<T>& vec);
	T Real_value(int index, const std::vector<T>& initial_vals);

	const T& operator[](int index) const;
	T& operator[](int index);
};

template<class T>
int RecurrenceRelation<T>::Order() const {
	return relation_m.size();
}

template<class T>
typename RecurrenceRelation<T>::Representative RecurrenceRelation<T>::Linear_expression(int index) const {
	if (index == 0) return Representative(Order());

	std::vector<T> vec;
	std::vector<Representative> Sn;
	Sn.reserve(Order());

	int n = index / 2;
	Sn.push_back(Linear_expression(n));
	for (int k = 1; k < Order(); ++k) {
		Sn.push_back(Sn.back().Successor(*this));
	}
	for (int j = 0; j < Order(); ++j) {
		T sum = T();
		for (int p = 0; p < Order(); ++p) {
			sum += Sn[0][p] * Sn[p][j];
		}
		vec.push_back(sum);
	}

	Representative ret(vec);
	return index % 2 == 0 ? ret : ret.Successor(*this);
}

template<class T>
inline RecurrenceRelation<T>::RecurrenceRelation(int size)
	: relation_m(size, 1) {
}

template<class T>
RecurrenceRelation<T>::RecurrenceRelation(const std::vector<T>& vec)
	: relation_m(vec) {
}

template<class T>
T RecurrenceRelation<T>::Real_value(int index, const std::vector<T>& initial_vals) {
	Representative coeffs = Linear_expression(index);
	return coeffs.Real_value(initial_vals);
}

template<class T>
inline const T& RecurrenceRelation<T>::operator[](int index) const {
	return relation_m[index];
}

template<class T>
inline T& RecurrenceRelation<T>::operator[](int index) {
	return relation_m[index];
}


