/* [-PI, PI] */
Radian Angle(const Vector2DInt& from, const Vector2DInt& center, const Vector2DInt& to) {
	Radian angle = (to - center).Arg() - (from - center).Arg();
	if (angle < 0) angle += 2 * PI;
	return angle;
}

Vector2DDouble Internal(const Vector2DInt& a, const Vector2DInt& b, double ratio) {
	return a * ratio + b * (1 - ratio);
}

/* object を direction 方向に射影 */
Vector2DRational Project(const Vector2DInt& object, const Vector2DInt& direction) {
	return direction * Dot(object, direction) / direction.Norm2();
}

CCWEnum CCW(const Vector2DInt& a, const Vector2DInt& b, const Vector2DInt& p) {
	Vector2DInt ab = b - a;
	Vector2DInt ap = p - a;
	if (Cross(ab, ap) > 0) return CCWEnum::Counterclockwise;
	if (Cross(ab, ap) < 0) return CCWEnum::Clockwise;
	if (Dot(ab, ap) < 0) return CCWEnum::Backward_On_Line;
	if (ab.Norm2() < ap.Norm2()) return CCWEnum::Forward_On_Line;
	return CCWEnum::Internal;
}

