            f64 b = dist(x1, y1, x3, y3);
            f64 c = dist(x2, y2, x3, y3);
            f64 tmp = (a * a + b * b - c * c) / (2. * a * b);
            f64 angle;
            if (tmp < -1.) angle = PI;
            else if (tmp > 1.) angle = 0.;
            else angle = acos(tmp);
            assert(!isnan(angle));
            angle = angle * 180. / PI;
            angle = 180. - angle;
            res[hull[i]] = angle;
            sum += angle;
        }
        for (int i = 0; i < n; ++i) {
            res[i] /= 360.;
            out.precision(20);
            out << fixed << res[i] << "\n";
        }
    }
};

