int orient(pt a, pt b, pt c) {
    ll val = (b.y - a.y) * (c.x - b.x) - (c.y - b.y) * (b.x - a.x);

    if (val < 0) {
        val = -1;
    }

    if (val > 0) {
        val = 1;
    }

    return val;
}

void convexHull(vector<pt> &arr) {
    vector<pt> hull;
    int st = 0;

    for (int i = 1; i < arr.size(); ++i) {
        if (arr[i].x < arr[st].x) {
            st = i;
        }
    }

    int p = st;

    do {
        hull.pb(arr[p]);
        int q = (p + 1) % arr.size();

        for (int i = 0; i < arr.size(); ++i) {
            if (orient(arr[p], arr[i], arr[q]) == -1) {
                q = i;
            }
        }

        p = q;
    }
    while (p != st);

    arr = hull;
}

ll distSq(pt a, pt b) {
    return (a.x - b.x) * (a.x - b.x) + (a.y - b.y) * (a.y - b.y);
}

