double dot(const Point &a,const Point &b) {return (a.x*b.x+a.y*b.y);}
double cross(const Point &a,const Point &b) {return (a.x*b.y-a.y*b.x);}
double norm(const Point &p) {return dot(p,p);}
double abs(const Point &p) {return sqrt(norm(p));}

vector<Point> ConvexHull(vector<Point> ps,bool linear){
    sort(ps.begin(),ps.end(),[](Point &a,Point &b){
        return (a.x!=b.x?a.x<b.x:a.y<b.y);
    });
    int n=ps.size();
    vector<Point> res(2*n);
    int lim=linear?0:1;

    int k=0;
    for(int i=0;i<n;i++){
        while(k>=2&&sgn(cross(res[k-1]-res[k-2],ps[i]-res[k-2]))<lim) --k;
        res[k++]=ps[i];
    }
    int t=k+1;
    for(int i=n-2;i>=0;i--){
        while(k>=t&&sgn(cross(res[k-1]-res[k-2],ps[i]-res[k-2]))<lim) --k;
        res[k++]=ps[i];
    }

    res.resize(k-1);
    return res;
}


