// --- 点の進行方向 --- //

// 点の進行方向を調べる
enum DotDir {
    Counterclockwise = 1,   // a -> b 反時計周りの方向に c
    Clockwise = -1,         // a -> b 時計周りの方向に c
    CAB = 2,                // c -> a -> b の順に並ぶ
    ABC = -2,               // a -> b -> c の順に並ぶ
    ACB = 0                 // a -> c -> b の順に並ぶ
};
int Ccw(const Point &a, Point b, Point c)
{
  b = b - a, c = c - a;
  if(Cross(b, c) > EPS) { return Counterclockwise; }
  if(Cross(b, c) < -EPS) { return Clockwise; }
  if(Dot(b, c) < 0) { return CAB; }
  if(b.Norm() < c.Norm()) { return ABC; }
  return ACB;
}

// --- 直線の平行・交差判定 --- //

// 直線の平行判定 a, b が平行なら true
bool Parallel(const Line& a,const Line& b){
  return abs(Cross(a.b - a.a, b.b - b.a)) < EPS;
}
// 直線の直交判定 a, b が直交していれば true
bool Orthogonal(const Line& a,const Line& b){
  return abs(Dot(a.a - a.b, b.a - b.b)) < EPS;
}

// --- 点から直線・線分への射影・反射 --- //
// ※射影と反射の定義、少し違う気がするが気にしないことにする

// 射影
// 点 p から直線 l に対して垂線をおろしたときの交点 x を射影と呼ぶことにする
// その x を返す
Point Projection(const Line& l, const Point& p) {
  double t = Dot(p - l.a, l.a - l.b) / (l.a - l.b).Norm();
  return l.a + (l.a - l.b) * t;
}
// 線分に対しても直線と同じ式()
Point Projection(const Segment& l, const Point& p) {
  double t = Dot(p - l.a, l.a - l.b) / (l.a - l.b).Norm();
  return l.a + (l.a - l.b) * t;
}

// 反射
// 直線 l を対象軸として点 p と線対称の位置にある点 x を p の反射と呼ぶ
Point Reflection(const Line& l, const Point& p) {
  return p + (Projection(l, p) - p) * 2.0;
}

// --- 点・直線・線分の距離 --- //

// いくつかの距離算出に交点を使うので前もって宣言
bool Intersect(const Line &l, const Point &p);
bool Intersect(const Line &l, const Line &m);
bool Intersect(const Segment &s, const Point &p);
bool Intersect(const Line &l, const Segment &s);
bool Intersect(const Segment &s, const Segment &t);
bool Intersect(const Circle &c, const Line &l);
bool Intersect(const Circle &c, const Point &p);
bool Intersect(const Circle &c1, const Circle& c2);
int Intersect(const Circle &c, const Segment &l);

// 2 点 a, b 間の距離
double Distance(const Point& a,const Point& b) { return (a - b).Abs(); }

// 点 p から直線 l に対して下した垂線の距離
// = 点 p と点 p の直線 l に対する射影の距離
double Distance(const Line& l,const Point& p) { return (p - Projection(l, p)).Abs(); }

// 直線同士の距離
// 平行である -> 直線 m 上の任意点からの l に対する射影への距離
// 平行でない -> 0
double Distance(const Line& l,const Line& m) {
  return Intersect(l, m) ? 0 : Distance(l, m.a);
}

// 線分と点の距離
// 点 p の線分 l に対する射影 r を求め、それが l 上にあるならそれと点 p の距離
// ないなら線分 l の両端のどっちか短い方が距離
double Distance(const Segment& s,const Point& p){
  Point r = Projection(s, p);
  if (Intersect(s, r)) { return (r - p).Abs(); }
  return min((s.a - p).Abs(), (s.b - p).Abs());
}

// 線分同士の距離
// 線分が交差している -> 0
// 交差していない -> 線分の端点の組み合わせパターンの最小が距離
double Distance(const Segment& a,const Segment& b){
  if(Intersect(a, b)) { return 0; }
  return min({ Distance(a, b.a), Distance(a, b.b), Distance(b, a.a), Distance(b, a.b) });
}

// 直線と線分の距離
// 交差している -> 0
// 交差していない -> 線分の端点 2 つと直線の距離の最小
double Distance(const Line& l,const Segment& s) {
  if (Intersect(l, s)) { return 0; }
  return min(Distance(l, s.a), Distance(l, s.b));
}

// --- 点・直線・線分の交差判定 --- //

// 直線 l 上に点 p があるなら true
bool Intersect(const Line &l, const Point &p) { return abs(Ccw(l.a, l.b, p)) != 1; }
// 直線同士が交わっているなら true
bool Intersect(const Line &l, const Line &m) {
  return abs(Cross(l.b - l.a, m.b - m.a)) > EPS || abs(Cross(l.b - l.a, m.b - l.a)) < EPS;
}
// 線分 s 上に点 p があるなら true
bool Intersect(const Segment &s, const Point &p) { return Ccw(s.a, s.b, p) == ACB; }
// 直線と線分が交わっているなら true
bool Intersect(const Line &l, const Segment &s) {
    return Cross(l.b - l.a, s.a - l.a) * Cross(l.b - l.a, s.b - l.a) < EPS;
}
// 線分同士が交わっているなら true
bool Intersect(const Segment &s, const Segment &t) {
  return Ccw(s.a, s.b, t.a) * Ccw(s.a, s.b, t.b) <= 0 && Ccw(t.a, t.b, s.a) * Ccw(t.a, t.b, s.b) <= 0;
}
// 直線と円が接しているなら true
bool Intersect(const Circle &c, const Line &l) { return Distance(l, c.p) <= c.r + EPS; }
// 点が円周上にあるなら true
bool Intersect(const Circle &c, const Point &p) { return abs((p - c.p).Abs() - c.r) < EPS; }
// 線分が円周と交差する数を返す
// ただし円の接線の場合も 2 を返す
int Intersect(const Circle &c, const Segment &l)
{
    // 円の中心から線分に向かっての射影までの距離が
    // 円の半径より大きいなら円と線分は交わっていない
    if((Projection(l, c.p) - c.p).Norm() - c.r * c.r > EPS) { return 0; }
    // 線分の端点から円の中心までの距離
    const double d1 = (c.p - l.a).Abs(), d2 = (c.p - l.b).Abs();
    // 両方の端点が円の内部にある場合は円に内包されているため交わっていない
    if(d1 < c.r + EPS && d2 < c.r + EPS) { return 0; }
    // 端点のどちらか片方だけ円に入っている
    if(d1 < c.r - EPS && d2 > c.r + EPS || d1 > c.r + EPS && d2 < c.r - EPS) { return 1; }
    // 円の中心から線分への射影
    const Point h = Projection(l, c.p);
    // 射影から各端点への内積が負 = 射影は線分の中にある
    // -> 線分は円を通過する
    if(Dot(l.a - h, l.b - h) < 0) { return 2; }
    return 0;
}

// 円周どうしの交差判定
bool Intersect(const Circle &c1, const Circle &c2) {
    double d = Distance(c1.p, c2.p);
    if(d > c1.r + c2.r) { return false; }
    if(d + min(c1.r, c2.r) < max(c1.r, c2.r)) { return false; }
    return true;
}


// --- 凸包 --- //

// 凸包：与えられた点全てを包含する最小の凸多角形のこと
// 点集合を与えることで多角形を返す
// 点は x 方向最小の点から反時計周りで順番に格納される
// p のもともとの順番をソートにより破壊してしまうので注意
// O(N log N)
Polygon ConvexHull(Polygon& p){
  int n = p.size(), k = 0;
  if(n >= 3){
    sort(p.begin(), p.end());
    vector< Point > ch(2 * n);
    for(int i = 0; i < n; ch[k++] = p[i++]){
      while(k >= 2 && Cross(ch[k - 1] - ch[k - 2], p[i] - ch[k - 1]) < 0) { --k; }
    }
    for(int i = n - 2, t = k + 1; i >= 0; ch[k++] = p[i--]){
      while(k >= t && Cross(ch[k - 1] - ch[k - 2], p[i] - ch[k - 1]) < 0) { --k; }
    }
    ch.resize(k - 1);
    return ch;
  } else {
    return p;
  }
}

// --- 点の多角形包含判定 --- //
enum
{
  Out, On, In
};
// 線上なら On, 多角形内なら In, それ以外なら Out が返る
int Contains(const Polygon &Q, const Point &p)
{
  bool in = false;
  for(int i = 0; i < Q.size(); i++) {
    Point a = Q[i] - p, b = Q[(i + 1) % Q.size()] - p;
    if(a.y > b.y) { swap(a, b); }
    if(a.y <= 0 && 0 < b.y && Cross(a, b) < 0) { in = !in; }
    if(Cross(a, b) == 0 && Dot(a, b) <= 0) { return On; }
  }
  return in ? In : Out;
}

// --- 多角形の重心 --- //

// 多角形の重心の位置を返す
Point GetPolyCenter(const Polygon& p) {
    Point ret(0, 0);
    for(auto& tmp_p : p) {
        ret.x += tmp_p.x;
        ret.y += tmp_p.y;
    }
    ret.x /= p.size();
    ret.y /= p.size();
    return ret;
}

// --- 多角形の法線 --- //

// 多角形の法線集合を求める
// Segment は a->b 方向に伸びるベクトルの法線であるとする
Segments GetNormal(const Polygon& p) {
    Segments res;
    for(int i = 0; i < p.size(); ++i) {
        Segment s = (i == p.size()-1) ? Segment(p[i], p[0]) : Segment(p[i], p[i+1]);
        Line pb = s.PerpBisector();     // 垂直二等分線
        // どれか垂直二等分線上の多角形外の点を探す
        for(int j = 0; j < 4; ++ j) {
            Point cand = s.Center();
            if(j == 0) {
                cand.x += 1.0;
                cand.y = pb.GetY(cand.x);
            }
            else if(j == 1) {
                cand.x -= 1.0;
                cand.y = pb.GetY(cand.x);
            }
            else if(j == 2) {
                cand.y += 1.0;
                cand.x = pb.GetX(cand.y);
            }
            else {
                cand.y -= 1.0;
                cand.x = pb.GetX(cand.y);
            }
            if(Contains(p, cand) == Out) {
                res.push_back(Segment(s.Center(), cand));
                break;
            }
            if(j == 3) { abort(); }
        }
    }
    return res;
}

