    for (int j = 0; j < points.size(); ++j) {
      int jj = (j + 1) % points.size();
      double angle = atan2(points[jj].y, points[jj].x) - atan2(points[j].y, points[j].x);
      if (angle < 1e-9) {
        angle += 2 * pi;
      }
      ma = max(ma, angle);
    }
    printf("%.10lf\n", ma < pi ? 0.0 : (ma - pi) / 2 / pi);
  }

  return 0;
}

