					if (ttdist > tempdist) {
						tempdist = ttdist;
						tempang = ttang;
						nexti = i;
					}
				}//
				else if (ttang<tempang ) {//別方向で角度が小さいもの
					//atan2()
					if (i!=tempp.pointnum) {
						tempdist = ttdist;
						tempang = ttang;
						nexti = i;
					}
				}
			}
		}


		tempp.pointnum = tempi;
		tempp.pointx = x[tempi];
		tempp.pointy = y[tempi];
		tempp.dang = tempang - tempp.ang;
		if (tempp.dang < 0) {
			tempp.dang+=2*M_PI;
		}
		tempp.ang = tempang;
		vp.push_back(tempp);

		if (nexti == minyi) {
			break;
		}
		tempx = x[nexti];
		tempy = y[nexti];
		tempi = nexti;
	}

	double tempang = 2 * M_PI;
	for (ll i = 1; i < vp.size(); i++) {
		tempang -= vp[i].dang;
	}
	vp[0].dang = tempang;

	//添字iごとの受け持ち確率を求める
	double answer[100] = {};
	for (ll i = 0; i < vp.size(); i++) {
		answer[vp[i].pointnum] = vp[i].dang/(M_PI*2.0);
	}

	//出力
	for (ll i = 0; i < n; i++) {
		cout << answer[i] << endl;
	}

	return 0;
}

