    const double theta = angle(v_prev, v_next);
    // printf("(%lf, %lf) -> (%lf, %lf): %lf\n", v_prev.first, v_prev.second,
    //        v_next.first, v_next.second, theta);
    // find index
    for (int j = 0; j < N; j++) {
      if (norm(sub(p_cur, ps[j])) < EPS) {
        probs[j] = theta / (2.0 * M_PI);
        break;
      }
    }
  }

  // print answer
  for (int i = 0; i < N; i++) {
    printf("%.10lf\n", probs[i]);
  }

  return 0;
}

