  return {-a.x, -a.y};
}

pt operator- (pt a, pt b) {
  return a + (-b);
}

ll dot (pt a, pt b) {
  return a.x * b.x + a.y * b.y;
}

ll cross (pt a, pt b) {
  return a.x * b.y - a.y * b.x;
}

ld norm (pt u) {
  return sqrt((ld) dot(u, u));
}

ld angle (pt a, pt o, pt b) {
  pt u = a - o;
  pt v = b - o;
  ld cosa = dot(u, v) / (norm(u) * norm(v));
  return acos(cosa);
}

bool cw (pt a, pt b, pt c) {
  return cross(b - a, c - a) < 0;
}

template<typename T>
T preback (const vector<T> &v) {
  return *next(v.rbegin());
}

const int MAX_N = 105;

ld ans [MAX_N];

int main () {
  ios::sync_with_stdio(false);

  int n;
  cin >> n;

  vector<pair<pt, int>> pts (n);
  for (int i = 0; i < n; i++) {
    cin >> pts[i].x.x >> pts[i].x.y;
    pts[i].y = i;
  }

  sort(pts.begin(), pts.end());

  vector<pair<pt, int>> upper;
  for (int i = 0; i < n; i++) {
    while ((int) upper.size() >= 2 && !cw(preback(upper).x, upper.back().x, pts[i].x)) {
      upper.pop_back();
    }
    upper.push_back(pts[i]);
  }

  reverse(pts.begin(), pts.end());

  vector<pair<pt, int>> lower;
  for (int i = 0; i < n; i++) {
    while ((int) lower.size() >= 2 && !cw(preback(lower).x, lower.back().x, pts[i].x)) {
      lower.pop_back();
    }
    lower.push_back(pts[i]);
  }

  if (upper.back().y == lower[0].y) upper.pop_back();
  for (auto pr : lower) {
    upper.push_back(pr);
  }
  if (upper.back().y == upper[0].y) upper.pop_back();

  // upper is now the convex hull
  int k = upper.size();
  if (k == 2) {
    cout << 0.5 << endl << 0.5 << endl;
    return 0;
  }

  for (int i = 0; i < k; i++) {
    ans[upper[i].y] = angle(upper[(i + k - 1) % k].x, upper[i].x, upper[(i + 1) % k].x);
    ans[upper[i].y] = (M_PI - ans[upper[i].y]) / (2 * M_PI);
  }

  for (int i = 0; i < n; i++) {
    cout << fixed << setprecision(12) << ans[i] << '\n';
  }
}

