int ccw(Point a, Point b, Point c) {
  b -= a; c -= a;
  if (cross(b,c) > 0)      return +1; // counter clockwise
  if (cross(b,c) < 0)      return -1; // clockwise
  if (dot(b,c) < 0)        return +2; // c--a--b on line
  if (dot(b,b) < dot(c,c)) return -2; // a--b--c on lne
  return 0;
}

// Convex Hull
//
// Algorithm:
//   Andrew's monotone chain
namespace std { 
  bool operator < (Point a, Point b) { // bottom-left
    return a.Y != b.Y ? a.Y < b.Y : a.X < b.X; 
  }
}
vector<Point> convexHull(vector<Point> p) {
  int n = p.size(), k = 0;
  vector<Point> h(2*n);
  sort(ALL(p));
  for (int i = 0; i < n; h[k++] = p[i++]) 
    while (k >= 2 && ccw(h[k-2], h[k-1], p[i]) <= 0) --k;
  for (int i = n-2, t = k+1; i >= 0; h[k++] = p[i--]) 
    while (k >= t && ccw(h[k-2], h[k-1], p[i]) <= 0) --k;
  return vector<Point>(h.begin(), h.begin() + k - (k > 1));
}

int main() {
    int n;
    in(n);

    vector<Point> p(n);

    for (int i = 0; i < n; i++) {
        Value x, y;
        in(x, y);

        p[i] = Point(x, y);
    }

    vector<int> use(n, 1);

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (j == i) {
                continue;
            }

            for (int k = 0; k < n; k++) {
                if (k == i || k == j) {
                    continue;
                }

                Point d1 = p[j] - p[i];
                Point d2 = p[k] - p[j];

                if (d1.X * d2.Y == d2.X * d1.Y) {
                    use[j] = 0;
                }
            }
        }
    }

    vector<Point> q;

    for (int i = 0; i < n; i++) {
        if (use[i]) {
            q.push_back(p[i]);
        }
    }

    auto s = convexHull(q);

    vector<double> ans(n, 0.0);

    double pi = acos(-1);

    cout << fixed << setprecision(12);

    for (int i = 0; i < s.size(); i++) {

        Point d1 = s[(i + 1) % s.size()] - s[i];
        Point d2 = s[(i + s.size() - 1) % s.size()] - s[i];

        double x = (pi - (arg(d2) - arg(d1))) / (2 * pi);

        if (x > 1.0) {
            x -= 1.0;
        }

        int ind = find(p.begin(), p.end(), s[i]) - p.begin();

        ans[ind] = x;
    }

    for (int i = 0; i < n; i++) {
        out(ans[i]);
    }
}

