  }
  REP(i,n) {
    ld minarg = pi;
    ld maxarg = -pi;
    ld minarg2 = 2*pi;
    ld maxarg2 = 0;
    ld x, y;
    tie(x, y) = vp[i];
    REP(j,n) {
      if (i==j) continue;
      ld nx, ny;
      tie(nx, ny) = vp[j];
      ld arg = atan2(ny-y, nx-x);
      minarg = min(minarg, arg);
      maxarg = max(maxarg, arg);
      if (arg < 0) arg += 2*pi;
      minarg2 = min(minarg2, arg);
      maxarg2 = max(maxarg2, arg);
    }
    //cerr << maxarg << ' ' << minarg << ' ' << maxarg2 << ' ' << minarg2 << endl;
    ld deg1 = pi - (maxarg - minarg);
    ld deg2 = pi - (maxarg2 - minarg2);
    ld deg = max(deg1, deg2);
    if (deg > 0) {
      cout << setprecision(10) << fixed << deg / (2*pi) << endl;
    } else {
      cout << setprecision(10) << fixed << 0.0 << endl;
    }
  }
  return 0;
}

