using namespace std;

using int64 = long long;
using Point = complex<int64>;

inline int64 cross(const Point& u, const Point& v) {
  return u.real() * v.imag() - u.imag() * v.real();
}

vector<int> ConvexHull(const vector<Point>& holes) {
  const int n = holes.size();

  vector<int> indexes(n);
  for (int i = 0; i < n; ++i)
    indexes[i] = i;

  // Sort by angles
  const Point center = (holes[0] + holes[1] + holes[2]) / Point(3, 0);
  sort(indexes.begin(), indexes.end(), [&](int a, int b) {
      const Point ap = holes[a] - center;
      const Point bp = holes[b] - center;
      return arg(complex<double>(ap.real(), ap.imag())) < arg(complex<double>(bp.real(), bp.imag()));
    });

  // Detect starting hole's index
  int start = 0;
  for (int i = 1; i < n; ++i) {
    if (holes[indexes[start]].real() < holes[indexes[i]].real()) {
      start = i;
      continue;
    }
    if (holes[indexes[start]].real() == holes[indexes[i]].real() &&
        holes[indexes[start]].imag() < holes[indexes[i]].imag()) {
      start = i;
      continue;
    }
  }

  vector<int> convex_ids;
  convex_ids.push_back(indexes[start]);
  int candidate = indexes[(start + 1) % n];
  for (int i = 2; i <= n; ++i) {
    int ii = indexes[(start + i) % n];
    const Point& from = holes[convex_ids.back()];
    const Point& to0 = holes[candidate];
    const Point& to1 = holes[ii];
    if (cross(to0 - from, to1 - from) > 0) {
      convex_ids.push_back(candidate);
    }
    candidate = ii;
  }

  return convex_ids;
}

vector<double> Solve(const vector<Point>& holes) {
  const int n = holes.size();
  if (n == 2) {
    return {0.5, 0.5};
  }
  vector<int> convex = ConvexHull(holes);
  const int m = convex.size();

  vector<double> results;
  for (int i = 0; i < n; ++i) {
    auto itr = find(convex.begin(), convex.end(), i);
    double r = 0;
    if (itr != convex.end()) {
      int c0 = itr - convex.begin();
      int c1 = (c0 + m - 1) % m;
      int c2 = (c0 + 1) % m;
      int id0 = convex[c0], id1 = convex[c1], id2 = convex[c2];
      Point d0 = holes[id0] - holes[id1];
      Point d1 = holes[id2] - holes[id0];
      double t0 = arg(complex<double>(d0.real(), d0.imag()));
      double t1 = arg(complex<double>(d1.real(), d1.imag()));
      double t = t1 - t0;
      if (t < 0)
        t += 2 * M_PI;
      r = t / (2 * M_PI);
    }
    results.push_back(r);
  }
  return results;
}

int main() {
  int N;
  cin >> N;
  vector<Point> holes;
  for (int i = 0; i < N; ++i) {
    int64 x, y;
    cin >> x >> y;
    holes.emplace_back(x, y);
  }

  for (double p : Solve(holes)) {
    printf("%.15f\n", p);
  }

  return 0;
}

