void ConvexHull(Point *p, int n , Point *ch,int &m){
	sort(p, p+n);
	m=0;
	ch[m++] = p[0]; ch[m++] = p[1];
	for (int i=2; i<n; i++){
		while ( m>=2 && dcmp(Cross(p[i]-ch[m-2], ch[m-1]-ch[m-2]))>=0) --m;
		ch[m++]= p[i];
	}
	int k=m;
	for (int i=n-1; i>=0; i--){
		while (m>k && dcmp(Cross(p[i]-ch[m-2], ch[m-1]-ch[m-2]))>=0) --m;
		ch[m++] = p[i];
	}
	--m;
}

