template<class T>
struct Pos2T
{
	Pos2T() {}
	Pos2T(T x, T y)
		: x(x)
		, y(y)
	{}

	bool operator== (const Pos2T &b) const
	{
		return x == b.x && y == b.y;
	}

	bool operator!= (const Pos2T &b) const
	{
		return x != b.x || y != b.y;
	}

	Pos2T operator*(T q) const
	{
		return Pos2T(x*q,y*q);
	}

	Pos2T operator+(const Pos2T &b) const
	{
		return Pos2T(x+b.x,y+b.y);
	}

	Pos2T &operator+=(const Pos2T &b)
	{
		x += b.x;
		y += b.y;
		return *this;
	}

	Pos2T operator-(const Pos2T &b) const
	{
		return Pos2T(x-b.x,y-b.y);
	}

	Pos2T &operator-=(const Pos2T &b)
	{
		x -= b.x;
		y -= b.y;
		return *this;
	}

	Pos2T operator-() const
	{
		return Pos2T(-x,-y);
	}

	Pos2T &operator*=(T q)
	{
		x *= q;
		y *= q;
		return *this;
	}

	T operator*(const Pos2T &b) const
	{
		return x*b.x + y*b.y;
	}

	T operator%(const Pos2T &b) const
	{
		return x*b.y - y*b.x;
	}

	const Pos2T &pos() const
	{
		return *this;
	}

	double len() const 
	{
		return sqrt(x*x+y*y);
	}

	T len2() const 
	{
		return x*x+y*y;
	}

	Pos2T norm() const
	{
		return (*this)*(1.0/len());
	}

	double dist(const Pos2T &p) const
	{
		return sqrt((x-p.x)*(x-p.x) + (y-p.y)*(y-p.y));
	}

	T dist2(const Pos2T &p) const
	{
		return (x-p.x)*(x-p.x) + (y-p.y)*(y-p.y);
	}	

	T x, y;
};

template<class T>
std::ostream& operator<<(std::ostream &s,const Pos2T<T> &p)
{
	s << "(" << p.x << "," << p.y << ")";
	return s;
}

typedef Pos2T<double> Pos;
typedef Pos2T<double> Vec;

const double eps = 1E-8;

int main()
{
	ios::sync_with_stdio(false);

	int n;
	cin >> n;
	vector<Pos> p(n);
	for(int i=0; i<n; ++i)
		cin >> p[i].x >> p[i].y;

	Pos mm[128][2];
	int nm[128] = {0};

	for(int i=0; i<n; ++i)
		for(int j=0; j<n; ++j) if(i != j)
		{
			Pos p1 = p[i];
			Pos p2 = p[j];
			bool ok = true;
			for(int k=0; ok && k<n; ++k) if(k != j && k != i)
			{
				if(eps < (p2-p1)%(p[k]-p1))
				{
					ok = false;
				}
			}
			if(!ok)
				continue;
			Pos m(-(p2.y-p1.y), p2.x-p1.x);
			mm[i][1] = m;
			mm[j][0] = m;
			nm[i]++;
			nm[j]++;
		}

	double ans[128] = {0};
	for(int i=0; i<n; ++i) if(nm[i])
	{
		assert(1 < nm[i]);
		Pos n1 = mm[i][0].norm();
		Pos n2 = mm[i][1].norm();
		double cs = n1*n2;
		double sn = n2%n1;
		double angle = atan2(sn,cs);
		ans[i] = angle/(2*M_PI);
	}

	for(int i=0; i<n; ++i)
		printf("%.19lf\n", ans[i]);
		//cout << ans[i] << "\n";

	return 0;
}

#include <bits/stdc++.h>
