  Visualizer &operator<<(Line l) {
    Real A, B, C;
    tie(A, B, C) = l.coef();
    ofs << "Line " << A << " " << B << " " << C << endl;
    return *this;
  }
  Visualizer &operator<<(Segment s) {
    ofs << "Segment " << s.p1 << " " << s.p2 << endl;
    return *this;
  }
  Visualizer &operator<<(Circle c) {
    ofs << "Circle " << c.o << " " << c.r << endl;
    return *this;
  }
  Visualizer &operator<<(Polygon g) {
    ofs << "Polygon" << endl;
    for (Point p : g) ofs << p << endl;
    ofs << "..." << endl;
    return *this;
  }
};

