      if (ch[j] == ps[i]) {
        Line l = bisector(ch[j], ch[ch.prev(j)]),
             m = bisector(ch[ch.next(j)], ch[j]);
        ans = arg(l.p2 - l.p1, m.p2 - m.p1);
        if (ans < 0) ans += 2 * PI;
        ans /= (2 * PI);
        break;
      }
    cout << ans << endl;
  }
