#include<bits/stdc++.h>
using namespace std;
#define double long double
#define int long long
const int N = 110;
const double pi = acos((double)-1);
const double eps = 1e-11;
int n, m, top;
double ans[N];
struct P{
	int x, y, id;
	double t;
	P(int x = 0, int y = 0):x(x), y(y){}
}p[N], sta[N];
inline int Sgn(long long x) { return x == 0 ? 0 : x > 0 ? 1 : -1; }
inline P operator-(P u, P v) { return P(u.x - v.x, u.y - v.y); }
inline int Cross(P u, P v) { return Sgn(1ll * u.x * v.y - 1ll * u.y * v.x); }
inline long long Length(P u) { return 1ll * u.x * u.x + 1ll * u.y * u.y; }
inline double Ang(P u, P v) { return acos((double)(1ll * u.x * v.x + 1ll * u.y * v.y) / sqrt(Length(u)) / sqrt(Length(v))); }
inline bool Cmp(P u, P v) {
	if (fabs(u.t - v.t) > eps) return u.t < v.t;
	return Length(u - p[0]) > Length(v - p[0]);
}
main() {
	scanf("%lld", &n);
	for (int i = 1; i <= n; ++i) {
		scanf("%lld%lld", &p[i].x, &p[i].y); p[i].id = i;
		if (p[i].x < p[1].x || (p[i].x == p[1].x && p[i].y < p[1].y)) swap(p[i], p[1]);
	}
	for (int i = 2; i <= n; ++i) {
		P tmp = p[i] - p[1];
		p[i].t = atan2(tmp.y, tmp.x);
	}
	sort(p + 2, p + n + 1, Cmp);
	m = 2; for (int i = 3; i <= n; ++i) if (fabs(p[i].t - p[m].t) > eps) p[++m] = p[i];
	for (int i = 1; i <= m; ++i) {
		while (top > 1 && Cross(p[i] - sta[top - 1], sta[top] - sta[top - 1]) > 0) --top;
		sta[++top] = p[i];
	}
	sta[top + 1] = sta[1]; sta[0] = sta[top];
	for (int i = 1; i <= top; ++i) ans[sta[i].id] = pi - Ang(sta[i - 1] - sta[i], sta[i + 1] - sta[i]);
	for (int i = 1; i <= n; ++i) printf("%.10Lf\n", ans[i] / pi / 2);
	return 0;
}

