int compare_int(const void *a, const void *b){
	pair<double, int> *A = (pair<double, int> *)a;
	pair<double, int> *B = (pair<double, int> *)b;
    double c = A->first;
    double d = B->first;
    if(c > d)return 1;
    if(c < d)return -1;
    return 0;
}
//pから見たqの角度
double elevation(struct node p, struct node q){
    double xx = q.x - p.x;
    double yy = q.y - p.y;
    return atan2(yy, xx);
}
int main(void){
    int n;
    scanf("%d", &n);
    int count = 0;
    for(int i = 0;i < n;i++){
        int a, b;
        scanf("%d %d", &a, &b);
        arr[i].x = (double)a;
        arr[i].y = (double)b;
    }
    if(n==2){
        printf("0.5\n0.5\n");
        return 0;
    }
    for(int i = 0;i < n;i++){
        for(int j = 0;j < n;j++){
            arr[i].rads[j].second = j;
            if(i == j)continue;
            arr[i].rads[j].first = elevation(arr[i], arr[j]);
        }
        if(i == 0)arr[i].rads[i].first = arr[i].rads[i+1].first;
        else arr[i].rads[i].first = arr[i].rads[i-1].first;
        qsort(arr[i].rads, n, sizeof(pair<double, int>), compare_int);
        for(int j = 0;j < n;j++)printf("%lf ", arr[i].rads[j].first);
        printf("\n");
        if(arr[i].rads[n-1].first - arr[i].rads[0].first < atan2(0.0, -1.0)){
            arr[i].ch = true;
            count++;
            continue;
        }
        arr[i].ch = false;
        for(int j = 1;j < n;j++){
            if(arr[i].rads[j].first - arr[i].rads[j-1].first > atan2(0.0, -1.0)){
                arr[i].ch = true;
                count++;
                break;
            }
        }
        if(!arr[i].ch)arr[i].rate = 0.0;
    }
    int num = 0;
    while(!arr[num].ch)num++;
    int j = 0;
    int flag = 1;
    for(int i = 0;i < n;i++){
        if(arr[arr[num].rads[i].second].ch && arr[num].rads[i].second != num){
            if(j != 0 && flag && arr[num].rads[j].first - arr[num].rads[j-1].first > atan2(0.0, -1.0)){
                roo[j] = 0;
                j++;
                flag = 0;
            }
            roo[j] = arr[num].rads[i].second;
            j++;
        }
    }
    if(flag){roo[j] = 0; j++;}
    for(int i = 0;i < j;i++)printf("%d\n", roo[i]);
    double ra = elevation(arr[roo[0]], arr[roo[count-1]]);
    double rb = elevation(arr[roo[0]], arr[roo[1]]);
    if(ra > rb)arr[roo[0]].rate = (rb - ra + atan2(0.0, -1.0)*2)/atan2(0.0, -1.0)/2.0 - 0.5;
    else arr[roo[0]].rate = (rb - ra)/atan2(0.0, -1.0)/2.0 - 0.5;
    ra = elevation(arr[roo[count-1]], arr[roo[count-2]]);
    rb = elevation(arr[roo[count-1]], arr[roo[0]]);
    if(ra > rb)arr[roo[count-1]].rate = (rb - ra + atan2(0.0, -1.0)*2)/atan2(0.0, -1.0)/2.0 - 0.5;
    else arr[roo[count-1]].rate = (rb - ra)/atan2(0.0, -1.0)/2.0 - 0.5;
    for(int i = 1;i < count-1;i++){
        ra = elevation(arr[roo[i]], arr[roo[i-1]]);
        rb = elevation(arr[roo[i]], arr[roo[i+1]]);
        if(ra > rb)arr[roo[i]].rate = (rb - ra + atan2(0.0, -1.0)*2)/atan2(0.0, -1.0)/2.0 - 0.5;
        else arr[roo[i]].rate = (rb - ra)/atan2(0.0, -1.0)/2.0 - 0.5;
    }
    for(int i = 0;i < n;i++)printf("%1.9lf\n", arr[i].rate);
    return 0;
}

