/* 角度が [0, pi) に含まれるかどうか */
bool Vector2DInt::Arg_is_less_than_pi() const {
	return y > 0 || (x >= 0 && y >= 0);
}

int Vector2DInt::Compare(const Vector2DInt& left, const Vector2DInt& right) {
	if (left.x > right.x) return 1;
	if (left.x < right.x) return -1;
	if (left.y > right.y) return 1;
	if (left.y < right.y) return -1;
	return 0;
}

/* 偏角で並べる, 偏角が等しいものは同じとみなす(そのため、 set などには使えない) */
int Vector2DInt::CompareArg(const Vector2DInt& left, const Vector2DInt& right) {
	/* ゼロベクトルは最も小さいとする */
	if (left.Is_zero()) return right.Is_zero() ? 0 : -1;
	if (right.Is_zero()) return 1;

	/* どちらか1つの偏角が PI 以上の場合、そちらが大きい */
	bool left_less = left.Arg_is_less_than_pi();
	bool right_less = right.Arg_is_less_than_pi();
	if (left_less && !right_less) return -1;
	if (!left_less && right_less) return 1;

	/* 両方とも PI より小さいか、PI 以上の場合は外積で比較 */
	long long cross = Cross(left, right);
	return -Sign(cross);
}


