int LineSegment::Compare(const LineSegment& left, const LineSegment& right) {
	if (left.start < right.start) return -1;
	if (left.start > right.start) return 1;
	if (left.end < right.end) return -1;
	if (left.end > right.end) return 1;
	return 0;
}

double Distance_segment_vector(const LineSegment& segment, const Vector2DInt& vec) {
	/* start が最も近い */
	if (Dot(segment.end - segment.start, vec - segment.start) <= 0) {
		return (vec - segment.start).Norm();
	}

	/* end が最も近い */
	if (Dot(segment.start - segment.end, vec - segment.end) <= 0) {
		return (vec - segment.end).Norm();
	}

	/* それ以外 → 点と直線の距離 */
	return Distance_line_vector(Line(segment), vec);
}

Vector2DDouble Internal(const LineSegmentDirected& segment, double ratio) {
	return Internal(segment.start, segment.end, ratio);
}

bool Has_Intersection_point(const LineSegment& a, const LineSegment& b) {
	return (int)CCW(a.start, a.end, b.start) * (int)CCW(a.start, a.end, b.end) <= 0
		&& (int)CCW(b.start, b.end, a.start) * (int)CCW(b.start, b.end, a.end) <= 0;
}

