Line::Line()
	: Line(Vector2DInt(1, 0), 0) {
}

Line::Line(int a, int b, int c)
	: Line(Vector2DInt(a, b), c) {
}

Line::Line(const Vector2DInt& normal, int c)
	: normal(normal), c(c) {
	Reduce();
}

/* (x_1, y_1), (x_2, y_2) を通る直線 → 直線 -(y_2 - y_1)x + (x_2 - x_1)y + (x_1 y_2 - x_2 y_1) = 0 */
/* オーバーフロー注意 */
Line::Line(const Vector2DInt& p, const Vector2DInt& q)
	: Line(p.y - q.y, q.x - p.x, Cross(p, q)) {
}

Line::Line(const LineSegment& segment)
	: Line(segment.start, segment.end) {
}

/* 表現を一意にする */
void Line::Reduce() {
	assert(!normal.Is_zero());

	/* normal と c の値は既約とする */
	int gcd = GCD(GCD(abs(normal.x), abs(normal.y)), abs(c));
	if (gcd != 1) {
		normal /= gcd;
		c /= gcd;
	}

	/* 0 <= normal.Arg < PI とする */
	if (!normal.Arg_is_less_than_pi()) {
		normal = -normal;
		c = -c;
	}
}

bool Line::Is_on(const Vector2DRational& point) const {
	return Dot(normal, point) + c == 0;
}

Rational Line::value_y_where_x_is(int x) const {
	const int a = normal.x;
	const int b = normal.y;
	return -(a * x + c) / (Rational)b;
}

Rational Line::value_x_where_y_is(int y) const {
	const int a = normal.x;
	const int b = normal.y;
	return -(b * y + c) / (Rational)a;
}

LineSegment Line::To_segment() const {
	assert(0);
	if (normal.y == 0) {
		// x + c == 0
		return LineSegment(Vector2DInt(-c, 0), Vector2DInt(-c, 1));
	}
	return LineSegment(
		Vector2DInt(0, value_y_where_x_is(0)),
		Vector2DInt(1, value_y_where_x_is(1))
		);
}

int Line::Compare(const Line& left, const Line& right) {
	if (left.normal < right.normal) return -1;
	if (left.normal > right.normal) return 1;
	if (left.c < right.c) return -1;
	if (left.c > right.c) return 1;
	return 0;
}


bool operator==(const Line& left, const Line& right) {
	return Line::Compare(left, right) == 0;
}

bool operator!=(const Line& left, const Line& right) {
	return Line::Compare(left, right) != 0;
}

bool operator<(const Line& left, const Line& right) {
	return Line::Compare(left, right) < 0;
}

bool operator<=(const Line& left, const Line& right) {
	return Line::Compare(left, right) <= 0;
}

bool operator>(const Line& left, const Line& right) {
	return Line::Compare(left, right) > 0;
}

bool operator>=(const Line& left, const Line& right) {
	return Line::Compare(left, right) >= 0;
}


double Distance_line_vector(const Line& line, const Vector2DInt& vec) {
	return abs(Dot(line.normal, vec) + line.c) / line.normal.Norm();
}

/* object を direction 方向に射影 */
Vector2DRational Project(const Vector2DInt& object, const Line& direction) {
	return object - Project(object, direction.normal);
}

Vector2DRational Reflect(const Vector2DInt& object, const Line& axis) {
	return object - axis.normal * (Dot(object, axis.normal) + axis.c) / axis.normal.Norm2();
}

LineSegment Reflect(const LineSegment& object, const Line& axis) {
	const Vector2DRational reflected_start = Reflect(object.start, axis);
	const Vector2DRational reflected_end = Reflect(object.end, axis);
	return LineSegment(reflected_start, reflected_end);
}

/* LineSegment 用の関数を使うのがよさそう */
Line Reflect(const Line& object, const Line& axis) {
	assert(0);
	return Line(Reflect(object.To_segment(), axis));
}

Vector2DRational Intersection_point(const Line& p, const Line& q) {
	Vector2DInt vec_a(p.normal.x, q.normal.x);
	Vector2DInt vec_b(p.normal.y, q.normal.y);
	Vector2DInt vec_c(p.c, q.c);
	long long det = Cross(vec_a, vec_b);
	return Vector2DRational(Cross(vec_b, vec_c) / det, (Cross(vec_c, vec_a) / det));
}

bool Has_Intersection_point(const LineSegment& segment, const Line& line) {
	return Sign(Dot(segment.start, line.normal)) * Sign(Dot(segment.end, line.normal)) <= 0;
}

bool Has_Intersection_point(const Line & line, const LineSegment & segment) {
	return Has_Intersection_point(segment, line);
}

bool Is_orthogonal(const Line& a, const Line& b) {
	return Is_orthogonal(a.normal, b.normal);
}

bool Is_parallel(const Line& a, const Line& b) {
	return Is_parallel(a.normal, b.normal);
