}

void Triangle::Reduce() {
	/* sort */
	if (a > b) std::swap(a, b);
	if (b > c) std::swap(b, c);
	if (a > b) std::swap(a, b);
}

long long Triangle::Area_twice() const {
	return Cross(b - a, c - a);
}

