double sum[100];
using P = complex<double>;
P p[100];

int main(){
	cin.tie(0);
	ios::sync_with_stdio(false);
#ifdef LOCAL
	std::ifstream in("in");
	std::cin.rdbuf(in.rdbuf());
#endif

	int N;
	cin >> N;
	for(int i = 0; i < N; i++){
		double x, y;
		cin >> x >> y;
		p[i] = P(x, y);
	}

	int cnt[100] = { 0 };
	vector<L> ls;
	for(int i = 0; i < N; i++){
		for(int j = i + 1; j < N; j++){
			P c = (p[i] + p[j]) / 2.0;
			P p1 = p[i] - c, p2 = p[j] - c;
			double rad1 = atan2(p1.imag(), p1.real());
			while(rad1 < 0) rad1 += 2 * PI;
			double rad2 = atan2(p2.imag(), p2.real());
			while(rad2 < 0) rad2 += 2 * PI;

			double dx = p1.imag() - p2.imag(), dy = p1.real() - p2.real();
			double rad = atan2(-dx, dy);
			while(rad < 0) rad += 2 * PI;
			if(rad >= PI) rad -= PI;
			assert(0 <= rad && rad < PI);
			if(rad1 < rad2){
				ls.push_back({ rad, i, j });
				ls.push_back({ rad + PI, j, i });
				cnt[j]++;
			}
			else{
				ls.push_back({ rad, j, i });
				ls.push_back({ rad + PI, i, j });
				cnt[i]++;
			}
		}
	}
	sort(ls.begin(), ls.end());

	double r = 0;
	for(auto l : ls){
		{
			int idx = min_element(cnt, cnt + N) - cnt;
			double diff = abs(r - l.rad);
			sum[idx] += diff;
		}

		cnt[l.B]--;
		cnt[l.A]++;
		r = l.rad;
	}
	{
		int idx = min_element(cnt, cnt + N) - cnt;
		double diff = 2 * PI - r;
		sum[idx] += diff;
	}

	for(int i = 0; i < N; i++){
		cout << fixed << setprecision(15) << sum[i] / (2 * PI) << endl;
	}
}

