    cout << 0.50 << endl;
    return 0;
  }

  VP B = convexHull(A);
  vector<double> ans(N, 0);
  ll M = B.size();
  REP(i, M) {
    ll index = 0;
    REP(j, N) if (A[j] == B[i]) index = j;
    D po = get_kakudo(B[i], B[(i - 1 + M) % M]);
    D yo = get_kakudo(B[(i + 1) % M], B[i]);

    D uo = yo - po;
    if (uo < 0)
      uo += 2 * M_PI;
    ans[index] = uo / (2 * M_PI);
  }
  REP(i, N) { cout << SP(20) << ans[i] << endl; }
  return 0;
}

