using namespace std;

template<class T>
vector<int> convex(vector<T> x, vector<T> y)
{
    int n = (int)x.size();
    vector<pair<pair<T,T>, int>> Pt(n);
    for (int i=0; i<n; i++)
        Pt[i] = make_pair(make_pair(x[i], y[i]), i);
    sort(Pt.begin(), Pt.end());
    vector<int> P(n);
    for (int i=0; i<n; i++)
        P[i] = Pt[i].second;

    vector<int> ans;
    ans.push_back(P[0]);
    ans.push_back(P[1]);
    for (int i=2; i<n; i++)
    {
        int t = (int)ans.size();
        T p = (x[P[i]]-x[ans[t-1]])*(y[ans[t-1]]-y[ans[t-2]])
            - (x[ans[t-1]]-x[ans[t-2]])*(y[P[i]]-y[ans[t-1]]);
        if (p < 0)
            ans.pop_back();
        ans.push_back(P[i]);
    }
    ans.push_back(P[n-2]);
    for (int i=n-3; i>=0; i--)
    {
        int t = (int)ans.size();
        T p = (x[P[i]]-x[ans[t-1]])*(y[ans[t-1]]-y[ans[t-2]])
            - (x[ans[t-1]]-x[ans[t-2]])*(y[P[i]]-y[ans[t-1]]);
        if (i!=0)
            ans.push_back(P[i]);
    }
    ans.pop_back();
    return ans;
}

int main()
{
    int N;
    cin>>N;
    vector<double> x(N), y(N);
    for (int i=0; i<N; i++)
        cin>>x[i]>>y[i];

    vector<int> C = convex(x, y);
    int cn = (int)C.size();
    vector<double> ans(N);
    double pi = acos(-1.0);
    for (int i=0; i<cn; i++)
    {
        double x0 = x[C[(i+cn-1)%cn]] - x[C[i]];
        double y0 = y[C[(i+cn-1)%cn]] - y[C[i]];
        double x1 = x[C[(i+1)%cn]] - x[C[i]];
        double y1 = y[C[(i+1)%cn]] - y[C[i]];
        double s = acos((x0*x1+y0*y1)/hypot(x0,y0)/hypot(x1,y1));
        ans[C[i]] = (pi-s)/(2*pi);
    }
    for (double a: ans)
        printf("%.20f\n", a);
}

