	  }
	  else{
		cout << 0.5 << endl;
	  }
	}

	return 0;
  }

  REP(i,N){
	int ix = find(ALL(ps_), ps[i]) - begin(ps_);
	if(ix == M){
	  cout << 0. << endl;
	}
	else{
	  Vector v1 = ps_[ix] - ps_[(ix+M-1)%M];
	  Vector v2 = ps_[(ix+1)%M] - ps_[ix];
	  v1.normalize();
