int main() {
  int n; scanf("%d", &n);
  int x[n], y[n];
  rep (i, n) {
    scanf("%d%d", &x[i], &y[i]);
  }
  int cnt[n];
  rep (i, n) cnt[i] = 0;
  int max_sep = 1000000;
  rep (i, max_sep) {
    double theta = M_PI * 2 * i / max_sep;
    double cos_t = cos(theta);
    double sin_t = sin(theta);
    int ind = -1;
    double max_value = -1e10;
    rep (j, n) {
      double value = x[j] * cos_t + y[j] * sin_t;
      if (value > max_value) {
        ind = j;
        max_value = value;
      }
    }
    assert(ind != -1);
    cnt[ind] += 1;
  }
  rep (i, n) {
    print((double)cnt[i] / max_sep);
  }

  return 0;
}

