double norm(P p){
    return sqrt(pow(p.first.first,2)+pow(p.first.second,2));
}
double vector_length(P p){
    return pow(p.first.first*p.first.first+p.first.second*p.first.second,0.5);
}

double cos_(P p1,P p2){
    if(vector_length(p1)*vector_length(p2)==0) return 0;
    return dot(p1,p2)/(vector_length(p1)*vector_length(p2));
}


int ccw(P p0,P p1,P p2){ //p0p1が基準
    p1.first.first -= p0.first.first;
    p1.first.second -= p0.first.second;
    p2.first.first -= p0.first.first;
    p2.first.second -= p0.first.second;

    if(cross(p1,p2) > 0) return 1; // counter_clockwise
    if(cross(p1,p2) < 0) return -1; // clockwise
    if(dot(p1,p2)<0) return 2 ;//on_line back
    if(norm(p1)<norm(p2)) return -2; //on_line front
    return 3; // on_segment
}

void pri(P p){
    cout << p.first.first << "  " << p.first.second << endl;
}


vector<P> convex_hull(vector<P> ps){

    for(int i = 0; i < ps.size(); i++){
        double x = ps[i].first.first;
        ps[i].first.first = ps[i].first.second;
        ps[i].first.second = x;
    }
    sort(all(ps));
    for(int i = 0; i < ps.size(); i++){
        double x = ps[i].first.first;
        ps[i].first.first = ps[i].first.second;
        ps[i].first.second = x;
    }
    int n = ps.size(),k=0;
    vector<P> ch(n*2);
    for(int i = 0; i < n; i++){
        while(k>=2 && ccw(ch[k-2],ch[k-1],ps[i])< 0) k--;
        ch[k] = ps[i];
        k++;
    }
    int t = k+1;
    for(int i = n-2; i >= 0; i--){
        while(k >= t && ccw(ch[k-2],ch[k-1],ps[i])< 0) k--;
        ch[k] = ps[i];
        k++;
    }

    ch.resize(k-1);
    return ch;
}

