struct Point {
    coord_t x, y;

    bool operator <(const Point &p) const {
        return x < p.x || (x == p.x && y < p.y);
    }
};

// 2D cross product of OA and OB vectors, i.e. z-component of their 3D cross product.
// Returns a positive value, if OAB makes a counter-clockwise turn,
// negative for clockwise turn, and zero if the points are collinear.
coord2_t cross(const Point &O, const Point &A, const Point &B)
{
    return (A.x - O.x) * (B.y - O.y) - (A.y - O.y) * (B.x - O.x);
}

// Returns a list of points on the convex hull in counter-clockwise order.
// Note: the last point in the returned list is the same as the first one.
vector<Point> convex_hull(vector<Point> P)
{
    ll n = P.size(), k = 0;
    if (n <= 3) return P;
    vector<Point> H(2*n);

    // Sort points lexicographically
    sort(P.begin(), P.end());

    // Build lower hull
    for (ll i = 0; i < n; ++i) {
        while (k >= 2 && cross(H[k-2], H[k-1], P[i]) <= 0) k--;
        H[k++] = P[i];
    }

    // Build upper hull
    for (ll i = n-1, t = k+1; i > 0; --i) {
        while (k >= t && cross(H[k-2], H[k-1], P[i-1]) <= 0) k--;
        H[k++] = P[i-1];
    }

    H.resize(k-1);
    return H;
}

double ang(Point s, Point t,Point u){
    Point x,y;
    x=Point{s.x-t.x,s.y-t.y};
    y=Point{u.x-t.x,u.y-t.y};
    double T=((x.x*y.x+x.y*y.y)/(sqrt(x.x*x.x+x.y*x.y)*sqrt(y.x*y.x+y.y*y.y))>=1?double(1):(x.x*y.x+x.y*y.y)/(sqrt(x.x*x.x+x.y*x.y)*sqrt(y.x*y.x+y.y*y.y)));
    return acos(T);
}
