namespace VEC {

	//EPSを考慮した足し算
	double add(const double a, const double b) {
		if (abs(a + b)<EPS*(abs(a) + abs(b))) { return 0; }
		return a + b;
	}

	class P {
	public:
		double x, y;
		int index;
		double prob;
		P() {}
		P(double x_, double y_) :x(x_), y(y_) {}
		P operator +(const P p) {
			return P(add(x, p.x), add(y, p.y));
		}
		P operator -(const P p) {
			return P(add(x, -p.x), add(y, -p.y));
		}
		P operator *(const double  d) {
			return P(x*d, y*d);
		}
		double dot(const P p) {
			return add(x*p.x, y*p.y);
		}
		double det(const P p) {
			return add(x*p.y, -y * p.x);
		}

		double norm() {
			return sqrt(add(x*x, y*y));
		}

	};

	//線分p1-p2上にqがあるか
	bool on_seg(P p1, P p2, P q) {
		return (p1 - q).det(p2 - q) == 0 && (p1 - q).dot(p2 - q) <= 0;
	}
	//直線p1-p2と直線q1-q2の交点
	P intersection(P p1, P p2, P q1, P q2) {
		return p1 + (p2 - p1)*((q2 - q1).det(q1 - p1) / (q2 - q1).det(p2 - p1));
	}

	//-----凸包を求めるためのコード---------------------
	bool cmp_x(const P& p, const P& q) {
		if (p.x != q.x)return p.x<q.x;
		return p.y<q.y;
	}

	//凸包の外辺を求める。
	vector<P> convex_hull(vector<P> ps) {
		int n = SZ(ps);
		sort(ps.begin(), ps.end(), cmp_x);//昇順ソート
		int k = 0;//凸包の頂点数
		vector<P> qs(n * 2);//構成中の凸包

							//下向き凸包の作成
		for (int i = 0; i<n; i++) {

			//kは毎回インクリメントされているのでk-1が最後に集合に追加された頂点になる。
			//新しく頂点を追加したらへこんだ部分を取り除く（これは繰り返される）
			//右ネジの逆方向であればそれはへこんでいるということになる
			while (k>1 && (qs[k - 1] - qs[k - 2]).det(ps[i] - ps[k - 1]) <= 0) { k--; }
			//最初の一個(index 0)と最後の一個(index n-1)は無条件で追加される
			qs[k++] = ps[i];
		}

		//上向き凸包の作成
		for (int i = n - 2, t = k; i >= 0; i--) {
			while (k>t && (qs[k - 1] - qs[k - 2]).det(ps[i] - qs[k - 1]) <= 0) { k--; }
			qs[k++] = ps[i];
		}

		//assert(k>0);
		//kを巻き戻しているのでresizeする必要がある
		qs.resize(k - 1);
		return  qs;
	}

	//反時計回りソート
	vector<P> sort_convex_hull(vector<P> ps) {
		int N = SZ(ps);
		//重心の計算
		P center(0, 0);
		REP(i, N) {
			center=center + ps[i];
		}
		center.x /= N,center.y/=N;

		//ソート
		vector< pair<double, int> > order(N);
		REP(i, N) {
			P a = ps[i] - center;
			order[i] = MP(atan2(a.y, a.x), i);
		}
		SORT(order);

		vector<P> res(N);
		REP(i, N) {
			res[i] = ps[order[i].second];
		}
		return res;
	}


	//距離の2乗
	double dist2(P p, P q) {
		return (p - q).dot(p - q);
	}
	//距離
	double dist(P p, P q) {
		return sqrt(dist2(p, q));
	}
	//2つのベクトルのなす角
	double rad(P p, P q) {
		return acos(p.dot(q) / (p.norm()*q.norm()));
	}
};


int main() {

	int N;
	cin >> N;
	vector<VEC::P> input(N);
	REP(i, N) {
		cin >> input[i].x >> input[i].y;
		input[i].index = i;
		input[i].prob = 0.0;
	}

	vector<VEC::P> qs=VEC::convex_hull(input);
	int K = SZ(qs);
	if (K ==2) {
		REP(i, SZ(qs)) {
			qs[i].prob = 0.5;
			input[qs[i].index].prob = 0.5;
		}
		goto PRINTANS;
	}
	qs = VEC::sort_convex_hull(qs);
	for (int i = 0; i < qs.size(); i++) {
		int j = (K + i - 1) % K;
		int k = (K + i + 1) % K;

		qs[i].prob = rad(qs[i] - qs[j], qs[k] - qs[i]) / (2 * PI);
		input[qs[i].index].prob = qs[i].prob;

	}
PRINTANS:;
	REP(i, SZ(input)) {
		cout <<fixed<<setprecision(10)<< input[i].prob << endl;
	}
	return 0;
}

