int main() {
  int n;
  cin >> n;
  vector<pair<double, double>> ps(n);
  for (int i = 0; i < n; i++)
    cin >> ps[i].first >> ps[i].second;
  vector<double> ans(n);
  mt19937 mt(10);
  long long m = 1000000;
  for (int i = 0; i < m; i++) {
    double theta = (double)mt();
    double x = cos(theta) * 100000000000, y = sin(theta) * 100000000000;
    int id = 0;
    double minP = -1;
    for (int j = 0; j < n; j++) {
      double dist = (ps[j].first - x) * (ps[j].first - x) +
                    (ps[j].second - y) * (ps[j].second - y);
      if (dist < minP || minP < 0) {
        minP = dist;
        id = j;
      }
    }
    ans[id] += 1;
  }
  for (int i = 0; i < n; i++) {
    printf("%.6lf\n", ans[i] / m);
  }
  return 0;
}

