using namespace std;
using LL = long long;

int N;
LL x[123], y[123];
int flag[123];
int maxf[123];
int minf[123];
long double ans[123];

const long double PI = acos(-1);

int main(void)
{
	cin >> N;
	for (int i = 0; i < N; ++i) {
		cin >> x[i] >> y[i];
	}
	vector<pair<double, pair<int, int>>>vec;
	for (int i = 0; i < N; ++i) {
		for (int j = 0; j < N; ++j) {
			if (i == j)continue;
			LL dx = x[i] - x[j];
			LL dy = y[i] - y[j];
			auto angle = atan2(dy, dx);
			angle += PI;
			angle += (PI / 2);
			if (angle >= PI * 2) {
				angle -= PI * 2;
			}
			vec.push_back({ angle,{i,j} });
		}
	}
	sort(vec.begin(), vec.end());
	fill(maxf, maxf + 123, -123456);
	fill(minf, minf + 123, 123456);
	for (auto elm : vec) {
		int in = elm.second.first;
		int out = elm.second.second;
		flag[in]++;
		flag[out]--;
		maxf[in] = max(maxf[in], flag[in]);
		maxf[out] = max(maxf[out], flag[out]);
		minf[in] = min(minf[in], flag[in]);
		minf[out] = min(minf[out], flag[out]);
	}
	int i = 0;
	int M = vec.size();
	for (auto elm : vec) {
		int in = elm.second.first;
		int out = elm.second.second;
		flag[in]++;
		flag[out]--;
		for (int x = 0; x < N;++x) {
			if (flag[x] == maxf[x]) {
				if (i + 1 == M) {
					ans[x] += vec[(i + 1) % M].first - vec[i].first + 2 * PI;
				}
				else {
					ans[x] += vec[(i + 1) % M].first - vec[i].first;
				}
			}
		}
		i++;
	}
	cout.precision(15);
	for (int x = 0; x < N; ++x) {
		ans[x] /= (2 * PI);
		if (N - 1 != maxf[x] - minf[x]) {
			ans[x] = 0;
		}
		cout << ans[x] << endl;
	}
	return 0;
}

