        double m2 = atan2(next.y - now.y, next.x - now.x);
        if(m2 < m1) m2 += 2.0 * PI;
        double tn = m2 - m1 - PI;
        if(tn < -EPS) tn += PI;
        if(tn > PI) tn -= PI;
        assert(-EPS <= tn && tn <= PI);
        double tmp = tn / (2.0 * PI);
        ans[id] = tmp;
    }
    rep(i, 0, n){
        printf("%.15f\n", ans[i]);
    }
}

