}

bool eq(C c1, C c2)
{
    return (eq(c1.real(), c2.real()) && eq(c1.imag(), c2.imag()));
}

//条件付きsqrt
LD Sqrt(LD x)
{
    if (x < 0)
        return 0;
    else
        return sqrt(x);
}

//正規化
C normalize(C c)
{
    return c / abs(c);
}

//角度(rad)
LD getarg(C a, C b)
{
    return arg(b * conj(a));
}

//外積
LD cross(const C a, const C b)
{
    return imag(conj(a) * b);
}
//内積
LD dot(const C a, const C b)
{
    return real(conj(a) * b);
}

int ccw(C a, C b, C c)
{
    b -= a;
    c -= a;
    if (cross(b, c) > 0)
        return +1;  // counter clockwise
    if (cross(b, c) < 0)
        return -1;  // clockwise
    if (dot(b, c) < 0)
        return +2;  // c--a--b on line
    if (norm(b) < norm(c))
        return -2;  // a--b--c on line
    return 0;       //b--a--c on line
}
