short int GetSign(LL val) {
    if (val == 0) return 0;
    return (val > 0) - (val < 0);
}

short int RelativePosition(const Point& O,const Point& A,const Point& B){
    return GetSign((A-O)^(B-O));
}

vector<int> ConvexHull(const vector<Point>& points){
    int N = points.size();
    vector <int> sorted_indexes(N);
    for (int i = 0; i < (int)sorted_indexes.size(); i++) sorted_indexes[i] = i;

    // Sorting from south to north (and from west to east) the points.
    sort(sorted_indexes.begin(), sorted_indexes.end(),
        [&points](int i, int j) {
            return points[i] < points[j];
        });

    // All points are equal.
    if (points[sorted_indexes[0]] == points[sorted_indexes.back()]) return {0};

    vector<int> anticlockwise, clockwise;
    anticlockwise.push_back(sorted_indexes[0]);
    clockwise.push_back(sorted_indexes[0]);

    for (int i = 1; i < N; i++) {
        // Finds the convex hull of the first i+1 points.
        int index = sorted_indexes[i];
        Point V = points[index];

        // Comparing V with the line generated by the last two points in
        // the anticlockwise array.
        while (anticlockwise.size() > 1 and
               RelativePosition(points[anticlockwise.rbegin()[1]], V,
                                points[anticlockwise.back()]) != -1) {
            anticlockwise.pop_back();
        }
        anticlockwise.push_back(index);

        // Comparing V with the line generated by the last two points in
        // the clockwise array.
        while (clockwise.size() > 1 and
               RelativePosition(points[clockwise.rbegin()[1]], V,
                                points[clockwise.back()]) != 1) {
            clockwise.pop_back();
        }
        clockwise.push_back(index);
    }

    // Joining anticlockwise and clockwise in a single vector.
    anticlockwise.pop_back();
    reverse(clockwise.begin(), clockwise.end());
    clockwise.pop_back();
    anticlockwise.insert(anticlockwise.end(), clockwise.begin(), clockwise.end());
    return anticlockwise;
}

