	for (int i = 0; i < N; i++) cin >> x[i][0] >> x[i][1];
	vector<vector<vector<double>>> normal(N, vector<vector<double>>(0, vector<double>(2)));
	for (int i = 0; i < N - 1; i++) {
		for (int j = i + 1; j < N; j++) {
			vector<double> dx(2);
			dx[0] = x[i][0] - x[j][0];
			dx[1] = x[i][1] - x[j][1];
			normal[j].push_back(dx);
			dx[0] *= -1;
			dx[1] *= -1;
			normal[i].push_back(dx);
		}
	}
	vector<vector<double>> dead_r(N, vector<double>(2, 0.0));
	vector<vector<double>> dead_l(N, vector<double>(2, pi));
	for (int i = 0; i < N; i++) {
		for (int j = 0; j < normal[i].size(); j++) {
			double theta;
			theta = atan2(normal[i][j][0], normal[i][j][1]);
			if (fabs(theta) > pi / 2.0) {
				theta = fmod(theta + 2.0 * pi, 2.0 * pi);
				dead_l[i][0] = min(dead_l[i][0], theta - pi / 2.0);
				dead_l[i][1] = max(dead_l[i][1], theta + pi / 2.0);
			}
			else {
				dead_r[i][0] = min(dead_r[i][0], theta - pi / 2.0);
				dead_r[i][1] = max(dead_r[i][1], theta + pi / 2.0);
			}
		}
		if (dead_r[i][1] >= dead_l[i][0]) {
			dead_r[i][1] = pi / 2.0;
			dead_l[i][0] = pi / 2.0;
		}
		if (dead_l[i][1] >= dead_r[i][0] + 2.0 * pi) {
			dead_l[i][1] = 3.0 * pi / 2.0;
			dead_r[i][0] = -pi / 2.0;
		}
		cout << setprecision(15) << (2.0 * pi - (dead_r[i][1] - dead_r[i][0] + dead_l[i][1] - dead_l[i][0])) / (2.0 * pi) << endl;
	}

	system("pause");
	return 0;
}

