            Vector2D A={(key[1].x-key[0].x)/2,(key[1].y-key[0].y)/2};
            Vector2D B={(key[0].x-key[key.size()-1].x)/2,(key[0].y-key[key.size()-1].y)/2};
            ans[l]=AngleOf2Vector(A,B)/360.0;
        }
