using Real = double;
constexpr Real eps = 1e-10;
constexpr Real pi = acos(-1.0L);
constexpr Real to_rad(int deg) { return Real(deg) * pi / 180; }
constexpr Real to_deg(Real rad) { return rad * 180 / pi; }

pair<Real,Real> intersection(vector<pair<Real,Real>> seg) {
    if (seg.empty()) return {0,2*pi};
    for (auto &[l,r] : seg) if (l < 0) l += 2*pi, r += 2*pi;
    auto [L,R] = seg[0];
    for (auto [l,r] : seg) {
        bool ok = false;
        for (auto k : {-1,0,+1}) {
            Real nl = l + 2*pi*k;
            Real nr = r + 2*pi*k;
            if (nl < R && L < nr) {
                ok = true;
                L = clamp(L,nl,nr);
                R = clamp(R,nl,nr);
                break;
            }
        }
        if (not ok) return {0,0};
    }
    return {L,R};
}

