int main() {
	int n; std::cin >> n;
	std::vector<Point> points(n);
	for (auto i = 0; i < n; ++i) {
		std::cin >> points[i].x >> points[i].y;
		points[i].id = i;
	}
	if (n == 2) {
		std::cout << "0.5\n0.5\n";
		return 0;
	}
	std::sort(points.begin(), points.end(), [](const Point& a, const Point& b) {return a.x < b.x; });
	std::vector<Point> stack;
	for (const Point& p : points) {
		while (stack.size() >= 2 && ((stack[stack.size() - 1] - stack[stack.size() - 2]).cross(p - stack[stack.size() - 1]) > 0 || ((stack[stack.size() - 1] - stack[stack.size() - 2]).cross(p - stack[stack.size() - 1]) == 0 && (stack[stack.size() - 1] - stack[stack.size() - 2]).dot(p - stack[stack.size() - 1]) >= 0))) {
			stack.pop_back();
		}
		stack.push_back(p);
	}
	for (auto itr = std::next(points.rbegin()); itr != points.rend(); ++itr) {
		auto p = *itr;
		while (stack.size() >= 2 && ((stack[stack.size() - 1] - stack[stack.size() - 2]).cross(p - stack[stack.size() - 1]) > 0 || ((stack[stack.size() - 1] - stack[stack.size() - 2]).cross(p - stack[stack.size() - 1]) == 0 && (stack[stack.size() - 1] - stack[stack.size() - 2]).dot(p - stack[stack.size() - 1]) >= 0))) {
			stack.pop_back();
		}
		stack.push_back(p);
	}
	stack.pop_back();
	std::vector<double> probability(n, 0);
	for (auto i = 0; i < stack.size(); ++i) {
		const auto prev = stack[(i + stack.size() - 1) % stack.size()];
		const auto current = stack[i];
		const auto next = stack[(i + 1) % stack.size()];
		const auto left = prev - current;
		const auto right = current - next;
		probability[current.id] = std::abs(std::atan2(right.cross(left), right.dot(left)));
	}
	const auto pi = std::acos(-1);
	std::cout << std::setprecision(9) << std::fixed;
	for (const auto prob : probability) {
		std::cout << prob / 2 / pi << '\n';
	}
}

