struct pt {
	double x, y;
	int it;
	double an = 0;
	pt(double x, double y, int it): x(x), y(y), it(it){}
};

bool cmp (pt a, pt b) {
	return a.x < b.x || a.x == b.x && a.y < b.y;
}

bool cw (pt a, pt b, pt c) {
	return a.x*(b.y-c.y)+b.x*(c.y-a.y)+c.x*(a.y-b.y) < 0;
}

bool ccw (pt a, pt b, pt c) {
	return a.x*(b.y-c.y)+b.x*(c.y-a.y)+c.x*(a.y-b.y) > 0;
}

void convex_hull (vector<pt> & a) {
	if (a.size() == 1)  return;
	sort (a.begin(), a.end(), &cmp);
	pt p1 = a[0],  p2 = a.back();
	vector<pt> up, down;
	up.push_back (p1);
	down.push_back (p1);
	for (size_t i=1; i<a.size(); ++i) {
		if (i==a.size()-1 || cw (p1, a[i], p2)) {
			while (up.size()>=2 && !cw (up[up.size()-2], up[up.size()-1], a[i]))
				up.pop_back();
			up.push_back (a[i]);
		}
		if (i==a.size()-1 || ccw (p1, a[i], p2)) {
			while (down.size()>=2 && !ccw (down[down.size()-2], down[down.size()-1], a[i]))
				down.pop_back();
			down.push_back (a[i]);
		}
	}
	a.clear();
	for (size_t i=0; i<up.size(); ++i)
		a.push_back (up[i]);
	for (size_t i=down.size()-2; i>0; --i)
		a.push_back (down[i]);
}

double getdist(pt a, pt b){
    return sqrt((a.x - b.x) * (a.x - b.x) + (a.y - b.y) * (a.y - b.y));
}
double an[100];

main()
{
    ios_base::sync_with_stdio(0);
    int n;
    cin >> n;
    vector<pt> a;
    for(int i = 0; i < n; i++){
        int x, y;
        cin >> x >> y;
        a.push_back(pt(x, y, i));
    }
    convex_hull(a);
    const double pi = atan2(0, -1);
    int t = a.size();
    for(int i = 0; i < t; i++){
        int j, k;
        j = (i == 0) ? t - 1 : i - 1;
        k = (i == t - 1) ? 0 : i + 1;
        double sum = 0;
        double A = getdist(a[i], a[j]);
        double B = getdist(a[i], a[k]);
        double C = getdist(a[j], a[k]);
        sum = acos((A*A+B*B-C*C)/(2*A*B));
        an[a[i].it] = (pi - sum) / (2 * pi);
    }
    cout << fixed << setprecision(12);
    for(int i = 0; i < n; i++) cout << an[i] << endl;
}

