using namespace std;

const double EPS = 10e-10;
const double pi = 3.14159265358979;

double add(double a, double b){
    if(abs(a+b) < EPS*(abs(a)+abs(b))) return 0;
    return a+b;
}

struct P{
    double x, y;
    P(){}
    P(double x, double y) :x(x), y(y){}
    P operator + (P p){
        return P(add(x, p.x), add(y, p.y));
    }
    P operator - (P p){
        return P(add(x, -p.x), add(y, -p.y));
    }
    P operator * (double d){
        return P(x*d, y*d);
    }
    double dot(P p){
        return add(x*p.x, y*p.y);
    }
    double det(P p){
        return add(x*p.y, -y*p.x);
    }
};

bool comp_x(const P& p, const P& q){
    if(p.x != q.x) return p.x < q.x;
    return p.y < q.y;
}

double dist(P p, P q){
    return (p-q).dot(p-q);
}

vector<P> convex_hull(P* ps, int n){
    sort(ps, ps+n, comp_x);
    int k = 0;
    vector<P> qs(n*2);
    for(int i = 0; i < n; i++){
        while(k > 1 && (qs[k-1] - qs[k-2]).det(ps[i] - qs[k-1]) <= 0) k--;
        qs[k++] = ps[i];
    }
    for(int i = n-2, t = k; i >= 0; i--){
        while(k > t && (qs[k-1] - qs[k-2]).det(ps[i] - qs[k-1]) <= 0) k--;
        qs[k++] = ps[i];
    }
    qs.resize(k-1);
    return qs;
}

int main(){
    int N;
    P p[100];
    P q[100];
    cin >> N;
    for(int i = 0; i <  N; i++){
        cin >> p[i].x >> p[i].y;
        q[i].x = p[i].x;
        q[i].y = p[i].y;
    }
    if(N == 2){
        cout << 0.5 << endl;
        cout << 0.5 << endl;
        return 0;
    }
    vector<P> conv = convex_hull(p, N);
    int n = conv.size();
    vector<double> prob(n);
    for(int i = 1; i <= n-2; i++){
        double inner_prod = (conv[i-1]-conv[i]).dot(conv[i+1]-conv[i]);
        double norm = sqrt(dist(conv[i-1], conv[i])*dist(conv[i+1], conv[i]));
        prob[i] = (pi - acos(inner_prod/norm))/(2*pi);
    }
    double inner_prod = (conv[n-1]-conv[0]).dot(conv[1]-conv[0]);
    double norm = sqrt(dist(conv[n-1], conv[0])*dist(conv[1], conv[0]));
    prob[0] = (pi - acos(inner_prod/norm))/(2*pi);
    inner_prod = (conv[n-2]-conv[n-1]).dot(conv[0]-conv[n-1]);
    norm = sqrt(dist(conv[n-2], conv[n-1])*dist(conv[0], conv[n-1]));
    prob[n-1] = (pi - acos(inner_prod/norm))/(2*pi);

    for(int i = 0; i < N; i++){
        //cout << i << ' ' << q[i].x << ' ' << q[i].y << endl;
        for(int j = 0; j < n; j++){
            if(q[i].x == conv[j].x && q[i].y == conv[j].y){
                //cout << conv[j].x << ' ' << conv[j].y << endl;
                cout << prob[j] << endl;
                break;
            }
            if(j == n-1){
                cout << 0 << endl;
            }
        }
    }
}

