const double PI = 3.14159265358979323;

double cross(Point a, Point b) {
	return a.real() * b.imag() - a.imag() * b.real();
}

double dot(Point a, Point b) {
	return a.real() * b.real() + a.imag() * b.imag();
}

bool isOn(Point s, Point e, Point p) {
	if (cross(e - s, p - s) != 0) return false;
	return dot(p - s, p - e) <= 0;
}

int n;
Point p[100];

bool isInTriangle(int id) {
	int i, j, k;
	for (i = 0; i < n; i++) {
		if (i == id) continue;
		for (j = i + 1; j < n; j++) {
			if (j == id) continue;
			for (k = j + 1; k < n; k++) {
				if (k == id) continue;
				if (cross(p[j] - p[i], p[k] - p[i]) == 0) continue;
				if (isOn(p[i], p[j], p[id])) { return true; }
				if (isOn(p[j], p[k], p[id])) { return true; }
				if (isOn(p[k], p[i], p[id])) { return true; }
				double a = cross(p[j] - p[i], p[id] - p[i]);
				double b = cross(p[k] - p[j], p[id] - p[j]);
				double c = cross(p[i] - p[k], p[id] - p[k]);
				if (a < 0 && b < 0 && c < 0) { return true; }
				if (a > 0 && b > 0 && c > 0) { return true; }
			}
		}
	}
	return false;
}

signed main() {
	int i, j, k;

	cin >> n;
	rep(i, n) {
		int x, y;
		cin >> x >> y;
		p[i] = Point((double)x, (double)y);
	}

	double su = 0;
	rep(i, n) {
		if (isInTriangle(i)) { cout << 0 << endl; continue; }

		vector<Point> vs;
		rep(j, n) {
			if (j == i) continue;
			//p[i] -- p[j]の垂直2等分線の向きを考える.
			Point mul = (p[j] - p[i]) * Point(0, 1);
			Point mid = (p[i] + p[j]) * (double)0.5;
			if (cross(mul, p[i] - mid) < 0) {
				mul *= (-1);
			}
			//単位化しておく
			mul /= abs(mul);
			vs.push_back(mul);
		}

		double minDot = 1;
		for (j = 0; j < (int)vs.size(); j++) {
			for (k = j + 1; k < (int)vs.size(); k++) {
				double score = dot(vs[j], vs[k]);
				minDot = min(minDot, score);
			}
		}
		//内積から角度を出す -> ここで内積を逆転させて、argcosする
		double rad = acos(minDot);
		double ans = (PI - rad) / (2.0 * PI);
		su += ans;
		printf("%.20Lf\n", ans);
	}
	if (!(0.10 < su && su < 10.00)) assert(0);
	return 0;
}

