inline pair<Point,Point> crossPoint(Circle c1,Circle c2){
    assert(dis(c1.c,c2.c)<c1.r+c2.r+EPS);
    DD d=dis(c1.c,c2.c);
    DD a=acos((c1.r*c1.r+d*d-c2.r*c2.r)/(2*c1.r*d));
    DD t=arg(c2.c-c1.c);
    return make_pair(c1.c+polar(c1.r,t+a),c1.c+polar(c1.r,t-a));
}

//pがcの外にあるかの判定が必要
inline pair<Point,Point> TanLine(Point &p,Circle &c){
    DD d=dis(p,c.c);
    assert(d>c.r-EPS);
    if(eq(d,c.r)) return make_pair(p,p);
    return crossPoint(c,Circle(p,sqrt(d*d-c.r*c.r)));
}

//https://ei1333.github.io/luzhiled/snippets/geometry/template.html
//↑すごい。丸写し
//円c1,c2の共通接線
//接点をつないで線にしている(１個だけ追加するときに注意)
vector<Line> TanLine(Circle c1,Circle c2){
    vector<Line> ret;
    if(c1.r<c2.r) swap(c1,c2);
    DD g=dis(c1.c,c2.c);
    if(eq(g,0)) return ret;
    Vector u=(c2.c-c1.c)/g;
    Vector v=rotate(u,PI*0.5);
    for(int s:{-1,1}){
        DD h=(c1.r+s*c2.r)/g;
        if(eq(1-h*h,0)){
            ret.emplace_back(c1.c+u*c1.r,c1.c+(u+v)*c1.r);
        }else if(1-h*h>0){
            Vector uu=u*h,vv=v*sqrt(1-h*h);
            ret.emplace_back(c1.c+(uu+vv)*c1.r,c2.c-(uu+vv)*c2.r*s);
            ret.emplace_back(c1.c+(uu-vv)*c1.r,c2.c-(uu-vv)*c2.r*s);
        }
    }
    return ret;
}

