		return 0;
	}

	std::vector<P> ps(n);
	REP(i, n) ps[i] = P(x[i], y[i]);
	auto p = convex_hull(ps);
	int sz = p.size();

	std::vector<double> ans(n, 0.0);
	REP(i, sz) {
		double a1 = real(p[(i + 0) % sz]) - real(p[(i + 1) % sz]);
		double a2 = imag(p[(i + 0) % sz]) - imag(p[(i + 1) % sz]);
		double b1 = real(p[(i + 2) % sz]) - real(p[(i + 1) % sz]);
		double b2 = imag(p[(i + 2) % sz]) - imag(p[(i + 1) % sz]);

		double theta = -(a1*b1 + a2 * b2) / (std::sqrt(a1*a1 + a2 * a2) * std::sqrt(b1*b1 + b2 * b2));
		double t = std::acos(theta);

		{
			double min = 1e308;
