template<typename T>
struct vec2D{
	T x, y;

	vec2D<T> operator+(const vec2D<T> &v) const{
		return vec2D<T>({x + v.x, y + v.y});
	}
	vec2D<T> operator-(const vec2D<T> &v) const{
		return vec2D<T>({x - v.x, y - v.y});
	}
	vec2D<T> operator*(const T &d) const{
		return vec2D({x * d, y * d});
	}
	bool operator==(const vec2D<T> &v) const{
		return x == v.x && y == v.y;
	}
	bool operator<(const vec2D<T> &v) const{
		if(x != v.x) return x < v.x;
		return y < v.y;
	}
	bool operator>(const vec2D<T> &v) const{
		if(x != v.x) return x > v.x;
		return y > v.y;
	}
	T inner(const vec2D<T> &v) const{
		return x * v.x + y * v.y;
	}
	T outer(const vec2D<T> &v) const{
		return x * v.y - y * v.x; 
	}
};

