		int nx = i + 1 == st.size() ? 0 : i + 1;
		ans[st[i].ind] = arg((st[nx] - st[i]).mycp / (st[i] - st[pr]).mycp) / M_PI / 2;
	}
	for (auto& x : ans)
		cout << x << '\n';
}

