struct v2
{
    double x = 0;
    double y = 0;

    bool operator==(const v2& v)const
    {
        return x == v.x && y == v.y;
    }

    v2 operator+(const v2& v) const
    {
        return {x + v.x, y + v.y};
    }

    v2 operator-(const v2& v) const
    {
        return {x - v.x, y - v.y};
    }

    double dot(const v2& v) const
    {
        return x*v.x + y*v.y;
    }

    double angle(const v2& v) const
    {
        return acos(dot(v) / (length() * v.length()));
    }

    double length() const
    {
        return hypot(x, y);
    }

    v2 unit() const
    {
        auto l = length();
        return { x / l, y / l };
    }
};

ostream& operator<<(ostream& os, const v2& v)
{
    return os << '(' << v.x << ',' << v.y << ')';
}

namespace std {
    template <>
    class hash<v2> {
    public:
        size_t operator()(const v2& v) const{
            return hash<double>()(v.x) ^ hash<double>()(v.y);
        }
    };
}


int main()
{
    size_t n;
    cin >> n;

    vector<v2> holes;
    holes.reserve(n);

    vector<v2> outers;
    outers.reserve(n);

    times_do(n, [&](){
        double x,y;
        cin >> x >> y;
        holes.push_back(v2{x, y});
    });

    v2 pivot = *min_element(begin(holes), end(holes), [](const v2& v1, const v2& v2){ return v1.x < v2.x; });
    //holes.erase(pivot);
    outers.push_back(pivot);
    //cout << pivot << '\n';
    v2 looking{0,1};

    for(size_t i = 0; i < n; ++i)
    {
        double score = 0;
        const v2* next = nullptr;
        for(const v2& v : holes)
        {
            if(pivot == v) continue;
            v2 d = (v - pivot).unit();
            double s = looking.dot(d);
            //cout << v << s << '\n';
            if(score < s || !next)
            {
                next = &v;
                score = s;
            }
        }
        looking = (*next - pivot).unit();
        pivot = *next;
        if(pivot == outers[0])
            break;
        outers.push_back(pivot);
        //cout << pivot << '\n';
    }


    //for(const auto& v : outers) cout << v << '\n';
    const double pi = std::acos(-1);

    unordered_map<v2, double> answers;

    for(size_t i = 0; i < outers.size(); ++i)
    {
        auto& prev = outers[(i == 0 ? outers.size() : i) - 1];
        auto& curr = outers[i];
        auto& next = outers[i + 1 == outers.size() ? 0 : i + 1];
        auto a = (prev-curr).angle(next-curr);
        if(a < 0) a += pi;
        //cout << fixed << setprecision(20);
        //cout << (pi - a) / (2 * pi) << '\n';
        auto p = (pi - a) / (2 * pi);
        answers.insert(make_pair(curr, p));
    }

    cout << fixed << setprecision(20);
    for(const auto& v : holes)
    {
        auto a = answers.find(v);
        if(a != answers.end())
        {
            cout << answers[v] << '\n';
        }
        else
        {
            cout << 0 << '\n';
        }
    }

    return 0;
}

