    scanf("%d", &n);
    for(int i = 0; i<n; i++)    
    {
        scanf("%lld %lld", &A[i].x, &A[i].y);
        A[i].index = i;
    }

    if(n == 2)
    {
        printf("0.5\n0.5\n");
        return 0;
    }
    if(n == 1)
    {
        printf("1.0\n");
        return 0;
    }
    vector<Point> H;
    H.clear();
    stack<Point> hull = grahamScan(A, n);
    while (!hull.empty())   {
        Point p = hull.top();
        hull.pop();
        H.pb(p);
    }

    long double angle;
    for(int i = 1; i<(H.size()-1); i++)
    {
        angle = calc(H[i-1], H[i], H[i+1]);
        P[H[i].index] = PI - angle;
    }

    if(H.size() < 3)
    {
        if(H.size() == 1)
            P[H[0].index] = 1.0;
        else if(H.size() == 0) // Bakchodi
            P[0] = 1.0;
        else
        {
            assert(H.size() == 2);

            P[H[0].index] = 0.5;
            P[H[1].index] = 0.5;
        }
        for(int i = 0; i<n; i++)
            printf("%.9Lf\n", P[i]);
        return 0;
    }
    else
    {
        angle = calc(H[H.size()-1], H[0], H[1]);
        P[H[0].index] = PI - angle;
        angle = calc(H[H.size()-2], H[H.size()-1], H[0]);
        P[H[H.size()-1].index] = PI - angle;
    }


    long double sum = 0.0;
    for(int i = 0; i<n; i++)
        sum += P[i];
    assert(abs(sum - 2*PI) < eps);
    for(int i = 0; i<n; i++)
        printf("%.9Lf\n", P[i]/sum);

    return 0;
}

