//https://beta.atcoder.jp/contests/joisc2007/submissions/3237997・・
void JOI_2007_line(){
	int n;
	cin>>n;
	vector<line> ls;
	for(int i=0;i<n;i++){
		line l;
		cin>>l.p1>>l.p2;
		bool f=true;
		for(int j=0;j<ls.size();j++){
			if(isParallel(l,ls[j])&&isSame(l,ls[j])){
				f=false;
				break;
			}
		}
		if(f){
			ls.push_back(l);
		}
	}
	n=ls.size();
	int ans=1;
	for(int i=0;i<n;i++){
		set<point> S;
		for(int j=i+1;j<n;j++){
			if(!isParallel(ls[i],ls[j])&&S.find(getCrossPointLL(ls[i],ls[j]))==S.end()){
				S.insert(getCrossPointLL(ls[i],ls[j]));
				ans++;
			}
		}
		ans++;
	}
	cout<<ans<<endl;
}
