double macos(double x){
	return acos(max(-1.0,min(1.0,x)));
}
double ans[100];
void AGC021_B(){
	int n;
	cin>>n;
	polygon q(n);
	map<point,int> M;
	for(int i=0;i<n;i++){
		cin>>q[i];
		M[q[i]]=i;
	}
	//
	polygon p=convex_hull(q);
	if(p.size()==2){
		ans[M[p[0]]]=0.5;
		ans[M[p[1]]]=0.5;
	}else{
		for(int i=0;i<p.size();i++){
			int pre=(i+p.size()-1)%p.size(),now=i,nex=(i+1)%p.size();
			line l0=bisector(p[pre],p[now]);
			line l1=bisector(p[now],p[nex]);
			Vector v0=l0.p1-l0.p2;
			Vector v1=l1.p1-l1.p2;
			double res=macos(dot(v0,v1)/(abs(v0)*abs(v1)))/(2*pi);
			ans[M[p[now]]]+=res;
		}
	}
	//
	for(int i=0;i<n;i++){
		cout<<fixed<<setprecision(12)<<ans[i]<<endl;
	}
}
int main(){
	AGC021_B();
	return 0;
}

