typedef struct Vector Point;
struct Vector
{
	double x,y;
	Vector(){}
	Vector(double _x,double _y)
	{x=_x;y=_y;}
	Vector(const Point &a,const Point &b)
	{x=b.x-a.x;y=b.y-a.y;}
	void read()
	{scanf("%lf%lf",&x,&y);}
	double operator * (const Vector &t)const
	{return x*t.x+y*t.y;}
	double operator ^ (const Vector &t)const
	{return x*t.y-t.x*y;}
	double length()
	{return sqrt(x*x+y*y);}
};
double angle(Vector a,Vector b)
{return acos(a*b/a.length()/b.length());}

int n;
Point P[MAXN];

int id[MAXN],hul[MAXN],top;
bool used[MAXN];
bool cmp(int a,int b)
{return P[a].x<P[b].x||(P[a].x==P[b].x&&P[a].y<P[b].y);}

void ConvexHull()
{
	for(int i=1;i<=n;i++)
		id[i]=i;
	sort(id+1,id+n+1,cmp);
	hul[1]=id[1],hul[2]=id[2],top=2;
	used[id[1]]=used[id[2]]=true;
	for(int i=3;i<=n;i++)
	{
		while(top>1&&fcmp(Vector(P[hul[top-1]],P[hul[top]])^Vector(P[hul[top]],P[id[i]]),0)==-1)
			used[hul[top]]=false,top--;
		used[id[i]]=true;
		hul[++top]=id[i];
	}
	for(int i=n-1;i>0;i--)
	{
		//if(used[id[i]]&&i!=1)continue;
		while(top>1&&fcmp(Vector(P[hul[top-1]],P[hul[top]])^Vector(P[hul[top]],P[id[i]]),0)==-1)
			used[hul[top]]=false,top--;
		used[id[i]]=true;
		hul[++top]=id[i];
	}
	top--;
}

double probability(int i)
{
	int l=hul[(i-1-1+top)%top+1];
	int r=hul[(i-1+1)%top+1];
	i=hul[i];
	double ang=angle(Vector(P[i],P[r]),Vector(P[i],P[l]));
	return (PI-ang)/(2.0*PI);
}

double ans[MAXN];

int main()
{
	scanf("%d",&n);
	if(n==2)
	{printf("0.5\n0.5\n");return 0;}
	for(int i=1;i<=n;i++)
		P[i].read();
	ConvexHull();

	for(int i=1;i<=top;i++)
		ans[hul[i]]=probability(i);
	for(int i=1;i<=n;i++)
		printf("%.20lf\n",ans[i]);
	return 0;
}

