		scanf("%lf%lf",&x[i],&y[i]);
	for (int i=1;i<=n;i++){
		for (int j=1;j<=n;j++)
			a[j]=atan2(y[j]-y[i],x[j]-x[i])*180.0/pi;
		a[i]=1e9;
		sort(a+1,a+n+1);
		double Max=a[1]+360.0-a[n-1];
		for (int i=1;i<n-1;i++)
			Max=max(Max,a[i+1]-a[i]);
		double ans=0;
		if (Max>180){
			for (int j=n;j<=(n-1)*2;j++)
				a[j]=a[j-(n-1)]+360;
			int L=n,R=n;
			while (a[L]-a[L-1]<180)
				L--;
			while (R<(n-1)*2&&a[R+1]-a[R]<180)
				R++;
			ans=(180-(a[R]-a[L]))/360;
		}
		printf("%.8lf\n",ans);
	}
	return 0;
