#include <algorithm>
using namespace std;
int main(){
	int N; 
	cin >> N; 
	pair<long long int, long long int> P[110] = {}; 
	int soeji = 0; 
	for(int i = 0; i < N; i++){
		cin >> P[i].first >> P[i].second; 
		if(P[i].first <= P[soeji].first && P[i].second <= P[soeji].second){
			soeji = i; 
		}
	}
	vector<int> CH = {};  
	CH.push_back(soeji); 
	long double mx = -2.0; int index = 0;
	for(int i = 0; i < N; i++){
		if(i == index) continue; 
		long long int a = P[soeji].first; 
		long long int b = P[soeji].second; 
		long long int c = P[i].first; 
		long long int d = P[i].second; 
		long double e = (double) (d-b) * pow((c-a) * (c-a) + (d-b) * (d-b), -0.5);
		if(e > mx) {
			index = i; mx = e; 
		}
	}
	CH.push_back(index); 
	long double cs[110][110][110] = {}; 
	for(int i = 0; i < N; i++){
		long long int a = P[i].first; 
		long long int b = P[i].second; 
		for(int j = 0; j < N; j++){
			long long int c = P[j].first; 
			long long int d = P[j].second; 
			for(int k = 0; k < N; k++){
				if(i==j || j==k) continue; 
				long long int e = P[k].first; 
				long long int f = P[k].second; 
				long long int g = (c-a)*(e-c) + (d-b)*(f-d); 
				long long int h = (c-a)*(c-a) + (d-b)*(d-b); 
				long long int l = (e-c)*(e-c) + (f-d)*(f-d); 
				cs[i][j][k] = (long double) g * pow(h, -0.5) * pow(l, -0.5); 
			}
		}
	}
	while(CH.at(CH.size() - 1) != soeji){
		int j = CH.at(CH.size() - 1);
		int i = CH.at(CH.size() - 2); 
		long double mx = -2.0; 
		int index = 0; 
		for(int k = 0; k < N; k++){
			if(i == k || j == k) continue;
			if(mx < cs[i][j][k]){
				index = k; mx = cs[i][j][k];
			} 
		}
		CH.push_back(index); 
	}
	long double ans[110] = {}; 
	for(int i = 0; i < N; i++){
		ans[i] = 1; 
	}
	cout.precision(15); 
	for(int i = 1; i < CH.size() - 1; i++){
		ans[CH[i]] = cs[CH[i-1]][CH[i]][CH[i+1]]; 
	}
	ans[CH[0]] = cs[CH[CH.size()-2]][CH[0]][CH[1]]; 
	for(int i = 0; i < N; i++){
		cout << acos(ans[i]) / (2.0 * acos(-1)) << endl; 
	}
}

