struct line {
    int a=1, b=1;
    ld c=0;
    ld m, m1, m2, y;
    line(ld a_, ld b_, ld c_) {
        while(abs(a_-round(a_)) > EPS ||
              abs(b_-round(b_)) > EPS) {
            a_*=10;
            b_*=10;
            c_*=10;
        }
        a=round(a_);
        b=round(b_);
        c=c_;
        int x = __gcd(a,b);
        if(x<0) x*=-1;
        a/=x;
        b/=x;
        if(b<0) a*=-1, b*=-1;
        c/=x;
        if(m2!=0) m = -(ld)a/b;
        else      m = 0;
        if(b<0) m1=a, m2=-b;
        else    m1=-a, m2=b;
        y = -c/b;
    }
    void print() {
        cerr << a << "x+" << b << "y+" << c << "=0" << endl;
    }
    void printmx() {
        cerr << "y=" << m << "x+" << y << endl;
    }
};
line pointsToLine(point a, point b) {
    ld m1=b.y()-a.y();
    ld m2=b.x()-a.x();
    return line(-m1, m2, m1*a.x()-m2*a.y());
}
line perpThroughPoint(line l, point p) {
    int m1 = l.m1;
    int m2 = l.m2;
    m1*=-1;
    swap(m1, m2);
    if(m2<0) m1*=-1, m2*=-1;
    return line(-m1, m2, (-(m1*-p.x())-(m2*p.y())));
}
bool isPara(line l, line k) { return l.a==k.a && l.b==k.b; }
bool isPerp(line l, line k) {
    return l.a==k.b && l.b==-k.a || l.a==-k.b && l.b==k.a;
}
bool onLine(point p, line l) {
    return (l.a*p.x())+(l.b*p.y()) == -l.c;
}


