int const N = 100;
int n;
double an[N], pi = acos(-1.0);

struct V{
	int x, y, id;
	V(){}
	V(int a, int b):x(a), y(b) {}
	void sc(int i) { scanf("%d%d", &x, &y); id = i; }
	bool operator <(V const o)const { if (x == o.x)return y < o.y; return x < o.x; }
	V operator -(V const o)const { return V(x - o.x, y - o.y); }
	V operator +(V const o)const { return V(x + o.x, y + o.y); }
	ll operator |(V const o)const { return (ll)x * o.y - (ll)o.x * y; }
	ll operator *(V const o)const { return (ll)x * o.x + (ll)o.y * y; }
	ll L() { return (ll)x * x + (ll)y * y; }
}p[N];

inline bool cmp0(V const a, V const b){
	V ap = a - p[0], bp = b - p[0];
	ll t = ap | bp;
	if (t == 0)return ap.L() < bp.L();
	return t > 0;
}
inline bool cmp(V const a, V const b, V const c) { return (a - c | b - c) >= 0; }

vector<int> v;

void ch(){
	v.push_back(0);
	v.push_back(1);
	f(i, 2, n){
		while ((int)v.size() > 1 && cmp(p[i], p[v.back()], p[v[v.size() - 2]]))v.pop_back();
		v.push_back(i);
	}
}

int main(){
	scanf("%d", &n);
	f(i, 0, n)p[i].sc(i);
	sort(p, p + n);
	sort(p + 1, p + n, cmp0);
	ch();
	if ((int)v.size() == 2)f(i, 0, v.size())an[p[v[i]].id] = 0.5;
	else f(i, 0, v.size()){
		int af = i + 1 == (int)v.size() ? 0 : i + 1, bf = i ? i - 1 : (int)v.size() - 1;
		V a = p[v[af]] - p[v[i]], b = p[v[i]] - p[v[bf]];
		double cth = b * a / (sqrt(b.L()) * sqrt(a.L()));
		double th = acos(cth);
		an[p[v[i]].id] = th / (2.0 * pi);
	}
	f(i, 0, n)printf("%.7lf\n", an[i]);
}

