typedef double D;     // 座標値の型。doubleかlong doubleを想定
typedef complex<D> P; // Point
typedef pair<P, P> L; // Line
typedef vector<P> VP;
const D EPS = 1e-9; // 許容誤差。問題によって変える
#define X real()
#define Y imag()
#define LE(n, m) ((n) < (m) + EPS)
#define GE(n, m) ((n) + EPS > (m))
#define EQ(n, m) (abs((n) - (m)) < EPS)
// 内積　dot(a,b) = |a||b|cosθ
D dot(P a, P b) { return (conj(a) * b).X; }
// 外積　cross(a,b) = |a||b|sinθ
D cross(P a, P b) { return (conj(a) * b).Y; }

bool cmp(const P a, const P b) { return a.X != b.X ? a.X < b.X : a.Y < b.Y; }

// 点の進行方向
int ccw(P a, P b, P c) {
  b -= a;
  c -= a;
  if (cross(b, c) > EPS)
    return +1; // counter clockwise
  if (cross(b, c) < -EPS)
    return -1; // clockwise
  if (dot(b, c) < -EPS)
    return +2; // c--a--b on line
  if (norm(b) < norm(c))
    return -2; // a--b--c on line or a==b
  return 0;    // a--c--b on line or a==c or b==c
}
VP convexHull(VP ps) { // 元の点集合がソートされていいならVP&に
  int n = ps.size(), k = 0;
  sort(ALL(ps), cmp);
  VP ch(2 * n);
  for (int i = 0; i < n; ch[k++] = ps[i++]) // lower-hull
    while (k >= 2 && ccw(ch[k - 2], ch[k - 1], ps[i]) <= 0)
      --k; // 余計な点も含むなら == -1 とする
  for (int i = n - 2, t = k + 1; i >= 0; ch[k++] = ps[i--]) // upper-hull
    while (k >= t && ccw(ch[k - 2], ch[k - 1], ps[i]) <= 0)
      --k;
  ch.resize(k - 1);
  return ch;
}

P crosspointLL(P a1, P a2, P b1, P b2) {
  D d1 = cross(b2 - b1, b1 - a1);
  D d2 = cross(b2 - b1, a2 - a1);
  if (EQ(d1, 0) && EQ(d2, 0))
    return a1; // same line
  if (EQ(d2, 0))
    throw "kouten ga nai"; // 交点がない
  return a1 + d1 / d2 * (a2 - a1);
}

D get_kakudo(P a, P b) {
  P c = a - b;
  D po = atan2(c.Y, c.X);
  if (po < 0)
    po += 2 * M_PI;
  return po;
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(NULL);
  ll N;
  cin >> N;
  VP A(N);
  REP(i, N) {
    D x, y;
    cin >> x >> y;
    A[i] = complex<D>(x, y);
  }
  if (N == 2) {
    cout << 0.50 << endl;
    cout << 0.50 << endl;
    return 0;
  }

  VP B = convexHull(A);
  vector<double> ans(N, 0);
  ll M = B.size();
  REP(i, M) {
    ll index = 0;
    REP(j, N) if (A[j] == B[i]) index = j;
    D po = get_kakudo(B[(i - 1 + M) % M], B[i]);
    D yo = get_kakudo(B[(i + 1) % M], B[i]);

    D uo = po - yo;
    if (uo < 0)
      uo += 2 * M_PI;
    uo = M_PI - uo;
    ans[index] = uo / (2 * M_PI);
  }
  REP(i, N) { cout << SP(20) << ans[i] << endl; }
  return 0;
}

