LD getang ( int x, int y )
{
	LD ans = atan2 ( y, x );
	if ( ans < -EPS ) ans += 2 * PI;
	return ans;
}

LD dec ( LD x, LD y )
{
	LD ans = x - y;
	if ( ans < -EPS ) ans += 2 * PI;
	if ( ans > 2 * PI - EPS ) ans -= 2 * PI;
	return ans;
}



