void work ()
{
	// main work

	int mp = 0;
	lp ( i, 1, n ) if ( cr[i].y < cr[mp].y || ( cr[i].y == cr[mp].y && cr[i].x < cr[mp].x ) ) mp = i;
	swap ( cr[mp], cr[0] );
	lp ( i, 1, n ) cr[i].ang = getang ( cr[i].x - cr[0].x, cr[i].y - cr[0].y );
	sort ( cr + 1, cr + n );

	int top = 0;
	stk[++top] = 0;
	LL det;
	lp ( i, 1, n ) {
		while ( top >= 2 ) {
			det = ( cr[stk[top]] - cr[stk[top - 1]] ) * ( cr[i] - cr[stk[top]] );
			if ( det < 0 || ( det == 0 && ( ( ( cr[stk[top]].x - cr[stk[top - 1]].x ) ^ ( cr[i].x - cr[stk[top]].x ) ) > 0 ) ) ) --top;
