double const epsilon = 1e-10;

struct P { 
  double x, y; 
  static double add(double x, double y) {
    if(abs(x+y) < epsilon*(abs(x)+abs(y))) return 0.0;
    return x+y;
  }
  P operator -(P const& p) const { return {add(x, -p.x), add(y, -p.y)}; }
  double det(P const& p) const { return add(x*p.y, -y*p.x); }
  P operator -() const { return {-x, -y}; }
};

double const PI = std::acos(-1);

int main() {
  std::cin.tie(0); std::ios::sync_with_stdio(false);
  std::cout << std::setprecision(10) << std::fixed;
  int N; std::cin >> N;
  std::vector<P> p(N);
  for(int i = 0; i < N; ++i) std::cin >> p[i].x >> p[i].y;
  std::vector<int> ix(N);
  std::iota(ix.begin(), ix.end(), 0);
  std::sort(ix.begin(), ix.end(), [&](int l, int r){ return p[l].x < p[r].x; });
  std::vector<int> q(N+2);
  int k = 0;
  for(int i = 0; i < N; ++i) {
    while(k > 1 && (p[q[k-1]] - p[q[k-2]]).det(p[i] - p[q[k-1]]) <= 0.0) --k;
    q[k++] = ix[i];
  }
  for(int i = N-2, t = k; i >= 0; --i) {
    while(k > t && (p[q[k-1]] - p[q[k-2]]).det(p[i] - p[q[k-1]]) <= 0.0) --k;
    q[k++] = ix[i];
  }
  q.resize(--k); // remove duplicate of start point
  std::vector<double> th;
  for(int i = 0; i < k; ++i) {
    P pb = p[q[i]], pe = p[q[(i+1)%k]];
    P v({pb.y-pe.y, pe.x-pb.x});
    if(v.det(pe-pb) <= 0) v = -v;
    th.push_back(std::atan2(v.y, v.x));
  }
  std::vector<double> ans(N, 0.0);
  for(int i = 0; i < k; ++i) {
    double thb = th[i], the = th[(i+1)%k];
    double thd = the-thb;
    if(thd < 0) thd += PI*2.0;
    ans[q[(i+1)%k]] = thd/(PI*2.0);
  }
  fin(ans, '\n');
  return 0;
}

