typedef long long ll;
typedef pair<ll,ll> P;
typedef pair<P,ll> P2;
ll det(P p1,P p2){
  return p1.first*p2.second-p2.first*p1.second;
}
P operator +(const P2 &p1,const P2 &p2){
  return P(p1.first.first+p2.first.first,p1.first.second+p2.first.second);
}
P operator -(const P2 &p1,const P2 &p2){
  return P(p1.first.first-p2.first.first,p1.first.second-p2.first.second);
}
P operator -(const P &p1,const P &p2){
  return P(p1.first-p2.first,p1.second-p2.second);
}
P operator -(const P2 &p1,const P &p2){
  return P(p1.first.first-p2.first,p1.first.second-p2.second);
}
vector<ll> convex(vector<P2> v,ll n){
  sort(v.begin(),v.end());
  ll k=0;
  vector<P> ans(n*2);
  vector<ll> ret(n*2);
  for(ll i=0;i<n;i++){
    while(k>1&&det(ans[k-1]-ans[k-2],v[i]-ans[k-1])<=0) k--;
    ans[k]=v[i].first;
    ret[k]=v[i].second;
    k++;
  }
  for(ll i=n-2,t=k;i>=0;i--){
    while(k>t&&det(ans[k-1]-ans[k-2],v[i]-ans[k-1])<=0) k--;
    ans[k]=v[i].first;
    ret[k]=v[i].second;
    k++;
  }
  ans.resize(k-1);
  ret.resize(k-1);
  return ret;
}
int main(){
  ll n;
  cin>>n;
  vector<P2> vec;
  for(ll i=0;i<n;i++){
    ll a,b;
    cin>>a>>b;
    vec.push_back(P2(P(a,b),i));
  }
  vector<ll> v=convex(vec,n);
  /*for(int i=0;i<v.size();i++) cout<<v[i]<<" ";
  cout<<endl;*/
  ll vs=v.size();
  double ans[105]={0.0};
  for(ll i=0;i<v.size();i++){
    ll px=vec[v[i]].first.first-vec[v[(i+1)%vs]].first.first;
    ll py=vec[v[i]].first.second-vec[v[(i+1)%vs]].first.second;
    py*=-1;
    double pa=M_PI/2;
    if(py!=0) pa=atan((double)px/py);

    ll zx=vec[v[i]].first.first-vec[v[(i-1)+(i==0?vs:0)]].first.first;
    ll zy=vec[v[i]].first.second-vec[v[(i-1)+(i==0?vs:0)]].first.second;
    zy*=-1;
    double za=-M_PI/2;
    if(zy!=0) za=atan((double)zx/zy);

    double ka=abs(pa-za);
    ll dot=px*(-zx)+(-py)*zy;
    if(dot>0) ka=min(ka,M_PI-ka);
    else if(dot<0) ka=max(ka,M_PI-ka);
    else ka=M_PI/2;
    //cout<<px<<" "<<py<<" "<<zx<<" "<<zy<<" "<<ka<<" "<<dot<<endl;
    ans[vec[v[i]].second]=ka/(M_PI*2);
  }
  for(int i=0;i<n;i++) printf("%.7lf\n",ans[i]);
}

