	int m=vp2.size();
	//rep(i,m) cout<<vp2[i].fi<<endl;
	if(m==2){
		out[vp2[0].se]=out[vp2[1].se]=0.5;
	}
	else{
		rep(i,m) out[vp2[i].se]=aSS(vp2[(i+m-1)%m].fi,vp2[i].fi,vp2[(i+1)%m].fi)/(2*PI);
	}
