// NOTE: All Angles are in Radians
#define PI 3.1415926535897932384
#define EPS (1e-7)
#define point complex<ld>
#define x() real()
#define y() imag()
ld toDegrees(ld radians) { return radians*(180/PI); }
ld toRadians(ld degrees) { return degrees/(180/PI); }
point toCartesian(point p) { return polar(p.x(), p.y()); }
point toPolar(point c) { return point(abs(c), arg(c)); }
ld dot(point a, point b) { return (conj(a) * b).x(); }
ld cross(point a, point b) { return (conj(a) * b).y(); }
ld eucDist(point a, point b) { return abs(a - b); }
ld manDist(point a, point b) { return norm(a - b); }
point closestPointToLine(point p, point a, point b) {
    ld norm_sq = (b-a).x()*(b-a).x() + (b-a).y()*(b-a).y();
    ld u = dot(p-a, b-a) / norm_sq;
    point c = a + (u * (b-a));
    return c;
}
ld distToLine(point p, point a, point b) {
    return eucDist(p, closestPointToLine(p, a, b));
}
ld distToLineSeg(point p, point a, point b) {
    ld norm_sq = (b-a).x()*(b-a).x() + (b-a).y()*(b-a).y();
    ld u = dot(p-a, b-a) / norm_sq;
    point c = a + (u * (b-a));
    if(u<0) c = a;
    if(u>1) c = b;
    return eucDist(p, c);
}
point midpoint(point a, point b) {
    return point((a.x()+b.x())/2, (a.y()+b.y())/2);
}
ld slope(point a, point b) { return tan(arg(b - a)); }
ld angleElevation(point a, point b) { return arg(b - a); }
ld angleABC(point a, point b, point c) {\
    return abs(remainder(arg(a-b) - arg(c-b), 2.0 * PI));
}
point rotateAboutOrigin(point a, ld theta) {
    return a * polar((ld)1.0, theta); }
point rotateAboutPoint(point a, ld theta, point p) {
    return (a-p) * polar((ld)1.0, theta) + p;
}
bool cw(point a, point b, point c) {           // turn a-b-c
    return cross(b-a, c-a)+EPS < 0;
}
bool ccw(point a, point b, point c) {          // turn a-b-c
    return cross(b-a, c-a)-EPS > 0;
}
bool collinear(point a, point b, point c) {
    return abs(cross(b-a, c-a)) <= EPS;
}
point intersection(point a, point b, point p, point q) {
    ld c1 = cross(p - a, b - a), c2 = cross(q - a, b - a);
    return (c1*q - c2*p) / (c1-c2);
}
bool compareByX(point a, point b) { // 1 if a goes before b
    if(a.x() < b.x()) return 1;
    if(a.x() == b.x() && a.y() < b.y()) return 1;
    return 0;
}
bool compareByY(point a, point b) {
    if(a.y() < b.y()) return 1;
    if(a.y() == b.y() && a.x() < b.x()) return 1;
    return 0;
}
bool angCompare(pair<ld, point> a, pair<ld, point> b) {
    if(a.first < b.first) return 1;
    if(a.first==b.first)return compareByX(a.second, b.second);
    return 0;
}
vector<point> GrahamsScan(vector<point> p) {     // O(NlogN)
    sort(p.begin(), p.end(), compareByY);  // O(N) if given in
    int mi=INF;
    point miPoint;
    for(auto q: p)
        if(q.y() < mi)
            mi=q.y(), miPoint = q;
    vector<pair<ld, point>> ang;          // c/clockwise order
    for(int i = 0; i < p.size(); i++)
        ang.push_back({angleElevation(miPoint, (p[i])), p[i]});
    sort(ang.begin(), ang.end(), angCompare); // Anticlockwise
    ang.push_back(ang[0]);
    vector<point> ch;
    ch.push_back(ang[0].second), ch.push_back(ang[1].second);
    for(int i = 2; i < ang.size(); i++) {
       while(ch.size() >= 2 &&
            !ccw(ch[ch.size()-2], ch.back(), ang[i].second))
            ch.pop_back();
       ch.push_back(ang[i].second);
    }
    ch.pop_back();
    return ch; // Starts with bottom left in counter clockwise
}

