typedef pair<ld,ld> pnt;
ld dis2(pnt a,pnt b)
{return (a.fi-b.fi)*(a.fi-b.fi)+(a.se-b.se)*(a.se-b.se);}
ld pi=acos(-1); 
ld gf(ld x)
{
	while(x<0) x+=pi+pi;
	while(x>=pi+pi) x-=pi+pi;
	return x;
}
int main()
{
	scanf("%d",&n);
	for(int i=1;i<=n;++i)
		scanf("%d%d",x+i,y+i);
	for(int i=1;i<=n;++i)
	{
		map<ld,int> ps;
		ps[0]=ps[pi+pi]=0;
		int mm=0;
		for(int j=1;j<=n;++j) if(j!=i)
		{
			ld L,R; ++mm;
			pnt m((x[i]+x[j])/2.0,(y[i]+y[j])/2.0);
			int dx=y[i]-y[j],dy=x[j]-x[i];
			//k=atan(dy/dx)
			if(!dx) L=pi*0.5,R=pi*1.5;
			else
			{
				ld k=dy/ld(dx),b=m.se-m.fi*k;
				ld A=k*k+1,B=2*k*b,C=b*b-r*r;
				ld d=sqrt(B*B-4*A*C);
				ld x1=(-B+d)/(2*A),x2=(-B-d)/(2*A);
				L=atan2(x1*k+b,x1); R=atan2(x2*k+b,x2);
			}
			L=gf(L); R=gf(R);
			if(L>R) swap(L,R);
			ld M=(L+R)/2;
			pnt g(r*cos(M),r*sin(M));
			//cerr<<L<<","<<R<<"\n"; 
			ld di=dis2(g,pnt(x[i],y[i])),dj=dis2(g,pnt(x[j],y[j]));
			if(di>dj) swap(L,R);
			if(L<=R)
				ps[L]++, ps[R]--;
			else
				ps[0]++,ps[R]--,ps[L]++,ps[pi+pi]--;
		}
		int s=0; ld ca=0;
		for(auto x=ps.begin();;++x) 
		{
			auto y=x; ++y;
			if(y==ps.end()) break;
			s+=x->se;
			if(s==mm) ca+=y->fi-x->fi;
		}
		printf("%.10lf\n",ca/(pi+pi));
	}
}

