  swap(a[0], a[pos]);
  sort(a.begin() + 1, a.end(), [&](P u, P v){return u - a[0] < v - a[0];});
  vector<P> cv;
  cv.push_back(a[0]);
  range(i, 1, n) {
    while(cv.size() >= 2 && a[i].cross(cv.back(), cv[cv.size() - 2]) <= 0) {
      cv.pop_back();
    }
    cv.push_back(a[i]);
  }
  vector<double> res(n);
  double cur = 2 * 3.141592653589793238462643;
  range(i, 0, (int) cv.size()) {
    P u = cv[(i + cv.size() - 1) % cv.size()];
    P v = cv[(i + 1) % cv.size()];
    u = u - cv[i];
    v = v - cv[i];
