inline long long GetTSC() {
  long long lo, hi;
  asm volatile ("rdtsc": "=a"(lo), "=d"(hi));
  return lo + (hi << 32);
}
inline double GetSeconds() {
  return GetTSC() / 2.8e9;
}

long x[100];
long y[100];
int r[100] = {};
double TO = 1.9;

void solve(){
  double starttime = GetSeconds();
  int n;
  cin >> n;
  for(int i=0; i<n; i++){
    cin >> x[i] >> y[i];
  }
  random_device seed_gen;
  mt19937 engine(seed_gen());
  uniform_real_distribution<> rd(pow(-10.0,13), pow(10.0,13));
  double rk = pow(10.0,26);
  int ii = 0;
  for(; ; ){
    if(GetSeconds()-starttime > TO) break;
    double a = rd(engine);
    double b = rd(engine);
    if(a*a+b*b>rk) continue;
    ii++;
    double m = pow(x[0]-a,2) + pow(y[0]-b,2);
    int mi = 0;
    for(int j=1; j<n; j++){
      double t = pow(x[j]-a,2) + pow(y[j]-b,2);
      if(t<m){
        m = t;
        mi = j;
      }
    }
    r[mi]++;
  }
  cerr << ii << endl;
  for(int i=0; i<n; i++){
    cout << (1.0 * r[i] / ii) << endl;
  }

  return;
}

