std::vector<Point> convexFull(std::vector<Point> p) {
	int n = p.size(), k = 0;
	if(2 < n) {
		sort(begin(p), end(p));
		std::vector<Point> ch(2 * n);
		for(int i = 0; i < n; ch[k++] = p[i++]) {
			while(k > 1 and cross(ch[k - 1] - ch[k - 2], p[i] - ch[k - 1]) < 0) --k;
		}
		for(int i = n - 2, t = k + 1; i >= 0; ch[k++] = p[i--]) {
			if(k >= t and cross(ch[k - 1] - ch[k - 2], p[i] - ch[k - 1])  < 0) --k;
		}
		ch.resize(k - 1);
		return ch;
	} else {
