void add(int i, double arg)
{
	double l = fmod(arg + 4 * PI, 2 * PI);
	double r = l + PI;
	if (l > argmax[i] || r < argmin[i]) {
		l += 2 * PI;
		r += 2 * PI;
	}
	argmin[i] = max(argmin[i], l);
	argmax[i] = min(argmax[i], r);
}

int main(int argc, char* argv[])
{
