		argmax[i] = 4 * PI;
	}
	for (int i = 0; i < N; i++) {
		for (int j = i + 1; j < N; j++) {
			double dx = x[i] - x[j];
			double dy = y[j] - y[i];
			double d = sqrt(dx * dx + dy * dy);
			double arg = asin(dx / d);
			if (dy < 0)
				arg = PI - arg;
			add(j, arg);
			add(i, arg + PI);
		}
	}
	for (int i = 0; i < N; i++) {
		if (argmax[i] <= argmin[i]) {
			printf("0.0\n");
		} else {
			double p = (argmax[i] - argmin[i]) / (2 * PI);
			printf("%.8f\n", p);
		}
	}

	return 0;
}

