struct P {
  long long x, y;
  int id;
  P operator - (const P & b) const {
    return P{x - b.x, y - b.y};
  }

  void operator += (const P & b) {
    x += b.x, y += b.y;
  }

  long long operator * (const P & b) const {
    return x * b.y - y * b.x;
  }

  long long operator ^ (const P & b) const {
    return x * b.x + y * b.y;
  }

  long long cross(const P & b, const P & c) const {
    return (b - *this) * (c - *this);
  }

   bool isRight() const {
    return x > 0 || (x == 0 && y > 0);
  }

  bool operator < (const P & b) const {
    if(isRight() != b.isRight())
      return isRight();
    return *this * b < 0;
  }

  bool operator == (const P & b) const {
    return make_pair(x, y) == make_pair(b.x, b.y);
  }
};

long double getAlpha(const P &a, const P &b) {
  return atan2((long double) (a * b), (long double) (a ^ b));
}

int n;

int main() {
  cout.precision(15);
  cin >> n;
  vector<P> a(n);
  range(i, 0, n) {
    cin >> a[i].x >> a[i].y;
    a[i].id = i;
  }
  if(n == 2) {
    cout << 0.5 << endl << 0.5;
    return 0;
  }
  int pos = 0;
  range(i, 0, n) if(make_pair(a[i].x, a[i].y) < make_pair(a[pos].x, a[pos].y)) pos = i;
  swap(a[0], a[pos]);
  sort(a.begin() + 1, a.end(), [&](P u, P v){return u - a[0] < v - a[0];});
  vector<P> cv;
  cv.push_back(a[0]);
  range(i, 1, n) {
    while(cv.size() >= 2 && a[i].cross(cv.back(), cv[cv.size() - 2]) < 0) {
      cv.pop_back();
    }
    cv.push_back(a[i]);
  }
  vector<double> res(n);
  double cur = 2 * 3.14159265359;
  range(i, 0, (int) cv.size()) {
    P u = cv[(i + cv.size() - 1) % cv.size()];
    P v = cv[(i + 1) % cv.size()];
    u = u - cv[i];
    v = v - cv[i];
    long double t = getAlpha(u, v);
    t = cur / 2 - t;
    res[cv[i].id] = t / cur;
  }
  range(i, 0, n) cout << res[i] << endl;
  return 0;
}

