struct vec {
    long double x, y;

    vec(pt a, pt b) {
        x = b.x - a.x;
        y = b.y - a.y;
    }

    long double length() {
        return sqrtl((long double) x * x + y * y);
    }
};

int n;
pt p[maxn];
long double ans[maxn];

