ll prod(vec a, vec b) {
    return a.x * b.y - a.y * b.x;
}

bool cmp(pt a, pt b) {
    vec v1 = vec(p[0], a);
    vec v2 = vec(p[0], b);

    if (prod(v1, v2) != 0)
        return prod(v1, v2) < 0;
    else
        return v1.x * v1.x + v1.y * v1.y < v2.x * v2.x + v2.y * v2.y;
}

long double ang(vec a, vec b) {
    long double t = (a.x * b.x + a.y * b.y) / (a.length() * b.length());
    if (t < -1) t = -1;
    if (t > 1) t = 1;
    return acosl(t);
}

void solve() {
    if (n == 2) {
        cout << "0.5\n0.5\n";
        return ;
    }

    int mn = -1;

    for (int i = 0; i < n; ++i)
        if (mn == -1 || p[i].x < p[mn].x || (p[i].x == p[mn].x && p[i].y < p[mn].y))
            mn = i;

    swap(p[0], p[mn]);
    sort(p + 1, p + n, cmp);
    vector<pt> ch;
    ch.push_back(p[0]);
    ch.push_back(p[1]);

    for (int i = 2; i < n; ++i) {
        while (sz(ch) >= 2 && prod(vec(ch[sz(ch) - 2], ch[sz(ch) - 1]), vec(ch[sz(ch) - 2], p[i])) > 0)
            ch.pop_back();

        ch.push_back(p[i]);
    }

    long double len = 0;
    pt pp(0, 0);

    for (int i = 0; i < sz(ch); ++i) {
        pt p1 = ch[(sz(ch) + i - 1) % sz(ch)];
        pt p2 = ch[i];
        pt p3 = ch[(i + 1) % sz(ch)];
        pt u1 = pt(0.5 * (p1.x + p2.x), 0.5 * (p1.y + p2.y));
        pt u2 = pt(0.5 * (p2.x + p3.x), 0.5 * (p2.y + p3.y));
        vec p12 = vec(p1, p2);
        vec p23 = vec(p2, p3);
        swap(p12.x, p12.y);
        swap(p23.x, p23.y);
        p12.x *= -1;
        p23.x *= -1;
        ans[ch[i].i] = ang(p12, p23);
        len += ans[ch[i].i];
    }

    for (int i = 0; i < n; ++i)
        cout << ans[i] / len << endl;
}

