LD det(point A, point B, point C)
{
    LD r = A.x * B.y - A.y * B.x + B.x * C.y - C.x * B.y + C.x * A.y - A.x * C.y;
    return r;
}

vector<point> convexHull()
{
    int i;
    cin >> n;

    if(n == 1)
    {
        cout << 1.0;
        exit(0);
    }
    if(n == 2)
    {
        cout << 0.5 << "\n" << 0.5;
        exit(0);
    }

    for(int i = 1; i <= n; i++)
        cin >> v[i].x >> v[i].y;
    for(int i = 1; i <= n; i++) bck[i] = v[i];
    sort(v + 1, v + n + 1);
    m = 2;
    stv[1] = 1;
    stv[2] = 2;
    for(i = 3; i <= n; i++)
    {
        while(m > 1 && det(v[ stv[m - 1] ], v[ stv[m] ], v[i]) < eps)
            m--;
        stv[++m] = i;
    }

    q = m;
    for(i = 1; i <= q; i++)
        r[i] = v[ stv[i] ];

    m = 2;
    stv[1] = n;
    stv[2] = n - 1;
    for(i = n - 2; i >= 1; i--)
    {
        while(m > 1 && det(v[ stv[m - 1] ], v[ stv[m] ], v[i]) < eps)
            m--;
        stv[++m] = i;
    }

    for(i = 1; i <= m; i++)
        r[ ++q ] = v[ stv[i] ];

    vector<point> ans;
    for(i = 1; i < q; i++)
    {
        if(r[i] == r[i - 1] && i > 1)
            continue;
        ans.push_back(r[i]);
    }
    return ans;
}

LD dist(point A, point B)
{
    LD d = (A.x - B.x) * (A.x - B.x) + (A.y - B.y) * (A.y - B.y);
    d = sqrt(d);
    return d;
}

LD ang[105];

