    int N = pts.size();
    pts.push_back(pts[0]);
    pts.push_back(pts[1]);

    LD sum = 0;
    LD PI = atan(1.0) * 4.0;
    for(int i = 1; i <= N; i++)
    {
        LD ab = dist(pts[i], pts[i - 1]);
        LD ac = dist(pts[i], pts[i + 1]);
        LD bc = dist(pts[i - 1], pts[i + 1]);

        LD a = (ab * ab + ac * ac - bc * bc) / (2.0 * ab * ac);
        ang[i] = acos(a);
        ang[i] = PI - ang[i];
        sum += ang[i];
    }

    for(int i = 1; i <= N; i++)
        ang[i] /= sum;

    for(int i = 1; i <= N; i++)
        mp[ pts[i] ] = ang[i];

    for(int i = 1; i <= n; i++)
        cout << fixed << setprecision(20) << mp[ bck[i] ] << '\n';

