int determinant(int i, int j, int k) {
  // -           -
  // | x[i] - x[j], x[k] - x[j] |
  // | y[i] - y[j], y[k] - y[j] |
  // -           -
  int det = (x[i] - x[j]) * (y[k] - y[j]) - (x[k]- x[j]) * (y[i] - y[j]);
  if (det > 0) return 1;
  if (det == 0) return 0;
  else return -1;
}

void removeColinear(int i) {
  printf("pt: %d----------------\n", i);
  int minX = x[i];
  int maxX = x[i];
  int minY = y[i];
  int maxY = y[i];

  for (auto j : idx[i]) {
    minX = min(minX, x[j]);
    maxX = max(maxX, x[j]);
    minY = min(minY, y[j]);
    maxY = max(maxY, y[j]);
  }

  idx[i].insert(i);
  printf("minX: %d, maxX: %d\nminY: %d, maxY: %d\n", minX, maxX, minY, maxY);
  for (auto j : idx[i]) {
    printf("testing %d\n", j);
    if ((x[j] != minX && x[j] != maxX) || (y[j] != minY && y[j] != maxY)) {
      printf("removing %d\n", j);
      toErase.PB(j);
    }
  }
}

void convexHull() {
  // brute force convex hull
  FORN(i, N) {
    for (int j = i+1; j < N; j++) {
      int signs = 0;
      bool same = true;
      FORN(k, N) {
        if (k == i || k == j) continue;
        int det = determinant(i, j, k);
        same &= (signs * det >= 0);
        signs = det;
      }
      if (same) {
          idx[i].insert(j);
      }
    }
  }

  for (auto& kv : idx) {
    if (kv.SS.size() > 2) {
      removeColinear(kv.FF);
    }
  }

  for (auto e : toErase) {
    if (idx.find(e) != idx.end()) {
      idx.erase(e);
    }
    for (auto& kv : idx) {
      kv.SS.erase(e);
    }
  }
}

double angle(Vector v1, Vector v2) {
//  printf("<%d, %d>, <%d, %d>\n", v1.x, v1.y, v2.x, v2.y);
  double dot = v1.x * v2.x + v1.y * v2.y;
  double len1 = v1.x * v1.x + v1.y * v1.y;
  double len2 = v2.x * v2.x + v2.y * v2.y;
  double param = dot / sqrt(len1 * len2);
//  cout << "dot: " << dot << endl;
//  cout << "len1: " << len1 << endl;
//  cout << "len2: " << len2 << endl;
//  cout << "param: " << param << endl;
  return acos(param);
}

