int main(){
	int n;
	cin>>n;
	vector<pair<int,int> > points;
	points.reserve(n);
	for(int i=0;i<n;i++){
		int x,y;
		cin>>x>>y;
		points.push_back(make_pair(x,y));
	}
	for(int i=0;i<n;i++){
		double min_num;
		double max_num;
		bool isFirst=true;
		bool noans=false;
		for(int j=0;j<n;j++){
			if(i==j){
				continue;
			}
			double xdiff=points[j].first-points[i].first;
			double ydiff=points[j].second-points[i].second;
			double min_angle=atan2(xdiff,-1*ydiff);
			double max_angle=atan2(-1*xdiff,ydiff);
			if(isFirst){
				min_num=min_angle;
				max_num=max_angle;
				isFirst=false;
			}else{
				if(max_angle>min_angle){
					if(max_num>min_num){
						max_num=min(max_num,max_angle);
						min_num=max(min_num,min_angle);
						if(max_num<min_num){
							noans=true;
							break;
						}
					}else{
						min_num=min_angle;
						max_num=min(max_num,max_angle);
						if(max_num<min_num){
							noans=true;
							break;
						}
					}
				}else{
					if(max_num>min_num){
						min_num=max(min_num,min_angle);
						//max_num=min(max_num,max_angle);
						if(max_num<min_num){
							noans=true;
							break;
						}
					}else{
						min_num=max(min_angle,min_num);
						max_num=min(max_num,max_angle);
					}
				}
			}

		}
		if(noans){
			cout<<0<<endl;
		}else{
			double p=0;
			if(max_num>min_num){
				p=(max_num-min_num)/(2*3.14159265);
			}else{
				p=(2*3.14159265+max_num-min_num)/(2*3.14159265);
			}
			cout<<fixed<<setprecision(10)<<p<<endl;
		}
	}

}

