double cross(pair<double, double> a, pair<double, double> b, pair<double, double> c) {
	pair<double, double> u = { a.first - c.first, a.second - c.second };
	pair<double, double> v = { a.first - b.first ,a.second - b.second };
	return u.first*v.second - u.second*v.first;
}

double abs(pair<double, double> a) {
	return sqrt(a.first*a.first + a.second*a.second);
}

int main() {
	int n; cin >> n;
	if (n == 2) {
		cout << 0.5 << endl;
		cout << 0.5 << endl;
		return 0;
	}
	vector<pair<pair<double, double>, int>> pi(n);
	for (int i = 0; i < n; i++) cin >> pi[i].first.first >> pi[i].first.second, pi[i].second = i;
	sort(pi.begin(), pi.end());
	double lm = 1e9; int idx = 0;
	vector<pair<pair<double, double>, int>> chi;
	bool used[103] = {};
	chi.push_back(pi[0]);
	used[idx] = true;
	for (int iter = 1; iter < n; iter++) {
		const auto &pr = chi.back().first;
		for (int i = 0; i < n; i++) {
			if (used[i]) continue;
			const auto &p = pi[i].first;
			int sgn = 0;
			bool flag = true;
			for (int j = 0; j < n; j++) {
				if (j == i) continue;
				if (p.first == pr.first && p.second == pr.second) continue;
				int s = cross(pr, p, pi[j].first) > 0 ? 1 : -1;
				flag &= sgn == 0 || s == sgn;
				sgn = s;
			}
			if (flag) {
				if (chi.size() >= 2) {
					const auto &pb = chi[chi.size() - 2].first;
					double s = (pr.first - p.first)*(pb.second - p.second);
					s -= (pb.first - p.first)*(pr.second - p.second);
					s /= 2.;
					s = abs(s);
					if (s < 1e-8) {
						chi.pop_back();
					}
				}
				chi.push_back(pi[i]);
				used[i] = true;
				break;
			}
		}
	}
	if (chi.size() >= 3) {
		const auto &pr = chi.back().first;
		const auto &pb = chi[chi.size() - 2].first;
		const auto &p = chi[0].first;
		double s = (pr.first - p.first)*(pb.second - p.second);
		s -= (pb.first - p.first)*(pr.second - p.second);
		s /= 2.;
		s = abs(s);
		if (s < 1e-8) {
			chi.pop_back();
		}
	}
	vector<double> ans(n);
	int m = chi.size();
	if (m >= 3) {
		for (int i = 0; i < m; i++) {
			const auto &pr = chi[(i - 1 + m) % m].first;
			const auto &pn = chi[(i + 1) % m].first;
			const auto &p = chi[i].first;
			pair<double, double> u = { p.first - pr.first, p.second - pr.second };
			pair<double, double> v = { p.first - pn.first, p.second - pn.second };
			double ang = acos((u.first*v.first + u.second*v.second) / abs(u) / abs(v));
			double r = acos(-1) - ang;
			ans[chi[i].second] = r / (2 * acos(-1));
		}
	}
	else {
		for (int i = 0; i < m; i++) {
			ans[chi[i].second] = 0.5;
		}
	}
	for (int i = 0; i < n; i++) printf("%.15f\n", ans[i]);
	int b = 2 * 0.;
	return 0;
}

//点iの領域は, 線分i-jの垂直2等分線(j≠i, 1≦j≦n)によって作られるが、全体を1としたときの面積は垂直2等分線同士の角度で求められる。
//変形すると、単に方向ベクトルi->j同士(i:固定, j:i以外)の角度で求められる。
//ある方向ベクトルi->j1を基準(Re=1, Im=0)に取り、反時計回りに進む方向を角度(0～2 * PI)正としたときの、方向ベクトルの最大角度
//をA(i, j1)とおくと、X = min(A(i, 1), …, A(i, n)) (2項目はi以外)がPI以上なら「i行目の答え = 0」、
//PI未満なら「i行目の答え = (PI - X) / (2 * PI)」になる。「基準i->j1以外の方向ベクトルの角度値を0超えにしたいこと・第3,4象限」を考慮すると、
//円環数列のテクの応用によって、O(N^2)に落とせる。
//注意点としては、円環数列を作る前に角度をソートする必要があること！！！

#include <iostream>
#include <complex>
#include <algorithm>
#include <cstdio>
using namespace std;
typedef complex<double> P;

double PI = 3.14159265358979;
int n;
P p[100];

int main() {
	int i, j, k;
	cin >> n;
	for (i = 0; i < n; i++) {
		double x, y; cin >> x >> y;
		p[i] = P(x, y);
	}

	for (i = 0; i < n; i++) {
		double ang[198];
		int cnt = 0;
		for (j = 0; j < n; j++) {
			if (j == i) continue;
			ang[cnt++] = arg(p[j] - p[i]);
		}
		sort(ang, ang + cnt);
		for (j = 0; j < cnt; j++) {
			ang[cnt + j] = ang[j] + 2 * PI;
		}

		double minArg = PI;
		for (j = 0; j < cnt; j++) {
			minArg = min(minArg, ang[j + cnt - 1] - ang[j]);
		}
		double ans = (PI - minArg) / (2 * PI);
		printf("%.14f\n", ans);
	}
	return 0;
}

