const double EPS = 1e-6;

struct point{
  double x, y;
  point() {}
  point(double X, double Y) : x(X), y(Y) {}
  point operator -(const point &o){
    point p(x - o.x, y - o.y);
    return p;
  }
  bool operator <(const point &p) const{
    return x < p.x || (x == p.x && y < p.y);
  }
  bool operator ==(const point &o){
    if(fabs(x - o.x) <= EPS && fabs(y - o.y) < EPS)
      return true;
    return false;
  }
  double dist(point &o){
    double d = (x - o.x)*(x - o.x);
    d += (y - o.y)*(y - o.y);
    d = sqrt(d);
    return d;
  }
  double cross_product(const point &a, const point &b) {
    return (a.x - x) * (b.y - y) - (a.y - y) * (b.x - x);
  }
  double point_product(const point &a, const point &b) {
    return (a.x - x) * (b.x - x) + (a.y - y) * (b.y - y);
  }
  double norm() {
    return sqrt(x * x + y * y);
  }
  friend ostream& operator <<(ostream& stream, point &p){
    stream << "(" << p.x << "," << p.y << ")";
    return stream;
  }
};

vector<point> convex_hull(vector<point> P){
  int n = P.size(), k = 0;
  vector<point> H(2 * n);
  sort(P.begin(), P.end());

  for(int i = 0; i < n; ++i){
    while(k >= 2 and H[k-2].cross_product(H[k-1], P[i]) < 0) k--;
    H[k] = P[i];
    k++;
  }

  for(int i = n - 2, t = k + 1; i >= 0; --i){
    while(k >= t and H[k-2].cross_product(H[k-1], P[i]) < 0) k--;
    H[k] = P[i];
    k++;
  }
  H.resize(k);

  return H;
}


