	if(n==2)return printf("0.5\n0.5\n"),0;
	fp(i,1,n)scanf("%d%d",&p[i].x,&p[i].y);
	fp(i,1,n)solve(i);
	pw=1.0/(2*Pi);
	fp(i,1,n)printf("%.10lf\n",ans[i]*pw);
	return 0;
}

