struct L : public std::vector<P> {
    L(const P &a = P(), const P &b = P()) : std::vector<P>(2) {
        begin()[0] = a;
        begin()[1] = b;
    }

    // Ax + By + C = 0
    L(ld A, ld B, ld C) {
        if (std::abs(A) < eps && std::abs(B) < eps) {
            abort();
        } else if (std::abs(A) < eps) {
            *this = L(P(0, -C / B), P(1, -C / B));
        } else if (std::abs(B) < eps) {
            *this = L(P(-C / A, 0), P(-C / A, 1));
        } else {
            *this = L(P(0, -C / B), P(-C / A, 0));
        }
    }
};

struct C {
    P p;
    ld r;
    C(const P &p = 0, ld r = 0) : p(p), r(r) {}
};

G andrewScan(G ps) {
    int N = ps.size(), k = 0;
    std::sort(ps.begin(), ps.end());
    G res(N * 2);
    for (int i = 0; i < N; i++) {
        while (k >= 2 && ccw(res[k - 2], res[k - 1], ps[i]) != CW) k--;
        res[k++] = ps[i];
    }
    int t = k + 1;
    for (int i = N - 2; i >= 0; i--) {
        while (k >= t && ccw(res[k - 2], res[k - 1], ps[i]) != CW) k--;
        res[k++] = ps[i];
    }
    res.resize(k - 1);
    return res;
}

int n;
G ps;

ld cv(P a, P b) {
    const P i(0, 1);
    P c = (a + b) / (ld)2;
    return arg((b - c) * i);
}

vec<ld> solve() {
    map<P, int> id;
    rep(i, n) {
        id[ps[i]] = i;
    }

    auto ch = andrewScan(ps);
    vec<ld> ans(n);
    if (ch.size() == 2) {
        ans[id[ch[0]]] = 0.5;
        ans[id[ch[1]]] = 0.5;
        return ans;
    } else {
        const ld PI = acos(-1);
        rep(i, n) {
            ld a = cv(ch[(i-1) % ch.size()], ch[i]);
            ld b = cv(ch[i], ch[(i+1) % ch.size()]);
            if (a < 0) a += 2 * PI;
            if (b < 0) b += 2 * PI;
            ld ratio = (a - b) / (2 * PI);
            if (ratio < 0) ratio = ratio + 1;
            ans[id[ch[i]]] = ratio;
        }
    }
    return ans;
}

