inline ll area(pll a, pll b, pll c)
{
	return abs(a.F*b.S + b.F*c.S + c.F*a.S - a.S*b.F - b.S*c.F - c.S*a.F);
}

inline pll slope(pll a, pll b)
{
	b.F -= a.F;
	b.S -= a.S;
	ll g = gcd(abs(b.F),abs(b.S));
	b.F /= g;
	b.S /= g;
	return b;
}

bool is_convex(int ind)
{
	int i, j, k;
	ll val;
	fo(i,1,n+1)
		fo(j,i+1,n+1)
			fo(k,j+1,n+1)
				if(i != ind && j != ind && k != ind)
				{
					val = area(pt[ind],pt[i],pt[j]) + area(pt[ind],pt[j],pt[k]) + area(pt[ind],pt[i],pt[k]);
					if(area(pt[i],pt[j],pt[k]) == val)
						return 0;
				}
	fo(i,1,n+1)
		fo(j,i+1,n+1)
			if(i != ind && j != ind && slope(pt[i],pt[ind]) == slope(pt[ind],pt[j]))
				return 0;
	return 1;
}

inline ld calc(int i, int ind1, int ind2)
{
	pair < ld, ld > v1, v2;
	v1 = {pt[i].F-pt[ind1].F,pt[i].S-pt[ind1].S};
	v2 = {pt[ind2].F-pt[i].F,pt[ind2].S-pt[i].S};
	ld dot = v1.F*v2.F + v1.S*v2.S;
	dot /= sqrtl(v1.F*v1.F + v1.S*v1.S);
	dot /= sqrtl(v2.F*v2.F + v2.S*v2.S);
	dot = acosl(dot);
	return dot;
}

void solve()
{
	int i, j, k, cnt = 0;
	ld dot;
	cin >> n;
	fo(i,1,n+1)
		cin >> pt[i].F >> pt[i].S;
	fo(i,1,n+1)
	{
		mark[i] = is_convex(i);
		if(mark[i])
			cnt++;
	}
	if(cnt == 2)
	{
		fo(i,1,n+1)
		{
			if(mark[i])
				cout << 0.5 << '\n';
			else
				cout << 0.0 << '\n';
		}
		return;
	}
	fo(i,1,n+1)
		if(mark[i])
		{
			dot = PI+PI;
			fo(j,1,n+1)
				fo(k,j+1,n+1)
					if(mark[j] && mark[k] && j != i && k != i)
						dot = min(dot, calc(i,j,k));
			ans[i] = dot/(PI+PI);
		}
	fo(i,1,n+1)
		cout << ans[i] << '\n';
	return;
}

