using namespace std;
typedef long long LL;
const LL MOD = 1000000007LL;
const double EPS = 1e-10;
typedef pair<int, int> PP;
double add(double a, double b) {
	if (abs(a + b) < EPS*(abs(a) + abs(b))) return 0;
	return a + b;
}
struct P {
	double x, y;
	P() {}
	P(double x, double y) :x(x), y(y) {}
	P operator+(P p) const {
		return P(add(x, p.x), add(y, p.y));
	}
	P operator-(P p) const {
		return P(add(x, -p.x), add(y, -p.y));
	}
	double dot(P p) const {
		return add(x*p.x, y*p.y);
	}
	double det(P p) const {
		return add(x*p.y, -y*p.x);
	}
	double norm() const {
		return sqrt(add(x*x, y*y));
	}
};
bool cmp_x(const P& p, const P& q) {
	if (p.x != q.x) return p.x < q.x;
	return p.y < q.y;
}
vector<P> covex_hull(P* ps, int n) {
	sort(ps, ps + n, cmp_x);
	int k = 0;
	vector<P> qs(n * 2);
	for (int i = 0; i < n; i++) {
		while (k > 1 && (qs[k - 1] - qs[k - 2]).det(ps[i] - qs[k - 1]) <= 0) k--;
		qs[k++] = ps[i];
	}
	for (int i = n - 2, t = k; i >= 0; i--) {
		while (k > t && (qs[k - 1] - qs[k - 2]).det(ps[i] - qs[k - 1]) <= 0) k--;
		qs[k++] = ps[i];
	}
	qs.resize(k - 1);
	return qs;
}
map<PP, double> ans;
P ps[100], _ps[100];
int main() {
	int N;
	cin >> N;
	for (int i = 0; i < N; i++) {
		int x, y;
		cin >> x >> y;
		ps[i] = P(x, y);
		_ps[i] = ps[i];
	}
	vector<P> qs = covex_hull(_ps, N);
	double PI = acos(-1);
	for (int i = 0; i < qs.size(); i++) {
		P a = qs[i] - qs[(i - 1 + qs.size()) % qs.size()];
		P b = qs[i] - qs[(i + 1) % qs.size()];
		double t = a.dot(b) / (a.norm()*b.norm());
		double theta = PI - acos(t - EPS);
		ans[PP((int)qs[i].x, (int)qs[i].y)] = theta / (2 * PI);
	}
	for (int i = 0; i < N; i++) {
		printf("%.15lf\n", ans[PP(ps[i].x, ps[i].y)]);
	}
}

