double norm(double d) {
    if (d > M_PI) {
        d -= 2 * M_PI;
    }
    if (d < -M_PI) {
        d += 2 * M_PI;
    }
    return d;
}
double dist(double s, double t) {
    double res = s - t;
    if (res < 0) {
        res += 2 * M_PI;
    }
    return res;
}

bool is_aida(double s, double t, double x) {
    if (s >= t) {
        return s >= x && x >= t;
    } else {
        return (s >= x && t >= x) || (s <= x && t <= x);
    }
}

signed main() {
    cin >> N;
    for (int i = 0; i < N; i++) {
        cin >> x[i] >> y[i];
    }
    double ans[100];
    for (int i = 0; i < N; i++) {
        double start_min = 4, end_min = -4;
        for (int j = 0; j < N; j++) {
            if (i == j) {
                continue;
            }
            double cur = atan2(y[i] - y[j], x[i] - x[j]);
            double s = norm(cur + M_PI / 2);
            double t = norm(cur - M_PI / 2);
            if (!is_aida(start_min, end_min, s) &&
                !is_aida(start_min, end_min, t) && !is_aida(s, t, start_min) &&
                !is_aida(s, t, end_min)) {
                start_min = end_min = 0;
                break;
            }
            if (is_aida(start_min, end_min, s)) {
                start_min = s;
            }
            if (is_aida(start_min, end_min, t) || end_min <= -M_PI - 0.5) {
                end_min = t;
            }
        }
        ans[i] = dist(start_min, end_min);
    }
    for (int i = 0; i < N; i++) {
        cout << ans[i] / (2 * M_PI) << endl;
    }
    return 0;
}

