pair<Poly, Poly> ConvexHull(Poly P) {
  sort(P.begin(), P.end(), [](Point a, Point b) {
    return make_pair(a.x, a.y) < make_pair(b.x, b.y);
  });

  Poly up, dw;
  for (auto p : P) {
    while (up.size() >= 2 &&
           det(up[up.size() - 2], up.back(), p) >= 0) // (1)
      up.pop_back();
    up.push_back(p);

    while (dw.size() >= 2 &&
          det(dw[dw.size() - 2], dw.back(), p) <= 0) // (2)
      dw.pop_back();
    dw.push_back(p);
  }
  return { up, dw };
}

