double EPS = 1e-10;
double PI = acos(-1.0);

double add(double a, double b) {
  if (abs(a + b) < EPS * (abs(a) + abs(b))) return 0;
  return a + b;
}

struct P {
  double x, y;
  P() {}
  P(double x, double y) : x(x), y(y) {}
  P operator+(P p) {
    return P(add(x, p.x), add(y, p.y));
  }
  P operator-(P p) {
    return P(add(x, -p.x), add(y, -p.y));
  }
  P operator*(double d) {
    return P(x * d, y * d);
  }
  double dot(P p) {
    return add(x * p.x, y * p.y);
  }
  double det(P p) {
    return add(x * p.y, -y * p.x);
  }
  double abs() {
    return sqrt(add(x * x, y * y));
  }
  P rotate90() {
    return P(y, -x);
  }
  bool operator==(P& p) {
    return fabs(x - p.x) < EPS && fabs(y - p.y) < EPS;
  }
};

bool cmp_x(const P& p, const P& q) {
  if (p.x != q.x) return p.x < q.x;
  return p.y < q.y;
}

vector<P> convex_hull(vector<P> ps, int n) {
  sort(ps.begin(), ps.end(), cmp_x);
  int k = 0;
  vector<P> qs(n * 2);
  for (int i = 0; i < n; i++) {
    while (k > 1 && (qs[k - 1] - qs[k - 2]).det(ps[i] - qs[k - 1]) <= 0) k--;
    qs[k++] = ps[i];
  }
  for (int i = n - 2, t = k; i >= 0; i--) {
    while (k > t && (qs[k - 1] - qs[k - 2]).det(ps[i] - qs[k - 1]) <= 0) k--;
    qs[k++] = ps[i];
  }
  qs.resize(k - 1);
  return qs;
}

int main() {
  cin.tie(0);
  ios_base::sync_with_stdio(false);

  int N;
  cin >> N;

  vector<P> a(N);
  for (int i = 0; i < N; i++) {
    cin >> a[i].x >> a[i].y;
  }

  vector<P> b = convex_hull(a, N);
  int bz = b.size();
  vector<double> ans(N, 0.0);
  for (int i = 0; i < N; i++) {
    int id = -1;
    for (int j = 0; j < bz; j++) {
      if (b[j] == a[i]) id = j;
    }
    if (id < 0) continue;
    P L = (b[id == 0 ? bz - 1 : id - 1] - b[id]).rotate90();
    P R = (b[id == bz - 1 ? 0 : id + 1] - b[id]).rotate90();
    ans[i] = bz == 2 ? 0.5 : (PI - acos(L.dot(R) / L.abs() / R.abs())) / 2 / PI;
  }

  for (int i = 0; i < N; i++) {
    printf("%.10f\n", ans[i]);
  }

  return 0;
}

