    V prev = vv[ch[m-1]];
    for (int i=0; i<m; i++) {
        V cur = vv[ch[i]],
          next = vv[ch[(i+1)%m]];
        // cerr << cur - prev << ' ' << next - cur << ' ' << acos(cos_between(cur - prev, next - cur)) << '\n';
        ans[ch[i]] = acos(cos_between(cur - prev, next - cur)) / (2 * M_PI);
        prev = cur;
    }
    for (auto &ai:ans) cout << setprecision(15) << ai << '\n';
    return 0;
}

