vpii convex_hull(vpii P){
	size_t n = P.size(), k = 0;
	if (n <= 3) return P;
	vector<pii> H(2*n);
	sort(P.begin(), P.end());
	for (size_t i = 0; i < n; ++i) {
		while (k >= 2 && cross(H[k-2], H[k-1], P[i]) <= 0) k--;
		H[k++] = P[i];
	}
	for (size_t i = n-1, t = k+1; i > 0; --i) {
		while (k >= t && cross(H[k-2], H[k-1], P[i-1]) <= 0) k--;
		H[k++] = P[i-1];
	}
	H.resize(k-1);
	return H;
}

