}
bool cmp1(p a,p b){
   if (a.y == b.y){
    return a.x < b.x; 
   }
   return a.y < b.y;
}
bool cmp2(p a,p b)
{   
    p O;
    O.x = xx;
    O.y = yy;
    if (cross(O,a,b) == 0){
       return dis(O,a) < dis(O,b);
    }
    return cross(O,a,b) > 0;
}
