}

struct P {
	double x,y;
	P() {}
	P(double x, double y) : x(x), y(y) {
	}
	P operator + (P p) {
		return P(add(x, p.x), add(y, p.y));
	}
	P operator - (P p) {
		return P(add(x, -p.x), add(y, -p.y));
	}
	P operator * (double d) {
		return P(x*d, y*d);
	}
	double dot(P p){
		return add(x*p.x, y*p.y);
	}
	double det(P p){
		return add(x*p.y, -y*p.x);
	}
};

bool cmp_x(const P& p, const P& q){
	if(p.x != q.x) return p.x < q.x;
	return p.y < q.y;
}

vector<P> convex_hull(P* ps, int n){
	sort(ps, ps+n, cmp_x);
	int k=0;

	vector<P> qs(n*2);
	for(int i=0; i<n; i++){
		while(k>1 && (qs[k-1] - qs[k-2]).det(ps[i] - qs[k-1])<=0) k--;
		qs[k++] = ps[i];
	}

	for(int i=n-2, t=k; i>=0; i--){
		while(k>t && (qs[k-1] - qs[k-2]).det(ps[i] - qs[k-1])<=0) k--;
		qs[k++] = ps[i];
	}
	qs.resize(k-1);
	return qs;
}

int N;
P ps[100];
P ps2[100];

int main(){
	scanf("%d", &N);
	for(int i=0;i<N; i++){
		int x,y;
		scanf("%d %d", &x, &y);
		ps[i] = P(x,y);
		ps2[i] = P(x,y);
	}

	vector<P> qs = convex_hull(ps, N);

	pair<double,double> vec[N];
	double deg[N];

	for(int i=0;i<qs.size();i++){
		double x1,y1,d;
		if(i<qs.size()-1){
			x1 = qs[i+1].x - qs[i].x;
			y1 = qs[i+1].y - qs[i].y;
			d = sqrt(x1*x1+y1*y1);
			vec[i] = make_pair(y1/d,-x1/d);
		}else{
			x1 = qs[0].x - qs[i].x;
			y1 = qs[0].y - qs[i].y;
			d = sqrt(x1*x1+y1*y1);
			vec[i] = make_pair(y1/d,-x1/d);
		}
	}

	for(int i=0;i<qs.size();i++){
		double cosin;
		if(i<qs.size()-1){
			cosin = vec[i].first*vec[i+1].first + vec[i].second*vec[i+1].second;
			deg[i] = acos(cosin);
		}else{
			cosin = vec[i].first*vec[0].first + vec[i].second*vec[0].second;
			deg[i] = acos(cosin);
		}

	}


	double ans[N];
	for(int i=0;i<N;i++) ans[i] = 0;

	for(int i=0;i<qs.size();i++){
		int num = i;

		for(int j=0;j<N;j++){
			if(ps2[j].x == qs[i].x && ps2[j].y == qs[i].y) num = j;
		}
		if(i>0){
			ans[num] = deg[i-1]/(2*M_PI);
		}else{
			ans[num] = deg[qs.size()-1]/(2*M_PI);
		}


	}

	for(int i=0;i<N;i++){
		printf("%f\n", ans[i]);
	}


	return 0;
}

