#define ll long long
#define rep(i,l,r) for(ll i=(l);i<(r);i++)
#define INF ((1LL<<62)-(1LL<<31))
#define PI 3.14159265358979323


typedef struct point{double x,y;ll n;}P;

//凸包を求める。点の配列を引いて、凸包を構成する点のindexを求め、その要素数を返す
//O(nlogn)
#define menseki(p,q)(p.x*q.y-p.y*q.x)
ll pindex[110];
int pointhikaku(const void*p,const void*q){
	//辞書順ソート
	P pp=*(P*)p,qq=*(P*)q;
	if(pp.x<qq.x)return -1;
	if(pp.x>qq.x)return  1;
	if(pp.y<qq.y)return -1;
	return 1;
} 
int pointhikaku2(const void*p,const void*q){
	//argでソート
	P pp=*(P*)p,qq=*(P*)q;
	double diff=atan2(pp.y,pp.x)-atan2(qq.y,qq.x);
	return diff>0?1:diff<0?-1:0;
}
ll totuhou(P*a,ll cnt){
	//https://www.jaist.ac.jp/~uehara/course/2014/i481f/pdf/ppt-3.pdfによる
	if(cnt<=2){
		rep(i,0,cnt)pindex[i]=i;
		return cnt;
	}

	P*t=(P*)malloc(cnt*sizeof(P));
	P O;
	O.x=a[0].x+a[1].x+a[2].x;
	O.y=a[0].y+a[1].y+a[2].y;

	rep(i,0,cnt){
		t[i].x=a[i].x*3-O.x;
		t[i].y=a[i].y*3-O.y;
		t[i].n=a[i].n;
	}

	qsort(t,cnt,sizeof(P),pointhikaku2);
	//このソートによりx軸負の位置から反時計回りに並ぶ

	//x軸最小の点を選ぶ
	double mx=10000000;
	ll mi;
	rep(i,0,cnt)if(t[i].x<mx){
		mx=t[i].x;
		mi=i;
	}

	ll anscnt=2;
	pindex[0]=mi;
	pindex[1]=(mi+1)%cnt;
	rep(i,2,cnt+1){
		//リストの最後の2つと今見てる点の3つが凸orリストが1点　になるまで点を削除
		//Oの反時計回り順にある3点ABCが凸⇔△OAB+△OBC>△OAC
		while(anscnt>=2){
			ll a=pindex[anscnt-2];
			ll b=pindex[anscnt-1];
			ll c=(mi+i)%cnt;
			if(menseki(t[a],t[b])+menseki(t[b],t[c])>menseki(t[a],t[c]))break;
			anscnt--;
		}
		pindex[anscnt++]=(mi+i)%cnt;
	}
	//全ての点が同一直線状にあるときanscnt(=リストの長さ)は2
	//そうでないとき4以上で、これは凸包を構成する点の数+1(pindex[0]==pindex[anscnt-1])
	if(anscnt>2){
		rep(i,0,anscnt)pindex[i]=t[pindex[i]].n;//元のindexに戻す
		return anscnt-1;
	}else{
		//全ての点が同一直線上
		//ソートして端の点を返す
		qsort(t,cnt,sizeof(P),pointhikaku);
		pindex[0]=t[    0].n;
		pindex[1]=t[cnt-1].n;
		return 2;
	}
}


P ppp[110];
double ans[110];

double kakudo(ll a,ll b,ll c){
	//反時計回りの3点a,b,cのなす角度を求める
	double siita=atan2(ppp[a].y-ppp[b].y,ppp[a].x-ppp[b].x)-atan2(ppp[c].y-ppp[b].y,ppp[c].x-ppp[b].x);
	while(siita>2*PI)siita-=2*PI;
	while(siita<0)siita+=2*PI;
	return siita;
}

int main(){
	int n;
	scanf("%d",&n);
	rep(i,0,n){
		int x,y;
		scanf("%d%d",&x,&y);
		ppp[i].x=x;
		ppp[i].y=y;
		ppp[i].n=i;
	}

	ll x=totuhou(ppp,n);	
	rep(i,0,x){
		ll a=pindex[(i-1+x)%x];
		ll b=pindex[i];
		ll c=pindex[(i+1)%x];
		ans[b]=(PI-kakudo(a,b,c))/(2*PI);
	}
	rep(i,0,n)printf("%.9f\n",ans[i]);
	return 0;
}

