data class Double2D(val x: Double, val y: Double) {
  operator fun plus(o: Double2D) = Double2D(x + o.x, y + o.y)
  operator fun minus(o: Double2D) = Double2D(x - o.x, y - o.y)
  operator fun times(o: Double) = Double2D(x * o, y * o)
  fun norm2() = x * x + y * y
  fun norm() = Math.sqrt(x * x + y * y)
}

fun cross(v1: Double2D, v2: Double2D) = v1.x * v2.y - v1.y * v2.x

fun dot(v1: Double2D, v2: Double2D) = v1.x * v2.x + v1.y * v2.y

fun ccw(p: Double2D, q: Double2D, r: Double2D): Int {
  val vq = q - p
  val vr = r - p
  if (cross(vq, vr) > 0)   return +1     // counter clockwise
  if (cross(vq, vr) < 0)   return -1     // clockwise
  if (dot(vq, vr) < 0)     return +2     // r-p-q on line
  if (vq.norm2() < vr.norm2()) return -2 // p-q-r on line
  return 0
}

fun compareDouble2D(p1: Double2D, p2: Double2D): Int {
  if (p1.x != p2.x) {
    return java.lang.Double.compare(p1.x, p2.x)
  }
  return java.lang.Double.compare(p1.y, p2.y)
}

fun convexHull(inputPs: List<Double2D>): List<Double2D> {
