  val ps = inputPs.sortedWith(java.util.Comparator { p1, p2 -> compareDouble2D(p1, p2) })
  val n = ps.size
  val qs = mutableListOf<Double2D>()
  for (i in 0 until n) {
    while (qs.size >= 2 &&
        // Use "<= 0" here to exclude a point on an edge.
        ccw(qs[qs.size - 2], qs[qs.size - 1], ps[i]) == -1) {
      qs.removeAt(qs.size - 1)
    }
    qs.add(ps[i])
  }
  val lowerHullSize = qs.size
  for (i in n - 2 downTo 0) {
    while (qs.size >= lowerHullSize &&
