public class Main implements Runnable {
    static ContestScanner in;
    static Writer out;
    public static void main(String[] args) {
        new Thread(null, new Main(), "", 16 * 1024 * 1024).start();
    }

    public void run() {
        Main main = new Main();
        try {
            in = new ContestScanner();
            out = new Writer();
            main.solve();
            out.close();
            in.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    void solve() throws IOException {
        int n = in.nextInt();
        List<int[]> list = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            int[] p = {in.nextInt(), in.nextInt(), i};
            list.add(p);
        }
        // ch.get(last) contains first
        List<int[]> ch = convexHull(list);
        double[] ans = new double[n];

        for (int i = 0; i < ch.size(); i++) {
            int[] p = ch.get(i);
            int[] pre = ch.get((i - 1 + ch.size()) % ch.size());
            int[] post = ch.get((i + 1 + ch.size()) % ch.size());
            int x1 = pre[0] - p[0];
            int y1 = pre[1] - p[1];
            int x2 = post[0] - p[0];
            int y2 = post[1] - p[1];
            double a = angle(x1, y1, x2, y2);
            ans[p[2]] = (Math.PI - a) / (Math.PI * 2);
        }
        for (int i = 0; i < n; i++) {
            System.out.println(ans[i]);
        }
    }

    public static List<int[]> convexHull(List<int[]> list){
        int k = 0;
        Collections.sort(list, new Comparator<int[]>(){
            @Override
            public int compare(int[] o1, int[] o2) {
                if(o1[0] != o2[0]) return o1[0]-o2[0];
                return o1[1]-o2[1];
            }
        });
        int n = list.size();
        int[][] qs = new int[n*2][2];
        for(int i=0; i<n; i++){
            while(k > 1 && cross(qs[k-2], qs[k-1], qs[k-1], list.get(i)) < 0) k--;
            qs[k++] = list.get(i);
        }

        for(int i=n-2, t=k; i>=0; i--){
            while(k > t && cross(qs[k-2], qs[k-1], qs[k-1], list.get(i)) < 0) k--;
            qs[k++] = list.get(i);
        }

        List<int[]> res = new ArrayList<>();
        for(int i=0; i<k-1; i++){
            res.add(qs[i]);
        }
        return res;
    }

    public static int cross(int[] p11, int[] p12, int[] p21, int[] p22){
        return (p12[0]-p11[0])*(p22[1]-p21[1]) - (p22[0]-p21[0])*(p12[1]-p11[1]);
    }

    double angle(double x1, double y1, double x2, double y2){
        double a1 = Math.atan2(y1, x1);
        double a2 = Math.atan2(y2, x2);
        double rad = Math.abs(a1-a2);
        if(rad>Math.PI) rad = 2*Math.PI - rad;
        return rad;
    }
}

