			d[i] = Math.sqrt((gx - z[i].x) * (gx - z[i].x) + (gy - z[i].y) * (gy - z[i].y));
			sum += d[i];
		}
		for (int i = 0; i < n; i++) {
			System.out.println(d[i] / sum);
		}

	}
	public static  class Point {
		int x, y;
		public Point(int x, int y) {
			this.x = x;
			this.y = y;
		}
	}
}

import java.io.OutputStream;
