public class Main {

  public static void main(String[] args) {
    InputStream inputStream = System.in;
    OutputStream outputStream = System.out;
    InputReader in = new InputReader(inputStream);
    OutputWriter out = new OutputWriter(outputStream);
    TaskB solver = new TaskB();
    solver.solve(1, in, out);
    out.close();
  }

  static class TaskB {

    public void solve(int testNumber, InputReader in, OutputWriter out) {
      int n = in.nextInt();
      ConvexHull.Point[] a = new ConvexHull.Point[n];
      for (int i = 0; i < n; ++i) {
        a[i] = new ConvexHull.Point(in.nextLong(), in.nextLong());
      }
      double[] res = new double[n];
      ConvexHull.Point[] backup = Arrays.copyOf(a, a.length);
      ConvexHull.Point[] b = ConvexHull.convexHull(a);
      a = backup;
      int[] ind = new int[b.length];
      for (int i = 0; i < b.length; ++i) {
        for (int j = 0; j < a.length; ++j) {
          if (a[j].x == b[i].x && a[j].y == b[i].y) {
            ind[i] = j;
          }
        }
      }
      for (int i = 0; i < b.length; ++i) {
        int j = (i + 1) % b.length;
        int k = (i + 2) % b.length;
        PointInt p1 = new PointInt((int) (b[j].x - b[i].x), (int) (b[j].y - b[i].y));
        PointInt p2 = new PointInt((int) (b[k].x - b[j].x), (int) (b[k].y - b[j].y));
        double alpha = Math.abs(Math.atan2(p1.cross(p2), p1.scalar(p2)));
        res[ind[j]] = alpha * 0.5 / Math.PI;
      }
      for (int i = 0; i < n; ++i) {
        out.printLine(res[i]);
      }
    }

  }

  static class ConvexHull {

    static boolean cw(ConvexHull.Point a, ConvexHull.Point b, ConvexHull.Point c) {
      return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x) < 0;
    }

    public static ConvexHull.Point[] convexHull(ConvexHull.Point[] p) {
      int n = p.length;
      if (n <= 1) {
        return p;
      }
      Arrays.sort(p);
      ConvexHull.Point[] q = new ConvexHull.Point[n * 2];
      int cnt = 0;
      for (int i = 0; i < n; q[cnt++] = p[i++]) {
        for (; cnt > 1 && !cw(q[cnt - 2], q[cnt - 1], p[i]); --cnt) {
          ;
        }
      }
      for (int i = n - 2, t = cnt; i >= 0; q[cnt++] = p[i--]) {
        for (; cnt > t && !cw(q[cnt - 2], q[cnt - 1], p[i]); --cnt) {
          ;
        }
      }
      ConvexHull.Point[] res = new ConvexHull.Point[cnt - 1 - (q[0].compareTo(q[1]) == 0 ? 1 : 0)];
      System.arraycopy(q, 0, res, 0, res.length);
      return res;
    }

    public static class Point implements Comparable<ConvexHull.Point> {

      public long x;
      public long y;

      public Point(long x, long y) {
        this.x = x;
        this.y = y;
      }

      public int compareTo(ConvexHull.Point o) {
        int sx = Long.signum(x - o.x);
        return sx != 0 ? sx : Long.signum(y - o.y);
      }

    }

  }

  static class InputReader {

    private InputStream stream;
    private byte[] buffer = new byte[10000];
    private int cur;
    private int count;

    public InputReader(InputStream stream) {
      this.stream = stream;
    }

    public static boolean isSpace(int c) {
      return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    public int read() {
      if (count == -1) {
        throw new InputMismatchException();
      }
      try {
        if (cur >= count) {
          cur = 0;
          count = stream.read(buffer);
          if (count <= 0) {
            return -1;
          }
        }
      } catch (IOException e) {
        throw new InputMismatchException();
      }
      return buffer[cur++];
    }

    public int readSkipSpace() {
      int c;
      do {
        c = read();
      } while (isSpace(c));
      return c;
    }

    public int nextInt() {
      int sgn = 1;
      int c = readSkipSpace();
      if (c == '-') {
        sgn = -1;
        c = read();
      }
      int res = 0;
      do {
        if (c < '0' || c > '9') {
          throw new InputMismatchException();
        }
        res = res * 10 + c - '0';
        c = read();
      } while (!isSpace(c));
      res *= sgn;
      return res;
    }

    public long nextLong() {
      long sgn = 1;
      int c = readSkipSpace();
      if (c == '-') {
        sgn = -1;
        c = read();
      }
      long res = 0;
      do {
        if (c < '0' || c > '9') {
          throw new InputMismatchException();
        }
        res = res * 10L + (long) (c - '0');
        c = read();
      } while (!isSpace(c));
      res *= sgn;
      return res;
    }

  }

  static class PointInt {

    public int x;
    public int y;

    public PointInt(int x, int y) {
      this.x = x;
      this.y = y;
    }

    public PointInt() {
      x = 0;
      y = 0;
    }

    public long cross(PointInt p) {
      return (long) x * (long) p.y - (long) y * (long) p.x;
    }

    public long scalar(PointInt p) {
      return (long) x * (long) p.x + (long) y * (long) p.y;
    }

  }

  static class OutputWriter {

    private final PrintWriter writer;

    public OutputWriter(OutputStream outputStream) {
      writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
    }

    public OutputWriter(Writer writer) {
      this.writer = new PrintWriter(writer);
    }

    public void print(Object... objects) {
      for (int i = 0; i < objects.length; i++) {
        if (i != 0) {
          writer.print(' ');
        }
        writer.print(objects[i]);
      }
    }

    public void printLine(Object... objects) {
      print(objects);
      writer.println();
    }

    public void close() {
      writer.close();
    }

  }
}

import java.io.*;
import java.util.*;


public class Main implements Runnable {

  public void run() {
    BetterScanner scanner = new BetterScanner(System.in);

    int n = scanner.nextInt();
    int[] xx = new int[n];
    int[] yy = new int[n];

    int a = 0;
    int minY = 10000000;
    int minX = 10000000;
    for (int i = 0 ; i < n ; i ++) {
      int x = scanner.nextInt();
      int y = scanner.nextInt();
      xx[i] = x;
      yy[i] = y;
      if (y <= minY) {
        // 2 つの処理の順番間違えただけなんです許してください (´・ω・｀)
        if (y < minY) {
          minX = 10000000;
        }
        minY = y;
        if (y == minY && x < minX) {
          minX = x;
          a = i;
        }
      }
    }

    List<Integer> hulls = new ArrayList(n);
    int firstA = a;
    int b, c;
    do {
      hulls.add(a);
      b = 0;
      for (int i = 1 ; i < n ; i ++) {
        c = i;
        if (b == a) {
          b = c;
        } else {
          long v = (long)(xx[a] - xx[b]) * (yy[a] - yy[c]) - (long)(xx[a] - xx[c]) * (yy[a] - yy[b]);
          if (v > 0L) {
            b = c;
          } else if (v == 0L) {
            long ab = (long)(xx[a] - xx[b]) * (xx[a] - xx[b]) + (long)(yy[a] - yy[b]) * (yy[a] - yy[b]);
            long ac = (long)(xx[a] - xx[c]) * (xx[a] - xx[c]) + (long)(yy[a] - yy[c]) * (yy[a] - yy[c]);
			if (ac > ab) {
              b = c;
            }
          }
        }
      }
      a = b;
    } while (a != firstA); 

    int m = hulls.size();
    double[] props = new double[n];
    for (int k = 0 ; k < m ; k ++) {
      int i = hulls.get(k);
      int nextI = (k < m - 1) ? hulls.get(k + 1) : hulls.get(0);
      int previousI = (k >= 1) ? hulls.get(k - 1) : hulls.get(m - 1);
      double nextTan = Math.atan2(yy[nextI] - yy[i], xx[nextI] - xx[i]) + Math.PI / 2;
      double previousTan = Math.atan2(yy[i] - yy[previousI], xx[i] - xx[previousI]) + Math.PI / 2;
      if (nextTan > Math.PI) {
        nextTan -= 2 * Math.PI;
      }
      if (previousTan > Math.PI) {
        previousTan -= 2 * Math.PI;
      }
      double range = previousTan - nextTan;
      if (range < 0) {
        range += 2 * Math.PI;
      }
      props[i] = range / (2 * Math.PI);
    }

    for (int i = 0 ; i < n ; i ++) {
      System.out.println(props[i]);
    }
  }

  public static void main(String[] args) {
    Main main = new Main();
    main.run();
  }

  // scanner slightly faster than usual ones
  public static class BetterScanner {

    private InputStream stream;
    private byte[] buffer = new byte[1024];
    private int pointer = 0;
    private int bufferLength = 0;

    public BetterScanner(InputStream stream) {
      this.stream = stream;
    }

    private boolean updateBuffer() {
      if (pointer >= bufferLength) {
        pointer = 0;
        try {
          bufferLength = stream.read(buffer);
        } catch (IOException exception) {
          exception.printStackTrace();
        }
        return bufferLength > 0;
      } else {
        return true;
      }
    }

    private int read() {
      if (updateBuffer()) {
        return buffer[pointer ++];
      } else {
        return -1;
      }
    }

    public boolean hasNext() {
      skipUnprintable();
      return updateBuffer();
    }

    private void skipUnprintable() { 
      while (updateBuffer() && !isPrintableChar(buffer[pointer])) {
        pointer ++;
      }
    }

    public String next() {
      if (hasNext()) {
        StringBuilder builder = new StringBuilder();
        int codePoint = read();
        while (isPrintableChar(codePoint)) {
          builder.appendCodePoint(codePoint);
          codePoint = read();
        }
        return builder.toString();
      } else {
        throw new NoSuchElementException();
      }
    }

    public long nextLong() {
      if (hasNext()) {
        long number = 0;
        boolean minus = false;
        int codePoint = read();
        if (codePoint == '-') {
          minus = true;
          codePoint = read();
        }
        if (codePoint >= '0' && codePoint <= '9') {
          while (true) {
            if (codePoint >= '0' && codePoint <= '9') {
              number *= 10;
              number += codePoint - '0';
            } else if (codePoint < 0 || !isPrintableChar(codePoint)) {
              return (minus) ? -number : number;
            } else {
              throw new NumberFormatException();
            }
            codePoint = read();
          }
        } else {
          throw new NumberFormatException();
        }
      } else {
        throw new NoSuchElementException();
      }
    }

    public int nextInt() {
      long number = nextLong();
      if (number >= Integer.MIN_VALUE && number <= Integer.MAX_VALUE) {
        return (int)number;
      } else {
        throw new NumberFormatException();
      }
    }

    private boolean isPrintableChar(int codePoint) {
      return codePoint >= 33 && codePoint <= 126;
    }

  }

}

