        int n = fsc.nextInt();
        Complex[] c = new Complex[n];
        for (int i = 0; i < n; i++) {
            int x = fsc.nextInt();
            int y = fsc.nextInt();
            c[i] = new Complex(x, y);
        }
        double[] p = new double[n];
        ArrayList<Integer> convexHull = Geometry.giftWrapping(c);
        int v = convexHull.size();
        for (int j = 0; j < v; j++) {
            int y = convexHull.get(j);
            int z = convexHull.get((j + 1) % v);
            int x = convexHull.get((j - 1 + v) % v);
            double arg = Math.PI - Geometry.arg(c[x], c[y], c[z]);
            p[y] = arg / (2 * Math.PI);
        }
