import java.io.IOException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) throws IOException {
		new Main().run();
	}

	void run() {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		double[] x = new double[n];
		double[] y = new double[n];
		for (int i = 0; i < n; ++i) {
			x[i] = sc.nextDouble();
			y[i] = sc.nextDouble();
		}
		for (int i = 0; i < n; ++i) {
			double[] deg = new double[n - 1];
			int cnt = 0;
			for (int j = 0; j < n; ++j) {
				if (i == j)
					continue;
				deg[cnt++] = (Math.atan2(y[j] - y[i], x[j] - x[i]));
			}
			for (int j = 0; j < deg.length; ++j)
				if (deg[j] < 0)
					deg[j] += Math.PI * 2;
			Arrays.sort(deg);
			double ans = 0;
			for (int j = 0; j < n - 1; ++j) {
				ans = Math.max(ans, (Math.PI * 2 + deg[(j + 1) % (n - 1)] - deg[j]) % (2 * Math.PI));
			}
			if (n == 2)
				ans = 2 * Math.PI;
			ans = ans - Math.PI;
			if (ans <= 0)
				System.out.println(0);
			else
				System.out.println(ans / (2 * Math.PI));
		}
	}

	void tr(Object... objects) {
		System.out.println(Arrays.deepToString(objects));
	}
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.TreeMap;

public class Main {
	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		int n = Integer.parseInt(br.readLine());
		int[] x = new int[n];
		int[] y = new int[n];
		for (int i = 0; i < n; i++) {
			String[] sa = br.readLine().split(" ");
			x[i] = Integer.parseInt(sa[0]);
			y[i] = Integer.parseInt(sa[1]);
		}
		br.close();

		double p2 = Math.PI * 2;
		for (int i = 0; i < n; i++) {
			TreeMap<Double, Double> map = new TreeMap<>();
			map.put(0d, p2);
			for (int j = 0; j < n; j++) {
				if (i != j) {
					double d = Math.atan2(y[j] - y[i], x[j] - x[i]);
					d += Math.PI / 2 + p2;
					d %= p2;
					if (d <= Math.PI) {
						double d2 = d + Math.PI;
						Double l = map.lowerKey(d);
						Double l2 = map.lowerKey(d2);
						if (l2 != null) {
							if (l != l2) {
								map.put(l2, Math.min(d2, map.get(l2)));
							}
						}
						if (l != null) {
							if (map.get(l) > d) {
								map.put(d, Math.min(d2, map.get(l)));
							}
							map.remove(l);
						}
						Double h2 = map.ceilingKey(d2);
						if (h2 != null) {
							map.remove(h2);
						}
					} else {
						double d2 = d - Math.PI;
						Double l = map.lowerKey(d);
						Double l2 = map.lowerKey(d2);
						Double h = map.ceilingKey(d);
						if (l != null) {
							if (l == l2) {
								if (map.get(l) > d) {
									map.put(d, Math.min(p2, map.get(l)));
								}
							} else {
								if (h == null) {
									if (map.get(l) > d) {
										map.put(d, Math.min(p2, map.get(l)));
									}
								}
								map.remove(l);
							}
						}
						if (l2 != null) {
							map.put(l2, Math.min(d2, map.get(l2)));
						}
					}
				}
			}
			double val = 0;
			for (Double d : map.keySet()) {
				if (map.get(d) < d) {
					throw new Exception();
				}
				val += map.get(d) - d;
			}
			System.out.println(val / p2);
		}
	}
}

import java.io.*;
import java.util.*;


public class Main implements Runnable {

  public void run() {
    BetterScanner scanner = new BetterScanner(System.in);

    int n = scanner.nextInt();
    int[] xx = new int[n];
    int[] yy = new int[n];

    // 最も上 (y 座標が小さい) にある点のインデックスを求める
    // y 座標が最小の点が複数ある場合はその中の最も左のものにしておく
    int a = 0;
    int minY = 10000000;
    int minX = 10000000;
    for (int i = 0 ; i < n ; i ++) {
      int x = scanner.nextInt();
      int y = scanner.nextInt();
      xx[i] = x;
      yy[i] = y;
      if (y < minY || (y == minY && x < minX)) {
        minY = y;
        minX = x;
        a = i;
      }
    }
    List<Integer> outers = new ArrayList(n);
    int b;
    do {
      outers.add(a);
      b = 0;
      for (int c = 1 ; c < n ; c ++) {
        if (b == a) {
          b = c;
        } else {
          long v = (long)(xx[a] - xx[b]) * (yy[a] - yy[c]) - (long)(xx[a] - xx[c]) * (yy[a] - yy[b]);
          long ab = (long)(xx[a] - xx[b]) * (xx[a] - xx[b]) + (long)(yy[a] - yy[b]) * (yy[a] - yy[b]);
          long ac = (long)(xx[a] - xx[c]) * (xx[a] - xx[c]) + (long)(yy[a] - yy[c]) * (yy[a] - yy[c]);
          if (v > 0L || (v == 0L && ac > ab)) {
            b = c;
          }
        }
      }
      a = b;
    } while (a != outers.get(0)); 

    int m = outers.size();
    double[] props = new double[n];
    for (int k = 0 ; k < m ; k ++) {
      int i = outers.get(k);
      int nextI = (k < m - 1) ? outers.get(k + 1) : outers.get(0);
      int previousI = (k >= 1) ? outers.get(k - 1) : outers.get(m - 1);
      // 凸包上で隣り合う点との垂直二等分線の角度を計算
      double nextTan = Math.atan2(yy[nextI] - yy[i], xx[nextI] - xx[i]) + Math.PI / 2;
      double previousTan = Math.atan2(yy[i] - yy[previousI], xx[i] - xx[previousI]) + Math.PI / 2;
      if (nextTan > Math.PI) {
        nextTan -= 2 * Math.PI;
      }
      if (previousTan > Math.PI) {
        previousTan -= 2 * Math.PI;
      }
      double range = previousTan - nextTan;
      if (range < 0) {
        range += 2 * Math.PI;
      }
      // 隣り合う点との垂直二等分線の角度の差を 2π でわったものが確率
      props[i] = range / (2 * Math.PI);
    }
    for (int i = 0 ; i < n ; i ++) {
      System.out.println(props[i]);
    }
  }

  public static void main(String[] args) {
    Main main = new Main();
    main.run();
  }

  // scanner slightly faster than usual ones
  public static class BetterScanner {

    private InputStream stream;
    private byte[] buffer = new byte[1024];
    private int pointer = 0;
    private int bufferLength = 0;

    public BetterScanner(InputStream stream) {
      this.stream = stream;
    }

    private boolean updateBuffer() {
      if (pointer >= bufferLength) {
        pointer = 0;
        try {
          bufferLength = stream.read(buffer);
        } catch (IOException exception) {
          exception.printStackTrace();
        }
        return bufferLength > 0;
      } else {
        return true;
      }
    }

    private int read() {
      if (updateBuffer()) {
        return buffer[pointer ++];
      } else {
        return -1;
      }
    }

    public boolean hasNext() {
      skipUnprintable();
      return updateBuffer();
    }

    private void skipUnprintable() { 
      while (updateBuffer() && !isPrintableChar(buffer[pointer])) {
        pointer ++;
      }
    }

    public String next() {
      if (hasNext()) {
        StringBuilder builder = new StringBuilder();
        int codePoint = read();
        while (isPrintableChar(codePoint)) {
          builder.appendCodePoint(codePoint);
          codePoint = read();
        }
        return builder.toString();
      } else {
        throw new NoSuchElementException();
      }
    }

    public long nextLong() {
      if (hasNext()) {
        long number = 0;
        boolean minus = false;
        int codePoint = read();
        if (codePoint == '-') {
          minus = true;
          codePoint = read();
        }
        if (codePoint >= '0' && codePoint <= '9') {
          while (true) {
            if (codePoint >= '0' && codePoint <= '9') {
              number *= 10;
              number += codePoint - '0';
            } else if (codePoint < 0 || !isPrintableChar(codePoint)) {
              return (minus) ? -number : number;
            } else {
              throw new NumberFormatException();
            }
            codePoint = read();
          }
        } else {
          throw new NumberFormatException();
        }
      } else {
        throw new NoSuchElementException();
      }
    }

    public int nextInt() {
      long number = nextLong();
      if (number >= Integer.MIN_VALUE && number <= Integer.MAX_VALUE) {
        return (int)number;
      } else {
        throw new NumberFormatException();
      }
    }

    private boolean isPrintableChar(int codePoint) {
      return codePoint >= 33 && codePoint <= 126;
    }

  }

}

import java.util.*;

public class Main{	
	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int[] x = new int[N];
		int[] y = new int[N];
		double pi = Math.PI;
		double[] radStart = new double[N];
		double[] radEnd = new double[N];
		boolean[] dead = new boolean[N];
		for(int i=0;i<N;++i){
			x[i] = sc.nextInt();
			y[i] = sc.nextInt();
			radStart[i] = 0.0;
			radEnd[i] = 2.0*pi;
		}

		for(int i=0;i<N;++i){
			for(int j=i+1;j<N;++j){
				double theta = y[i] == y[j] ? pi/2.0 : Math.atan(solvea(x[i],y[i],x[j],y[j]));
				if(theta < 0) theta = pi+theta;
				//System.out.println(Math.tan(theta));
				if(x[i]<=x[j]){
					//i
					if(radEnd[i]<theta && radStart[i]>theta+pi) dead[i] = true;
					else{
						if(radStart[i]<theta) radStart[i] = theta;
						if(radEnd[i]>theta+pi) radEnd[i] = theta+pi;
					}
					//j
					if(radEnd[j] != 2*pi && radEnd[j]>theta+pi && radStart[j]<theta) dead[j] = true;
					else{
						if(radStart[j]<theta+pi) radStart[j] = theta+pi;
						if(radEnd[j] == 2*pi ||(radEnd[j]<pi && radEnd[j]>theta)) radEnd[j] = theta;
					}
				}else{
					//j
					if(radEnd[j]<theta && radStart[j]>theta+pi) dead[j] = true;
					else{
						if(radStart[j]<theta) radStart[j] = theta;
						if(radEnd[j]>theta+pi) radEnd[j] = theta+pi;
					}
					//i
					if(radEnd[i]>theta+pi && radStart[i]<theta) dead[i] = true;
					else{
						if(radStart[i]<theta+pi) radStart[i] = theta+pi;
						if(radEnd[i] == 2*pi ||(radEnd[i]<pi && radEnd[i]>theta)) radEnd[i] = theta;
					}
				}
			}
		}

		for(int i=0;i<N;++i){
			if(dead[i]) System.out.println(0.0);
			else if(radEnd[i]>radStart[i]) System.out.println((radEnd[i]-radStart[i])/(2.0*pi)); 
			else System.out.println((radEnd[i]-radStart[i]+2.0*pi)/(2.0*pi));
		}
		return;
	}

	public static double solvea(int x1,int y1,int x2, int y2){
		return -1.0 * (double)(x2-x1)/(double)(y2-y1);
	}
}

