    static double getTotsu(int[] x, int[] y) {
        int N = x.length;
        ArrayList<Integer> list = new ArrayList<>();
        int start = 0;
        // x座標のもっとも大きい点を始点にする
        for (int i = 1; i < N; i++) {
            if (x[start] < x[i]) start = i;
        }
        boolean[] used = new boolean[N];
        used[start] = true;
        list.add(start);

        // Y軸の正の向きの単位ベクトル
        double[] prevDir = new double[2];
        prevDir[0] = 0.0;
        prevDir[1] = 1.0;

        while (true) {
            int from = list.get(list.size() - 1);
            double max = -2;
            int next = -1;

            for (int to = 0; to < N; to++) {
                // 前のベクトルに対して最も内積が大きくなるように次の点を探す
                // そうすると、曲がり角を最大にすることが出来る
                double[] toDir = direction(x, y, from, to);
                double pro = product(prevDir, toDir);
                if (max < pro) {
                    max = pro;
                    next = to;
                }
            }

            prevDir = direction(x, y, from, next);
            list.add(next);
            if (used[next]) {
                break;
            }
            used[next] = true;
        }

        int last = list.get(list.size() - 1);
        while (list.get(0) != last) {
            list.remove(0);
        }

        double ans = 0;
        for (int i = 1; i < list.size(); i++) {
            int a = list.get(i - 1);
            int b = list.get(i);

            ans += Math.sqrt(Math.pow(x[a] - x[b], 2) + Math.pow(y[a] - y[b], 2));
        }
        return ans;
    }

    static double[] direction(int[] X, int[] Y, int from, int to) {
        // fromからtoへの単位ベクトルを返す
        double dx = X[to] - X[from];
        double dy = Y[to] - Y[from];
        return new double[]{dx / Math.sqrt(dx * dx + dy * dy), dy / Math.sqrt(dx * dx + dy * dy)};
    }

    static double product(double[] a, double[] b) {
        // ベクトル内積を返す
        return a[0] * b[0] + a[1] * b[1];
    }

    //角abc

    // 点Pと線(AB)の距離
    static double distanceDotAndLine(PD p, PD A, PD B) {
        Vec AB = new Vec(B.x - A.x, B.y - A.y);
        Vec AP = new Vec(p.x - A.x, p.y - A.y);

        // ベクトルAB、APの外積の絶対値が平行四辺形Dの面積になる
        double D = Math.abs(crossVector(AB, AP));

        double L = distance(A, B); // AB間の距離

        double H = D / L;
        return H;
    }

    static double area(double x1, double y1, double x2, double y2, double x3, double y3) {
        return abs((x2 - x1) * (y3 - y1) - (y2 - y1) * (x3 - x1)) / 2.0;
    }

    static double area(double a, double b, double c) {
        double s = (a + b + c) / 2;
        return Math.sqrt(s * (s - a) * (s - b) * (s - c));
    }

    // 点間距離
    static double distance(PD a, PD b) {
        double dx = a.x - b.x;
        double dy = a.y - b.y;
        return Math.sqrt(dx * dx + dy * dy);
    }

    // 点間距離
    static double len(Vec a) {
        double dx = a.x;
        double dy = a.y;
        return Math.sqrt(dx * dx + dy * dy);
    }

    //ベクトル内積
    static double product(Vec a, Vec b) {
