	public static void main(String[] args) {
		sc = new Scanner(System.in);
		pr = new Printer(System.out);

		solve();

		pr.close();
		sc.close();
	}

	@SuppressWarnings("unused")
	private static class Scanner {
		BufferedReader br;

		Scanner (InputStream in) {
			br = new BufferedReader(new InputStreamReader(in));
		}

		private boolean isPrintable(int ch) {
			return ch >= '!' && ch <= '~';
		}

		private boolean isCRLF(int ch) {
			return ch == '\n' || ch == '\r' || ch == -1;
		}

		private int nextPrintable() {
			try {
				int ch;
				while (!isPrintable(ch = br.read())) {
					if (ch == -1) {
						throw new NoSuchElementException();
					}
				}

				return ch;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		String next() {
			try {
				int ch = nextPrintable();
				StringBuilder sb = new StringBuilder();
				do {
					sb.appendCodePoint(ch);
				} while (isPrintable(ch = br.read()));

				return sb.toString();
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		int nextInt() {
			try {
				// parseInt from Integer.parseInt()
				boolean negative = false;
				int res = 0;
				int limit = -Integer.MAX_VALUE;
				int radix = 10;

				int fc = nextPrintable();
				if (fc < '0') {
					if (fc == '-') {
						negative = true;
						limit = Integer.MIN_VALUE;
					} else if (fc != '+') {
						throw new NumberFormatException();
					}
					fc = br.read();
				}
				int multmin = limit / radix;

				int ch = fc;
				do {
					int digit = ch - '0';
					if (digit < 0 || digit >= radix) {
						throw new NumberFormatException();
					}
					if (res < multmin) {
						throw new NumberFormatException();
					}
					res *= radix;
					if (res < limit + digit) {
						throw new NumberFormatException();
					}
					res -= digit;

				} while (isPrintable(ch = br.read()));

				return negative ? res : -res;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		long nextLong() {
			try {
				// parseLong from Long.parseLong()
				boolean negative = false;
				long res = 0;
				long limit = -Long.MAX_VALUE;
				int radix = 10;

				int fc = nextPrintable();
				if (fc < '0') {
					if (fc == '-') {
						negative = true;
						limit = Long.MIN_VALUE;
					} else if (fc != '+') {
						throw new NumberFormatException();
					}
					fc = br.read();
				}
				long multmin = limit / radix;

				int ch = fc;
				do {
					int digit = ch - '0';
					if (digit < 0 || digit >= radix) {
						throw new NumberFormatException();
					}
					if (res < multmin) {
						throw new NumberFormatException();
					}
					res *= radix;
					if (res < limit + digit) {
						throw new NumberFormatException();
					}
					res -= digit;

				} while (isPrintable(ch = br.read()));

				return negative ? res : -res;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		float nextFloat() {
			return Float.parseFloat(next());
		}

		double nextDouble() {
			return Double.parseDouble(next());
		}

		String nextLine() {
			try {
				int ch;
				while (isCRLF(ch = br.read())) {
					if (ch == -1) {
						throw new NoSuchElementException();
					}
				}
				StringBuilder sb = new StringBuilder();
				do {
					sb.appendCodePoint(ch);
				} while (!isCRLF(ch = br.read()));

				return sb.toString();
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		void close() {
			try {
				br.close();
			} catch (IOException e) {
//				throw new NoSuchElementException();
			}
		}
	}

	private static class Printer extends PrintWriter {
		Printer(PrintStream out) {
			super(out);
		}
	}
}

import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.NoSuchElementException;

public class Main {
	private static FastScanner sc = new FastScanner();

	public static void main(String[] args) {
		int N = sc.nextInt();
		double[] x = new double[N];
		double[] y = new double[N];
		double minx = 10000000;
		int minpos = -1;
		for(int i=0; i<N; i++) {
			x[i] = sc.nextDouble();
			y[i] = sc.nextDouble();
			if(x[i] < minx) {
				minx = x[i];
				minpos = i;
			}
		}
		ArrayList<Integer> L = new ArrayList<>();
		int a = minpos;
		do {
			L.add(a);
			int b = 0;
			for(int i=1; i<N; i++) {
				int c = i;
				if(b == a) {
					b = c;
				} else {
					double v = (x[b] - x[a])*(y[c] - y[a]) - (x[c] - x[a])*(y[b] - y[a]);
					if(v > 0 || (v == 0 && (x[c] - x[a])*(x[c] - x[a]) + (y[c] - y[a])*(y[c] - y[a]) > (x[b] - x[a])*(x[b] - x[a]) + (y[b] - y[a])*(y[b] - y[a]))) {
						b = c;
					}
				}
			}
			a = b;
		} while(a != minpos);

		double[] p = new double[N];

		for(int i=0; i<L.size(); i++) {
			double ax = (x[L.get(i)] + x[L.get((i+1)%L.size())]) / 2;
			double ay = (y[L.get(i)] + y[L.get((i+1)%L.size())]) / 2;
			double bx = (x[L.get(i)] + x[L.get((i-1+L.size())%L.size())]) / 2;
			double by = (y[L.get(i)] + y[L.get((i-1+L.size())%L.size())]) / 2;
			double cos = ((ax - x[L.get(i)])*(bx - x[L.get(i)]) + (ay - y[L.get(i)])*(by - y[L.get(i)])) 
					/ Math.sqrt((ax - x[L.get(i)])*(ax - x[L.get(i)])+(ay - y[L.get(i)])*(ay - y[L.get(i)])) 
					/ Math.sqrt((bx - x[L.get(i)])*(bx - x[L.get(i)])+(by - y[L.get(i)])*(by - y[L.get(i)]));
			if(cos > 1) cos = 1;
			if(cos < 0) cos = 0;
			p[L.get(i)] = (1 - Math.acos(cos) / Math.PI)/2;
		}

		for(int i=0; i<N; i++) {
			System.out.println(p[i]);
		}
	}

	static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;
        private boolean hasNextByte() {
            if(ptr < buflen) {
                return true;
            } else {
                ptr = 0;
                try {
                    buflen = in.read(buffer);
                } catch(IOException e) {
                    e.printStackTrace();
                }
                if(buflen <= 0) {
                    return false;
                }
            }
            return true;
        }
        private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
        private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
        private void skipUnprintable() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;}
        public boolean hasNext() { skipUnprintable(); return hasNextByte();}
        public String next() {
            if (!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while(isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }
        public long nextLong() {
            return Long.parseLong(next());
        }
        public int nextInt(){
            return Integer.parseInt(next());
        }
        public double nextDouble(){
            return Double.parseDouble(next());
        }
    }
}

import java.util.Scanner;
import java.util.Comparator;
import java.util.Arrays;
import java.util.List;
import java.util.ArrayList;

class Main{
    public static void main(String[] args){
        Scanner scan = new Scanner(System.in);
        int N = scan.nextInt();

        int[] x = new int[N];
        int[] y = new int[N];
        for(int i=0;i<N;++i){
            x[i]=scan.nextInt();
            y[i]=scan.nextInt();
        }

        for(int i=0;i<N;++i){
            List<Double> thetas = new ArrayList<>();
            for(int j=0;j<N;++j){
                if(i==j)continue;
                thetas.add(Math.atan2(y[j]-y[i], x[j]-x[i]));
            }
            thetas.sort(Comparator.naturalOrder());
            thetas.add(thetas.get(0)+2*Math.PI);
            double ans = 0;
            for(int k=0;k<N-1;++k)ans = Math.max(ans, thetas.get(k+1)-thetas.get(k)-Math.PI);

            System.out.println(ans/(Math.PI*2));
        }
    }
}

