import java.io.BufferedReader;
import java.util.Comparator;
import java.util.LinkedList;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        MyScan in = new MyScan(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        public void solve(int testNumber, MyScan in, PrintWriter out) {
            int n = in.nextInt();
            int[][] pp = new int[n][3];
            for (int s = 0; s < n; s++) {
                pp[s][0] = in.nextInt();
                pp[s][1] = in.nextInt();
                pp[s][2] = s;
            }
            ConvexHull convexHull = new ConvexHull();
            pp = convexHull.calculate(pp);
            double[] res = new double[n];
            for (int i = 0; i < pp.length; i++) {
                int li = (i - 1 + pp.length) % pp.length;
                int ri = (i + 1 + pp.length) % pp.length;

                int[] v11 = ConvexHull.v1(pp[i], pp[li]);
                int[] v12 = ConvexHull.v1(pp[i], pp[ri]);

                res[pp[i][2]] = (Math.PI - ConvexHull.angle(v11, v12)) / 2 / Math.PI;

            }


            for (int i = 0; i < n; i++) {
                out.println(res[i]);
            }
        }

    }

    static class ConvexHull {
        public int[][] calculate(int[][] points) {
            int n = points.length;
            int[] right = Arrays.stream(points).min(Comparator.<int[]>comparingInt(t -> -t[0]).thenComparing(t -> t[1])).get();
            long[] dist = new long[n];
            for (int i = 0; i < n; i++) {
                dist[i] = (long) (points[i][0] - right[0]) * (points[i][0] - right[0])
                        + (long) (points[i][1] - right[1]) * (points[i][1] - right[1]);
            }
            Arrays.sort(points, (s1, s2) -> {
                if (s1 == right) return -1;
                if (s2 == right) return 1;
                int ccw = ccw(s1, s2, right);
                if (ccw != 0) return ccw;
                return Long.compare(dist[s1[2]], dist[s2[2]]);
            });
            LinkedList<int[]> hull = new LinkedList<>();
            hull.add(points[0]);
            hull.add(points[1]);
            for (int s = 2; s < n; s++) {
                while (hull.size() > 1) {
                    int[] p2 = hull.pollLast();
                    int[] p1 = hull.getLast();
                    if (ccw(p2, points[s], p1) <= 0) {
                        hull.add(p2);
                        break;
                    }
                }
                hull.add(points[s]);
            }
            return hull.toArray(new int[0][]);
        }

        public static int[] v1(int[] i1, int[] i2) {
            return new int[]{i1[0] - i2[0], i1[1] - i2[1]};
        }

        private static int ccw(int[] s1, int[] s2, int[] right) {
            long xa = s1[0] - right[0];
            long xb = s1[1] - right[1];
            long ya = s2[0] - right[0];
            long yb = s2[1] - right[1];
            return Long.compare(xb * ya, xa * yb);
        }

        public static long dot(long[] v11, long[] v12) {
            return (long) v11[0] * v12[0] + (long) v11[1] * v12[1];
        }

        public static double f(long[] x) {
            return Math.sqrt(x[0] * x[0] + x[1] * x[1]);
        }

        public static double angle(int[] v1, int[] v2) {
            long[] v11 = new long[v1.length];
            long[] v12 = new long[v2.length];
            for (int s = 0; s < v1.length; s++) {
                v11[s] = v1[s];
            }
            for (int s = 0; s < v12.length; s++) {
                v12[s] = v2[s];
            }

            return Math.acos(dot(v11, v12) / f(v11) / f(v12));
        }

    }

    static class MyScan {
        BufferedReader br;
        StringTokenizer st;

        MyScan(BufferedReader br) {
            this.br = br;
        }

        public MyScan(InputStream in) {
            this(new BufferedReader(new InputStreamReader(in)));
        }

        public void findToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
        }

        public String next() {
            findToken();
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.Comparator;
import java.util.InputMismatchException;

public class Main {
	static InputStream is;
	static PrintWriter out;
	static String INPUT = "";

	static void solve()
	{
		int n = ni();
		int[][] co = new int[n][];
		for(int i = 0;i < n;i++){
			co[i] = new int[]{ni(), ni()};
		}
		boolean[] dead = new boolean[n];
		outer:
		for(int i = 0;i < n;i++){
			for(int j = 0;j < n;j++){
				for(int k = j+1;k < n;k++){
					if(j == i || k == i)continue;
					if(isACB(co[j][0], co[j][1], 
							co[k][0], co[k][1],
							co[i][0], co[i][1])){
						dead[i] = true;
						continue outer;
					}

					for(int l = k+1;l < n;l++){
						if(j == i || k == i || l == i)continue;
						if(onSameLine(co[j], co[k], co[l]))continue;
						int c1 = ccw(co[j], co[k], co[i]);
						int c2 = ccw(co[k], co[l], co[i]);
						int c3 = ccw(co[l], co[j], co[i]);
						if(c1+c2+c3 == 3 || c1+c2+c3 == -3){
							dead[i] = true;
							continue outer;
						}
					}
				}
			}
		}

		int alive = 0;
		for(int i = 0;i < n;i++){
			if(!dead[i])alive++;
		}
		if(alive == 2){
			for(int i = 0;i < n;i++){
				if(dead[i]){
					out.println(0);
				}else{
					out.println(0.5);
				}
			}
			return;
		}

		outer:
		for(int i = 0;i < n;i++){
			if(dead[i]){
				out.println(0);
				continue;
			}

			double[][] theta = new double[n-1][];
			int p = 0;
			for(int j = 0;j < n;j++){
				if(j == i)continue;
				theta[p++] = new double[]{Math.atan2(
						co[j][1]-co[i][1], 
						co[j][0]-co[i][0]
								), j};
			}
			Arrays.sort(theta, new Comparator<double[]>() {
				public int compare(double[] a, double[] b) {
					return Double.compare(a[0], b[0]);
				}
			});
			for(int j = 0;j < n-1;j++){
				int cur = (int)theta[j][1];
				int nex = (int)theta[(j+1)%(n-1)][1];
				if(inArg(
						co[cur][0]-co[i][0],
						co[cur][1]-co[i][1],
						-(co[cur][0]-co[i][0]),
						-(co[cur][1]-co[i][1]),
						co[nex][0]-co[i][0],
						co[nex][1]-co[i][1]) < 0){
//					tr(cur, i, nex);
					double val = Math.atan2(
							co[nex][1]-co[i][1], 
							co[nex][0]-co[i][0]
									) - Math.atan2(
											co[cur][1]-co[i][1], 
											co[cur][0]-co[i][0]
													) - Math.PI;
					if(val < -1e-5)val += 2*Math.PI;
					out.printf("%.14f\n", val/(2*Math.PI));
					continue outer;
				}
			}
		}
	}
	public static boolean onSameLine(int[] a, int[] b, int[] c)
	{
		return (long)(c[0]-a[0])*(b[1]-a[1])-(long)(c[1]-a[1])*(b[0]-a[0])==0;
	}


	public static boolean isACB(long ax, long ay, long bx, long by, long cx, long cy)
	{
