class Solve{
    public Solve(){}
    StringBuilder sb;
    ReadData re;
    public static int Main(){
        new Solve().Run();
        return 0;
    }
    void Run(){
        sb = new StringBuilder();
        re = new ReadData();
        Calc();
        Console.Write(sb.ToString());
    }
    void Calc(){
        int N = re.i();
        double[] X = new double[N];
        double[] Y = new double[N];
        for(int i=0;i<N;i++){
            X[i] = re.i();
            Y[i] = re.i();
        }
        for(int i=0;i<N;i++){
            double s1 = 0;
            double e1 = Math.PI;
            double s2 = 0;
            double e2 = Math.PI;
            for(int j=0;j<N;j++){
                if(i != j){
                    if(Y[i] == Y[j]){
                        if(X[i] > X[j]){
                            e1 = Math.Min(Math.PI/2,e1);
                            s2 = Math.Max(Math.PI/2,s2);
                        }
                        else{
                            e2 = Math.Min(Math.PI/2,e2);
                            s1 = Math.Max(Math.PI/2,s1);
                        }
                    }
                    else if(Y[i] > Y[j]){
                        double theta = Math.Atan((X[j]-X[i])/(Y[i]-Y[j]));
                        if(theta >= 0){
                            s1 = Math.Max(theta,s1);
                            e2 = Math.Min(theta,e2);
                        }
                        else{
                            theta = -theta;
                            e1 = Math.Min(Math.PI-theta,e1);
                            s2 = Math.Max(Math.PI-theta,s2);
                        }
                    }
                    else{
                        double theta = Math.Atan((X[j]-X[i])/(Y[i]-Y[j]));
                        if(theta >= 0){
                            e1 = Math.Min(theta,e1);
                            s2 = Math.Max(theta,s2);
                        }
                        else{
                            theta = -theta;
                            s1 = Math.Max(Math.PI-theta,s1);
                            e2 = Math.Min(Math.PI-theta,e2);
                        }
                    }
                }
            }
            double count = Math.Max(e1-s1,0) + Math.Max(e2-s2,0);
            count /= Math.PI*2;
            sb.Append(count+"\n");
        }
    }
}
