		for(int i = 0;i<n;i++) {
			if(i!=p){arr[i]=new Mo(Math.Atan2(a[i][1]-a[0][1],a[i][0]-a[0][0])*180/Math.PI,i,a[i][0],a[i][1]);}
		}
