                Vector v = plot[i] - plot[j];
                //初期化
                if (!initialized)
                {
                    basev = v;
                    initialized = true;
                }

                //ベースとの角度
                double vrad = Vector.GetRadian(basev, v);

                //ベクトルがベースの右側だったら(外積がマイナス)
                if (Vector.CrossProduct(basev, v) < 0)
                {
                    //今のtopとなす角を比較、大きかったら代入
                    rrad = Max(rrad, vrad);
                }
                //左だったら
                else if (Vector.CrossProduct(basev, v) > 0)
                {
                    //今のtopとなす角を比較
                    lrad = Max(lrad, vrad);
                }
                else
                {
                    //内積が0の場合は同方向と逆方向の二種類考えられる。
