import (
  "fmt"
  "math"
  "sort"
)

func main() {
  var n int
  fmt.Scan(&n)
  p := Points{}
  for i:=0;i<n;i++ {
    var x,y float64
    fmt.Scan(&x,&y)
    p = append(p,Point{x,y,i})
  }
  h := p.GetHull()
  var f []float64 = make([]float64,n)
  var m int = h.Len()
  if m == 1 {
    for i:=0;i<n;i++ {
      p[i].x,p[i].y = -p[i].y,p[i].x
    }
    h = p.GetHull()
    m = h.Len()
  }
  f[h[0].id] = (math.Pi-h[0].angle(h[1],h[m-1]))/(2*math.Pi)
  f[h[m-1].id] = (math.Pi-h[m-1].angle(h[0],h[m-2]))/(2*math.Pi)
  for i:=1;i<m-1;i++ {
    f[h[i].id] = (math.Pi-h[i].angle(h[i+1],h[i-1]))/(2*math.Pi)
  }
  for i:=0;i<n;i++ { fmt.Printf("%.10f\n",f[i]) }
}

type Point struct {
  x,y float64
  id int
}
func(p Point) equals(t Point) bool { return p.x == t.x && p.y == t.y }
func(p Point) angle(sta Point,end Point) float64 {
  ax := sta.x - p.x
  bx := end.x - p.x
  ay := sta.y - p.y
  by := end.y - p.y
  return math.Atan2(ax*by-ay*bx,ax*bx+ay*by)
}
func(p Point) distance(t Point) float64 {
  dx := p.x - t.x
  dy := p.y - t.y
  return math.Sqrt(dx*dx+dy*dy)
}
type Points []Point
func(ps Points) Len() int { return len(ps) }
func(ps Points) Swap(i,j int) { ps[i],ps[j] = ps[j],ps[i] }
func(ps Points) Less(i,j int) bool {
  if ps[i].x == ps[j].x {
    if ps[i].y == ps[j].y { return ps[i].id < ps[j].id }
    return ps[i].y < ps[j].y
  }
  return ps[i].x < ps[j].x
}
func(ps Points) GetHull() Points {
  sort.Sort(sort.Reverse(ps))
  now := ps[0]
  prv := Point{now.x,now.y-1,-1}
  hull := Points{now}
  for {
    var minagl,maxdst float64
    minagl = 2*math.Pi
    maxdst = 0
    nxt := ps[0]
    for _,p := range ps {
      if p.equals(now) { continue }
      var angle,dstnc float64
      angle = now.angle(prv,p)
      dstnc = now.distance(p)
      if angle < 0 { angle += 2*math.Pi }
      if angle < minagl && angle >= math.Pi {
        minagl = angle
        nxt = p
        maxdst = dstnc
      } else if angle == minagl && dstnc > maxdst {
        nxt = p
        maxdst = dstnc
      }
    }
    if nxt.equals(hull[0]) { break }
    hull = append(hull,nxt)
    prv = now
    now = nxt
  }
  return hull
}

