    _B := []float64{A[C[i]][0] - x, A[C[i]][1] - y}
    theta := Angle(&_A, &_B)
    R[C[i + 1]] = theta / 2.0
  }
  for _, r := range R {
    Write(r / 360.0)
  }
  return
}

func main() {
  Solve()
  Output()
}

