func main() {
	var n int
	var pi = math.Acos(-1.0)
	var res float64
	fmt.Scanf("%d", &n)

	x := make([]float64, n)
	y := make([]float64, n)

	for i := 0; i < n; i++ {
		fmt.Scanf("%f %f", &x[i], &y[i])
	}

	for i := 0; i < n; i++ {
		res = 0.0
		var angles []float64
		for j := 0; j < n; j++ {
			if i != j {
				angles = append(angles, math.Atan2(y[j]-y[i], x[j]-x[i]))
			}
		}

		sort.Float64s(angles)
		var max float64
		for j := 0; j < len(angles)-1; j++ {
			max = math.Max(max, angles[j+1]-angles[j])
		}
		max = math.Max(max, angles[0]-angles[len(angles)-1]+2*pi)

		if max > pi {
			res = (max - pi) / (2 * pi)
		}
		fmt.Printf("%f\n", res)
	}

	return
}

