void main(){
  import std.stdio, std.string, std.conv, std.algorithm;
  import std.math;

  int n; rd(n);
  auto xs=new int[](n), ys=new int[](n);
  foreach(i; 0..n) rd(xs[i], ys[i]);

  foreach(i; 0..n){
    double[] theta;
    foreach(j; 0..n){
      if(i==j) continue;
      double dx=xs[j]-xs[i], dy=ys[j]-ys[i];
      theta~=atan2(dy, dx);
    }
    sort(theta);
    auto mxth=(theta[0]+PI*2)-theta[$-1];
    foreach(j; 1..(theta.length)) mxth=max(mxth, theta[j]-theta[j-1]);
    writefln("%.15f", max(0.0, mxth-PI)/(PI*2));
  }
}

void rd(T...)(ref T x){
  import std.stdio, std.string, std.conv;
  auto l=readln.split;
  assert(l.length==x.length);
  foreach(i, ref e; x){
    e=l[i].to!(typeof(e));
  }
}

