void solve(){
    int n = scan!int;
    Vector[] ps;
    foreach(_; 0 .. n) ps ~= Vector(scan!long, scan!long);

    Edge[] edges;
    foreach(i1, p1; ps) foreach(i2, p2; ps){
        if(p1 == p2) continue;
        Edge ed = Edge(i1.to!int, i2.to!int, p2 - p1);
        bool f = 1;
        foreach(p3; ps){
            if(p3 == p1 || p3 == p2) continue;
            Vector v = p3 - p1;
            if(v.isLeftTo(ed.v) || v.arg == ed.v.arg && v.square < ed.v.square) continue;
            f = 0;
            break;
        }
        if(f) edges ~= ed;
    }

    edges.sort!"a.v.arg.follows(b.v.arg)"();
    if(DEBUG) foreach(edge; edges) edge.writeln;

    edges ~= edges[0];
    real[] ans = new real[](n);
    foreach(i; 0 .. n) ans[i] = 0.0;
    foreach(i; 0 .. edges.length - 1){
        Edge ed1 = edges[i], ed2 = edges[i + 1];
        int id = ed1.id2;
        Argument arg = ed2.v.arg - ed1.v.arg;
        real angle = arg.angle;
        ans[id] = (angle / PI / 2.0);
    }

    foreach(an; ans) writefln("%3.10f", an);

    if(DEBUG){
        log(Argument(1, 0).angle, 0);
        log((Argument(1, 1) - Argument(17320508, 10000000)).angle, PI / 12);
        log(Argument(17320508, 10000000).angle, PI / 6);
        log(Argument(1, 1).angle, PI / 4);
        log(Argument(0, 1).angle, PI / 2);
        log(Argument(-1, 1).angle, PI * 3 / 4);
        log(Argument(-17320508, 10000000).angle, PI * 5 / 6);
        log(Argument(-1, 0).angle, PI);
        log(Argument(-17320508, -10000000).angle, PI * 7 / 6);
        log(Argument(0, -1).angle, PI * 3 / 2);
        log(Argument(17320508, -10000000).angle, PI * 11 / 6);
    }
}

