  var ans = newSeq[float](n)

  for i in 0..<n:
    var th = newSeq[float](0)
    for j in 0..<n:
      if i == j:
        continue
      th.add((ps[j] - ps[i]).arg())

    th.sort(cmp[float])
    th.add(th[0] + 2 * PI)

    debug th
    var maxTh = 0.0
    for i in 0..<th.len() - 1:
      maxTh = max(maxTh, th[i + 1] - th[i])

    if maxTh <= PI:
      ans[i] = 0.0
      continue

    ans[i] = (maxTh - PI) / (2 * PI)

  for i in 0..<n:
    echo ans[i]


