type Pos = tuple [ x, y: int ]

proc `<`(p1, p2: Pos): bool =
  if p1.x == p2.x:
    return p1.y < p2.y
  return p1.x < p2.x

proc `-`(p1, p2: Pos): Pos = (p1.x - p2.x, p1.y - p2.y)

proc det(p1, p2: Pos): int = p1.x * p2.y - p1.y * p2.x

proc convexHull(ps: seq[Pos]): seq[Pos] =
  let n = ps.len()
  let ps = ps.sorted(cmp[Pos])

  var qs = newSeq[Pos](0)

  for i in 0..<n:
    while qs.len() > 1 and (qs[qs.len() - 1] - qs[qs.len() - 2]).det(ps[i] - ps[qs.len() - 1]) <= 0:
      discard qs.pop()
    qs.add(ps[i])

  let t = qs.len()
  for i in countdown(n - 2, 0):
    while qs.len() > t and (qs[qs.len() - 1] - qs[qs.len() - 2]).det(ps[i] - qs[qs.len() - 1]) <= 0:
      discard qs.pop()
    qs.add(ps[i])

  return qs[0..<qs.len() - 1]

proc norm(p: Pos): float = sqrt((p.x.float() * p.x.float()) + (p.y.float() * p.y.float()))

proc dot(p1, p2: Pos): int = p1.y * p2.y + p1.x * p2.x

proc main() =
  let n = readInt1()

  var ps = newSeq[Pos](n)
  for i in 0..<n:
    let (x, y) = readInt2()
    ps[i] = (x, y)

  var ans = initTable[Pos, float]()
  for i in 0..<n:
    ans[ps[i]] = 0.0

  let qs = convexHull(ps)
  let m = qs.len()

  for i in 0..<m:
    let p0 = qs[(i - 1 + m) mod m]
    let p1 = qs[i]
    let p2 = qs[(i + 1 + m) mod m]

    let v0 = p1 - p0
    let v1 = p2 - p1

    let u0 = (v0.y, -v0.x)
    let u1 = (v1.y, -v1.x)

    let th = arccos(dot(u0, u1).float() / u0.norm() / u1.norm())
    ans[qs[i]] = th / (2 * PI)

  for i in 0..<n:
    echo ans[ps[i]]

