import math


def angle(p1, p2):
    x1, y1 = p1
    x2, y2 = p2
    return math.atan2(y2-y1, x2-x1)


def find_convex_hull(points):
    if len(points) < 2:
        return points
    P = sorted(points)
    upper = [P[0], P[1]]
    for p in P[2:]:
        if angle(upper[-2], upper[-1]) <= angle(upper[-1], p):
            upper.pop()
        upper.append(p)
    lower = [P[-1], P[-2]]
    for p in reversed(P[:-2]):
        if angle(lower[-2], lower[-1]) >= angle(lower[-1], p):
            lower.pop()
        lower.append(p)
    if upper[-1] == lower[0]:
        upper = upper[:-1]
    if upper[0] == lower[-1]:
        lower = lower[:-1]
    ans = upper + lower
    return ans


