def solve(rng_lst, N):
    pos_lst = [] # (pos, opp, isStart)
    for rng in rng_lst:
        pos_lst.append((rng[0], rng[2], True))
        pos_lst.append((rng[1], rng[2], False))
    pos_lst = sorted(pos_lst, key=lambda x: x[0])

    ans = 0
    opp_lst = []
    prv = 0
    for pos in pos_lst:
        if pos[2]: # if start
            opp_lst.append(pos[1])
        else: # if end
            if len(opp_lst) == N - 1:
                ans += (pos[0] - prv)
            opp_lst.remove(pos[1])
        prv = pos[0]
    return ans/(2*pi)

