def convex_hull(inlist):
    inlist = sorted(inlist)
    x_min, x_max = inlist[0], inlist[-1]

    def cross_product(p1,p2,p3):
        return (p2[0]-p1[0])*(p3[1]-p1[1])-(p2[1]-p1[1])*(p3[0]-p1[0])

    upper_list = [x_min]
    downer_list = [x_min]
    for i in inlist:
        if cross_product(x_min,i,x_max) < 0:
            upper_list.append(i)
        elif cross_product(x_min,i,x_max) > 0:
            downer_list.append(i)
    upper_list.append(x_max)
    downer_list.append(x_max)

    upper_convex_hull = upper_list[:2]
    if len(upper_list) > 2:
        for i in range(len(upper_list)-2):
            upper_convex_hull.append(upper_list[i+2])
            if cross_product(upper_convex_hull[-3],upper_convex_hull[-2],upper_convex_hull[-1]) >= 0:
                del upper_convex_hull[-2]

    downer_convex_hull = downer_list[:2]
    if len(downer_list) > 2:
        for i in range(len(downer_list)-2):
            downer_convex_hull.append(downer_list[i+2])
            if cross_product(downer_convex_hull[-3],downer_convex_hull[-2],downer_convex_hull[-1]) <= 0:
                del downer_convex_hull[-2]


    outlist = upper_convex_hull + list(reversed(downer_convex_hull[1:-1]))
    return outlist

