import math


class ConvexHull:
    """凸包に関する各種性質を求める"""
    def __init__(self, ps):
        self.n = len(ps)
        self.ps = sorted(ps)
        self.qs = []

        # 下側凸包の構築
        for p in self.ps:
            while len(self.qs) > 1 and self._ccw(self.qs[-2], self.qs[-1], p) < 0:
               self.qs.pop()
            self.qs.append(p)
        t = len(self.qs)

        # 上側凸包の構築
        for i in range(self.n - 2, -1, -1):
            p = self.ps[i]
            while len(self.qs) > 1 and self._ccw(self.qs[-2], self.qs[-1], p) < 0:
               self.qs.pop()
            self.qs.append(p)

    def _ccw(self, p1, p2, p3):
        """p1 -> p2 -> p3と頂点を移動したときの回転方向を返す。
        反時計回り -> +1、時計回り -> -1、0°もしくは180°回る -> 0
        """
        p2 = [p2[i] - p1[i] for i in range(2)]
        p3 = [p3[i] - p1[i] for i in range(2)]
        if p2[0] * p3[1] == p2[1] * p3[0]:
            return 0
        if p2[0] * p3[1] - p2[1] * p3[0] > 0:
            return +1
        else:
            return -1

    def get_ps(self):
        """凸包の頂点組を反時計回り順で求める（GrahamScan）。"""
        return self.qs


def get_theta(o, a, b):
    a = [a[i] - o[i] for i in range(2)]
    b = [b[i] - o[i] for i in range(2)]
    len_a = (a[0] ** 2 + a[1] ** 2) ** 0.5
    len_b = (b[0] ** 2 + b[1] ** 2) ** 0.5
    ab = a[0] * b[0] + a[1] * b[1]
    return 180 - math.degrees(math.acos(ab / len_a / len_b))


