        a1 = angle(ch[i], ch[(i-1) % M]) - math.pi / 2
        a2 = angle(ch[i], ch[(i+1) % M]) + math.pi / 2
        ratio = ((a1-a2) / (math.pi*2)) % 1.0
        ans[ch[i]] = ratio
    for p in P:
        print(ans[p])


