fn main() {
    let n = get!(usize);
    let xy = get!(f64, f64; n);

    let vs: Vec<Vector2D> = xy.into_iter().map(|(x, y)| Vector2D(x, y)).collect();

    let mut ans = vec![0.0; n];

    let ch = convex_hull(&vs);

    for i in 0..ch.len() {
        let p = vs[ch[i]];
        let p1 = vs[ch[(i + 1) % ch.len()]];
        let p2 = vs[ch[(i + ch.len() - 1) % ch.len()]];

        let v1 = p1 - p;
        let v2 = p2 - p;
        let v1 = Vector2D(v1.1, -v1.0).unit();
        let v2 = Vector2D(v2.1, -v2.0).unit();

        let dot = v1.dot(v2);
        let cos = dot / (v1.len() * v2.len());
        ans[ch[i]] = (std::f64::consts::PI - f64::acos(cos)) / (2.0 * std::f64::consts::PI);
    }

    util::with_bufwriter(|mut out| {
        for x in ans {
            writeln!(out, "{}", x).unwrap();
        }
    });
}

macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String {
            bytes
                .by_ref()
                .map(|r| r.unwrap() as char)
                .skip_while(|c| c.is_whitespace())
                .take_while(|c| !c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };

    ($next:expr, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, [ $t:tt ]) => {
        {
            let len = read_value!($next, usize);
            (0..len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
        }
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

