#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum CCW {
    /// a--b--c
    OnlineFront = -2,
    /// a--b-vc
    Clockwise = -1,
    /// a--c--b
    OnSegment = 0,
    /// a--b-^c
    CounterClockwise = 1,
    /// c--a--b
    OnlineBack = 2,
}
pub fn ccw(a: Point, b: Point, c: Point) -> CCW {
    let x = b - a;
    let y = c - a;
    if Real(x.cross(y)) > Real(0.) {
        CCW::CounterClockwise
    } else if Real(x.cross(y)) < Real(0.) {
        CCW::Clockwise
    } else if Real(x.dot(y)) < Real(0.) {
        CCW::OnlineBack
    } else if Real(x.abs()) < Real(y.abs()) {
        CCW::OnlineFront
    } else {
        CCW::OnSegment
    }
}
pub type Point = Complex<f64>;
pub fn convex_hull(ps: &[Point]) -> Vec<usize> {
    let mut idx: Vec<_> = (0..ps.len()).collect();
    idx.sort_by(|&i1, &i2| {
        (ps[i1].re, ps[i1].im)
            .partial_cmp(&(ps[i2].re, ps[i2].im))
            .unwrap()
    });
    let mut qs = Vec::new();
    for &i in idx.iter().chain(idx.iter().rev().skip(1)) {
        while {
            let k = qs.len();
            k > 1 && ccw(ps[qs[k - 2]], ps[qs[k - 1]], ps[i]) == CCW::Clockwise
        } {
            qs.pop();
        }
        qs.push(i);
    }
    qs.pop();
    qs
}
