fn find_range(i: usize, points: &Vec<(f64, f64)>) -> Option<f64> {
    let num_points = points.len();

    let mut min: f64 = 0.0;
    let mut max = 2.0 * f64::consts::PI;

    for j in 0..num_points {
        if j == i {
            continue;
        }

        let p = points[i];
        let q = points[j];

        let mid = ((p.0 + q.0) / 2.0, (p.1 + q.1) / 2.0);
        let gradient = if p.1 == q.1 {
            f64::INFINITY
        } else {
            -(p.0 - q.0) / (p.1 - q.1)
        };

        let is_upper = p.1 - mid.1 >= gradient * (p.0 - mid.0);
        let r = gradient.atan();

        let (mut r_min, mut r_max) = if is_upper {
            (r, r + f64::consts::PI)
        } else {
            (r - f64::consts::PI, r)
        };

        if r_min < 0.0 {
            r_min += 2.0 * f64::consts::PI;
            r_max += 2.0 * f64::consts::PI;
        }

        if j == 0 || (j == 1 && i == 0) {
            // first
            min = r_min;
            max = r_max;
            continue;
        }

        // find shared
        if r_min <= min {
            if r_max >= max {
                // no update
                continue;
            } else if min <= r_max {
                max = r_max;
                continue;
            } else if max < r_min + 2.0 * f64::consts::PI {
                // no shared
                return None;
            } else {
                min = r_min;
                max -= 2.0 * f64::consts::PI;
                continue;
            }
        } else if r_min <= max {
            min = r_min;
            continue;
        } else if min > r_max - 2.0 * f64::consts::PI {
            // no shared
            return None;
        } else if max >= r_max - 2.0 * f64::consts::PI {
            max = r_max - 2.0 * f64::consts::PI;
            continue;
        } else {
            // no update
            continue;
        }
    }

    Some((max - min) / (2.0 * f64::consts::PI))
}

