fn ccw(x: (i64,i64), y: (i64,i64), z: (i64,i64)) -> i64 {
    ((y.0-x.0)*(z.1-x.1) - ((y.1-x.1)*(z.0-x.0))).signum()
}

fn norm(x: (i64,i64)) -> f64 {
    ((x.0*x.0 + x.1*x.1) as f64).sqrt()
}

fn dot(x: (i64,i64), y: (i64,i64)) -> i64 {
    x.0*y.0 + x.1*y.1
}

fn arg(x: (i64,i64), y: (i64,i64)) -> f64 {
    (dot(x,y) as f64 / norm(x) / norm(y)).acos()
}

