    let mut ans = vec![0.0; n];
    for i in 1..hull.len() - 1 {
        ans[hull[i]] = std::f64::consts::PI - angle(v[hull[i - 1]], v[hull[i]], v[hull[i + 1]]);
    }
    for &a in &ans {
        println!("{}", a / (2.0 * std::f64::consts::PI));
    }
}

fn angle(p1: (f64, f64), p0: (f64, f64), p2: (f64, f64)) -> f64 {
    let a = (p1.0 - p0.0).abs().hypot((p1.1 - p0.1).abs());
    let b = (p2.0 - p0.0).abs().hypot((p2.1 - p0.1).abs());
    let c2 = (p1.0 - p2.0).powi(2) + (p1.1 - p2.1).powi(2);
    ((a.powi(2) + b.powi(2) - c2) / (2.0 * a * b)).acos()
}

fn convex_hull(v: &Vec<(f64, f64)>) -> Vec<usize> {
    let mut s = 0;
    for i in 1..v.len() {
        if v[s] > v[i] {
            s = i;
        }
    }
    let mut v2: Vec<(f64, f64, usize)> = v.iter().enumerate().map(|(i, p)| (p.0, p.1, i)).collect();
    v2.sort_by(|p, q| p.0.partial_cmp(&q.0).unwrap());
    v2.sort_by(|p, q| p.1.atan2(p.0).partial_cmp(&q.1.atan2(q.0)).unwrap());
    let mut hull = vec![s];
    let mut si = 0;
    while v2[si].2 != s {
        si += 1;
    }
    let n = v2.len();
    for idx in 1..n {
        let x = v2[(idx + si) % n].0;
        let y = v2[(idx + si) % n].1;
        let i = v2[(idx + si) % n].2;
        loop {
            if hull.len() < 2 {
                hull.push(i);
                break;
            }
            let p0 = v[hull[hull.len() - 2]];
            let p1 = v[hull[hull.len() - 1]];
            if (p1.0 - p0.0) * (y - p0.1) <= (p1.1 - p0.1) * (x - p0.0) {
                hull.pop();
            } else {
                hull.push(i);
                break;
            }
        }
    }
    let mut l = hull.len();
    while l > 3 {
        let p0 = v[hull[l - 2]];
        let p1 = v[hull[l - 1]];
        if (p1.0 - p0.0) * (v[s].1 - p0.1) <= (p1.1 - p0.1) * (v[s].0 - p0.0) {
            hull.pop();
            l -= 1;
        } else {
            break;
        }
    }
    hull
}

