/// Implement Eq and Ord for a type which has only PartialEq and PartialOrd.
/// It is useful when sorting a Vec of f64
pub struct Total<T>(pub T);
impl<T: PartialEq> Eq for Total<T> {}
impl<T: PartialOrd> Ord for Total<T> {
    fn cmp(&self, other: &Total<T>) -> Ordering {
        self.0.partial_cmp(&other.0).unwrap()
    }
}

#[allow(dead_code)]
fn main() {
    let n = get!(usize);
    let xy = get!(f64, f64; n);

    let m = 5_000_000;

    let mut counts = vec![0; n];

    for i in 0..m {
        let t = 2.0 * std::f64::consts::PI * i as f64 / m as f64;

        let sin = t.sin();
        let cos = t.cos();

        let j = (0..n)
            .max_by_key(|&j| {
                let (x1, y1) = xy[j];

                Total(cos * x1 + sin * y1)
            })
            .unwrap();

        counts[j] += 1;
    }

    util::with_bufwriter(|mut out| {
        for i in 0..n {
            writeln!(out, "{}", counts[i] as f64 / m as f64).unwrap();
        }
    });
}

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let mut points = vec![];
    for _ in 0..n {
        let x = sc.read();
        let y = sc.read();
        let p = Point { x: x, y: y };
        points.push(p);
    }
    let convex_hull = extract_convex_hull(&points, false);
    let m = convex_hull.len();

    let mut ans = vec![];
    for i in 0..m {
        let left = convex_hull[(m + i - 1) % m];
        let center = convex_hull[i];
        let right = convex_hull[(i + 1) % m];

        let ax = points[left].x - points[center].x;
        let ay = points[left].y - points[center].y;

        let bx = points[right].x - points[center].x;
        let by = points[right].y - points[center].y;

        let cos = (ax * bx + ay * by) / (ax * ax + ay * ay).sqrt() / (bx * bx + by * by).sqrt();
        let t = cos.acos();
        let pi = std::f64::consts::PI;
        ans.push((center, pi - t));
    }

    let sum = ans.iter().map(|&(_, s)| s).sum::<f64>();
    assert!((sum - std::f64::consts::PI * 2.0).abs() < 1e-5);
    let mut a = vec![0.0; n];
    for (i, s) in ans.into_iter() {
        a[i] = s / sum;
    }

    for ans in a.into_iter() {
        sc.write(format!("{}\n", ans));
    }
}

pub fn extract_convex_hull(points: &Vec<Point>, contain_on_segment: bool) -> Vec<usize> {
    let n = points.len();
    if n <= 1 {
        return vec![0];
    }

    let mut ps: Vec<usize> = (0..n).collect();
    ps.sort_by(|&a, &b| {
        if points[a].x == points[b].x {
            points[a].y.partial_cmp(&points[b].y).unwrap()
        } else {
            points[a].x.partial_cmp(&points[b].x).unwrap()
        }
    });

    let mut qs: Vec<usize> = Vec::new();
    for &i in &ps {
        while qs.len() > 1 {
            let k = qs.len();
            let det = (points[qs[k - 1]] - points[qs[k - 2]]).det(&(points[i] - points[qs[k - 1]]));
            if det < 0.0 || (det <= 0.0 && !contain_on_segment) {
                qs.pop();
            } else {
                break;
            }
        }
        qs.push(i);
    }

    let t = qs.len();
    for i in (0..(n - 1)).rev() {
        let i = ps[i];
        while qs.len() > t {
            let k = qs.len();
            let det = (points[qs[k - 1]] - points[qs[k - 2]]).det(&(points[i] - points[qs[k - 1]]));
            if det < 0.0 || (det <= 0.0 && !contain_on_segment) {
                qs.pop();
            } else {
                break;
            }
        }
        qs.push(i);
    }

    qs.pop();
    return qs;
}

