use std::f64;

type V = Vec2<f64>;

fn intersection(r1: (f64, f64), r2: (f64, f64)) -> Option<(f64, f64)> {
    let l = if r1.0 < r2.0 { r2.0 } else { r1.0 };
    let r = if r1.1 < r2.1 { r1.1 } else { r2.1 };
    (l < r).then((l, r))
}

fn angle(i: usize, ps: &[V]) -> f64 {
    let mut ranges = vec![(-f64::consts::PI, f64::consts::PI)];
    for j in 0..ps.len() {
        if i == j {
            continue;
        }
        let v = ps[j] - ps[i];
        let l = f64::atan2(v.x, v.y);
        let r = l + f64::consts::PI;
        let new = if r < f64::consts::PI {
            vec![(l, r)]
        } else {
            vec![(l, f64::consts::PI), (-f64::consts::PI, r - 2.0*f64::consts::PI)]
        };
        let mut inter = Vec::new();
        for &r1 in &ranges {
            for &r2 in &new {
                if let Some(r) = intersection(r1, r2) {
                    inter.push(r);
                }
            }
        }
        ranges = inter;
        dbg!(&ranges);
    }
    ranges.into_iter().map(|(l, r)| r - l).sum()
}

fn main() {
    read!(n = usize);
    let ps: Vec<V> = read_lines::<V>().collect();
    let angles: Vec<f64> = (0..n).map(|i| angle(i, &ps)).collect();
    let sum: f64 = angles.iter().sum();
    for a in angles {
        println!("{}", a / sum);
    }
}

