use std::io::{BufRead, Write};
use std::io;
use std::iter;

fn solve<R: BufRead, W: Write>(mut input: R, mut output: W) {
    let mut buf = String::new();
    input.read_line(&mut buf).unwrap();
    let n: usize = buf.trim_right().parse().unwrap();
    let xy: Vec<(i64, i64)> = (0..n).map(|_| {
        buf.clear();
        input.read_line(&mut buf).unwrap();
        let mut split = buf.split_whitespace();
        (split.next().unwrap().parse().unwrap(), split.next().unwrap().parse().unwrap())
    }).collect();
    for i in 0..n {
        let mut angles: Vec<f64> = (0..n).filter(|&j| j != i).map(|j| {
            let (a_x, a_y) = xy[i];
            let (b_x, b_y) = xy[j];
            ((b_y - a_y) as f64).atan2((b_x - a_x) as f64)
        }).collect();
        angles.sort_by(|a, b| a.partial_cmp(b).unwrap());
        let max_diff: f64 = angles.windows(2).map(|w| w[1] - w[0]).chain(
            iter::once(angles[0] - angles.last().unwrap() + 2. * std::f64::consts::PI)
        ).max_by(|a, b| a.partial_cmp(b).unwrap()).unwrap();
        writeln!(output, "{}", (max_diff / (2. * std::f64::consts::PI) - 0.5).max(0.)).unwrap();
    }
}

fn main() {
    let stdin = io::stdin();
    let stdout = io::stdout();
    solve(stdin.lock(), stdout.lock());
}

