#[derive(Default, Clone, Copy)]
struct Vec2<T>(T, T);

macro_rules! impl_binops_vec2 {
	($(($op:ident, $method:ident)),+) => {$(
		impl<T: Copy + std::ops::$op<Output = T>> std::ops::$op for Vec2<T> {
			type Output = Self;
			fn $method(self, rhs: Self) -> Self::Output {
				Vec2((self.0).$method(rhs.0), (self.1).$method(rhs.1))
			}
		}
	)+};
}

macro_rules! impl_vec2_signed {
	($($T:ty),+) => {$(
		impl Vec2<$T> {
			fn normal(&self) -> Vec2<$T> {
				Vec2(-self.1, self.0)
			}
			fn cross(&self, rhs: &Self) -> $T {
				self.0 * rhs.1 - self.1 * rhs.0
			}
		}
	)+};
}

macro_rules! impl_vec2_float {
	($($Ts:ty),+; $F:ty) => {$(
		impl_vec2_float![implement $Ts, $F];
	)+};
	($($Ts:ty),+) => {$(
		impl_vec2_float![implement $Ts, $Ts];
	)+};
	(implement $T:ty, $F:ty) => {
		impl Vec2<$T> {
			fn atan(&self) -> $F {
				(self.1 as $F).atan2(self.0 as $F)
			}
		}
	};
}

