fn main() {
    let n = read::<usize>();
    let mut points = Vec::new();
    for i in 0..n {
        let v = read_vec::<i64>();
        points.push(Vector2D(v[0] as f64, v[1] as f64));
    }

    let hull = convex_hull(&points);
    if hull.len() == 2 {
        for i in 0..n {
            if let Some(_) = hull.iter().find(|&&x| x == i) {
                println!("0.5");
            } else {
                println!("0.0");
            }
        }
        return;
    }
    let mut rates = vec![0f64; n];
    for (i, &middle_idx) in hull.iter().enumerate() {
        let left_idx = hull[(hull.len() + i - 1) % hull.len()];
        let right_idx = hull[(i + 1) % hull.len()];
        let theta1 = (points[right_idx].1 - points[middle_idx].1)
            .atan2(points[right_idx].0 - points[middle_idx].0)
            .to_degrees();
        let theta2 = (points[left_idx].1 - points[middle_idx].1)
            .atan2(points[left_idx].0 - points[middle_idx].0)
            .to_degrees();
        let mut angle_diff = (theta2 - theta1).abs();
        if angle_diff > 180.0 {
            angle_diff = angle_diff - 180.0;
        } else {
            angle_diff = 180.0 - angle_diff;
        }
        rates[middle_idx] = angle_diff / 360.0;
    }
    for rate in rates.into_iter() {
        println!("{:?}", rate);
    }
}

