#[allow(unused_imports)]
use std::cmp::{min,max};
#[allow(unused_imports)]
use std::collections::BTreeMap;
#[allow(unused_imports)]
use std::ops::*;
#[allow(unused_imports)]
use std::collections::BinaryHeap;

fn ccw(x: (i64,i64), y: (i64,i64), z: (i64,i64)) -> i64 {
    ((y.0-x.0)*(z.1-x.1) - ((y.1-x.1)*(z.0-x.0))).signum()
}

fn norm(x: (i64,i64)) -> f64 {
    ((x.0*x.0 + x.1*x.1) as f64).sqrt()
}

fn dot(x: (i64,i64), y: (i64,i64)) -> i64 {
    x.0*y.0 + x.1*y.1
}

fn arg(x: (i64,i64), y: (i64,i64)) -> f64 {
    (dot(x,y) as f64 / norm(x) / norm(y)).acos()
}

fn convex(ps: &Vec<(i64,i64)>) -> Vec<(i64,i64)> {
    let qs = {
        let mut qs = ps.clone();
        qs.sort();
        qs
    };
    let n = qs.len();
    let mut u = vec![];
    let mut l = vec![];
    u.push(qs[0]);
    u.push(qs[1]);
    l.push(qs[n-1]);
    l.push(qs[n-2]);
    for i in 2..n {
        while u.len() >= 2 && ccw(u[u.len()-2], u[u.len()-1], qs[i]) > 0 {
            u.pop();
        }
        u.push(qs[i]);
    }
    for i in (0..n-2).rev() {
        while l.len() >= 2 && ccw(l[l.len()-2], l[l.len()-1], qs[i]) > 0 {
            l.pop();
        }
        l.push(qs[i]);
    }
    for i in 1..u.len()-1 {
        l.push(u[i]);
    }
    let mut map = BTreeMap::new();
    use std::f64;
    for j in 0..l.len() {
        let i = (j + l.len() - 1) % l.len();
        let k = (j + 1) % l.len();
        let a = (f64::consts::PI - arg((l[i].0-l[j].0, l[i].1-l[j].1), (l[k].0-l[j].0,l[k].1-l[j].1))) / f64::consts::PI / 2.0;
        map.insert(l[j], a);
    }
    l
}

fn main() {
    let n = read_i64() as usize;
    let ps = {
        let mut ps = vec![];
        for _ in 0..n {
            let xs = read_vec_i64();
            ps.push((xs[0], xs[1]));
        }
        ps
    };
    let l = convex(&ps);
    let mut map = BTreeMap::new();
    use std::f64;
    for j in 0..l.len() {
        let i = (j + l.len() - 1) % l.len();
        let k = (j + 1) % l.len();
        let a = (f64::consts::PI - arg((l[i].0-l[j].0, l[i].1-l[j].1), (l[k].0-l[j].0,l[k].1-l[j].1))) / f64::consts::PI / 2.0;
        map.insert(l[j], a);
    }
    for i in 0..n {
        match map.get(&ps[i]) {
            Some(res) => {
